"""Codec helper for the script-analysis fixtures' self-describing payloads.

The script-analysis generator hides each fixture's plan behind a declared codec, written next to the payload:
    Const Codec_<id> = "<rep>|<transform>|<key>"            (VBS; also bash `readonly`, Python `CODEC_<id> = ...`)
    rem HUNTRESS-CODEC:<rep>|<transform>                       (Batch: the parameter is part of the transform name)
and the payload as `Material_<id>` / `MATERIAL_<id>` / `rem HUNTRESS-MATERIAL:`. The rep says how the bytes are WRITTEN
(base64, hex pairs, decimal list...), the transform how they were scrambled (named for the ENCODE side, the key is hex).

This is a TOOL for the worker and its solver, not a solver: `decode()` turns (material, rep, transform, key) into the
plaintext, `find_codecs()` lists every declared codec in a source text, `plan_kv()` splits `k=v|k=v`. Anything it does
not know returns None (never raises) -- a new rep/transform is the worker's job; propose it under `## Proposed lib
additions` in NOTES.md and the post-run ratchet adds it here.

Every name is tagged with the day it was FIRST seen (`REPS` / `TRANSFORMS`), so a from-scratch replay of day N can load
only what days < N taught: `HCTF_CODEC_MAX_DAY=<N-1>` (unset = everything).
Validation: the right reading yields a plan starting `v=` (or JSON `{`); ambiguous parameters (rotation amount, rolling
xor flavour, reversal order) are tried in a small fixed order and the first valid plaintext wins.
"""
import base64
import binascii
import os
import re
import time
import unicodedata

# name -> first day seen in the GM's script-analysis evidence
REPS = {
    "base64_literal": 3, "decimal_bytes": 3, "hex_pairs": 3, "plain_fragments": 3, "reversed_text": 3,
    "split_fragments": 3,
    "base64_chunks": 4, "decimal_comma": 4, "decimal_dash": 4, "decimal_pipe": 4, "hex_colon": 4, "hex_compact": 4,
    "hex_dash": 4, "reversed_decimal": 4, "reversed_hex": 4,
    "decimal_csv": 5, "decimal_dot": 5, "hex_escape": 5, "hex_literal": 5, "integer_list": 5, "integer_tuple": 5,
    "reversed_integer_list": 5, "urlsafe_base64": 5,
    "decimal_colon": 6, "decimal_space": 6, "octal_space": 6, "percent_hex": 6,
    "json_numbers": 7, "unicode_escapes": 7, "reversed_base64": 7, "xor_hex": 7,
    "hex_base64": 8,
    # compressed / wider-alphabet reps (prebuild gzip-zlib-codec-rep, 10-16): tagged 16 so no earlier-day replay sees them
    "gzip_base64": 16, "zlib_base64": 16, "deflate_base64": 16, "gzip_hex": 16, "zlib_hex": 16, "base32": 16,
    "base85": 16, "ascii85": 16,
}
TRANSFORMS = {
    "identity": 3, "reverse": 3, "add_7": 3, "xor_5a": 3, "rotate_left": 3, "reverse_xor": 3,
    "add_modulo_256": 4, "subtract_modulo_256": 4, "repeating_key_xor": 4, "reverse_bytes": 4,
    "reverse_then_xor": 4, "rolling_xor": 4, "single_byte_xor": 4,
    # layer transforms (gzip-zlib-codec-rep): the _fallback tries them only after every earlier pair found no plan
    "rot13": 16, "atbash": 16, "rc4": 16, "gzip": 16, "zlib": 16, "deflate": 16,
}
_LAYER_TRANSFORMS = ("rot13", "atbash", "rc4", "gzip", "zlib", "deflate")
_TRANSFORM_ALIAS = {"rot_13": "rot13", "rot-13": "rot13", "caesar_13": "rot13", "arc4": "rc4", "arcfour": "rc4",
                    "rc4_key": "rc4", "gunzip": "gzip", "gzip_compress": "gzip", "zlib_compress": "zlib",
                    "inflate": "deflate", "raw_deflate": "deflate", "deflate_raw": "deflate"}


def _max_day():
    try:
        return int(os.environ.get("HCTF_CODEC_MAX_DAY", "0")) or 99
    except ValueError:
        return 99


def known(rep=None, transform=None):
    """True if every given name is in the vocabulary visible to this run."""
    md = _max_day()
    return ((rep is None or REPS.get(rep, 99) <= md) and
            (transform is None or _base_transform(transform)[0] in TRANSFORMS and
             TRANSFORMS.get(_base_transform(transform)[0], 99) <= md))


def _base_transform(t):
    """'xor_5a' -> ('xor_5a', 0x5a); 'add_7' -> ('add_7', 7). Parameterised names carry their own key."""
    t = _TRANSFORM_ALIAS.get((t or "").lower(), t)
    m = re.fullmatch(r"(xor|add|sub|subtract|rotate_left|rol)_([0-9a-fA-F]{1,2})", t or "")
    if m:
        return t, m.group(2) if m.group(1) == "xor" else f"{int(m.group(2)):02x}"   # add_7 = decimal 7
    return t, None


# ------------------------------------------------------------------------------------------------ helpers

def b64(text):
    """Standard or urlsafe base64, whitespace/quotes stripped, padding repaired. bytes or None."""
    s = re.sub(r"[^A-Za-z0-9+/=_-]", "", text or "")
    s = s.rstrip("=")
    s += "=" * (-len(s) % 4)
    for alt in (None, b"-_"):
        try:
            return base64.b64decode(s, altchars=alt, validate=True) if alt is None else base64.b64decode(s, altchars=alt)
        except (binascii.Error, ValueError):
            continue
    return None


def int_array(text, radix=None):
    """Integers from any separator-joined list. radix: 10/16/8, or None = per token (`0x..` hex, else decimal).
    READ THE RADIX FROM THE CODE (`parseInt(x, 16)`, `CInt("&H" & x)`, `int(x, 8)`) when it is not explicit."""
    toks = re.findall(r"0[xX][0-9a-fA-F]+|&[hH][0-9a-fA-F]+|[0-9a-fA-F]+", text or "")
    out = []
    for t in toks:
        if t[:2] in ("0x", "0X"):
            out.append(int(t, 16))
        elif t[:2] in ("&h", "&H"):
            out.append(int(t[2:], 16))
        elif radix:
            out.append(int(t, radix))
        elif t.isdigit():
            out.append(int(t))
        else:
            return None
    return out


def hex_bytes(text):
    """Hex digits in any wrapping (pairs, colon/dash/space separated, `0x`, `\\x`, `%`) -> bytes or None."""
    s = re.sub(r"0[xX]|\\x|%|&[hH]", " ", text or "")
    toks = re.findall(r"[0-9a-fA-F]+", s)
    if not toks:
        return None
    if all(len(t) <= 2 for t in toks) and len(toks) > 1:
        return bytes(int(t, 16) for t in toks)
    s = "".join(toks)
    if len(s) % 2:
        return None
    try:
        return bytes.fromhex(s)
    except ValueError:
        return None


def key_bytes(key):
    """Codec key field -> bytes. Hex ('0b', 'b8b3fe'), or a comma list of hex bytes ('b8,b3,fe')."""
    if key is None:
        return b""
    k = str(key).strip()
    if not k:
        return b""
    if "," in k:
        try:
            return bytes(int(x, 16) for x in k.split(",") if x.strip())
        except ValueError:
            return b""
    try:
        return bytes.fromhex(k if len(k) % 2 == 0 else "0" + k)
    except ValueError:
        return b""


def looks_like_plan(b):
    """The right decode yields `v=N|...` (or a JSON object)."""
    if not b:
        return False
    try:
        t = b.decode("utf-8")
    except UnicodeDecodeError:
        return False
    t = t.lstrip("﻿ \r\n\t")
    if t.startswith("{") and t.rstrip().endswith("}"):
        # a JSON plan must PARSE: a wrong rolling-xor/rotation guess can start with '{' and end with '}' by chance
        # (Day 7 Node json_numbers under a renamed rep decoded to '{Jr^hYuAx...}' and was accepted)
        import json
        try:
            return isinstance(json.loads(t), dict)
        except ValueError:
            return False
    return t.startswith("v=") or "|steps=" in t[:80]


def plan_kv(text):
    """'v=1|steps=a,b|url=..' -> dict (first '=' splits; later duplicates keep the first)."""
    out = {}
    for part in (text or "").strip().split("|"):
        if "=" in part:
            k, v = part.split("=", 1)
            out.setdefault(k.strip(), v)
    return out


# Target plan-key-passthrough: v=3 plans carry keys no question asked yet (`verdict` since D16, `language`). An answer
# id names its plan key in its tail (`set1.php-stager-next-language` -> next_language): the longest hyphen-suffix that
# is a plan key (or an alias of one) wins, so `-next-language` never reads `language`. Values go out plan-verbatim,
# shaped only by the answer_format: ordered_tokens '>'-joins a comma list, integer is base-10, enum must be one of the
# accepted_values (else None). None = this plan cannot answer the id (the per-day solver keeps its own reading).
PLAN_KEY_ALIASES = {"campaign": "campaign_id", "obfuscation": "obfuscation_profile", "file_path": "file_path",
                    "upload_url": "upload_url"}
# multi-word keys seen in v=3 plans: an id ending in one the plan lacks is unanswerable here (None), never read as the
# shorter key under it (`-next-language` must not answer `language`, `-upload-url` must not answer `url`)
PLAN_KNOWN_KEYS = {"next_language", "host_profile", "stage_profile", "obfuscation_profile", "stage_count",
                   "campaign_id", "file_path", "upload_url", "host_id"}


def plan_key_for(answer_id, plan):
    """The plan key an answer id asks for (longest suffix match, hyphens -> underscores, aliases), or None."""
    keys = {str(k).lower(): k for k in (plan or {})}
    parts = re.split(r"[-_]+", str(answer_id or "").rsplit(".", 1)[-1].lower())
    for i in range(len(parts)):
        suf = "_".join(p for p in parts[i:] if p)
        for cand in (suf, PLAN_KEY_ALIASES.get(suf), suf + "_id"):
            if cand and cand in keys:
                return keys[cand]
        if "_" in suf and (suf in PLAN_KNOWN_KEYS or PLAN_KEY_ALIASES.get(suf) in PLAN_KNOWN_KEYS):
            return None
    return None


def _plan_dict(plan):
    if isinstance(plan, dict):
        return plan
    if isinstance(plan, (bytes, bytearray)):
        plan = bytes(plan).decode("utf-8", "replace")
    t = str(plan or "").lstrip("﻿ \r\n\t")
    if t.startswith("{"):
        import json
        try:
            d = json.loads(t)
            return d if isinstance(d, dict) else {}
        except ValueError:
            return {}
    return plan_kv(t)


def plan_answer(answer_id, plan, q=None):
    """Answer `answer_id` straight from a decoded plan (dict, `k=v|..` text or JSON text) under the question's
    answer_format, or None when the plan has no such key / the value does not fit the format. Never raises."""
    try:
        plan = _plan_dict(plan)
        key = plan_key_for(answer_id, plan)
        if key is None or plan.get(key) is None:
            return None
        val = plan[key]
        fmt = (q or {}).get("answer_format") or {}
        kind = str(fmt.get("kind") or "").lower()
        if isinstance(val, (list, tuple)):
            val = ",".join(str(x) for x in val)
        val = str(val).strip()
        if kind == "ordered_tokens":
            toks = [t.strip() for t in re.split(r"[,>]", val) if t.strip()]
            return ">".join(toks) if toks else None
        if kind == "integer":
            return str(int(val)) if re.fullmatch(r"[+-]?\d+", val) else None
        if kind == "enum":
            acc = [str(a) for a in fmt.get("accepted_values") or []]
            if not acc:
                return val
            return val if val in acc else next((a for a in acc if a.lower() == val.lower()), None)
        return val
    except Exception:  # noqa: BLE001
        return None


# Target per-file-hashed-contract (D23/D24 TT + Mastery): answer ids `<family>-<4-8 hex member stem>-<field>` over
# `<stem>.<ext>` members (`jscript-9a6714-style`, `bash-advanced-ab2131-feature`, `set2.python-4c1097-handoff-id`).
# pf_route splits an id into (family, member, field), checked against the archive's members; pf_answer reads a field
# from a decoded plan / per-member analysis dict: composite `|`-joined labels (style / carrier / obfuscation), the
# primary indicator by the precedence the QUESTION states, campaign-token, url-host, path-leaf, PS secondary /
# tertiary keyed by scenario, anything else through plan_answer. None = cannot answer here. Never raises.
PF_HEX = re.compile(r"[0-9a-f]{4,8}")
PF_FIELD = re.compile(r"[a-z][a-z0-9-]*")
PF_KIND = {"jscript": "js", "javascript": "js", "js": "js", "batch": "bat", "bat": "bat", "cmd": "bat",
           "vbscript": "vbs", "vbs": "vbs", "python": "py", "py": "py", "powershell": "ps", "ps": "ps", "ps1": "ps"}
# composite fields: the solver's analysis keys per kind, in the order the question lists the labels
PF_COMPOSITE = {("js", "style"): (("function-style", "function_style"), ("invocation-style", "invocation_style"),
                                  ("property-style", "property_style")),
                ("bat", "style"): (("graph", "topology"), ("control",),
                                   ("expansion_style", "expansion_stmt", "expansion")),
                ("vbs", "style"): (("representation", "rep"), ("transform",), ("control",)),
                ("py", "carrier"): (("carrier",), ("windows-chain", "windows_chain")),
                ("py", "obfuscation"): (("syntax",), ("obfuscation",))}
PF_INDICATOR_ORDER = ("url", "upload_url", "next_stage", "file_path", "schedule_path", "note_name", "recovery_note",
                      "host_id")
# question phrase (lower, [- ] -> _) -> plan keys, tried in order
PF_PHRASE_KEYS = {"url": ("url",), "upload_url": ("upload_url",), "next_stage_file": ("next_stage", "next_stage_file"),
                  "next_stage": ("next_stage",), "file_path": ("file_path",),
                  "schedule_path": ("schedule_path",), "recovery_note_name": ("note_name", "recovery_note"),
                  "recovery_note": ("recovery_note", "note_name"), "note_name": ("note_name",),
                  "host_id": ("host_id",), "wallet_address": ("wallet",), "mutex_name": ("mutex",),
                  "staged_file_name": ("file",), "user_agent": ("agent", "user_agent"),
                  "encrypted_file_extension": ("extension",)}
PF_PS_BY_SCENARIO = {"resource_hijacking": ("wallet", "mutex"), "synthetic_collection": ("file", "agent"),
                     "synthetic_impact": ("note", "extension")}


def _pf_split(aid):
    """All (family, stem, field) readings of an id (set prefix dropped), rightmost hex token first."""
    tail = str(aid or "").strip()
    tail = re.sub(r"^set\d+\.", "", tail, flags=re.I)
    toks = tail.split("-")
    out = []
    for i in range(len(toks) - 2, 0, -1):
        field = "-".join(toks[i + 1:])
        if PF_HEX.fullmatch(toks[i]) and PF_FIELD.fullmatch(field):
            out.append(("-".join(toks[:i]), toks[i], field))
    return out


def pf_route(answer_id, question=None, members=()):
    """`<family>-<stem>-<field>` -> (family, member, field), the member being the archive member whose stem the id
    names (members = names/paths, or the question's `artifact` `zip -> member` when none given); None otherwise."""
    try:
        names = [str(m) for m in (members or ())]
        art = str((question or {}).get("artifact") or "")
        if art:
            names.append(art.split("->")[-1].strip())
        stems = {}
        for n in names:
            leaf = re.split(r"[\\/]", n.split("->")[-1].strip())[-1]
            stems.setdefault(leaf.rsplit(".", 1)[0].lower() if "." in leaf else leaf.lower(), n.split("->")[-1].strip())
        for fam, stem, field in _pf_split(answer_id):
            if stem in stems:
                return fam, stems[stem], field
        return None
    except Exception:  # noqa: BLE001
        return None


def _pf_get(plan, *keys):
    for k in keys:
        for kk in (k, "ind:" + k, k.replace("-", "_"), "ind:" + k.replace("-", "_"), k.replace("_", "-")):
            v = plan.get(kk)
            if v not in (None, ""):
                return v
    return None


def pf_indicator_order(question):
    """Plan keys in the precedence the question states (`... using this order: URL, upload URL, next-stage file, ...`),
    falling back to the D23 order when the question names none."""
    text = str((question or {}).get("question") or "") if isinstance(question, dict) else str(question or "")
    m = re.search(r"\b(?:order|precedence)\s*:\s*([^.]*(?:\.[a-z][^.]*)*)", text, re.I)
    if not m:
        return [(k,) for k in PF_INDICATOR_ORDER]
    out = []
    for ph in re.split(r",|\bthen\b|\bor\b|\band\b|>", m.group(1)):
        n = re.sub(r"[^a-z0-9]+", "_", ph.strip().lower()).strip("_")
        if not n:
            continue
        keys = PF_PHRASE_KEYS.get(n)
        if keys is None:
            keys = (n,) + ((n.rsplit("_", 1)[0],) if n.endswith(("_name", "_file", "_value")) else ())
        out.append(tuple(keys))
    return out or [(k,) for k in PF_INDICATOR_ORDER]


def pf_answer(field, plan, question=None, kind=None):
    """The value of per-file `field` from a decoded plan (dict / `k=v|..` text / JSON text) or a per-member analysis
    dict; kind = js|bat|vbs|py|ps (or the id's family). None when the plan cannot answer it."""
    try:
        o = _plan_dict(plan)
        if not o:
            return None
        field = str(field or "").lower()
        kind = PF_KIND.get(str(kind or "").lower().split("-")[0], str(kind or "").lower())
        q = question if isinstance(question, dict) else {"question": str(question or "")}
        if field in ("campaign-token", "campaign_token"):
            c = _pf_get(o, "campaign", "campaign_id")
            return str(c).split("-", 1)[1] if c and "-" in str(c) else None
        if field == "campaign":
            return _pf_get(o, "campaign", "campaign_id")
        if field == "steps":
            v = _pf_get(o, "steps")
            if isinstance(v, (list, tuple)):
                v = ">".join(str(x) for x in v)
            toks = [x.strip() for x in re.split(r"[,>]", str(v or "")) if x.strip()]
            return ">".join(toks) or None
        if field == "indicator":
            for keys in pf_indicator_order(q):
                v = _pf_get(o, *keys)
                if v is not None:
                    return str(v)
            return None
        if field == "url-host":
            from urllib.parse import urlsplit
            u = _pf_get(o, "url")
            return urlsplit(str(u)).hostname if u else None
        if field == "path-leaf":
            p = _pf_get(o, "file_path")
            return (re.split(r"[\\/]", str(p))[-1] or None) if p else None
        if kind == "ps" and field in ("secondary", "tertiary"):
            pair = PF_PS_BY_SCENARIO.get(str(o.get("scenario") or ""))
            return _pf_get(o, pair[field == "tertiary"]) if pair else None
        comp = PF_COMPOSITE.get((kind, field))
        if comp:
            vals = [_pf_get(o, *alts) for alts in comp]
            return "|".join(str(v) for v in vals) if all(v is not None for v in vals) else None
        v = _pf_get(o, field)
        if v is not None:
            return v if isinstance(v, str) else ">".join(map(str, v)) if isinstance(v, (list, tuple)) else str(v)
        return plan_answer(field, o, q)
    except Exception:  # noqa: BLE001
        return None


# ------------------------------------------------------------------------------------------------ reps

def _rep_candidates(rep, material):
    """All plausible byte readings of the written material for this rep (most likely first)."""
    m = material or ""
    c = []
    if rep.startswith(("gzip", "zlib", "deflate")):   # D16 names: the compressed stream written as base64 / hex
        c += [_inflate(x) for x in (hex_bytes(m) if "hex" in rep else b64(m),) if x]
    elif rep in ("base32", "base85", "ascii85"):
        c += _layer_readings(m, rep)
    elif rep.startswith(("hex_base64", "hex_b64")):   # D8 v=3 `HB64`: hex digits of a base64 text (GM label hex_base64)
        h = hex_bytes(m)
        c += [b64(h.decode("latin-1")) if h else None, h]
    elif "base64" in rep:
        c.append(b64(m))
        c.append(b64(m[::-1]))
    elif rep.startswith("reversed_hex"):
        h = hex_bytes(m)
        c += [h[::-1] if h else None, hex_bytes(re.sub(r"[^0-9a-fA-F]", "", m)[::-1])]
    elif "hex" in rep:
        c.append(hex_bytes(m))
    elif rep.endswith("escapes"):   # Node `unicode_escapes` (D7): '\\u0076\\u003d..' -- any backslash count
        esc = re.findall(r"\\+u([0-9a-fA-F]{4})|\\+x([0-9a-fA-F]{2})", m)
        v = [int(a or b, 16) for a, b in esc]
        c.append(bytes(v) if v and all(x < 256 for x in v) else None)
    elif rep.startswith("octal"):
        a = int_array(m, 8)
        c.append(bytes(a) if a and all(0 <= x < 256 for x in a) else None)
    elif rep.startswith(("reversed_decimal", "reversed_integer")):
        a = int_array(m, 10)
        c.append(bytes(a[::-1]) if a and all(0 <= x < 256 for x in a) else None)
        c.append(bytes(a) if a and all(0 <= x < 256 for x in a) else None)
    elif rep.startswith(("decimal", "integer", "json_num")):   # json_numbers (Node, D7) = '[118,61,49,..]'
        a = int_array(m, 10) or int_array(m)
        c.append(bytes(a) if a and all(0 <= x < 256 for x in a) else None)
    elif rep == "reversed_text":
        c += [m[::-1].encode("latin-1", "replace"), m.encode("latin-1", "replace"), b64(m[::-1]), b64(m)]
    else:  # plain_fragments / split_fragments / unknown text-ish reps: the text itself, or a base64 of it
        c += [m.encode("latin-1", "replace"), b64(m), hex_bytes(m)]
    seen, out = set(), []
    for x in c:
        if x and x not in seen:
            seen.add(x)
            out.append(x)
    return out


# ------------------------------------------------------------------------------------------------ transforms

_XOR_TABLES = {}


def _xor_table(k):
    """bytes.translate table for a single-byte XOR key (built once per key)."""
    t = _XOR_TABLES.get(k)
    if t is None:
        t = _XOR_TABLES[k] = bytes(x ^ k for x in range(256))
    return t


def _xor(b, k):
    # same bytes as `bytes(x ^ k[i % len(k)] for i, x in enumerate(b))`, via translate / one big-int XOR (fast path)
    if not k:
        return b
    b = bytes(b)
    if len(k) == 1:
        return b.translate(_xor_table(k[0]))
    n = len(b)
    if not n:
        return b""
    ks = (bytes(k) * (n // len(k) + 1))[:n]
    return (int.from_bytes(b, "big") ^ int.from_bytes(ks, "big")).to_bytes(n, "big")


_PREFIX_XOR = {}


def _rolling(b, k0, flavour):
    # cipher: p[i] = b[i] ^ b[i-1] (b[-1] = k0) -> one big-int XOR; plain: p[i] = k0 ^ b[0] ^ .. ^ b[i] -> the
    # key-0 prefix XOR (memoised per input, the caller sweeps 256 keys) translated by k0. Same bytes as the byte loop.
    b = bytes(b)
    n = len(b)
    if not n:
        return b""
    if flavour == "cipher":
        return (int.from_bytes(b, "big") ^ int.from_bytes(bytes([k0]) + b[:-1], "big")).to_bytes(n, "big")
    px = _PREFIX_XOR.get(b)
    if px is None:
        out, prev = bytearray(n), 0
        for i, x in enumerate(b):
            prev ^= x
            out[i] = prev
        if len(_PREFIX_XOR) > 32:
            _PREFIX_XOR.clear()
        px = _PREFIX_XOR[b] = bytes(out)
    return px.translate(_xor_table(k0)) if k0 else px


def _transform_candidates(transform, key, data):
    t, inline = _base_transform(transform)
    k = key_bytes(inline if inline is not None else key)
    k1 = k[0] if k else None
    rev = data[::-1]
    if t == "identity":
        yield data
    elif t in ("reverse", "reverse_bytes"):
        yield rev
    elif t.startswith("xor_") or t == "single_byte_xor" or t == "repeating_key_xor":
        yield _xor(data, k)
        yield _xor(rev, k)
    elif t.startswith("add_"):
        yield bytes((x - k1) % 256 for x in data) if k1 is not None else data
    elif t.startswith(("sub_", "subtract_")):
        yield bytes((x + k1) % 256 for x in data) if k1 is not None else data
    elif t in ("reverse_then_xor", "reverse_xor"):
        kk = k or b"\x5a"           # batch `reverse_xor` carries no key field (0x5a family seen with it)
        yield _xor(rev, kk)
        yield _xor(data, kk)[::-1]
        if not k:
            for g in range(1, 256):
                yield _xor(rev, bytes([g]))
    elif t == "rolling_xor":
        for start in ([k1] if k1 is not None else range(256)):
            yield _rolling(data, start, "cipher")
            yield _rolling(data, start, "plain")
    elif t == "rot13":
        yield data.translate(_ROT13)
    elif t == "atbash":
        yield data.translate(_ATBASH)
    elif t == "rc4":   # stated key: hex bytes, else the key text itself
        for kk in dict.fromkeys(x for x in (k, str(key or "").strip().encode("latin-1", "ignore")) if x):
            yield _rc4(data, kk)
    elif t in ("gzip", "zlib", "deflate"):
        z = _inflate(data)
        if z:
            yield z
    elif t in ("rotate_left", "rol"):
        amounts = [int(inline, 16) % 8] if inline else ([k1 % 8] if k1 else list(range(1, 8)))
        for n in amounts:
            yield bytes(((x >> n) | (x << (8 - n))) & 0xFF for x in data)   # undo a left rotation


_UP, _LO = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ", b"abcdefghijklmnopqrstuvwxyz"
_ROT13 = bytes.maketrans(_UP + _LO, _UP[13:] + _UP[:13] + _LO[13:] + _LO[:13])
_ATBASH = bytes.maketrans(_UP + _LO, _UP[::-1] + _LO[::-1])
_ROT13_S = str.maketrans(_UP.decode() + _LO.decode(), (_UP[13:] + _UP[:13] + _LO[13:] + _LO[:13]).decode())
_B32_TEXT = re.compile(r"[A-Z2-7]{8,}=*|[a-z2-7]{8,}=*")


def _rc4(b, k):
    if not k or len(b) > (1 << 16):
        return b""
    S, j = list(range(256)), 0
    for i in range(256):
        j = (j + S[i] + k[i % len(k)]) & 255
        S[i], S[j] = S[j], S[i]
    out, i, j = bytearray(), 0, 0
    for x in b:
        i = (i + 1) & 255
        j = (j + S[i]) & 255
        S[i], S[j] = S[j], S[i]
        out.append(x ^ S[(S[i] + S[j]) & 255])
    return bytes(out)


def _inflate(b, raw=True):
    """gzip (H4sI) / zlib (eJ, eF..) / bz2 / xz by magic, raw deflate too when `raw`: the COMPLETE stream's bytes, else
    None. A truncated stream (no end marker) is None, never a partial plan. Output bounded to 256 KiB."""
    import bz2
    import lzma
    import zlib
    if not b or len(b) < 8:
        return None
    try:
        if b[:3] == b"BZh":
            d = bz2.BZ2Decompressor()
        elif b[:6] == b"\xfd7zXZ\x00":
            d = lzma.LZMADecompressor()
        else:
            if b[:2] == b"\x1f\x8b":
                w = 31
            elif b[0] & 0x0F == 8 and b[0] >> 4 <= 7 and ((b[0] << 8) | b[1]) % 31 == 0:
                w = 15
            elif raw:
                w = -15
            else:
                return None
            d = zlib.decompressobj(w)
        out = d.decompress(b, 1 << 18)
        return out if out and d.eof else None
    except (zlib.error, OSError, EOFError, ValueError, lzma.LZMAError):
        return None


def _layer_readings(material, rep):
    """Second-pass readings: base32 ([A-Z2-7]=), base85 / Ascii85 (<~..~>), base64 of a ROT13'd text, then every
    generic reading -- each followed by its inflated stream when it is gzip / zlib / raw deflate. Unvalidated."""
    m0 = re.sub(r"\s+", "", material or "").strip("\"'")   # '`' is a base85 digit
    out = []
    for m in dict.fromkeys((m0, m0[::-1])):
        if _B32_TEXT.fullmatch(m):
            s = m.upper().rstrip("=")
            try:
                out.append(base64.b32decode(s + "=" * (-len(s) % 8)))
            except (binascii.Error, ValueError):
                pass
        a = m[2:-2] if m.startswith("<~") and m.endswith("~>") else m
        for f in (base64.b85decode, base64.a85decode):
            try:
                out.append(f(a))
            except (binascii.Error, ValueError):
                pass
        if re.fullmatch(r"[A-Za-z0-9+/=_-]{8,}", m):
            out.append(b64(m.translate(_ROT13_S)))
    out += _generic_readings(material or "", rep or "")
    seen, res = set(), []
    for b in out:
        for x in (b, _inflate(b)):
            if x and x not in seen:
                seen.add(x)
                res.append(x)
    return res


def _spec(rep, transform, key):
    """Normalise short codec specs (D7 bash): `rep|` (empty transform) = identity; `xor_hex|cd` (the rep names the xor
    and the 2nd field is the KEY, not a transform) = repeating_key_xor with that key."""
    t = (transform or "").strip()
    if not t:
        return "identity", key
    if "xor" in rep and t not in TRANSFORMS and _base_transform(t)[1] is None and \
            re.fullmatch(r"[0-9a-fA-F]{1,2}(?:,?[0-9a-fA-F]{2})*", t):
        return "repeating_key_xor", t
    return t, key


def decode(material, rep, transform, key=None):
    """Plaintext (str) of a declared codec, or None. Tries the rep's plausible readings x the transform's plausible
    parameters and returns the first that looks like a plan (`v=` / JSON). Unknown names fall through to
    `_fallback()` (a name-agnostic reading of the literal itself); None if that finds no plan either."""
    if not material or not rep:
        return None
    if re.sub(r"[^a-z]", "", rep.lower()) in ("cmdline", "commandline"):   # cmdline-canon (no plan reading)
        got = _cl_decode(material, rep, transform)
        if got is not None:
            return got
    if re.sub(r"[^a-z]", "", rep.lower()) in ("pipelinelocus", "executionlocus", "locus"):   # pipeline-execution-locus
        return _locus_decode(material, transform)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("jenkinshome", "jenkinssecrets", "jenkinsartifacts"):   # jenkins-artifact-secrets
        return _jenkins_decode(material, transform)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("ghaworkflow", "ghatrust", "githubactions"):   # gha-trigger-trust-model
        return _gha_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("ciexpressions", "ciexpression", "expressioninjection", "ciinjection"):   # ci-expression-injection-secrets
        return _cix_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("actionhandoffs", "actionhandoff", "actiondefinition"):   # github-action-definition-route
        return _ah_decode(material, transform)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("repohooks", "repohook", "githooks", "repoautorun"):   # git-repo-hooks-route
        return _rh_decode(material, transform)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("plistscripts", "launchd", "plist", "launchdplist"):   # launchd-plist-route
        return _plist_decode(material, transform)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("scheduleentries", "persistence", "schedulepersistence"):   # ci-schedule-persistence-model
        return _sched_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("installeractions", "installeraction", "installerscript"):   # installer-action-model
        return _ia_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("asar", "electronasar", "appasar", "squirrel", "squirrelnupkg", "nupkg",
                                              "squirrelsetup", "electronapp"):   # electron-asar-squirrel-route
        return _electron_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("rpa", "renpy", "renpyarchive", "rpyc", "renpycompiled", "unityfs",
                                              "unitybundle", "gamearchive", "love", "lovearchive"):   # game-archive-carriers
        return _game_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("deb", "rpm", "apk", "ipk", "pkgscripts", "maintainerscripts",
                                              "linuxpackage", "rpmspec", "pkgbuild", "apkbuild"):   # linux-package-maintainer-scripts
        return _pkg_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("webshell", "webshellmodel", "webshellprimitives"):   # webshell-request-primitive-model
        return _ws_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("configchain", "configdiff", "configsurvival", "stageconfig"):   # stage-config-survival-diff
        return _cfgchain_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("lineage", "specimenlineage", "parentattribution", "lineageattribution"):   # specimen-lineage-attribution
        return _lin_decode(material, transform, key)
    if re.sub(r"[^a-z]", "", rep.lower()) in ("corpussummary", "corpusaggregate", "corpusstats", "capstone"):   # corpus-aggregate-questions
        return _cs_decode(material, transform, key)
    transform, key = _spec(rep, transform, key)
    if known(rep, transform):
        for data in _rep_candidates(rep, material):
            for out in _transform_candidates(transform, key, data):
                if looks_like_plan(out):
                    return out.decode("utf-8").lstrip("\ufeff")
    return _fallback(material, rep, transform, key)


FALLBACK = os.environ.get("HCTF_CODEC_FALLBACK", "1") != "0"   # 0: names only (strict replay of what day N knew)


def _generic_readings(material, rep):
    """Byte readings of a literal read from its own FORM, not the rep name: \\uXXXX/\\xXX escapes, an int array
    (decimal, or hex when the rep says hex), compact hex, base64 -- each also from the reversed TEXT, and reversed
    bytes. Day 7 TT renamed reps mid-day (`unicode_escapes`, `json_numbers`, `reversed_base64|`, `xor_hex|cd`): every
    one was readable from the material itself, but cost a ~100s generalize because decode() keyed on the name."""
    out = []
    for m in (material, material[::-1]):
        esc = re.findall(r"\\+u([0-9a-fA-F]{4})|\\+x([0-9a-fA-F]{2})", m)
        if esc:
            v = [int(a or b, 16) for a, b in esc]
            if all(x < 256 for x in v):
                out.append(bytes(v))
        if re.fullmatch(r"\s*[\[(]?[\s0-9a-fA-FxX,;:|.-]+[\])]?\s*", m) and re.search(r"[\s,;:|.-]", m.strip()):
            for radix in ((8, 10, 16) if "oct" in rep else (16, 10, 8) if "hex" in rep else (10, 16, 8)):
                try:
                    a = int_array(m, radix)
                except ValueError:       # '3d' is not radix 10: that reading just doesn't apply
                    continue
                if a and all(0 <= x < 256 for x in a):
                    out.append(bytes(a))
        for f in (hex_bytes, b64):
            try:
                b = f(m)
            except (ValueError, TypeError):
                b = None
            if b:
                out.append(b)
    seen, uniq = set(), []
    for b in out + [b[::-1] for b in out]:
        if b not in seen:
            seen.add(b)
            uniq.append(b)
    return uniq


def _fallback(material, rep, transform, key):
    """Name-agnostic decode: generic readings x (the declared transform if known, then every known transform), with
    the declared key or any hex-looking spec field as the key. Only a plan-shaped plaintext is accepted, so a wrong
    guess returns None rather than garbage. Never raises."""
    if not FALLBACK:
        return None
    try:
        trs = [transform] if known(transform=transform) else []
        trs += [t for t in TRANSFORMS if t not in trs and known(transform=t)]
        keys = [k for k in dict.fromkeys([key, transform]) if k and re.fullmatch(r"[0-9a-fA-F]{1,8}|(?:[0-9a-fA-F]{2},)+[0-9a-fA-F]{2}", k)] or [key]
        readings = (_rep_candidates(rep, material) if known(rep) else []) + _generic_readings(material, rep or "")
        for data in readings:
            if not data:
                continue
            for t in trs:
                for k in keys:
                    for out in _transform_candidates(t, k, data):
                        if looks_like_plan(out):
                            return out.decode("utf-8").lstrip("\ufeff")
        return _fallback_layers(material, rep, transform, trs, keys, readings)
    except Exception:  # noqa: BLE001 - a tool for the solver: unknown -> None, never an exception
        return None


def _fallback_layers(material, rep, transform, trs, keys, tried, budget=0.15):
    """Second _fallback pass (gzip-zlib-codec-rep): base32 / base85 / gzip / zlib / deflate readings x (the layer
    transforms rot13 / atbash / rc4 / inflate, then the earlier ones), each output also inflated when it carries a
    gzip / zlib / bz2 / xz magic (plan -> gzip -> rc4). Runs only after the first pass found nothing, so every earlier
    result is unchanged; pairs the first pass already tried skip straight to the inflate check. Bounded by `budget`."""
    import time
    end = time.time() + budget
    lay = [t for t in _LAYER_TRANSFORMS if known(transform=t)]
    trs2 = list(dict.fromkeys(([transform] if transform in trs else []) + lay + trs))
    tried = set(tried)
    for data in _layer_readings(material, rep or ""):
        for t in trs2:
            old = data in tried and t not in lay
            for k in keys:
                for out in _transform_candidates(t, k, data):
                    if not old and looks_like_plan(out):
                        return out.decode("utf-8").lstrip("\ufeff")
                    z = _inflate(out, raw=False)
                    if z and looks_like_plan(z):
                        return z.decode("utf-8").lstrip("\ufeff")
            if time.time() > end:
                return None
    return None


# ------------------------------------------------------------------------------------------------ source scanning

_CODEC_RE = re.compile(r"""(?:Codec|CODEC)_(?P<id>[0-9A-Za-z]+)(?:\s+(?i:As)\s+[A-Za-z_][\w.]*)?\s*=\s*["'](?P<spec>[^"']*)["']""")
_BATCH_CODEC_RE = re.compile(r"HUNTRESS-CODEC:\s*(?P<spec>\S+)")
_BATCH_MAT_RE = re.compile(r"HUNTRESS-MATERIAL:\s*(?P<mat>\S+)")
# D8 cross-language v=3 fixtures (.php, .wsf/.hta markup inside .js/.vbs): `HUNTRESS_ANALYSIS_V1:<TAG>-<data>` comment +
# the same data in a `descriptor_<id>` literal; identity transform. FRAG = dot-separated hex fragments.
_ANALYSIS_RE = re.compile(r"""HUNTRESS_ANALYSIS_V\d+:(?P<tag>[A-Za-z0-9_]+)-(?P<mat>[^\s"'<]+)""")
_ANALYSIS_TAG_REP = {"B64": "base64_literal", "HEX": "hex_compact", "HB64": "hex_base64", "FRAG": "hex_compact"}


def material_text(src, ident):
    """The written payload for `Material_<ident>` / `MATERIAL_<ident>`: every string literal (or the int tuple/array)
    of its assignment(s), joined in order -- one literal, `& _` / `+` continuation, adjacent quoted strings, later
    `+=` / `&=` appends. Returns the raw text (rep decoding is decode()'s job) or None."""
    pat = re.compile(r"(?:Material|MATERIAL)_" + re.escape(ident) + r"(?:_[0-9A-Za-z]+)?\b")   # also split `_a`/`_b` parts
    pieces = []
    for m in pat.finditer(src):
        rest = src[m.end():]
        a = re.match(r"(?:\s+(?i:As)\s+[A-Za-z_][\w.]*)?\s*(\+=|&=|=|\.=)?\s*", rest)   # VBA `Const X As String =`
        if not a or not a.group(1):
            continue                                   # a use, not an assignment
        body = rest[a.end():]
        if body[:1] in "([{" and not body.startswith(("('", '("')):
            close = {"(": ")", "[": "]", "{": "}"}[body[0]]
            end = body.find(close)
            pieces.append(body[1:end] if end > 0 else body[1:400])
            continue
        # string literal(s) until the statement ends (newline not preceded by a continuation)
        stmt, depth = [], 0
        for line in body.splitlines():
            stmt.append(line)
            depth += line.count("(") - line.count(")")       # parenthesised adjacent literals: ("..." \n "...")
            if depth <= 0 and not re.search(r"(&\s*_|\+|\\|,)\s*$", line.rstrip()):
                break
        text = "\n".join(stmt)
        lits = re.findall(r'"((?:[^"\\]|\\.)*)"|\'((?:[^\'\\]|\\.)*)\'', text)
        joined = "".join(a or b for a, b in lits)
        if joined:
            pieces.append(joined)
    return "".join(pieces) or None


# Unix scripting-language material templates (prebuild ruby-perl-pack-reps, 10-16): a v=1 `Codec_<id>` whose material
# is WRITTEN through the language's own byte syntax instead of one plain literal -- Ruby `["..."].pack("H*")`,
# `"..".unpack1("m0")`, `[118, 61].pack("C*")`, `%w[76 3d].map(&:hex).pack("C*")`, `"\u{76 3d}"`; Perl
# `pack("H*", "..")`, `pack("C*", qw(..))`, `MIME::Base64::decode("..")`, `"\x{76}"`; Tcl `set Material_x [binary
# decode hex|base64 ".."]`, `binary format c* {..}`, `set Codec_x {..}`; Lua `"\118\061"`, `string.char(..)`.
# material_text() joins every literal (format `H*` / `m0` included) or misses the statement (Tcl `set`); here the
# assignment is read by its shape + the named template: the inner literal under the declared rep, then the bytes the
# template evaluates to (also with the template ops chained in either order) under the declared transform. Only
# consulted when the plain material reading found no plan, so every earlier result is unchanged. Bounded, never raises.
_TPL_CODEC_RES = (re.compile(r"""\bset\s+(?:Codec|CODEC)_(?P<id>[0-9A-Za-z]+)\s+(?:"(?P<q>[^"]*)"|\{(?P<b>[^{}]*)\})"""),
                  re.compile(r"""(?:Codec|CODEC)_(?P<id>[0-9A-Za-z]+)['"]?\s*=>\s*(?:"(?P<q>[^"]*)"|'(?P<b>[^']*)')"""))
_TPL_FMT = re.compile(r"[A-Za-z][*\d]{0,3}")
_TPL_WORDS = re.compile(r"(?:%[wWiI]|\bqw)\s*([\[({</|!])")
_TPL_ESC_PERL = re.compile(r"\\(x\{[0-9a-fA-F\s]{1,8}\}|x[0-9a-fA-F]{1,2}|u\{[0-9a-fA-F\s]{1,64}\}|u[0-9a-fA-F]{4}|"
                           r"[0-7]{1,3}|.)", re.S)
_TPL_ESC_LUA = re.compile(r"\\(x[0-9a-fA-F]{2}|u\{[0-9a-fA-F]{1,6}\}|\d{1,3}|.)", re.S)


def _tpl_unescape(body, lua=False):
    """Double-quoted literal body -> its bytes: Ruby/Perl/Tcl (`\\u{76 3d}`, `\\x{76}`, `\\xHH`, octal `\\166`) or Lua
    (decimal `\\118`, `\\xHH`, `\\u{..}`). None when an escape is out of range."""
    def sub(m):
        s = m.group(1)
        if s[0] in "xu" and len(s) > 1 and (s[1] == "{" or s[0] == "x" or len(s) == 5):
            return "".join(chr(int(h, 16)) for h in s[1:].strip("{}").split())
        if s[0].isdigit():
            v = int(s, 10 if lua else 8)
            if v > 255:
                raise ValueError(s)
            return chr(v)
        return _CH_DQ_ESC.get(s, s)
    try:
        t = (_TPL_ESC_LUA if lua else _TPL_ESC_PERL).sub(sub, body)
        return t.encode("latin-1") if max(map(ord, t or "\0")) < 256 else t.encode("utf-8")
    except (ValueError, OverflowError):
        return None


def _tpl_stmts(src, ident, limit=8):
    """RHS text of each `Material_<id> = ..` / `=> ..` / `.= ..` / `<< ..` / Tcl `set Material_<id> ..` statement."""
    pat = re.compile(r"(\bset\s+|\bappend\s+)?[$@]?(?:Material|MATERIAL)_" + re.escape(ident) + r"(?:_[0-9A-Za-z]+)?\b")
    out = []
    for m in pat.finditer(src):
        a = re.compile(r"[ \t]+" if m.group(1) else r"['\"]?\s*(\+=|\.=|<<|=>|=(?![=~]))\s*").match(src, m.end())
        if not a:
            continue
        i, depth, q, prev = a.end(), 0, None, ""
        while i < len(src) and i - a.end() < 65536:
            c = src[i]
            if q:
                if c == "\\":
                    i += 1
                elif c == q:
                    q = None
            elif c in "\"'":
                q = c
            elif c in "([{":
                depth += 1
            elif c in ")]}":
                depth -= 1
                if depth < 0:
                    break
            elif depth <= 0 and (c == ";" or c == "\n" and prev not in "\\+.,&(|"):
                break
            if not c.isspace():
                prev = c
            i += 1
        out.append(src[a.end():i])
        if len(out) >= limit:
            break
    return out


def _tpl_parse(stmt, tcl):
    """(literals [(quote, body)], words, bare text outside literals) of one RHS."""
    lits, words, bare, i, s = [], [], [], 0, stmt
    while i < len(s):
        c = s[i]
        w = _TPL_WORDS.match(s, i)
        if w:
            close = _CH_PAIR.get(w.group(1), w.group(1))
            j = s.find(close, w.end())
            j = len(s) if j < 0 else j
            words += s[w.end():j].split()
            i = j + 1
            continue
        if c in "\"'" or (tcl and c == "{"):
            close = "}" if c == "{" else c
            j, body = i + 1, []
            while j < len(s) and s[j] != close:
                if s[j] == "\\" and j + 1 < len(s) and c != "{":
                    body.append(s[j:j + 2])
                    j += 2
                    continue
                body.append(s[j])
                j += 1
            lits.append((c, "".join(body)))
            i = j + 1
            bare.append(" ")
            continue
        bare.append(c)
        i += 1
    return lits, words, "".join(bare)


def _tpl_ops(stmt):
    """Decoding ops the statement names, in source order: 'hex' / 'hexlo' / 'b64' / 'bytes'."""
    ops = []
    pats = ((r"""\bunpack1?\s*\(?\s*["']m0?\*?["']|\bdecode64\b|\bstrict_decode64\b|\bdecode_base64\b|"""
             r"""MIME::Base64::decode\b|\bb64decode\b|\bbase64_decode\b|binary\s+decode\s+base64\b|\bfrom_base64\b""",
             "b64"),
            (r"""\bpack\s*\(?\s*["']H\*?\d*["']|binary\s+(?:decode\s+hex|format\s+H\*?\d*)\b|\bhex2bin\b|"""
             r"""\bunhexlify\b|\bfrom_hex\b""", "hex"),
            (r"""\bpack\s*\(?\s*["']h\*?\d*["']|binary\s+format\s+h\*?\d*\b""", "hexlo"),
            (r"""\bpack\s*\(?\s*["'][CcUW]\*?\d*["']|binary\s+format\s+[cC]\*?\d*\b|\bstring\.char\b|\bchr\b|"""
             r"""\.chr\b|&:chr\b""", "bytes"))
    for p, op in pats:
        ops += [(m.start(), op) for m in re.finditer(p, stmt)]
    return [op for _, op in sorted(ops)]


def _tpl_apply(op, text):
    if op == "b64":
        return b64(text)
    h = hex_bytes(text) if re.fullmatch(r"[\s0-9a-fA-F]+", text or "") else None
    if h and op == "hexlo":
        return bytes(((x & 15) << 4) | (x >> 4) for x in h)
    return h


def _tpl_numbers(words, lits, bare, stmt):
    """Byte list of a pack('C*') / string.char / binary format c* template, radix read from the code (`hex`, `16`)."""
    toks = list(words)
    for q, body in lits:
        if re.fullmatch(r"[\s,0-9a-fA-FxX]+", body) and re.search(r"[\s,]", body.strip()):
            toks += re.split(r"[\s,]+", body.strip())
    b = re.sub(r"\bto_i\s*\(\s*16\s*\)|\bunpack1\b|[\w.]*[A-Za-z_][\w.]*\d\w*", " ", bare)
    toks += re.findall(r"(?<![\w.])(?:0[xX][0-9a-fA-F]+|\d+)(?![\w.])", b)
    toks = [t for t in toks if t]
    if not toks:
        return []
    hexy = bool(re.search(r"\bhex\b|&:hex|to_i\s*\(\s*16|\b16\b|scan\s*%x", stmt)) or \
        any(re.search(r"[a-fA-F]", t) and not t.lower().startswith("0x") for t in toks)
    out = []
    for radix in ((16, 10) if hexy else (10, 16)):
        try:
            v = [int(t, 16) if t.lower().startswith("0x") else int(t, radix) for t in toks]
        except ValueError:
            continue
        if all(0 <= x < 256 for x in v):
            out.append(bytes(v))
        elif "U*" in stmt and all(0 <= x < 0x110000 for x in v):
            out.append("".join(map(chr, v)).encode("utf-8"))
    return out


def _tpl_decode(src, ident, rep, tr, key, budget=0.8):
    """(plain, statement) for a template-written material (see the section comment), else (None, None)."""
    try:
        end = time.time() + budget
        stmts = _tpl_stmts(src, ident)
        if not stmts:
            return None, None
        blobs = []
        parts = [[], [], [], []]                       # raw text / perl-unescaped / lua-unescaped / evaluated bytes
        for st in stmts:
            tcl = bool(re.match(r"\s*\[", st)) or "binary " in st or bool(re.search(r"\bset\s+(?:Material|MATERIAL)_"
                                                                                  + re.escape(ident), src))
            lits, words, bare = _tpl_parse(st, tcl)
            fmt = bool(re.search(r"\b(?:un)?pack1?\b|binary\s+format", st))
            body = [(q, b) for q, b in lits if not (fmt and _TPL_FMT.fullmatch(b))]
            raw = "".join(b for _, b in body) + " ".join(words)
            perl = b"".join((_tpl_unescape(b) or b"") if q == '"' else b.encode("latin-1", "ignore") for q, b in body)
            lua = b"".join((_tpl_unescape(b, True) or b"") if q == '"' else b.encode("latin-1", "ignore")
                           for q, b in body)
            ops = _tpl_ops(st)
            ev = []
            for seq in dict.fromkeys((tuple(ops), tuple(reversed(ops)))):
                for start in (perl, lua):
                    cur = [start] if seq[:1] != ("bytes",) else _tpl_numbers(words, lits, bare, st)
                    for op in seq:
                        if op == "bytes":
                            continue
                        cur = [x for x in (_tpl_apply(op, c.decode("latin-1")) for c in cur) if x]
                    ev += cur
                    for op in seq[:1]:                     # a single op of a two-op chain
                        if op != "bytes" and len(seq) > 1:
                            x = _tpl_apply(op, start.decode("latin-1"))
                            ev += [x] if x else []
            for k, v in enumerate((raw.encode("latin-1", "ignore"), perl, lua, b"".join(ev[:1]))):
                parts[k].append(v)
            blobs += ev[1:4]
        texts = [b"".join(p) for p in parts[:3]]
        blobs = [b"".join(parts[3])] + blobs + texts[1:]
        # the inner literal under the declared rep, then the evaluated bytes under the declared transform; names
        # only first (cheap), then decode() with its name-agnostic fallback
        cands = list(dict.fromkeys([(t.decode("latin-1"), rep) for t in texts if t] +
                                   [(b.hex(), "hex_compact") for b in blobs if b]))
        for full in (False, True):
            for m, r in cands:
                if time.time() > end:
                    return None, None
                t2, k2 = _spec(r, tr, key)
                if full:
                    p = decode(m, r, tr, key)
                elif known(r, t2):
                    p = next((o.decode("utf-8").lstrip("\ufeff") for d in _rep_candidates(r, m)
                              for o in _transform_candidates(t2, k2, d) if looks_like_plan(o)), None)
                else:
                    continue
                if p:
                    return p, stmts[0]
    except Exception:  # noqa: BLE001 - unknown -> None, never an exception
        pass
    return None, None


# JScript.Encode / VBScript.Encode (screnc: .jse/.vbe, `language="VBScript.Encode"` in WSF/HTA/SCT/ASP hosts):
# `#@~^<len b64>==<body><checksum b64>==^#~@`. Each body char < 0x80 advances a position i; tab and 0x20-0x7F (bar
# `<` `>` `@`) go through one of 3 permutation tables picked by _WSH_SLOT[i % 64]; `@&` `@#` `@*` `@!` `@$` are \n \r
# > < @. _WSH_ENC[s] lists the slot-s ciphertext of each _WSH_PLAIN char. find_codecs() reads the decoded source
# (blocks substituted in place) when the text carries the marker. Length/checksum are not enforced (lenient).
_WSH_PLAIN = "\t" + "".join(chr(c) for c in range(32, 128) if c not in (60, 62, 64))
_WSH_ENC = (
    '7~ZE:yY\'vcbMQSR &Tq+f*X\x7f{01lIx_)$/93o!u(BFJ\\H6K}]jPi#\tpet,wD?m|C8^[nWL4r%VshUG25.dO;-Aaz"`kN=g',
    'i,er[fuLEv*C3B cJZ8y2Wl+FRO=p{Qz~;GAwV_&xndtg}h5"U:`jqoI\\]\'Y%|#m(19\x7f6T4bN0^s\tKa$MkD!7SXH.P-)?/',
    'dP"Ja^][B`#e_~ORz!F &c*vG%,)i\'gbAZf2sMCq9|SH1rnpI?Kj.\x7f(5}$-T7{=l4mN+0otkL3V:xWw;D/YE\\h6Xy\tu8UQ',
)
_WSH_SLOT = "0120121221210212021200122102122100212120200120210212001220012021"
_WSH_DEC = tuple({e: p for e, p in zip(enc, _WSH_PLAIN)} for enc in _WSH_ENC)
_WSH_ESC = {"&": "\n", "#": "\r", "*": ">", "!": "<", "$": "@"}
_WSH_RE = re.compile(r"#@~\^[A-Za-z0-9+/]{6}==(.*?)[A-Za-z0-9+/]{6}==\^#~@", re.S)


def wsh_decode_block(body):
    """Plain text of one screnc body (between the `#@~^XXXXXX==` header and the `XXXXXX==^#~@` trailer)."""
    out, i, k = [], 0, 0
    while k < len(body):
        c = body[k]
        k += 1
        if c == "@" and k < len(body) and body[k] in _WSH_ESC:
            c = _WSH_ESC[body[k]]
            k += 1
        elif c < "\x80" and c not in "<>@":
            c = _WSH_DEC[int(_WSH_SLOT[i & 63])].get(c, c)
        if c < "\x80":
            i += 1
        out.append(c)
    return "".join(out)


def wsh_decode(src):
    """`src` with every `#@~^..^#~@` encoded block replaced by its plain script, or None when it carries none."""
    try:
        if not isinstance(src, str) or "#@~^" not in src:
            return None
        dec = _WSH_RE.sub(lambda m: wsh_decode_block(m.group(1)), src)
        return dec if dec != src else None
    except Exception:  # noqa: BLE001
        return None


# ------------------------------------------------------------------------------------------------ Dockerfile / Makefile
# Target dockerfile-makefile-route: build hosts read as the build tool would, never run (`make -n` / `docker build`).
# Logical lines join `\`-newline continuations (Dockerfile `# escape=` honoured, comment lines inside an instruction
# dropped; a Makefile `#` comment ending in `\` continues). Variables: Dockerfile `ARG X=..`, `ENV X=.. Y=..`, legacy
# `ENV X value`; Makefile `X (=|:=|::=|:::=|?=|+=|!=) ..` (override/export prefixes) and `define X .. endef`, all with
# `$(X)`/`${X}`/`$X` expanded. Payloads: `echo`/`printf` arguments of RUN / TAB-recipe / `$(shell ..)` / `!=` pipelines
# (`| base64 -d | sh`, `xxd -r -p`, gunzip ...) and RUN heredoc bodies. Each candidate is peeled name-agnostically
# (peel_plan); descriptor variables first, then the continued `#` marker, echo payloads, other variables. Only
# consulted when nothing earlier yielded a plan.
# A Mix project (`mix.exs`, target eex-heex-template-carrier) reads its `aliases:` task strings `"cmd .."` (the
# `--cd`/`--app` options dropped) as the RUN commands: build-time shell execution like a Dockerfile RUN.
_BH_DOCKER = re.compile(r"(?im)^[ \t]*(?:FROM|ARG|ENV|RUN|LABEL)[ \t]+\S")
_BH_MAKE = re.compile(r"(?m)^\t[^\n]*\S|^(?:override[ \t]+|export[ \t]+)*[A-Za-z_][\w.-]*[ \t]*(?:::?=|:::=|\?=|\+=|!=)"
                      r"|^define[ \t]+\w")
_BH_APPEND = re.compile(r"(?im)^[ \t]*(?:(?:override|export)[ \t]+)*(descriptor[_-][\w.-]*)[ \t]*"
                        r"(?:\+=|:{0,3}=[ \t]*\$[({]\1[)}])")
_BH_MK_ASSIGN = re.compile(r"(?:(?:override|export|private)[ \t]+)*(?P<name>[A-Za-z_][\w.-]*)[ \t]*"
                           r"(?P<op>:::=|::=|:=|\?=|\+=|!=|=)[ \t]*(?P<val>.*)\Z", re.S)
_BH_ENV_PAIR = re.compile(r"""(?P<name>[A-Za-z_]\w*)=(?P<val>"(?:[^"\\]|\\.)*"|'[^']*'|(?:[^\s"'\\]|\\.)*)""")
_BH_VAR = re.compile(r"\$(?:\((?P<p>[A-Za-z_][\w.-]*)\)|\{(?P<b>[A-Za-z_][\w.-]*)(?::?[-+](?P<d>[^}]*))?\}|(?P<s>[A-Za-z_]\w*))")
_BH_ECHO = re.compile(r"""(?:^|[\s;&|(`"'\[,])(?:/(?:usr/)?bin/)?(?P<cmd>echo|printf)\b(?P<args>(?:\\.|"[^"]*"|'[^']*'|[^|;&<>)`\n])*)""")
# GNU make text functions a descriptor may be wrapped in (target makefile-v3-carrier-forms), args already literal;
# `$(info|warning|error ..)` text is printed at parse time: a payload like an echo argument
_BH_MKFN = re.compile(r"\$\((?P<f>strip|subst|value|firstword|lastword)[ \t]+(?P<a>[^()$\0]*)\)")
_BH_MKMSG = re.compile(r"\$\((?:info|warning|error)[ \t]+(?P<a>(?:[^()]|\([^()]*\))*)\)")
_BH_MKCOND = re.compile(r"(?m)^(?:ifn?def|ifn?eq)[ \t]+\S[^\n]*\n(?:[^\n]*\n)*?endif\b")
_BH_HEREDOC = re.compile(r"""<<-?[ \t]*(["']?)(?P<tag>[A-Za-z_]\w*)\1[^\n]*\n(?P<body>.*?)\n[ \t]*(?P=tag)[ \t]*(?:\n|$)""", re.S)
_MIX_CMD = re.compile(r"""(?<![\w"'])(?:"cmd[ \t]+(?P<c>(?:[^"\\\r\n]|\\.)+)"|'cmd[ \t]+(?P<c2>(?:[^'\\\r\n]|\\.)+)')""")


def _bh_lines(src, docker):
    """Logical lines: `\\`-newline continuations joined (continuation-line indentation kept as one space)."""
    esc = "\\"
    if docker:
        m = re.match(r"(?:[ \t]*#[ \t]*\w+[ \t]*=[^\n]*\n)*?[ \t]*#[ \t]*escape[ \t]*=[ \t]*([\\`])", src, re.I)
        esc = m.group(1) if m else "\\"
    out, cur = [], None
    for ln in src.split("\n"):
        ln = ln.rstrip("\r")
        if cur is not None:
            if docker and re.match(r"[ \t]*#", ln):                  # comment inside a continued instruction
                continue
            ln = (" " if ln[:1] in " \t" else "") + ln.strip(" \t")
            cur += ln
        else:
            cur = ln
        if cur.endswith(esc) and not cur.endswith(esc * 2):
            cur = cur[:-1]
            continue
        out.append(cur)
        cur = None
    if cur is not None:
        out.append(cur)
    return out


def _bh_expand(s, env, depth=0, mk=False):
    """`$(X)` / `${X}` / `${X:-d}` / `$X` from `env` (unknown -> ''), `$$` -> `$`, `$(shell ..)` left for the caller.
    `mk`: GNU make `$(strip|subst|value|firstword|lastword ..)` evaluated too (innermost first, bounded)."""
    if "$" not in s or depth > 4:
        return s

    def rep(m):
        n = m.group("p") or m.group("b") or m.group("s")
        if n in env:
            return _bh_expand(env[n], env, depth + 1, mk)
        if m.group("s"):
            return m.group(0)                                        # bare `$X`: a shell variable, keep
        return m.group("d") or ""

    def fn(m):
        f, a = m.group("f"), m.group("a")
        if f == "subst":
            p = a.split(",", 2)
            return p[2].replace(p[0], p[1]) if len(p) == 3 and p[0] else (p[-1] if len(p) == 3 else a)
        if f == "value":
            return env.get(a.strip(), "").replace("$$", "\0")
        w = a.split()
        return " ".join(w) if f == "strip" else (w[0] if f == "firstword" else w[-1]) if w else ""
    s = _BH_VAR.sub(rep, s.replace("$$", "\0"))
    for _ in range(6 if mk else 0):
        s2 = _BH_VAR.sub(rep, _BH_MKFN.sub(fn, s))
        if s2 == s:
            break
        s = s2
    return s.replace("\0", "$")


def _bh_shell_calls(s):
    """Bodies of `$(shell ..)` calls (balanced parentheses)."""
    out, i = [], 0
    while len(out) < 16:
        i = s.find("$(shell", i)
        if i < 0:
            break
        d, j = 0, i + 1
        while j < len(s):
            d += {"(": 1, ")": -1}.get(s[j], 0)
            if d == 0:
                break
            j += 1
        out.append(s[i + 7:j])
        i = j
    return out


def _bh_echo_args(cmd):
    """Joined arguments of each echo/printf in a shell command (quotes, option flags, `%s` formats dropped)."""
    out = []
    for m in _BH_ECHO.finditer(cmd):
        a = m.group("args").strip()
        a = re.sub(r"^(?:-[neE]+[ \t]+)+", "", a)
        if m.group("cmd") == "printf":
            a = re.sub(r"""^(["']?)%[bs](?:\\n)?\1[ \t]+""", "", a)
        a = re.sub(r"""["'\\]""", "", a)
        out.append(a)
    return out


def _bh_payloads(cmd, env, mk=False):
    cmd = _bh_expand(cmd, env, mk=mk)
    return [a for a in _bh_echo_args(cmd)] + [m.group("body") for m in _BH_HEREDOC.finditer(cmd)]


def _build_host_codecs(src, budget=0.6):
    """find_codecs entries read from a Dockerfile / Makefile build host (see the section comment)."""
    try:
        if not src or len(src) > (1 << 20):
            return []
        docker = bool(_BH_DOCKER.search(src))
        make = bool(_BH_MAKE.search(src) or _BH_MKCOND.search(src))  # or only indented assignments inside ifdef/ifeq
        mix = not (docker or make) and "Mix.Project" in src
        if not (docker or make or mix):
            return []
        end = time.time() + budget
        env, order, run_cmds, marks, msgs = {}, [], [], [], []
        lines = [] if mix else _bh_lines(src, docker and not make)
        if mix:                                   # mix.exs `aliases:` task strings: `cmd ..` is a build-time shell run
            run_cmds = [re.sub(r"^(?:--(?:cd|app)[ \t]+\S+[ \t]+)+", "", _cl_unescape(m.group("c") or m.group("c2")))
                        for m in _MIX_CMD.finditer(src[:1 << 20])]
        k = 0
        while k < len(lines):
            ln = lines[k]
            k += 1
            st = ln.strip()
            if st.startswith("#"):
                if _ANALYSIS_RE.search(st):
                    marks.append(re.sub(r"\s+", "", st))
                continue
            if make and "$(" in ln and _BH_MKMSG.search(ln):
                msgs.append(ln)
            if ln.startswith("\t"):                                  # make recipe line
                run_cmds.append(ln[1:].lstrip("@-+ \t"))
                continue
            dm = re.match(r"(?i)(ARG|ENV|LABEL)[ \t]+(.*)\Z", st, re.S) if docker else None
            if dm:
                body = dm.group(2)
                pairs = list(_BH_ENV_PAIR.finditer(body))
                if not pairs and dm.group(1).upper() != "ARG":       # legacy `ENV X value`
                    lm = re.match(r"([A-Za-z_]\w*)[ \t]+(.+)", body, re.S)
                    pairs = [(lm.group(1), lm.group(2).strip())] if lm else []
                else:
                    pairs = [(p.group("name"), p.group("val")) for p in pairs]
                for n, v in pairs:
                    if v[:1] in "\"'" and v[-1:] == v[:1] and len(v) > 1:
                        v = v[1:-1].replace("\\" + '"', '"') if v[0] == '"' else v[1:-1]
                    env[n] = _bh_expand(v, env)
                    order.append(n)
                continue
            rm = re.match(r"(?i)(RUN|CMD|ENTRYPOINT)[ \t]+(.*)\Z", st, re.S) if docker else None
            if rm:
                cmd = rm.group(2)
                hm = re.search(r"<<-?[ \t]*([\"']?)([A-Za-z_]\w*)\1", cmd)
                if hm:                                               # RUN <<EOF heredoc: body up to the tag line
                    body = []
                    while k < len(lines) and lines[k].strip() != hm.group(2):
                        body.append(lines[k])
                        k += 1
                    k += 1
                    cmd = cmd + "\n" + "\n".join(body) + "\n" + hm.group(2) + "\n"
                    run_cmds.extend(body)
                run_cmds.append(cmd)
                continue
            if make:
                fm = re.match(r"(?:(?:override|export)[ \t]+)*define[ \t]+([A-Za-z_][\w.-]*)", st)
                if fm:
                    body = []
                    while k < len(lines) and not re.match(r"[ \t]*endef\b", lines[k]):
                        body.append(lines[k])
                        k += 1
                    k += 1
                    env[fm.group(1)] = "\n".join(body)
                    order.append(fm.group(1))
                    continue
                am = _BH_MK_ASSIGN.match(st)
                if am and not re.match(r"[^=]*:[ \t]*[^=:]", st[:am.start("op")]):
                    n, op, v = am.group("name"), am.group("op"), re.sub(r"(?<!\\)[ \t]*#.*$", "", am.group("val"))
                    for sc in _bh_shell_calls(v):
                        run_cmds.append(sc)
                    if op == "!=":
                        run_cmds.append(v)
                        v = ""
                    elif op == "?=" and n in env:
                        continue
                    if op == "+=" and n in env:
                        v = env[n] + " " + v
                    elif op in (":=", "::=", ":::="):
                        v = _bh_expand(v, env, mk=True)
                    env[n] = v
                    order.append(n)
        cands, seen = [], set()

        def add(ident, lit):
            if lit and lit.strip() and (ident, lit) not in seen:
                seen.add((ident, lit))
                cands.append((ident, lit))
        names = list(dict.fromkeys(order))
        for n in names:
            if re.match(r"(?i)descriptor[_-]", n):
                add(re.sub(r"(?i)^descriptor[_-]", "", n), _bh_expand(env[n], env, mk=make))
        for c in run_cmds:
            if re.search(r"(?i)\bdescriptor[_-]", c):
                for a in _bh_payloads(c, env, make):
                    add("run", a)
        for ln in msgs:                                              # `$(info ..)` text, expanded
            for mm in _BH_MKMSG.finditer(ln):
                add("info", _bh_expand(mm.group("a"), env, mk=True).strip())
        for mk in marks:
            am = _ANALYSIS_RE.search(mk)
            plain = peel_plan(am.group("mat"), am.group("tag"), budget=min(0.3, max(0.05, end - time.time())))
            if plain:
                dm = re.search(r"(?i)descriptor[_-](\w+)", src)
                return [{"id": dm.group(1) if dm else "analysis", "rep": "descriptor", "transform": "identity",
                         "key": "", "material": am.group("mat"), "plain": plain}]
        for c in run_cmds:
            for a in _bh_payloads(c, env, make):
                add("run", a)
        for n in names:
            add(n, _bh_expand(env[n], env, mk=make))
        ident, plain = _peel_ext(cands, budget=max(0.05, end - time.time()))
        if plain:
            return [{"id": ident, "rep": "descriptor", "transform": "identity", "key": "",
                     "material": dict(cands).get(ident), "plain": plain}]
        if docker and not make and len(re.findall(r"(?im)^[ \t]*FROM[ \t]+\S", src)) > 1:
            sc = _ds_stage_cands(docker_stages(src))                 # multi-stage: per-stage ARG/ENV scopes
            ident, plain = _peel_ext([c for c in sc if (c[0], c[1]) not in seen],
                                     budget=max(0.05, end + 0.4 - time.time()))
            if plain:
                return [{"id": ident, "rep": "descriptor", "transform": "identity", "key": "",
                         "material": dict(sc).get(ident), "plain": plain, "stage": ident}]
    except Exception:  # noqa: BLE001 - unknown host -> nothing, never an exception
        return []
    return []


# Target dockerfile-multistage-stage-graph: a multi-stage Dockerfile read as BuildKit scopes it (never built).
# docker_stages(text) -> ordered [{index, name, base, platform, parent, args, env, labels, copies_from, runs, onbuild,
# files}]: global `ARG`s before the first FROM feed only FROM lines (`FROM ${BASE} AS x`, `--platform=..`) unless a
# stage re-declares `ARG X`; per-stage `ARG X=..` / `ENV` (legacy `ENV X v` too) expanded in that stage's scope; ENV
# (not ARG) inherited from a parent stage (`FROM <earlier stage> AS y`); `COPY|ADD --from=<stage|index|image>` and
# `RUN --mount=..,from=<stage>` recorded as edges (`stage` = the resolved stage index, None for an external image);
# `ONBUILD <instr>` kept raw; `\`-continuations with `# escape=` (backtick on Windows images); RUN heredocs appended to
# the command, `COPY <<EOF /dst` heredoc bodies kept as `files`. _build_host_codecs() falls back to these per-stage
# scopes (a stage-1 `RUN echo "$A$B" | base64 -d` whose `B` a later stage re-ENVs) when its flat pass found no plan,
# stages that feed the last stage via COPY --from first.
_DS_TOK = re.compile(r"""(?P<name>[A-Za-z_][\w.-]*)(?:=(?P<val>"(?:[^"\\]|\\.)*"|'[^']*'|(?:[^\s"'\\]|\\.|\\)*))?""")
_DS_HD = re.compile(r"""<<-?[ \t]*(["']?)([A-Za-z_]\w*)\1""")


def _ds_unq(v):
    if len(v) > 1 and v[:1] in "\"'" and v[-1:] == v[:1]:
        return v[1:-1].replace('\\"', '"') if v[0] == '"' else v[1:-1]
    return v


def _ds_pairs(body, legacy):
    body = body.strip()
    if legacy and not re.match(r"[A-Za-z_][\w.-]*=", body):           # legacy `ENV X value`
        lm = re.match(r"([A-Za-z_][\w.-]*)[ \t]+(.+)", body, re.S)
        return [(lm.group(1), lm.group(2).strip())] if lm else []
    out, i = [], 0
    while i < len(body) and len(out) < 64:
        if body[i] in " \t\n":
            i += 1
            continue
        m = _DS_TOK.match(body, i)
        if not m or m.end() == i:
            break
        out.append((m.group("name"), None if m.group("val") is None else _ds_unq(m.group("val"))))
        i = m.end()
    return out


def docker_stages(text):
    """Ordered build stages of a Dockerfile text (see the section comment); [] if it has no FROM. Never raises."""
    try:
        if not text or len(text) > (1 << 20) or not re.search(r"(?im)^[ \t]*FROM[ \t]+\S", text):
            return []
        text = text.replace("\r\n", "\n")
        dm = re.match(r"(?:[ \t]*#[ \t]*\w+[ \t]*=[^\n]*\n)+", text)      # parser directives never continue
        if dm:
            text = re.sub(r"(?m)$", " ", dm.group(0)) + text[dm.end():]
        lines = _bh_lines(text, True)
        glob, stages, k = {}, [], 0
        while k < len(lines) and len(stages) < 64:
            st = lines[k].strip()
            k += 1
            if not st or st.startswith("#"):
                continue
            m = re.match(r"(?i)(ONBUILD[ \t]+)?([A-Z]+)(?:[ \t]+(.*))?\Z", st, re.S)
            if not m:
                continue
            onb, ins, rest = m.group(1), m.group(2).upper(), m.group(3) or ""
            hm = _DS_HD.search(rest) if ins in ("RUN", "COPY", "ADD") else None
            body = None
            if hm:                                                   # heredoc: raw lines up to the tag line
                buf = []
                while k < len(lines) and lines[k].strip() != hm.group(2):
                    buf.append(lines[k])
                    k += 1
                k += 1
                body = "\n".join(buf)
            cur = stages[-1] if stages else None
            if ins == "FROM" and not onb:
                fm = re.match(r"((?:--[\w-]+(?:=\S*)?[ \t]+)*)(\S+)(?:[ \t]+AS[ \t]+(\S+))?", rest, re.I)
                if not fm:
                    continue
                pm = re.search(r"--platform=(\S+)", fm.group(1) or "")
                base = _bh_expand(fm.group(2), glob)
                name = _bh_expand(fm.group(3), glob).lower() if fm.group(3) else None
                parent = next((s["index"] for s in stages if s["name"] and s["name"] == base.lower()), None)
                stages.append({"index": len(stages), "name": name, "base": base,
                               "platform": _bh_expand(pm.group(1), glob) if pm else None, "parent": parent,
                               "args": {}, "env": dict(stages[parent]["env"]) if parent is not None else {},
                               "labels": {}, "copies_from": [], "runs": [], "onbuild": [], "files": {}})
                continue
            if onb:
                if cur is not None:
                    cur["onbuild"].append(ins + " " + rest + ("\n" + body if body is not None else ""))
                continue
            if ins == "ARG":
                for n, v in _ds_pairs(rest, False):
                    if cur is None:
                        glob[n] = _bh_expand(v, glob) if v is not None else glob.get(n, "")
                    else:
                        scope = dict(cur["env"], **cur["args"])
                        cur["args"][n] = _bh_expand(v, scope) if v is not None else glob.get(n, "")
                continue
            if cur is None:
                continue
            scope = dict(cur["args"], **cur["env"])
            if ins in ("ENV", "LABEL"):
                for n, v in _ds_pairs(rest, ins == "ENV"):
                    if v is None:
                        continue
                    v = _bh_expand(v, scope)
                    if ins == "ENV":
                        cur["env"][n] = scope[n] = v
                    else:
                        cur["labels"][_ds_unq(n)] = v
                continue
            if ins in ("COPY", "ADD"):
                r = _bh_expand(rest, scope)
                if r.lstrip().startswith("["):
                    parts = re.findall(r'"((?:[^"\\]|\\.)*)"', r)
                else:
                    parts = r.split()
                frm = next((p.split("=", 1)[1] for p in parts if p.lower().startswith("--from=")), None)
                paths = [p for p in parts if not p.startswith("--")]
                if body is not None and paths:
                    cur["files"][paths[-1]] = _bh_expand(body, scope) if not hm.group(1) else body
                if frm is not None:
                    cur["copies_from"].append({"from": frm, "stage": _ds_ref(stages, frm), "kind": ins.lower(),
                                               "src": paths[:-1], "dst": paths[-1] if paths else None})
                continue
            if ins in ("RUN", "CMD", "ENTRYPOINT"):
                cmd = rest
                for mm in re.finditer(r"--mount=(\S+)", rest):
                    opts = dict(o.split("=", 1) for o in mm.group(1).split(",") if "=" in o)
                    if opts.get("from"):
                        cur["copies_from"].append({"from": opts["from"], "stage": _ds_ref(stages, opts["from"]),
                                                   "kind": "mount", "src": [opts.get("source", "/")],
                                                   "dst": opts.get("target") or opts.get("dst")})
                cmd = re.sub(r"^(?:--[\w-]+(?:=\S*)?[ \t]+)+", "", cmd)
                if body is not None:
                    cmd += "\n" + body + "\n" + hm.group(2)
                if ins == "RUN":
                    cur["runs"].append(_bh_expand(cmd, scope))
        return stages
    except Exception:  # noqa: BLE001
        return []


def _ds_ref(stages, ref):
    """Stage index a `--from=` reference resolves to (name or earlier index), None for an external image."""
    r = (ref or "").lower()
    if r.isdigit():
        return int(r) if int(r) < len(stages) else None
    return next((s["index"] for s in stages if s["name"] == r), None)


def _ds_stage_cands(stages):
    """(ident, literal) candidates per stage scope, stages copied into the last stage (transitively) first."""
    if not stages:
        return []
    want, todo = [], [len(stages) - 1]
    while todo and len(want) < 64:
        i = todo.pop(0)
        for c in stages[i]["copies_from"]:
            if c["stage"] is not None and c["stage"] not in want and c["stage"] != len(stages) - 1:
                want.append(c["stage"])
                todo.append(c["stage"])
        if stages[i]["parent"] is not None and stages[i]["parent"] not in want:
            want.append(stages[i]["parent"])
            todo.append(stages[i]["parent"])
    order = want + [i for i in range(len(stages)) if i not in want]
    out = []
    for i in order:
        s, sid = stages[i], stages[i]["name"] or str(i)
        for cmd in s["runs"] + [o.split(None, 1)[-1] for o in s["onbuild"] if o.upper().startswith("RUN")]:
            for a in _bh_echo_args(cmd) + [m.group("body") for m in _BH_HEREDOC.finditer(cmd)]:
                out.append((sid, a))
        out += [(sid, v) for v in s["files"].values()]
        out += [(sid, v) for v in list(s["env"].values()) + list(s["args"].values()) + list(s["labels"].values())]
    return out


# Build / infra wrapper hosts (target build-file-host-profiles): docker-compose / Taskfile YAML, CMake, justfile and
# package.json scripts wrapping an earlier language, read as the tool would evaluate them -- never run. Variables:
# compose `environment:` / `args:` maps and `- K=V` lists with `${X:-default}` / `$${X}` (`$$` -> `$`), Taskfile `vars:`
# with `{{.X}}`; CMake `set()` / `string(APPEND|PREPEND|CONCAT|JOIN|REPLACE|STRIP)` / `list(APPEND|JOIN)` with `${X}`
# (quoted / bracket / unquoted arguments, `;` lists); justfile `x := 'a' + y` with `{{x}}`; package.json strings as
# `npm_package_<path>` (`$x` / `${x}` / `%x%`). Payloads are the echo / printf arguments of `command:` / `entrypoint:` /
# `cmds:` / recipe / `COMMAND` / script strings plus every variable (descriptor-named first) and JSON string, peeled
# name-agnostically (peel_plan). A YAML scalar is read as text only (no `on:` -> True). find_codecs() uses it for a gap
# or a full plan ahead of a piece reading it extends.
_BW_COMPOSE = re.compile(r"(?m)^(?:services|x-[\w-]+)[ \t]*:[ \t]*(?:&[\w-]+[ \t]*)?$")
_BW_TASK = re.compile(r"(?m)^tasks[ \t]*:[ \t]*$")
_BW_CMAKE = re.compile(r"(?im)^[ \t]*(?:cmake_minimum_required|project|execute_process|add_custom_(?:command|target)|"
                       r"include|message)[ \t]*\(")
_BW_JUST = re.compile(r"(?m)^(?:export[ \t]+)?[A-Za-z_][\w-]*[ \t]*:=[ \t]*\S")
_BW_YKEY = re.compile(r"""(?P<i>[ \t]*)(?P<d>-[ \t]+)?(?P<k>"[^"]*"|'[^']*'|[^\s:#'"\[\]{}&*!|>-][^:#\n]*?)[ \t]*:"""
                      r"""(?:[ \t]+(?P<v>.*))?\Z""")
_BW_REF = re.compile(r"\$\$?\{(?P<b>[A-Za-z_]\w*)(?::?-(?P<d>[^}]*))?\}|\$\$?(?P<s>[A-Za-z_]\w*)|\$\$|"
                     r"\{\{-?[ \t]*\.?(?P<t>[A-Za-z_][\w-]*)[ \t]*-?\}\}|%(?P<p>npm_[A-Za-z_]\w*)%")


def _bw_kind(src):
    if src.lstrip("\ufeff \t\r\n")[:1] == "{" and re.search(r'"(?:scripts|config)"[ \t]*:', src):
        return "npm"
    if _BW_COMPOSE.search(src) or (_BW_TASK.search(src) and re.search(r"(?m)^[ \t]+cmds[ \t]*:", src)):
        return "yaml"
    if _BW_CMAKE.search(src) and re.search(r"(?im)^[ \t]*(?:set|string|list|execute_process|file)[ \t]*\(", src):
        return "cmake"
    if _BW_JUST.search(src) and re.search(r"(?m)^[A-Za-z_@][\w-]*(?:[ \t]+[^:\n=]*)?:(?!=)[^\n]*\n(?:[ \t]+[^\n]*\n?)+", src):
        return "just"
    return None


def _bw_expand(s, env, skip=(), depth=0):
    """Expand compose / shell / Taskfile / just / npm references from `env`; unknown -> default or kept as written."""
    if depth > 4 or not s or not any(c in s for c in "${%"):
        return s

    def rep(m):
        if m.group(0) == "$$":
            return "$"
        n = m.group("b") or m.group("s") or m.group("t") or m.group("p")
        if n in env and n not in skip:
            return _bw_expand(env[n], env, tuple(skip) + (n,), depth + 1)
        if m.group("d") is not None:
            return _bw_expand(m.group("d"), env, skip, depth + 1)
        return m.group(0)
    return _BW_REF.sub(rep, s)


def _bw_yaml_scalar(v):
    """A YAML flow scalar as text: quotes removed (double: escapes; single: `''`), trailing comment dropped."""
    import json
    v = v.strip()
    if v[:1] == '"':
        m = re.match(r'"((?:[^"\\]|\\.)*)"', v, re.S)
        if m:
            try:
                return json.loads('"' + re.sub(r"\\(?![\"\\/bfnrtu])", r"\\\\", m.group(1).replace("\n", " ")) + '"')
            except ValueError:
                return m.group(1)
    if v[:1] == "'":
        m = re.match(r"'((?:[^']|'')*)'", v, re.S)
        if m:
            return m.group(1).replace("''", "'")
    return re.sub(r"[ \t]+#.*$", "", v)


def _bw_yaml(src, env, runs):
    """Minimal YAML reader: `key: scalar`, block scalars (`|` / `>` with chomping), multi-line plain / quoted scalars,
    `- K=V` / `- scalar` items and flow sequences; leaf key -> env, every scalar -> runs."""
    import json
    lines = src.split("\n")[:20000]
    i = 0
    while i < len(lines):
        ln = lines[i].rstrip("\r")
        i += 1
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        ind = len(ln) - len(ln.lstrip(" "))
        m = _BW_YKEY.match(ln)
        key, val = (m.group("k").strip("\"'"), m.group("v") or "") if m else (None, None)
        if m is None:
            im = re.match(r"[ \t]*-[ \t]+(.*)\Z", ln)
            if not im:
                continue
            val = im.group(1)
        val = re.sub(r"^(?:[&!][\w!-]*[ \t]*)+", "", val.strip())
        if val[:1] and val[0] in "|>":                               # block scalar
            body, bi = [], None
            while i < len(lines):
                b = lines[i].rstrip("\r")
                if b.strip():
                    bind = len(b) - len(b.lstrip(" "))
                    if bind <= ind:
                        break
                    bi = bind if bi is None else bi
                    body.append(b[min(bi, bind):])
                else:
                    body.append("")
                i += 1
            text = "\n".join(body).strip("\n") if val[0] == "|" else re.sub(r"[ \t]*\n[ \t]*", " ", "\n".join(body).strip())
        else:
            if val[:1] and val[0] in "\"'" and not re.match(r"""("(?:[^"\\]|\\.)*"|'(?:[^']|'')*')""", val, re.S):
                while i < len(lines) and not re.match(r"""("(?:[^"\\]|\\.)*"|'(?:[^']|'')*')""", val, re.S):
                    val += " " + lines[i].strip()
                    i += 1
            elif val and val[:1] not in "[{\"'":
                while i < len(lines) and lines[i].strip() and not lines[i].lstrip().startswith(("#", "- ")) and \
                        len(lines[i]) - len(lines[i].lstrip(" ")) > ind and not _BW_YKEY.match(lines[i].rstrip("\r")):
                    val += " " + lines[i].strip()
                    i += 1
            if val[:1] == "[":                                       # flow sequence: items joined like an argv
                try:
                    items = json.loads(re.sub(r"[ \t]+#.*$", "", val))
                    text = " ".join(str(x) for x in items) if isinstance(items, list) else val
                except ValueError:
                    text = " ".join(_bw_yaml_scalar(x) for x in val.strip("[] ").split(","))
            else:
                text = _bw_yaml_scalar(val)
        if not text:
            continue
        if key is None or (m and m.group("d") and "=" in key):
            kv = re.match(r"([A-Za-z_]\w*)=(.*)\Z", text if key is None else ln.split("-", 1)[1].strip(), re.S)
            if kv:
                env[kv.group(1)] = _bw_yaml_scalar(kv.group(2))
                continue
        if key:
            env[key] = text
        runs.append(text)


def _bw_cmake_args(body):
    """CMake arguments of one command: (value, kind) with kind 'q' quoted, 'b' bracket, 'u' unquoted."""
    out, i, n = [], 0, len(body)
    while i < n:
        c = body[i]
        if c in " \t\r\n":
            i += 1
        elif c == "#":
            bm = re.match(r"#\[(=*)\[", body[i:])
            if bm:
                j = body.find("]" + bm.group(1) + "]", i)
                i = n if j < 0 else j + len(bm.group(1)) + 2
            else:
                j = body.find("\n", i)
                i = n if j < 0 else j
        elif c == '"':
            j, buf = i + 1, []
            while j < n and body[j] != '"':
                if body[j] == "\\" and j + 1 < n:
                    e = body[j + 1]
                    buf.append({"n": "\n", "t": "\t", "r": "\r", "\n": ""}.get(e, e))
                    j += 2
                else:
                    buf.append(body[j])
                    j += 1
            out.append(("".join(buf), "q"))
            i = j + 1
        elif c == "[" and re.match(r"\[(=*)\[", body[i:]):
            eq = re.match(r"\[(=*)\[", body[i:]).group(1)
            j = body.find("]" + eq + "]", i)
            j = n if j < 0 else j
            v = body[i + len(eq) + 2:j]
            out.append((v[1:] if v[:1] == "\n" else v, "b"))
            i = j + len(eq) + 2
        else:
            m = re.match(r"""(?:\\.|[^\s()#"\\]|\([^()]*\))+""", body[i:], re.S)
            if not m:
                i += 1
                continue
            out.append((re.sub(r"\\(.)", r"\1", m.group(0)), "u"))
            i += m.end()
    return out


def _bw_cmake(src, env, runs):
    """Evaluate the CMake variable commands in source order (set / string / list / file / execute_process ...)."""
    i, n, cnt = 0, len(src), 0
    cmd_re = re.compile(r"(?m)(?:^|(?<=[\s;)]))([A-Za-z_]\w*)[ \t]*\(")
    while i < n and cnt < 5000:
        cnt += 1
        if src[i] == "#":                                            # line / bracket comment
            bm = re.match(r"#\[(=*)\[", src[i:i + 40])
            j = src.find("]" + bm.group(1) + "]", i) if bm else src.find("\n", i)
            i = n if j < 0 else j + 1
            continue
        m = cmd_re.match(src, i) if (i == 0 or src[i - 1] in "\n \t;)") else None
        if not m:
            i += 1
            continue
        j, d, q = m.end(), 1, False                                  # matching `)` outside quotes / brackets
        while j < n and d:
            c = src[j]
            if q:
                if c == "\\":
                    j += 1
                elif c == '"':
                    q = False
            elif c == '"':
                q = True
            elif c == "[" and re.match(r"\[(=*)\[", src[j:j + 40]):
                eq = re.match(r"\[(=*)\[", src[j:j + 40]).group(1)
                k = src.find("]" + eq + "]", j)
                j = n if k < 0 else k + len(eq) + 1
            elif c == "#":
                k = src.find("\n", j)
                j = n if k < 0 else k
                continue
            else:
                d += {"(": 1, ")": -1}.get(c, 0)
            j += 1
        name, raw = m.group(1).lower(), src[m.end():j - 1]
        i = j
        args = [(v if k == "b" else _bw_expand(re.sub(r"\$ENV\{", "${", v), env), k)
                for v, k in _bw_cmake_args(raw)]
        a = [v for v, _ in args]
        if name == "set" and a:
            vals = a[1:]
            for kw in ("CACHE", "PARENT_SCOPE"):
                if kw in vals:
                    vals = vals[:vals.index(kw)]
            env[a[0]] = ";".join(vals)
        elif name == "string" and len(a) >= 2:
            op = a[0].upper()
            if op in ("APPEND", "PREPEND", "CONCAT") and len(a) >= 2:
                s = "".join(a[2:])
                env[a[1]] = (env.get(a[1], "") + s if op == "APPEND" else s + env.get(a[1], "") if op == "PREPEND" else s)
            elif op == "JOIN" and len(a) >= 3:
                env[a[2]] = a[1].join(a[3:])
            elif op == "REPLACE" and len(a) >= 4:
                env[a[3]] = "".join(a[4:]).replace(a[1], a[2]) if a[1] else "".join(a[4:])
            elif op == "STRIP" and len(a) >= 3:
                env[a[2]] = a[1].strip()
            elif op == "REGEX" and len(a) >= 6 and a[1].upper() == "REPLACE":
                try:
                    env[a[4]] = re.sub(a[2], re.sub(r"\\(\d)", r"\\\1", a[3]), "".join(a[5:]))
                except (re.error, IndexError):
                    env[a[4]] = "".join(a[5:])
        elif name == "list" and len(a) >= 2:
            op = a[0].upper()
            if op == "APPEND":
                env[a[1]] = ";".join([x for x in [env.get(a[1], "")] if x] + a[2:])
            elif op == "JOIN" and len(a) >= 4:
                env[a[3]] = a[2].join(env.get(a[1], "").split(";"))
        elif name in ("execute_process", "add_custom_command", "add_custom_target", "file", "message",
                      "configure_file", "install"):
            runs.append(" ".join(a))
            if name in ("file", "message"):
                runs.extend(a[1:] if name == "file" else a)


def _bw_just(src, env, runs):
    """justfile `[export] x := 'a' + "b" + y` (adjacent `/` = path join) assignments and recipe bodies."""
    import json
    tok = re.compile(r"""[ \t]*(?:'''(?P<t1>.*?)'''|\"\"\"(?P<t2>.*?)\"\"\"|'(?P<s>[^']*)'|"(?P<d>(?:[^"\\]|\\.)*)"|"""
                     r"""(?P<id>[A-Za-z_][\w-]*)|(?P<op>[+/]))""", re.S)
    for m in re.finditer(r"(?m)^(?:export[ \t]+)?([A-Za-z_][\w-]*)[ \t]*:=[ \t]*((?:[^\n]|\\\n)*)", src):
        parts, pos, expr, op = [], 0, m.group(2), "+"
        while pos < len(expr):
            t = tok.match(expr, pos)
            if not t or t.end() == pos:
                break
            pos = t.end()
            if t.group("op"):
                op = t.group("op")
                continue
            if t.group("d") is not None:
                v = t.group("d")
                try:
                    v = json.loads('"' + re.sub(r"\\(?![\"\\nrt])", r"\\\\", v) + '"')
                except ValueError:
                    pass
            elif t.group("id"):
                v = env.get(t.group("id"), "")
            else:
                v = next(g for g in (t.group("t1"), t.group("t2"), t.group("s")) if g is not None)
            parts.append(("/" if op == "/" and parts else "") + v)
        env[m.group(1)] = "".join(parts)
    for m in re.finditer(r"(?m)^[ \t]+(\S[^\n]*)", src):
        runs.append(m.group(1).lstrip("@-"))


def _bw_npm(src, env, runs):
    import json
    try:
        doc = json.loads(src.lstrip("\ufeff"))
    except ValueError:
        return

    def walk(o, path, depth=0):
        if depth > 12:
            return
        if isinstance(o, dict):
            for k, v in o.items():
                walk(v, path + [str(k)], depth + 1)
        elif isinstance(o, list):
            for k, v in enumerate(o):
                walk(v, path + [str(k)], depth + 1)
        elif isinstance(o, str):
            env[re.sub(r"\W", "_", "npm_package_" + "_".join(path))] = o
            runs.append(o)
    walk(doc, [])


def _build_wrap_codecs(src, budget=0.4):
    """find_codecs entries read from a compose / Taskfile / CMake / justfile / package.json wrapper (section above)."""
    try:
        if not isinstance(src, str) or not src or len(src) > (1 << 20):
            return []
        kind = _bw_kind(src)
        if not kind:
            return []
        end = time.time() + budget
        env, runs = {}, []
        {"npm": _bw_npm, "yaml": _bw_yaml, "cmake": _bw_cmake, "just": _bw_just}[kind](src, env, runs)
        cands, seen = [], set()

        def add(ident, lit):
            if lit and lit.strip() and len(lit) < (1 << 18) and (ident, lit) not in seen and len(cands) < 400:
                seen.add((ident, lit))
                cands.append((ident, lit))
                if kind == "cmake" and ";" in lit:
                    cands.append((ident, lit.replace(";", "")))
        val = {k: _bw_expand(v, env, (k,)) for k, v in list(env.items())[:2000]}
        for k, v in val.items():
            if re.search(r"(?i)descriptor", k):
                add(re.sub(r"(?i)^.*?descriptor[_-]?", "", k) or k, v)
        for r in runs[:2000]:
            x = _bw_expand(r, val)
            for a in _bh_echo_args(x) + [hm.group("body") for hm in _BH_HEREDOC.finditer(x)]:
                add("run", a)
        for k, v in val.items():
            add(k, v)
        best, tried = None, set()                                    # the longest plan: a piece reads as a prefix
        for ident, lit in cands:
            for cand in (re.sub(r"\s+", "", lit), lit.strip()):
                if not cand or cand in tried or time.time() > end:
                    continue
                tried.add(cand)
                plain = peel_plan(cand, budget=min(0.3, max(0.05, end - time.time())))
                if plain and (best is None or len(plain) > len(best[2])):
                    best = (ident, lit, plain)
        if best:
            return [{"id": best[0], "rep": "descriptor", "transform": "identity", "key": "", "material": best[1],
                     "plain": best[2]}]
    except Exception:  # noqa: BLE001 - unknown wrapper -> nothing, never an exception
        return []
    return []


# Variable interpolation / concatenation fold (target var-interpolation-concat-fold): a descriptor split over several
# build / shell variables and joined at the use site -- Dockerfile `ARG A=..` `LABEL d=${A}${B}` / `${A:-x}`, Makefile
# `D := $(A)$(B)` / `+=` / `$(subst|strip ..)`, HCL `"${local.a}${local.b}"` / `join("", [..])`, bash / zsh `d=${a}${b}`
# / `d+=..`, fish `set d $a$b` / `set -a`, Tcl `set d "$a$b"` / `append`, awk `d = a b`, Kotlin / Swift `"${a}$b"` /
# `"\(a)"`. Only literal assignments and references are folded (depth <= 4): a command substitution / function call
# leaves the value unresolved. find_codecs() uses it for a gap, or the full plan ahead of a piece reading it extends.
_VIF_CUE = re.compile(r"\$\{?[A-Za-z_]|\$\([A-Za-z_][\w.-]*\)|\\\([A-Za-z_]\w*\)|\bappend[ \t]|\+=|\bjoin\(|"
                      r"(?:^|[;{])[ \t]*[A-Za-z_]\w*[ \t]*=[ \t]*[A-Za-z_]\w*[ \t]+[A-Za-z_\"]", re.M)
_VIF_REF = re.compile(r"\$\$|\$\{(?P<b>[A-Za-z_][\w.]*)(?::?-(?P<d>[^}]*))?\}|\$\((?P<f>subst|strip)[ \t]+(?P<a>[^()$]*)\)"
                      r"|\$\((?P<p>[A-Za-z_][\w.-]*)\)|\$(?P<s>[A-Za-z_]\w*)|\\\((?P<w>[A-Za-z_][\w.]*)\)|\$\(|`")
_VIF_DECL = re.compile(r"(?:(?:export|local|typeset|declare|readonly|override|private|public|internal|static|lazy|"
                       r"final|const|val|var|let|my|our|global)[ \t]+(?:-[A-Za-z]+[ \t]+)*)*"
                       r"(?P<n>[A-Za-z_][\w.]*)(?:[ \t]*:[ \t]*[\w.<>?]+)?[ \t]*(?P<op>:::=|::=|:=|\?=|\+=|=)(?!=)[ \t]*(?P<v>.*)\Z", re.S)
_VIF_SET = re.compile(r"(?P<c>set|append|lappend)[ \t]+(?P<fl>(?:-{1,2}[A-Za-z]+[ \t]+)*)(?P<n>[A-Za-z_]\w*)(?:[ \t]+(?P<v>.*))?\Z", re.S)
_VIF_MKVAR = re.compile(r"\$[({]([A-Za-z_][\w.-]*)[)}]")
_VIF_LIT = re.compile(r""""((?:[^"\\]|\\.)*)"|'([^']*)'""", re.S)


def _vif_lang(src, hint):
    h = (hint or "").lower()
    if h:
        return {"dockerfile": "docker", "makefile": "make", "terraform": "hcl", "zsh": "sh", "bash": "sh", "kts": "kt",
                "kotlin": "kt", "swift": "kt", "gawk": "awk"}.get(h, h)
    if re.search(r"(?im)^[ \t]*FROM[ \t]+\S", src) and _BH_DOCKER.search(src):
        return "docker"
    if re.search(r"(?m)^[ \t]*(?:locals|variable[ \t]+\"[\w-]+\"|resource[ \t]+\"|output[ \t]+\"[\w-]+\")[ \t]*\{", src):
        return "hcl"
    if re.search(r"^#!.*\b[gm]?awk\b|^[ \t]*BEGIN[ \t]*\{", src, re.M):
        return "awk"
    if re.search(r"^#!.*\bfish\b|^[ \t]*set[ \t]+-[gxlUa]+[ \t]|^[ \t]*end[ \t]*$", src, re.M):
        return "fish"
    if re.search(r"^#!.*\btclsh\b|^[ \t]*(?:puts|proc)[ \t]|^[ \t]*set[ \t]+\w+[ \t]+[\"{]", src, re.M):
        return "tcl"
    if re.search(r"(?m)^[ \t]*(?:val|let|var|const[ \t]+val|fun|func|import)[ \t]+\w", src):
        return "kt"
    if re.search(r"(?m)^[A-Za-z_][\w.-]*[ \t]*(?:::?=|\?=)|^\t\S|^[\w./-]+[ \t]*:(?!=)", src):
        return "make"
    return "sh"


def _vif_stmts(src, lang):
    """Logical statements (`\\`-continuations joined, `;` split outside quotes / braces), HCL block names attached."""
    lines = _bh_lines(src, lang == "docker") if lang in ("docker", "make", "sh", "fish", "tcl") else src.split("\n")
    out, blk = [], []
    for ln in lines:
        st = ln.strip().rstrip("\r")
        if lang == "hcl":
            m = re.match(r"(locals|variable[ \t]+\"([\w-]+)\")[ \t]*\{[ \t]*$", st)
            if m:
                blk.append("local" if m.group(1) == "locals" else "var:" + m.group(2))
                continue
            if st.endswith("{"):
                blk.append("")
                continue
            if st.startswith("}") and blk:
                blk.pop()
                continue
            out.append((blk[-1] if blk else "", st))
            continue
        cur, q, d = "", "", 0
        for ch in st:
            if q:
                q = "" if ch == q and not cur.endswith("\\") else q
            elif ch in "\"'" and lang != "make":
                q = ch
            elif ch == "{" and (lang == "tcl" or cur.endswith("$")):
                d += 1
            elif ch == "}" and d:
                d -= 1
            elif ch in "{}" and lang in ("awk", "kt", "sh"):          # block braces: statement separators
                out.append(("", cur.strip()))
                cur = ""
                continue
            elif ch == ";" and not d and lang != "make":
                out.append(("", cur.strip()))
                cur = ""
                continue
            cur += ch
        out.append(("", cur.strip()))
    return out


def _vif_interp(s, env, lang, used, depth):
    """`s` with `$X` / `${X}` / `${X:-d}` / `$(X)` / `\\(X)` / make `$(subst|strip ..)` folded, or None (unresolved)."""
    bad = []
    if lang == "make" and depth == 0:                              # innermost first: `$(subst .,,$(A).$(B))`
        s = s.replace("$$", "\0")
        for _ in range(6):
            s2 = _VIF_MKVAR.sub(lambda m: (used.append(m.group(1)) or env[m.group(1)].replace("$$", "\0"))
                                if m.group(1) in env else m.group(0), s)
            s2 = _VIF_REF.sub(lambda m: _vif_interp(m.group(0), env, lang, used, 1) or m.group(0)
                              if m.group("f") else m.group(0), s2)
            if s2 == s:
                break
            s = s2
        return None if re.search(r"\$[({]|\$[A-Za-z_]", s) else s.replace("\0", "$")

    def rep(m):
        g = m.group(0)
        if g == "$$":
            return "$" if lang == "make" else g
        if g in ("$(", "`"):
            bad.append(g)
            return ""
        if m.group("f"):
            a = _vif_interp(m.group("a"), env, lang, used, depth + 1) if lang == "make" else None
            if a is None:
                bad.append(g)
                return ""
            if m.group("f") == "strip":
                return " ".join(a.split())
            p = a.split(",", 2)
            return p[2].replace(p[0], p[1]) if len(p) == 3 and p[0] else a
        n = m.group("b") or m.group("p") or m.group("s") or m.group("w")
        if m.group("p") and lang != "make":
            bad.append(g)                                            # shell `$(cmd)`: never evaluated
            return ""
        if m.group("w") and lang != "kt":
            return g
        if n in env:
            used.append(n)
            return env[n]
        if m.group("d") is not None:
            used.append(n)
            return m.group("d")
        if lang == "kt" and m.group("s") and not s[m.end():m.end() + 1].isalnum():
            return g if depth else (bad.append(g) or "")
        bad.append(g)
        return ""
    out = _VIF_REF.sub(rep, s)
    return None if bad else out


def _vif_unq(body):
    return re.sub(r"\\([\"\\$`])", r"\1", body)


def _vif_eval(rhs, env, lang, used):
    """A right-hand side: quoted / bare pieces concatenated (fish / make args keep their spaces), or None."""
    rhs = rhs.strip()
    if lang in ("make", "docker"):
        if lang == "make":
            rhs = re.sub(r"(?<!\\)[ \t]*#.*$", "", rhs)
        elif rhs[:1] in "\"'" and rhs[-1:] == rhs[:1] and len(rhs) > 1:
            rhs = _vif_unq(rhs[1:-1]) if rhs[0] == '"' else rhs[1:-1]
            return rhs if "$" not in rhs or rhs.startswith("'") else _vif_interp(rhs, env, lang, used, 0)
        return _vif_interp(rhs, env, lang, used, 0)
    m = re.match(r"join\(\s*(\"[^\"]*\"|'[^']*')\s*,\s*\[(.*)\]\s*\)\s*[,;]?\Z", rhs, re.S)
    if m:                                                            # HCL / JS `join("", [a, "b"])`
        parts = [_vif_eval(p, env, lang, used) for p in re.split(r"\s*,\s*", m.group(2).strip().rstrip(","))]
        return None if None in parts else m.group(1)[1:-1].join(parts)
    out, i, n, sep = [], 0, len(rhs), lang in ("fish", "tcl_args")
    while i < n:
        c = rhs[i]
        if c in " \t":
            if lang == "sh":                                         # `local a="$x" b`: the word ends the value
                break
            while i < n and rhs[i] in " \t":
                i += 1
            if sep and out and i < n and rhs[i] != "#":
                out.append(" ")
            continue
        if c == "#" and lang in ("sh", "fish", "tcl", "tcl_args", "awk", "hcl"):
            break
        if rhs.startswith("//", i) and lang in ("kt", "hcl"):
            break
        if c == '"':
            m = re.compile(r'"((?:[^"\\]|\\.)*)"', re.S).match(rhs, i)
            if not m:
                return None
            body = m.group(1)
            if lang == "kt":
                body = re.sub(r"\\([\"\\$])", r"\1", body.replace("\\$", "\0")).replace("\0", "\\$")
                v = _vif_interp(body, env, lang, used, 0)
                v = v.replace("\\$", "$") if v is not None else None
            else:
                v = _vif_interp(body, env, lang, used, 0)
                v = _vif_unq(v) if v is not None else None
            if v is None:
                return None
            out.append(v)
            i = m.end()
            continue
        if c == "'" and lang not in ("kt", "tcl", "tcl_args"):
            j = rhs.find("'", i + 1)
            if j < 0:
                return None
            out.append(rhs[i + 1:j])
            i = j + 1
            continue
        if c == "{" and lang in ("tcl", "tcl_args"):
            d, j = 0, i
            while j < n:
                d += {"{": 1, "}": -1}.get(rhs[j], 0)
                if d == 0:
                    break
                j += 1
            out.append(rhs[i + 1:j])
            i = j + 1
            continue
        if c in "+&" or rhs.startswith("..", i) or (c in ".," and lang in ("awk", "kt", "hcl")):
            i += 2 if rhs.startswith("..", i) else 1
            continue
        if c in ";" :
            break
        m = re.compile(r"[^\s\"'+&;#]+").match(rhs, i)
        if not m:
            return None
        w = m.group(0)
        i = m.end()
        if lang in ("awk", "kt", "hcl"):
            if w in env:
                used.append(w)
                out.append(env[w])
            elif re.fullmatch(r"\d+", w):
                out.append(w)
            else:
                return None
        else:
            v = _vif_interp(w, env, lang, used, 0)
            if v is None:
                return None
            out.append(v.replace("\\", "") if lang == "sh" else v)
    return "".join(out)


def fold_interpolation(text, lang_hint=None):
    """Folded values (>= 40 chars) of variables / use-site strings assembled from other variables by interpolation or
    concatenation (see the section comment); descriptor-named ones first. Never raises."""
    try:
        if not isinstance(text, str):
            text = (text or b"").decode("utf-8", "ignore")
        if not text or len(text) > (1 << 20):
            return []
        lang = _vif_lang(text, lang_hint)
        stmts = _vif_stmts(text, lang)[:20000]
        prev, env, folded = {}, {}, {}
        for _ in range(4):                     # forward references (make `=`, HCL) resolve over repeated passes
            env, folded, uses = {}, {}, []
            look = _VifEnv(env, prev)
            for blk, st in stmts:
                if not st or st.startswith("#") or st.startswith("//"):
                    continue
                pairs = []
                if lang == "docker":
                    dm = re.match(r"(?i)(ARG|ENV|LABEL)[ \t]+(.*)\Z", st, re.S)
                    if dm:
                        ps = list(_BH_ENV_PAIR.finditer(dm.group(2)))
                        if ps:
                            pairs = [(p.group("name"), "=", p.group("val")) for p in ps]
                        elif dm.group(1).upper() == "ENV":
                            lm = re.match(r"([A-Za-z_]\w*)[ \t]+(.+)", dm.group(2), re.S)
                            pairs = [(lm.group(1), "=", lm.group(2).strip())] if lm else []
                    elif not re.match(r"(?i)(FROM|RUN|CMD|ENTRYPOINT|COPY|ADD|WORKDIR|USER|SHELL|EXPOSE)\b", st):
                        continue
                    else:
                        uses.append(st)
                        continue
                elif lang in ("fish", "tcl") and _VIF_SET.match(st):
                    sm = _VIF_SET.match(st)
                    c, fl, v = sm.group("c"), sm.group("fl"), sm.group("v")
                    if v is None:
                        continue
                    op = "+=" if c != "set" or re.search(r"-\w*a\b|--append", fl) else "="
                    pairs = [(sm.group("n"), op + ("s" if c != "append" else ""), v)]
                else:
                    am = _VIF_DECL.match(st)
                    if not am:
                        uses.append(st)
                        continue
                    nm = am.group("n")
                    if lang == "hcl" and blk:
                        if blk == "local":
                            nm = "local." + nm
                        elif nm == "default":
                            nm = "var." + blk[4:]
                        else:
                            continue
                    pairs = [(nm, am.group("op"), am.group("v"))]
                for nm, op, v in pairs:
                    used = []
                    if op.startswith("+=") and lang == "fish" or op == "+=s":
                        lg = "fish" if lang == "fish" else "tcl_args"
                    elif lang == "tcl" and op == "+=":
                        lg = "tcl_args"
                    else:
                        lg = lang
                    if op == "?=" and nm in env:
                        continue
                    val = _vif_eval(v, look, lg, used)
                    if lg == "tcl_args" and val is not None and op == "+=":
                        val = val.replace(" ", "") if lang == "tcl" and not op.endswith("s") else val
                    if val is None:
                        continue
                    if op.startswith("+=") and nm in env:
                        sep = " " if lang == "make" or op.endswith("s") or lang == "fish" else ""
                        val = env[nm] + sep + val
                        used.append(nm)
                    if op == "+=" and lang == "kt" and nm not in env:
                        continue
                    env[nm] = val
                    if used:
                        folded[nm] = val
                    else:
                        folded.pop(nm, None)
            if env == prev:
                break
            prev = dict(env)
        out = [v for k, v in sorted(folded.items(), key=lambda kv: not re.search(r"(?i)descriptor", kv[0]))]
        look = _VifEnv(env, {})
        for st in [u for u in uses if "$" in u or "\\(" in u][:256]:   # use-site strings: `echo "$a$b"`, `"${a}${b}"`
            for m in _VIF_LIT.finditer(st):
                if m.group(1) is not None and len(_VIF_REF.findall(m.group(1))) >= 2:
                    used = []
                    v = _vif_interp(m.group(1), look, "kt" if lang == "kt" else lang, used, 0)
                    if v is not None and used:
                        out.append(v)
        seen = set()
        return [v for v in out if len(v.strip()) >= 40 and not (v in seen or seen.add(v))]
    except Exception:  # noqa: BLE001 - unreadable input -> nothing
        return []


class _VifEnv(dict):
    """Current-pass variables, falling back to the previous pass (forward references)."""

    def __init__(self, cur, prev):
        super().__init__()
        self.cur, self.prev = cur, prev

    def __contains__(self, k):
        return k in self.cur or k in self.prev

    def __getitem__(self, k):
        return self.cur[k] if k in self.cur else self.prev[k]


def _vif_codecs(src, budget=0.5):
    """find_codecs entries: the first folded value that peels to a `v=` plan."""
    try:
        vals = fold_interpolation(src)
        if not vals:
            return []
        end = time.time() + budget
        for v in vals:
            for cand in (re.sub(r"\s+", "", v), v.strip()):
                if time.time() > end:
                    return []
                plain = peel_plan(cand, budget=min(0.3, max(0.05, end - time.time())))
                if plain and plain.lstrip("\ufeff \r\n\t").startswith("v="):
                    return [{"id": "fold", "rep": "descriptor", "transform": "identity", "key": "", "material": v,
                             "plain": plain}]
    except Exception:  # noqa: BLE001
        return []
    return []


# Marker-damaged / nameless fallback (target function-return-literal-battery). D22 NSIS `StrCpy $0 ".."` and D26 Erlang
# `build_plan() -> "<data>".` carried the plan with no descriptor name: only the marker regex found it. When the marker
# line is split or dropped and nothing else reads, every long literal in any quote syntax (`".."`, `'..'`, Rust
# `r#".."#`, Swift `#".."#`, `"""..""" `, Lua `[[..]]`, Tcl `{..}`, heredoc / Makefile `define`..`endef` bodies, bare
# `$(info ..)` / `ARG X=..` tokens) is joined with its adjacent pieces and shape-peeled; only a `v=` plan is kept. A
# `$VAR` use site (Dockerfile `LABEL x=$HUNTRESS_DESCRIPTOR`) is short, so the `ARG` literal is what reads.
_AL_CUE = re.compile(r"[A-Za-z0-9+/=_\-]{40}")
_AL_LIT = re.compile(r"""(?P<rh>(?<![\w])r(?P<h1>\#+)"(?P<rb>.*?)"(?P=h1))|(?P<sh>(?<![\w"])(?P<h2>\#+)"(?P<sb>.*?)"(?P=h2))"""
                     r"""|(?P<tq>(?P<q3>\"\"\"|''')(?P<tb>.*?)(?P=q3))|\[(?P<eq>=*)\[(?P<lb>.*?)\](?P=eq)\]"""
                     r"""|"(?P<db>(?:[^"\\\n]|\\.){1,65536})"|'(?P<qb>(?:[^'\\\n]|\\.){1,65536})'"""
                     r"""|(?<![\w$])\{(?P<cb>[^{}\s]{40,})\}""", re.S)
_AL_BLOCK = re.compile(r"""<<[-~<]?[ \t]*(["']?)(?P<tag>[A-Za-z_]\w*)\1[^\n]*\n(?P<hb>.*?)\n[ \t]*(?P=tag)\b"""
                       r"""|(?m:^define[ \t]+\S+[^\n]*\n)(?P<mb>.*?)\n[ \t]*endef\b""", re.S)
_AL_GAP = re.compile(r"""(?:\s|\\\r?\n|\+\+|<>|\.\.|[+.&,~|_\\])*""")
_AL_BARE = re.compile(r"(?<![\w+/=%.~:\-])[A-Za-z0-9+/=_\-.%~:]{40,}")
_AL_ESC = re.compile(r"\\(?:\r?\n[ \t]*|[nrt])")


def _anylit_candidates(src):
    """Literal bodies >= 40 chars, longest-first: adjacent-joined runs, single pieces, heredoc / define bodies, bare
    encoded tokens."""
    pieces, runs = [], []
    for m in _AL_LIT.finditer(src):
        body = next((m.group(g) for g in ("rb", "sb", "tb", "lb", "db", "qb", "cb") if m.group(g) is not None), "")
        if pieces and _AL_GAP.fullmatch(src, pieces[-1][1], m.start()):
            runs[-1].append(body)
        else:
            runs.append([body])
        pieces.append((m.start(), m.end()))
    out = ["".join(r) for r in runs if len(r) > 1] + [b for r in runs for b in r]
    out += [m.group("hb") if m.group("hb") is not None else m.group("mb") for m in _AL_BLOCK.finditer(src)]
    out += [m.group(0) for m in _AL_BARE.finditer(src)]
    seen, cands = set(), []
    for b in out:
        for c in (b, _AL_ESC.sub("", b)):
            if c not in seen and _AL_CUE.search(re.sub(r"\s+", "", c)):
                seen.add(c)
                cands.append(c)
    return sorted(cands, key=len, reverse=True)[:48]


def _anylit_codecs(src, budget=0.6):
    """find_codecs entries: every distinct `v=` plan under a long nameless literal (bounded by `budget` s)."""
    try:
        if not isinstance(src, str) or len(src) > (1 << 20) or not _AL_CUE.search(src):
            return []
        end, out, seen = time.time() + budget, [], set()
        for lit in _anylit_candidates(src):
            for cand in dict.fromkeys((re.sub(r"\s+", "", lit), lit.strip())):
                if time.time() > end or len(out) >= 4:
                    return out
                plain = peel_plan(cand, budget=min(0.25, max(0.05, end - time.time())))
                if plain and plain.lstrip("\ufeff \r\n\t").startswith("v=") and \
                        not any(q.startswith(plain) for q in seen):      # a wrapped line of a longer literal
                    seen.add(plain)
                    out.append({"id": "anylit", "rep": "literal", "transform": "identity", "key": "", "material": lit,
                                "plain": plain})
                    break
    except Exception:  # noqa: BLE001
        return []
    return out


# --- shell startup / config files as hosts (shell-rc-host-carriers, T1546.004) ---------------------------------------
# A persistence-flavoured zsh / fish / bash host keeps its descriptor in an rc file (.zshrc precmd hook, oh-my-zsh
# *.plugin.zsh alias, fish conf.d `--on-event` function, .bashrc PROMPT_COMMAND). Plain `"..."` / `'...'` bodies there
# already read through the generic literal readers; this reads the three rc-only spellings they miss:
#   fish_variables `SETUVAR [--export] name:value` (what `set -U` writes: every non-word char as `\xNN`, lists `\x1e`),
#   bash/zsh ANSI-C `$'\xNN\NNN\uXXXX..'` strings (adjacent `$'..'"..."'..'` words joined),
#   list joins: zsh `arr=(a b c)` + `${(j::)arr}` / `${(j.-.)arr}`, fish `set [-l|-g|-U] arr a b c` + `string join '' $arr`.
_SHRC_CUE = re.compile(r"(?m)^SETUVAR[ \t]|\$'|\$\{\([^)]*j(.)|\bstring[ \t]+join0?\b")
_SHRC_ANSI_ESC = re.compile(r"\\(?:x([0-9a-fA-F]{1,2})|u([0-9a-fA-F]{1,4})|U([0-9a-fA-F]{1,8})|([0-7]{1,3})|c(.)|(.))",
                            re.S)
_SHRC_ANSI_SIMPLE = {"a": "\a", "b": "\b", "e": "\x1b", "E": "\x1b", "f": "\f", "n": "\n", "r": "\r", "t": "\t",
                     "v": "\v", "\\": "\\", "'": "'", '"': '"', "?": "?"}
_SHRC_WORD = re.compile(r"\$'((?:[^'\\]|\\.)*)'|\"((?:[^\"\\]|\\.)*)\"|'([^']*)'|([^\s'\"$;|&()<>`#]+)", re.S)
_SHRC_ARR = re.compile(r"(?m)^[ \t]*(?:(?:typeset|declare|local|readonly|export)[ \t]+(?:-[A-Za-z]+[ \t]+)*)?"
                       r"([A-Za-z_]\w*)=\(([^()]*)\)")
_SHRC_FISH_SET = re.compile(r"(?m)^[ \t]*set[ \t]+(?:-[A-Za-z]+[ \t]+|--[a-z]+[ \t]+)*([A-Za-z_]\w*)[ \t]+([^\n;]+)")


def _shrc_ansi(body):
    """bash/zsh `$'..'` body -> text (`\\xHH`, octal, `\\uXXXX`, `\\cX`, C escapes)."""
    def sub(m):
        hx, u4, u8, oc, ctl, ch = m.groups()
        if hx or u4 or u8:
            v = int(hx or u4 or u8, 16)
            return chr(v) if v < 0x110000 else ""
        if oc:
            return chr(int(oc, 8) & 0xFF)
        if ctl is not None:
            return chr(ord(ctl) & 0x1F)
        return _SHRC_ANSI_SIMPLE.get(ch, "\\" + ch)
    return _SHRC_ANSI_ESC.sub(sub, body)


def _shrc_words(s):
    """Shell words of `s` (adjacent quoted pieces joined: `$'..'"..."x` is one word), unquoted."""
    words, cur, last = [], None, -1
    for m in _SHRC_WORD.finditer(s):
        a, d, q, bare = m.groups()
        piece = (_shrc_ansi(a) if a is not None else
                 re.sub(r"\\([\\\"$`\n])", r"\1", d) if d is not None else q if q is not None else bare)
        if cur is not None and m.start() == last:
            cur += piece
        else:
            if cur is not None:
                words.append(cur)
            cur = piece
        last = m.end()
    if cur is not None:
        words.append(cur)
    return words


def _shrc_codecs(src, budget=0.5):
    """find_codecs entries read from shell rc / fish_variables spellings (see the section comment)."""
    try:
        if not isinstance(src, str) or len(src) > (1 << 20) or not _SHRC_CUE.search(src):
            return []
        end, cands = time.time() + budget, []
        for m in re.finditer(r"(?m)^SETUVAR[ \t]+(?:--\w+[ \t]+)*([A-Za-z_]\w*):(.*)$", src):
            v = re.sub(r"\\x([0-9a-fA-F]{2})", lambda x: chr(int(x.group(1), 16)), m.group(2)).replace("\\\\", "\\")
            cands += [v.replace("\x1e", ""), v.replace("\x1e", " ")] if "\x1e" in v else [v]
        for n, m in enumerate(re.finditer(r"\$'((?:[^'\\]|\\.)*)'", src)):  # ANSI-C words + adjacent pieces
            if n >= 256:
                break
            ls = src.rfind("\n", 0, m.start()) + 1
            le = src.find("\n", m.end())
            for w in [_shrc_ansi(m.group(1))] + _shrc_words(src[ls:le if le >= 0 else len(src)]):
                for v in (w, re.sub(r"\A[A-Za-z_]\w*(?:\[[^\]]*\])?\+?=", "", w)):  # `name=$'..'` word
                    if len(v) >= 24:
                        cands.append(v)
        arrs = {}
        for m in _SHRC_ARR.finditer(src):
            arrs[m.group(1)] = _shrc_words(m.group(2).replace("\\\n", " "))
        for m in _SHRC_FISH_SET.finditer(src):
            if m.group(1) not in arrs:
                ws = _shrc_words(m.group(2))
                if len(ws) > 1:
                    arrs[m.group(1)] = ws
        for m in re.finditer(r"\$\{\(([^)]*)\)([A-Za-z_]\w*)", src):   # zsh ${(j:sep:)arr}, j with any delimiter
            jm = re.search(r"j(.)(.*?)\1", m.group(1))
            if jm and m.group(2) in arrs:
                cands.append(jm.group(2).join(arrs[m.group(2)]))
        for m in re.finditer(r"\bstring[ \t]+join[ \t]+(?:--\S+[ \t]+)*('[^']*'|\"[^\"]*\"|\S+)[ \t]+((?:\$\w+[ \t]*)+)",
                             src):
            sep = _shrc_words(m.group(1))
            names = re.findall(r"\$(\w+)", m.group(2))
            if all(n in arrs for n in names):
                cands.append((sep[0] if sep else "").join(w for n in names for w in arrs[n]))
        out, seen = [], set()
        for c in sorted(dict.fromkeys(cands), key=len, reverse=True)[:32]:
            if time.time() > end or len(out) >= 4:
                break
            plain = peel_plan(c, budget=min(0.25, max(0.05, end - time.time())))
            if plain and plain.lstrip("﻿ \r\n\t").startswith("v=") and \
                    not any(q.startswith(plain) for q in seen):
                seen.add(plain)
                out.append({"id": "shrc", "rep": "literal", "transform": "identity", "key": "", "material": c,
                            "plain": plain})
    except Exception:  # noqa: BLE001
        return []
    return out


_FC_CACHE = {}


def find_codecs(src, _depth=0):
    """Every declared codec in a source text (see _find_codecs_uncached). Nested readings (_depth >= 1) of one inner
    text are memoised: the SaaS JSON-string reader and the nested string-carrier reader can unescape the same text."""
    if _depth < 1 or not isinstance(src, str) or len(src) > (1 << 20):
        return _find_codecs_uncached(src, _depth)
    hit = _FC_CACHE.get((src, _depth))
    if hit is None:
        if len(_FC_CACHE) > 64:
            _FC_CACHE.clear()
        hit = _FC_CACHE[(src, _depth)] = _find_codecs_uncached(src, _depth)
    return [dict(c) for c in hit]


def _find_codecs_uncached(src, _depth=0):
    """Every declared codec in a source text: [{id, rep, transform, key, material, plain}] (plain = decode() or None).
    Batch `HUNTRESS-CODEC:` has no id -- its material is the `HUNTRESS-MATERIAL:` line.
    `src` may also be raw bytes (or latin-1 text) of a container carrier: see _carrier_codecs, tried only when the
    text itself declares nothing."""
    raw = None
    if isinstance(src, (bytes, bytearray)):
        raw = bytes(src)
        src = raw.decode("utf-8", "ignore")
    src = wsh_decode(src) or src                         # JScript.Encode / VBScript.Encode blocks: read the plain
    out = _find_codecs_text(src)
    if _depth < 2 and _PL_CUE.search((src or "")[:4096]):
        # launchd / plist carrier (launchd-plist-route): a gap, or the full plan ahead of a first-piece reading of an
        # XML-escaped body it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _plist_codecs(src, raw, _depth) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) for p in have)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _NSIS_CUE.search(src[:1 << 20]):
        # NSIS `!define`/`${X}`/`StrCpy $0 "$0.."` folded descriptor: a gap, or the full plan ahead of a piece it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _nsis_codecs(src) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) for p in have)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _SHRC_CUE.search(src[:1 << 20]):
        # shell rc / fish_variables (`SETUVAR`, `$'..'`, `${(j::)arr}` / `string join`): a gap, or the full plan ahead
        # of the first array element it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _shrc_codecs(src) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) for p in have)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _INNO_CUE.search(src[:1 << 20]):
        # Inno Setup ISPP `{#X}` / Pascal `'..' + #13#10 + X` / [Run] Parameters folded descriptor: same rule as NSIS
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _inno_codecs(src) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) for p in have)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and (_WIX_CUE.search(src[:1 << 20]) or
                                                src[:8] == "\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"):
        # WiX `<CustomAction>` / MSI CustomAction table: `[PROP]`-formatted script bodies, a gap, or the full plan
        # ahead of a piece it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _wix_codecs(src, raw, _depth) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) for p in have)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out) and (_GD_CUE.search((src or "")[:1 << 16]) or
                                                                  (src or "")[-4:] == "GDPC"):
        out = out + _godot_codecs(src, raw, _depth)  # Godot .tscn/.tres script/source, .pck members, .gdc tokens
    if _depth < 2 and not any(c.get("plain") for c in out) and \
            ((raw or (src or "")[:12].encode("latin-1", "replace"))[:4] in (b"FOR1", b"PK\x03\x04") or
             (src or "")[:2] == "#!" and re.search(r"(?m)^(?:PK\x03\x04|FOR1)", (src or "")[:1 << 14])):
        out = out + _beam_bin_codecs(src, raw)            # compiled .beam / escript archive literals
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _carrier_codecs(src, raw, _depth)
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _bat_codecs(src)
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _ps_codecs(src, _depth)
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _ps_v3_codecs(src)
    elif _depth < 2 and _PSV3_VAR.search((src or "")[:1 << 20]):
        # a PS `"a" +` backtick-continued / `'it''s'` descriptor reads lossy elsewhere: the full plan goes first
        x = [c for c in _ps_v3_codecs(src) if any(_psv3_lossy(c["plain"], o.get("plain")) for o in out)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _xslt_codecs(src)
    elif _depth < 2 and _XSL_HOST.search((src or "")[:1 << 16]):
        # an XML-escaped `"a" &amp; _ "b"` reads as the plan-shaped first piece only: the full plan goes first
        x = [c for c in _xslt_codecs(src) if any(c["plain"] != p and c["plain"].startswith(p)
                                                 for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _chain_codecs(src, _depth)
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _build_host_codecs(src)
    elif _depth < 2 and _BH_APPEND.search((src or "")[:1 << 20]):
        # a Makefile `descriptor_x += ..` / `:= $(descriptor_x)..` append reads as its first piece only: full plan first
        x = [c for c in _build_host_codecs(src) if any(c["plain"] != p and c["plain"].startswith(p)
                                                       for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out) and _HK_CUE.search((src or "")[:1 << 16]) and \
            re.search(r"<executable>|<exec\b", (src or "")[:1 << 20]):
        out = out + _hook_codecs(src, _depth)            # Maven / Ant build hook: argv split over XML elements
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _saas_host_codecs(src, raw, _depth)     # SaaS / add-in host: JSON-escaped script, zip / CRX package
    if _depth < 2 and _JC_CUE.search((src or "")[:1 << 16]) and (src or "").lstrip("\ufeff \t\r\n")[:1] in "{[/":
        # script carried in a JSON document (ipynb / tasks.json / package.json / devcontainer): a gap, or the full plan
        # when what was read so far is its prefix (a `"a"\<nl>"b"` bash cell reads as the first piece)
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _json_carrier_codecs(src, raw, _depth) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) for p in have)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _JMX_CUE.search(src[:1 << 16]):
        # JMeter `.jmx` User Defined Variable / header pair `descriptor_x` = `${a}${b}`: a gap, or the full plan ahead
        # of a piece reading it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _jmx_codecs(src, _depth) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out) and _MH_CUE.search((src or "")[:1 << 20]):
        out = out + _managed_host_codecs(src, raw, _depth)  # .NET-hosted inner C# / VB / JScript (Add-Type, ASP, csc)
    elif _depth < 2 and _MH_CUE.search((src or "")[:1 << 20]):
        # a `"a" & _` / `"a" +` continued descriptor inside the host reads as its first piece only: the full plan first
        x = [c for c in _managed_host_codecs(src, raw, _depth) if any(c["plain"] != p and c["plain"].startswith(p)
                                                                       for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out) and _PH_CUE.search((src or "")[:1 << 20]):
        out = out + _prior_host_codecs(src, raw, _depth)    # host wrapping an older language (WSC, ipynb, unit, cron)
    elif _depth < 2 and _PH_CUE.search((src or "")[:1 << 20]) and re.search(r"(?i)<component\b|<scriptlet\b", (src or "")[:1 << 16]):
        # a WSC `"a" & _` continued descriptor reads as its first piece only: the full plan goes first
        x = [c for c in _prior_host_codecs(src, raw, _depth) if any(c["plain"] != p and c["plain"].startswith(p)
                                                                     for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _cs_fold_codecs(src)                      # C# / VB / F# descriptor assembled at runtime
    elif _depth < 2 and (_CS_CUE.search((src or "")[:1 << 18]) or _BSH_CUE.search((src or "")[:1 << 18])) and \
            _CS_DESC_NAME.search((src or "")[:1 << 18]):
        # a `"a" + (char)0x76 + ..` descriptor reads as its literal pieces only: the folded full plan goes first
        x = [c for c in _cs_fold_codecs(src, 0.3) if any(c["plain"] != p and c["plain"].startswith(p)
                                                          for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out):
        out = out + _gv_fold_codecs(src)                      # Groovy / Kotlin descriptor assembled at runtime
    elif _depth < 2 and _GV_CUE.search((src or "")[:1 << 18]) and _CS_DESC_NAME.search((src or "")[:1 << 18]):
        # a `new String(x1) + ..` / `[x1, x2].join()` descriptor reads as one plan-shaped piece only: full plan first
        x = [c for c in _gv_fold_codecs(src, 0.3) if any(c["plain"] != p and (c["plain"].startswith(p) or (
            # Kotlin raw `"""..${'$'}.."""`: the literal reading keeps the template, the fold resolves it to `$`
            "${" in p and c["plain"] == re.sub(r"""\$\{\s*(?:'\$'|"\$")\s*\}""", "$", p)))
                                                          for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and not any(c.get("plain") for c in out) and (_DN_CARRIER.search((src or "")[:8 << 20]) or
                                                                (raw or b"")[:2] == b"MZ"):
        out = out + _dotnet_codecs(src, raw, _depth)          # managed assembly bytes carried by the script
    if _depth < 1 and not any(c.get("plain") for c in out):
        norm = normalize(raw if raw is not None else src)     # whole-leaf UTF-16 / gzip / base64: rescan the source
        if norm:
            out = out + [dict(c, id=f"{c['id']}@leaf") for c in find_codecs(norm, _depth + 1) if c.get("plain")]
    if _depth < 1 and not any(c.get("plain") for c in out):
        out = out + _reg_inf_codecs(normalize(raw if raw is not None else src) or src, _depth)
    if _depth < 1 and not any(c.get("plain") for c in out):
        mat, plain = _split_array_plain(src, budget=0.5)          # split chunk-list carrier without the SPLIT marker
        if plain:
            out = out + [{"id": "split", "rep": "split_array", "transform": "identity", "key": "", "material": mat,
                          "plain": plain}]
    if _depth < 1 and not any(c.get("plain") for c in out):
        out = out + _proc_codecs(src, raw, _depth)   # process-telemetry log: codecs inside escaped command lines
    if _depth < 1 and isinstance(src, str) and _CI_CUE.search(src[:1 << 16]):
        # CI pipeline step bodies (Groovy / YAML string semantics): a host-escaped body goes first, else fills a gap
        have = {c.get("plain") for c in out if c.get("plain")}
        x = [(c, ck) for c, ck in _pipeline_codecs(src) if c["plain"] not in have]
        out = [c for c, ck in x if ck] + out + ([c for c, ck in x if not ck] if not have else [])
    if _depth < 1 and isinstance(src, str) and _K8S_CUE.search(src[:1 << 18]):
        # Kubernetes / Helm manifest: a Helm-rendered / Secret-decoded body goes first, else a script body fills a gap
        have = {c.get("plain") for c in out if c.get("plain")}
        x = [(c, ck) for c, ck in _k8s_codecs(src) if c["plain"] not in have]
        out = [c for c, ck in x if ck] + out + ([c for c, ck in x if not ck] if not have else [])
    if _depth < 1 and isinstance(src, str) and _IAC_CUE.search(src[:1 << 18]):
        # IaC template (Terraform / CloudFormation / ARM / Bicep / Ansible): a gap, or the full plan ahead of a piece
        # it extends (a `Fn::Join` / `concat()` / HCL-escaped body reads as its first piece only)
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _iac_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 1 and not any(c.get("plain") for c in out):
        out = out + _nested_codecs(src)              # inner script carried as an escaped / encoded host string literal
    elif _depth < 1 and _NS_LOSSY.search((src or "")[:1 << 20]):
        # a marker whose material runs into a `\uXXXX` / `&#x..;` / backtick escape reads truncated: full plan first
        x = [c for c in _nested_codecs(src, 0.3) if any(c["plain"] != p and c["plain"].startswith(p)
                                                        for p in (o.get("plain") for o in out) if p)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and re.search(r"(?i)descriptor[_-]", src[:1 << 20]):
        # Rust / Swift / Nim / Zig / Dart raw, `\\` multi-line, `\u{..}` and adjacent literals (_cl_literals): a gap,
        # or the full plan ahead of a first-piece reading it extends (printable tail only)
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _cl_codecs(src, extend_only=bool(have)) if not have or
             any(c["plain"] != p and c["plain"].startswith(p) and c["plain"][len(p):].isprintable() for p in have)]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _NST_CUE.search(src[:1 << 20]):
        # Tcl `append` / `[binary decode ..]` / `$var`, Swift `String(decoding: [UInt8])`, Nim `cast[string](@[..])`
        # (_nst_codecs): a gap, or the full plan ahead of a first-piece reading it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _nst_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _GM_DESC.search(src[:1 << 20]):
        # game-script verbatim `@".."`, Pawn `descriptor_x[] =` / escapes, mcfunction `set value` (_gm_literals)
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _gm_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _BEAM_CUE.search(src[:1 << 18]) and \
            re.search(r"(?i)descriptor", src[:1 << 20]):
        # Erlang / Elixir folded descriptor (binaries, charlists, sigils, `++` / `<>`, Base.decode64!): a gap, or the
        # full plan ahead of a first-piece reading it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _beam_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _SHFN_CUE.search(src[:1 << 20]) and _SHFN_PR.search(src[:1 << 20]) \
            and (not any(c.get("plain") for c in out) or _SHFN_NAMED.search(src[:1 << 20])):
        # zsh / bash / fish function-return descriptor `build_plan_x() { print -r -- ".." }` / `function x; echo ..; end`:
        # a gap, or the full plan ahead of a first-piece reading it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _shfn_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _AWKSED_CUE.search(src[:1 << 16]):
        # awk `descriptor_x = "ab" "cd"` / `function build_plan_x() { return ".." }`, sed `s/^.*$/<data>/` (`\/`
        # escapes) and `1i\` / `a\` / `c\` text commands: a gap, or the full plan ahead of a first-piece reading it
        # extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _awksed_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _TFH_CUE.search(src[:1 << 18]) and \
            re.search(r"(?i)descriptor", src[:1 << 20]):
        # Terraform descriptor folded over locals / var defaults / heredocs / join / format / base64decode: a gap, the
        # full plan ahead of a piece reading it contains, else after every earlier reading
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _tfh_codecs(src) if c["plain"] not in have]
        ext = [c for c in x if not have or any(c["plain"] != p and p in c["plain"] for p in have)]
        out = ext + out + [c for c in x if c not in ext]
    if _depth < 2 and isinstance(src, str) and _MF_CUE.search(src[:1 << 20]) and \
            (_MF_ERL.search(src[:1 << 20]) or re.search(r"(?m)GenServer\.|postMessage\(|^package\s", src[:1 << 20])):
        # actor / message-passing source: a plan split over `Pid ! {chunk, N, ".."}` / `send` / `postMessage` / `ch <-`
        # messages (_mf_codecs): a gap, or the full plan ahead of a first-piece reading it extends
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _mf_codecs(src) if c["plain"] not in have and (not have or any(
            c["plain"] != p and c["plain"].startswith(p) for p in have))]
        out = x + out
    if _depth < 2 and isinstance(src, str) and _VIF_CUE.search(src[:1 << 20]):
        # descriptor split over variables joined by interpolation / concatenation (fold_interpolation): a gap, or the
        # full plan ahead of a piece reading it extends (a piece of a split base64 / hex plan reads plan-shaped with a
        # ragged tail, or as a middle `|steps=` run)
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _vif_codecs(src, 0.5 if not have else 0.25) if c["plain"] not in have and (not have or any(
            len(c["plain"]) > len(p) and (p in c["plain"] or c["plain"].startswith(p[:max(12, len(p) - 4)]))
            for p in have))]
        out = x + out
    if _depth < 1 and isinstance(src, str) and (_JSP_CUE.search(src[:1 << 16]) or (
            "\\u" in src and "String" in src and _JAVA_CUE.search(src[:1 << 16]))):
        # JSP / JSPX / .tag / Java / .war: a gap, or -- when unicode escapes, includes or constant concatenations can
        # hide a dead (commented) decoy -- the live reading ahead of readings it disagrees with entirely
        have = [c.get("plain") for c in out if c.get("plain")]
        if not have or "\\u" in src or src[:4] == "PK\x03\x04" or _JSP_INCL.search(src[:1 << 20]) or \
                re.search(r"=\s*[A-Za-z_]\w*\s*\+", src[:1 << 20]):
            x = _jsp_codecs(src, raw)
            if not have:
                out = out + x
            elif x and not set(have) & {c["plain"] for c in x}:
                out = x + out
    if _depth < 1 and isinstance(src, str) and _bw_kind(src[:1 << 20]):
        # compose / Taskfile / CMake / justfile / package.json wrapper: a gap, or the full plan ahead of a piece reading
        # it extends (a `string(APPEND ..)` / `- D0=..` / `p0 + p1` split reads as its first piece)
        have = [c.get("plain") for c in out if c.get("plain")]
        x = [c for c in _build_wrap_codecs(src, 0.4 if not have else 0.25) if c["plain"] not in have and (
            not have or any(c["plain"] != p and c["plain"].startswith(p) or (   # or a short garbled first-piece read
                p.startswith("v=") and p.count("|") < 6 and len(c["plain"]) > len(p) and
                c["plain"].startswith(p[:p.rfind("|") + 1])) for p in have))]
        out = x + out
    if _depth < 1 and isinstance(src, str):
        # marker split / dropped, nameless literal: any long literal fills a gap, or goes ahead of short plan-shaped
        # readings it extends (a split marker reads as the first piece `v=3|language=x|role`)
        have = [c.get("plain") for c in out if c.get("plain")]
        if not have:
            out = out + _anylit_codecs(src)
        elif all(p.startswith("v=") and p.count("|") < 6 for p in have):
            out = [c for c in _anylit_codecs(src, 0.3) if any(c["plain"] != p and c["plain"].startswith(p)
                                                              for p in have)] + out
    return out


def _find_codecs_text(src):
    out = []
    for m in _CODEC_RE.finditer(src or ""):
        parts = m.group("spec").split("|")
        rep, tr, key = (parts + ["", "", ""])[:3]
        mat = material_text(src, m.group("id"))
        out.append({"id": m.group("id"), "rep": rep, "transform": tr, "key": key, "material": mat,
                    "plain": decode(mat, rep, tr, key)})
    seen = {c["id"] for c in out}
    for rx in _TPL_CODEC_RES:                         # Tcl `set Codec_x {..}`, Perl `CODEC_X => '..'`
        for m in rx.finditer(src or ""):
            if m.group("id") not in seen:
                seen.add(m.group("id"))
                rep, tr, key = ((m.group("q") or m.group("b") or "").split("|") + ["", "", ""])[:3]
                mat = material_text(src, m.group("id"))
                out.append({"id": m.group("id"), "rep": rep, "transform": tr, "key": key, "material": mat,
                            "plain": decode(mat, rep, tr, key)})
    tpl_end = time.time() + 1.0
    for c in out:                                     # material written through a pack/unpack/escape template
        if c["plain"] is None and c["rep"] and time.time() < tpl_end:
            p, st = _tpl_decode(src, c["id"], c["rep"], c["transform"], c["key"], max(0.05, tpl_end - time.time()))
            if p:
                c["plain"], c["material"] = p, st
    bc, bm = _BATCH_CODEC_RE.search(src or ""), _BATCH_MAT_RE.search(src or "")
    if bc:
        parts = bc.group("spec").split("|")
        rep, tr, key = (parts + ["", "", ""])[:3]
        mat = bm.group("mat") if bm else None
        out.append({"id": "batch", "rep": rep, "transform": tr, "key": key, "material": mat,
                    "plain": decode(mat, rep, tr, key)})
    am = _ANALYSIS_RE.search(src or "") or _marker_bare(src or "")
    if am:
        rep = _ANALYSIS_TAG_REP.get(am.group("tag").upper(), am.group("tag").lower())
        dm = re.search(r"descriptor_(\w+)", src)
        # a tag the reps don't name (B32, GZ64, XOR, ROT, A85, URL, UTF16...): peel its layers BEFORE the name-agnostic
        # _fallback, whose transform guesses can turn UTF-16 NULs into a plan-shaped 'v==33||ll..' (known tags unchanged)
        known_tag = am.group("tag").upper() in _ANALYSIS_TAG_REP
        plain = decode(am.group("mat"), rep, "identity") if known_tag else peel_plan(am.group("mat"), am.group("tag"))
        if plain:                                # a wrapped marker whose first line alone peels to a prefix plan
            plain = _marker_extended(src, am, plain)
        if plain is None:
            plain = peel_plan(am.group("mat"), am.group("tag")) if known_tag else decode(am.group("mat"), rep, "identity")
            for lit in ([] if plain else _descriptor_literals(src)):
                plain = peel_plan(lit, am.group("tag"))
                if plain:
                    break
            if plain is None:                    # wrapped marker material, then the wider descriptor syntax set
                cont = [("", v) for v in _marker_continued(src, am)]
                plain = _peel_ext(cont + _ahk_literals(src) + _descriptor_literals_ext(src), am.group("tag"),
                                  tried=_descriptor_literals(src) + [am.group("mat")])[1]
        mat = am.group("mat")
        if plain is None or (am.string is src and re.match(r"""["'<][^\s;,)\-"'>]""", src[am.end():am.end() + 2])):
            vt = _v3_tag_line(src, budget=0.3)               # v3-tag-vocab-extend: tag table / full marker line (b85/a85 `<"'`)
            if vt and (plain is None or len(vt[2]) > len(plain) and vt[2].startswith(plain)):
                mat, plain = vt[1], vt[2]
        out.append({"id": dm.group(1) if dm else "analysis", "rep": rep, "transform": "identity", "key": "",
                    "material": mat, "plain": plain})
    elif not out:
        if _SPLIT_MARK_RE.search(src or ""):                     # D18 bare SPLIT marker + literal-array material
            mat, plain = _split_array_plain(src)
            if plain:
                out.append({"id": "analysis", "rep": "split_array", "transform": "identity", "key": "",
                            "material": mat, "plain": plain})
        for ident, lit in ([] if out else _ahk_literals(src)):   # AHK v1 continuation section / `.=` appends
            plain = _peel_ext([(ident, lit)])[1]
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "", "material": lit,
                            "plain": plain})
                break
        for ident, lit in ([] if out else _descriptor_literals(src or "", with_id=True)):  # descriptor literal, no marker line
            plain = peel_plan(lit)
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "", "material": lit,
                            "plain": plain})
                break
        if not out:
            lits = _descriptor_literals_ext(src or "")
            ident, plain = _peel_ext(lits, tried=_descriptor_literals(src or ""))
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "",
                            "material": dict(lits).get(ident), "plain": plain})
        if not out and "HUNTRESS_ANALYSIS_V" in (src or ""):     # a marker material _ANALYSIS_RE cannot start (b85 `<`)
            vt = _v3_tag_line(src)
            if vt:
                out.append({"id": "analysis", "rep": vt[0].lower(), "transform": "identity", "key": "",
                            "material": vt[1], "plain": vt[2]})
    return out


# ------------------------------------------------------------------------------------------------ v=3 layer peel
# The v=3 cross-language marker `HUNTRESS_ANALYSIS_V1:<TAG>-<material>` names its layers in TAG (B64, HEX, HB64, FRAG
# so far). A new tag must not silently yield no plan: peel_plan() reads the material through lib.decode's layer
# expander (hex/b32/b64/b64url/b85/a85/gzip/zlib/bz2/lzma/url/reverse/rot) plus UTF-16 text, raw deflate and
# single-byte / tag-keyed XOR, breadth-first to `depth` layers, accepting only a plan (looks_like_plan).

_DESC_RE = re.compile(r"""descriptor_(?P<id>\w+)\s*(?::=|:|=)?\s*((?:"[^"]*"|'[^']*'|\s*[.+&]\s*|\s*_\s*\n)+)""")


def _descriptor_literals(src, with_id=False):
    """The joined string literal(s) of each `descriptor_<id> = "..." [+ "..."]` assignment."""
    out = []
    for m in _DESC_RE.finditer(src or ""):
        lit = "".join(a or b for a, b in re.findall(r'"([^"]*)"|\'([^\']*)\'', m.group(2)))
        if lit:
            out.append((m.group("id"), lit) if with_id else lit)
    return out



# Descriptor syntax beyond `descriptor_x = "..."` (target descriptor-syntax-generic): any case / `-` separator, typed or
# non-`=` binders (Tcl `set x {..}`, R `<-`, Go `:=` / `var x string =`, Rust/Kotlin/TS `: &str =`, YAML `x: |`, JSON
# `"x": "..."`), multi-line literal forms (triple quotes, here-strings, heredocs, Lua long strings, braces, backticks,
# YAML block scalars) and XML elements (`<descriptor_x>..</..>`, `<string name="descriptor_x">`, plist <key>). Only
# consulted after _descriptor_literals found no plan, so every earlier reading is unchanged.
_XDESC_RE = re.compile(r"""descriptor[_-](?P<id>[\w-]+)["']?""", re.I)
# D21 GitHub Actions (and its CI siblings: GitLab `variables:`, Azure `- name: X` + `value:`, CircleCI / Drone
# `environment:`, Buildkite / Tekton `env:`, Bitbucket `export X=..`) bind the descriptor to a bare UPPERCASE
# `HUNTRESS_DESCRIPTOR` key with no id. Read after every `descriptor_<id>` match, so earlier readings keep priority.
_HDESC_RE = re.compile(r"""(?<![\w-])HUNTRESS[_-](?P<id>DESCRIPTOR)(?![\w-])["']?""", re.I)
_XBIND_RE = re.compile(r"""[ \t]*(?::[ \t]*&?(?:'static[ \t]+)?[\w.\[\]<>]+[ \t]*(?==))?(?:[ \t]+-?[A-Za-z_][\w.\[\]]*[ \t]*(?==))?"""
                       r"""[ \t]*(?P<op><<-|<-|:=|=>|->|=|:|,)?[ \t]*""")
_XML_DESC_RES = (
    re.compile(r"<(?P<tag>descriptor[\w-]*)\b(?P<attrs>[^>]*)>(?P<body>.*?)</(?P=tag)\s*>", re.I | re.S),
    re.compile(r"""<(?P<tag>[\w:-]+)\b[^>]*?\b(?:name|id|key)\s*=\s*["']descriptor[_-](?P<id>[\w-]+)["'][^>]*>(?P<body>.*?)</(?P=tag)\s*>""",
               re.I | re.S),
    re.compile(r"<key>\s*descriptor[_-](?P<id>[\w-]+)\s*</key>\s*<(?P<tag>\w+)>(?P<body>.*?)</(?P=tag)>", re.I | re.S),
)


# YAML value shapes (target yaml-ci-host-route: GitHub Actions / GitLab CI / Ansible hosts) the quoting forms below miss:
# `!!binary` / `!tag` / `&anchor` properties, `*alias`, `[..]` flow sequences, a value on the deeper-indented lines
# below its key (block sequence items joined, a mapping's default/value/data child, a lone scalar), `|2-` indicators,
# plain scalars folded over deeper-indented lines, and `- name: descriptor_x` + sibling `value:`. Pure regex/indent
# reading (no PyYAML in-window); every shape here used to read as None, so earlier readings are unchanged.
_YAML_PROPS = re.compile(r"(?:(?:!!?[\w:/.-]*|!<[^>\s]*>|&[\w-]+)(?:[ \t]+|(?=[ \t]*(?:#[^\n]*)?\r?\n)))+")
_YAML_SUB_KEYS = ("default", "value", "data", "content", "payload", "text", "body", "stdin", "src")
_YAML_KEY = re.compile(r"""[ \t]*(?:-[ \t]+)?(["']?)([\w.-]+)\1[ \t]*:(?:[ \t]+|(?=\r?$))""")
_YAML_PLAIN_CONT = re.compile(r"\n( +)([A-Za-z0-9+/=_\-.%~]+)[ \t]*(?=\r?\n|$)")
_YAML_JINJA = re.compile(r"""\s*\{\{-?\s*(["'])(.*?)\1\s*(?:\|\s*\w+(?:\([^)]*\))?\s*)*-?\}\}\s*""", re.S)
_YAML_FLOW_ITEM = re.compile(r""""([^"]*)"|'([^']*)'|([^,\s\[\]"']+)""")


def _yaml_indent(src, i):
    ls = src.rfind("\n", 0, i) + 1
    line = src[ls:i]
    return len(line) - len(line.lstrip(" \t"))


def _yaml_children(src, j, base, lim=1 << 16):
    """[(indent, line, offset)] of the non-blank, non-comment lines from src[j] on that sit deeper than `base`."""
    out, stop = [], j + lim
    while j < len(src) and j < stop and len(out) < 512:
        e = src.find("\n", j)
        e = len(src) if e < 0 else e
        line = src[j:e].rstrip("\r")
        s = line.strip()
        if s and not s.startswith("#"):
            ind = len(line) - len(line.lstrip(" \t"))
            if ind <= base:
                break
            out.append((ind, line, j))
        j = e + 1
    return out


def _yaml_node(src, i, depth=0):
    """(text, end) of a YAML value at src[i] in one of the shapes above, or (None, i)."""
    if depth > 2 or i >= len(src):
        return None, i
    p = _YAML_PROPS.match(src, i)
    if p and p.end() > i:
        return _read_literal(src, p.end(), ":", depth + 1)
    m = re.match(r"\*([\w-]+)", src[i:i + 80])
    if m:                                                            # alias -> the anchored value
        a = re.search(r"(?<![\w*-])&" + re.escape(m.group(1)) + r"(?=[ \t\r\n])", src)
        return (_read_literal(src, a.start(), ":", depth + 1)[0] if a else None), i + m.end()
    if src.startswith("[", i):                                       # flow sequence ["ab", 'cd', ef]
        j = src.find("]", i, i + (1 << 16))
        if j < 0:
            return None, i
        text = "".join(a or b or c for a, b, c in _YAML_FLOW_ITEM.findall(src[i + 1:j]))
        return (text or None), j + 1
    m = re.match(r"[ \t]*(?:#[^\n]*)?\r?\n", src[i:i + 4096])
    if not m:
        return None, i
    kids = _yaml_children(src, i + m.end(), _yaml_indent(src, i))
    if not kids:
        return None, i
    ind0 = kids[0][0]
    top = [k for k in kids if k[0] == ind0]
    end = kids[-1][2] + len(kids[-1][1])
    if top[0][1].lstrip().startswith("- "):                          # block sequence: scalar items joined
        parts = []
        for ind, line, off in top:
            body = line.lstrip()
            if not body.startswith("- ") or _YAML_KEY.match(body[2:]):
                return None, i
            t, _ = _read_literal(src, off + ind + 2, ":", depth + 1)
            parts.append(body[2:].strip() if t is None else t)
        return "".join(parts), end
    keyed = [(km, off + ind) for ind, line, off in top for km in [_YAML_KEY.match(line.lstrip())] if km]
    if keyed:                                                        # nested mapping: default/value/data, else longest
        vals = []
        for km, off in keyed:
            t, _ = _read_literal(src, off + km.end(), ":", depth + 1)
            if t:
                vals.append((km.group(2).lower() in _YAML_SUB_KEYS, len(t), t))
        return (max(vals)[2] if vals else None), end
    t, e = _read_literal(src, top[0][2] + ind0, ":", depth + 1)      # lone scalar on the next line
    return t, (e if t is not None else i)


def _yaml_sibling_value(src, start):
    """`- name: descriptor_x` (k8s env / Actions inputs list): the sibling `value:` / `default:` literal, else None."""
    ls = src.rfind("\n", 0, start) + 1
    m = re.match(r"""([ \t]*(?:-[ \t]+)?)(?:name|key|id|variable)[ \t]*:[ \t]*["']?$""", src[ls:start])
    if not m:
        return None
    col, j = len(m.group(1)), src.find("\n", start)
    for ind, line, off in _yaml_children(src, j + 1 if j >= 0 else len(src), col - 1)[:32]:
        km = _YAML_KEY.match(line) if ind == col else None
        if km and km.group(2).lower() in _YAML_SUB_KEYS:
            return _read_literal(src, off + km.end(), ":")[0]
    return None


def _read_literal(src, i, op, _depth=0):
    """(text, end) of the literal starting at src[i] in any common quoting form, or (None, i)."""
    lim = 1 << 16
    if op == ":":
        r = _yaml_node(src, i, _depth)
        if r[0] is not None:
            return r
    t = src[i:i + 3]
    if t in ('"""', "'''"):
        j = src.find(t, i + 3, i + lim)
        return (src[i + 3:j], j + 3) if j > 0 else (None, i)
    m = re.match(r"""@(["'])[ \t]*\r?\n""", src[i:i + 4])            # PowerShell here-string @" .. "@
    if m:
        e = re.compile(r"\n[ \t]*" + m.group(1) + "@").search(src, i, i + lim)
        return (src[i + m.end():e.start()], e.end()) if e else (None, i)
    m = re.match(r"""<<[-~]?[ \t]*(["']?)([A-Za-z_]\w*)\1[^\n]*\n""", src[i:i + 80])     # heredoc
    if m:
        e = re.compile(r"\n[ \t]*" + re.escape(m.group(2)) + r"\b").search(src, i + m.end() - 1, i + lim)
        return (src[i + m.end():e.start()], e.end()) if e else (None, i)
    m = re.match(r"\[(=*)\[", src[i:i + 12])                          # Lua long string [[ .. ]] / [==[ .. ]==]
    if m:
        j = src.find("]" + m.group(1) + "]", i, i + lim)
        return (src[i + m.end():j], j + len(m.group(0))) if j > 0 else (None, i)
    c = src[i:i + 1]
    if c in "\"'`":
        j = i + 1
        while j < len(src) and j < i + lim:
            if src[j] == "\\" and c != "`":
                j += 2
                continue
            if src[j] == c:
                return src[i + 1:j], j + 1
            j += 1
        return None, i
    if c == "{":                                                     # Tcl braces (nesting)
        depth, j = 0, i
        while j < len(src) and j < i + lim:
            depth += {"{": 1, "}": -1}.get(src[j], 0)
            if depth == 0:
                return src[i + 1:j], j + 1
            j += 1
        return None, i
    m = re.match(r"[|>](?:[-+]?\d?|\d[-+])[ \t]*(?:#[^\n]*)?\r?\n", src[i:i + 40])   # YAML block scalar
    if m and op == ":":
        ls = src.rfind("\n", 0, i) + 1
        base = len(src[ls:i]) - len(src[ls:i].lstrip(" \t"))
        body, j = [], i + m.end()
        for line in src[j:j + lim].split("\n"):
            if line.strip() and len(line) - len(line.lstrip(" \t")) <= base:
                break
            body.append(line)
            j += len(line) + 1
        return "\n".join(body), j
    if op in ("=", ":", ":="):                                       # YAML / INI / env plain scalar
        m = re.match(r"[^\s#;,\"'<>(){}\[\]]{8,}", src[i:i + lim])
        if m:
            text, j = m.group(0), i + m.end()
            # Makefile / Dockerfile / shell `\`-newline continuation: `X := aaaa\` + `bbbb\` + `cccc` (joined)
            while text.endswith("\\") and len(text) < lim:
                c = re.match(r"\r?\n[ \t]*([^\s#;,\"'<>(){}\[\]]+)", src[j:j + lim])
                if not c:
                    break
                text, j = text[:-1] + c.group(1), j + c.end()
            if op == ":" and not text.endswith("\\"):                 # YAML plain scalar folded over deeper lines
                base = _yaml_indent(src, i)
                while len(text) < lim:
                    c = _YAML_PLAIN_CONT.match(src, j)
                    if not c or len(c.group(1)) <= base:
                        break
                    text, j = text + c.group(2), c.end()
            return text, j
    return None, i


# JVM script readings (target jvm-dsl-script-route): Scala `"""|..|..""".stripMargin` (margin bars dropped) and Scala/
# Kotlin/Groovy `$name` / `${name}` templates resolved from plain `val|var|def|String name = ".."` literals in the
# same file. Appended after the literal's own reading, so every earlier reading keeps its place.
_JVM_TPL = re.compile(r"\$\{\s*([A-Za-z_]\w*)\s*\}|\$([A-Za-z_]\w*)")


def _jvm_readings(src, ident, lit, end, out):
    if re.match(r"\s*\.stripMargin\b", src[end:end + 40]):
        out.append((ident, re.sub(r"(?m)^[ \t]*\|", "", lit)))
    if "$" in lit and len(lit) < 1 << 16:
        bad = []

        def one(t):
            n = t.group(1) or t.group(2)
            v = re.search(r"(?:\bva[lr]|\bdef|\bString|\bfinal)[ \t]+" + re.escape(n) +
                          r"""[ \t]*(?::[ \t]*String[ \t]*)?=[ \t]*"([^"\\\r\n$]*)"(?=[ \t]*;?[ \t]*\r?\n|$)""", src)
            if not v:
                bad.append(n)
                return t.group(0)
            return v.group(1)
        r = _JVM_TPL.sub(one, lit)
        if not bad and r != lit:
            out.append((ident, r))


# YAML scalar semantics the raw literal reading above keeps verbatim (target yaml-scalar-carrier-twists): a double-quoted
# value's escapes (`\x41` `A` `\U0001..` `\n`, `\`-newline folding) and a `!!binary` value's base64 -> bytes (the
# descriptor text, e.g. dotted FRAG hex). Appended after the raw reading, so an existing plan keeps its place.
def _yaml_scalar_variants(src, i, op, lit, ident, out):
    if op != ":" or not lit:
        return
    try:
        pre = ""
        al = re.match(r"\*([\w-]+)", src[i:i + 80])
        if al:                                                       # alias: read the anchored node's tag / quoting
            a = re.search(r"(?<![\w*-])&" + re.escape(al.group(1)) + r"(?=[ \t\r\n])", src)
            if not a:
                return
            i, pre = a.start(), src[src.rfind("\n", 0, a.start()) + 1:a.start()]
        pm = _YAML_PROPS.match(src, i)
        props = (re.search(r"(?:!!?[\w:/.-]*[ \t]+)+$", pre) or re.match("", "")).group(0) + (pm.group(0) if pm else "")
        k = pm.end() if pm else i
        if src.startswith('"', k) and "\\" in lit:
            out.append((ident, _ci_ydq(lit)))
        elif re.search(r"!!binary\b|tag:yaml\.org,2002:binary", props):
            t = base64.b64decode(re.sub(r"\s+", "", lit), validate=True).decode("ascii")
            if t.isprintable():
                out.append((ident, t))
    except (ValueError, OverflowError, binascii.Error):
        pass


def _descriptor_literals_ext(src, limit=24):
    """(id, literal) of descriptor assignments in the wider syntax set above; concatenated pieces joined."""
    out = []
    for m in list(_XDESC_RE.finditer(src or "")) + list(_HDESC_RE.finditer(src or ""))[:8]:
        if len(out) >= limit:
            break
        b = _XBIND_RE.match(src, m.end())
        i, op = b.end(), b.group("op")
        if src.startswith("{", i) and m.group(0).lower().startswith("descriptor") and \
                not re.search(r"\bset\s*$", src[max(0, m.start() - 12):m.start()], re.I) and op is None:
            continue                                                 # `descriptor_x {` that is not a Tcl `set`
        lit, end = _read_literal(src, i, op)
        if lit is None and op == "=":                                # F# offside `let x =` + literal on the next line
            nl = re.match(r"""(?:[ \t]*\r?\n)+[ \t]+(?=["'])""", src[i:i + 400])
            if nl:
                lit, end = _read_literal(src, i + nl.end(), op)
        pm = None
        if lit is None and op in ("=", ":="):                         # Scala/Kotlin interpolator s".." f".." raw"""..."""
            pm = re.match(r"""(?:s|f|raw)(?=["'])""", src[i:i + 4])
            if pm:
                lit, end = _read_literal(src, i + pm.end(), None)
        if lit is None and op is None:
            lit = _yaml_sibling_value(src, m.start())
            if lit:
                out.append((m.group("id"), lit))
            continue
        if lit is None:
            continue
        pieces = [lit]
        while len(pieces) < 64:                                      # "a" + "b" / . / .. / & / ~ / || / F# ^, `& _` lines
            c = re.match(r"""\s*(?:\+|\.\.?|&|~|\|\||<>|\^)\s*(?:_[ \t]*\r?\n\s*)?(?=["'`])""", src[end:end + 200])
            if not c:
                break
            nxt, e2 = _read_literal(src, end + c.end(), None)
            if nxt is None:
                break
            pieces.append(nxt)
            end = e2
        out.append((m.group("id"), "".join(pieces)))
        if "\\\n" in out[-1][1] or "\\\r\n" in out[-1][1]:      # F# "aa\<newline>   bb": backslash-newline + indent dropped
            out.append((m.group("id"), re.sub(r"\\\r?\n[ \t]*", "", out[-1][1])))
        _yaml_scalar_variants(src, i, op, lit, m.group("id"), out)
        jm = _YAML_JINJA.fullmatch(out[-1][1])                       # Ansible "{{ 'blob' | b64decode }}"
        if jm:
            out.append((m.group("id"), jm.group(2)))
        _jvm_readings(src, m.group("id"), out[-1][1], end, out)
    for rx in _XML_DESC_RES:
        for m in rx.finditer(src or ""):
            if len(out) >= 2 * limit:
                break
            body = re.sub(r"<!\[CDATA\[(.*?)\]\]>", r"\1", m.group("body"), flags=re.S)
            if "<" in body:
                continue
            ident = m.groupdict().get("id") or (re.search(r"""\b(?:id|name|key)\s*=\s*["']([\w-]+)""", m.group("attrs") or "")
                                                or re.match(r"descriptor[_-]?(.*)", m.group("tag"), re.I)).group(1)
            out.append((ident, body))
    return out


# AutoHotkey v1 legacy descriptor forms (target ahk-compiled-exe-extract): a continuation section
# `descriptor_x =` / `:= "` + `(Join..` lines `)` (`)"` closes the quoted form) and `descriptor_x .= ".."` / `.= text`
# appends. Only ids that use one of these AHK constructs are returned (whole value accumulated in source order), so a
# plain `descriptor_x = ..` keeps its earlier reading.
_AHK_ASSIGN_RE = re.compile(r"""^[ \t]*(?:global[ \t]+|static[ \t]+|local[ \t]+)?descriptor_(?P<id>\w+)[ \t]*(?P<op>\.=|:=|=)"""
                            r"""[ \t]*(?P<rest>[^\r\n]*)""", re.M)
_AHK_CONT_OPEN_RE = re.compile(r"""\r?\n[ \t]*\((?P<opts>[^\r\n)]*)\r?\n""")


def _ahk_value(rest, op):
    """Value of a one-line AHK v1 assignment: `:=`/`.=` take quoted pieces joined by ` . `; legacy `=` the raw text."""
    rest = re.sub(r"""[ \t]+;.*$""", "", rest).strip()
    if op == "=" or (op == ".=" and rest[:1] not in "\"'"):
        return rest or None
    pieces = re.findall(r'"((?:[^"]|"")*)"', rest)
    return "".join(x.replace('""', '"') for x in pieces) if pieces else None


def _ahk_literals(src, limit=16):
    """(id, value) of descriptors written with an AHK continuation section or `.=` appends; [] otherwise."""
    if not src or "descriptor_" not in src:
        return []
    vals, special = {}, set()
    for m in _AHK_ASSIGN_RE.finditer(src[:1 << 20]):
        ident, op, rest = m.group("id"), m.group("op"), m.group("rest").strip()
        val = None
        if rest in ("", '"') and op in ("=", ":="):
            c = _AHK_CONT_OPEN_RE.match(src, m.end())
            if c:
                body, j = [], c.end()
                for line in src[j:j + (1 << 16)].split("\n"):
                    if re.match(r"[ \t]*\)", line):
                        break
                    body.append(line.rstrip("\r"))
                else:
                    continue
                opts = c.group("opts")
                jm = re.search(r"\bjoin(\S*)", opts, re.I)
                lines = [ln.strip() for ln in body]                  # LTrim/RTrim: indentation never part of a blob
                sep = (jm.group(1).replace("`s", " ").replace("`n", "\n").replace("`t", "\t") if jm else "\n")
                val = sep.join(lines)
                special.add(ident)
        elif rest:
            val = _ahk_value(rest, op)
        if val is None:
            continue
        if op == ".=":
            special.add(ident)
            vals[ident] = vals.get(ident, "") + val
        else:
            vals[ident] = val
    return [(k, v) for k, v in vals.items() if k in special and v][:limit]


# Compiled-language descriptor literals (target compiled-lang-source-route): Rust `r#".."#` / `br".."`, Swift `#".."#` /
# `#"""..."""#`, Nim / Dart `r".."` / `r'''..'''`, Zig `\\` multi-line strings, `\u{..}` / `\xNN` escapes (Rust/Swift),
# binders the wider set misses (Zig `: []const u8 =`, Nim `descriptor_x* =`, Dart `const String x =`) and Dart / C
# adjacent-literal concatenation `'a'\n 'b';`. Read only as a gap (no plan elsewhere) or, when an escape / adjacency
# reading extends an existing plan, ahead of that lossy prefix reading. Pure regex, bounded, never raises.
_CL_DESC = re.compile(r"""descriptor[_-](?P<id>\w+)[ \t]*\*?[ \t]*(?::[ \t]*(?:&'[A-Za-z_]\w*|\[[^\]\r\n=]{1,24}\]|[^=\r\n;{}()"'`]){1,48}?[ \t]*)?(?::=|=)[ \t]*""", re.I)
_CL_ESC = re.compile(r"""\\(u\{[0-9A-Fa-f]{1,6}\}|u[0-9A-Fa-f]{4}|x[0-9A-Fa-f]{2}|\r?\n[ \t]*|.)""", re.S)
_CL_SIMPLE = {"n": "\n", "t": "\t", "r": "\r", "0": "\0", "\\": "\\", '"': '"', "'": "'", "`": "`", "$": "$"}


def _cl_unescape(s):
    def one(m):
        e = m.group(1)
        if e[0] in "ux" and len(e) > 1:
            return chr(int(e.strip("u{}x") if e[0] == "u" else e[1:], 16))
        if e[0] in "\r\n":                                     # Rust / Swift `\`-newline: next line's indent dropped
            return ""
        return _CL_SIMPLE.get(e, "\\" + e)
    return _CL_ESC.sub(one, s)


def _cl_literal(src, i):
    """(text, end, novel) of one compiled-language string literal at src[i], else (None, i, False)."""
    lim = 1 << 16
    m = re.match(r"""(?:b?r(#*)|(#+))(\"\"\"|'''|"|')""", src[i:i + 80])   # raw: Rust r#"..# / Swift #".."# / r'..'
    if m:
        hashes, q = m.group(1) or m.group(2) or "", m.group(3)
        j = src.find(q + hashes, i + m.end(), i + lim)
        if j < 0:
            return None, i, False
        body = src[i + m.end():j]
        if m.group(2) and len(q) == 3:
            body = _cl_dedent(body)
        return body, j + len(q) + len(hashes), True
    m = re.match(r"(?:[ \t]*\r?\n)*[ \t]*\\\\", src[i:i + 400])                 # Zig `\\line` multi-line string
    if m:
        lines, j = [], i
        for z in re.finditer(r"[ \t]*\\\\([^\r\n]*)\r?\n?", src[i:i + lim]):
            if z.start() != j - i and not re.fullmatch(r"\s*", src[j:i + z.start()]):
                break
            lines.append(z.group(1))
            j = i + z.end()
        return ("\n".join(lines), j, True) if lines else (None, i, False)
    t = src[i:i + 3]
    if t in ('"""', "'''"):
        j = src.find(t, i + 3, i + lim)
        if j < 0:
            return None, i, False
        body = _cl_dedent(src[i + 3:j])
        u = _cl_unescape(body)
        return u, j + 3, u != body
    c = src[i:i + 1]
    if c in "\"'":
        j = i + 1
        while j < len(src) and j < i + lim and src[j] not in "\r\n" + c:
            j += 2 if src[j] == "\\" else 1
        if j >= len(src) or src[j] != c:
            if j < len(src) and src[j] in "\r\n" and src[j - 1] == "\\":    # `"aa\` + newline continuation
                k = src.find(c, j, i + lim)
                while k > 0 and src[k - 1] == "\\":
                    k = src.find(c, k + 1, i + lim)
                if k > 0:
                    body = src[i + 1:k]
                    return _cl_unescape(body), k + 1, True
            return None, i, False
        body = src[i + 1:j]
        u = _cl_unescape(body)
        return u, j + 1, u != body
    return None, i, False


# Rust value expressions (target rust-cargo-buildrs-route): `concat!("a", r#"b"#, 'c', 1)`, byte strings `b".."` /
# `br#".."#`, `[u8; N]` / `&[118, 61, 0x33]` arrays, `vec![..]`, `String::from(..)` / `String::from_utf8(vec![..])` /
# `str::from_utf8(&[..])` / `_lossy` wrappers and a trailing `.to_string()` / `.unwrap()`. Statically folded, never run.
_RS_WRAP = re.compile(r"""\s*(?:(?:(?:std|core|alloc)::)?(?:(?:string|str)::)?(?:String|str)::from(?:_utf8(?:_lossy)?)?\s*\(|"""
                      r"""(?:std::)?concat!\s*[(\[{]|vec!\s*(?=\[)|&(?:'static\s+)?|\*)""")
_RS_INT = re.compile(r"\s*(0x[0-9A-Fa-f_]+|0o[0-7_]+|0b[01_]+|\d[\d_]*)(?:_?u8)?\s*(,|\])")


def _rs_value(src, i):
    """(text, end) of one Rust descriptor value expression at src[i] (see above), else (None, i)."""
    try:
        cat, depth = False, 0
        while depth < 6:
            w = _RS_WRAP.match(src, i, i + 200)
            if not w or w.end() == i:
                break
            cat, i, depth = cat or "concat!" in w.group(0), w.end(), depth + 1
        pieces, j = [], i
        while len(pieces) < 256:
            k = j + len(re.match(r"\s*", src[j:j + 200]).group(0))
            if src[k:k + 1] == "[":                                     # byte array
                vals, p = [], k + 1
                while len(vals) < 1 << 16:
                    m = _RS_INT.match(src, p, p + 64)
                    if not m:
                        break
                    s = m.group(1).replace("_", "").lower()
                    vals.append(int(s, 0) if s[:2] in ("0x", "0o", "0b") else int(s))
                    p = m.end()
                    if m.group(2) == "]":
                        break
                    if re.match(r"\s*\]", src[p:p + 64]):
                        p += len(re.match(r"\s*\]", src[p:p + 64]).group(0))
                        break
                if not vals or max(vals) > 255 or src[p - 1] != "]":
                    return None, i
                b = bytes(vals)
                try:
                    t = b.decode("utf-8")
                except UnicodeDecodeError:
                    t = b.decode("latin-1")
                pieces.append(t)
                j = p
            elif cat and re.match(r"-?\d[\d_.]*\b", src[k:k + 40]):    # concat! numeric / bool literal
                n = re.match(r"-?\d[\d_.]*\b|true\b|false\b", src[k:k + 40]).group(0)
                pieces.append(n)
                j = k + len(n)
            else:
                b0 = k + 1 if src[k:k + 2] in ('b"', "b'") else k
                lit, e, _ = _cl_literal(src, b0)
                if lit is None:
                    break
                pieces.append(lit)
                j = e
            if not cat:
                break
            c = re.match(r"\s*,", src[j:j + 200])
            if not c:
                break
            j += c.end()
        if not pieces or (cat and not re.match(r"\s*,?\s*[)\]}]", src[j:j + 200])):
            return None, i
        return "".join(pieces), j
    except Exception:  # noqa: BLE001
        return None, i


def _cl_dedent(body):
    """Swift / Dart multi-line literal: drop the opening newline and the closing delimiter's indentation."""
    body = re.sub(r"^[ \t]*\r?\n", "", body)
    ind = re.search(r"\n([ \t]*)$", body)
    if ind:
        body = body[:ind.start()]
        body = re.sub(r"(?m)^" + re.escape(ind.group(1)), "", body) if ind.group(1) else body
    return body


def _cl_literals(src, limit=24):
    """[(id, text, extends)] of compiled-language descriptor literals; `extends` = an escape / adjacency / continuation
    reading that may complete a lossy first-piece reading."""
    out = []
    if not src or not re.search(r"(?i)descriptor[_-]", src):
        return out
    for m in _CL_DESC.finditer(src[:1 << 20]):
        if len(out) >= limit:
            break
        lit, end, novel = _cl_literal(src, m.end())
        if lit is None:
            lit, end = _rs_value(src, m.end())                      # Rust concat! / b"" / [u8] / from_utf8(vec![..])
            if lit is None:
                continue
            novel = True
        pieces, ext = [lit], novel
        while len(pieces) < 64:                    # "a" + "b" / ++ / & / .. / ~, Dart/C adjacent 'a' 'b' (then ; or ))
            c = re.match(r"""\s*(\+\+|\+|&|\.\.|~)?\s*(?=b?r#*["']|#+["']|["']|[ \t]*\\\\)""", src[end:end + 200])
            if not c:
                break
            nxt, e2, nv = _cl_literal(src, end + c.end())
            if nxt is None:
                break
            if not c.group(1):
                k = e2
                while True:
                    s2 = re.match(r"\s*(?=[\"'])", src[k:k + 200])
                    nn = _cl_literal(src, k + s2.end()) if s2 else (None, k, False)
                    if nn[0] is None:
                        break
                    k = nn[1]
                if not re.match(r"\s*[;),]", src[k:k + 200]):
                    break
                ext = True
            pieces.append(nxt)
            end, ext = e2, ext or nv
        out.append((m.group("id"), "".join(pieces), ext))
    return out


def _cl_codecs(src, extend_only=False, budget=0.5):
    """Plan codecs of compiled-language descriptor literals (see _cl_literals); [] when none reads to a plan."""
    try:
        end, out = time.time() + budget, []
        am = _ANALYSIS_RE.search(src or "")
        for ident, lit, ext in _cl_literals(src):
            if time.time() > end or (extend_only and not ext):
                continue
            plain = _peel_ext([(ident, lit)], am.group("tag") if am else "", budget=max(0.05, end - time.time()))[1]
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "", "material": lit,
                            "plain": plain})
        return out
    except Exception:  # noqa: BLE001
        return []


# Nim / Swift / Tcl descriptor values the literal readings above miss (target nim-swift-tcl-literal-route): Tcl
# `append descriptor_x ..` accumulation and `[binary decode base64|hex ..]` / `[join $l ""]` / `[string reverse ..]` /
# `$var` substitution (a `#` comment counts only at command start); Swift `String(decoding: [UInt8], as: UTF8.self)` /
# `String(bytes:encoding:)` / `Data(base64Encoded: "..")`; Nim `cast[string](@[byte 0x41, ..])` / `decode("..")`.
# Read only as a gap after every earlier reading (or a longer plan extending one), so existing results are unchanged.
_NST_CUE = re.compile(r"(?i)(?:^|[;\[])[ \t]*(?:set|append|lappend)[ \t]+descriptor[_-]|descriptor[_-][\w-]*\*?[ \t]*"
                      r"(?::[^=\r\n]{1,40})?=[ \t]*(?:String|cast|Data|decode|\[|@\[)", re.M)
_NST_TCL_ESC = {"n": "\n", "t": "\t", "r": "\r", "a": "\a", "b": "\b", "f": "\f", "v": "\v"}


def _nst_tcl_bs(src, j):
    """(text, end) of the Tcl backslash sequence at src[j] == '\\'."""
    c = src[j + 1:j + 2]
    m = re.match(r"x([0-9a-fA-F]{1,2})|u([0-9a-fA-F]{1,4})|U([0-9a-fA-F]{1,8})|([0-7]{1,3})", src[j + 1:j + 10])
    if m:
        v = int(m.group(1) or m.group(2) or m.group(3) or "0", 16) if not m.group(4) else int(m.group(4), 8)
        return (chr(v) if v < 0x110000 else ""), j + 1 + m.end()
    if c == "\n":
        k = j + 2
        while k < len(src) and src[k] in " \t":
            k += 1
        return " ", k
    return _NST_TCL_ESC.get(c, c), j + 2


def _nst_tcl_word(src, i, env, depth):
    """(value, end) of one Tcl word at src[i] (quotes, braces, `[cmd]`, `$var`, bare), or (None, i)."""
    if depth > 6 or i >= len(src):
        return None, i
    if src[i] == "{":
        lv, j = 0, i
        while j < len(src) and j < i + (1 << 16):
            if src[j] == "\\":
                j += 2
                continue
            lv += {"{": 1, "}": -1}.get(src[j], 0)
            if lv == 0:
                return src[i + 1:j], j + 1
            j += 1
        return None, i
    quoted = src[i] == '"'
    j, buf = i + 1 if quoted else i, []
    while j < len(src) and j < i + (1 << 16):
        c = src[j]
        if quoted and c == '"':
            return "".join(buf), j + 1
        if not quoted and (c in " \t\r\n;]"):
            break
        if c == "\\":
            t, j = _nst_tcl_bs(src, j)
            buf.append(t)
        elif c == "[":
            v, j2 = _nst_tcl_cmd(src, j + 1, env, depth + 1)
            if v is None:
                return None, i
            buf.append(v if isinstance(v, str) else " ".join(v))
            j = j2
        elif c == "$":
            m = re.match(r"\{([^}]+)\}|((?:::)?[A-Za-z_][\w:]*)", src[j + 1:j + 80])
            if not m or (m.group(1) or m.group(2)) not in env:
                return None, i
            v = env[m.group(1) or m.group(2)]
            buf.append(v if isinstance(v, str) else " ".join(v))
            j += 1 + m.end()
        else:
            buf.append(c)
            j += 1
    return (None, i) if quoted else ("".join(buf), j)


def _nst_tcl_list(v):
    if isinstance(v, list):
        return v
    out, i = [], 0
    while i < len(v):
        while i < len(v) and v[i] in " \t\r\n":
            i += 1
        if i >= len(v):
            break
        w, e = _nst_tcl_word(v, i, {}, 5)
        if w is None or e <= i:
            return v.split()
        out.append(w)
        i = e
    return out


def _nst_bytes_text(b):
    """Decoded bytes as descriptor text: printable UTF-8 verbatim, else base64 (so the peel sees a binary layer)."""
    try:
        t = b.decode("utf-8")
        if t.strip() and all(ch.isprintable() or ch in "\r\n\t" for ch in t):
            return t
    except UnicodeDecodeError:
        pass
    return base64.b64encode(b).decode("ascii")


def _nst_tcl_cmd(src, i, env, depth):
    """(value, end after `]`) of the Tcl command substitution starting at src[i] (just past `[`), or (None, i)."""
    words, j = [], i
    while j < len(src) and len(words) < 512:
        while j < len(src) and src[j] in " \t\r\n" or src.startswith("\\\n", j):
            j += 2 if src[j] == "\\" else 1
        if j >= len(src):
            return None, i
        if src[j] == "]":
            break
        w, e = _nst_tcl_word(src, j, env, depth)
        if w is None or e <= j:
            return None, i
        words.append(w)
        j = e
    else:
        return None, i
    j += 1
    if not words:
        return None, i
    w0, args = words[0], words[1:]
    try:
        if w0 == "binary" and len(args) >= 3 and args[0] == "decode":
            data = args[-1]
            if args[1] == "base64":
                return _nst_bytes_text(base64.b64decode(re.sub(r"\s+", "", data) + "==="[:(-len(re.sub(r"\s+", "", data))) % 4])), j
            if args[1] == "hex":
                return _nst_bytes_text(bytes.fromhex(re.sub(r"[^0-9a-fA-F]", "", data))), j
            return None, i
        if w0 == "binary" and len(args) == 3 and args[0] == "format" and args[1] in ("H*", "a*", "A*"):
            return (_nst_bytes_text(bytes.fromhex(args[2])) if args[1] == "H*" else args[2]), j
        if w0 == "list":
            return list(args), j
        if w0 == "join" and 1 <= len(args) <= 2:
            return (args[1] if len(args) == 2 else " ").join(_nst_tcl_list(args[0])), j
        if w0 == "string" and len(args) == 2 and args[0] == "reverse":
            return args[1][::-1], j
        if w0 == "encoding" and args and args[0] == "convertfrom":
            return args[-1], j
        if w0 == "set" and len(args) == 1 and args[0] in env:
            return env[args[0]], j
        if w0 == "concat":
            return " ".join(a.strip() for a in args if a.strip()), j
    except (ValueError, binascii.Error, TypeError):
        pass
    return None, i


_NST_TCL_STMT = re.compile(r"(?m)(?:^|;)[ \t]*(?P<cmd>set|append|lappend)[ \t]+(?P<name>(?:::)?[A-Za-z_][\w:-]*)[ \t]+")


def _nst_tcl_literals(src):
    """(id, value) of Tcl descriptor variables built with `append` / `lappend` or a `[..]` command substitution."""
    env, special, out = {}, set(), []
    for m in _NST_TCL_STMT.finditer(src[:1 << 20]):
        name, cmd, j, vals = m.group("name"), m.group("cmd"), m.end(), []
        while j < len(src) and src[j] not in "\r\n;]" and len(vals) < 256:
            w, e = _nst_tcl_word(src, j, env, 0)
            if w is None or e <= j:
                vals = None
                break
            vals.append(w)
            j = e
            while j < len(src) and src[j] in " \t" or src.startswith("\\\n", j):
                j += 2 if src[j] == "\\" else 1
        if not vals:
            continue
        if cmd == "set":
            if len(vals) == 1:
                env[name] = vals[0]
                if "[" in src[m.end():j] or "$" in src[m.end():j]:
                    special.add(name)
            continue
        if cmd == "append":
            env[name] = (env.get(name, "") if isinstance(env.get(name, ""), str) else "") + "".join(
                v if isinstance(v, str) else " ".join(v) for v in vals)
        else:
            env[name] = _nst_tcl_list(env.get(name, [])) + list(vals)
        special.add(name)
    for name in special:
        dm = re.match(r"(?i)(?:::)?descriptor[_-]([\w-]+)$", name)
        v = env.get(name)
        if dm and v:
            out.append((dm.group(1), v if isinstance(v, str) else "".join(v)))
    return out


_NST_BYTE_ARR = r"(?:\[UInt8\][ \t]*\(|cast\[string\][ \t]*\(|@)?[ \t]*\[(?:[ \t]*byte\b)?(?P<arr>[^\]\[]{1,1048576}?)\]"
_NST_BYTE_EL = re.compile(r"(?:0[xX][0-9a-fA-F_]+|0[oO][0-7_]+|0[bB][01_]+|\d+)(?:'?[uU]8)?$")


def _nst_byte_list(body):
    out = bytearray()
    for el in body.replace("\n", " ").split(","):
        el = el.strip()
        if not el:
            continue
        if not _NST_BYTE_EL.match(el):
            return None
        el = re.sub(r"'?[uU]8$", "", el).replace("_", "")
        v = int(el, 0) if not re.match(r"0\d", el) else int(el)
        if v > 255:
            return None
        out.append(v)
    return bytes(out) if out else None


_NST_SWIFT_RHS = re.compile(r"""(?:String[ \t]*\([ \t]*(?:decoding|bytes|cString)[ \t]*:|cast\[string\][ \t]*\(|"""
                            r"""String[ \t]*\([ \t]*data[ \t]*:[ \t]*|Data[ \t]*\([ \t]*base64Encoded[ \t]*:|"""
                            r"""(?:base64\.)?decode[ \t]*\(|(?=@?\[))[ \t]*""")


def _nst_call_literals(src, limit=16):
    """(id, value) of Swift / Nim descriptors bound to a byte array, a String(decoding:..) / cast[string] of one, or a
    Data(base64Encoded:) / decode() call wrapping a single string literal."""
    out = []
    for m in _CL_DESC.finditer(src[:1 << 20]):
        if len(out) >= limit:
            break
        r = _NST_SWIFT_RHS.match(src, m.end())
        if not r:
            continue
        k = r.end()
        if src.startswith("Data", k):                                 # String(data: Data(base64Encoded: "..")!, ..)
            r2 = re.match(r"Data[ \t]*\([ \t]*base64Encoded[ \t]*:[ \t]*", src[k:k + 40])
            if not r2:
                continue
            k += r2.end()
        if src[k:k + 1] in "\"'":
            lit, _ = _read_literal(src, k, None)
            if lit:
                out.append((m.group("id"), lit))
            continue
        a = re.compile(_NST_BYTE_ARR).match(src, k)
        if not a:
            n = re.match(r"([A-Za-z_]\w*)\b", src[k:k + 80])
            if not n:
                continue
            a = re.compile(r"(?:let|var|const)[ \t]+" + re.escape(n.group(1)) + r"[ \t]*(?::[ \t]*[^=\r\n]{1,40})?=[ \t]*"
                           + _NST_BYTE_ARR).search(src)
            if not a:
                continue
        b = _nst_byte_list(a.group("arr"))
        if b:
            out.append((m.group("id"), _nst_bytes_text(b)))
    return out


def _nst_codecs(src, budget=0.5):
    """Plan codecs of the Nim / Swift / Tcl descriptor values above; [] when none reads to a plan."""
    try:
        end, out = time.time() + budget, []
        am = _ANALYSIS_RE.search(src or "")
        lits = (_nst_tcl_literals(src) if re.search(r"(?m)(?:^|;)[ \t]*(?:set|append|lappend)[ \t]", src) else []) + \
            _nst_call_literals(src)
        for ident, lit in lits:
            if time.time() > end:
                break
            plain = _peel_ext([(ident, lit)], am.group("tag") if am else "", budget=max(0.05, end - time.time()))[1]
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "", "material": lit,
                            "plain": plain})
        return out
    except Exception:  # noqa: BLE001
        return []


def _peel_ext(lits, tag="", tried=(), budget=1.5):
    """First plan among the wider literals (whitespace-joined first: wrapped base64/hex/base32 lines), or (None, None)."""
    import time
    end, seen = time.time() + budget, set(tried)
    for ident, lit in lits:
        for cand in (re.sub(r"\s+", "", lit), lit.strip()):
            if not cand or cand in seen or time.time() > end:
                continue
            seen.add(cand)
            plain = peel_plan(cand, tag, budget=min(0.4, max(0.05, end - time.time())))
            if plain:
                return ident, plain
    return None, None


# Game-engine / modding script descriptors (target game-script-language-route), the D23 GDScript siblings. Luau, Ren'Py
# (`define` / `init python:` / `$ x =`), GML `#macro` / `global.x`, AngelScript `const string`, UnrealScript
# `defaultproperties`, Unity C# `[SerializeField]` and LÖVE Lua already read through _descriptor_literals_ext; this adds
# the forms it misses: a Squirrel / C# / GML verbatim `@"..."` (`""` -> `"`, multi-line), a Pawn array `new const
# descriptor_x[] = "..."` (packed `!"`, adjacent / `...`-joined pieces, `\xHH;` / `\ddd;` / backslash-newline escapes,
# `#pragma ctrlchar`), and an mcfunction `data modify storage ns:descriptor_x set value "..."` (SNBT escapes, `\` line
# continuation). Only those special forms are returned; find_codecs() uses them for a gap or a full plan ahead of a
# lossy first-piece reading, so every earlier reading keeps its place.
_GM_DESC = re.compile(r"""descriptor[_-](?P<id>\w+)(?P<arr>[ \t]*\[[ \t]*\w*[ \t]*\])?(?:[ \t]*:[ \t]*[\w.<>\[\]]+)?"""
                      r"""(?P<op>[ \t]*=(?!=)|(?:[ \t]|\\\r?\n)+set(?:[ \t]|\\\r?\n)+value(?:[ \t]|\\\r?\n)+)[ \t]*""", re.I)
_GM_CTRL = re.compile(r"""^[ \t]*#[ \t]*pragma[ \t]+ctrlchar[ \t]+(?:'(?P<c>[^'\r\n])'|(?P<n>\d{1,3}))""", re.M)
_GM_JOIN = re.compile(r"""\s*(?:\.\.\.|\+|\.\.)?\s*(?=[!@]?["'])""")


def _gm_string(src, i, ctrl="\\"):
    """(value, end, special) of the game-script string literal at src[i], else (None, i, False)."""
    lim, n = i + (1 << 16), len(src)
    pre = src[i] if src[i:i + 1] in ("@", "!") else ""
    j = i + len(pre)
    q = src[j:j + 1]
    if q not in ("'", '"'):
        return None, i, False
    out, j, special = [], j + 1, bool(pre)
    while j < n and j < lim:
        c = src[j]
        if pre == "@":                                               # verbatim: no escapes, `""` is one quote
            if c == q:
                if src[j + 1:j + 2] == q:
                    out.append(q)
                    j += 2
                    continue
                return "".join(out), j + 1, True
            out.append(c)
            j += 1
            continue
        if c == ctrl and j + 1 < n:
            special = True
            m = re.match(r"x([0-9A-Fa-f]{1,6});?|(\d{1,3});?|(\r?\n)[ \t]*|(.)", src[j + 1:j + 10], re.S)
            if m.group(1):
                out.append(chr(int(m.group(1), 16)))
            elif m.group(2):
                out.append(chr(int(m.group(2)) & 0x10FFFF))
            elif m.group(4):
                out.append({"n": "\n", "t": "\t", "r": "\r", "a": "\a", "b": "\b", "e": "\x1b", "f": "\f",
                            "v": "\v"}.get(m.group(4), m.group(4)))
            j += 1 + m.end()
            continue
        if c == q:
            return "".join(out), j + 1, special
        if c in "\r\n":
            return None, i, False
        out.append(c)
        j += 1
    return None, i, False


def _gm_literals(src, limit=24):
    """(id, literal) of the special-form game-script descriptor assignments above (concatenated pieces joined)."""
    out = []
    if not src or "descriptor" not in src.lower():
        return out
    cm = _GM_CTRL.search(src[:1 << 16])
    ctrl = (cm.group("c") or chr(int(cm.group("n")))) if cm else "\\"
    for m in _GM_DESC.finditer(src):
        if len(out) >= limit:
            break
        i = m.end()
        v, end, special = _gm_string(src, i, ctrl)
        if v is None:
            continue
        pieces = [v]
        while len(pieces) < 64:
            c = _GM_JOIN.match(src, end)
            if not c or c.end() == end:
                break
            nxt, e2, sp2 = _gm_string(src, c.end(), ctrl)
            if nxt is None:
                break
            pieces.append(nxt)
            special, end = special or sp2, e2
        if special or m.group("arr") or "set" in m.group("op").lower():
            out.append((m.group("id"), "".join(pieces)))
    return out


def _gm_codecs(src, extend_only=False, budget=0.4):
    """Plan codecs of game-script descriptor literals (see _gm_literals); [] when none reads to a plan."""
    try:
        end, out = time.time() + budget, []
        am = _ANALYSIS_RE.search(src or "")
        for ident, lit in _gm_literals(src):
            if time.time() > end:
                break
            plain = _peel_ext([(ident, lit)], am.group("tag") if am else "", budget=max(0.05, end - time.time()))[1]
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "", "material": lit,
                            "plain": plain})
        return out
    except Exception:  # noqa: BLE001
        return []


_MARK_CONT_RE = re.compile(r"""^[ \t]*(?:#|//|--|;+|'|REM\b|::|\*|%|!)?[ \t]*([A-Za-z0-9+/=_\-.%~:]+)[ \t]*\r?$""")


def _marker_continued(src, am):
    """The v=3 marker material with its wrapped continuation lines appended (block comments / =begin / <# #> / YAML
    folded lines): following lines holding one material-charset token after an optional comment leader."""
    if am.string is not src:
        return []
    parts, pos = [am.group("mat")], am.end()
    rest = src[pos:pos + (1 << 16)]
    if rest[:1] not in ("\r", "\n"):
        return []
    variants = []
    for line in rest.lstrip("\r").split("\n")[1:65]:
        if re.match(r"\s*(?:=\w+|\"\"\"|'''|#>|\*/|-->|\]\])\s*$", line):
            break
        m = _MARK_CONT_RE.match(line)
        if not m or not m.group(1):
            break
        parts.append(m.group(1))
        variants.append("".join(parts))
    return variants[::-1][:4]


# The marker split across several comment lines (target yaml-scalar-carrier-twists): `# HUNTRESS_ANALYSIS_V1:` (or
# `:<TAG>-`) with the material on the following lines, and a `<TAG>-<material>` whose first line alone peels to a
# truncated prefix plan. Continuation lines must carry the marker line's own comment leader (`#`, `//`, `;` ..), so
# code / YAML (`---`, `end`) after a one-line marker never extends it; a one-line marker reads exactly as before.
_ANALYSIS_BARE_RE = re.compile(r"HUNTRESS_ANALYSIS_V(\d+):(?:([A-Za-z0-9_]+)-)?[ \t]*\r?\n")


# An EEx `<%#` / HEEx `<%!--` / HTML `<!--` block comment opened on the marker line (target eex-heex-template-carrier)
# stays open over bare material lines up to its `%>` / `--%>` / `-->` closer, which no material token matches.
_MARK_BLOCK_OPEN = ("<%!--", "<%#", "<!--")


def _marker_lines(src, start, end):
    """Material tokens of the comment lines after the marker line [start:end) sharing its leader (or any bare line
    inside a still-open EEx/HEEx/HTML block comment); [] when none."""
    ls = src.rfind("\n", 0, start) + 1
    lead = src[ls:start].strip()
    block = lead in _MARK_BLOCK_OPEN
    if not lead or (len(lead) > 4 and not block):
        return []
    parts = []
    for line in src[end:end + (1 << 16)].lstrip("\r").split("\n")[1:65]:
        s = line.strip()
        m = _MARK_CONT_RE.match(line) if block or s.startswith(lead) else None
        if not m or not m.group(1):
            break
        parts.append(m.group(1))
    return parts


def _marker_bare(src):
    """An _ANALYSIS_RE match over the rejoined `HUNTRESS_ANALYSIS_V1:` + continuation-line material, else None."""
    try:
        bm = _ANALYSIS_BARE_RE.search(src, 0, 1 << 20)
        if not bm:
            return None
        parts = _marker_lines(src, bm.start(), bm.end() - 1)
        joined = (bm.group(2) + "-" if bm.group(2) else "") + "".join(parts)
        return _ANALYSIS_RE.fullmatch("HUNTRESS_ANALYSIS_V%s:%s" % (bm.group(1), joined)) if parts else None
    except Exception:  # noqa: BLE001
        return None


def _marker_extended(src, am, plain):
    """The longer plan of a marker wrapped over same-leader comment lines when it extends `plain`; else `plain`."""
    try:
        if am.string is not src or src[am.end():am.end() + 1] not in ("\r", "\n"):
            return plain
        parts = _marker_lines(src, am.start(), am.end())
        if not parts:
            return plain
        p = peel_plan(am.group("mat") + "".join(parts), am.group("tag"))
        if p and len(p) >= len(plain) + 8 and p.startswith(plain[:max(8, len(plain) - 8)]):
            return p
    except Exception:  # noqa: BLE001
        pass
    return plain

# D18 Google Apps Script v=3 fixtures: a bare `// HUNTRESS_ANALYSIS_V1:SPLIT` marker (no `-<material>`) and the material
# as an array of string-literal chunks, `const X = ["<TAG>-chunk", "chunk", ..].join("")` (TAG = B64/HEX/HB64/FRAG),
# plus an untagged copy. The same split carrier in the other host syntaxes reads through three name-agnostic shapes:
#  - separator runs: quoted literals (r/b/u/@/$ prefixes, Lua [[..]]) joined by `,` `;` `+` `&` `..` `.` whitespace or a
#    line continuation (`_` / backtick / `\`) -- JS/AHK/Python `[..]`, tuples, PS `@(..)` / `"a","b"`, Lua `{..}`, Perl
#    `(..)`, VBS `Array(..)`, AutoIt `[..]`, AppleScript `{..}`, implicit/explicit concatenation;
#  - word lists: Perl `qw(..)`, Ruby `%w[..]`;
#  - line runs: consecutive lines holding one value each -- `x += "c"` / `push @a, "c"` / `table.insert(t, "c")` /
#    `$a[1] = "c"` / `set end of L to "c"`, batch `set c1=..` / `set "c1=.."` / `set x=%x%..`, XML `<Chunk>..</Chunk>`
#    and `<Chunk Include=".." />` (MSBuild).
# A joined run is peeled from its first chunk and from every `<TAG>-` chunk (tag stripped, and kept); only a plan counts.
_SPLIT_MARK_RE = re.compile(r"HUNTRESS_ANALYSIS_V\d+:SPLIT\b")
_SPLIT_LIT = re.compile(r"""(?<![\w"'`])[rRbBuU@$]{0,2}(?:"([^"\r\n]*)"|'([^'\r\n]*)'|`([^`$\r\n]*)`)|\[\[([^\]\r\n]*)\]\]""")
_SPLIT_SEP = re.compile(r"""(?:\s|[,;+&.]|_[ \t]*\r?\n|`[ \t]*\r?\n|\\[ \t]*\r?\n)*""")
_SPLIT_VAL = re.compile(r"[A-Za-z0-9+/=_\-.%~:]+")
_SPLIT_TAG = re.compile(r"([A-Za-z0-9_]{1,12})-(.+)$", re.S)
_SPLIT_WORDS = re.compile(r"(?:\bqw|%[wW])\s*([\[({</|!])")
_SPLIT_CLOSE = {"[": "]", "(": ")", "{": "}", "<": ">"}
_SPLIT_BAT = re.compile(r"""^[ \t]*@?set[ \t]+"?(?P<n>[^=\s"/][^=\s"]*)=(?P<v>[^"\r\n]*?)"?[ \t]*$""", re.I)
_SPLIT_XML = re.compile(r"<(?P<t>[A-Za-z_][\w.:-]*)\b[^<>]*>(?P<v>[^<>\r\n]+)</(?P=t)\s*>")


def _split_runs(src):
    """Joined chunk lists (list of value lists) of a source, in the three shapes above."""
    runs, cur, prev = [], [], None
    for m in _SPLIT_LIT.finditer(src):                                   # separator runs
        v = next((g for g in m.groups() if g is not None), "")
        if prev is not None and (m.start() - prev > 400 or not _SPLIT_SEP.fullmatch(src, prev, m.start())):
            if len(cur) > 1:
                runs.append(cur)
            cur = []
        cur.append(v)
        prev = m.end()
    if len(cur) > 1:
        runs.append(cur)
    for m in _SPLIT_WORDS.finditer(src):                                 # qw(..) / %w[..]
        close = _SPLIT_CLOSE.get(m.group(1), m.group(1))
        j = src.find(close, m.end())
        if 0 < j - m.end() < (1 << 16):
            runs.append(src[m.end():j].split())
    cur = []                                                              # one value per line
    for line in src.splitlines() + [""]:
        v = None
        bm = _SPLIT_BAT.match(line)
        if bm:
            v = re.sub(r"%" + re.escape(bm.group("n")) + r"%|!" + re.escape(bm.group("n")) + "!", "", bm.group("v"))
            v = None if re.search(r"%[A-Za-z_][\w.$#@-]*%|![A-Za-z_][\w.$#@-]*!", v) else v   # `set p=%c1%%c2%`: the join
        else:
            xm = list(_SPLIT_XML.finditer(line))
            lm = list(_SPLIT_LIT.finditer(line))
            if len(xm) == 1:
                v = xm[0].group("v").strip()
            elif len(lm) == 1:
                v = next((g for g in lm[0].groups() if g is not None), "")
        if v and _SPLIT_VAL.fullmatch(v):
            cur.append(v)
        else:
            if len(cur) > 1:
                runs.append(cur)
            cur = []
    return runs


def _split_array_plain(src, budget=0.8):
    """(material, plan) of the first chunk run that joins to `[<TAG>-]<material>` and peels to a plan, else
    (None, None). Bounded by `budget` seconds; never raises."""
    try:
        end, seen = time.time() + budget, set()
        for run in _split_runs((src or "")[:1 << 20]):
            run = [v.strip() for v in run if v.strip()]
            starts = [0] + [i for i, v in enumerate(run) if i and _SPLIT_TAG.match(v)]
            for i in starts[:6]:
                j = "".join(run[i:])
                if len(j) < 16 or not (_SPLIT_VAL.fullmatch(j) or _LYR_ANY_RE.match("-" + j) and not re.search(r"\s", j)):
                    continue                                    # a LYR head may carry b85/a85/z85 punctuation
                tm = _SPLIT_TAG.match(j)
                for tag, mat in ([(tm.group(1), tm.group(2))] if tm else []) + [("", j)]:
                    if mat in seen or time.time() > end:
                        continue
                    seen.add(mat)
                    plain = peel_plan(mat, tag, budget=min(0.25, max(0.02, end - time.time())))
                    if plain:
                        return mat, plain
    except Exception:  # noqa: BLE001 - a decoy / truncated carrier reads as nothing
        return None, None
    return None, None


def _utf16(b):
    """UTF-16 text (BOM'd, or LE/BE with every other byte NUL) re-encoded as UTF-8, else None."""
    if len(b) < 4 or len(b) % 2:
        return None
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        enc = "utf-16"
    elif b[1::2].count(0) >= 0.9 * (len(b) // 2):
        enc = "utf-16-le"
    elif b[0::2].count(0) >= 0.9 * (len(b) // 2):
        enc = "utf-16-be"
    else:
        return None
    try:
        return b.decode(enc).lstrip("\ufeff").encode("utf-8")
    except UnicodeDecodeError:
        return None


# Whole-leaf encodings (prebuild source-encoding-normalize, 10-16): the zip member itself is UTF-16 (BOM'd or not,
# .reg / PS `-Encoding Unicode` saves), UTF-32, gzip'd, or one base64 blob of the source (optionally gzip'd / UTF-16
# under it). find_codecs() rescans normalize(src) only when every other reading of the text found no plan.
_LEAF_B64 = re.compile(r"[A-Za-z0-9+/\-_]+={0,2}")


def _leaf_text(b):
    """Source text of a leaf's bytes when they read as a printable script (UTF-8, UTF-16/32 by BOM or NUL
    interleave), else None."""
    if b[:4] in (b"\xff\xfe\x00\x00", b"\x00\x00\xfe\xff"):
        try:
            t = b.decode("utf-32")
        except UnicodeDecodeError:
            return None
    else:
        u = _utf16(b[:len(b) & ~1]) if b"\x00" in b[:256] or b[:2] in (b"\xff\xfe", b"\xfe\xff") else None
        try:
            t = (u or b).decode("utf-8")
        except UnicodeDecodeError:
            return None
    t = t.lstrip("\ufeff")
    if not t.strip() or sum(c.isprintable() or c in "\r\n\t" for c in t) < 0.95 * len(t):
        return None
    return t


def normalize(data, depth=3):
    """The source text under a whole-leaf encoding: BOM / UTF-16 / UTF-32 sniff, gzip / zlib / bz2 / xz, one base64
    (or base64url) blob, peeled up to `depth` layers. `data` is bytes or (lossy-decoded) text. None when the leaf is
    plain text already or reads as nothing printable -- never raises."""
    try:
        if isinstance(data, str):
            if not data:
                return None
            b = data.encode("latin-1") if max(data) < "\u0100" else data.encode("utf-8", "surrogateescape")
        else:
            b = bytes(data or b"")
        start, cur = b, b
        for _ in range(depth):
            if len(cur) < 8:
                break
            nxt = None
            if cur[:2] in (b"\xff\xfe", b"\xfe\xff", b"\xef\xbb") or b"\x00" in cur[:256]:
                t = _leaf_text(cur)
                nxt = t.encode("utf-8") if t is not None else None
            if nxt is None and (cur[:2] == b"\x1f\x8b" or cur[:3] == b"BZh" or cur[:6] == b"\xfd7zXZ\x00"
                                or (cur[0] & 0x0F == 8 and ((cur[0] << 8) | cur[1]) % 31 == 0)):
                nxt = _inflate(cur, raw=False)
            if nxt is None:
                s = re.sub(rb"\s+", b"", cur).decode("latin-1")
                if len(s) >= 24 and len(s) <= (1 << 20) and _LEAF_B64.fullmatch(s):
                    s = s.replace("-", "+").replace("_", "/").rstrip("=")
                    try:
                        nxt = base64.b64decode(s + "=" * (-len(s) % 4), validate=True)
                    except (binascii.Error, ValueError):
                        nxt = None
            if not nxt or nxt == cur:
                break
            cur = nxt
        if cur is start:
            return None
        t = _leaf_text(cur)
        return t if t is not None and t != data else None
    except Exception:  # noqa: BLE001 - a decoy / truncated leaf reads as nothing
        return None


def _peel_children(b, tag):
    from lib import decode as _d
    import zlib
    rot_all = "ROT" in tag
    for name, out in _d._candidates(b):
        if name.startswith("rot") and not (rot_all or name == "rot13"):
            continue
        yield out
    u = _utf16(b)
    if u:
        yield u
    if _d._printable(b) is None:
        try:
            yield zlib.decompressobj(-15).decompress(b, 1 << 20)
        except zlib.error:
            pass
        m = re.search(r"XOR_?([0-9A-Fa-f]{2,16})", tag)
        if m and len(m.group(1)) % 2 == 0:
            k = bytes.fromhex(m.group(1))
            yield bytes(c ^ k[i % len(k)] for i, c in enumerate(b))
        for k in range(1, 256):
            x = bytes(b).translate(_xor_table(k))
            if x[:2] == b"v=" or x[:1] == b"{" or _d._printable(x):
                yield x


# D23 "Press Start to Decode": `HUNTRESS_ANALYSIS_V1:LYR-<l1>_<l2>_..-<material>` -- the tag lists the ENCODE layers in
# order (b64, b32, hex, rev = reverse, frag = dot-joined fragments); undo them last-first. A frag below the top layer
# (e.g. hex_frag_hex) defeats the generic BFS (112/634 day-23 payloads), so the named chain is tried first.
_LYR_LAYERS = ("b64", "b32", "hex", "rev", "frag")
_LYR_RE = re.compile(r"(?:^|-)LYR-((?:%s)(?:_(?:%s))*)-(.+)$" % ("|".join(_LYR_LAYERS), "|".join(_LYR_LAYERS)), re.S)


def lyr_undo(text):
    """The plan under a `LYR-<layers>-<material>` (tag and material joined, or the material alone) chain, or None."""
    m = _LYR_RE.search((text or "").strip().strip("\"'"))
    if not m or _max_day() < 23:
        return None
    s = m.group(2).strip().encode()
    try:
        for name in reversed(m.group(1).split("_")):
            if name == "frag":
                s = s.replace(b".", b"")
            elif name == "rev":
                s = s[::-1]
            elif name == "hex":
                s = binascii.unhexlify(re.sub(rb"\s", b"", s))
            elif name == "b32":
                t = re.sub(rb"\s", b"", s).upper()
                s = base64.b32decode(t + b"=" * (-len(t) % 8))
            else:
                t = re.sub(rb"\s", b"", s).replace(b"-", b"+").replace(b"_", b"/")
                s = base64.b64decode(t + b"=" * (-len(t) % 4))
    except (ValueError, binascii.Error):
        return None
    return s.decode("utf-8", "ignore").lstrip("\ufeff") if looks_like_plan(s) else None


# Target lyr-tag-layer-peel: the next LYR "power-up" may list layers beyond D23's five. lyr_peel() reads the tag's layer
# list with tolerant names (b64u/urlsafe, b32hex, b58, b85/a85/z85, gz/zlib/deflate/bz2/xz/lzma/zstd/br/lz4, rot13/rotN/
# rot47, xor<hex>, url/pct, uu, qp, utf16, bin, rev, frag; `_ , + | >` separators, up to 6 layers), undoes them last-first
# over a small DFS of each name's readings, and falls back to the name-agnostic shape peel when the tag does not match
# the bytes. Only a `v=` plan is accepted. Bounded, never raises.
_LYR_ANY_RE = re.compile(r"(?:^|[-:\s])LYR[-:]([A-Za-z0-9_,+|>]{1,96})-(.+)$", re.S | re.I)
_LYR_SEP = re.compile(r"[_,+|>]+")
_B58_ALPHA = b"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
_Z85_ALPHA = b"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ.-:+=^!/*?&<>()[]{}@%$#"


def _lyr_ws(s):
    return re.sub(rb"\s", b"", s)


def _lyr_b64(s, url=False):
    t = _lyr_ws(s).rstrip(b"=")
    if url or b"-" in t or b"_" in t:
        t = t.replace(b"-", b"+").replace(b"_", b"/")
    return base64.b64decode(t + b"=" * (-len(t) % 4), validate=True)


def _lyr_b32(s, ext=False):
    t = _lyr_ws(s).upper().rstrip(b"=")
    t += b"=" * (-len(t) % 8)
    return base64.b32hexdecode(t) if ext else base64.b32decode(t)


def _lyr_b58(s):
    t = _lyr_ws(s)
    n = 0
    for c in t:
        i = _B58_ALPHA.find(bytes([c]))
        if i < 0:
            raise ValueError("b58")
        n = n * 58 + i
    body = n.to_bytes((n.bit_length() + 7) // 8, "big") if n else b""
    return b"\0" * (len(t) - len(t.lstrip(b"1"))) + body


def _lyr_z85(s):
    t = _lyr_ws(s)
    if len(t) % 5:
        raise ValueError("z85")
    out = bytearray()
    for i in range(0, len(t), 5):
        n = 0
        for c in t[i:i + 5]:
            j = _Z85_ALPHA.find(bytes([c]))
            if j < 0:
                raise ValueError("z85")
            n = n * 85 + j
        out += n.to_bytes(4, "big")
    return bytes(out)


def _lyr_a85(s):
    t = _lyr_ws(s)
    return base64.a85decode(t, adobe=t.startswith(b"<~"))


def _lyr_rot(s, n):
    def sh(c):
        if 65 <= c <= 90:
            return 65 + (c - 65 - n) % 26
        if 97 <= c <= 122:
            return 97 + (c - 97 - n) % 26
        return c
    return bytes(sh(c) for c in s)


def _lyr_xor(s, key, last):
    if not key:
        if not (last and s):
            raise ValueError("xor key")
        key = bytes([s[0] ^ 0x76])                                   # known plaintext: a plan starts `v=`
    return bytes(c ^ key[i % len(key)] for i, c in enumerate(s))


def _lyr_decomp(s, kind):
    import zlib
    if kind == "gz":
        import gzip
        return gzip.decompress(s)
    if kind == "zlib":
        return zlib.decompress(s)
    if kind == "deflate":
        return zlib.decompressobj(-15).decompress(s, 1 << 22)
    if kind == "bz2":
        import bz2
        return bz2.decompress(s)
    if kind == "xz":
        import lzma
        return lzma.decompress(s)
    if kind == "zstd":
        import zstandard
        return zstandard.ZstdDecompressor().decompress(s, max_output_size=1 << 22)
    if kind == "br":
        import brotli
        return brotli.decompress(s)
    import lz4.frame
    return lz4.frame.decompress(s)


def _lyr_utf16(s):
    for enc in ("utf-16-le", "utf-16-be", "utf-16"):
        try:
            t = s.decode(enc)
        except UnicodeDecodeError:
            continue
        if t and all(c.isprintable() or c in "\r\n\t﻿" for c in t[:64]):
            return t.lstrip("﻿").encode("utf-8")
    raise ValueError("utf16")


_LYR_NAMES = (   # (name regex, list of reading builders: key-group -> fn(bytes, last) -> bytes)
    (r"b64u|b64url|base64u|base64url|urlsafe|urlsafeb64|u64|websafe", [lambda k: lambda s, l: _lyr_b64(s, True)]),
    (r"b64|base64|64|bas64", [lambda k: lambda s, l: _lyr_b64(s)]),
    (r"b32hex|base32hex|b32h|b32x|b32ext", [lambda k: lambda s, l: _lyr_b32(s, True), lambda k: lambda s, l: _lyr_b32(s)]),
    (r"b32|base32|32", [lambda k: lambda s, l: _lyr_b32(s), lambda k: lambda s, l: _lyr_b32(s, True)]),
    (r"hex|b16|base16|16|hx", [lambda k: lambda s, l: binascii.unhexlify(_lyr_ws(s).replace(b"\\x", b"").replace(b"0x", b""))]),
    (r"b58|base58|58", [lambda k: lambda s, l: _lyr_b58(s)]),
    (r"z85", [lambda k: lambda s, l: _lyr_z85(s), lambda k: lambda s, l: base64.b85decode(_lyr_ws(s))]),
    (r"a85|ascii85|adobe85", [lambda k: lambda s, l: _lyr_a85(s), lambda k: lambda s, l: base64.b85decode(_lyr_ws(s))]),
    (r"b85|base85|85", [lambda k: lambda s, l: base64.b85decode(_lyr_ws(s)), lambda k: lambda s, l: _lyr_a85(s),
                        lambda k: lambda s, l: _lyr_z85(s)]),
    (r"gz|gzip|gunzip", [lambda k: lambda s, l: _lyr_decomp(s, "gz"), lambda k: lambda s, l: _lyr_decomp(s, "zlib")]),
    (r"zlib|zl|z", [lambda k: lambda s, l: _lyr_decomp(s, "zlib"), lambda k: lambda s, l: _lyr_decomp(s, "deflate")]),
    (r"deflate|raw|rawdeflate|inflate|dfl", [lambda k: lambda s, l: _lyr_decomp(s, "deflate"),
                                             lambda k: lambda s, l: _lyr_decomp(s, "zlib")]),
    (r"bz2|bzip2|bz|bzip", [lambda k: lambda s, l: _lyr_decomp(s, "bz2")]),
    (r"xz|lzma|lz", [lambda k: lambda s, l: _lyr_decomp(s, "xz")]),
    (r"zstd|zst", [lambda k: lambda s, l: _lyr_decomp(s, "zstd")]),
    (r"br|brotli", [lambda k: lambda s, l: _lyr_decomp(s, "br")]),
    (r"lz4", [lambda k: lambda s, l: _lyr_decomp(s, "lz4")]),
    (r"rot47", [lambda k: lambda s, l: bytes(33 + (c - 33 + 47) % 94 if 33 <= c <= 126 else c for c in s)]),
    (r"(?:rot|caesar|shift)(\d{0,2})", [lambda k: lambda s, l: _lyr_rot(s, int(k or 13)),
                                        lambda k: lambda s, l: _lyr_rot(s, -int(k or 13))]),
    (r"xor(?:0x)?([0-9a-f]*)", [lambda k: lambda s, l: _lyr_xor(s, bytes.fromhex(k) if k and len(k) % 2 == 0 else
                                                          (bytes([int(k, 16)]) if k and len(k) <= 2 else b""), l)]),
    (r"url|pct|percent|urlenc|urlencode|uri", [lambda k: lambda s, l: _lyr_url(s)]),
    (r"uu|uue|uuencode", [lambda k: lambda s, l: _lyr_uu(s)]),
    (r"qp|quotedprintable|quopri", [lambda k: lambda s, l: binascii.a2b_qp(s)]),
    (r"utf16|utf16le|utf16be|u16|wide|unicode|utf_16", [lambda k: lambda s, l: _lyr_utf16(s)]),
    (r"bin|binary|bits", [lambda k: lambda s, l: bytes(int(x, 2) for x in re.findall(rb"[01]{8}", _lyr_ws(s)))]),
    (r"rev|reverse|reversed|flip", [lambda k: lambda s, l: s[::-1]]),
    (r"frag|frags|split|dots|chunks", [lambda k: lambda s, l: s.replace(b".", b""),
                                       lambda k: lambda s, l: re.sub(rb"[.\s,|]", b"", s)]),
)
_LYR_NAME_RES = [(re.compile(p + "$", re.I), fs) for p, fs in _LYR_NAMES]


def _lyr_url(s):
    from urllib.parse import unquote_to_bytes
    return unquote_to_bytes(s.replace(b"+", b" ") if b"%" in s else s)


def _lyr_uu(s):
    out = b""
    for line in s.splitlines():
        line = line.strip(b"\r")
        if not line or line.startswith((b"begin ", b"end")) or line == b"`":
            continue
        out += binascii.a2b_uu(line)
    return out


def _lyr_readings(name):
    """The candidate decode functions of one layer name, else None (unknown name)."""
    for rx, fs in _LYR_NAME_RES:
        m = rx.match(name)
        if m:
            k = m.group(1) if m.groups() else None
            return [f(k) for f in fs]
    return None


def _lyr_layers(spec):
    """'b64_xor_5a_rot_13' -> ['b64', 'xor5a', 'rot13']: a bare key/shift token after xor/rot joins it."""
    out = []
    for t in _LYR_SEP.split(spec or ""):
        if not t:
            continue
        if out and _lyr_readings(t) is None and (re.fullmatch(r"xor", out[-1], re.I) and re.fullmatch(r"(?:0x)?[0-9a-fA-F]{1,32}", t)
                                                  or re.fullmatch(r"(?:rot|caesar|shift)", out[-1], re.I) and t.isdigit()):
            out[-1] += t
        else:
            out.append(t)
    return out


def _lyr_v(b):
    try:
        t = b.decode("utf-8").lstrip("﻿ \r\n\t")
    except (UnicodeDecodeError, AttributeError):
        return None
    return t if t.startswith("v=") else None


def lyr_peel(tag, data, budget=0.4):
    """The `v=` plan under a LYR layer chain: `tag` = `LYR-<l1>_<l2>..` / `<l1>_<l2>..` (ENCODE order, undone
    last-first) and `data` = the material, or tag empty / None and data = `LYR-<layers>-<material>`. A tag that does not
    match the bytes falls back to the shape peel. Returns str or None; never raises."""
    try:
        if _max_day() < 23:
            return None
        tag = (tag or "").strip().strip("\"'")
        data = (data or "").strip().strip("\"'")
        if not tag or tag.upper() == "LYR":
            m = _LYR_ANY_RE.search((tag + "-" if tag else "") + data) or _LYR_ANY_RE.search(data)
            if m:
                tag, data = m.group(1), m.group(2).strip()
        else:
            tag = re.sub(r"^(?:HUNTRESS_ANALYSIS_V\d+:)?LYR[-:]", "", tag, flags=re.I).strip("-")
        if not data:
            return None
        end = time.time() + budget
        layers = _lyr_layers(tag)[:6]
        reads = [_lyr_readings(n) for n in layers]
        if layers and all(reads):
            chain = list(reversed(reads))
            steps = [0]

            def dfs(i, s):
                if i == len(chain):
                    return _lyr_v(s)
                for f in chain[i]:
                    steps[0] += 1
                    if steps[0] > 2000 or time.time() > end:
                        return None
                    try:
                        o = f(s, i == len(chain) - 1)
                    except Exception:  # noqa: BLE001 - this reading does not fit; try the next
                        continue
                    if o and len(o) < (1 << 22):
                        r = dfs(i + 1, o)
                        if r:
                            return r
                return None
            r = dfs(0, data.encode("utf-8", "ignore"))
            if r:
                return r
        p = peel_plan(data, "", depth=6, max_nodes=4000, budget=max(0.05, end - time.time()))   # shape peel
        return p if p and _lyr_v(p.encode("utf-8")) else None
    except Exception:  # noqa: BLE001
        return None


def peel_plan(material, tag="", depth=4, max_nodes=3000, budget=0.5):
    """The plan (str) under up to `depth` generic layers of a v=3 marker/descriptor material, or None. Bounded by
    `max_nodes` and `budget` seconds; never raises."""
    import time
    try:
        mat = (material or "").strip().strip("\"'")
        if not mat:
            return None
        if "LYR-" in (tag or "").upper() + "-" + mat[:4]:   # D23 named layer chain
            lyr = lyr_undo((tag or "") + "-" + mat) or lyr_peel(tag, mat, budget=min(0.3, budget))
            if lyr:
                return lyr
        tag = (tag or "").upper()
        end = time.time() + budget
        frontier = [mat.encode()]
        if "." in mat:
            frontier.append(mat.replace(".", "").encode())          # FRAG-style dot-split fragments
        seen, n = set(frontier), 0
        for level in range(depth + 1):
            nxt = []
            for b in frontier:
                if looks_like_plan(b):
                    return b.decode("utf-8").lstrip("\ufeff")
                if level == depth:
                    continue
                for out in _peel_children(b, tag):
                    n += 1
                    if n > max_nodes or time.time() > end:
                        return None
                    if out and out not in seen and len(out) < (1 << 20):
                        if looks_like_plan(out):
                            return out.decode("utf-8").lstrip("\ufeff")
                        seen.add(out)
                        nxt.append(out)
            frontier = nxt
    except Exception:  # noqa: BLE001 - unknown -> None, never an exception
        return None
    return None


# ------------------------------------------------------------------------------------------------ v=3 tag vocabulary
# Target v3-tag-vocab-extend: the single's marker has carried B64/HEX/HB64/FRAG (+ SPLIT / LYR) for 20 days; a late
# twist may name a new carrier tag (B32, B85/A85, ZB64 = zlib+b64, GZB64, ROT13, REV, UTF16B64, XOR<key>, URL, ...).
# _V3_TAG_TOKENS spells each tag token as a LYR layer name (lib.codec _lyr_readings); a compound tag is split greedily
# (`_` separators too), an `XOR<key>` token takes a hex or ASCII key, and the chain is undone in both orders (ENCODE
# order ZB64 = zlib then b64; READ order HB64 = hex of b64). An unknown tag falls back to the name-agnostic shape peel
# (max 4 layers: zlib/gzip magic, base32 alphabet, utf-16le NULs). The marker line is re-read to its end, so a b85/a85
# material keeps the `<"'` its alphabet holds. Only a `v=` plan is accepted and it is returned verbatim: the peel never
# composes a field (obfuscation_profile= comes from the plan bytes or not at all). Consulted only when every earlier
# reading found no plan, so GM-verified readings are unchanged. Bounded, never raises.
_V3_TAG_TOKENS = (
    ("UTF16LE", "utf16"), ("UTF16BE", "utf16"), ("UTF16", "utf16"), ("UNICODE", "utf16"), ("WIDE", "utf16"),
    ("U16", "utf16"), ("BASE64URL", "b64u"), ("B64URL", "b64u"), ("B64U", "b64u"), ("URLB64", "b64u"),
    ("BASE64", "b64"), ("B64", "b64"), ("BASE32HEX", "b32hex"), ("B32HEX", "b32hex"), ("B32H", "b32hex"),
    ("BASE32", "b32"), ("B32", "b32"), ("BASE85", "b85"), ("B85", "b85"), ("ASCII85", "a85"), ("A85", "a85"),
    ("Z85", "z85"), ("BASE58", "b58"), ("B58", "b58"), ("BASE16", "hex"), ("HEX", "hex"), ("B16", "hex"),
    ("GZIP", "gz"), ("GZ", "gz"), ("ZLIB", "zlib"), ("DEFLATE", "deflate"), ("DFL", "deflate"), ("ZL", "zlib"),
    ("BZIP2", "bz2"), ("BZ2", "bz2"), ("LZMA", "xz"), ("XZ", "xz"), ("ZSTD", "zstd"), ("BROTLI", "br"),
    ("LZ4", "lz4"), ("ROT47", "rot47"), ("ROT13", "rot13"), ("REVERSE", "rev"), ("REV", "rev"), ("URL", "url"),
    ("PCT", "url"), ("QP", "qp"), ("UUE", "uu"), ("UU", "uu"), ("BIN", "bin"), ("FRAG", "frag"), ("Z", "zlib"),
    ("H", "hex"),
)
_V3_LINE_RE = re.compile(r"HUNTRESS_ANALYSIS_V\d+:([A-Za-z0-9_]{1,40})-([^\s]{8,})")
_V3_CLOSERS = ("-->", "--%>", "*/", "?>", "%>", "#>", "]]", "--]]", "|#", "-}", "*)", ";", '"', "'", ")", ",")


def _v3_tag_split(tag, limit=48):
    """Every reading of a compound tag as [layer name, ...] (XOR<key> -> 'xor<hex>'), up to `limit`."""
    out = []

    def rec(t, acc):
        if len(out) >= limit or len(acc) > 6:
            return
        if not t:
            out.append(acc)
            return
        if t[0] == "_":
            return rec(t[1:], acc)
        u = t.upper()
        if u.startswith("XOR"):
            rest = t[3:]
            for j in range(min(len(rest), 32), -1, -1):
                key, tail = rest[:j], rest[j:]
                if tail and tail[0] != "_" and not any(tail.upper().startswith(p) for p, _ in _V3_TAG_TOKENS):
                    continue
                k = key.lstrip("_")
                keys = []
                if re.fullmatch(r"(?:0[xX])?[0-9a-fA-F]+", k) and len(k.replace("0x", "").replace("0X", "")) % 2 == 0:
                    keys.append("xor" + k.lower().replace("0x", ""))
                if k:
                    keys.append(("xorasc", k))
                else:
                    keys.append("xor")
                for kk in keys:
                    rec(tail, acc + [kk])
            return
        m = re.match(r"(?:ROT|CAESAR|SHIFT)(\d{1,2})", u)
        if m and m.group(0) not in ("ROT13", "ROT47"):
            rec(t[m.end():], acc + ["rot" + m.group(1)])
        for p, name in _V3_TAG_TOKENS:
            if u.startswith(p):
                rec(t[len(p):], acc + [name])
    rec(tag, [])
    return out


def _v3_layer_fns(name):
    if isinstance(name, tuple):                                    # ASCII XOR key
        k = name[1].encode("latin-1", "ignore")
        return [lambda s, l, k=k: _lyr_xor(s, k, l)] if k else None
    return _lyr_readings(name)


def v3_tag_peel(tag, material, budget=0.3):
    """The `v=` plan (str, verbatim) of a v=3 marker `<tag>-<material>` read through the tag table (both layer orders),
    else through the name-agnostic shape peel (max 4 layers); None when neither yields a plan. Never raises."""
    try:
        mat = (material or "").strip()
        if not mat or not tag:
            return None
        end = time.time() + budget
        data = mat.encode("utf-8", "ignore")
        steps = [0]

        def dfs(chain, i, s):
            if i == len(chain):
                return _lyr_v(s)
            for f in chain[i]:
                steps[0] += 1
                if steps[0] > 4000 or time.time() > end:
                    return None
                try:
                    o = f(s, i == len(chain) - 1)
                except Exception:  # noqa: BLE001 - this reading does not fit
                    continue
                if o and len(o) < (1 << 22):
                    r = dfs(chain, i + 1, o)
                    if r:
                        return r
            return None
        splits = _v3_tag_split(tag.strip("_"))
        text_layers = {"b64", "b64u", "b32", "b32hex", "b85", "a85", "z85", "b58", "hex", "url", "qp", "uu", "bin"}
        for outer in (None, "b64", "hex", "b32", "b64u"):     # a tag naming no text layer (XORK3Y): the material has one
            for layers in splits:
                if outer and any(n in text_layers for n in layers if isinstance(n, str)):
                    continue
                lay = layers + [outer] if outer else layers
                reads = [_v3_layer_fns(n) for n in lay]
                if not layers or not all(reads):
                    continue
                for chain in ((reads[::-1], reads) if len(reads) > 1 and not outer else (reads[::-1],)):
                    r = dfs(chain, 0, data)
                    if r:
                        return r
                if time.time() > end:
                    break
        p = peel_plan(mat, "", depth=4, max_nodes=2500, budget=max(0.03, end - time.time()))
        return p if p and _lyr_v(p.encode("utf-8")) else None
    except Exception:  # noqa: BLE001
        return None


def _v3_tag_line(src, budget=0.4):
    """(tag, material, plan) of the first v=3 marker line whose tag-table peel yields a plan, else None."""
    try:
        end = time.time() + budget
        for m in _V3_LINE_RE.finditer(src or "", 0, 1 << 20):
            tag, mat = m.group(1), m.group(2)
            if tag.upper() in ("LYR", "SPLIT"):
                continue
            cands = [mat]
            for _ in range(3):
                t = cands[-1]
                for c in _V3_CLOSERS:
                    if t.endswith(c) and len(t) > len(c) + 8:
                        cands.append(t[:-len(c)])
                        break
                else:
                    break
            for c in cands:
                if time.time() > end:
                    return None
                p = v3_tag_peel(tag, c, budget=max(0.03, min(0.25, end - time.time())))
                if p:
                    return tag, c, p
    except Exception:  # noqa: BLE001
        return None
    return None


# ------------------------------------------------------------------------------------------------ .reg / .inf hosts
# Target reg-inf-host-route (persistence hosts; builds on source-encoding-normalize): a regedit export (UTF-16LE + BOM
# for `Version 5.00`, ANSI for REGEDIT4) hides values as `"name"=hex(2):`/`hex(7):`/`hex:` comma-hex (UTF-16LE text,
# NUL-terminated / NUL-separated) wrapped with `,\` line continuations; an INF (CMSTP / setupapi) spells its values as
# %var% references into [Strings] and its registry writes as `root,subkey,name,flags,value` AddReg lines
# (RunPreSetupCommands / UnRegisterOCXSection name the command sections). _reg_inf_host() rewrites the host as plain
# text -- every hex value decoded to `"name"="text"`, every %var% substituted, every AddReg line as `"name"="value"` --
# and _reg_inf_codecs() rescans it, then peels each decoded value name-agnostically. Only consulted when nothing else
# produced a plan, so every earlier reading is unchanged. Bounded, regex + bytes only, never raises.
_REG_HDR = re.compile(r"^.{0,4}?(?:Windows Registry Editor Version [\d.]+|REGEDIT4)[ \t]*\r?$", re.M | re.I)
_REG_HEXVAL = re.compile(r"""^[ \t]*(?P<name>@|"(?:[^"\\\r\n]|\\.)*")[ \t]*=[ \t]*hex(?:\((?P<t>[0-9a-fA-F]{1,8})\))?:"""
                         r"""(?P<body>(?:[0-9a-fA-F]{2}|[ \t,]|\\[ \t]*\r?\n)*)""", re.M)
_INF_HINT = re.compile(r"^[ \t]*\[(?:version|strings|defaultinstall[\w.]*)\][ \t]*\r?$", re.M | re.I)
_INF_SECT = re.compile(r"^[ \t]*\[([^\]\r\n]+)\][ \t]*\r?$", re.M)
_INF_VAR = re.compile(r"%([^%\s,\"]{1,64})%|%%")
_INF_ROOTS = {"hkcr", "hkcu", "hklm", "hku", "hkr", "hkey_classes_root", "hkey_current_user", "hkey_local_machine",
              "hkey_users"}


def _reg_bytes_text(b, wide):
    """Strings of a registry value's bytes (UTF-16LE when `wide` or NUL-interleaved, else latin-1), NUL-split."""
    if wide or (len(b) >= 4 and b[1::2].count(0) >= 0.8 * (len(b) // 2)):
        t = b[:len(b) & ~1].decode("utf-16-le", "replace")
    else:
        t = b.decode("latin-1")
    return [s for s in t.lstrip("﻿").split("\x00") if s.strip()]


def _inf_split(line):
    """INF fields: comma-separated, `"..."` quoted with `""` as a literal quote, `;` comments outside quotes."""
    out, cur, q, i, quoted = [], [], False, 0, False
    while i < len(line):
        c = line[i]
        if q:
            if c == '"' and line[i + 1:i + 2] == '"':
                cur.append('"')
                i += 1
            elif c == '"':
                q = False
            else:
                cur.append(c)
        elif c == '"':
            q = quoted = True
        elif c == ",":
            out.append("".join(cur) if quoted else "".join(cur).strip())
            cur, quoted = [], False
        elif c == ";":
            break
        else:
            cur.append(c)
        i += 1
    out.append("".join(cur) if quoted else "".join(cur).strip())
    return out


def _reg_inf_host(src):
    """(rewritten text, [(name, value)]) for a .reg / .inf host, else None."""
    if not src or len(src) > (1 << 21):
        return None
    vals, extra = [], []
    if _REG_HDR.search(src[:4096]) or (re.match(r"\W{0,6}\[HKEY_", src) and "=hex" in src):
        ansi = bool(re.search(r"^.{0,4}?REGEDIT4", src[:256], re.I | re.M))

        def sub(m):
            t = (m.group("t") or "3").lower().lstrip("0") or "0"
            if t in ("4", "5", "b"):                          # dword / big-endian / qword: no text
                return m.group(0)
            b = bytes.fromhex("".join(re.findall(r"[0-9a-fA-F]{2}", m.group("body")))[:1 << 18])
            parts = _reg_bytes_text(b, not ansi and t in ("1", "2", "6", "7"))
            if t in ("3", "0") and parts and sum(ch.isprintable() for ch in "".join(parts)) < 0.9 * len("".join(parts)):
                return m.group(0)                             # binary blob, not text
            name = m.group("name").strip('"')
            vals.extend((name, p) for p in parts[:32])
            nl = "\r\n" if "\r\n" in m.group(0) else "\n"
            return nl.join('"%s"="%s"' % (name, p) for p in parts[:32]) + nl if parts else m.group(0)
        out = _REG_HEXVAL.sub(sub, src)
        return (out, vals) if vals else None
    if not _INF_HINT.search(src):
        return None
    txt = re.sub(r"\\[ \t]*\r?\n[ \t]*", "", src)            # INF `\` line continuation
    secs, last = {}, None
    for m in _INF_SECT.finditer(txt):
        if last is not None:
            secs.setdefault(last[0].strip().lower(), []).append(txt[last[1]:m.start()])
        last = (m.group(1), m.end())
    if last is not None:
        secs.setdefault(last[0].strip().lower(), []).append(txt[last[1]:])
    strings = {}
    for body in secs.get("strings", []) + [b for k, v in secs.items() if k.startswith("strings.") for b in v]:
        for ln in body.splitlines()[:4096]:
            k, eq, v = ln.partition("=")
            k = k.strip().strip('"')
            if eq and k and not k.startswith(";"):
                f = _inf_split(v.strip())
                strings.setdefault(k.lower(), f[0] if len(f) == 1 else v.strip())
    if not strings and "addreg" not in txt.lower():
        return None

    def subst(s):
        for _ in range(4):
            n = _INF_VAR.sub(lambda m: "%" if m.group(0) == "%%" else strings.get(m.group(1).lower(), m.group(0)), s)
            if n == s:
                break
            s = n
        return s
    out = subst(txt)
    for k, v in strings.items():
        vals.append((k, subst(v)))
    for ln in out.splitlines()[:8192]:                         # AddReg: root,subkey,name,flags,value[,value..]
        f = _inf_split(ln)
        if len(f) >= 5 and f[0].strip().lower() in _INF_ROOTS:
            try:
                flags = int(f[3] or "0", 0)
            except ValueError:
                flags = 0
            if flags & 1:                                      # FLG_ADDREG_BINVALUETYPE: hex byte fields
                try:
                    parts = _reg_bytes_text(bytes(int(x, 16) for x in f[4:] if x), False)
                except ValueError:
                    parts = []
            else:
                parts = [x for x in f[4:] if x]
            vals.extend((f[2], p) for p in parts[:32])
            extra.extend('"%s"="%s"' % (f[2], p) for p in parts[:32])
    return out + "\n" + "\n".join(extra) + "\n", vals


def _reg_inf_codecs(src, depth=0):
    """Codecs of a .reg / .inf host read as text (see _reg_inf_host): the rewritten host rescanned, then each decoded
    value peeled on its own. [] when `src` is not such a host or nothing reads as a plan."""
    try:
        host = _reg_inf_host(src)
        if not host:
            return []
        text, vals = host
        out = [dict(c, id=f"{c['id']}@host") for c in find_codecs(text, depth + 1) if c.get("plain")]
        if out:
            return out
        end = time.time() + 0.8
        for name, v in sorted(vals[:128], key=lambda nv: "descriptor" not in nv[0].lower()):
            if time.time() > end:
                break
            v = v.strip()
            if len(v) < 8:
                continue
            p = peel_plan(v, budget=max(0.05, min(0.3, end - time.time())))
            if p:
                return [{"id": f"host:{name}", "rep": "reg_value", "transform": "identity", "key": "", "material": v,
                         "plain": p}]
    except Exception:  # noqa: BLE001 - a decoy / truncated host reads as nothing
        return []
    return []


# ------------------------------------------------------------------------------------------------ XSLT msxsl:script host
# Target xslt-msxsl-route (msxsl.exe / `wmic /format:evil.xsl`, Squiblytwo; sibling of the D9 SCT and D14 MSBuild hosts):
# an <xsl:stylesheet> carrying <msxsl:script language="JScript|VBScript"> (any prefix bound to
# urn:schemas-microsoft-com:xslt, e.g. <ms:script>). Without CDATA the body is XML-escaped (`&quot;`, VBS `&amp; _`,
# `&#NN;` char refs), which hides the descriptor from the text readings. _xslt_codecs() never applies the transform: it
# reads (1) each script body unescaped and folded per language= (JScript String.fromCharCode, VBS Chr/ChrW), (2) the
# whole document flattened (CDATA unwrapped, the rest unescaped: comment marker + descriptor), (3) XPath string
# literals / concat() of <xsl:variable|param name="descriptor_x" select=..>. Only consulted when nothing else produced
# a plan, and only on an XSLT host, so every earlier reading is unchanged. Pure regex + html.unescape, never raises.
_XSL_HOST = re.compile(r"<[\w.-]*:?(?:stylesheet|transform)\b|urn:schemas-microsoft-com:xslt", re.I)
_XSL_SCRIPT = re.compile(r"<(?P<tag>[\w.-]+:script)\b(?P<attrs>[^>]*)>(?P<body>.*?)</(?P=tag)\s*>", re.I | re.S)
_XSL_VAR = re.compile(r"<[\w.-]+:(?:variable|param|with-param)\b(?P<attrs>[^>]*)>", re.I)
_XSL_CDATA = re.compile(r"<!\[CDATA\[(.*?)\]\]>", re.S)


def _xml_flat(s):
    """XML text with CDATA sections unwrapped and everything outside them entity-unescaped."""
    import html
    out, pos = [], 0
    for m in _XSL_CDATA.finditer(s):
        out.append(html.unescape(s[pos:m.start()]))
        out.append(m.group(1))
        pos = m.end()
    out.append(html.unescape(s[pos:]))
    return "".join(out)


def _xsl_fold(body, lang):
    """Constant char-code builders of the script's language rewritten as quoted literals."""
    def q(codes):
        try:
            return '"' + "".join(chr(int(c, 0)) for c in codes).replace('"', "") + '"'
        except (ValueError, OverflowError):
            return None
    if "vb" in lang:
        body = re.sub(r"&[ \t]*_[ \t]*\r?\n\s*", "& ", body)                # `& _` continuation lines joined
        rx = re.compile(r"(?:ChrW?\s*\(\s*(?:&H[0-9A-Fa-f]+|\d+)\s*\)\s*&?\s*)+", re.I)
        sub = lambda m: q([c.replace("&H", "0x").replace("&h", "0x") for c in   # noqa: E731
                           re.findall(r"\(\s*(&H[0-9A-Fa-f]+|\d+)", m.group(0), re.I)]) or m.group(0)
    else:
        rx = re.compile(r"String\.fromCharCode\s*\(\s*([0-9xXa-fA-F,\s]+)\)")
        sub = lambda m: q([c for c in re.split(r"[\s,]+", m.group(1)) if c]) or m.group(0)   # noqa: E731
    return rx.sub(sub, body[:1 << 18])


def _xpath_literal(expr):
    """The string of an XPath `'lit'` / `"lit"` / concat(lit, ...) select expression, else None."""
    e = expr.strip()
    m = re.fullmatch(r"concat\s*\((.*)\)", e, re.S)
    lits = re.findall(r"""'([^']*)'|"([^"]*)\"""", m.group(1) if m else e)
    if not lits or (not m and len(lits) > 1):
        return None
    return "".join(a or b for a, b in lits)


_XSL_NODTD = re.compile(r"<!(?:DOCTYPE|ENTITY)\b", re.I)


def _xslt_etree_text(src):
    """Target xslt-v3-fixtures (D23-D27 shape): the stylesheet parsed with xml.etree (no DTD, so no entity expansion;
    never applied). Comment text ends at `-->` (a tight `<!-- HUNTRESS_ANALYSIS_V1:B64-..-->` marker), char refs
    (`&#x2E;` FRAG dots) and CDATA come back resolved, and EVERY <xsl:variable|param> (any name: huntress_descriptor,
    d, ..) is rewritten as `descriptor_<name> = "<select literal | text content>"`. Returns that text, else None."""
    import xml.etree.ElementTree as ET
    if len(src) > 1 << 20 or _XSL_NODTD.search(src):
        return None
    try:   # a pull parser: the line-2 marker comment sits BEFORE the root element, which fromstring() drops
        pp = ET.XMLPullParser(events=("comment", "end"))
        pp.feed(src.encode("utf-8"))
        pp.close()
        events = list(pp.read_events())
    except Exception:  # noqa: BLE001 - not well-formed XML: the regex readings already ran
        return None
    out = []
    for ev, e in events:
        if len(out) >= 64:
            break
        if ev == "comment":
            t = (e.text or "").strip()
            if "HUNTRESS_ANALYSIS" in t:
                out.append(t + "\n")
            continue
        if not isinstance(e.tag, str) or not re.search(r"\}(?:variable|param|with-param)$", e.tag):
            continue
        nm = re.sub(r"\W", "_", e.get("name") or "")
        sel = e.get("select")
        lit = _xpath_literal(sel) if sel else "".join(e.itertext()).strip()
        if nm and lit:
            out.append('descriptor_%s = "%s"\n' % (nm, lit.replace('"', "")))
    return "".join(out) or None


def _xslt_codecs(src):
    try:
        if not src or not _XSL_HOST.search(src[:1 << 16]):
            return []
        texts = []
        for m in _XSL_SCRIPT.finditer(src):
            if len(texts) >= 16:
                break
            lm = re.search(r"""\blanguage\s*=\s*["']([^"']*)""", m.group("attrs"), re.I)
            lang = (lm.group(1) if lm else "jscript").lower()
            body = _xml_flat(m.group("body"))
            texts.append(("msxsl_" + re.sub(r"\W", "", lang), _xsl_fold(body, lang)))
        flat = _xml_flat(src)
        syn = []
        for m in _XSL_VAR.finditer(flat if "&" in src else src):
            a = m.group("attrs")
            nm = re.search(r"""\bname\s*=\s*["'](descriptor[_-][\w-]+)["']""", a, re.I)
            sel = re.search(r"""\bselect\s*=\s*(?:"([^"]*)"|'([^']*)')""", a, re.S)
            lit = _xpath_literal(sel.group(1) if sel.group(1) is not None else sel.group(2)) if nm and sel else None
            if lit:
                syn.append('%s = "%s"\n' % (nm.group(1).replace("-", "_"), lit.replace('"', "")))
        texts.append(("xslt", flat + "\n" + "".join(syn)))
        ety = _xslt_etree_text(src)
        if ety:
            texts.append(("xslt", ety))
        for ident, text in texts:
            for c in _find_codecs_text(text):
                if c.get("plain"):
                    c = dict(c, id=c.get("id") or ident)
                    return [c]
    except Exception:  # noqa: BLE001 - unknown -> None, never an exception
        return []
    return []


# ------------------------------------------------------------------------------------------------ PowerShell v=3 route
# Target ps-v3-polyglot-route: a polyglot-PowerShell day (.ps1/.psm1/.psd1/.ps1xml) writes the v=3 descriptor in PS
# syntax: `[string]$script:descriptor_x = "..."`, `${descriptor_x}`, `Set-Variable -Name descriptor_x -Value '..'`,
# here-strings `@' .. '@` / `@" .. "@`, `'a' + 'b'` / backtick-continued pieces, `-join @('a','b')`, `''` / `""` /
# backtick escapes, a .psd1 hashtable key `Descriptor = '..'` and a .ps1xml `<Name>descriptor_x</Name><Value>..`.
# find_codecs() consults _ps_v3_codecs() when nothing else produced a plan, and puts its plan first only when an
# earlier reading of the SAME literal is demonstrably lossy (a truncated first piece, or a `''`/`""` escape dropped).
# is_v3() / v3_plan() let a solver route v=3 before the v=1 `$encodedMaterial` / `$nativeTypes` JSON path.
_PSV3_VAR = re.compile(r"""(?:\[[\w.\[\]]+\]\s*)*\$\{?(?:(?:script|global|local|private|using|env):)?(?P<n>descriptor[_-]?[\w-]*)\}?"""
                       r"""[ \t]*=(?!=)[ \t]*""", re.I)
_PSV3_SETVAR = re.compile(r"""\b(?:Set|New)-Variable\s+(?:-Name\s+)?['"]?(?P<n>descriptor[_-]?[\w-]*)['"]?\s+"""
                          r"""(?:-Value\s+)?""", re.I)
_PSV3_KEY = re.compile(r"""(?:^|[;{(])[ \t]*['"]?(?P<n>descriptor[_-]?[\w-]*)['"]?[ \t]*=(?!=)[ \t]*""", re.I | re.M)
_PSV3_XML = re.compile(r"""<Name>\s*(?P<n>descriptor[_-]?[\w-]*)\s*</Name>\s*<Value>(?P<v>.*?)</Value>""", re.I | re.S)
_PSV3_NOTPS = re.compile(r"""<\?php|^\s*my\s+[$@%]|^\s*use\s+strict\b""", re.I | re.M)
_PSV3_MARK = re.compile(r"HUNTRESS_ANALYSIS_V\d+:[A-Za-z0-9_]+-")


def _psv3_str(s, i):
    """(value, end) of the PowerShell string literal at s[i] ('..', "..", @'..'@, @"..."@), else (None, i)."""
    n = len(s)
    if s.startswith(("@'", '@"'), i):
        q = s[i + 1]
        j = s.find("\n", i + 2)
        if j < 0 or s[i + 2:j].strip():
            return None, i
        m = re.compile(r"\r?\n" + q + "@").search(s, j)
        if not m:
            return None, i
        body = s[j + 1:m.start()]
        return (body if q == "'" else _psv3_dq(body, here=True)), m.end()
    if i < n and s[i] in "'‘’":
        out, j = [], i + 1
        while j < n:
            c = s[j]
            if c in "'‘’":
                if j + 1 < n and s[j + 1] in "'‘’":
                    out.append(c)
                    j += 2
                    continue
                return "".join(out), j + 1
            out.append(c)
            j += 1
        return None, i
    if i < n and s[i] in '"“”':
        j = i + 1
        while j < n:
            c = s[j]
            if c == "`":
                j += 2
                continue
            if c in '"“”':
                if j + 1 < n and s[j + 1] in '"“”':
                    j += 2
                    continue
                return _psv3_dq(s[i + 1:j]), j + 1
            j += 1
        return None, i
    return None, i


def _psv3_dq(body, here=False):
    """Expandable-string body: backtick escapes and `""` (no variable expansion: a constant descriptor has none)."""
    out, j, n = [], 0, len(body)
    while j < n:
        c = body[j]
        if c == "`" and j + 1 < n:
            d = body[j + 1]
            out.append(_PS_DQ_ESC.get(d, "" if d in "\r\n" else d))
            j += 2
        elif not here and c in '"“”' and j + 1 < n and body[j + 1] in '"“”':
            out.append(c)
            j += 2
        else:
            out.append(c)
            j += 1
    return "".join(out)


def _psv3_ws(s, i, nl):
    """Skip blanks (newlines too when `nl`), backtick line continuations and `<# #>` comments."""
    n = len(s)
    while i < n:
        if s[i] in " \t" or (nl and s[i] in "\r\n"):
            i += 1
        elif s[i] == "`" and s[i + 1:i + 2] in ("\n", "\r"):
            i += 2
        elif s.startswith("<#", i):
            e = s.find("#>", i + 2)
            if e < 0:
                return n
            i = e + 2
        else:
            return i
    return i


def _psv3_expr(s, i, depth=0):
    """(value, end) of a constant PowerShell string expression at s[i]: literals joined by `+`, `-join @(..)`,
    `(..)`, `@('a','b') -join ''`, `[string]::Concat(..)` / `[string]::Join('', ..)`; else (None, i)."""
    if depth > 6:
        return None, i
    parts, j = [], _psv3_ws(s, i, False)
    while True:
        j0 = j
        mj = re.compile(r"-join\s*", re.I).match(s, j)
        if not parts and mj:
            v, j = _psv3_group(s, mj.end(), depth)
        elif not parts and re.match(r"\[string\]::(?:concat|join)\s*\(", s[j:j + 24], re.I):
            k = s.index("(", j)
            isjoin = s[j:k].lower().rstrip().endswith("join")
            items, j = _psv3_items(s, k + 1, ")", depth)
            v = None if items is None or (isjoin and len(items) < 1) else \
                (items[0].join(items[1:]) if isjoin else "".join(items))
        elif s.startswith(("@(", "("), j):
            v, j = _psv3_group(s, j, depth)
            mj = re.compile(r"\s*-join\s*", re.I).match(s, j)
            if v is not None and mj:
                sep, j2 = _psv3_str(s, mj.end())
                if sep is not None:
                    v, j = v, j2                                # `@('a','b') -join ''`: separator already ''
        else:
            v, j = _psv3_str(s, j)
        if v is None:
            j = j0
            break
        parts.append(v)
        k = _psv3_ws(s, j, False)
        if s.startswith("+", k):
            j = _psv3_ws(s, k + 1, True)
            continue
        j = k
        break
    return ("".join(parts), j) if parts else (None, i)


def _psv3_items(s, i, close, depth):
    """Comma/newline separated constant expressions up to `close`: (list, end) or (None, i)."""
    items, j = [], i
    while True:
        j = _psv3_ws(s, j, True)
        if s.startswith(close, j):
            return items, j + 1
        if items and s.startswith((",", ";"), j):
            j += 1
            continue
        if s.startswith("@(", j) and _psv3_expr(s, j, depth + 1)[0] is None:  # nested array: flatten
            sub, j2 = _psv3_items(s, j + 2, ")", depth + 1)
            if sub is None:
                return None, i
            items += sub
            j = j2
            continue
        v, j2 = _psv3_expr(s, j, depth + 1)
        if v is None:
            return None, i
        items.append(v)
        j = j2


def _psv3_group(s, i, depth):
    """`@(..)` / `(..)` of constant strings -> their concatenation (the `-join` reading), or a bare literal."""
    if s.startswith("@(", i):
        items, j = _psv3_items(s, i + 2, ")", depth)
    elif s.startswith("(", i):
        items, j = _psv3_items(s, i + 1, ")", depth)
    else:
        v, j = _psv3_str(s, i)
        return v, j
    return ("".join(items) if items is not None else None), j


def _ps_descriptor_literals(src, limit=24):
    """(id, literal) of every PowerShell-syntax descriptor assignment (see the block comment above)."""
    out = []
    if not src or "descriptor" not in src.lower() or _PSV3_NOTPS.search(src[:1 << 16]):
        return out
    texts = [src]
    if "<Value>" in src or "&lt;" in src or "<ScriptBlock>" in src:
        import html
        texts.append(html.unescape(re.sub(r"<!\[CDATA\[(.*?)\]\]>", r"\1", src, flags=re.S)))
        for m in _PSV3_XML.finditer(src):
            out.append((m.group("n"), html.unescape(m.group("v").strip())))
    hashtable = "@{" in src
    for t in texts:
        for rx in (_PSV3_VAR, _PSV3_SETVAR) + ((_PSV3_KEY,) if hashtable else ()):
            for m in rx.finditer(t):
                if rx is _PSV3_KEY and "@{" not in t[:m.start()]:
                    continue
                v, _ = _psv3_expr(t, m.end())
                if v:
                    out.append((m.group("n"), v))
                if len(out) >= limit:
                    break
    seen, res = set(), []
    for n, v in out:
        ident = re.sub(r"(?i)^descriptor[_-]?", "", n) or "descriptor"
        if (ident, v) not in seen:
            seen.add((ident, v))
            res.append((ident, v))
    return res


def _ps_v3_codecs(src, budget=1.0):
    """Codec entries for PowerShell-syntax descriptors whose literal peels to a plan (marker TAG as the layer hint)."""
    try:
        lits = _ps_descriptor_literals(src)
        if not lits:
            return []
        am = _ANALYSIS_RE.search(src)
        end, out = time.time() + budget, []
        for ident, lit in lits:
            if time.time() > end:
                break
            plain = None
            for cand in (lit, re.sub(r"\s+", "", lit), lit.strip()):
                plain = peel_plan(cand, am.group("tag") if am else "",
                                  budget=min(0.4, max(0.05, end - time.time()))) if cand else None
                if plain:
                    break
            if plain:
                out.append({"id": ident, "rep": "descriptor", "transform": "identity", "key": "", "material": lit,
                            "plain": plain})
        return out
    except Exception:
        return []


def _psv3_lossy(full, part):
    """`part` is a lossy reading of the plan `full`: its truncated first piece, or `full` with quotes dropped."""
    if not full or not part or full == part:
        return False
    if full.startswith(part):
        return True
    sq = lambda t: re.sub(r"['\"‘’“”]", "", t)
    return sq(full) == sq(part)


# ------------------------------------------------------------------------------------------------ BEAM (Erlang / Elixir)
# Target beam-erlang-elixir-route: Erlang `.erl` / escript and Elixir `.ex`/`.exs` descriptors beyond the D25
# `descriptor_x = ".."` shape: `-define(DESCRIPTOR_X, ..).`, `descriptor_x() -> ..`, `@descriptor_x ..` attributes,
# `defp descriptor, do: ..`, `%{descriptor: ..}` / `#{descriptor => ..}` map values, binaries `<<"..">>` /
# `<<118,61,51>>`, charlists `[118,61,51]` / `'..'` / `$v`, sigils `~s(..)` `~S"""..""""` `~c".."`, `++` / `<>` concat,
# `|>` pipes, `?MACRO` / `@attr` / `part()` / variable references, and the constant calls Base.decode64! / :base64.decode
# / Base.decode16! / binary:decode_hex / reverse / list_to_binary / Enum.join. _beam_codecs() folds them statically
# (never runs anything); consulted by find_codecs() only behind _BEAM_CUE + a `descriptor` name. Never raises.
_BEAM_CUE = re.compile(r"""-module\(|-define\(|escript|defmodule\s|\bdefp?\s+\w|<<|~[sScC][(\[{<"'|/]|\s(?:<>|\+\+)\s|"""
                       r"""@descriptor|Base\.decode|\bbase64[:.]|\|>""")
_BEAM_DEF = re.compile(r"""(?m)-define\(\s*(?P<d>\w+)\s*,|^[ \t]*(?P<f>[a-z]\w*)\(\s*\)\s*->|"""
                       r"""^[ \t]*defp?\s+(?P<x>\w+[?!]?)(?:\(\s*\))?(?:\s*,\s*do:|\s+do\b)|"""
                       r"""^[ \t]*@(?P<a>\w+)[ \t]+(?=\S)|(?<![\w.:@?])(?P<v>[A-Za-z_]\w*)[ \t]*=(?![=>~])[ \t]*|"""
                       r"""(?<![\w.])(?P<k>descriptor\w*)(?::[ \t]+|\s*=>\s*)""")
_BEAM_ESC = {"n": "\n", "t": "\t", "r": "\r", "s": " ", "e": "\x1b", "d": "\x7f", "b": "\b", "f": "\f", "v": "\v",
             "0": "\0", "a": "\a"}
_BEAM_ID = {"list_to_binary", "binary_to_list", "iolist_to_binary", "characters_to_binary", "characters_to_list",
            "to_string", "to_charlist", "iodata_to_binary", "chardata_to_string", "flatten", "trim", "concat",
            "list_to_bitstring", "bitstring_to_list", "unicode_characters_to_binary", "to_binary", "append", "join",
            "iolist_to_iovec", "string"}


class _BeamFail(Exception):
    pass


class _Beam:
    def __init__(self, src, env, end):
        self.s, self.env, self.end, self.seen = src, env, end, set()
        self.erl = "-module(" in src or "escript" in src[:256]

    def ws(self, i, nl=True):
        s = self.s
        while i < len(s):
            c = s[i]
            if c in " \t\r" or (nl and c == "\n"):
                i += 1
            elif nl and c in "%#" and (c == "#" or s[i + 1:i + 2] in ("%", " ", "\t", "\n", "")) and \
                    s[i + 1:i + 2] != "{":
                j = s.find("\n", i)
                i = len(s) if j < 0 else j + 1
            else:
                break
        return i

    def expr(self, i):
        v, i = self.term(i)
        while True:
            if time.time() > self.end:
                raise _BeamFail
            j = self.ws(i)
            op = self.s[j:j + 2]
            if self.erl and op[:1] == '"':                           # Erlang adjacent literals `"a" "b"`
                w, i = self.term(j)
                v = self.text(v) + self.text(w)
            elif op in ("++", "<>"):
                w, i = self.term(self.ws(j + 2))
                v = self.text(v) + self.text(w)
            elif op == "|>":
                k = self.ws(j + 2)
                m = re.compile(r"[:\w.]+[!?]?").match(self.s, k)
                if not m:
                    raise _BeamFail
                k = self.ws(m.end(), False)
                args = []
                if self.s[k:k + 1] == "(":
                    args, k = self.args(k + 1, ")")
                v, i = self.call(m.group(0), [v] + args), k
            else:
                return v, i

    def text(self, v):
        if isinstance(v, int):
            if not 0 <= v < 0x110000:
                raise _BeamFail
            return chr(v)
        if isinstance(v, list):
            return "".join(self.text(x) for x in v)
        return v

    def args(self, i, close):
        out = []
        i = self.ws(i)
        while self.s[i:i + 1] != close:
            km = re.compile(r"\w+:\s").match(self.s, i)          # keyword arg `case: :lower` -- skipped
            if km:
                vm = re.compile(r"\s*:?[\w\"]+").match(self.s, km.end())
                i = self.ws(vm.end() if vm else km.end())
            else:
                v, i = self.expr(i)
                out.append(v)
                i = self.ws(i)
            if self.s[i:i + 1] == ",":
                i = self.ws(i + 1)
            elif self.s[i:i + 1] != close:
                raise _BeamFail
        return out, i + 1

    def quoted(self, i, close, esc, heredoc=False):
        s, out = self.s, []
        while True:
            if i >= len(s) or time.time() > self.end:
                raise _BeamFail
            if heredoc and s.startswith(close, i):
                body = "".join(out)
                ind = body[body.rfind("\n") + 1:]
                if ind.strip():
                    raise _BeamFail
                lines = body[:len(body) - len(ind)].split("\n")
                lines = lines[1:] if lines and not lines[0].strip() else lines
                return "\n".join(ln[len(ind):] if ln.startswith(ind) else ln.lstrip() for ln in lines), i + len(close)
            c = s[i]
            if not heredoc and c == close:
                return "".join(out), i + 1
            if c == "\\" and esc:
                n = s[i + 1:i + 2]
                hm = re.compile(r"x\{([0-9A-Fa-f]{1,6})\}|x([0-9A-Fa-f]{2})|u\{([0-9A-Fa-f]{1,6})\}|u([0-9A-Fa-f]{4})|"
                                r"([0-7]{1,3})").match(s, i + 1)
                if hm:
                    out.append(chr(int(next(g for g in hm.groups()[:4] if g), 16) if not hm.group(5)
                                   else int(hm.group(5), 8)))
                    i = hm.end()
                elif n == "\n":
                    i += 2
                else:
                    out.append(_BEAM_ESC.get(n, n))
                    i += 2
            elif c == "\\" and not esc and s[i + 1:i + 2] == close and not heredoc:
                out.append(close)
                i += 2
            elif c == "#" and esc and s[i + 1:i + 2] == "{":
                raise _BeamFail                                  # runtime interpolation
            else:
                out.append(c)
                i += 1

    def term(self, i):
        s = self.s
        i = self.ws(i)
        if s.startswith('"""', i) or s.startswith("'''", i):
            return self.quoted(i + 3, s[i:i + 3], True, True)
        c = s[i:i + 1]
        if c in "\"'":
            return self.quoted(i + 1, c, True)
        if c == "~":
            m = re.compile(r"~([sScC])").match(s, i)
            if not m:
                raise _BeamFail
            j, esc = m.end(), m.group(1).islower()
            if s.startswith('"""', j) or s.startswith("'''", j):
                v, j = self.quoted(j + 3, s[j:j + 3], esc, True)
            else:
                o = s[j:j + 1]
                close = {"(": ")", "[": "]", "{": "}", "<": ">"}.get(o, o)
                if not o or o not in "([{<\"'|/":
                    raise _BeamFail
                v, j = self.quoted(j + 1, close, esc)
            while j < len(s) and s[j].isalpha():
                j += 1
            return v, j
        if s.startswith("<<", i):
            out, j = [], self.ws(i + 2)
            while not s.startswith(">>", j):
                v, j = self.term(j)
                j = self.ws(j)
                tm = re.compile(r"(?::\d+)?(?:/[\w-]+)?").match(s, j)  # `:8` size / `/utf8` type spec
                j = self.ws(tm.end())
                out.append(self.text(v))
                if s[j:j + 1] == ",":
                    j = self.ws(j + 1)
                elif not s.startswith(">>", j):
                    raise _BeamFail
            return "".join(out), j + 2
        if c == "[":
            out, j = self.args(i + 1, "]")
            return out, j
        if c == "(":
            v, j = self.expr(i + 1)
            j = self.ws(j)
            if s[j:j + 1] != ")":
                raise _BeamFail
            return v, j + 1
        if c == "$" and i + 1 < len(s):                           # Erlang `$v`
            if s[i + 1] == "\\":
                return _BEAM_ESC.get(s[i + 2:i + 3], s[i + 2:i + 3]), i + 3
            return ord(s[i + 1]), i + 2
        m = re.compile(r"(\d+)#([0-9A-Za-z]+)|0x([0-9A-Fa-f_]+)|0o([0-7_]+)|0b([01_]+)|(\d[\d_]*)").match(s, i)
        if m:
            g = m.groups()
            v = int(g[1], int(g[0])) if g[0] else int((g[2] or g[3] or g[4] or g[5]).replace("_", ""),
                                                      16 if g[2] else 8 if g[3] else 2 if g[4] else 10)
            return v, m.end()
        if c == "?" and i + 1 < len(s):
            mm = re.compile(r"\?(\w+)").match(s, i)
            if mm and mm.group(1) in self.env:
                return self.ref(mm.group(1)), mm.end()
            return ord(s[i + 1]), i + 2                           # Elixir `?v`
        m = re.compile(r"(@)?(:?[A-Za-z_][\w.:]*[!?]?)").match(s, i)
        if not m:
            raise _BeamFail
        name, j = m.group(2), self.ws(m.end(), False)
        if m.group(1):
            return self.ref(name), m.end()
        if s[j:j + 1] == "(":
            args, j = self.args(j + 1, ")")
            if not args and name in self.env:
                return self.ref(name), j
            return self.call(name, args), j
        if name in self.env:
            return self.ref(name), m.end()
        raise _BeamFail

    def ref(self, name):
        if name in self.seen or name not in self.env:
            raise _BeamFail
        self.seen.add(name)
        try:
            return self.expr(self.env[name])[0]
        finally:
            self.seen.discard(name)

    def call(self, name, args):
        f = re.split(r"[.:]", name.lstrip(":"))[-1].rstrip("!?").lower()
        mod = name.lstrip(":").lower()
        if not args:
            raise _BeamFail
        a = args[0]
        if f in ("reverse",):
            return a[::-1] if isinstance(a, (list, str)) else _fail()
        if f == "join" and isinstance(a, list):
            sep = self.text(args[1]) if len(args) > 1 else ""
            return sep.join(self.text(x) for x in a)
        t = self.text(a)
        if f in _BEAM_ID:
            return t.strip() if f == "trim" else t
        if f in ("decode64", "decode", "decode_to_string", "mime_decode", "url_decode64", "mime_decode_to_string") \
                and ("base64" in mod or "decode64" in f):
            t = re.sub(r"\s+", "", t)
            raw = base64.urlsafe_b64decode(t + "=" * (-len(t) % 4)) if "url" in f else \
                base64.b64decode(t + "=" * (-len(t) % 4))
        elif f in ("decode16", "decode_hex") or (f == "decode" and "hex" in mod):
            raw = bytes.fromhex(re.sub(r"\s+", "", t))
        elif f == "decode32":
            raw = base64.b32decode(t.upper() + "=" * (-len(t) % 8))
        else:
            raise _BeamFail
        try:
            return raw.decode("utf-8")
        except UnicodeDecodeError:
            return raw.decode("latin-1")


def _fail():
    raise _BeamFail


def _beam_literals(src, budget=0.4):
    """[(name, folded value)] for every `descriptor`-named BEAM binding / map value, else []."""
    end = time.time() + budget
    env, keys = {}, []
    for m in _BEAM_DEF.finditer(src):
        g = m.lastgroup
        name = m.group(g)
        if g == "k":
            keys.append((name, m.end()))
        elif name not in env:
            env[name] = m.end()
    ev, out = _Beam(src, env, end), []
    for name, pos in [(n, p) for n, p in env.items() if "descriptor" in n.lower()] + keys:
        if time.time() > end:
            break
        try:
            v = ev.text(ev.expr(pos)[0])
        except Exception:
            continue
        if v and (name, v) not in out:
            out.append((name, v))
    return out


def _beam_codecs(src, budget=0.5):
    """Codec entries for BEAM descriptors whose folded value peels to a plan (marker TAG as the layer hint)."""
    try:
        lits = _beam_literals(src)
        am = _ANALYSIS_RE.search(src) if lits else None
        end, out = time.time() + budget, []
        for ident, lit in lits:
            if time.time() > end:
                break
            plain = None
            for cand in (lit, re.sub(r"\s+", "", lit)):
                plain = peel_plan(cand, am.group("tag") if am else "", budget=min(0.3, max(0.05, end - time.time())))
                if plain:
                    break
            if plain:
                out.append({"id": re.sub(r"(?i)^descriptor_?", "", ident) or ident, "rep": "descriptor",
                            "transform": "identity", "key": "", "material": lit, "plain": plain})
        return out
    except Exception:
        return []

# ------------------------------------------------------------------- actor / message-passing flow (static edge list)
# actor-message-flow-model: who sends what to whom, read from the source only (never run erl / elixir / node / go).
# Erlang `Pid ! {Tag, V}`, `gen_server:call/cast`, Elixir `send(pid, msg)` / `GenServer.call/cast`, JS
# `w.postMessage(m)` (`new Worker('x.js')`), Go `ch <- v` (only in a `package` + `chan` source: R also writes `x <- ".."`).
# Receivers resolve through `X = spawn(..f..)` / `register(name, X)` / `Task.async` / `start_link` / `new Worker`, and
# a spawned function's parameters through the spawn's arguments (`self()` = the spawner). message_flow(src) ->
# [{seq, sender, receiver, tag, payload, index, kind, final}] in source order (a loop over a literal list expands);
# `final` is the last process a forwarded payload reaches (`receive {tag, X} -> Next ! {tag2, X}`). _mf_codecs joins
# each (receiver, tag) group's string payloads (by their integer sequence element when every message has one) and
# peels the result to a plan.
_MF_CUE = re.compile(r"""(?:[\w)'?]\s*!\s*[{\[<"'\w])|gen_server:(?:call|cast)\(|GenServer\.(?:call|cast)\(|"""
                     r"""(?<![\w.])send\(\s*[\w:]+|\.postMessage\(|(?<![\w.])postMessage\(|\bchan\b""")
_MF_ERL = re.compile(r"(?m)^-module\(|\breceive\b|(?<![\w.:])spawn(?:_link|_monitor)?\(|escript")
_MF_GO = re.compile(r"(?m)^package\s+\w+")
_MF_HEADS = (re.compile(r"(?m)^(?P<n>[a-z]\w*)\((?P<a>[^()\n]*(?:\([^()\n]*\)[^()\n]*)*)\)\s*(?:when\b[^\n]*)?->"),  # Erlang
             re.compile(r"(?m)^[ \t]*defp?\s+(?P<n>\w+[?!]?)(?:\((?P<a>[^\n]*?)\))?(?:\s+when\b[^\n]*?)?(?:\s*,\s*do:|\s+do\b)"),
             re.compile(r"(?m)^[ \t]*(?:export\s+)?(?:async\s+)?function\s*\*?\s*(?P<n>\w+)\s*\((?P<a>[^)]*)\)|"
                        r"^[ \t]*(?:const|let|var)\s+(?P<n2>\w+)\s*=\s*(?:async\s+)?(?:function\b[^(]*\((?P<a2>[^)]*)\)|"
                        r"\(?(?P<a3>[\w\s,]*)\)?\s*=>)"),
             re.compile(r"(?m)^func\s+(?:\([^)]*\)\s*)?(?P<n>\w+)\s*\((?P<a>[^)]*)\)"))
_MF_KW = {"return", "if", "while", "and", "or", "not", "case", "of", "when", "andalso", "orelse", "else", "do", "end"}
_MF_ESC = {"n": "\n", "t": "\t", "r": "\r", "0": "\0", "e": "\x1b", "s": " ", "d": "\x7f", "b": "\b", "f": "\f",
           "v": "\v", "\\": "\\", '"': '"', "'": "'", "`": "`", "$": "$"}


def _mf_unescape(s):
    def rep(m):
        e = m.group(1)
        if e[0] in "xX" and len(e) > 1:
            return chr(int(e[1:].strip("{}"), 16))
        if e[0] in "uU" and len(e) > 1:
            return chr(int(e[1:].strip("{}"), 16))
        if e[0] in "01234567" and len(e) > 1:
            return chr(int(e, 8))
        return _MF_ESC.get(e, e)
    try:
        return re.sub(r"\\(x\{[0-9a-fA-F]{1,6}\}|x[0-9a-fA-F]{2}|u\{[0-9a-fA-F]{1,6}\}|u[0-9a-fA-F]{4}|[0-7]{1,3}|.)",
                      rep, s, flags=re.S)
    except (ValueError, OverflowError):
        return s


def _mf_close(s, i):
    """Index past the bracket/quote group opening at s[i] (or len(s))."""
    pairs, stack, j, n = {"(": ")", "[": "]", "{": "}"}, [], i, len(s)
    while j < n:
        c = s[j]
        if c in "\"'`":
            k = j + 1
            while k < n and s[k] != c:
                k += 2 if s[k] == "\\" else 1
            j = k + 1
            if not stack:
                return j
            continue
        if c == "%" and s[j - 1:j] != "\\" and _MF_ERL_MODE[0]:
            k = s.find("\n", j)
            j = n if k < 0 else k
            continue
        if c in pairs:
            stack.append(pairs[c])
        elif stack and c == stack[-1]:
            stack.pop()
            if not stack:
                return j + 1
        elif c in ")]}":
            return j
        j += 1
    return n


_MF_ERL_MODE = [False]


def _mf_split(s, seps=","):
    """Top-level split of an expression list (brackets and quotes respected)."""
    out, j, start, n = [], 0, 0, len(s)
    while j < n:
        c = s[j]
        if c in "\"'`([{":
            if c == "'" and _MF_ERL_MODE[0] is None:
                j += 1
                continue
            j = _mf_close(s, j)
            continue
        if c in seps:
            out.append(s[start:j])
            start = j + 1
        j += 1
    out.append(s[start:])
    return [x.strip() for x in out]


def _mf_expr(s, i):
    """The expression starting at s[i]: up to a top-level `,` `;` newline `)` `]` `}` or Erlang end-dot."""
    n, j = len(s), i
    while j < n and s[j] in " \t":
        j += 1
    k = j
    while k < n:
        c = s[k]
        if c in "\"'`([{":
            k = _mf_close(s, k)
            continue
        if c in ",;\n)]}" or (c == "." and (k + 1 >= n or s[k + 1] in " \t\r\n")):
            break
        if s.startswith("end", k) and not re.match(r"\w", s[k + 3:k + 4] or " ") and not re.match(r"\w", s[k - 1:k] or " "):
            break
        k += 1
    return s[j:k].strip(), k


def _mf_value(e, env, depth=0):
    """Literal value of an expression: str, int, list, ('atom', name) or ('tuple', [..]); None when unresolved."""
    e = (e or "").strip()
    if not e or depth > 6:
        return None
    if e[0] == "{" and e[-1] == "}":
        return ("tuple", [_mf_value(x, env, depth + 1) if x else None for x in _mf_split(e[1:-1])])
    parts = [p for p in _mf_split(e, "+") if p] if re.search(r"\+\+|<>|\+", e) else [e]
    if len(parts) > 1:
        parts = [p.strip(" +<>") for p in re.split(r"""(\+\+|<>|\+)(?=(?:[^"'`]*["'`][^"'`]*["'`])*[^"'`]*$)""", e)
                 if p.strip() and p.strip() not in ("++", "<>", "+")]
        vals = [_mf_value(p, env, depth + 1) for p in parts]
        if all(isinstance(v, str) for v in vals):
            return "".join(vals)
        if all(isinstance(v, int) for v in vals):
            return sum(vals)
        return None
    m = re.fullmatch(r'''(?s)(?:~c)?("(?:[^"\\]|\\.)*"\s*)+''', e)
    if m:
        return "".join(_mf_unescape(x) for x in re.findall(r'"((?:[^"\\]|\\.)*)"', e))
    m = re.fullmatch(r"(?s)`([^`]*)`", e)
    if m:
        return m.group(1)
    m = re.fullmatch(r"(?s)'((?:[^'\\]|\\.)*)'", e)
    if m:
        return ("atom", m.group(1)) if _MF_ERL_MODE[0] and env.get("__erl_atoms__") else _mf_unescape(m.group(1))
    m = re.fullmatch(r"(?s)<<\s*(.*?)\s*>>", e)
    if m:
        vals = [_mf_value(x, env, depth + 1) for x in _mf_split(m.group(1))] if m.group(1) else []
        if all(isinstance(v, (str, int)) for v in vals):
            try:
                return "".join(v if isinstance(v, str) else chr(v & 0xFF) for v in vals)
            except ValueError:
                return None
        return None
    m = re.fullmatch(r"(?s)(?:\[\]\s*(?:string|byte|int|interface\{\}|any)\s*\{(.*)\}|\[(.*)\])", e)
    if m:
        body = m.group(1) if m.group(1) is not None else m.group(2)
        vals = [_mf_value(x, env, depth + 1) for x in _mf_split(body)] if body.strip() else []
        if vals and all(isinstance(v, int) and 0 <= v < 0x110000 for v in vals) and m.group(2) is not None and \
                _MF_ERL_MODE[0]:
            return "".join(map(chr, vals))                      # Erlang char list
        return vals
    m = re.fullmatch(r"-?(?:0[xX][0-9a-fA-F]+|\d+)", e)
    if m:
        return int(e, 0) if not re.fullmatch(r"-?0\d+", e) else int(e)
    m = re.fullmatch(r"\$(.)", e)                               # Erlang $c
    if m and _MF_ERL_MODE[0]:
        return ord(m.group(1))
    m = re.fullmatch(r":(\w+[?!]?)|:\"([^\"]*)\"", e)            # Elixir atom
    if m:
        return ("atom", m.group(1) or m.group(2))
    m = re.fullmatch(r"(?:list_to_binary|iolist_to_binary|binary_to_list|unicode:characters_to_binary|"
                     r"lists:flatten|to_string|String\.from|base64:decode|Base\.decode64!?)\((.*)\)", e, re.S)
    if m:
        v = _mf_value(m.group(1), env, depth + 1)
        if isinstance(v, list) and all(isinstance(x, str) for x in v):
            v = "".join(v)
        if isinstance(v, str) and "decode" in e:
            try:
                return base64.b64decode(v).decode("latin-1")
            except (binascii.Error, ValueError):
                return None
        return v if isinstance(v, str) else None
    if re.fullmatch(r"[A-Za-z_][\w.]*", e):
        if e in env:
            return env[e]
        if _MF_ERL_MODE[0] and e[0].islower():
            return ("atom", e)
    return None


def _mf_heads(src):
    """[(pos, name, [params])] of every function head, any of the four syntaxes."""
    out = []
    for rx in _MF_HEADS:
        for m in rx.finditer(src):
            name = m.group("n") or m.groupdict().get("n2")
            args = next((m.group(g) for g in ("a", "a2", "a3") if g in rx.groupindex and m.group(g) is not None), "")
            if name and name not in _MF_KW:
                params = [re.sub(r"\s.*|[^\w]", "", p.strip().split(" ")[0]) if not re.match(r"[\w]+\s+\w", p.strip())
                          else p.strip().split()[0] for p in _mf_split(args)] if args and args.strip() else []
                out.append((m.start(), name, params))
    out.sort()
    return out


def _mf_owner(heads, pos):
    best = None
    for h in heads:
        if h[0] > pos:
            break
        best = h
    return best


def _mf_spawn_target(e):
    """Function name a spawn-like expression starts (or a Worker script), else None."""
    m = re.search(r"""(?:spawn(?:_link|_monitor|_opt)?|Task\.(?:async|start(?:_link)?)|proc_lib:spawn(?:_link)?)\s*\(\s*"""
                  r"""(?:(?:fun\s*\(\s*\)\s*->|fn\s*(?:\(\s*\))?\s*->)\s*(?:[\w:.?]+[:.])?(?P<f>[a-z_]\w*[?!]?)\s*\((?P<a>[^\n]*?)\)\s*end|"""
                  r"""fun\s+(?P<g>[a-z]\w*)/\d+|&(?:__MODULE__\.)?(?P<h>\w+)/\d+|"""
                  r"""(?:\?MODULE|__MODULE__|[\w.:']+)\s*,\s*:?'?(?P<k>[a-z_]\w*)'?\s*,\s*\[(?P<ka>[^\]]*)\])""", e)
    if m:
        f = m.group("f") or m.group("g") or m.group("h") or m.group("k")
        return f, (m.group("a") if m.group("f") else m.group("ka")) or ""
    m = re.search(r"""new\s+Worker\s*\(\s*(?:new\s+URL\(\s*)?["'`]([^"'`]+)["'`]""", e)
    if m:
        return m.group(1), ""
    m = re.search(r"(?:gen_server|GenServer|gen_statem|GenStage)[:.]start(?:_link)?\s*\(\s*(?:\{\s*(?:local|global)\s*,\s*\w+\s*\}\s*,\s*)?"
                  r"(\?MODULE|__MODULE__|[\w.]+)", e)
    if m:
        return "gen_server:" + m.group(1), ""
    return None


def message_flow(src, budget=0.4):
    """Static send edges of an actor / message-passing source (see the block comment). Never raises; [] when none."""
    try:
        return _message_flow(src if isinstance(src, str) else (src or b"").decode("utf-8", "replace"), budget)
    except Exception:
        return []


def _message_flow(src, budget):
    src = src[:1 << 20]
    if not _MF_CUE.search(src):
        return []
    end = time.time() + budget
    erl = bool(_MF_ERL.search(src)) and not re.search(r"(?m)^\s*(?:defmodule|import|const|func|package)\b", src)
    ex = bool(re.search(r"(?m)^\s*defmodule\s", src))
    go = bool(_MF_GO.search(src)) and "chan" in src
    _MF_ERL_MODE[0] = erl
    mod = re.search(r"-module\(\s*'?(\w+)", src) or re.search(r"defmodule\s+([\w.]+)", src)
    mod = mod.group(1) if mod else "?MODULE"
    heads = _mf_heads(src)
    env, procs, ownerbind = {"__erl_atoms__": erl}, {}, {}
    # bindings: literals (lists too) and process handles
    for m in re.finditer(r"(?m)(?:^|[\s,;(])(?:(?:const|let|var)\s+)?(?P<v>[A-Za-z_]\w*)\s*(?::=|=(?![=>~]))\s*", src):
        if time.time() > end:
            break
        e, _ = _mf_expr(src, m.end())
        if not e:
            continue
        st = _mf_spawn_target(e)
        if st:
            procs[m.group("v")] = st[0]
            ownerbind[m.group("v")] = (m.start(), st)
            continue
        if re.fullmatch(r"self\(\)", e):
            o = _mf_owner(heads, m.start())
            procs[m.group("v")] = o[1] if o else "main"
            continue
        v = _mf_value(e, env)
        if v is not None and m.group("v") not in env:
            env[m.group("v")] = v
    for m in re.finditer(r"\{\s*(?:ok|:ok)\s*,\s*(?P<v>[A-Za-z_]\w*)\s*\}\s*=\s*", src):
        e, _ = _mf_expr(src, m.end())
        st = _mf_spawn_target(e)
        if st:
            procs[m.group("v")] = st[0]
    for m in re.finditer(r"(?:register|Process\.register)\(\s*(?P<a>:?'?\w+'?)\s*,\s*(?P<b>:?'?\w+'?)\s*\)", src):
        a, b = m.group("a").strip(":'"), m.group("b").strip(":'")
        if m.group(0).startswith("Process"):
            a, b = b, a
        if b in procs:
            procs[a] = procs[b]
    for m in re.finditer(r"start(?:_link)?\s*\(\s*\{\s*(?:local|global)\s*,\s*(\w+)\s*\}\s*,\s*(\?MODULE|\w+)", src):
        procs[m.group(1)] = "gen_server:" + m.group(2)
    for m in re.finditer(r"start(?:_link)?\s*\(\s*(__MODULE__|[\w.]+)[^)\n]*name:\s*:?(\w+)", src):
        procs[m.group(2)] = "gen_server:" + m.group(1)
    # spawned functions' parameters bound from the spawn arguments
    params = {}
    for v, (pos, (f, args)) in ownerbind.items():
        h = next((x for x in heads if x[1] == f), None)
        if not h or not args:
            continue
        o = _mf_owner(heads, pos)
        for p, a in zip(h[2], _mf_split(args)):
            if a == "self()" or a == "self":
                params[(f, p)] = o[1] if o else "main"
            elif a in procs:
                params[(f, p)] = procs[a]
    srv = {}                                   # handle_call/handle_cast/handle_info module -> process name
    if re.search(r"\bhandle_(?:call|cast|info)\b", src):
        srv[mod] = srv["?MODULE"] = srv["__MODULE__"] = mod

    def proc_name(t, owner):
        t = (t or "").strip()
        t = re.sub(r"^(?:whereis|Process\.whereis)\(\s*:?'?(\w+)'?\s*\)$", r"\1", t).strip(":'")
        if owner and (owner, t) in params:
            return params[(owner, t)]
        if t in procs:
            r = procs[t]
        elif t in ("self()", "self"):
            r = owner or "main"
        else:
            r = t
        if r.startswith("gen_server:"):
            r = r.split(":", 1)[1]
            r = mod if r in ("?MODULE", "__MODULE__") else r
        if r in ("?MODULE", "__MODULE__"):
            r = mod
        return r

    sends = []
    if erl:
        for m in re.finditer(r"(?:(?<![\w?'])(?P<w>whereis\(\s*'?\w+'?\s*\))|(?P<t>\??[A-Za-z_][\w@]*|'[^'\n]+'))\s*!(?!=)\s*", src):
            if (m.group("t") or "") in _MF_KW:
                continue
            e, _ = _mf_expr(src, m.end())
            sends.append((m.start(), m.group("w") or m.group("t"), e, "erlang_send"))
    for m in re.finditer(r"(?<![\w.:])(?P<k>gen_server:(?:call|cast)|GenServer\.(?:call|cast)|send|Process\.send|"
                         r"(?P<o>[\w.]+)\.postMessage|postMessage)\s*\(", src):
        k = m.group("k")
        if k == "send" and not ex and not erl:
            continue
        j = _mf_close(src, m.end() - 1)
        args = _mf_split(src[m.end():j - 1])
        if "postMessage" in k:
            o = m.group("o") or "self"
            tgt = "parent" if o in ("self", "parentPort", "port", "window.parent", "parent", "postMessage") or \
                k == "postMessage" else o
            if args and args[0]:
                sends.append((m.start(), tgt, args[0], "post_message"))
        elif len(args) >= 2:
            sends.append((m.start(), args[0], args[1], k.replace(".", ":").lower().replace("process:send", "send")))
    if go:
        chans = {}
        for m in re.finditer(r"(?:<-\s*(\w+)|\brange\s+(\w+))", src):
            if src[max(0, m.start() - 4):m.start()] == "chan" or m.group(1) == "chan":    # `chan<- T` / `<-chan T`
                continue
            c = m.group(1) or m.group(2)
            o = _mf_owner(heads, m.start())
            chans.setdefault(c, []).append(o[1] if o else "main")
        alias = {}                                     # `go f(ch)` / `f(ch)`: f's channel parameter is ch
        for m in re.finditer(r"(?<![\w.])(?P<f>\w+)\s*\((?P<a>[^()\n]*)\)", src):
            h = next((x for x in heads if x[1] == m.group("f")), None)
            if h and h[0] != m.start() and not src[max(0, m.start() - 5):m.start()].endswith("func "):
                for p, a in zip(h[2], _mf_split(m.group("a"))):
                    if re.fullmatch(r"\w+", a) and a in chans:
                        alias[(h[1], p)] = a
        for m in re.finditer(r"(?m)(?:^|[;{])[ \t]*(?P<c>\w+)\s*<-\s*", src):
            e, _ = _mf_expr(src, m.end())
            o = _mf_owner(heads, m.start())
            c = alias.get((o[1] if o else "main", m.group("c")), m.group("c"))
            sends.append((m.start(), "chan:" + c, e, "go_chan"))
    sends.sort()
    edges = []
    for pos, tgt, e, kind in sends:
        if time.time() > end or len(edges) > 4096:
            break
        o = _mf_owner(heads, pos)
        owner = o[1] if o else "main"
        if kind == "go_chan":
            c = tgt[5:]
            rx = [f for f in chans.get(c, []) if f != owner] if go else []
            recv = rx[0] if rx else ("main" if c in chans else "chan:" + c)
        elif kind == "post_message" and tgt != "parent":
            recv = procs.get(tgt, tgt)
        else:
            recv = proc_name(tgt, owner)
        for val in _mf_expand(src, pos, e, env):
            tag, payload, idx = "", val, None
            if isinstance(val, tuple) and val[0] == "tuple":
                els = val[1]
                if els and isinstance(els[0], tuple) and els[0][0] == "atom":
                    tag, els = els[0][1], els[1:]
                if tag in ("$gen_call", "$gen_cast") and els:
                    els = els[-1:]
                ints = [x for x in els if isinstance(x, int)]
                strs = [x for x in els if isinstance(x, str)]
                idx = ints[0] if ints else None
                payload = strs[-1] if strs else (els[0] if len(els) == 1 else None)
            elif isinstance(val, tuple) and val[0] == "atom":
                tag, payload = val[1], None
            edges.append({"seq": len(edges), "sender": owner, "receiver": recv, "tag": tag,
                          "payload": payload if payload is None or isinstance(payload, (str, int)) else str(payload),
                          "index": idx, "kind": kind, "expr": e[:200]})
    _mf_finals(src, heads, edges)
    return edges


def _mf_expand(src, pos, e, env):
    """The message value(s): one, or one per element when a free variable is bound by a loop over a literal list."""
    v = _mf_value(e, env)
    if v is not None and not _mf_unresolved(v):
        return [v]
    names = [n for n in re.findall(r"(?<![\w:'\"$])([A-Za-z_]\w*)(?![\w(:])", e) if n not in env and n not in _MF_KW
             and not (_MF_ERL_MODE[0] and n[0].islower())]
    win = src[max(0, pos - 4000):pos + 400]
    p0 = min(pos, 4000)
    for n in names:
        q = re.escape(n)
        hits = sorted(((abs(m.start() - p0), m.start(), rx, m) for rx in (
            rf"\b{q}\s*<-\s*", rf"fun\s*\(\s*{q}\s*\)\s*->", rf"fn\s+\(?\s*{q}\s*\)?\s*->",
            rf"(?:const|let|var)\s+{q}\s+of\s+", rf"\.forEach\s*\(\s*(?:function\s*)?\(?\s*{q}\s*\)?\s*(?:=>|\{{)",
            rf"for\s+(?:_\s*,\s*)?{q}\s*:=\s*range\s+") for m in re.finditer(rx, win)), key=lambda x: x[:2])
        for _d, _p, rx, m in hits[:8]:
            if True:
                lst = None
                mm = re.match(r"\[\]\s*\w+\s*\{", win[m.end():]) if "range" in rx else None
                if mm:                                          # Go `range []string{..} {`: the literal only
                    lst = _mf_value(win[m.end():_mf_close(win, m.end() + mm.end() - 1)], env)
                elif "<-" in rx or " of" in rx or "range" in rx:
                    le, _ = _mf_expr(win, m.end())
                    le = re.sub(r"\s*(?:\)\s*)?\{?\s*$", "", le) if "range" in rx or " of" in rx else le
                    le = re.sub(r"\)\s*$", "", le) if " of" in rx else le
                    lst = _mf_value(le, env)
                elif "fun" in rx:                               # lists:foreach(fun(X) -> .. end, List)
                    k = win.find("end", m.end())
                    while k >= 0 and k < len(win):
                        mm = re.match(r"end\s*,\s*", win[k:])
                        if mm:
                            lst = _mf_value(_mf_expr(win, k + mm.end())[0], env)
                            break
                        k = win.find("end", k + 3)
                else:                                           # Enum.each(List, fn x -> ..) / List.forEach(x => ..)
                    head = win[max(0, m.start() - 400):m.start()]
                    mm = re.search(r"(?:Enum\.(?:each|map)\(\s*(?P<a>[^\n]*?)\s*,\s*$)|(?P<b>\[[^\[\]]*\]|[A-Za-z_]\w*)\s*$", head)
                    if mm:
                        lst = _mf_value(mm.group("a") or mm.group("b"), env)
                if isinstance(lst, list) and lst:
                    out = []
                    for item in lst[:256]:
                        v = _mf_value(e, dict(env, **{n: item}))
                        if v is not None:
                            out.append(v)
                    if out:
                        return out
    return [v] if v is not None else [e]


def _mf_unresolved(v):
    return v is None or (isinstance(v, tuple) and v[0] == "tuple" and any(_mf_unresolved(x) for x in v[1]))


def _mf_finals(src, heads, edges):
    """edge['final']: follow `receive {Tag, X} -> .. Next ! {Tag2, X}` forwards (same receiving function)."""
    spans = {}
    for i, h in enumerate(heads):
        stop = next((x[0] for x in heads[i + 1:] if x[1] != h[1]), len(src))
        s0 = spans.get(h[1], (h[0], stop))
        spans[h[1]] = (min(s0[0], h[0]), max(s0[1], stop))
    fwd = {}
    for e in edges:
        f = spans.get(e["sender"])
        if not f:
            continue
        body = src[f[0]:f[1]]
        for m in re.finditer(r"\{\s*(?::|')?(\w+)'?\s*,([^{}\n]*)\}", body):
            vars_ = re.findall(r"(?<![\w:'\"])([A-Z_a-z]\w*)", m.group(2))
            if m.group(1) and any(re.search(rf"(?<![\w:'\"]){re.escape(v)}(?!\w)", e["expr"]) for v in vars_) and \
                    m.group(0) not in e["expr"]:
                fwd.setdefault((e["sender"], m.group(1)), e)
    for e in edges:
        cur, seen = e, set()
        while (cur["receiver"], cur["tag"]) in fwd and (cur["receiver"], cur["tag"]) not in seen and len(seen) < 16:
            seen.add((cur["receiver"], cur["tag"]))
            cur = fwd[(cur["receiver"], cur["tag"])]
        e["final"] = cur["receiver"]


def message_tuples(src):
    """[(sender, receiver, tag, payload)] in source order."""
    return [(e["sender"], e["receiver"], e["tag"], e["payload"]) for e in message_flow(src)]


def message_final_consumers(src):
    """{payload: final consuming process} for every string payload (first edge carrying it wins)."""
    out = {}
    for e in message_flow(src):
        if isinstance(e["payload"], str) and e["payload"] not in out:
            out[e["payload"]] = e["final"]
    return out


def _mf_codecs(src, budget=0.4):
    """Plans carried over messages: each (receiver, tag) group's string payloads joined (index order when every message
    carries an integer index, else source order), and each payload alone, peeled to a plan."""
    try:
        edges = message_flow(src, budget=min(0.3, budget))
        if not edges:
            return []
        end = time.time() + budget
        am = _ANALYSIS_RE.search(src)
        groups, out, seen = {}, [], set()
        for e in edges:
            if isinstance(e["payload"], str) and e["payload"]:
                groups.setdefault((e["final"], e["tag"]), []).append(e)
        cands = []
        for (recv, tag), es in groups.items():
            if all(x["index"] is not None for x in es) and len({x["index"] for x in es}) == len(es):
                es = sorted(es, key=lambda x: x["index"])
            cands.append((f"flow:{recv}:{tag}", "".join(x["payload"] for x in es)))
            cands += [(f"flow:{recv}:{tag}:{x['seq']}", x["payload"]) for x in es if len(es) > 1]
        joined = set()
        for ident, mat in cands:
            if time.time() > end or mat in seen or ident.count(":") > 2 and ident.rsplit(":", 1)[0] in joined:
                continue
            seen.add(mat)
            plain = peel_plan(mat, am.group("tag") if am else "", budget=min(0.2, max(0.05, end - time.time())))
            if plain and (plain.lstrip()[:1] == "{" or len(plan_kv(plain)) >= 3) and \
                    plain not in {c["plain"] for c in out}:     # a lone `v=3 ..` status line is not a plan
                joined.add(ident)
                out.append({"id": ident, "rep": "message_flow", "transform": "identity", "key": "", "material": mat,
                            "plain": plain})
        return out
    except Exception:
        return []


# ---------------------------------------------------------------------------------- compiled BEAM / escript archives
# Target erlang-beam-chunk-literals: the Erlang carrier ships compiled -- a `.beam` (IFF `FOR1 <len> BEAM`, 4-aligned
# chunks: AtU8/Atom atoms, StrT bs_put_string pool, LitT `<<UncompSize:32, zlib>>` (0 = stored) -> `<<N:32, [<<Sz:32,
# ETF>>]>>`, Dbgi/Attr/CInf `term_to_binary`) or an escript whose body after its `#!` / `%%` / `%%!` header lines is a
# zip archive of beams or a bare beam. The compiler folds `++` / list_to_binary / binary_to_list of constants, so the
# descriptor usually sits whole in one LitT literal. _etf_read() is a hand-rolled External Term Format reader (no erlang
# on the box); every string / binary / charlist / atom / flattened iolist is peeled (marker TAG as the layer hint).
# Reached from find_codecs(bytes | latin-1 text) and v3_plan(bytes). Stdlib only, bounded, never raises.
_ETF_NODES = 200000


class _EtfFail(Exception):
    pass


def _etf_read(b, i, st, depth=0):
    """(term, next offset) of one ETF term at b[i:] (no 131 version byte). Atoms -> ('atom', str), binaries and
    STRING_EXT -> bytes, lists -> list, tuples -> tuple, maps -> list of pairs; raises _EtfFail when unreadable."""
    st[0] += 1
    if st[0] > _ETF_NODES or depth > 400 or i >= len(b):
        raise _EtfFail
    import struct
    t = b[i]
    i += 1

    def need(n):
        if i + n > len(b):
            raise _EtfFail
    if t == 97:
        need(1)
        return b[i], i + 1
    if t == 98:
        need(4)
        return struct.unpack(">i", b[i:i + 4])[0], i + 4
    if t == 70:
        need(8)
        return struct.unpack(">d", b[i:i + 8])[0], i + 8
    if t == 99:
        need(31)
        return b[i:i + 31].split(b"\0")[0].decode("latin-1"), i + 31
    if t in (100, 118, 115, 119):                       # ATOM / ATOM_UTF8 (2-byte len), SMALL_ATOM(_UTF8) (1-byte)
        w = 2 if t in (100, 118) else 1
        need(w)
        n = int.from_bytes(b[i:i + w], "big")
        need(w + n)
        return ("atom", b[i + w:i + w + n].decode("utf-8" if t in (118, 119) else "latin-1", "replace")), i + w + n
    if t in (104, 105):
        w = 1 if t == 104 else 4
        need(w)
        n, i = int.from_bytes(b[i:i + w], "big"), i + w
        out = []
        for _ in range(n):
            v, i = _etf_read(b, i, st, depth + 1)
            out.append(v)
        return tuple(out), i
    if t == 106:
        return [], i
    if t == 107:
        need(2)
        n = int.from_bytes(b[i:i + 2], "big")
        need(2 + n)
        return bytes(b[i + 2:i + 2 + n]), i + 2 + n
    if t == 108:
        need(4)
        n, i = int.from_bytes(b[i:i + 4], "big"), i + 4
        if n > len(b):
            raise _EtfFail
        out = []
        for _ in range(n + 1):                          # elements, then the tail (NIL for a proper list)
            v, i = _etf_read(b, i, st, depth + 1)
            out.append(v)
        tail = out.pop()
        return out + ([tail] if tail != [] else []), i
    if t in (109, 77):
        need(4)
        n, i = int.from_bytes(b[i:i + 4], "big"), i + 4 + (t == 77)
        need(n)
        return bytes(b[i:i + n]), i + n
    if t in (110, 111):
        w = 1 if t == 110 else 4
        need(w + 1)
        n = int.from_bytes(b[i:i + w], "big")
        need(w + 1 + n)
        v = int.from_bytes(b[i + w + 1:i + w + 1 + n], "little")
        return (-v if b[i + w] else v), i + w + 1 + n
    if t == 116:
        need(4)
        n, i = int.from_bytes(b[i:i + 4], "big"), i + 4
        if n > len(b):
            raise _EtfFail
        out = []
        for _ in range(n):
            k, i = _etf_read(b, i, st, depth + 1)
            v, i = _etf_read(b, i, st, depth + 1)
            out.append((k, v))
        return out, i
    if t == 113:                                        # EXPORT_EXT fun M:F/A
        out = []
        for _ in range(3):
            v, i = _etf_read(b, i, st, depth + 1)
            out.append(v)
        return tuple(out), i
    if t == 80:                                         # compressed term
        import zlib
        need(4)
        try:
            inner = zlib.decompressobj().decompress(b[i + 4:], 1 << 24)
        except zlib.error:
            raise _EtfFail
        return _etf_read(inner, 0, st, depth + 1)[0], len(b)
    raise _EtfFail


def _etf_term(b):
    """The term of a `term_to_binary` blob (131 version byte), else None."""
    try:
        if b[:1] != b"\x83":
            return None
        return _etf_read(b, 1, [0])[0]
    except (_EtfFail, ValueError, IndexError, RecursionError):
        return None


def _etf_iolist(v, acc, n=0):
    """Flatten an iolist (bytes / 0..255 ints / nested lists) into acc; False when it is not one."""
    if isinstance(v, bytes):
        acc += v
        return True
    if isinstance(v, bool) or n > 64:
        return False
    if isinstance(v, int):
        if 0 <= v < 256:
            acc.append(v)
            return True
        return False
    if isinstance(v, list):
        return all(_etf_iolist(x, acc, n + 1) for x in v)
    return False


def _etf_strings(v, out, n=0):
    """Every string-shaped value of a term (pre-order): binaries, charlists (unicode ints too), atoms, iolists."""
    if len(out) > 4096 or n > 400:
        return
    if isinstance(v, bytes):
        out.append(v.decode("utf-8") if _utf8_ok(v) else v.decode("latin-1"))
    elif isinstance(v, tuple):
        if len(v) == 2 and v[0] == "atom":
            out.append(v[1])
            return
        for x in v:
            _etf_strings(x, out, n + 1)
    elif isinstance(v, list):
        if v and all(isinstance(x, int) and not isinstance(x, bool) and 0 <= x < 0x110000 for x in v):
            try:
                out.append("".join(map(chr, v)))
            except ValueError:
                pass
            return
        acc = bytearray()
        if len(v) > 1 and _etf_iolist(v, acc) and acc:
            out.append(acc.decode("utf-8") if _utf8_ok(acc) else acc.decode("latin-1"))
        for x in v:
            _etf_strings(x, out, n + 1)


def _utf8_ok(b):
    try:
        bytes(b).decode("utf-8")
        return True
    except UnicodeDecodeError:
        return False


def beam_chunks(b):
    """{chunk id: bytes} of a `FOR1 <len> BEAM` module (first of each id), else {}. Never raises."""
    import struct
    out = {}
    try:
        if b[:4] != b"FOR1" or b[8:12] != b"BEAM":
            return {}
        end = min(len(b), 8 + struct.unpack(">I", b[4:8])[0])
        i = 12
        while i + 8 <= end and len(out) < 64:
            cid, n = b[i:i + 4], struct.unpack(">I", b[i + 4:i + 8])[0]
            if not re.match(rb"[A-Za-z0-9]{4}$", cid):
                break
            out.setdefault(cid.decode("ascii"), bytes(b[i + 8:min(i + 8 + n, len(b))]))
            i += 8 + ((n + 3) & ~3)
    except Exception:  # noqa: BLE001
        return out
    return out


def beam_strings(b):
    """[(chunk, string)] recovered statically from a compiled BEAM: LitT literals, StrT pool, atoms, Dbgi / Attr /
    CInf terms. Never raises."""
    import struct
    import zlib
    ch, out = beam_chunks(b), []
    try:
        lit = ch.get("LitT", b"")
        if len(lit) >= 4:
            size = struct.unpack(">I", lit[:4])[0]
            try:
                tab = zlib.decompressobj().decompress(lit[4:], 1 << 24) if size else lit[4:]
            except zlib.error:
                tab = b""
            if len(tab) >= 4:
                j, cnt = 4, struct.unpack(">I", tab[:4])[0]
                for _ in range(min(cnt, 1 << 16)):
                    if j + 4 > len(tab):
                        break
                    sz = struct.unpack(">I", tab[j:j + 4])[0]
                    term = _etf_term(tab[j + 4:j + 4 + sz])
                    j += 4 + sz
                    s = []
                    _etf_strings(term, s)
                    out.extend(("LitT", x) for x in s)
        strt = ch.get("StrT", b"")
        if strt:
            out.append(("StrT", strt.decode("utf-8") if _utf8_ok(strt) else strt.decode("latin-1")))
        at = ch.get("AtU8") or ch.get("Atom") or b""
        if len(at) >= 4:
            cnt, j = struct.unpack(">i", at[:4])[0], 4
            compact = cnt < 0                           # OTP 28 compact-term atom lengths
            for _ in range(min(abs(cnt), 1 << 16)):
                if j >= len(at):
                    break
                n = at[j]
                if compact:
                    if n & 0x08:
                        if j + 1 >= len(at):
                            break
                        n, j = ((n >> 5) << 8) | at[j + 1], j + 2
                    else:
                        n, j = n >> 4, j + 1
                else:
                    j += 1
                out.append(("Atom", at[j:j + n].decode("utf-8" if "AtU8" in ch else "latin-1", "replace")))
                j += n
        for cid in ("Dbgi", "Abst", "Attr", "CInf"):
            if ch.get(cid):
                s = []
                _etf_strings(_etf_term(ch[cid]), s)
                out.extend((cid, x) for x in s)
    except Exception:  # noqa: BLE001
        pass
    return out


def _escript_payload(raw):
    """The archive / beam body of an escript (`#!` + up to 3 header lines), else None."""
    if raw[:2] != b"#!":
        return None
    i = 0
    for _ in range(4):
        if raw[i:i + 4] in (b"PK\x03\x04", b"FOR1"):
            return raw[i:]
        j = raw.find(b"\n", i, i + 4096)
        if j < 0:
            return None
        i = j + 1
    return None


def _beam_bin_units(raw):
    """[(name, beam bytes | text)] of a beam / escript / zip-of-beams carrier."""
    import io
    import zipfile
    body = _escript_payload(raw) if raw[:2] == b"#!" else raw
    if not body:
        return []
    if body[:4] == b"FOR1":
        return [("beam", body)]
    units = []
    try:
        with zipfile.ZipFile(io.BytesIO(body)) as z:
            for zi in z.infolist()[:256]:
                if zi.file_size > (8 << 20) or zi.is_dir():
                    continue
                d = z.read(zi)
                units.append((zi.filename, d if d[:4] == b"FOR1" else d.decode("utf-8", "replace")))
    except Exception:  # noqa: BLE001 - truncated / impostor archive: what was read so far
        pass
    return units


def _is_beam_carrier(raw):
    return bool(raw) and (raw[:4] == b"FOR1" and raw[8:12] == b"BEAM" or
                          raw[:2] == b"#!" and _escript_payload(raw[:1 << 14]) is not None or
                          raw[:4] == b"PK\x03\x04" and b".beam" in raw[:1 << 20])


def _beam_bin_codecs(src, raw=None, budget=0.8):
    """Codec entries for a compiled BEAM / escript archive whose recovered strings peel to a plan. Never raises."""
    try:
        if raw is None:
            if not src:
                return []
            raw = src.encode("latin-1") if max(src[:1 << 16]) < "Ā" and max(src) < "Ā" else \
                src.encode("utf-8", "surrogateescape")
        if not _is_beam_carrier(raw):
            return []
        end, out, seen = time.time() + budget, [], set()
        for name, unit in _beam_bin_units(raw):
            if time.time() > end:
                break
            if isinstance(unit, str):                   # escript archive text member (.erl / .app / .config)
                for c in _find_codecs_text(unit) + (_beam_codecs(unit) if "descriptor" in unit else []):
                    if c.get("plain"):
                        return [dict(c, id=f"{c['id']}@{name}")]
                continue
            strs = beam_strings(unit)
            texts = [s for _, s in strs]
            am = next((m for m in (_ANALYSIS_RE.search(t) for t in texts) if m), None)
            tag = am.group("tag") if am else ""
            dids = sorted({m.group(1) for t in texts for m in [re.match(r"descriptor_?(\w+)$", t)] if m})
            ident = (dids[0] if len(dids) == 1 else "beam") + "@" + name
            cands = [(c, s) for c, s in strs if c != "Atom" and len(s) >= 8] + \
                    ([("AM", am.group("mat"))] if am else []) + [(c, s) for c, s in strs if c == "Atom" and len(s) >= 16]
            for cid, s in cands:
                if s in seen or time.time() > end:
                    continue
                seen.add(s)
                plain = s.lstrip("﻿ \r\n\t") if looks_like_plan(s.encode("utf-8", "replace")) else \
                    peel_plan(s, tag, budget=min(0.15, max(0.02, end - time.time())))
                if plain:
                    return [{"id": ident, "rep": "beam", "transform": "identity", "key": "",
                             "material": s, "plain": plain, "chunk": cid}]
            for c in _find_codecs_text("\n".join(t for t in texts if len(t) < (1 << 16))):
                if c.get("plain"):
                    return [dict(c, id=f"{c['id']}@{name}")]
        return out
    except Exception:  # noqa: BLE001
        return []


# ---------------------------------------------------------------------------------- shell function-return descriptors
# Target zsh-fish-minimal-v3-fixtures: the descriptor as a shell function's output -- zsh/bash `build_plan_x() { print
# -r -- ".." }` / `function descriptor_x { echo ".." }`, fish `function build_plan_x; echo ".."; end` (newline or `;`
# separated). The body's print / echo / printf '%s' literals (joined in order) and each literal alone are peeled with the
# marker TAG as the layer hint. Static (never runs a shell); gated on a function header + print/echo cue. Never raises.
_SHFN_CUE = re.compile(r"(?m)^[ \t]*(?:function[ \t]+[A-Za-z_][\w-]*|[A-Za-z_][\w-]*[ \t]*\([ \t]*\)[ \t]*\{)")
_SHFN_PR = re.compile(r"\b(?:print|echo|printf)[ \t]+[-'\"\w]")
_SHFN_NAMED = re.compile(r"(?mi)^[ \t]*(?:function[ \t]+)?(?:build_plan|descriptor)\w*")
_SHFN_HEAD = re.compile(r"(?m)(?:^|(?<=[;{]))[ \t]*(?:function[ \t]+(?P<a>[A-Za-z_][\w-]*)(?:[ \t]*\(\s*\))?|"
                        r"(?P<b>[A-Za-z_][\w-]*)[ \t]*\(\s*\))")
_SHFN_LIT = re.compile(r"""\b(?:print|echo|printf)\b(?:[ \t]+(?:-[A-Za-z]+|--|'%s'|"%s"))*[ \t]+"""
                       r"""(?:"(?P<d>(?:[^"\\$`]|\\.)*)"|'(?P<s>[^']*)'|(?P<w>[A-Za-z0-9+/=._:-]{16,}))""")


def _shfn_codecs(src, budget=0.4):
    """Codec entries for shell functions whose printed literal peels to a plan (marker TAG as the layer hint)."""
    try:
        end, out, seen = time.time() + budget, [], set()
        am = _ANALYSIS_RE.search(src)
        tag = am.group("tag") if am else ""
        heads = list(_SHFN_HEAD.finditer(src[:1 << 20]))[:64]
        for k, m in enumerate(heads):
            if time.time() > end:
                break
            name = m.group("a") or m.group("b")
            stop = heads[k + 1].start() if k + 1 < len(heads) else len(src)
            e = re.compile(r"(?m)^[ \t]*(?:end\b|\})|;[ \t]*(?:end\b|\})").search(src, m.end(), stop)
            body = src[m.end():e.end() if e else min(stop, m.end() + (1 << 16))]
            lits = [x.group("d") if x.group("d") is not None else x.group("s") if x.group("s") is not None
                    else x.group("w") for x in _SHFN_LIT.finditer(body)][:32]
            lits = [re.sub(r"\\(.)", r"\1", x) if "\\" in x else x for x in lits]
            for cand in ([("".join(lits))] if len(lits) > 1 else []) + lits:
                if len(cand) < 16 or cand in seen or time.time() > end:
                    continue
                seen.add(cand)
                plain = peel_plan(cand, tag, budget=min(0.3, max(0.05, end - time.time())))
                if plain:
                    out.append({"id": re.sub(r"(?i)^(?:descriptor|build_plan)_?", "", name) or name,
                                "rep": "descriptor", "transform": "identity", "key": "", "material": cand,
                                "plain": plain})
                    break
        return out
    except Exception:
        return []


# ------------------------------------------------------------------------------------------ awk / sed descriptors
# Target awk-sed-minimal-v3-fixtures: awk `BEGIN { descriptor_x = ".." }` / `function build_plan_x() { return ".." }`
# with juxtaposition concat `"ab" "cd"` (awk escapes `\" \\ \/`), sed `s/^.*$/<data>/p` (any delimiter, `\<delim>`
# unescaped) and `1i\` / `$a\` / `c\` text commands (continuation lines ending in `\`, GNU one-line `1i text`); `y///`
# is noise. Each candidate is peeled with the marker TAG as the layer hint. Static (never runs awk / sed); gated on an
# awk / sed shebang, a `#n` first line or awk BEGIN / function cues. Never raises.
_AWKSED_CUE = re.compile(r"(?m)\A(?:#![^\n]*\b(?:[gnm]?awk|g?sed)\b|#n[ \t]*\r?\n)|^[ \t]*(?:BEGIN[ \t]*\{|"
                         r"function[ \t]+[A-Za-z_]\w*[ \t]*\([^)\n]*\)[ \t]*\{|\d*\$?[aic]\\\r?$|s/\^\.\*\$/)")
_AWK_STR = r'"(?:[^"\\\n]|\\.)*"'
_AWK_EXPR = re.compile(r"(?m)(?:\breturn\b[ \t(]*|\b[A-Za-z_]\w*[ \t]*=(?!=)[ \t]*)((?:%s)(?:(?:[ \t]|\\\r?\n)*%s)*)"
                       % (_AWK_STR, _AWK_STR))
_AWK_ESC = {"n": "\n", "t": "\t", "r": "\r", "/": "/", '"': '"', "\\": "\\"}
_SED_SUB = re.compile(r"(?m)^[ \t]*(?:[\d$]+[ \t]*|/[^/\n]*/[ \t]*)?s([^\w\s\\])\^?\.\*\$?\1((?:[^\\\n]|\\.)*?)\1[gpI\d]*"
                      r"[ \t]*(?:;|$)")
_SED_TXT = re.compile(r"(?m)^[ \t]*(?:[\d$]+[ \t]*|/[^/\n]*/[ \t]*)?[aic][ \t]*(?:\\\r?\n((?:[^\n]*\\\r?\n)*[^\n]*)|"
                      r"(?![ \t]*\\)[ \t]*([^\n]+))")


def _awksed_codecs(src, budget=0.4):
    """Codec entries for awk string assignments / returns and sed s///-replacement / text-command data."""
    try:
        end, out, seen = time.time() + budget, [], set()
        am = _ANALYSIS_RE.search(src)
        tag = am.group("tag") if am else ""
        body = "\n".join(ln for ln in src[:1 << 20].splitlines() if "HUNTRESS_ANALYSIS" not in ln)
        cands = []
        for m in list(_AWK_EXPR.finditer(body))[:64]:
            lits = re.findall(_AWK_STR, m.group(1))
            cands.append("".join(re.sub(r"\\(.)", lambda e: _AWK_ESC.get(e.group(1), "\\" + e.group(1)), x[1:-1])
                                 for x in lits))
        for m in list(_SED_SUB.finditer(body))[:64]:
            d = re.escape(m.group(1))
            cands.append(re.sub(r"\\(%s|\\)" % d, r"\1", m.group(2)))
        for m in list(_SED_TXT.finditer(body))[:64]:
            t = m.group(1) if m.group(1) is not None else m.group(2)
            t = re.sub(r"\\\r?\n", "\n", t)
            cands.append(re.sub(r"\\(.)", r"\1", t))
        for cand in cands:
            cand = cand.strip()
            if len(cand) < 16 or cand in seen or time.time() > end:
                continue
            seen.add(cand)
            plain = peel_plan(cand, tag, budget=min(0.3, max(0.05, end - time.time())))
            if plain:
                out.append({"id": "awk_sed", "rep": "descriptor", "transform": "identity", "key": "",
                            "material": cand, "plain": plain})
        return out
    except Exception:
        return []


# ------------------------------------------------------------------------------------------- JSP / JSPX carrier twists
# Target jsp-jspx-unicode-carrier: javac reads `\uXXXX` escapes before it lexes, so `\u002f\u002f String DESCRIPTOR_X =
# ".."` is a dead comment (a decoy) and `// note \u000a String descriptor_x = ".."` is live code; JSPX bodies are XML
# (entities decoded outside CDATA, then the unicode escapes); `<%@ include file=..%>` / `<jsp:directive.include ../>` /
# `<jsp:include page=..>` / web.xml `<include-prelude>` splice another member (.war/.jar zip, .jspf/.tag/.tagx); and a
# descriptor may be `A + ".."` over other String constants. jsp_text() gives the normalised live Java text per entry
# page (comments stripped, constant concatenations folded into one literal); _jsp_codecs() reads it through
# find_codecs at depth 1. Gated on JSP/JSPX/Java cues (cheap substring tests); never raises.
_JSP_CUE = re.compile(r"<%|<jsp:|xmlns:jsp\b|\.jspf?\b|\.tagx?\b")
_JAVA_CUE = re.compile(r"\bimport\s+java\.|\bclass\s+\w+|\bstatic\s+final\s+String\b")
_JSP_UESC = re.compile(r"(?<!\\)((?:\\\\)*)\\u+([0-9a-fA-F]{4})")
_JSP_INCL = re.compile(r"""<%@\s*include\s+file\s*=\s*["']([^"']+)["']\s*%>|"""
                       r"""<jsp:(?:directive\.)?include\s+(?:file|page)\s*=\s*["']([^"']+)["'][^>]*>""")
_JSP_REGION = re.compile(r"<%(?!--)[!=]?(.*?)%>|<jsp:(declaration|scriptlet|expression)\b[^>]*>(.*?)</jsp:\2\s*>", re.S)
_JSP_LIT = r'"(?:[^"\\\n]|\\.)*"'
_JSP_CAT = re.compile(r"(?:%s|[A-Za-z_]\w*)(?:\s*\+\s*(?:%s|[A-Za-z_]\w*))+" % (_JSP_LIT, _JSP_LIT))
_JSP_DEF = re.compile(r"\b([A-Za-z_]\w*)\s*=\s*((?:%s|[A-Za-z_]\w*)(?:\s*\+\s*(?:%s|[A-Za-z_]\w*))*)\s*;"
                      % (_JSP_LIT, _JSP_LIT))
_JSP_JESC = {"n": "\n", "t": "\t", "r": "\r", "b": "\b", "f": "\f", "s": " ", "0": "\0", '"': '"', "'": "'", "\\": "\\"}


def _jsp_uesc(s):
    return _JSP_UESC.sub(lambda m: m.group(1) + chr(int(m.group(2), 16)), s)


def _jsp_xml(s):
    """XML text of a JSPX body: entities decoded outside CDATA, CDATA sections kept verbatim."""
    import html
    out, pos = [], 0
    for m in re.finditer(r"<!\[CDATA\[(.*?)\]\]>", s, re.S):
        out.append(html.unescape(s[pos:m.start()]))
        out.append(m.group(1))
        pos = m.end()
    return "".join(out) + html.unescape(s[pos:])


def _jsp_strip_comments(s):
    """Java code with `//` and `/* */` comments removed (string / char literals respected)."""
    out, i, n = [], 0, len(s)
    while i < n:
        c = s[i]
        if c == '"':
            m = re.compile(_JSP_LIT).match(s, i)
            j = m.end() if m else i + 1
            out.append(s[i:j])
            i = j
        elif c == "'":
            m = re.compile(r"'(?:[^'\\\n]|\\[^\n]{1,6}?)'").match(s, i)
            j = m.end() if m else i + 1
            out.append(s[i:j])
            i = j
        elif s.startswith("//", i):
            j = s.find("\n", i)
            i = n if j < 0 else j
        elif s.startswith("/*", i):
            j = s.find("*/", i + 2)
            out.append(" ")
            i = n if j < 0 else j + 2
        else:
            out.append(c)
            i += 1
    return "".join(out)


def _jsp_lit_val(lit):
    return re.sub(r"\\(.)", lambda m: _JSP_JESC.get(m.group(1), m.group(1)), lit[1:-1])


def _jsp_fold(java):
    """Fold `NAME = "a" + OTHER + "b";` String-constant concatenations into one literal (bounded, in source order)."""
    env = {}
    for m in list(_JSP_DEF.finditer(java))[:256]:
        parts, ok = re.findall(r'%s|[A-Za-z_]\w*' % _JSP_LIT, m.group(2)), True
        val = []
        for p in parts:
            if p.startswith('"'):
                val.append(_jsp_lit_val(p))
            elif p in env:
                val.append(env[p])
            else:
                ok = False
                break
        if ok and (len(parts) > 1 or parts[0].startswith('"') or parts[0] in env):
            env[m.group(1)] = "".join(val)[:1 << 20]

    def cat(m):
        parts = re.findall(r'%s|[A-Za-z_]\w*' % _JSP_LIT, m.group(0))
        if not all(p.startswith('"') or p in env for p in parts):
            return m.group(0)
        v = "".join(_jsp_lit_val(p) if p.startswith('"') else env[p] for p in parts)
        return '"' + v.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'
    if not env:
        return java
    java = _JSP_CAT.sub(cat, java)
    # a bare `DESCRIPTOR_X = OTHER;` alias of a folded constant
    return re.sub(r"\b((?i:descriptor)\w*)\s*=\s*([A-Za-z_]\w*)\s*;",
                  lambda m: f'{m.group(1)} = "{env[m.group(2)]}";' if m.group(2) in env and '"' not in env[m.group(2)]
                  and "\\" not in env[m.group(2)] else m.group(0), java)


def _jsp_members(data):
    """{name: text} of a .war/.jar zip (bytes via zipfile; a lossy-decoded str of a STORED zip by its local headers),
    JSP-family / Java / web.xml members only; {} when it is not a zip."""
    import io
    import zipfile
    keep = re.compile(r"(?i)\.(?:jspx?|jspf|tagx?|java|xml|txt)$")
    out = {}
    try:
        if isinstance(data, (bytes, bytearray)) and bytes(data[:4]) == b"PK\x03\x04":
            with zipfile.ZipFile(io.BytesIO(bytes(data))) as z:
                for zi in z.infolist()[:2000]:
                    if keep.search(zi.filename) and zi.file_size < (4 << 20):
                        out[zi.filename] = z.read(zi).decode("utf-8", "replace")
                    if len(out) >= 200:
                        break
        elif isinstance(data, str) and data[:4] == "PK\x03\x04":
            body = data.split("PK\x01\x02", 1)[0]
            for chunk in body.split("PK\x03\x04")[1:201]:
                for p in range(22, 41):                 # u16 name length + u16 extra length (0) survive the decode
                    ln = ord(chunk[p - 4]) + 256 * ord(chunk[p - 3]) if len(chunk) > p else 0
                    if 0 < ln < 512 and chunk[p - 2:p] == "\x00\x00" and keep.search(chunk[p:p + ln]) and \
                            re.fullmatch(r"[\w$./-]+", chunk[p:p + ln]):
                        out[chunk[p:p + ln]] = chunk[p + ln:]
                        break
    except Exception:  # noqa: BLE001
        return out
    return out


def _jsp_resolve(ref, cur, members):
    import posixpath
    ref = ref.strip()
    base = posixpath.dirname(cur)
    for cand in (ref.lstrip("/"), posixpath.normpath(posixpath.join(base, ref)).lstrip("/")):
        if cand in members:
            return cand
    tail = [k for k in members if k.endswith("/" + ref.lstrip("/").split("/")[-1]) or k == ref.split("/")[-1]]
    return tail[0] if len(tail) == 1 else None


def _jsp_page(name, text, members, depth=0, seen=()):
    """Page text with its includes spliced in (bounded depth, cycle-safe)."""
    if depth > 4 or not members:
        return text

    def sub(m):
        ref = _jsp_resolve(m.group(1) or m.group(2), name, members)
        if not ref or ref in seen:
            return m.group(0)
        return _jsp_page(ref, members[ref], members, depth + 1, seen + (ref,))
    return _JSP_INCL.sub(sub, text)


def _jsp_java(text, xml=None):
    """Live Java of one JSP/JSPX/tag/Java text: XML entities (JSPX), unicode escapes, comments, constant folds."""
    if xml is None:
        xml = bool(re.search(r"<jsp:root\b|xmlns:jsp\b|<jsp:(?:declaration|scriptlet|expression)\b", text[:1 << 16]))
    text = re.sub(r"<%--.*?--%>", " ", text, flags=re.S)
    regions, bare = [], False
    for m in _JSP_REGION.finditer(text):
        if m.group(3) is not None:
            body = _jsp_xml(m.group(3)) if xml else m.group(3)
            kind = {"declaration": "!", "expression": "="}.get(m.group(2), "")
        else:
            body = m.group(1)
            kind = text[m.start() + 2:m.start() + 3] if text[m.start() + 2:m.start() + 3] in "!=" else ""
        regions.append((kind, body))
    if not regions:
        if not _JAVA_CUE.search(text[:1 << 16]):
            return None
        regions, bare = [("", text)], True
    java = "\n".join(_jsp_strip_comments(_jsp_uesc(b)) if bare else f"<%{k}{_jsp_strip_comments(_jsp_uesc(b))}%>"
                     for k, b in regions)
    return _jsp_fold(java)


def jsp_text(data, members=None):
    """[(entry, normalised live Java text)] of a JSP / JSPX / .tag(x) / Java source, or of every entry page of a
    .war/.jar zip (includes and web.xml include-prelude/-coda spliced from the other members). [] when nothing reads.
    Never raises."""
    try:
        zm = _jsp_members(data)
        if zm:
            members = zm
        if not members:
            text = data.decode("utf-8", "replace") if isinstance(data, (bytes, bytearray)) else (data or "")
            j = _jsp_java(text)
            return [("", j)] if j else []
        wx = next((v for k, v in members.items() if k.lower().endswith("web-inf/web.xml")), "")
        pre = re.findall(r"<include-prelude>\s*([^<\s]+)\s*</include-prelude>", wx)
        coda = re.findall(r"<include-coda>\s*([^<\s]+)\s*</include-coda>", wx)
        included = set()
        for k, v in members.items():
            for m in _JSP_INCL.finditer(v):
                r = _jsp_resolve(m.group(1) or m.group(2), k, members)
                if r:
                    included.add(r)
        for p in pre + coda:
            r = _jsp_resolve(p, "", members)
            if r:
                included.add(r)
        pages = [k for k in members if re.search(r"(?i)\.(?:jspx?|tagx?|java)$", k) and k not in included] or \
            [k for k in members if re.search(r"(?i)\.(?:jspx?|jspf|tagx?|java)$", k)]
        out = []
        for k in pages[:64]:
            parts = [members[r] for r in (_jsp_resolve(p, "", members) for p in pre) if r]
            parts.append(_jsp_page(k, members[k], members, 0, (k,)))
            parts += [members[r] for r in (_jsp_resolve(p, "", members) for p in coda) if r]
            xml = k.lower().endswith(("x", ".tagx"))
            j = "\n".join(filter(None, (_jsp_java(t, xml or None) for t in parts)))
            if j:
                out.append((k, j))
        return out
    except Exception:  # noqa: BLE001
        return []


def _jsp_codecs(src, raw=None, budget=0.6):
    """Codecs read from the normalised live Java of a JSP-family source / .war (see jsp_text). Never raises."""
    out, end = [], time.time() + budget
    try:
        for name, j in jsp_text(raw if raw is not None and raw[:4] == b"PK\x03\x04" else src):
            if time.time() > end:
                break
            if not name and j.strip() == (src or "").strip():
                continue                                # nothing normalised: the plain reading already ran
            for c in find_codecs(j, 1):
                if c.get("plain"):
                    out.append(dict(c, id=f"{c['id']}@jsp{':' + name if name else ''}"))
    except Exception:  # noqa: BLE001
        return out
    return out


def v3_plan(src):
    """The v=3 plan text of a source (str or bytes, UTF-16/BOM'd sources too), else None. Never raises."""
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            if b[:4] == b"PK\x03\x04" and re.search(rb"\.(?:jspx?|jspf|tagx?)\b", b[:1 << 22]):
                for c in _jsp_codecs(None, b):          # .war / .jar: deflated members, includes across members
                    if c["plain"].lstrip().startswith("v=3"):
                        return c["plain"]
            u = _utf16(b[:1 << 22]) if (b[:2] in (b"\xff\xfe", b"\xfe\xff") or b[1:64:2].count(0) > 20
                                         or b[0:64:2].count(0) > 20) else None
            if _is_beam_carrier(b[:1 << 20]):
                for c in _beam_bin_codecs(None, b):     # compiled .beam / escript archive: the bytes, not utf-8
                    if c["plain"].lstrip().startswith("v=3"):
                        return c["plain"]
            src = (u or b).decode("utf-8", "ignore").lstrip("﻿")
        for c in find_codecs(src or ""):
            p = c.get("plain")
            if p and (p.lstrip().startswith("v=3") or re.match(r'\s*\{\s*"v"\s*:\s*"?3\b', p)):
                return p
    except Exception:
        return None
    return None


def is_v3(src):
    """True when a source is a v=3 polyglot (HUNTRESS_ANALYSIS marker, or a descriptor peeling to a `v=3` plan): route
    it to the v=3 reader before the v=1 `$encodedMaterial` / `$nativeTypes` JSON path. Never raises."""
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            if _PSV3_MARK.search(b.decode("latin-1")) or _PSV3_MARK.search(b.replace(b"\x00", b"").decode("latin-1")):
                return True
        elif _PSV3_MARK.search(src or ""):
            return True
        return v3_plan(src) is not None
    except Exception:
        return False


# ------------------------------------------------------------------------------------------------ PowerShell layer peel
# Target ps-layer-peel: the Invoke-Obfuscation family hides the descriptor / marker behind constant PowerShell string
# expressions: backtick ticks, `'a'+'b'`, `"{1}{0}" -f ..`, `[char]N` / `[char[]](..)` / `-join`, `[string]::Join`,
# `'..'[-1..-N]` reversal, `.Replace()` / `-replace`, `$env:comspec[4,15,25]` style env-index tables, and the payload
# layers `-EncodedCommand <UTF-16LE b64>`, `[Text.Encoding]::X.GetString([Convert]::FromBase64String(..))` and
# Deflate/GzipStream over FromBase64String. _ps_codecs() folds the constants statically (never runs anything), then
# reads the folded text and every decoded payload through the normal text readings. Consulted by find_codecs() only
# when nothing else produced a plan, so every earlier reading is unchanged. Bounded, pure python, never raises.
_PS_HINT = re.compile(r"""-f\s*['"(]|\[char\b|\[char\[\]\]|-join\b|::join\(|frombase64string|\s[-/]e(?:c|nc\w*)\s+['"]?[A-Za-z0-9+/]{16}|"""
                      r"""\$env:|\$pshome\b|\$shellid\b|invoke-expression|-[ci]?replace\b""", re.I)
_PS_S = r"'(?:[^']|'')*'"
_PS_SG = r"('(?:[^']|'')*')"
_PS_ENV = {"comspec": r"C:\WINDOWS\system32\cmd.exe", "pshome": r"C:\Windows\System32\WindowsPowerShell\v1.0",
           "shellid": "Microsoft.PowerShell", "verbosepreference": "SilentlyContinue", "public": r"C:\Users\Public",
           "windir": r"C:\WINDOWS", "systemroot": r"C:\WINDOWS", "programdata": r"C:\ProgramData"}
_PS_DQ_ESC = {"0": "\0", "a": "\a", "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t", "v": "\v"}


def _ps_q(s):
    return "'" + s.replace("'", "''") + "'"


def _ps_u(lit):
    return lit[1:-1].replace("''", "'")


def _ps_list(body):
    """'a','b' (single-quoted literals, comma separated) -> [str], else None."""
    if not re.fullmatch(r"\s*" + _PS_S + r"(?:\s*,\s*" + _PS_S + r")*\s*", body):
        return None
    return [_ps_u(a) for a in re.findall(_PS_S, body)]


def _ps_nums(body):
    toks = [t for t in re.split(r"[\s,]+", body.strip()) if t]
    try:
        return [int(t, 0) for t in toks] if toks else None
    except ValueError:
        return None


def _ps_tokens(src):
    """Normalise quoting: constant double-quoted strings (no `$`) -> single-quoted with backtick escapes applied; ticks
    outside strings dropped; comments kept verbatim."""
    out, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c == "#" or src.startswith("<#", i):
            j = src.find("#>", i + 2) + 2 if c == "<" else src.find("\n", i)
            j = n if j < (2 if c == "<" else 0) else j
            out.append(src[i:j])
            i = j
        elif c == "'":
            m = re.compile(_PS_S).match(src, i)
            if not m:
                out.append(src[i:])
                break
            out.append(m.group(0))
            i = m.end()
        elif c == '"':
            j, buf, const = i + 1, [], True
            while j < n:
                d = src[j]
                if d == "`" and j + 1 < n:
                    buf.append(_PS_DQ_ESC.get(src[j + 1], src[j + 1]))
                    j += 2
                    continue
                if d == '"':
                    if src.startswith('""', j):
                        buf.append('"')
                        j += 2
                        continue
                    break
                if d == "$":
                    const = False
                buf.append(d)
                j += 1
            out.append(_ps_q("".join(buf)) if const else src[i:j + 1])
            i = j + 1
        elif c == "`" and i + 1 < n and src[i + 1] not in "\r\n":
            i += 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


def _ps_format(fmt, args):
    def sub(m):
        if m.group(0) in ("{{", "}}"):
            return m.group(0)[0]
        k = int(m.group(1))
        if k >= len(args):
            raise IndexError
        return args[k]
    return re.sub(r"\{\{|\}\}|\{(\d+)\}", sub, fmt)


def _ps_fold_once(t):
    S, SG = _PS_S, _PS_SG
    NUMS = r"((?:\s*(?:0x[0-9a-fA-F]+|\d+)\s*,)*\s*(?:0x[0-9a-fA-F]+|\d+)\s*)"
    rules = []

    def env(m):
        return _ps_q(_PS_ENV[m.group(1).lower()])
    rules.append((r"\$(?:env:)?(comspec|pshome|shellid|public|windir|systemroot|programdata)\b(?![\w:])", env, re.I))
    rules.append((r"\(?\s*\$(verbosepreference)\b(?:\.tostring\(\s*\))?\s*\)?(?=\s*\[)|\[string\]\s*\$(verbosepreference)\b",
                  lambda m: _ps_q(_PS_ENV["verbosepreference"]), re.I))

    def ch(m):
        v = int(m.group(1), 0)
        return _ps_q(chr(v)) if v < 0x110000 else m.group(0)
    rules.append((r"\[char\]\s*\(?\s*(0x[0-9a-fA-F]+|\d+)\s*\)?", ch, re.I))
    rules.append((r"\[char\[\]\]\s*@?\(" + NUMS + r"\)", lambda m: "(" + ",".join(_ps_q(chr(v)) for v in _ps_nums(m.group(1))) + ")", re.I))
    rules.append((r"\(?\s*@?\(" + NUMS + r"\)\s*\|\s*(?:%|foreach-object|foreach)\s*\{\s*\[char\]\s*\$_\s*\}\s*\)?",
                  lambda m: "(" + ",".join(_ps_q(chr(v)) for v in _ps_nums(m.group(1))) + ")", re.I))
    rules.append((r"\[char\[\]\]\s*" + SG, lambda m: "(" + ",".join(_ps_q(c) for c in _ps_u(m.group(1))) + ")", re.I))
    rules.append((SG + r"\.tochararray\(\s*\)", lambda m: "(" + ",".join(_ps_q(c) for c in _ps_u(m.group(1))) + ")", re.I))

    def idx(m):
        s, body = _ps_u(m.group(1)), m.group(2)
        r = re.fullmatch(r"\s*(-?\d+)\s*\.\.\s*-?\s*\(?\s*(-?\d+|" + S + r"\.length)\s*\)?\s*", body, re.I)
        if r:
            a = int(r.group(1))
            b = -len(s) if r.group(2).lower().endswith(".length") else int(r.group(2))
            if body.replace(" ", "").split("..")[1].startswith("-") and b > 0:
                b = -b
            step = 1 if b >= a else -1
            ks = range(a, b + step, step)
        else:
            ks = _ps_nums(body.replace("-", " -").replace(" -", "-")) if re.fullmatch(r"[\s\d,\-x]+", body) else None
            if ks is None:
                try:
                    ks = [int(k) for k in body.split(",")]
                except ValueError:
                    return m.group(0)
        got = [s[k] for k in ks if -len(s) <= k < len(s)]
        if len(got) != len(list(ks)):
            return m.group(0)
        return _ps_q(got[0]) if len(got) == 1 and "," not in body and ".." not in body else "(" + ",".join(_ps_q(c) for c in got) + ")"
    rules.append((SG + r"\s*\[([^\[\]]{1,80})\]", idx, re.I))

    def rtl(m):
        return "(" + ",".join(_ps_q(c) for c in _ps_u(m.group(1))[::-1]) + ")"
    rules.append((r"\[regex\]::matches\(\s*" + SG + r"\s*,\s*'\.'\s*,\s*'righttoleft'\s*\)\s*\|\s*(?:%|foreach-object|foreach)"
                  r"\s*\{\s*\$_(?:\.value)?\s*\}", rtl, re.I))
    rules.append((r"(?<![\w\]\)\.\$])\(\s*" + SG + r"\s*\)", lambda m: m.group(1), 0))

    def fmt(m, lead=""):
        args = _ps_list(m.group(m.lastindex))
        if args is None:
            return m.group(0)
        try:
            return lead + _ps_q(_ps_format(_ps_u(m.group(m.lastindex - 1)), args))
        except (IndexError, ValueError):
            return m.group(0)
    rules.append((r"(?<![\w\]\)\.\$])\(\s*" + SG + r"\s*-f\s*((?:" + S + r"\s*,\s*)*" + S + r")\s*\)", fmt, re.I))
    rules.append((r"(?<=[=;(\n])(\s*)" + SG + r"\s*-f\s*((?:" + S + r"\s*,\s*)*" + S + r")(?=\s*[;)\n]|\s*$)",
                  lambda m: fmt(m, m.group(1)), re.I))

    def join_bin(m):
        items = _ps_list(m.group(1))
        return m.group(0) if items is None else _ps_q(_ps_u(m.group(2)).join(items))
    rules.append((r"\(\s*((?:" + S + r"\s*,\s*)*" + S + r")\s*\)\s*-join\s*" + SG, join_bin, re.I))

    def join_un(m):
        items = _ps_list(m.group(1))
        return m.group(0) if items is None else _ps_q("".join(items))
    rules.append((r"-join\s*\(\s*((?:" + S + r"\s*,\s*)*" + S + r")\s*\)", join_un, re.I))
    rules.append((r"\[string\]::join\(\s*" + SG + r"\s*,\s*\(?\s*((?:" + S + r"\s*,\s*)*" + S + r")\s*\)?\s*\)",
                  lambda m: (lambda it: m.group(0) if it is None else _ps_q(_ps_u(m.group(1)).join(it)))(_ps_list(m.group(2))), re.I))
    rules.append((SG + r"\.replace\(\s*" + SG + r"\s*,\s*" + SG + r"\s*\)",
                  lambda m: _ps_q(_ps_u(m.group(1)).replace(_ps_u(m.group(2)), _ps_u(m.group(3)))), re.I))

    def rx(m):
        a, pat, rep = _ps_u(m.group(1)), _ps_u(m.group(3)), _ps_u(m.group(4))
        if "$" in rep or t[max(0, m.start() - 8):m.start()].rstrip().endswith("+"):     # `+` binds tighter
            return m.group(0)
        try:
            return _ps_q(re.sub(pat, lambda _: rep, a, flags=0 if m.group(2).lower() == "c" else re.I))
        except re.error:
            return m.group(0)
    rules.append((SG + r"\s*-([ci]?)replace\s*" + SG + r"\s*,\s*" + SG + r"(?!\s*[\[\.+])", rx, re.I))
    def cat(m):
        before = t[max(0, m.start() - 8):m.start()].rstrip()
        if re.search(r"(?:[,.\w\]\)'*]|-f)$", before, re.I):          # `-f`, `,`, `*`, member access bind tighter
            return m.group(0)
        return _ps_q(_ps_u(m.group(1)) + _ps_u(m.group(2)))
    rules.append((SG + r"\s*\+\s*" + SG + r"(?!\s*(?:[\[\.,*]|-f\b))", cat, re.I))

    def b64s(m):
        try:
            raw = base64.b64decode(re.sub(r"\s", "", _ps_u(m.group(2))), validate=False)
            enc = {"unicode": "utf-16-le", "bigendianunicode": "utf-16-be", "utf8": "utf-8", "ascii": "latin-1",
                   "default": "latin-1", "utf32": "utf-32-le"}.get(m.group(1).lower(), "utf-8")
            return _ps_q(raw.decode(enc))
        except (ValueError, UnicodeDecodeError):
            return m.group(0)
    rules.append((r"\[(?:system\.)?text\.encoding\]::(\w+)\.getstring\(\s*\[(?:system\.)?convert\]::frombase64string\(\s*"
                  + SG + r"\s*\)\s*\)", b64s, re.I))
    for pat, fn, fl in rules:
        t2 = re.sub(pat, fn, t, flags=fl)
        if t2 != t:
            return t2
    return t


def _ps_simplify(src, budget=0.4):
    import time
    end = time.time() + budget
    t = _ps_tokens(src)
    for _ in range(400):
        if time.time() > end:
            break
        t2 = _ps_fold_once(t)
        if t2 == t:
            break
        t = t2
    return t


_PS_ENC_RE = re.compile(r"""(?:^|\s)[-/](e[a-z]*)\s+['"]?([A-Za-z0-9+/]{16,}={0,2})""", re.I)
_PS_B64ARG_RE = re.compile(r"frombase64string\(\s*'((?:[^']|'')*)'\s*\)", re.I)


def _ps_inflate(b):
    """Raw deflate that must reach its end-of-stream block (a truncated stream is no payload)."""
    import zlib
    d = zlib.decompressobj(-15)
    out = d.decompress(b, 1 << 22)
    if not d.eof:
        raise ValueError("truncated deflate")
    return out


def _ps_payloads(t):
    """Decoded payload texts in a folded PowerShell text: -EncodedCommand (UTF-16LE) and FromBase64String layers
    (Deflate/Gzip when the statement names the stream, else UTF-16LE / UTF-8 text)."""
    import gzip
    import zlib
    out = []
    for m in _PS_ENC_RE.finditer(t):
        if "encodedcommand".startswith(m.group(1).lower()) or m.group(1).lower() == "ec":
            try:
                out.append(base64.b64decode(m.group(2)).decode("utf-16-le"))
            except (ValueError, UnicodeDecodeError):
                pass
    for m in _PS_B64ARG_RE.finditer(t):
        try:
            raw = base64.b64decode(re.sub(r"\s", "", m.group(1).replace("''", "'")))
        except ValueError:
            continue
        stmt = t[max(0, m.start() - 400):m.end() + 400].lower()
        cands = []
        if "deflatestream" in stmt:
            cands.append(_ps_inflate)
        if "gzipstream" in stmt or raw[:2] == b"\x1f\x8b":
            cands.append(lambda b: gzip.decompress(b))
        if "zlibstream" in stmt or raw[:1] == b"\x78":
            cands.append(lambda b: zlib.decompress(b))
        cands.append(lambda b: b)
        for f in cands:
            try:
                b = f(raw)
            except (zlib.error, OSError, EOFError, ValueError):
                continue
            u = _utf16(b)
            try:
                out.append((u or b).decode("utf-8").lstrip("\ufeff"))
                break
            except UnicodeDecodeError:
                continue
    return out


def _ps_codecs(src, depth=0, budget=0.6):
    """find_codecs entries read from the folded PowerShell text and its decoded payload layers (up to 4 deep)."""
    import time
    try:
        if not src or len(src) > (1 << 18) or not _PS_HINT.search(src):
            return []
        end, frontier, seen = time.time() + budget, [src], {src}
        for level in range(4):
            nxt = []
            for text in frontier:
                if time.time() > end:
                    return []
                folded = _ps_simplify(text, budget=min(0.3, max(0.05, end - time.time())))
                for cand in ([folded] if level == 0 else [text, folded]):
                    if looks_like_plan(cand.strip().encode("utf-8", "ignore")):
                        return [{"id": "ps-layer", "rep": "powershell", "transform": "identity", "key": "",
                                 "material": None, "plain": cand.strip().lstrip("\ufeff")}]
                    for c in (_find_codecs_text(cand) if cand != src else []):
                        if c.get("plain"):
                            return [dict(c, id=f"{c['id']}@ps{level}")]
                for p in _ps_payloads(folded):
                    if p and p not in seen and len(seen) < 64:
                        seen.add(p)
                        nxt.append(p)
            frontier = nxt
            if not frontier:
                break
    except Exception:  # noqa: BLE001 - unknown -> nothing, never an exception
        return []
    return []


# ------------------------------------------------------------------------------------------------ batch DOSfuscation
# Target batch-substring-emulation: a .bat/.cmd that spells its plan through cmd's own expansion (Invoke-DOSfuscation
# style) instead of a HUNTRESS-MATERIAL line -- %VAR:~n,m% / !VAR:~n,m! substrings (negative n/m), %VAR:old=new% and
# %VAR:*old=new% substitution, ^ carets, setlocal EnableDelayedExpansion / cmd /V:ON !VAR!, `call set` second percent
# pass, `for /l` and `for %%G in (..)` loops. A straight-line pass (goto/exit/if are not followed: an `if` runs its
# command) records every set value and echo line; the first plan-shaped one (or one peel_plan reads) is the plain.
# Bounded by a step count; never raises. The per-day solver's batchplan.py stays the control-flow-exact reading.
_BAT_HINT = re.compile(r"(?im)^[\s@(]*(?:s\^?e\^?t|c\^?a\^?l\^?l|f\^?o\^?r)\b[^\n]*[%!]|^[\s@]*cmd(?:\.exe)?\b[^\n]*/v")
_BAT_LABEL = re.compile(r"^\s*:[^:]")


class _Bat:
    def __init__(self, delayed, max_steps=20000):
        self.env, self.delayed, self.steps, self.max_steps = {}, delayed, 0, max_steps
        self.seen = []                                   # set values and echo lines, in execution order

    def var(self, body):
        m = re.match(r"^([^:]+):~\s*(-?\d+)\s*(?:,\s*(-?\d+))?\s*$", body)
        if m:
            v = self.env.get(m.group(1).lower())
            if v is None:
                return None
            a = int(m.group(2))
            a = max(len(v) + a, 0) if a < 0 else min(a, len(v))
            if m.group(3) is None:
                return v[a:]
            b = int(m.group(3))
            return v[a:a + b] if b >= 0 else v[a:max(len(v) + b, a)]
        m = re.match(r"^([^:]+):(\*?)([^=]*)=(.*)$", body, re.S)
        if m:
            v = self.env.get(m.group(1).lower())
            if v is None or not m.group(3):
                return v
            if m.group(2):
                i = v.lower().find(m.group(3).lower())
                return v if i < 0 else m.group(4) + v[i + len(m.group(3)):]
            return re.sub(re.escape(m.group(3)), lambda _: m.group(4), v, flags=re.I)
        return self.env.get(body.lower())

    def percent(self, s, batch_file=True):
        out, i, n = [], 0, len(s)
        while i < n:
            c = s[i]
            if c != "%":
                out.append(c); i += 1; continue
            if batch_file and s.startswith("%%", i):
                out.append("%"); i += 2; continue
            m = re.match(r"%(?:~[a-zA-Z]*)?[0-9*]", s[i:]) if batch_file else None
            if m:                                        # %1 / %~dp0 / %*: no arguments
                i += len(m.group(0)); continue
            j = s.find("%", i + 1)
            if j < 0:
                if not batch_file:
                    out.append(c)
                i += 1; continue
            v = self.var(s[i + 1:j]) if j > i + 1 else None
            if v is None:
                if batch_file:
                    i = j + 1
                else:
                    out.append(s[i:j]); i = j
                continue
            out.append(v); i = j + 1
        return "".join(out)

    def delayed_exp(self, s):
        if not self.delayed or "!" not in s:
            return s
        out, i, n = [], 0, len(s)
        while i < n:
            c = s[i]
            if c == "^":                                 # a line holding '!' loses one more level of carets
                if i + 1 < n:
                    out.append(s[i + 1])
                i += 2; continue
            if c != "!":
                out.append(c); i += 1; continue
            j = s.find("!", i + 1)
            if j < 0:
                i += 1; continue
            out.append(self.var(s[i + 1:j]) or "")
            i = j + 1
        return "".join(out)

    @staticmethod
    def split_ops(s):
        """Unquoted, unescaped & && || | -> [(cmd, op_before)]; carets outside quotes consumed (escaped char kept)."""
        parts, cur, op, q, i, n, depth = [], [], None, False, 0, len(s), 0
        while i < n:
            c = s[i]
            if c == '"':
                q = not q; cur.append(c); i += 1; continue
            if not q and c == "^":
                if i + 1 < n:
                    cur.append(s[i + 1])
                i += 2; continue
            if not q:
                depth += (c == "(") - (c == ")")
            if not q and depth <= 0 and c in "&|":
                dbl = i + 1 < n and s[i + 1] == c
                parts.append(("".join(cur), op))
                op, cur = c * 2 if dbl else c, []
                i += 2 if dbl else 1; continue
            cur.append(c); i += 1
        parts.append(("".join(cur), op))
        return parts

    def line(self, s, batch_file=True, depth=0):
        s = self.percent(s, batch_file)
        for cmd, op in self.split_ops(s):
            if op != "|":                                # right side of a pipe: output only
                self.cmd(cmd.strip(), batch_file, depth)

    def _set(self, rest):
        rest = rest.strip()
        if re.match(r"(?i)/p\b", rest):
            return
        if re.match(r"(?i)/a\b", rest):                  # only `set /a n=<int>` (loop bounds / offsets)
            m = re.match(r'(?i)/a\s*"?\s*([^\s="]+)\s*=\s*(-?\d+)\s*"?\s*$', rest)
            if m:
                self.env[m.group(1).lower()] = str(int(m.group(2)))
            return
        if rest.startswith('"'):
            end = rest.rfind('"')
            rest = rest[1:end] if end > 0 else rest[1:]
        if "=" not in rest:
            return
        name, val = rest.split("=", 1)
        name = name.strip().lower()
        if not name:
            return
        if val:
            self.env[name] = val
            self.seen.append(val)
        else:
            self.env.pop(name, None)

    def cmd(self, c, batch_file, depth):
        self.steps += 1
        if not c or depth > 6 or self.steps > self.max_steps:
            return
        while c.startswith("(") and c.endswith(")"):
            c = c[1:-1].strip()
        c = c.lstrip("@( ").rstrip(") ") if c.count("(") != c.count(")") else c.lstrip("@ ")
        if not c:
            return
        low = c.lower()
        word = re.match(r"[^\s(.:;,/\\\[\]+=]*", low).group(0)
        if word == "rem" or low.startswith("::"):
            return
        if word == "setlocal":
            if re.search(r"enabledelayedexpansion", low):
                self.delayed = True
            return
        if word == "echo":
            body = c[5:] if len(c) > 4 else ""
            if low.strip() not in ("echo off", "echo on", "echo"):
                self.seen.append(self.delayed_exp(body).rstrip())
            return
        if word == "for":                                # its body expands !vars! per iteration
            return self._for(c, batch_file, depth)
        c = self.delayed_exp(c)
        if word == "set":
            self._set(c[3:])
        elif word == "call":
            rest = c[4:].strip()
            if rest and not rest.startswith(":"):
                self.line(rest, batch_file, depth + 1)
        elif word == "if":
            m = re.match(r'(?i)if\s+(?:/i\s+)?(?:not\s+)?(?:(?:defined|exist|errorlevel|cmdextversion)\s+\S+|'
                         r'"[^"]*"\s*(?:==|equ|neq|lss|leq|gtr|geq)\s*"[^"]*"|\S+?\s*==\s*\S+)\s*(.*)$', c, re.S)
            if m:
                body = re.split(r"\)\s*else\s*\(?", m.group(1), maxsplit=1, flags=re.I)[0]
                self.cmd(body.strip(), batch_file, depth + 1)
        elif word in ("cmd", "cmd.exe") or re.match(r"[^\s]*\\cmd(?:\.exe)?$", word):
            m = re.search(r'(?i)/[ck]\s+(.*)$', c, re.S)
            if m:
                inner = m.group(1).strip()
                if inner.startswith('"') and inner.endswith('"'):
                    inner = inner[1:-1]
                child = _Bat(self.delayed or bool(re.search(r"(?i)/v(?::?on)?\b", c[:m.start()])),
                             self.max_steps - self.steps)
                child.env = dict(self.env)
                child.line(inner, batch_file=False, depth=depth + 1)
                self.steps += child.steps
                self.seen.extend(child.seen)

    def _for(self, c, batch_file, depth):
        m = re.match(r'(?i)for\s+(/l\s+|/f\s+(?:"[^"]*"\s+)?)?%%?([A-Za-z])\s+in\s*\((.*?)\)\s*do\s+(.*)$', c, re.S)
        if not m:
            return
        flag, letter, lst, body = (m.group(1) or "").strip().lower(), m.group(2), m.group(3), m.group(4)
        if flag.startswith("/l"):
            nums = [int(x) for x in re.findall(r"-?\d+", lst)][:3]
            if len(nums) != 3 or nums[1] == 0:
                return
            a, st, e = nums
            items = [str(x) for x in range(a, e + (1 if st > 0 else -1), st)][:8192]
        elif flag.startswith("/f"):
            lm = re.match(r'\s*"(.*)"\s*$', lst, re.S)        # only a literal string, first token
            if not lm:
                return
            items = (lm.group(1).split() or [""])[:1]
        else:
            items = [t for t in re.split(r'[\s,;=]+', lst) if t][:4096]
        pat = re.compile(r"%~?" + re.escape(letter))
        for it in items:
            if self.steps > self.max_steps:
                return
            self.cmd(pat.sub(lambda _: it, body).strip(), batch_file, depth + 1)


def _bat_run(src, max_steps=20000):
    """Straight-line emulation of a batch source -> the _Bat (its `seen` set values / echo lines)."""
    text = (src or "").replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"(?<!\^)\^\n", "", text)              # caret line continuation
    b = _Bat(False, max_steps)
    for ln in text.split("\n")[:5000]:
        if b.steps > max_steps:
            break
        s = ln.strip()
        if not s or s.startswith("::") or _BAT_LABEL.match(s):
            continue
        b.line(s)
    return b


def _bat_codecs(src, budget=0.4):
    """find_codecs fallback for DOSfuscated batch: the plan a set/echo spells once cmd's expansions are applied."""
    import time
    try:
        if not src or not _BAT_HINT.search(src):
            return []
        b = _bat_run(src)
        seen, end = [], time.time() + budget
        for v in reversed(b.seen):                       # later values are the assembled ones
            v = v.strip()
            if v and v not in seen:
                seen.append(v)
        for v in seen:
            if looks_like_plan(v.encode("utf-8", "ignore")):
                return [{"id": "batch_emu", "rep": "batch_expansion", "transform": "identity", "key": "",
                         "material": v, "plain": v}]
        for v in seen[:24]:
            tok = re.fullmatch(r"[A-Za-z0-9+/=_\-:%.]{24,}", v)
            if tok and time.time() < end:
                plain = peel_plan(v, budget=min(0.2, max(0.02, end - time.time())))
                if plain:
                    return [{"id": "batch_emu", "rep": "batch_expansion", "transform": "identity", "key": "",
                             "material": v, "plain": plain}]
    except Exception:  # noqa: BLE001 - unknown -> nothing, never an exception
        return []
    return []


# ------------------------------------------------------------------------------------------------ container carriers
# Target container-carrier-extract: the script rides inside a container (OOXML zip -> vbaProject.bin, OLE .doc/.xls,
# LNK StringData, OneNote FileDataStoreObject, gzip, pyc constants, UTF-16LE .reg/.ps1). find_codecs() falls back to
# this only when the text itself yields no plan: from raw bytes (find_codecs(bytes)), latin-1 text, or -- when the
# caller decoded utf-8 'ignore'/'replace' -- whatever survived (UTF-16LE runs keep their NULs). Each member text goes
# through the text readings, then a bounded peel of its long material-charset tokens. Pure python, bounded, never raises.
# CHM content (LZX-compressed section) is NOT decompressed: only its uncompressed bytes/UTF-16 runs are scanned.
_ONE_FDSO = bytes.fromhex("e716e3bd65261145a4c48d4d0b7a9eac")      # {BDE316E7-2665-4511-A4C4-8D4D0B7A9EAC}
_MAGICS = (b"PK\x03\x04", b"\xd0\xcf\x11\xe0", b"\x1f\x8b", b"L\x00\x00\x00\x01\x14\x02\x00",
           bytes.fromhex("e4525c7b8cd8a74daeb15378d02996d3"), b"ITSF",
           b"\xd4\xc3\xb2\xa1", b"\xa1\xb2\xc3\xd4", b"\x4d\x3c\xb2\xa1", b"\xa1\xb2\x3c\x4d", b"\x0a\x0d\x0d\x0a",
           b"RPA-", b"RENPY RPC2", b"UnityFS\x00")
_U16_RUN = re.compile(rb"(?:[\t\n\r\x20-\x7e]\x00){12,}")
_U16_RUN_S = re.compile(r"(?:[\t\n\r\x20-\x7e]\x00){12,}")
_MAT_TOKEN = re.compile(r"[A-Za-z0-9+/=_\-:%.]{24,}")


def _ovba_decompress(b, i):
    """MS-OVBA CompressedContainer at b[i] (signature 0x01) -> bytes, or None if it is not one."""
    if i >= len(b) or b[i] != 1:
        return None
    out, i = bytearray(), i + 1
    while i + 2 <= len(b) and len(out) < (1 << 22):
        hdr = b[i] | b[i + 1] << 8
        if (hdr >> 12) & 7 != 3:
            return bytes(out) if out else None
        chunk, i = b[i + 2:i + (hdr & 0xFFF) + 3], i + (hdr & 0xFFF) + 3
        if not hdr >> 15:
            out += chunk[:4096]
            continue
        start, j = len(out), 0
        while j < len(chunk):
            fb, j = chunk[j], j + 1
            for bit in range(8):
                if j >= len(chunk):
                    break
                if not fb >> bit & 1:
                    out.append(chunk[j])
                    j += 1
                    continue
                if j + 1 >= len(chunk):
                    return None
                tok, j = chunk[j] | chunk[j + 1] << 8, j + 2
                bc = max((len(out) - start - 1).bit_length(), 4)
                ln, off = (tok & (0xFFFF >> bc)) + 3, (tok >> (16 - bc)) + 1
                if off > len(out) - start:
                    return None
                for _ in range(ln):
                    out.append(out[-off])
    return bytes(out) if out else None


def _vba_sources(s):
    """VBA module source(s) in an OLE module stream: the compressed container after the p-code (validated by
    `Attribute VB_`), tried from the last candidate signature backwards."""
    cands = [m.start() for m in re.finditer(rb"\x01[\x00-\xff][\xb0-\xbf]", s)][-48:]
    for i in reversed(cands):
        src = _ovba_decompress(s, i)
        if src and b"Attribute VB_" in src[:400]:
            return src
    return None


def _vba_dir_offsets(d):
    """{module stream name (lower): MODULEOFFSET} from a VBA `dir` stream (MS-OVBA 2.3.4.2 records), or {}."""
    d, out, name, i = _ovba_decompress(d, 0) or b"", {}, None, 0
    while i + 6 <= len(d) and len(out) < 4096:
        rid, size = int.from_bytes(d[i:i + 2], "little"), int.from_bytes(d[i + 2:i + 6], "little")
        size = 6 if rid == 0x0009 else size                     # PROJECTVERSION: Size says 4, 6 bytes follow
        body, i = d[i + 6:i + 6 + size], i + 6 + size
        if rid == 0x001A:                                       # MODULESTREAMNAME (MBCS; 0x0032 unicode follows)
            name = body.decode("latin-1").lower()
        elif rid == 0x0031 and name is not None and size == 4:  # MODULEOFFSET of the source in that stream
            out[name] = int.from_bytes(body, "little")
    return out


# Target nsis-compiled-installer-extract: the BUILT NSIS setup EXE (D22 OutFile `huntress-<8hex>.exe`). The PE overlay
# holds firstheader (flags, EF BE AD DE, `NullsoftInst`, header_size, archive_size) at a 512-aligned offset, then
# either non-solid blocks (u32 len, high bit = compressed) or one solid stream (u32 header_size + header + raw blocks).
# Compressors: raw deflate, LZMA (props 5D + dict u32, optional x86-filter flag byte); NSIS's modified bzip2 -> {}. The header
# holds 8 block headers (pages, sections, entries, strings, langtables, ...); the string table is UTF-16LE for
# `Unicode True`, with NSIS 3 codes 1-4 (LANG/SHELL/VAR/SKIP) + CODE_SHORT, Park 0xE000-3, NSIS 2 ANSI 252-255.
# 7-Zip 26 lists/extracts the files but no longer emits `[NSIS].nsi`. Inno Setup is only detected (use innoextract).
_NSIS_SIG = b"\xef\xbe\xad\xdeNullsoftInst"
_NSIS_VARS = {20: "$CMDLINE", 21: "$INSTDIR", 22: "$OUTDIR", 23: "$EXEDIR", 24: "$LANGUAGE"}
_INNO_SIG = re.compile(rb"Inno Setup Setup Data \((\d+\.\d+\.\d+[^)]{0,16})\)")


def _nsis_inflate(c, cap):
    """Decompress one NSIS stream `c` (format sniffed: LZMA / raw deflate) -> bytes, "" when neither reads it. NSIS
    bzip2 is a modified stream (1-byte block signatures, no CRCs) that stdlib bz2 cannot read: not supported."""
    import lzma
    import zlib
    tries = []
    for k in (0, 1):                                          # LZMA props, optionally after the BCJ-x86 flag byte
        if len(c) > 5 + k and c[k] == 0x5D and (k == 0 or c[0] in (0, 1)):
            tries.append(("lzma", k))
    tries.append(("zlib", 0))
    for kind, k in tries:
        try:
            if kind == "lzma":
                d = lzma.LZMADecompressor(lzma.FORMAT_ALONE).decompress(c[k:k + 5] + b"\xff" * 8 + c[k + 5:], cap)
            else:
                d = zlib.decompressobj(-15).decompress(c, cap)
            if d:
                return d
        except (OSError, ValueError, EOFError, lzma.LZMAError, zlib.error):
            continue
    return b""


def _nsis_string(tab, i, uni, ver):
    """String at char index `i` of an NSIS string table, escape codes rendered as `$VAR` / `$(LANG_n)` / `$SHELL_n`."""
    unit, out = (2 if uni else 1), []
    p = i * unit
    while p + unit <= len(tab) and len(out) < 8192:
        c = int.from_bytes(tab[p:p + unit], "little")
        p += unit
        if c == 0:
            break
        code = (c if ver == 3 and 1 <= c <= 4 else c - 0xE000 + 1 if ver == 1 and 0xE000 <= c <= 0xE003 else
                256 - c if ver == 2 and c >= 252 else 0)
        if not code:
            out.append(chr(c))
            continue
        code = {1: 4, 2: 3, 3: 2, 4: 1}[code] if ver == 1 else code   # Park: SKIP E000 VAR E001 SHELL E002 LANG E003
        if code == 4:                                         # NS_SKIP: next char is literal
            if p + unit <= len(tab):
                out.append(chr(int.from_bytes(tab[p:p + unit], "little")))
                p += unit
            continue
        raw = tab[p:p + 2]
        p += unit if uni else 2
        if len(raw) < 2:
            break
        n = (raw[0] & 0x7F) | (raw[1] & 0x7F) << 7
        if code == 3:
            out.append(f"${n}" if n < 10 else f"$R{n - 10}" if n < 20 else _NSIS_VARS.get(n, f"$_{n}_"))
        elif code == 2:
            out.append(f"$SHELL_{raw[0]:02x}{raw[1]:02x}")
        else:
            out.append(f"$(LSTR_{n})")
    return "".join(out)


def nsis_extract(data, budget=0.6):
    """Strings and files of a compiled NSIS installer (PE with the NSIS overlay, or the bare overlay) without running
    it: {"format": "nsis", "unicode", "solid", "strings": [..], "files": [(name, bytes)], "offset"}; an Inno Setup
    EXE -> {"format": "inno", "version", "unsupported": "use innoextract"}; anything else -> {}. Never raises."""
    import struct
    import time
    end, cap = time.time() + budget, 32 << 20
    try:
        data = bytes(data or b"")
        if b"NullsoftInst" not in data:
            m = _INNO_SIG.search(data[:64 << 20])
            return {"format": "inno", "version": m.group(1).decode("latin-1"), "unsupported": "use innoextract"} \
                if m else {}
        offs = [m.start() - 4 for m in re.finditer(re.escape(_NSIS_SIG), data) if m.start() >= 4][:16]
        for off in sorted(offs, key=lambda o: o % 512 != 0):
            if time.time() > end:
                break
            hsize, total = struct.unpack_from("<II", data, off + 20) if off + 28 <= len(data) else (0, 0)
            if not 0 < hsize < cap:
                continue
            arc = data[off + 28:off + max(total, 28) if total > 28 else len(data)]
            head, blocks, solid = None, b"", False
            n0 = int.from_bytes(arc[:4], "little")
            if n0 & 0x80000000 and 0 < (n0 & 0x7FFFFFFF) <= len(arc) - 4:
                h = _nsis_inflate(arc[4:4 + (n0 & 0x7FFFFFFF)], hsize + 1)
                if len(h) == hsize:
                    head, blocks = h, arc[4 + (n0 & 0x7FFFFFFF):]
            elif 0 < n0 == hsize <= len(arc) - 4:                # stored header
                head, blocks = arc[4:4 + n0], arc[4 + n0:]
            if head is None:                                    # solid: one stream, header_size first
                s = _nsis_inflate(arc, cap)
                if len(s) >= 4 + hsize and int.from_bytes(s[:4], "little") == hsize:
                    head, blocks, solid = s[4:4 + hsize], s[4 + hsize:], True
            if head is None or len(head) < 68:
                continue
            bh = [struct.unpack_from("<II", head, 4 + 8 * k) for k in range(8)]
            s0 = bh[3][0]
            s1 = min([o for o, _ in bh if o > s0] + [len(head)])
            tab = head[s0:s1] if 0 < s0 < len(head) else b""
            if not tab:
                continue
            odd = tab[1::2][:4096]
            uni = len(tab) >= 2 and tab[:2] == b"\0\0" and odd.count(0) > len(odd) * 0.6
            unit = 2 if uni else 1
            chars = [int.from_bytes(tab[p:p + unit], "little") for p in range(0, min(len(tab), 1 << 20), unit)]
            ver = 3 if any(1 <= c <= 4 for c in chars) else 1 if uni and any(0xE000 <= c <= 0xE003 for c in chars) \
                else 2 if not uni and any(c >= 252 for c in chars) else 3
            starts, i = [], 1 if chars[:1] == [0] else 0
            while i < len(chars) and len(starts) < 20000:
                starts.append(i)
                while i < len(chars) and chars[i]:
                    if (ver == 3 and 1 <= chars[i] <= 3) or (ver == 1 and 0xE001 <= chars[i] <= 0xE003) or \
                            (ver == 2 and 253 <= chars[i] <= 255):
                        i += 1 if uni else 2                    # skip the coded index (it may hold no NUL)
                    elif (ver == 3 and chars[i] == 4) or (ver == 1 and chars[i] == 0xE000) or \
                            (ver == 2 and chars[i] == 252):
                        i += 1
                    i += 1
                i += 1
            strs = {k: _nsis_string(tab, k, uni, ver) for k in starts}
            files, seen = [], {}
            p = 0
            while p + 4 <= len(blocks) and len(files) < 256 and time.time() < end:
                n = int.from_bytes(blocks[p:p + 4], "little")
                ln = n & 0x7FFFFFFF
                if ln > len(blocks) - p - 4:
                    break
                body = blocks[p + 4:p + 4 + ln]
                body = _nsis_inflate(body, 8 << 20) if n & 0x80000000 and not solid else body
                seen[p] = len(files)
                files.append([f"block@{p}", body])
                p += 4 + ln
                if not solid and p + 4 >= len(blocks):             # trailing CRC32
                    break
            e0, en = bh[2]
            ents = [struct.unpack_from("<i4xii", head, e0 + 28 * k) for k in range(min(en, 50000))
                    if e0 + 28 * k + 28 <= len(head)]
            for ops in ((20,), (18, 19, 21, 22)):                  # EW_EXTRACTFILE (NSIS 3), then version shifts
                for w, nm, dof in ents:
                    if w in ops and dof in seen and strs.get(nm) and files[seen[dof]][0].startswith("block@"):
                        files[seen[dof]][0] = strs[nm].rsplit("\\", 1)[-1]
            return {"format": "nsis", "unicode": uni, "solid": solid, "offset": off,
                    "strings": [s for s in strs.values() if s], "files": [tuple(f) for f in files]}
    except Exception:  # noqa: BLE001 - truncated / impostor installer: no answer
        return {}
    return {}


# ------------------------------------------------------------------------------------------- Godot resources / packs
# Target godot-resource-pck-carrier (D23 GDScript moved into a Godot resource): text resources `.tscn`/`.tres`
# (`[gd_scene ..]` / `[gd_resource ..]`, `[sub_resource type="GDScript" id=..]` + `script/source = "<escaped>"`: Godot 4
# writes c_escape_multiline -- `\\` `\"` only, newlines literal -- Godot 3 / hand-made ones use \n \t \" \uXXXX),
# `.pck` packs (GDPC; v1 Godot 3: u32 ver, u32 major/minor/patch, 16 x u32 reserved, u32 count, {u32 padded path len,
# path, u64 offset, u64 size, md5[16]}; v2 Godot 4.0-4.3: + u32 pack_flags, u64 file_base, + u32 per-file flags; v3
# Godot 4.4+: + u64 dir_offset; encrypted directory / files skipped; embedded = trailing u64 size + `GDPC`), `.gdc`
# tokenized scripts (GDSC; Godot 3: identifiers XOR 0xb6 + encode_variant constants; Godot 4.3+ v100+: zstd body,
# UTF-32 identifiers XOR 0xb6) and RSCC-compressed binary resources. godot_members(data) -> [(path, bytes)] never
# runs anything; _godot_codecs() runs the normal readings on each text member. Bounded, never raises.
_GD_CUE = re.compile(r"\A(?:GDPC|GDSC|RSCC|RSRC)|^\[gd_(?:scene|resource)\b|^[ \t]*script/source[ \t]*=[ \t]*\"", re.M)
_GD_SRC = re.compile(r"""^[ \t]*script/source[ \t]*=[ \t]*\"""", re.M)
_GD_ESC = {"n": "\n", "t": "\t", "r": "\r", "b": "\b", "f": "\f", "\\": "\\", '"': '"', "'": "'"}
_GD_TEXT_EXT = (".gd", ".tscn", ".tres", ".cfg", ".json", ".godot", ".txt", ".csv", ".import", ".remap", ".cs",
                ".gdshader", ".md", ".xml", ".ini", ".lua", ".py", ".js", ".ps1", ".sh", ".bat", ".vbs")
_GD_U32RUN = re.compile(rb"(?:[\t\n\r\x20-\x7e]\x00\x00\x00){2,}")


def _gd_bytes(data):
    if isinstance(data, (bytes, bytearray)):
        return bytes(data)
    try:
        return data.encode("latin-1")
    except UnicodeEncodeError:
        return data.encode("utf-8", "surrogateescape")


def _gd_string(s, i):
    """Godot VariantParser string literal body starting after the opening quote at s[i]: (text, end) or None."""
    out, n = [], len(s)
    while i < n:
        c = s[i]
        if c == '"':
            return "".join(out), i + 1
        if c == "\\" and i + 1 < n:
            e = s[i + 1]
            if e in "uU":
                w = 4 if e == "u" else 6
                h = s[i + 2:i + 2 + w]
                if len(h) == w and all(x in "0123456789abcdefABCDEF" for x in h):
                    try:
                        out.append(chr(int(h, 16)))
                    except ValueError:
                        pass
                    i += 2 + w
                    continue
            out.append(_GD_ESC.get(e, e))
            i += 2
            continue
        out.append(c)
        i += 1
    return None


def _gd_text_sources(text, limit=32):
    """Unescaped `script/source = ".."` bodies of a Godot text resource."""
    out = []
    for m in _GD_SRC.finditer(text):
        r = _gd_string(text, m.end())
        if r and r[0].strip():
            out.append(r[0])
            if len(out) >= limit:
                break
    return out


def _gd_pck(b, start=0, end=None):
    """[(path, bytes)] of a GDPC pack at b[start:end] (offsets validated, md5 picks the base when ambiguous)."""
    import hashlib
    import struct
    end = len(b) if end is None else end
    u32 = lambda o: struct.unpack_from("<I", b, o)[0]  # noqa: E731
    u64 = lambda o: struct.unpack_from("<Q", b, o)[0]  # noqa: E731
    if b[start:start + 4] != b"GDPC":
        return []
    ver, out = u32(start + 4), []
    if ver in (0, 1):
        flags, bases, pos = 0, (start, 0), start + 20 + 64
    elif ver in (2, 3):
        flags, fb = u32(start + 20), u64(start + 24)
        if flags & 1:                                         # encrypted directory: needs the export key
            return []
        bases = (start + fb, fb)
        pos = start + 32
        if ver == 3:
            dofs = u64(pos)
            pos = start + dofs if start + dofs < end else dofs
        else:
            pos += 64
    else:
        return []
    count = u32(pos)
    pos += 4
    for _ in range(min(count, 4096)):
        n = u32(pos)
        if n > 4096:
            break
        path = b[pos + 4:pos + 4 + n].rstrip(b"\0").decode("utf-8", "replace")
        pos += 4 + n
        off, size = struct.unpack_from("<QQ", b, pos)
        md5 = b[pos + 16:pos + 32]
        pos += 32
        fflags = 0
        if ver >= 2:
            fflags = u32(pos)
            pos += 4
        if fflags & 1 or size > (8 << 20):
            continue
        cands = [base + off for base in bases if 0 <= base + off and base + off + size <= end]
        if not cands:
            continue
        good = next((a for a in cands if hashlib.md5(b[a:a + size]).digest() == md5), cands[0])
        out.append((path, b[good:good + size]))
    return out


def _gd_gdc_text(b):
    """Identifiers + string constants of a tokenized GDScript (.gdc) as one text (one item per line)."""
    import struct
    ver = struct.unpack_from("<I", b, 4)[0]
    idents, strs = [], []
    if ver >= 100:                                            # Godot 4.3+ binary tokens: optional zstd body
        dsize = struct.unpack_from("<I", b, 8)[0]
        body = b[12:]
        if dsize:
            import zstandard
            body = zstandard.ZstdDecompressor().decompress(body, max_output_size=min(dsize, 16 << 20))
        x = bytes(c ^ 0xB6 for c in body[:1 << 22])
        idents = [r.decode("utf-32-le", "ignore") for r in _GD_U32RUN.findall(x)]
    else:                                                     # Godot 3: counts, XOR'd identifiers, variants
        ni, nc = struct.unpack_from("<II", b, 8)
        body, pos = b, 24
        for _ in range(min(ni, 1 << 16)):
            n = struct.unpack_from("<I", b, pos)[0]
            idents.append(bytes(c ^ 0xB6 for c in b[pos + 4:pos + 4 + n]).rstrip(b"\0").decode("utf-8", "ignore"))
            pos += 4 + n
        for _ in range(min(nc, 1 << 16)):
            t = struct.unpack_from("<I", b, pos)[0]
            ty, wide = t & 0xFF, bool(t & (1 << 16))
            if ty == 0:
                pos += 4
            elif ty in (1, 2, 3):
                pos += 4 + (8 if wide and ty != 1 else 4)
            elif ty == 4:
                n = struct.unpack_from("<I", b, pos + 4)[0]
                strs.append(b[pos + 8:pos + 8 + n].decode("utf-8", "ignore"))
                pos += 8 + n + (-n % 4)
            else:
                break
    if not strs:                                              # any layout: length-prefixed STRING variants
        i = body.find(b"\x04\x00\x00\x00")
        while 0 <= i and len(strs) < 512:
            n = int.from_bytes(body[i + 4:i + 8], "little")
            s = body[i + 8:i + 8 + n]
            if 2 <= n <= (1 << 20) and len(s) == n:
                try:
                    strs.append(s.decode("utf-8"))
                except UnicodeDecodeError:
                    pass
            i = body.find(b"\x04\x00\x00\x00", i + 1)
    return "\n".join([i for i in idents if i] + [f'"{s}"' for s in strs if s])


def _gd_rscc(b):
    """Decompressed body of a Godot FileAccessCompressed resource (RSCC; deflate / zstd / gzip blocks)."""
    import struct
    import zlib
    mode, bs, total = struct.unpack_from("<III", b, 4)
    if not 0 < bs <= (16 << 20) or total > (32 << 20):
        return b""
    nb = total // bs + 1
    sizes = struct.unpack_from("<%dI" % nb, b, 16)
    pos, out = 16 + 4 * nb, []
    for s in sizes:
        blk = b[pos:pos + s]
        pos += s
        if mode == 1:
            out.append(zlib.decompress(blk))
        elif mode == 3:
            out.append(zlib.decompressobj(31).decompress(blk))
        elif mode == 2:
            import zstandard
            out.append(zstandard.ZstdDecompressor().decompress(blk, max_output_size=bs))
        else:                                                 # FastLZ: no stdlib reader
            return b""
    return b"".join(out)[:total]


def _gd_walk(b, name, out, depth, end):
    if depth > 3 or time.time() > end or len(out) > 256:
        return
    try:
        if b[:4] == b"GDPC" or (b[-4:] == b"GDPC" and len(b) > 12):
            if b[:4] == b"GDPC":
                mem = _gd_pck(b)
            else:
                size = int.from_bytes(b[-12:-4], "little")
                st = len(b) - 12 - size
                mem = _gd_pck(b, st, len(b) - 12) if 0 <= st else []
            for p, fb in mem:
                out.append((f"{name}!{p}" if name else p, fb))
                _gd_walk(fb, f"{name}!{p}" if name else p, out, depth + 1, end)
        elif b[:4] == b"GDSC":
            out.append((name + "#gdc", _gd_gdc_text(b).encode("utf-8")))
        elif b[:4] == b"RSCC":
            d = _gd_rscc(b)
            if d:
                out.append((name + "#rscc", d))
        elif b"script/source" in b[:1 << 22] and b"\x00" not in b[:4096]:
            t = b.decode("utf-8", "replace")
            out.extend((f"{name}#script/source{k or ''}", s.encode("utf-8"))
                       for k, s in enumerate(_gd_text_sources(t)))
    except Exception:  # noqa: BLE001 - truncated / impostor: keep what was read
        return


def godot_members(data, budget=0.5):
    """[(path, bytes)] of a Godot carrier: .pck members (recursively expanded), unescaped `script/source` bodies of a
    .tscn/.tres, the identifier/string text of a .gdc, the body of an RSCC resource. [] when it is none of these."""
    out = []
    try:
        _gd_walk(_gd_bytes(data), "", out, 0, time.time() + budget)
    except Exception:  # noqa: BLE001
        return out
    return out


def _gd_is_text(path, b):
    p = path.lower()
    if p.endswith(("#gdc", "#rscc")) or "#script/source" in p or p.endswith(_GD_TEXT_EXT):
        return True
    return b[:4] not in (b"GDPC", b"GDSC", b"RSCC", b"RSRC") and b"\x00" not in b[:4096]


def _godot_codecs(src, raw=None, depth=0):
    """find_codecs readings of the text members of a Godot resource / pack / tokenized script."""
    try:
        end = time.time() + 0.6
        texts = [(p, fb.decode("utf-8", "ignore")) for p, fb in godot_members(raw if raw is not None else src)
                 if _gd_is_text(p, fb)]
        for p, t in texts:
            for c in (find_codecs(t, depth + 1) if depth < 1 else _find_codecs_text(t)):
                if c.get("plain"):
                    return [dict(c, id=f"{c.get('id')}@{p}")]
        seen = set()
        for p, t in texts:
            for tok in _MAT_TOKEN.findall(t)[:48]:
                if tok in seen or time.time() > end:
                    continue
                seen.add(tok)
                plain = peel_plan(tok, budget=min(0.15, max(0.02, end - time.time())))
                if plain:
                    return [{"id": f"godot@{p}", "rep": "carrier", "transform": "identity", "key": "",
                             "material": tok, "plain": plain}]
    except Exception:  # noqa: BLE001
        return []
    return []


# ------------------------------------------------------------------------------------------------ game archive carriers
# Target game-archive-carriers: a script riding in a game archive. Ren'Py `.rpa` (`RPA-3.0 <hex index offset> <hex
# key>\n`, RPA-3.2 `RPA-3.2 <off> <v> <key..>` (key = XOR of the fields after the offset), RPA-2.0 `RPA-2.0 <off>\n`
# no key): the index at <off> is zlib(pickle {path: [(offset ^ key, length ^ key[, prefix])]}), member data stored raw
# (prefix bytes first). The index is read by a RESTRICTED hand-rolled pickle reader (_pk_load: dict/list/tuple/str/
# bytes/int/None/bool + memo; the only GLOBALs are the protocol-2 bytes builders `_codecs.encode` / `__builtin__.bytes`,
# applied as data, never imported; any other opcode -> None). Ren'Py `.rpyc` (`RENPY RPC2`, slot table {u32 slot, u32
# start, u32 len} until slot 0, each slot zlib(pickle of the AST)): the AST is NEVER unpickled -- _pk_strings walks the
# opcodes and keeps the string literals only. `.love` = zip (the zip walk); UnityFS bundles (u32 BE version, unity
# version/revision, u64 size, u32 csize/usize/flags of the blocks info, LZ4/LZ4HC/none blocks) -> each node's bytes plus
# its long printable runs (TextAsset `m_Script` is u32 len + utf-8). game_members(data) -> [(path, text)].
_PK_FIXED = {0x80: 1, 0x95: 8, 0x47: 8, 0x4a: 4, 0x4b: 1, 0x4d: 2, 0x68: 1, 0x6a: 4, 0x71: 1, 0x72: 4, 0x82: 1,
             0x83: 2, 0x84: 4}
_PK_COUNTED = {0x54: (4, "s"), 0x55: (1, "s"), 0x58: (4, "u"), 0x42: (4, "b"), 0x43: (1, "b"), 0x8c: (1, "u"),
               0x8d: (8, "u"), 0x8e: (8, "b"), 0x96: (8, "b"), 0x8a: (1, "l"), 0x8b: (4, "l")}
_PK_LINE = {0x49: 1, 0x4c: 1, 0x46: 1, 0x53: 1, 0x56: 1, 0x50: 1, 0x67: 1, 0x70: 1, 0x63: 2, 0x69: 2}
_PK_NOARG = set(b"(.012NRabdelostu}])Q") | set(range(0x81, 0x82)) | set(range(0x85, 0x8a)) | set(range(0x8f, 0x95)) | \
    {0x97, 0x98}
_RPA_HDR = re.compile(rb"\ARPA-(2\.0|3\.0|3\.2) ([0-9A-Fa-f]{1,16})((?: [0-9A-Fa-f]{1,16})*)[ \t]*\r?\n")


class _PkG:
    __slots__ = ("mod", "name")

    def __init__(self, mod, name):
        self.mod, self.name = mod, name


def _pk_load(data, max_ops=400000):
    """Restricted pickle reader -> the object, or None (any opcode outside the data subset, or malformed)."""
    st, marks, memo, i, n, ops = [], [], {}, 0, len(data), 0

    def pop_mark():
        k = marks.pop()
        items = st[k:]
        del st[k:]
        return items
    try:
        while i < n and ops < max_ops:
            op, i, ops = data[i], i + 1, ops + 1
            if op == 0x80:
                i += 1
            elif op == 0x95:
                i += 8
            elif op == 0x7d:                                     # }
                st.append({})
            elif op == 0x5d:                                     # ]
                st.append([])
            elif op == 0x29:                                     # )
                st.append(())
            elif op == 0x28:                                     # (
                marks.append(len(st))
            elif op in (0x58, 0x8c, 0x8d, 0x54, 0x55, 0x42, 0x43, 0x8e):
                w, kind = _PK_COUNTED[op]
                ln = int.from_bytes(data[i:i + w], "little", signed=op == 0x54)
                if ln < 0 or i + w + ln > n:
                    return None
                raw, i = data[i + w:i + w + ln], i + w + ln
                st.append(raw.decode("utf-8", "surrogatepass") if kind == "u" else bytes(raw))
            elif op == 0x4a:                                     # BININT
                st.append(int.from_bytes(data[i:i + 4], "little", signed=True))
                i += 4
            elif op == 0x4b:
                st.append(data[i])
                i += 1
            elif op == 0x4d:
                st.append(int.from_bytes(data[i:i + 2], "little"))
                i += 2
            elif op in (0x8a, 0x8b):                             # LONG1 / LONG4
                w = 1 if op == 0x8a else 4
                ln = int.from_bytes(data[i:i + w], "little", signed=True)
                if ln < 0 or ln > 64:
                    return None
                st.append(int.from_bytes(data[i + w:i + w + ln], "little", signed=True))
                i += w + ln
            elif op == 0x74:                                     # t
                st.append(tuple(pop_mark()))
            elif op in (0x85, 0x86, 0x87):
                k = op - 0x84
                t = tuple(st[-k:])
                del st[-k:]
                st.append(t)
            elif op == 0x73:                                     # s
                v, k = st.pop(), st.pop()
                st[-1][k] = v
            elif op == 0x75:                                     # u
                items = pop_mark()
                d = st[-1]
                for j in range(0, len(items) - 1, 2):
                    d[items[j]] = items[j + 1]
            elif op == 0x61:                                     # a
                v = st.pop()
                st[-1].append(v)
            elif op == 0x65:                                     # e
                items = pop_mark()
                st[-1].extend(items)
            elif op == 0x94:
                memo[len(memo)] = st[-1]
            elif op in (0x71, 0x72):                             # BINPUT / LONG_BINPUT
                w = 1 if op == 0x71 else 4
                memo[int.from_bytes(data[i:i + w], "little")] = st[-1]
                i += w
            elif op in (0x68, 0x6a):                             # BINGET / LONG_BINGET
                w = 1 if op == 0x68 else 4
                st.append(memo[int.from_bytes(data[i:i + w], "little")])
                i += w
            elif op == 0x4e:
                st.append(None)
            elif op in (0x88, 0x89):
                st.append(op == 0x88)
            elif op == 0x63:                                     # GLOBAL: data builders only, never imported
                j = data.index(b"\n", i)
                k = data.index(b"\n", j + 1)
                st.append(_PkG(data[i:j].decode("ascii"), data[j + 1:k].decode("ascii")))
                i = k + 1
            elif op == 0x93:                                     # STACK_GLOBAL
                name, mod = st.pop(), st.pop()
                st.append(_PkG(mod, name))
            elif op == 0x52:                                     # REDUCE
                args, fn = st.pop(), st.pop()
                if not isinstance(fn, _PkG) or not isinstance(args, tuple):
                    return None
                if (fn.mod, fn.name) == ("_codecs", "encode") and args and isinstance(args[0], str):
                    st.append(args[0].encode("latin-1"))
                elif fn.name == "bytes" and fn.mod in ("__builtin__", "builtins") and not args:
                    st.append(b"")
                else:
                    return None
            elif op == 0x2e:                                     # STOP
                return None if isinstance(st[-1], _PkG) else st[-1]
            else:
                return None
    except Exception:  # noqa: BLE001 - malformed pickle
        return None
    return None


def _pk_strings(data, max_ops=400000, limit=4000):
    """String literals of a pickle stream, walking its opcodes without building or importing anything."""
    out, i, n, ops = [], 0, len(data), 0
    try:
        while i < n and ops < max_ops and len(out) < limit:
            op, i, ops = data[i], i + 1, ops + 1
            if op in _PK_COUNTED:
                w, kind = _PK_COUNTED[op]
                ln = int.from_bytes(data[i:i + w], "little", signed=w == 4 and kind in "sl")
                if ln < 0 or i + w + ln > n:
                    break
                raw, i = data[i + w:i + w + ln], i + w + ln
                if kind in "usb" and len(raw) >= 2:
                    try:
                        out.append(raw.decode("utf-8"))
                    except UnicodeDecodeError:
                        pass
            elif op in _PK_FIXED:
                i += _PK_FIXED[op]
            elif op in _PK_LINE:
                for _ in range(_PK_LINE[op]):
                    j = data.index(b"\n", i)
                    if op == 0x56:
                        out.append(data[i:j].decode("raw_unicode_escape"))
                    elif op == 0x53:
                        s = data[i:j].decode("latin-1").strip()
                        if s[:1] in "'\"" and s[-1:] == s[:1]:
                            out.append(s[1:-1].encode("latin-1").decode("unicode_escape"))
                    i = j + 1
            elif op == 0x2e:
                if i < n and data[i] == 0x80:                     # pickles back to back
                    continue
                break
            elif op not in _PK_NOARG:
                break
    except Exception:  # noqa: BLE001 - truncated stream: keep what was read
        return out
    return out


def _zinflate(b, cap=8 << 20):
    import zlib
    try:
        return zlib.decompressobj().decompress(b, cap)
    except Exception:  # noqa: BLE001
        return None


def rpa_members(b):
    """[(path, bytes)] of a Ren'Py RPA-2.0/3.0/3.2 archive, or [] (impostor / bad index)."""
    m = _RPA_HDR.match(b[:200])
    if not m:
        return []
    off, key = int(m.group(2), 16), 0
    fields = m.group(3).split()
    for f in (fields[1:] if m.group(1) == b"3.2" else fields) if m.group(1) != b"2.0" else ():
        key ^= int(f, 16)
    if not 0 < off < len(b):
        return []
    idx = _zinflate(b[off:])
    idx = _pk_load(idx) if idx else None
    out = []
    if not isinstance(idx, dict):
        return out
    for path, ents in list(idx.items())[:2000]:
        if not isinstance(path, (str, bytes)) or not isinstance(ents, (list, tuple)):
            continue
        path = path if isinstance(path, str) else path.decode("utf-8", "replace")
        data = b""
        for e in ents[:64]:
            if not isinstance(e, (list, tuple)) or len(e) < 2 or not all(isinstance(x, int) for x in e[:2]):
                break
            o, ln = e[0] ^ key, e[1] ^ key
            pre = e[2] if len(e) > 2 and isinstance(e[2], (bytes, str)) else b""
            pre = pre.encode("latin-1") if isinstance(pre, str) else pre
            if o < 0 or ln < len(pre) or o + ln - len(pre) > len(b) or ln > (8 << 20):
                break
            data += pre + b[o:o + ln - len(pre)]
        out.append((path, data))
    return out


def rpyc_strings(b):
    """String literals of a Ren'Py compiled script (RENPY RPC2 slots, or a legacy bare zlib pickle), or []."""
    import struct
    chunks = []
    if b[:10] == b"RENPY RPC2":
        p = 10
        while p + 12 <= len(b) and len(chunks) < 16:
            slot, start, ln = struct.unpack_from("<III", b, p)
            if slot == 0:
                break
            if start + ln <= len(b):
                chunks.append(b[start:start + ln])
            p += 12
    elif b[:1] == b"\x78":
        chunks.append(b)
    out = []
    for c in chunks:
        d = _zinflate(c)
        if d and d[:1] == b"\x80":
            out.extend(_pk_strings(d))
    return out


def unityfs_nodes(b, end=None):
    """[(node path, bytes)] of a UnityFS asset bundle (LZ4 / LZ4HC / uncompressed blocks), or []."""
    import struct
    end = end or time.time() + 0.5
    if b[:8] != b"UnityFS\x00":
        return []
    ver = struct.unpack_from(">I", b, 8)[0]
    p = 12
    for _ in range(2):
        p = b.index(b"\x00", p) + 1
    _size, csz, usz, flags = struct.unpack_from(">QIII", b, p)
    p += 20
    if ver >= 7:
        p = (p + 15) & ~15
    if flags & 0x80:
        info, data_at = b[len(b) - csz:], p
    else:
        info, data_at = b[p:p + csz], p + csz
    if flags & 0x200:
        data_at = (data_at + 15) & ~15

    def unpack(blob, kind, size):
        if kind == 0:
            return blob[:size]
        if kind in (2, 3):
            import lz4.block
            return lz4.block.decompress(blob, uncompressed_size=size)
        return None                                        # LZMA blocks: not read
    info = unpack(info, flags & 0x3F, usz)
    if not info:
        return []
    q = 16
    nb = struct.unpack_from(">I", info, q)[0]
    q += 4
    stream, at = bytearray(), data_at
    for _ in range(min(nb, 4096)):
        bu, bc, bf = struct.unpack_from(">IIH", info, q)
        q += 10
        if time.time() > end or bu > (16 << 20) or len(stream) > (32 << 20):
            return []
        blk = unpack(b[at:at + bc], bf & 0x3F, bu)
        if blk is None:
            return []
        stream += blk
        at += bc
    nn = struct.unpack_from(">I", info, q)[0]
    q += 4
    out = []
    for _ in range(min(nn, 1024)):
        o, sz, _nf = struct.unpack_from(">QQI", info, q)
        q += 20
        e = info.index(b"\x00", q)
        out.append((info[q:e].decode("utf-8", "replace"), bytes(stream[o:o + sz])))
        q = e + 1
    return out


_GAME_RUN = re.compile(rb"[\t\n\r\x20-\x7e\x80-\xff]{32,}")


def game_members(data, budget=0.5):
    """[(path, text)] of a game archive carrier: Ren'Py .rpa members, .rpyc string literals, UnityFS node runs
    (TextAsset strings). [] when it is none of these. Never raises, never unpickles a class."""
    out = []
    try:
        b = _gd_bytes(data)
        end = time.time() + budget
        if b[:4] == b"RPA-":
            for p, fb in rpa_members(b):
                if p.lower().endswith(".rpyc") or fb[:10] == b"RENPY RPC2":
                    out.append((p + "#strings", "\n".join(rpyc_strings(fb))))
                else:
                    out.append((p, fb.decode("utf-8", "ignore")))
        elif b[:10] == b"RENPY RPC2":
            out.append(("#strings", "\n".join(rpyc_strings(b))))
        elif b[:8] == b"UnityFS\x00":
            for p, fb in unityfs_nodes(b, end):
                out.extend((f"{p}@{m.start()}", m.group(0).decode("utf-8", "ignore"))
                           for m in _GAME_RUN.finditer(fb[:16 << 20]))
    except Exception:  # noqa: BLE001 - truncated / impostor: keep what was read
        return out
    return out


def _game_decode(material, transform=None, key=None):
    """decode() route for rep rpa / rpyc / renpy / unityfs / game_archive: the material is the archive itself (base64,
    hex or latin-1 bytes). The plan of its first plan-bearing member, or None."""
    try:
        m = (material or "").strip()
        for b in (b64(m), hex_bytes(m) if re.fullmatch(r"[0-9a-fA-F\s]+", m) else None, m.encode("latin-1", "ignore")):
            if b and (b[:4] in (b"RPA-", b"PK\x03\x04") or b[:10] == b"RENPY RPC2" or b[:8] == b"UnityFS\x00"):
                hits = _carrier_codecs(None, b)
                if hits:
                    return hits[0]["plain"]
    except Exception:  # noqa: BLE001
        return None
    return None


def _carrier_blobs(b, name="", depth=0, budget=None):
    """(member name, bytes) of every stream inside a container, recursively (zip / OLE+VBA / gzip / OneNote)."""
    import io
    import time
    import zlib
    budget = budget if budget is not None else time.time() + 0.8
    if depth > 3 or time.time() > budget or len(b) < 8:
        return
    yield name, b
    try:
        if b[:4] in (b"GDPC", b"GDSC", b"RSCC") or b[-4:] == b"GDPC":   # Godot pack / tokenized script / resource
            for p, fb in godot_members(b, budget=max(0.05, min(0.5, budget - time.time()))):
                yield f"{name}!{p}", fb
        elif b[:4] == b"RPA-" or b[:10] == b"RENPY RPC2" or b[:8] == b"UnityFS\x00":   # game archives
            for p, t in game_members(b, budget=max(0.05, min(0.5, budget - time.time()))):
                yield f"{name}!{p}", t.encode("utf-8")
        elif b[:4] == b"PK\x03\x04":
            import zipfile
            z = zipfile.ZipFile(io.BytesIO(b))
            for zi in z.infolist()[:200]:
                if zi.is_dir() or zi.flag_bits & 1 or zi.file_size > (8 << 20):
                    continue
                try:
                    yield from _carrier_blobs(z.read(zi), f"{name}/{zi.filename}", depth + 1, budget)
                except Exception:  # noqa: BLE001 - one bad member, keep walking
                    continue
        elif b[:4] == b"\xd0\xcf\x11\xe0":
            import olefile
            ole = olefile.OleFileIO(io.BytesIO(b))
            offs = {}                                           # VBA storages: dir-stream module offsets
            for ent in ole.listdir()[:300]:
                if ent[-1].lower() == "dir" and ole.get_size("/".join(ent)) < (1 << 20):
                    offs.update({"/".join(ent[:-1] + [k]).lower(): v
                                 for k, v in _vba_dir_offsets(ole.openstream(ent).read()).items()})
            for ent in ole.listdir()[:300]:
                if ole.get_size("/".join(ent)) > (8 << 20):
                    continue
                s = ole.openstream(ent).read()
                if len(ent) >= 2 and ent[-1].lower() not in ("dir", "_vba_project") and \
                        not ent[-1].startswith("__SRP_") and ole.exists("/".join(ent[:-1] + ["dir"])):
                    off = offs.get("/".join(ent).lower())
                    src = (_ovba_decompress(s, off) if off is not None else None) or _vba_sources(s)
                    if src:
                        yield f"{name}:{'/'.join(ent)}", src
                        continue
                yield from _carrier_blobs(s, f"{name}:{'/'.join(ent)}", depth + 1, budget)
        elif b[:2] == b"MZ" and depth == 0:                    # compiled AHK (Ahk2Exe) / any PE: RT_RCDATA members
            ns = nsis_extract(b, budget=max(0.05, min(0.5, budget - time.time()))) if b"NullsoftInst" in b else {}
            if ns.get("format") == "nsis":                      # NSIS overlay: the string table, then the files
                yield f"{name}#nsis:strings", "\n".join(ns["strings"]).encode("utf-8")
                for fn, fb in ns["files"][:64]:
                    yield from _carrier_blobs(fb, f"{name}#nsis:{fn}", depth + 1, budget)
            import pefile
            pe = pefile.PE(data=b, fast_load=True)
            pe.parse_data_directories(directories=[pefile.DIRECTORY_ENTRY["IMAGE_DIRECTORY_ENTRY_RESOURCE"]])
            for t in getattr(getattr(pe, "DIRECTORY_ENTRY_RESOURCE", None), "entries", [])[:64]:
                if t.id != 10 or not hasattr(t, "directory"):
                    continue
                for n in t.directory.entries[:64]:
                    for lang in getattr(getattr(n, "directory", None), "entries", [])[:8]:
                        d = lang.data.struct
                        if 0 < d.Size <= (8 << 20) and time.time() < budget:
                            data = pe.get_data(d.OffsetToData, d.Size)
                            data = data[3:] if data[:3] == b"\xef\xbb\xbf" else data
                            yield from _carrier_blobs(data, f"{name}#rcdata:{n.name or n.id}", depth + 1, budget)
        elif b[:4] in (b"\xd4\xc3\xb2\xa1", b"\xa1\xb2\xc3\xd4", b"\x4d\x3c\xb2\xa1", b"\xa1\xb2\x3c\x4d",
                       b"\x0a\x0d\x0d\x0a"):             # pcap / pcapng: reassembled HTTP bodies (the fetched stage)
            for o in http_objects(b, budget=max(0.05, budget - time.time())):
                if o["body"]:
                    yield from _carrier_blobs(o["body"], f"{name}#http:{o['uri'] or o['direction']}", depth + 1,
                                              budget)
        elif b[:8] == b"!<arch>\n" or b[:4] in (b"\xed\xab\xee\xdb", b"\x8e\xad\xe8\x01"):   # .deb / .rpm scripts
            for r in pkg_scripts(name, b)[:32]:
                if isinstance(r.get("body"), str) and r["body"].strip():
                    yield f"{name}#{r['format']}:{r['hook']}", r["body"].encode("utf-8", "surrogateescape")
        elif b[:2] == b"\x1f\x8b":
            yield from _carrier_blobs(zlib.decompressobj(31).decompress(b, 1 << 22), name + "|gunzip", depth + 1, budget)
        elif _is_asar(b):                                # Electron app.asar: its files, package.json `main` first
            for p, fb in asar_files(b).items():
                if time.time() > budget:
                    break
                yield from _carrier_blobs(fb, f"{name}!/{p}", depth + 1, budget)
        else:
            i = b.find(_ONE_FDSO)
            while 0 <= i and i + 36 <= len(b):
                n = int.from_bytes(b[i + 16:i + 24], "little")
                if 0 < n <= len(b) - i - 36:
                    yield from _carrier_blobs(b[i + 36:i + 36 + n], f"{name}#one@{i}", depth + 1, budget)
                i = b.find(_ONE_FDSO, i + 16)
    except Exception:  # noqa: BLE001 - truncated / impostor container: keep what was yielded
        return


def _carrier_texts(src, raw):
    """(member, text) candidates for a carrier: decoded member streams plus their UTF-16LE runs."""
    if raw is None and src:
        try:
            raw = src.encode("latin-1") if max(src) < "Ā" else src.encode("utf-8", "surrogateescape")
        except (UnicodeEncodeError, ValueError):
            raw = None
    out = []
    if raw and (raw[:4] in (m[:4] for m in _MAGICS) or raw[:16] in _MAGICS or b"\x00" in raw[:1 << 16]):
        for name, b in _carrier_blobs(raw):
            u = _utf16(b) if b[:2] in (b"\xff\xfe", b"\xfe\xff") else None
            if name and b[:4] not in (m[:4] for m in _MAGICS):
                out.append((name, (u or b).decode("utf-8", "ignore")))
            out.extend((name + "~u16", r.decode("utf-16-le")) for r in _U16_RUN.findall(b)[:64])
    elif src and "\x00" in src:                      # lossy utf-8 decode of a carrier: the UTF-16LE runs survive
        out.extend(("~u16", r.encode("latin-1").decode("utf-16-le")) for r in _U16_RUN_S.findall(src)[:64])
    if src and "\x00" in src and not out:
        out.append(("", src))
    return out


def _carrier_codecs(src, raw, depth=0):
    import time
    try:
        texts = _carrier_texts(src, raw)
        end = time.time() + 0.6
        for name, text in texts:
            for c in _find_codecs_text(text):
                if c.get("plain"):
                    return [dict(c, id=f"{c['id']}@{name}" if name else c["id"])]
        for name, text in texts if depth < 1 else ():   # a fetched HTTP body is a whole script: every reading
            if "#http:" in name and not name.endswith("~u16") and time.time() < end:
                for c in find_codecs(text, depth + 1):
                    if c.get("plain"):
                        return [dict(c, id=f"{c['id']}@{name}")]
        seen = set()
        for name, text in texts + ([("", src)] if src and "\x00" in src else []):
            for tok in _MAT_TOKEN.findall(text)[:48]:
                if tok in seen or time.time() > end:
                    continue
                seen.add(tok)
                plain = peel_plan(tok, budget=min(0.15, max(0.02, end - time.time())))
                if plain:
                    return [{"id": f"carrier@{name}", "rep": "carrier", "transform": "identity", "key": "",
                             "material": tok, "plain": plain}]
        if raw is not None and depth < 1 and (raw[:4] == b"PK\x03\x04" or raw[:2] == b"MZ"):
            return _electron_codecs(raw)                # Squirrel Setup.exe / .nupkg chains deeper than the walk above
    except Exception:  # noqa: BLE001 - unknown -> nothing, never an exception
        return []
    return []


# ------------------------------------------------------------------------------------- Electron app.asar / Squirrel
# Target electron-asar-squirrel-route: installer-delivered Electron apps hide their Node JS in resources/app.asar -- a
# Chromium pickle header (u32 4, u32 header_size, u32 pickle payload size, u32 json_len, JSON `{"files":{name:{offset
# (string), size, unpacked?, link?} | {"files":{...}}}}`, padded to 4) with the file data at 8 + header_size. Squirrel
# ships it as Setup.exe (PE resource "DATA"/131 = a zip of Update.exe + RELEASES + <App>-<ver>-full.nupkg) -> the
# .nupkg (zip) -> lib/net45/<App>.exe + lib/net45/resources/app.asar. asar_files() lists one archive; electron_members()
# unwraps the whole chain; _electron_codecs() runs the text readers over each member, package.json `main` first.
# Reached from find_codecs(bytes) (via _carrier_blobs) and from decode(rep=asar|squirrel|nupkg, base64/hex material).
# Bounded, never raises; a lossy utf-8 text read keeps working when the JSON + JS survived (the header u32s may not).
_ASAR_HDR = b'{"files":'
_ASAR_TEXT_EXT = re.compile(r"\.(?:[cm]?js|json|html?|ps1|psm1|bat|cmd|vbs|txt|nuspec|xml|config|sh|py)$|(?:^|/)RELEASES$",
                            re.I)


def _is_asar(b):
    return len(b) >= 24 and b[:4] == b"\x04\x00\x00\x00" and b.find(_ASAR_HDR, 8, 64) >= 0


def asar_files(data, limit=4000):
    """{path: bytes} of an Electron app.asar (packed members only: `unpacked` / `link` entries live outside it), in
    header order with package.json's `main` first. {} when `data` is not an asar or is truncated. Never raises."""
    import json
    import struct
    out = {}
    try:
        b = bytes(data or b"")
        if not _is_asar(b):
            return {}
        hdr = base = None
        hs, _ps, jl = struct.unpack_from("<III", b, 4)
        if 8 + jl <= hs <= len(b) - 8 and b[16:17] == b"{":
            try:
                hdr, base = json.loads(b[16:16 + jl].decode("utf-8")), 8 + hs
            except ValueError:
                hdr = None
        if not isinstance(hdr, dict):                   # lossy read: the u32s are mangled, the JSON is intact
            i = b.find(_ASAR_HDR, 8, 64)
            t = b[i:i + (16 << 20)].decode("utf-8", "replace")
            hdr, end = json.JSONDecoder().raw_decode(t)
            jl = len(t[:end].encode("utf-8"))
            base = i + jl + (-jl % 4)
        stack = [("", hdr.get("files") if isinstance(hdr, dict) else None)]
        while stack and len(out) < limit:
            pre, node = stack.pop(0)
            if not isinstance(node, dict):
                continue
            for name, ent in list(node.items())[:limit]:
                if not isinstance(ent, dict):
                    continue
                path = f"{pre}{name}"
                if "files" in ent:
                    stack.append((path + "/", ent["files"]))
                elif not ent.get("unpacked") and "link" not in ent:
                    off, size = int(ent.get("offset", -1)), int(ent.get("size", -1))
                    if off >= 0 and 0 <= size <= len(b) - base - off:
                        out[path] = b[base + off:base + off + size]
        main = None
        if "package.json" in out:
            try:
                main = json.loads(out["package.json"].decode("utf-8-sig")).get("main")
            except (ValueError, AttributeError):
                main = None
        main = re.sub(r"^(?:\./)+", "", str(main or "index.js")).strip("/")
        for k in (main, main + ".js", main + "/index.js"):
            if k in out:
                return {k: out[k], **{p: v for p, v in out.items() if p != k}}
    except Exception:  # noqa: BLE001 - impostor / truncated archive: whatever parsed so far
        return out
    return out


def electron_members(data, name="", depth=0, end=None):
    """[(path, bytes)] of every leaf inside an Electron / Squirrel delivery chain: Setup.exe (PE resources holding a
    zip or asar) -> zip / .nupkg members -> app.asar files (gzip peeled). Leaves are returned as-is. Never raises."""
    import io
    import zlib
    end = end if end is not None else time.time() + 0.8
    out = []
    try:
        b = bytes(data or b"")
        if depth > 6 or time.time() > end or len(b) < 8:
            return [(name, b)] if b else []
        if _is_asar(b):
            for p, fb in asar_files(b).items():
                out += electron_members(fb, f"{name}!/{p}", depth + 1, end)
            return out or [(name, b)]
        if b[:4] == b"PK\x03\x04":
            import zipfile
            z = zipfile.ZipFile(io.BytesIO(b))
            for zi in z.infolist()[:400]:
                if not zi.is_dir() and not zi.flag_bits & 1 and zi.file_size <= (32 << 20) and time.time() < end:
                    try:
                        out += electron_members(z.read(zi), f"{name}/{zi.filename}", depth + 1, end)
                    except Exception:  # noqa: BLE001 - one bad member, keep walking
                        continue
            return out or [(name, b)]
        if b[:2] == b"\x1f\x8b":
            return electron_members(zlib.decompressobj(31).decompress(b, 32 << 20), name + "|gunzip", depth + 1, end)
        if b[:2] == b"MZ":
            import pefile
            pe = pefile.PE(data=b, fast_load=True)
            pe.parse_data_directories(directories=[pefile.DIRECTORY_ENTRY["IMAGE_DIRECTORY_ENTRY_RESOURCE"]])
            for t in getattr(getattr(pe, "DIRECTORY_ENTRY_RESOURCE", None), "entries", [])[:64]:
                for n in getattr(getattr(t, "directory", None), "entries", [])[:64]:
                    for lang in getattr(getattr(n, "directory", None), "entries", [])[:8]:
                        d = getattr(getattr(lang, "data", None), "struct", None)
                        if d is None or not 0 < d.Size <= (64 << 20) or time.time() > end:
                            continue
                        rb = pe.get_data(d.OffsetToData, d.Size)
                        if rb[:4] == b"PK\x03\x04" or _is_asar(rb) or rb[:2] == b"\x1f\x8b":
                            tn = str(t.name) if t.name else t.id
                            out += electron_members(rb, f"{name}#{tn}/{n.name or n.id}", depth + 1, end)
            return [(name, b)] + out
    except Exception:  # noqa: BLE001 - truncated / impostor container: keep what was found
        return out or ([(name, bytes(data))] if isinstance(data, (bytes, bytearray)) else [])
    return [(name, b)]


def _electron_codecs(raw, budget=1.2):
    """find_codecs-shaped hits from the script members of an Electron / Squirrel chain, or []. Never raises."""
    try:
        end = time.time() + budget
        mem = electron_members(raw, end=end - budget / 3)
        if len(mem) < 2 and not _is_asar(bytes(raw[:64])):
            return []
        texts = []
        for p, b in mem:
            if not b or not (_ASAR_TEXT_EXT.search(p) or b"\x00" not in b[:4096]) or b[:2] == b"MZ":
                continue
            u = _utf16(b) if b[:2] in (b"\xff\xfe", b"\xfe\xff") else None
            texts.append((p, u if isinstance(u, str) else (u or b).decode("utf-8-sig", "replace")))
        for p, t in texts:
            for c in _find_codecs_text(t):
                if c.get("plain"):
                    return [dict(c, id=f"{c['id']}@{p}")]
        for p, t in texts:
            if time.time() > end:
                break
            for c in find_codecs(t, 2):
                if c.get("plain"):
                    return [dict(c, id=f"{c['id']}@{p}")]
        seen = set()
        for p, t in texts:
            for tok in _MAT_TOKEN.findall(t)[:48]:
                if tok in seen or time.time() > end:
                    continue
                seen.add(tok)
                plain = peel_plan(tok, budget=min(0.15, max(0.02, end - time.time())))
                if plain:
                    return [{"id": f"asar@{p}", "rep": "carrier", "transform": "identity", "key": "",
                             "material": tok, "plain": plain}]
    except Exception:  # noqa: BLE001 - unknown -> nothing, never an exception
        return []
    return []


def _electron_decode(material, transform=None, key=None):
    """decode() route for rep asar / electron_asar / squirrel / nupkg: the material is the container itself (base64,
    hex, or latin-1 bytes). The plan of its first plan-bearing script member, or None."""
    try:
        m = (material or "").strip()
        for b in (b64(m), hex_bytes(m) if re.fullmatch(r"[0-9a-fA-F\s]+", m) else None, m.encode("latin-1", "ignore")):
            if b and (_is_asar(b) or b[:4] == b"PK\x03\x04" or b[:2] in (b"MZ", b"\x1f\x8b")):
                hits = _electron_codecs(b)
                if hits:
                    return hits[0]["plain"]
    except Exception:  # noqa: BLE001
        return None
    return None


# ------------------------------------------------------------------------------------------------ SaaS / add-in hosts
# D18 opened SaaS script hosts (Apps Script google_docs_sidebar). Siblings ship the same plan inside a host container:
# a JSON document whose string holds the script (Office Scripts .osts `body`, Apps Script project `files[].source`,
# Power Automate / Logic Apps definitions, VS Code package.json), or a zip / CRX package whose manifest names the script
# members (appsscript.json, Chrome MV3 manifest.json, Office add-in manifest.xml, VSIX). saas_host() unwraps the
# container into script texts; _saas_host_codecs() runs the normal readers over each.

_SAAS_STR = re.compile(r'"((?:[^"\\\r\n]|\\.){48,})"')
_SAAS_REF = re.compile(r'"(?:service_worker|main|browser|scripts|js|file|path|scriptFile)"\s*:\s*(\[[^\]]{0,2000}\]|"[^"]{1,300}")'
                       r'|(?:DefaultValue|src|href)\s*=\s*"([^"]{1,300})"')
_SAAS_PROFILES = (
    ("office_script", re.compile(r"ExcelScript\.Workbook|\"noCodeMetadata\"|\.osts$")),
    ("apps_script", re.compile(r"appsscript\.json|\.gs$|\"SERVER_JS\"|\b(?:DocumentApp|SpreadsheetApp|GmailApp|"
                               r"HtmlService|ScriptApp|CardService)\.|function do(?:Get|Post)\s*\(")),
    ("office_addin", re.compile(r"<OfficeApp\b|Office\.onReady|Office\.initialize")),
    ("browser_extension", re.compile(r"\"manifest_version\"|\"service_worker\"|\"content_scripts\"|^Cr24|\.crx$")),
    ("power_automate", re.compile(r"Microsoft\.Logic|\"definition\"\s*:\s*\{|\"triggers\"\s*:|\"actions\"\s*:")),
    ("vscode_extension", re.compile(r"\"activationEvents\"|\"engines\"\s*:\s*\{\s*\"vscode\"|extension\.vsixmanifest")),
    ("salesforce_apex", re.compile(r"\.cls$|@AuraEnabled|\b(?:public|global)\s+(?:with sharing\s+)?class\s+\w+")),
)


def _saas_json_strings(text, limit=24):
    """Code-bearing JSON string values of `text`, longest first: a full parse when it is JSON, else every long quoted
    literal json-unescaped (JSONC / truncated / JSON embedded in another file)."""
    import json
    vals = []
    s = (text or "").lstrip("﻿ \t\r\n")
    if s[:1] in "{[" and len(s) < (4 << 20):
        try:
            stack, n = [json.loads(s)], 0
            while stack and n < 20000:
                v, n = stack.pop(), n + 1
                if isinstance(v, dict):
                    stack.extend(v.values())
                elif isinstance(v, list):
                    stack.extend(v)
                elif isinstance(v, str) and len(v) >= 48:
                    vals.append(v)
        except (ValueError, RecursionError):
            vals = []
    if not vals:
        for m in _SAAS_STR.finditer((text or "")[:4 << 20]):
            if "\\" in m.group(1):
                try:
                    vals.append(json.loads('"' + m.group(1) + '"'))
                except ValueError:
                    continue
    vals = [v for v in dict.fromkeys(vals) if "\n" in v or "(" in v or "=" in v]
    return sorted(vals, key=len, reverse=True)[:limit]


def _saas_zip(raw):
    """The zip inside a package: a plain zip / VSIX / .xpi, or a Chrome CRX2/CRX3 (`Cr24` header then the zip)."""
    if raw[:4] == b"PK\x03\x04":
        return raw
    if raw[:4] == b"Cr24" and len(raw) > 16:
        ver = int.from_bytes(raw[4:8], "little")
        off = 12 + int.from_bytes(raw[8:12], "little") if ver == 3 else \
            16 + int.from_bytes(raw[8:12], "little") + int.from_bytes(raw[12:16], "little")
        if raw[off:off + 4] != b"PK\x03\x04":
            off = raw.find(b"PK\x03\x04", 12, 1 << 16)
        return raw[off:] if off > 0 else None
    return None


def saas_host(name, src):
    """Unwrap a cloud/SaaS/add-in script host. `src` = bytes or text of the file (`name` its file name, may be "").
    -> {"profile": guess or None, "scripts": [(member, text)]} -- manifest-referenced members first; [] when it is
    not a host container. Never raises."""
    import io
    import time
    out = {"profile": None, "scripts": []}
    try:
        end = time.time() + 0.4
        raw = bytes(src) if isinstance(src, (bytes, bytearray)) else None
        if raw is None and src:
            try:
                raw = src.encode("latin-1") if max(src) < "Ā" else None
            except (UnicodeEncodeError, ValueError):
                raw = None
        text = src if isinstance(src, str) else (raw or b"").decode("utf-8", "ignore")
        z = _saas_zip(raw) if raw else None
        scripts, sig = [], [name or "", text[:1 << 16] if z is None else "Cr24" if raw[:4] == b"Cr24" else ""]
        if z is not None:
            import zipfile
            zf = zipfile.ZipFile(io.BytesIO(z))
            mem = {}
            for zi in zf.infolist()[:200]:
                if zi.is_dir() or zi.flag_bits & 1 or zi.file_size > (4 << 20) or time.time() > end:
                    continue
                try:
                    mem[zi.filename] = zf.read(zi).decode("utf-8", "ignore").lstrip("﻿")
                except Exception:  # noqa: BLE001 - one bad member, keep walking
                    continue
            refs = set()
            for fn, t in mem.items():
                base = fn.rsplit("/", 1)[-1].lower()
                if base in ("manifest.json", "appsscript.json", "package.json", "manifest.xml",
                            "extension.vsixmanifest") or base.endswith((".html", ".htm", ".xml")):
                    sig.append(fn + "\n" + t[:1 << 14])
                    for m in _SAAS_REF.finditer(t[:1 << 18]):
                        for r in re.findall(r'[^"\[\],\s]+', m.group(1) or m.group(2) or ""):
                            refs.add(r.split("?")[0].rstrip("/").rsplit("/", 1)[-1].lower())
                elif base.endswith((".gs", ".osts", ".cls", ".trigger")):
                    sig.append(fn)
            order = sorted(mem, key=lambda fn: (fn.rsplit("/", 1)[-1].lower() not in refs,
                                                not fn.lower().endswith((".gs", ".js", ".ts", ".osts", ".cls",
                                                                         ".html", ".htm", ".json")), fn))
            for fn in order:
                scripts.append((fn, mem[fn]))
                if fn.lower().endswith((".json", ".osts")):
                    scripts.extend((f"{fn}#str", v) for v in _saas_json_strings(mem[fn], 8))
        elif text.lstrip("﻿ \t\r\n")[:1] in "{[" or "\\n" in text[:1 << 16]:
            scripts = [("#str", v) for v in _saas_json_strings(text)]
        for pool in (sig, [t[:1 << 14] for _, t in scripts[:6]]):     # the container's own signals win
            out["profile"] = next((p for p, rx in _SAAS_PROFILES if any(rx.search(s) for s in pool)), None)
            if out["profile"]:
                break
        out["scripts"] = scripts
    except Exception:  # noqa: BLE001 - truncated / impostor container: what was read so far
        pass
    return out


def _saas_host_codecs(src, raw, depth=0, name=""):
    import time
    try:
        host = saas_host(name, raw if raw is not None else src)
        end = time.time() + 0.8
        for member, text in host["scripts"]:
            if time.time() > end:
                break
            for c in find_codecs(text, depth + 1):
                if c.get("plain"):
                    tag = f"saas:{host['profile'] or 'host'}:{member}"
                    return [dict(c, id=f"{c['id']}@{tag}")]
    except Exception:  # noqa: BLE001 - unknown -> nothing, never an exception
        return []
    return []


# ------------------------------------------------------------------------------------------------ JSON script carriers
# Target notebook-manifest-json-carrier: a script carried inside a JSON document -- Jupyter `.ipynb` (`source` = list of
# lines, `%%bash` / `%%powershell` cell magics, `!cmd` shell escapes, outputs), VS Code `tasks.json` / `launch.json`
# (`command` + `args`, `runOptions.runOn: folderOpen` auto-run), package.json / composer.json `scripts`,
# `.devcontainer.json` `postCreateCommand` (string / argv / named map), Logic App `definition.actions.*.inputs`.
# JSONC (comments, trailing commas) is cleaned first. json_scripts() lists the carried texts; _json_carrier_codecs()
# reads them (shell `-c` / `node -e` bodies unquoted, bash `"a"\<nl>"b"` folded, `!echo` chunk lists) through
# find_codecs. Consulted when nothing produced a plan, or when the plan read so far is a prefix (lossy) of its reading.

_JC_CUE = re.compile(r'"(?:cells|nbformat|scripts|tasks|configurations|command|args|(?:postCreate|postStart|postAttach|'
                     r'onCreate|updateContent|initialize)Command|definition|actions|inputs|preLaunchTask|'
                     r'(?:pre|post)_(?:un)?install|(?:un)?installer)"\s*:')
_JC_TOKS = re.compile(r'"(?:[^"\\]|\\.)*"|//[^\n]*|/\*.*?\*/|,(?=(?:\s|//[^\n]*|/\*.*?\*/)*[}\]])', re.S)
_JC_DEVC = ("initializeCommand", "onCreateCommand", "updateContentCommand", "postCreateCommand", "postStartCommand",
            "postAttachCommand")
_JC_SCRIPT_KEYS = ("preinstall", "install", "postinstall", "prepare", "prepublish", "prepublishOnly", "preuninstall",
                   "postuninstall", "pretest", "test", "start", "build")
_JC_SCOOP = ("pre_install", "post_install", "installer", "pre_uninstall", "post_uninstall", "uninstaller")
_JC_MAGIC = {"bash": "bash", "sh": "bash", "zsh": "bash", "script": None, "powershell": "powershell", "pwsh": "powershell",
             "javascript": "javascript", "js": "javascript", "node": "javascript", "perl": "perl", "ruby": "ruby",
             "python": "python", "python3": "python", "python2": "python", "pypy": "python", "cmd": "batch",
             "html": "html", "writefile": None, "file": None}
_JC_INTERP = re.compile(r"""(?:^|[\s;&|(])(?:[\w./\\-]*[\\/])?(?:node|nodejs|deno|python[\d.]*|py|php|perl|ruby|lua|"""
                        r"""powershell|pwsh|cmd)(?:\.exe)?[ \t]+(?:-[\w-]+[ \t]+)*?(?:-e|-c|-r|--eval|-Command|-command|"""
                        r"""/c|/k|/C|/K)[ \t]+""")


def _jc_load(text):
    """JSON / JSONC (comments, trailing commas) -> object, or None."""
    import json
    s = (text or "").lstrip("﻿ \t\r\n")
    if not s or len(s) > (4 << 20):
        return None
    try:
        return json.loads(s)
    except (ValueError, RecursionError):
        pass
    try:
        t = _JC_TOKS.sub(lambda m: m.group(0) if m.group(0)[:1] == '"' else "", s)
        return json.loads(t)
    except (ValueError, RecursionError):
        return None


def _jc_lang(cmd):
    w = re.split(r"[\s\"']+", (cmd or "").strip().strip("\"'"), 1)[0].replace("\\", "/").rsplit("/", 1)[-1].lower()
    w = re.sub(r"\.exe$", "", w)
    return {"sh": "bash", "bash": "bash", "zsh": "bash", "pwsh": "powershell", "powershell": "powershell",
            "node": "javascript", "npx": "javascript", "deno": "javascript", "php": "php", "@php": "php", "perl": "perl",
            "ruby": "ruby", "cmd": "batch", "lua": "lua"}.get(w) or ("python" if w.startswith(("python", "py")) else None)


def _jc_argv(v):
    """A VS Code / devcontainer argv item: str, or {"value": .., "quoting": ..}."""
    if isinstance(v, dict):
        v = v.get("value")
    if isinstance(v, list):
        return " ".join(str(x) for x in v if isinstance(x, (str, int, float)))
    return v if isinstance(v, str) else None


def _jc_notebook(nb, out):
    cells = nb.get("cells") or [c for w in nb.get("worksheets") or [] if isinstance(w, dict)
                                for c in w.get("cells") or []]
    md = nb.get("metadata") if isinstance(nb.get("metadata"), dict) else {}
    kl = str((md.get("kernelspec") or {}).get("language") or (md.get("language_info") or {}).get("name")
             or "python").lower()
    bang = []
    for i, c in enumerate(cells[:4096]):
        if not isinstance(c, dict):
            continue
        s = c.get("source", c.get("input", ""))
        t = "".join(str(x) for x in s) if isinstance(s, list) else str(s or "")
        if not t.strip():
            pass
        elif c.get("cell_type") not in (None, "code"):
            out.append({"path": f"cells[{i}]", "lang": str(c.get("cell_type")), "text": t})
        else:
            first, _, rest = t.lstrip().partition("\n")
            m = re.match(r"%%(\w+)[ \t]*(\S*)", first)
            if m and m.group(1).lower() in _JC_MAGIC:
                lang = _JC_MAGIC[m.group(1).lower()] or _jc_lang(m.group(2)) or \
                    {"ps1": "powershell", "sh": "bash", "js": "javascript", "py": "python", "bat": "batch",
                     "cmd": "batch", "vbs": "vbscript"}.get(m.group(2).rsplit(".", 1)[-1].lower()) or m.group(2) or kl
                out.append({"path": f"cells[{i}]%%{m.group(1)}", "lang": lang, "text": rest})
            else:
                out.append({"path": f"cells[{i}]", "lang": kl, "text": t})
                b = [re.sub(r"^[ \t]*(?:\w+[ \t]*=[ \t]*)?(?:!|%(?:sx|system)[ \t]+)", "", ln)
                     for ln in t.splitlines() if re.match(r"[ \t]*(?:\w+[ \t]*=[ \t]*)?(?:!|%(?:sx|system)[ \t])", ln)]
                if b:
                    bang.extend(b)
                    out.append({"path": f"cells[{i}]!", "lang": "bash", "text": "\n".join(b)})
        for j, o in enumerate((c.get("outputs") or [])[:64]):
            if not isinstance(o, dict):
                continue
            parts = [o.get("text")] + [v for k, v in (o.get("data") or {}).items()
                                       if k.startswith(("text/", "application/javascript", "application/json"))]
            for v in parts:
                v = "".join(str(x) for x in v) if isinstance(v, list) else v
                if isinstance(v, str) and v.strip():
                    out.append({"path": f"cells[{i}].outputs[{j}]", "lang": "output", "text": v})
    if bang and len(out) > 1:
        out.append({"path": "cells[*]!", "lang": "bash", "text": "\n".join(bang)})


def json_scripts(name, data):
    """Scripts carried inside a JSON / JSONC document -> [{path, lang, text}] (carrier-specific fields first, then every
    other string value); [] when it is not JSON. `data` = text or bytes. Never raises."""
    out = []
    try:
        if isinstance(data, (bytes, bytearray)):
            b = bytes(data)[:4 << 20]
            data = (_utf16(b) or b).decode("utf-8", "ignore") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else \
                b.decode("utf-8", "ignore")
        doc = _jc_load(data)
        if not isinstance(doc, (dict, list)):
            return []
        if isinstance(doc, dict) and (isinstance(doc.get("cells"), list) or "nbformat" in doc or
                                      isinstance(doc.get("worksheets"), list)):
            _jc_notebook(doc, out)
        rest, stack, n = [], [("$", doc)], 0
        while stack and n < 20000:
            path, v = stack.pop()
            n += 1
            if isinstance(v, dict):
                cmd = v.get("command") if isinstance(v.get("command"), str) else None
                if cmd is not None or isinstance(v.get("args"), list):
                    args = [a for a in (_jc_argv(x) for x in (v.get("args") or [])[:256]) if a is not None]
                    auto = ((v.get("runOptions") or {}).get("runOn") == "folderOpen") if isinstance(v.get("runOptions"), dict) else False
                    out.append({"path": path + (".command[folderOpen]" if auto else ".command"),
                                "lang": _jc_lang(cmd or (args[:1] or [""])[0]),
                                "text": " ".join([cmd or ""] + args).strip()})
                for k in _JC_DEVC:
                    c = v.get(k)
                    for kk, cv in (c.items() if isinstance(c, dict) else [("", c)]):
                        t = _jc_argv(cv)
                        if t:
                            out.append({"path": f"{path}.{k}{'.' + kk if kk else ''}", "lang": _jc_lang(t), "text": t})
                for k in _JC_SCOOP:      # Scoop: a PowerShell body as a string or an array of lines (joined)
                    c = v.get(k)
                    c = c.get("script") if isinstance(c, dict) and k.endswith("installer") else c
                    t = "\n".join(x for x in c[:4096] if isinstance(x, str)) if isinstance(c, list) else c
                    if isinstance(t, str) and t.strip():
                        out.append({"path": f"{path}.{k}", "lang": "powershell", "text": t})
                if isinstance(v.get("scripts"), dict):
                    sc = v["scripts"]
                    for k in sorted(sc, key=lambda k: k not in _JC_SCRIPT_KEYS and not k.startswith(("pre", "post"))):
                        for t in (sc[k] if isinstance(sc[k], list) else [sc[k]])[:64]:
                            if isinstance(t, str) and t.strip():
                                out.append({"path": f"{path}.scripts.{k}", "lang": _jc_lang(t) or "bash", "text": t})
                stack.extend((f"{path}.{k}", x) for k, x in reversed(list(v.items())))
            elif isinstance(v, list):
                stack.extend((f"{path}[{i}]", x) for i, x in reversed(list(enumerate(v[:4096]))))
            elif isinstance(v, str) and len(v) >= 16:
                rest.append({"path": path, "lang": None, "text": v})
        seen, res = set(), []
        for d in out + rest:
            if d["text"] not in seen:
                seen.add(d["text"])
                res.append(d)
        return res[:512]
    except Exception:  # noqa: BLE001 - truncated / impostor: what was read so far
        return out[:512]


def _jc_variants(d):
    """Readable forms of one carried text: itself, its shell / interpreter `-c` / `-e` bodies, bash continuation fold."""
    t = d["text"]
    vs = [t]
    for m in list(_PH_SHC.finditer(t)) + list(_JC_INTERP.finditer(t)):
        b = _ph_shell_word(t, m.end())
        if b and b.strip() and len(b) >= 16:
            vs.append(b)
    if d.get("lang") == "bash" or "\\\n" in t:
        for b in list(vs):
            f = re.sub(r"""(["'])[ \t]*\\\r?\n[ \t]*\1""", "", b)          # "a"\<nl>"b" -> "ab"
            f = re.sub(r"""(["'])\1(?=[A-Za-z0-9+/=_\-.%~:])""", "", f)   # "a""b" -> "ab"
            if f != b:
                vs.append(f)
    return list(dict.fromkeys(vs))


# JMeter test plan (.jmx, jvm-pair-host-profiles): the descriptor rides as a User Defined Variable / header / HTTP
# argument -- an `<elementProp>` whose `*.name` stringProp (or name= attribute) is `descriptor_x` and whose `*.value`
# stringProp holds the XML-escaped literal, `${var}` references resolved from the plan's other pairs (JMeter variable
# expansion) -- while the BeanShell / JSR223 sampler only reads it back with `vars.get("descriptor_x")`. Regex +
# html.unescape over the text (no DTD / entity resolution), bounded, never raises.
_JMX_CUE = re.compile(r"<jmeterTestPlan\b|<stringProp\s+name=[\"'](?:Argument|Header|HTTPArgument)\.(?:name|value)[\"']")
_JMX_ELEM = re.compile(r"<elementProp\b([^>]*?)/?>|</elementProp\s*>")
_JMX_PROP = re.compile(r"""<stringProp\s+name=(["'])(?P<n>[^"'<>]*)\1\s*(?:/>|>(?P<v>[^<]*)</stringProp\s*>)""")
_JMX_NAME = re.compile(r"""\bname=(["'])([^"'<>]*)\1""")
_JMX_VAR = re.compile(r"\$\{([A-Za-z_][\w.-]*)\}")


def _jmx_codecs(src, depth=0, budget=0.4):
    """find_codecs readings of the `descriptor_x` name/value pairs a JMeter test plan carries (`@jmx`)."""
    import html
    try:
        end = time.time() + budget
        s = src[:1 << 20]
        env, descs = {}, []
        ms = list(_JMX_ELEM.finditer(s))
        for k, m in enumerate(ms):
            if m.group(0).startswith("</") or m.group(0).endswith("/>"):
                continue
            body = s[m.end():ms[k + 1].start() if k + 1 < len(ms) else len(s)]
            props = {}
            for p in _JMX_PROP.finditer(body):
                props.setdefault(p.group("n").rsplit(".", 1)[-1].lower(), html.unescape(p.group("v") or ""))
            if "value" not in props:
                continue
            na = _JMX_NAME.search(m.group(1) or "")
            name = (props.get("name") or (html.unescape(na.group(2)) if na else "")).strip()
            if name and name not in env:
                env[name] = props["value"]
                if re.fullmatch(r"(?i)descriptor[_-][\w-]+", name):
                    descs.append(name)
        if not descs:
            return []
        lines = [m.group(0) for m in _CODEC_RE.finditer(html.unescape(s))][:8]
        for name in descs[:8]:
            v = env[name]
            for _ in range(4):                                       # ${a}${b} -> nested User Defined Variables
                w = _JMX_VAR.sub(lambda r: env.get(r.group(1), r.group(0)) if r.group(1) != name else r.group(0), v)
                if w == v or len(w) > (1 << 20):
                    break
                v = w
            v = v.strip()
            if v and time.time() < end:
                lines.append('String %s = "%s";' % (re.sub(r"\W", "_", name), v.replace("\\", "\\\\").replace('"', '\\"')))
        out = []
        for c in find_codecs("\n".join(lines) + "\n", depth + 1):
            if c.get("plain") and c["plain"] not in {o["plain"] for o in out}:
                out.append(dict(c, id=f"{c['id']}@jmx"))
        return out
    except Exception:  # noqa: BLE001
        return []


def _json_carrier_codecs(src, raw=None, depth=0, name="", budget=0.6):
    """find_codecs readings of the scripts a JSON document carries (first plan wins; `@json:<path>`)."""
    try:
        end = time.time() + budget
        items = json_scripts(name, raw if raw is not None else src)
        if not items:
            return []
        for d in items[:256]:
            if time.time() > end:
                break
            hits = []
            for t in _jc_variants(d):
                if t != src:
                    hits.extend(c for c in find_codecs(t, depth + 1)[:8] if c.get("plain"))
            if hits:      # a continued literal reads as its first piece raw: the variant that extends it wins
                best = max(hits, key=lambda c: sum(o["plain"] != c["plain"] and c["plain"].startswith(o["plain"])
                                                   for o in hits))
                return [dict(best, id=f"{best.get('id')}@json:{d['path']}")]
            if d["path"].endswith("!"):           # `!echo -n '<chunk>' >> f` lines: a chunk-list carrier
                mat, plain = _split_array_plain(d["text"], budget=0.2)
                if plain:
                    return [{"id": f"split@json:{d['path']}", "rep": "split_array", "transform": "identity",
                             "key": "", "material": mat, "plain": plain}]
    except Exception:  # noqa: BLE001
        return []
    return []


# ------------------------------------------------------------------------------------- package-manager install manifests
# Target package-manager-install-manifests (T1195.002 / T1059.001 / T1105): a package manager runs the package's own
# script or fetches its installer. pkgmgr_scripts() lists them by manager: Chocolatey `.nupkg` tools/chocolatey*.ps1,
# NuGet tools/install.ps1|init.ps1 + `.nuspec`, Scoop JSON pre_/post_install + installer/uninstaller.script (string or
# line array, joined) + url, winget YAML InstallerUrl / InstallerType / InstallerSwitches.Custom, Homebrew formula
# `def install|post_install` + cask `postflight do`, MSIX `.appinstaller` `<MainPackage Uri=>`, ClickOnce `.application`
# `<deploymentProvider codebase=>`. The plan itself is read by find_codecs (zip carrier / json_scripts route).

_PM_CHOCO = re.compile(r"(?i)(?:^|/)tools/chocolatey(install|beforemodify|uninstall)\.ps1$")
_PM_NUGET = re.compile(r"(?i)(?:^|/)tools/(install|init|uninstall)\.ps1$")
_PM_WINGET = re.compile(r"(?m)^[ \t-]*(InstallerUrl|InstallerType|Custom)[ \t]*:[ \t]*(?:[>|][-+]?[ \t]*\r?\n"
                        r"((?:[ \t]+\S[^\n]*\n?)+)|['\"]?([^'\"\r\n#]*)['\"]?)")
_PM_RB_DEF = re.compile(r"(?m)^([ \t]*)(def[ \t]+(install|post_install)\b|(postflight|preflight|uninstall_postflight|"
                        r"uninstall_preflight)[ \t]+do\b)[^\n]*\n")
_PM_XML_URI = re.compile(r"(?is)<(MainPackage|MainBundle|deploymentProvider|AppInstaller)\b[^>]*?\b(Uri|codebase)"
                         r"\s*=\s*[\"']([^\"']+)[\"']")


def _pm_members(members):
    items = list(members.items()) if isinstance(members, dict) else list(members or [])
    out = []
    for name, data in items[:512]:
        b = data if isinstance(data, (bytes, bytearray)) else str(data or "").encode("utf-8", "ignore")
        if bytes(b[:4]) == b"PK\x03\x04":
            try:
                import io
                import zipfile
                with zipfile.ZipFile(io.BytesIO(bytes(b))) as z:
                    for zi in z.infolist()[:256]:
                        if not zi.is_dir() and zi.file_size < (4 << 20):
                            out.append((f"{name}!{zi.filename}", z.read(zi)))
            except Exception:  # noqa: BLE001 - truncated / impostor zip
                pass
            continue
        out.append((str(name), bytes(b)))
    return out


def pkgmgr_scripts(members):
    """Package-manager install hooks -> [{manager, hook, lang, body_or_url}]. `members` = {name: bytes|str} or
    [(name, data)]; a `.nupkg` / zip member is expanded. [] when nothing is a package manifest. Never raises."""
    res = []
    try:
        for name, b in _pm_members(members):
            t = (_utf16(b[:4 << 20]) or b[:4 << 20]).decode("utf-8", "ignore").lstrip("\ufeff")
            inner = name.rsplit("!", 1)[-1].replace("\\", "/")
            low = inner.lower()
            m = _PM_CHOCO.search(inner) or _PM_NUGET.search(inner)
            if m:
                res.append({"manager": "chocolatey" if m.re is _PM_CHOCO else "nuget", "hook": m.group(1).lower(),
                            "lang": "powershell", "body_or_url": t})
                continue
            if low.endswith(".nuspec") and "<package" in t:
                for u in re.findall(r"(?is)<(projectUrl|licenseUrl|iconUrl|packageSourceUrl)>\s*([^<\s]+)", t)[:8]:
                    res.append({"manager": "nuget", "hook": u[0], "lang": "url", "body_or_url": u[1]})
                continue
            if low.endswith((".appinstaller", ".application", ".manifest")) or "<AppInstaller" in t[:4096] or \
                    "<deploymentProvider" in t:
                for tag, _a, u in _PM_XML_URI.findall(t)[:16]:
                    res.append({"manager": "clickonce" if tag.lower() == "deploymentprovider" else "msix",
                                "hook": tag, "lang": "url", "body_or_url": u})
                continue
            if t.lstrip()[:1] == "{" and any(f'"{k}"' in t for k in _JC_SCOOP + ("url",)):
                doc = _jc_load(t)
                if isinstance(doc, dict) and any(k in doc for k in _JC_SCOOP + ("url", "architecture")):
                    for k in _JC_SCOOP:
                        c = doc.get(k)
                        c = c.get("script") if isinstance(c, dict) and k.endswith("installer") else c
                        s = "\n".join(x for x in c if isinstance(x, str)) if isinstance(c, list) else c
                        if isinstance(s, str) and s.strip():
                            res.append({"manager": "scoop", "hook": k, "lang": "powershell", "body_or_url": s})
                    archs = [doc] + [a for a in (doc.get("architecture") or {}).values() if isinstance(a, dict)]
                    for a in archs[:8]:
                        for u in (a.get("url") if isinstance(a.get("url"), list) else [a.get("url")])[:16]:
                            if isinstance(u, str) and u:
                                res.append({"manager": "scoop", "hook": "url", "lang": "url", "body_or_url": u})
                    continue
            if re.search(r"(?m)^[ \t]*(?:PackageIdentifier|ManifestType)[ \t]*:", t[:1 << 16]):
                for k, blk, one in _PM_WINGET.findall(t)[:64]:
                    v = " ".join(x.strip() for x in blk.splitlines() if x.strip()) if blk else one.strip()
                    if v:
                        res.append({"manager": "winget", "hook": k, "lang": "url" if k == "InstallerUrl" else
                                    ("text" if k == "InstallerType" else "cmd"), "body_or_url": v})
                continue
            if re.search(r"(?m)^[ \t]*(?:class[ \t]+\w+[ \t]*<[ \t]*Formula\b|cask[ \t]+['\"])", t[:1 << 16]):
                mgr = "homebrew-cask" if re.search(r"(?m)^[ \t]*cask[ \t]+['\"]", t[:1 << 16]) else "homebrew"
                for m in _PM_RB_DEF.finditer(t):
                    end = re.compile(r"(?m)^" + re.escape(m.group(1)) + r"end\b").search(t, m.end())
                    res.append({"manager": mgr, "hook": m.group(3) or m.group(4), "lang": "ruby",
                                "body_or_url": t[m.end():end.start() if end else len(t)]})
                for u in re.findall(r"(?m)^[ \t]*url[ \t]+['\"]([^'\"]+)", t)[:8]:
                    res.append({"manager": mgr, "hook": "url", "lang": "url", "body_or_url": u})
    except Exception:  # noqa: BLE001
        return res
    return res


# ------------------------------------------------------------------------------- linux package maintainer scripts
# Target linux-package-maintainer-scripts (T1546.016 installer packages / T1059.004): the Linux side of the installer
# script chain -- the package manager runs the maintainer script as root at install time. pkg_scripts(name, data) ->
# [{format, hook, interpreter, body}]: `.deb` = ar (`!<arch>\n`, 60-byte member headers) -> control.tar[.gz|.xz|.bz2|
# .zst] -> preinst/postinst/prerm/postrm/config/triggers; `.rpm` = 96-byte lead `ED AB EE DB` -> signature header
# (8-byte aligned) -> main header (`8E AD E8 01`, 16-byte index entries tag/type/offset/count) -> PREIN 1023 .. POSTUN
# 1026, PRETRANS 1151 / POSTTRANS 1152, VERIFYSCRIPT 1079, TRIGGERSCRIPTS 1065 (+ *PROG interpreter tags); `.spec`
# `%post -p /bin/sh` sections; Arch PKGBUILD `install=x.install` + `.install` `post_install() {..}`; Alpine `.apk`
# (gzip-concatenated tars) / APKBUILD `.pre-install`/`.post-install` files. Bodies go through the normal readers
# (find_codecs) -- decode(material, rep='deb'|'rpm'|'pkg_scripts', transform=''|'hooks'|'interpreter', key=hook).

_PKG_DEB_HOOKS = ("preinst", "postinst", "prerm", "postrm", "config", "triggers")
_PKG_RPM_TAGS = {1023: ("%pre", 1085), 1024: ("%post", 1086), 1025: ("%preun", 1087), 1026: ("%postun", 1088),
                 1151: ("%pretrans", 1153), 1152: ("%posttrans", 1154), 1079: ("%verifyscript", 1091)}
_PKG_RPM_TRIG = ((1 << 25, "%triggerprein"), (1 << 16, "%triggerin"), (1 << 17, "%triggerun"),
                 (1 << 18, "%triggerpostun"))
_PKG_APK_HOOKS = ("pre-install", "post-install", "pre-upgrade", "post-upgrade", "pre-deinstall", "post-deinstall",
                  "trigger")
_PKG_ARCH_FN = re.compile(r"(?m)^[ \t]*(?:function[ \t]+)?((?:pre|post)_(?:install|upgrade|remove))[ \t]*\(\)[ \t]*\{")
_PKG_SPEC_SEC = re.compile(r"(?m)^%(pre|post|preun|postun|pretrans|posttrans|preuntrans|postuntrans|verifyscript|"
                           r"trigger(?:prein|in|un|postun)|filetrigger(?:in|un|postun)|transfiletrigger(?:in|un|postun)"
                           r")\b([^\n]*)\n")
_PKG_SPEC_END = re.compile(r"(?m)^%(?:package|description|prep|build|install|check|clean|files|changelog|pre|post|"
                           r"preun|postun|pretrans|posttrans|preuntrans|postuntrans|verifyscript|trigger\w*|"
                           r"filetrigger\w*|transfiletrigger\w*|generate_buildrequires|conf|patchlist|sourcelist)\b")


def _pkg_interp(body, default=None):
    s = body.lstrip("﻿") if isinstance(body, str) else ""
    if s.startswith("#!"):
        return s[2:].split("\n", 1)[0].strip() or default
    return default


def _pkg_text(b):
    b = bytes(b or b"")[:4 << 20]
    u = _utf16(b) if b[:2] in (b"\xff\xfe", b"\xfe\xff") else None
    return u if isinstance(u, str) else b.decode("utf-8", "replace").lstrip("﻿")


def _pkg_unpack(b, cap=32 << 20):
    """Decompressed bytes of a gz / xz / bz2 / zstd stream (concatenated gzip members joined), or b itself."""
    import zlib
    if b[:2] == b"\x1f\x8b":
        out, rest = [], b
        while rest[:2] == b"\x1f\x8b" and sum(map(len, out)) < cap:
            d = zlib.decompressobj(31)
            out.append(d.decompress(rest, cap))
            rest = d.unused_data
        return b"".join(out)
    if b[:6] == b"\xfd7zXZ\x00":
        import lzma
        return lzma.LZMADecompressor().decompress(b, cap)
    if b[:3] == b"BZh":
        import bz2
        return bz2.BZ2Decompressor().decompress(b, cap)
    if b[:4] == b"\x28\xb5\x2f\xfd":
        import zstandard
        return zstandard.ZstdDecompressor().decompressobj().decompress(b)[:cap]
    return b


def _pkg_tar(b):
    """[(member basename, bytes)] of a (compressed) tar, end-of-archive blocks ignored (Alpine's cut tars)."""
    import io
    import tarfile
    out = []
    with tarfile.open(fileobj=io.BytesIO(_pkg_unpack(b)), mode="r:", ignore_zeros=True) as tf:
        for ti in tf:
            if len(out) >= 256:
                break
            if ti.isfile() and ti.size < (8 << 20):
                out.append((ti.name.replace("\\", "/").rsplit("/", 1)[-1], tf.extractfile(ti).read()))
    return out


def _pkg_ar(b):
    """[(name, bytes)] of a Unix ar archive (`!<arch>\n`, 60-byte headers, even-padded data, GNU `name/`)."""
    out, i = [], 8
    while i + 60 <= len(b) and len(out) < 64:
        h = b[i:i + 60]
        if h[58:60] != b"`\n":
            break
        try:
            n = int(h[48:58].decode("ascii").strip() or "0")
        except ValueError:
            break
        out.append((h[:16].decode("ascii", "replace").strip().rstrip("/"), b[i + 60:i + 60 + n]))
        i += 60 + n + (n & 1)
    return out


def _pkg_rpm_header(b, i):
    """({tag: value}, end offset) of one RPM header structure at b[i:] (`8E AD E8 01`), or (None, i)."""
    import struct
    if b[i:i + 4] != b"\x8e\xad\xe8\x01" or i + 16 > len(b):
        return None, i
    nidx, hsize = struct.unpack(">II", b[i + 8:i + 16])
    if nidx > 4096 or hsize > (64 << 20):
        return None, i
    st = i + 16 + 16 * nidx
    store = b[st:st + hsize]
    if len(store) < hsize:
        return None, i
    tags = {}
    for k in range(nidx):
        tag, typ, off, cnt = struct.unpack(">IIII", b[i + 16 + 16 * k:i + 32 + 16 * k])
        if off >= hsize:
            continue
        if typ in (6, 8, 9):                            # STRING / STRING_ARRAY / I18NSTRING
            vals, j = [], off
            for _ in range(1 if typ == 6 else min(cnt, 4096)):
                e = store.find(b"\x00", j)
                e = hsize if e < 0 else e
                vals.append(store[j:e].decode("utf-8", "replace"))
                j = e + 1
            tags[tag] = vals[0] if typ in (6, 9) and vals else vals
        elif typ == 4:                                  # INT32
            tags[tag] = list(struct.unpack(">%dI" % min(cnt, 4096), store[off:off + 4 * min(cnt, 4096)]))
    return tags, st + hsize


def _pkg_rpm(b):
    i = 0
    if b[:4] == b"\xed\xab\xee\xdb":
        sig, e = _pkg_rpm_header(b, 96)
        if sig is None:
            return []
        i = e + (-e % 8)
    tags, _e = _pkg_rpm_header(b, i)
    if not tags:
        return []
    out = []
    for t, (hook, pt) in _PKG_RPM_TAGS.items():
        body = tags.get(t)
        if isinstance(body, str) or pt in tags:
            p = tags.get(pt)
            p = " ".join(p) if isinstance(p, list) else (p or "/bin/sh")
            out.append({"format": "rpm", "hook": hook, "interpreter": p, "body": body if isinstance(body, str) else ""})
    trig = tags.get(1065)
    if isinstance(trig, list):
        progs, flags, idx = tags.get(1092) or [], tags.get(1068) or [], tags.get(1069) or []
        for n, body in enumerate(trig):
            fl = next((f for f, ix in zip(flags, idx) if ix == n), 0)
            hook = next((h for bit, h in _PKG_RPM_TRIG if fl & bit), "%trigger")
            out.append({"format": "rpm", "hook": hook, "interpreter": progs[n] if n < len(progs) else "/bin/sh",
                        "body": body})
    return out


def _pkg_spec(t):
    out = []
    for m in _PKG_SPEC_SEC.finditer(t):
        opts = m.group(2)
        p = re.search(r"(?:^|\s)-p[ \t]+(\S+)", opts)
        end = _PKG_SPEC_END.search(t, m.end())
        out.append({"format": "rpm-spec", "hook": "%" + m.group(1), "interpreter": p.group(1) if p else "/bin/sh",
                    "body": t[m.end():end.start() if end else len(t)].rstrip("\n") + "\n"})
    return out


def _pkg_shell_fn(t, i):
    """Body of a shell function whose `{` ends at t[i-1] (brace depth, quotes skipped)."""
    d, q, j = 1, None, i
    while j < len(t) and j - i < (1 << 18):
        ch = t[j]
        if q:
            if ch == "\\" and q == '"':
                j += 1
            elif ch == q:
                q = None
        elif ch == "\\":
            j += 1
        elif ch in "\"'":
            q = ch
        elif ch == "#" and (j == i or t[j - 1] in " \t\n;"):
            nl = t.find("\n", j)
            j = len(t) if nl < 0 else nl
            continue
        elif ch == "{":
            d += 1
        elif ch == "}":
            d -= 1
            if d == 0:
                break
        j += 1
    return t[i:j]


def pkg_scripts(name, data):
    """Linux package maintainer scripts -> [{format (deb|rpm|rpm-spec|pkgbuild|arch-install|apk|apkbuild), hook,
    interpreter, body}]. `data` = bytes or text of a .deb / .rpm / .apk / .spec / PKGBUILD / .install / APKBUILD /
    Alpine `<pkg>.post-install` file. [] when it is none. Never raises."""
    out = []
    try:
        b = data if isinstance(data, (bytes, bytearray)) else str(data or "").encode("utf-8", "surrogateescape")
        b = bytes(b)[:64 << 20]
        nm = str(name or "").replace("\\", "/").rsplit("/", 1)[-1]
        low = nm.lower()
        if b[:8] == b"!<arch>\n":
            for mn, mb in _pkg_ar(b):
                if mn.startswith("control.tar"):
                    for fn, fb in _pkg_tar(mb):
                        if fn in _PKG_DEB_HOOKS:
                            t = _pkg_text(fb)
                            out.append({"format": "deb", "hook": fn,
                                        "interpreter": _pkg_interp(t, None if fn == "triggers" else "/bin/sh"),
                                        "body": t})
            return out
        if b[:4] in (b"\xed\xab\xee\xdb", b"\x8e\xad\xe8\x01"):
            return _pkg_rpm(b)
        if b[:2] == b"\x1f\x8b" and (low.endswith(".apk") or b"PKGINFO" in _pkg_unpack(b[:1 << 20], 1 << 20)):
            for fn, fb in _pkg_tar(b):
                if fn.startswith(".") and fn[1:] in _PKG_APK_HOOKS:
                    t = _pkg_text(fb)
                    out.append({"format": "apk", "hook": fn[1:], "interpreter": _pkg_interp(t, "/bin/sh"), "body": t})
            return out
        if b"\x00" in b[:4096]:
            return out
        t = _pkg_text(b)
        if low.endswith(".spec") or (re.search(r"(?mi)^Name[ \t]*:", t[:1 << 16]) and _PKG_SPEC_SEC.search(t)):
            return _pkg_spec(t)
        ext = next((h for h in _PKG_APK_HOOKS if low.endswith("." + h)), None)
        if ext:
            return [{"format": "apk", "hook": ext, "interpreter": _pkg_interp(t, "/bin/sh"), "body": t}]
        is_pb = low in ("pkgbuild", "apkbuild") or re.search(r"(?m)^[ \t]*(?:pkgname|pkgver)=", t[:1 << 16])
        if is_pb:
            fmt = "apkbuild" if low == "apkbuild" or (low != "pkgbuild" and re.search(
                r"\$pkgname\.(?:pre|post)-|^[ \t]*subpackages=", t[:1 << 16], re.M)) else "pkgbuild"
            m = re.search(r"""(?m)^[ \t]*install=(?:"([^"]*)"|'([^']*)'|(\S*))""", t)
            if m:
                for ref in (m.group(1) or m.group(2) or m.group(3) or "").split():
                    out.append({"format": fmt, "hook": "install", "interpreter": None, "body": ref})
        for m in _PKG_ARCH_FN.finditer(t):
            out.append({"format": "pkgbuild" if is_pb else "arch-install", "hook": m.group(1),
                        "interpreter": "/bin/bash", "body": _pkg_shell_fn(t, m.end()).strip("\n") + "\n"})
    except Exception:  # noqa: BLE001 - truncated / impostor package: keep what was read
        return out
    return out


def _pkg_codecs(raw, name="", budget=1.0):
    """find_codecs-shaped hits from the maintainer scripts of a Linux package, or []. Never raises."""
    try:
        end = time.time() + budget
        rows = [r for r in pkg_scripts(name, raw) if isinstance(r.get("body"), str) and r["body"].strip()]
        for r in rows:
            for c in _find_codecs_text(r["body"]):
                if c.get("plain"):
                    return [dict(c, id=f"{c['id']}@{r['format']}:{r['hook']}")]
        for r in rows:
            if time.time() > end:
                break
            for c in find_codecs(r["body"], 2):
                if c.get("plain"):
                    return [dict(c, id=f"{c['id']}@{r['format']}:{r['hook']}")]
    except Exception:  # noqa: BLE001
        return []
    return []


def _pkg_decode(material, transform=None, key=None):
    """decode() route for rep deb / rpm / apk / pkg_scripts / maintainer_scripts: the material is the package (base64,
    hex, latin-1 bytes or the text itself). transform '' / plan -> the plan of its first plan-bearing script (key = a
    hook filter); hooks -> `hook,hook`; interpreter -> the key hook's (or first script's) interpreter. None if none."""
    try:
        m = (material or "").strip()
        tr = re.sub(r"[^a-z]", "", (transform or "").lower())
        k = (key or "").strip().lstrip("%").lower()
        for b in (b64(m), hex_bytes(m) if re.fullmatch(r"[0-9a-fA-F\s]+", m) else None,
                  m.encode("latin-1") if max(m or "\0") < "Ā" else m.encode("utf-8")):
            rows = pkg_scripts("", b) if b else []
            if not rows:
                continue
            sel = [r for r in rows if not k or r["hook"].lstrip("%").lower() == k] or ([] if k else rows)
            if tr in ("hooks", "hook", "hooklist"):
                return ",".join(r["hook"] for r in rows)
            if tr in ("interpreter", "interp", "prog"):
                return next((r["interpreter"] for r in sel if r.get("interpreter")), None)
            if tr in ("format", "type"):
                return rows[0]["format"]
            for r in sel:
                if isinstance(r.get("body"), str) and r["body"].strip():
                    for c in find_codecs(r["body"], 1):
                        if c.get("plain"):
                            return c["plain"]
            return None
    except Exception:  # noqa: BLE001
        return None
    return None


# ------------------------------------------------------------------------------------------------ build-manifest hooks
# Target build-manifest-hooks (supply-chain sibling of the Jenkins / CI hosts): a package or build manifest runs a
# command at install / build / test / import time -- npm `package.json` lifecycle scripts (json_scripts), node-gyp
# `binding.gyp` actions, setup.py `cmdclass={'install': ..}` / pyproject `[tool.setuptools.cmdclass]`, `.pth` `import`
# lines, gemspec `extensions` + extconf.rb, Rust build.rs `Command::new`, Go `//go:generate`, Maven exec-maven-plugin
# `<executable>` + `<arguments><argument>` / antrun `<exec><arg value=>`, Gradle `commandLine` / `exec {}`, MSBuild
# `<Target BeforeTargets=..><Exec Command=..>`, NuGet tools/install.ps1, CMake `execute_process` / `add_custom_command`.
# hooks() lists them; _hook_codecs() reads the argv a manifest splits over XML elements (a pom `<argument>` list is bare
# element text no literal reader joins) and is consulted only when nothing else read a plan.

_HK_CUE = re.compile(r"<argument>|<executable>|<commandlineArgs>|cmdclass|go:generate|execute_process|"
                     r"add_custom_command|Command::new|commandLine|<Exec\b|<exec\b|extconf|\.extensions\b|\"action\"|"
                     r"'action'|^import[ \t]", re.I | re.M)
_HK_WHEN = {"preinstall": "install", "install": "install", "postinstall": "install", "prepare": "install",
            "preuninstall": "install", "uninstall": "install", "postuninstall": "install", "test": "test",
            "pretest": "test", "posttest": "test", "develop": "install", "egg_info": "install", "bdist_wheel": "build",
            "build_py": "build", "build_ext": "build", "build": "build", "sdist": "build"}
_HK_SUB = {"powershell": "T1059.001", "applescript": "T1059.002", "batch": "T1059.003", "bash": "T1059.004",
           "vbscript": "T1059.005", "python": "T1059.006", "javascript": "T1059.007"}
_HK_DEP = ("npm", "node-gyp", "setuptools", "pth", "gem", "cargo", "go", "nuget")   # dependency manager -> .001


def _hk_xml_text(s):
    import html
    return html.unescape(re.sub(r"<!\[CDATA\[(.*?)\]\]>", r"\1", s or "", flags=re.S)).strip()


def _hk_join(argv):
    return " ".join(a if a and not re.search(r"\s", a) or '"' in a else f'"{a}"' for a in argv if a)


def _hk_strs(body, limit=256):
    """Quoted string literals of a call / list body, in order ('..', "..", Rust r#".."#)."""
    out = []
    for m in re.finditer(r'r(#*)"(.*?)"\1|"((?:[^"\\\n]|\\.)*)"|\'((?:[^\'\\\n]|\\.)*)\'', body or "", re.S):
        v = m.group(2) if m.group(2) is not None else (m.group(3) if m.group(3) is not None else m.group(4))
        if m.group(2) is None:
            v = re.sub(r"\\(.)", lambda e: {"n": "\n", "t": "\t"}.get(e.group(1), e.group(1)), v)
        out.append(v)
        if len(out) >= limit:
            break
    return out


def _hk_call_bodies(src, head, limit=64):
    """Bodies of `head(...)` calls (balanced parentheses, quotes skipped)."""
    out = []
    for m in re.finditer(head, src):
        i, d, q, j = m.end(), 1, None, m.end()
        while j < len(src) and j - i < (1 << 18):
            ch = src[j]
            if q:
                if ch == "\\":
                    j += 1
                elif ch == q:
                    q = None
            elif ch in "\"'":
                q = ch
            elif ch in "([{":
                d += 1
            elif ch in ")]}":
                d -= 1
                if d == 0:
                    break
            j += 1
        out.append(src[i:j])
        if len(out) >= limit:
            break
    return out


def hooks(name, src):
    """Install / build / test / import-time hooks of a package or build manifest -> [{hook, when, command, lang,
    host, attack}] (`attack` = T1195.001 dependency / T1195.002 build supply chain + T1059.x of the command's
    language). [] when it is none. `src` = text or bytes. Never raises."""
    out = []
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)[:4 << 20]
            src = (_utf16(b) or b).decode("utf-8", "ignore") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else \
                b.decode("utf-8", "ignore")
        src = (src or "")[:1 << 20].lstrip("﻿")
        nm = (name or "").replace("\\", "/").lower()
        base = nm.rsplit("/", 1)[-1]

        def add(hook, when, argv, host, lang=None):
            cmd = argv if isinstance(argv, str) else _hk_join(argv)
            if cmd and cmd.strip():
                out.append({"hook": hook, "when": when, "command": cmd.strip(), "lang": lang or _jc_lang(cmd),
                            "host": host})

        head = src.lstrip()[:1]
        if head in "{[" and (base in ("package.json", "binding.gyp") or base.endswith((".gyp", ".gypi")) or
                             re.search(r'["\'](?:scripts|targets|actions)["\']\s*:', src[:1 << 16])):
            for d in json_scripts(name, src):
                m = re.search(r"\.scripts\.([\w:.-]+)$", d["path"])
                if m:
                    k = m.group(1)
                    add(k, _HK_WHEN.get(k, _HK_WHEN.get(re.sub(r"^(?:pre|post)", "", k), "build")), d["text"], "npm",
                        d["lang"] or "bash")
            for body in _hk_call_bodies(src, r"""["']action["']\s*:\s*\["""):      # gyp: JSON or Python literal
                add("action", "install", _hk_strs(body), "node-gyp")
        if re.search(r"<project\b|<Project\b|<target\b", src[:1 << 16]):        # Maven / Ant / MSBuild XML
            for m in re.finditer(r"(?s)<execution\b.*?</execution>|<plugin\b(?:(?!<execution\b).)*?</plugin>", src):
                blk = m.group(0)
                ex = re.search(r"(?s)<executable>(.*?)</executable>", blk)
                if not ex:
                    continue
                argv = [_hk_xml_text(ex.group(1))]
                argv += [_hk_xml_text(a) for a in re.findall(r"(?s)<argument>(.*?)</argument>", blk)[:256]]
                cl = re.search(r"(?s)<commandlineArgs>(.*?)</commandlineArgs>", blk)
                if cl:
                    argv.append(_hk_xml_text(cl.group(1)))
                ph = re.search(r"<phase>\s*([\w-]+)\s*</phase>", blk)
                ph = ph.group(1) if ph else "build"
                add("exec-maven-plugin:" + ph, "test" if "test" in ph else ("install" if ph in ("install", "deploy")
                                                                             else "build"), argv, "maven")
            for m in re.finditer(r"(?s)<exec\b([^>]*?)(/>|>(.*?)</exec>)", src):
                ex = re.search(r"""\bexecutable\s*=\s*(["'])(.*?)\1""", m.group(1), re.S)
                if not ex:
                    continue
                argv = [_hk_xml_text(ex.group(2))]
                for a in re.finditer(r"""<arg\b[^>]*?\b(value|line)\s*=\s*(["'])(.*?)\2""", m.group(3) or "", re.S):
                    argv.append(_hk_xml_text(a.group(3)))
                add("antrun:exec", "build", argv, "maven" if "<artifactId>maven-antrun" in src else "ant")
            for m in re.finditer(r"(?s)<Target\b([^>]*)>(.*?)</Target>", src):
                at = re.search(r"""\b(BeforeTargets|AfterTargets)\s*=\s*(["'])(.*?)\2""", m.group(1))
                tn = re.search(r"""\bName\s*=\s*(["'])(.*?)\1""", m.group(1))
                for e in re.finditer(r"""<Exec\b[^>]*?\bCommand\s*=\s*(["'])(.*?)\1""", m.group(2), re.S):
                    hook = (tn.group(2) if tn else "Target") + (f":{at.group(1)}={at.group(3)}" if at else "")
                    add(hook, "test" if at and "test" in at.group(3).lower() else "build", _hk_xml_text(e.group(2)),
                        "msbuild")
        if base.endswith(".pth"):
            for ln in src.splitlines()[:4096]:
                if re.match(r"import[ \t]", ln):
                    add("pth:import", "import", ln, "pth", "python")
        if base == "setup.py" or re.search(r"\bcmdclass\s*=", src[:1 << 18]):
            cm = re.search(r"cmdclass\s*=\s*(?:dict\s*\(|\{)(.*?)[})]", src, re.S)
            pairs = re.findall(r"""["']?(\w+)["']?\s*[:=]\s*([\w.]+)""", cm.group(1)) if cm else []
            for k, cls in pairs[:32]:
                c = re.search(rf"(?ms)^class[ \t]+{re.escape(cls.rsplit('.', 1)[-1])}\b.*?(?=^\S|\Z)", src)
                body = c.group(0) if c else ""
                calls = [_hk_strs(b) for b in _hk_call_bodies(
                    body, r"\b(?:subprocess\.(?:call|run|Popen|check_call|check_output)|os\.(?:system|popen))\s*\(")]
                for argv in calls or [[cls]]:
                    add(f"cmdclass:{k}", _HK_WHEN.get(k, "install"), argv, "setuptools", None if calls else "python")
        if base == "pyproject.toml" or "[tool.setuptools" in src[:1 << 16]:
            m = re.search(r"(?ms)^\[tool\.setuptools\.cmdclass\][ \t]*\n(.*?)(?=^\[|\Z)", src)
            for k, v in re.findall(r"""(?m)^[ \t]*["']?(\w+)["']?[ \t]*=[ \t]*["']([^"'\n]+)["']""",
                                   m.group(1) if m else ""):
                add(f"cmdclass:{k}", _HK_WHEN.get(k, "install"), v, "setuptools", "python")
        if base.endswith(".gemspec") or re.search(r"\.extensions\s*=", src[:1 << 16]):
            for m in re.finditer(r"\.extensions\s*=\s*(?:%w[\[(](.*?)[\])]|\[(.*?)\]|([\"'][^\"']+[\"']))", src, re.S):
                for e in (m.group(1) or "").split() + _hk_strs(m.group(2) or m.group(3) or ""):
                    add("gemspec:extensions", "install", e, "gem", "ruby")
        if base == "extconf.rb" or "mkmf" in src[:4096]:
            for b in _hk_call_bodies(src, r"(?<![\w.])(?:system|exec|spawn|IO\.popen|Open3\.\w+)\s*\("):
                add("extconf.rb", "install", _hk_strs(b), "gem")
            for m in re.finditer(r"`([^`\n]+)`|%x\{([^}\n]+)\}", src):
                add("extconf.rb", "install", m.group(1) or m.group(2), "gem")
        if base == "build.rs" or "Command::new" in src:
            for m in re.finditer(r"Command::new\s*\(", src):
                tail = src[m.end():m.end() + 8192]
                end = re.search(r"\.(?:status|output|spawn)\s*\(|;", tail)
                chain = tail[:end.start() if end else len(tail)]
                add("build.rs", "build", _hk_strs(chain), "cargo")
        for m in re.finditer(r"(?m)^//go:generate[ \t]+(.+)$", src):
            add("go:generate", "build", m.group(1), "go")
        if base.endswith((".gradle", ".gradle.kts")) or re.search(r"\bcommandLine\b|type\s*:\s*Exec\b", src[:1 << 16]):
            for m in re.finditer(r"\bcommandLine\b\s*\(?([^\n]*(?:\n[ \t]*[,'\"][^\n]*)*)", src):
                argv = _hk_strs(m.group(1))
                add("gradle:exec", "build", argv, "gradle")
        for b in _hk_call_bodies(src, r"(?i)\b(?:execute_process|add_custom_command|add_custom_target)\s*\("):
            mm = re.search(r"(?s)\bCOMMAND\b(.*?)(?=\b(?:COMMAND|WORKING_DIRECTORY|OUTPUT_VARIABLE|RESULT_VARIABLE|"
                           r"OUTPUT|DEPENDS|COMMENT|VERBATIM)\b|\Z)", b)
            if mm:
                argv = _hk_strs(mm.group(1)) or mm.group(1).split()
                add("cmake:COMMAND", "build", argv, "cmake")
        if re.search(r"(?:^|/)tools/(?:install|init|uninstall)\.ps1$", nm) or base in ("install.ps1", "init.ps1"):
            add("nuget:" + base, "install", src, "nuget", "powershell")
        for d in out:
            lang = d["lang"] or ""
            d["attack"] = ["T1195.001" if d["host"] in _HK_DEP else "T1195.002"] + \
                ([_HK_SUB[lang]] if lang in _HK_SUB else [])
        return out[:512]
    except Exception:  # noqa: BLE001 - truncated / impostor: what was read so far
        return out[:512]


def _hk_argv_xml(src):
    """Commands a Maven / Ant XML splits over `<executable>` + `<argument>` / `<arg value=>` elements."""
    return [d for d in hooks("pom.xml", src) if d["host"] in ("maven", "ant")]


def _hook_codecs(src, depth=0, budget=0.4):
    """find_codecs readings of a manifest hook's argv (joined command first, then each long argument)."""
    try:
        end = time.time() + budget
        for d in _hk_argv_xml(src)[:64]:
            for t in [d["command"]] + [a for a in re.split(r'\s+(?=(?:[^"]*"[^"]*")*[^"]*$)', d["command"])
                                       if len(a) >= 16]:
                if time.time() > end:
                    return []
                t = t.strip('"')
                if t == src:
                    continue
                hit = next((c for c in find_codecs(t, depth + 1)[:8] if c.get("plain")), None)
                if hit:
                    return [dict(hit, id=f"{hit.get('id')}@hook:{d['hook']}")]
    except Exception:  # noqa: BLE001
        return []
    return []


# ------------------------------------------------------------------------------------------------ encode (inverse)
# For synthetic "family" regression cases (hctf/family.py): re-encode a fixture's plaintext under ANOTHER known
# rep x transform, so a solver that decodes codecs by name/table instead of through decode() fails offline instead of
# on the next timed variant (rehearsal Day 7 replay: a second TT generalize for one more member of the same codec family).
# The written FORMAT of a rep is copied from a real material `sample` of that rep (separators, 0x prefix, case,
# brackets); every result is verified by decode() and None is returned if it doesn't round-trip.

def _encode_transform(p, transform, key):
    t, inline = _base_transform(transform)
    k = key_bytes(inline if inline is not None else key)
    k1 = k[0] if k else None
    if t == "identity":
        return p
    if t in ("reverse", "reverse_bytes"):
        return p[::-1]
    if t.startswith("xor_") or t in ("single_byte_xor", "repeating_key_xor"):
        return _xor(p, k) if k else None
    if t.startswith("add_"):
        return bytes((x + k1) % 256 for x in p) if k1 is not None else None
    if t.startswith(("sub_", "subtract_")):
        return bytes((x - k1) % 256 for x in p) if k1 is not None else None
    if t in ("reverse_then_xor", "reverse_xor"):
        return _xor(p, k or b"\x5a")[::-1]
    if t == "rolling_xor":
        if k1 is None:
            return None
        out, prev = bytearray(), k1
        for x in p:
            c = x ^ prev
            out.append(c)
            prev = c
        return bytes(out)
    if t in ("rotate_left", "rol"):
        n = int(inline, 16) % 8 if inline else (k1 % 8 if k1 else 0)
        return bytes(((x << n) | (x >> (8 - n))) & 0xFF for x in p) if n else None
    return None


def _format_like(data, rep, sample):
    """Write `data` the way `sample` (a real material of `rep`) is written."""
    if rep.startswith(("hex_base64", "hex_b64")):   # hex digits of the base64 text (D8 v=3 HB64), case like the sample
        s = base64.b64encode(data).hex()
        return s.upper() if sample and re.search(r"[A-F]", sample) and not re.search(r"[a-f]", sample) else s
    if "base64" in rep:
        s = base64.b64encode(data).decode()
        if "urlsafe" in rep or (sample and re.search(r"[-_]", sample) and not re.search(r"[+/]", sample)):
            s = base64.urlsafe_b64encode(data).decode()
        if sample and not sample.rstrip().endswith("=") and not rep.startswith("reversed"):
            s = s.rstrip("=")
        return s[::-1] if rep.startswith("reversed") else s
    if rep == "percent_hex":
        return "".join(f"%{b:02x}" for b in data)
    if not sample:
        return None
    if rep.startswith("octal"):
        tok, radix = re.compile(r"[0-7]+"), 8
    elif "hex" in rep:
        tok, radix = re.compile(r"(?:0[xX]|\\x|&[hH])?[0-9a-fA-F]{2}"), 16
    elif rep.startswith(("decimal", "integer", "json_num", "reversed_decimal", "reversed_integer")):
        tok, radix = re.compile(r"\d+"), 10
    else:
        return None
    toks = list(tok.finditer(sample))
    if len(toks) < 2:
        return None
    pre, sep, suf = sample[:toks[0].start()], sample[toks[0].end():toks[1].start()], sample[toks[-1].end():]
    t0 = toks[0].group(0)
    prefix = re.match(r"0[xX]|\\x|&[hH]", t0)
    prefix = prefix.group(0) if prefix else ""
    upper = any(c in "ABCDEF" for m in toks for c in m.group(0)[len(prefix):])
    width = len(t0) - len(prefix) if (radix != 10 or t0.startswith("0")) else 0
    vals = list(data[::-1] if rep.startswith(("reversed_decimal", "reversed_integer", "reversed_hex")) else data)
    if radix == 16:
        body = [f"{v:0{max(2, width)}{'X' if upper else 'x'}}" for v in vals]
    elif radix == 8:
        body = [f"{v:0{width}o}" for v in vals]
    else:
        body = [f"{v:0{width}d}" if width else str(v) for v in vals]
    return pre + sep.join(prefix + b for b in body) + suf


def encode(plain, rep, transform, key=None, sample=None):
    """Material text that decode(material, rep, transform, key) turns back into `plain` (bytes or str), or None.
    `sample` = a real material written in `rep` (its format is copied). Only known names; result verified."""
    if isinstance(plain, str):
        plain = plain.encode("utf-8")
    if not known(rep, None):
        return None
    t, k = _spec(rep, transform, key)
    if not known(None, t):
        return None
    data = _encode_transform(plain, t, k)
    if data is None:
        return None
    mat = _format_like(data, rep, sample)
    if not mat:
        return None
    try:
        back = decode(mat, rep, transform, key)
    except Exception:  # noqa: BLE001
        back = None
    return mat if back == plain.decode("utf-8", "replace").lstrip("﻿") else None


# ------------------------------------------------------------------------------------------------ decode call chains
# Target php-eval-chain: `@eval(gzinflate(base64_decode(str_rot13('..'))))` onions (PHP webshells) and the same shape in
# Ruby (`eval(Zlib::Inflate.inflate('..'.unpack1('m')))`, `[".."].pack('H*')`), Python (`exec(zlib.decompress(
# base64.b64decode(b'..')))`, `codecs.decode(x,'rot13')`, `[::-1]`) and Perl (`eval uncompress decode_base64 '..'`,
# `pack('H*', ..)`, `scalar reverse`). A tiny expression parser (calls, paren-less known calls, method/postfix chains,
# literal concatenation, `$var`/name assignments) evaluates each NAMED decoder innermost-first; wrappers it does not
# know (eval/exec/assert/print...) pass their first argument through. A decoded layer that is code again is re-read
# (up to 4 levels); the result must be a plan (looks_like_plan, else peel_plan). Only consulted when nothing else
# produced a plan, so every earlier reading is unchanged. Bounded (budget seconds, node count), never raises.
# Target python-onion-regex-fold adds Python's module indirection (`__import__('zlib').decompress(..)`,
# `getattr(__import__('base64'),'b85decode')(..)`) and pyobfuscate-style `_ = lambda __: ..(__[::-1]); exec((_)(b'..'))`
# (the body is evaluated with the parameter bound). `marshal.loads` stops the fold: the code object is not unmarshalled,
# only a plan string constant whose marshal length field matches it exactly is reported (rep "marshal").
_CH_B64 = {"base64_decode", "b64decode", "standard_b64decode", "urlsafe_b64decode", "decode64", "decode_base64",
           "urlsafe_decode64", "strict_decode64", "decodebase64", "frombase64string", "atob", "a2b_base64",
           "decodebytes", "decodestring", "base64decode", "mime_base64_decode"}
_CH_INFL = {"gzinflate", "gzuncompress", "gzdecode", "zlib_decode", "inflate", "decompress", "uncompress",
            "memgunzip", "gunzip", "inflateraw", "inflatesync", "gunzipsync", "inflaterawsync", "unzip",
            "zlib_decompress", "bz2_decompress", "bzdecompress", "lzma_decompress", "memgunzip_s"}
_CH_HEX = {"hex2bin", "unhexlify", "fromhex", "a2b_hex", "hex_decode", "hexdecode", "b16decode"}
_CH_URL = {"urldecode", "rawurldecode", "unquote", "unquote_plus", "unquote_to_bytes", "decodeuricomponent",
           "unescape", "decode_www_form_component", "uri_unescape", "url_decode"}
_CH_ALL = (_CH_B64 | _CH_INFL | _CH_HEX | _CH_URL |
           {"str_rot13", "rot13", "strrev", "reverse", "convert_uudecode", "a2b_uu", "uudecode", "b32decode",
            "base32_decode", "b85decode", "a85decode", "quoted_printable_decode", "pack", "unpack", "unpack1",
            "decode", "tr", "eval", "assert", "exec", "create_function", "instance_eval", "class_eval",
            "module_eval", "preg_replace", "system", "compile"})
_CH_START = re.compile(r"(?<![\w$>.:\\])[@\\]*(?:[A-Za-z_][\w]*(?:(?:::|\.|->|\\)[A-Za-z_]\w*)*)(?=\s*[(\s'\"$\[])")
_CH_QOP = re.compile(r"(qq|q|%[qQ]|%)\s*([{(\[<|/!])")
_CH_PAIR = {"{": "}", "(": ")", "[": "]", "<": ">"}
_CH_LIT_PLAN = re.compile(r"""(["'])((?:v=\d+\||\{)[^\n]{8,}?)\1|\b(?:qq?|%[qQ]?)\s*\{((?:v=\d+\||\{)[^\n]{8,}?)\}""")
_CH_DQ_ESC = {"n": "\n", "r": "\r", "t": "\t", "0": "\0", "e": "\x1b", "f": "\f", "v": "\v", "a": "\a", "b": "\b"}


def _ch_unescape(body, q):
    if "\\" not in body:
        return body
    if q == "'":
        return re.sub(r"\\([\\'])", r"\1", body)

    def sub(m):
        s = m.group(1)
        if s[0] in "xX":
            return chr(int(s[1:], 16))
        if s[0] == "u":
            return chr(int(s[1:].strip("{}"), 16))
        if s[0] in "01234567":
            return chr(int(s, 8) & 0xFF)
        return _CH_DQ_ESC.get(s, s)
    return re.sub(r"\\(x[0-9a-fA-F]{1,2}|u\{[0-9a-fA-F]{1,6}\}|u[0-9a-fA-F]{4}|[0-7]{1,3}|.)", sub, body, flags=re.S)


def _ch_uu(b):
    out = bytearray()
    for line in b.split(b"\n"):
        line = line.rstrip(b"\r")
        if not line or line.startswith((b"begin ", b"end")):
            continue
        try:
            out += binascii.a2b_uu(line)
        except binascii.Error:
            try:                                         # lenient: trailing garbage on a short final line
                n = (line[0] - 32) & 63
                out += binascii.a2b_uu(line[:1 + (n + 2) // 3 * 4])
            except (binascii.Error, IndexError):
                return None
    return bytes(out) or None


_CH_LAMBDA = r"(?:^|[;\n])[ \t]*{}[ \t]*=[ \t]*lambda[ \t]*([A-Za-z_]\w*)?[ \t]*:"
_CH_IMPORT = ("__import__", "import_module")


class _Chain:
    def __init__(self, src, end, depth=0, env=None):
        self.s, self.end, self.depth, self.nodes = src, end, depth, 0
        self.env, self.marshal = env or {}, None

    # -- lexing helpers
    def ws(self, i):
        s = self.s
        while i < len(s):
            if s[i] in " \t\r\n":
                i += 1
            elif s.startswith("\\\n", i):
                i += 2
            else:
                break
        return i

    def literal(self, i):
        """(text, j) for a quoted literal at i (b/r/u prefixes, PHP/Python/Ruby/Perl quoting), else None."""
        s = self.s
        pm = _CH_QOP.match(s, i)
        if pm:                                            # Perl q{..} / qq{..}, Ruby %q{..} / %Q{..}
            close = _CH_PAIR.get(pm.group(2), pm.group(2))
            j = s.find(close, pm.end())
            if j < 0:
                return None
            body = s[pm.end():j]
            return (body if pm.group(1).lower() in ("q", "%q") else _ch_unescape(body, '"')), j + 1
        m = re.compile(r"""[bBrRuUfF]{0,2}(\"\"\"|'''|"|')""").match(s, i)
        if not m:
            return None
        q, raw = m.group(1), "r" in m.group(0).lower()
        j, body = m.end(), []
        while j < len(s):
            if s.startswith(q, j):
                t = "".join(body)
                return (t if raw else _ch_unescape(t, q[0] if len(q) == 1 or q[0] == "'" else '"')), j + len(q)
            if s[j] == "\\" and j + 1 < len(s):
                body.append(s[j:j + 2])
                j += 2
                continue
            body.append(s[j])
            j += 1
        return None

    # -- expression parser: returns (value, j); value = bytes | list | ("name", qualified) | None
    def expr(self, i, lvl=0):
        self.nodes += 1
        if lvl > 40 or self.nodes > 4000 or time.time() > self.end:
            raise ValueError("budget")
        v, i = self.postfix(*self.primary(i, lvl), lvl)
        while True:
            j = self.ws(i)
            m = re.compile(r"\.\.|\.(?![\w(])|\+(?!\+)").match(self.s, j)
            if not m and j < len(self.s) and self.s[j] in "'\"" and isinstance(v, bytes):
                m2 = self.literal(j)                       # Python implicit 'a' 'b' concatenation
                if m2:
                    v, i = v + m2[0].encode("latin-1", "ignore"), m2[1]
                    continue
            if not m:
                return v, i
            w, k = self.postfix(*self.primary(self.ws(m.end()), lvl + 1), lvl + 1)
            if not (isinstance(v, bytes) and isinstance(w, bytes)):
                return v, i
            v, i = v + w, k

    def primary(self, i, lvl):
        s = self.s
        i = self.ws(i)
        while i < len(s) and s[i] in "@\\":
            i += 1
        if i >= len(s):
            return None, i
        lit = self.literal(i)
        if lit:
            return lit[0].encode("latin-1", "ignore") if max(map(ord, lit[0] or "\0")) < 256 \
                else lit[0].encode("utf-8"), lit[1]
        if s[i] == "(":
            v, j = self.expr(i + 1, lvl + 1)
            j = self.ws(j)
            return v, (j + 1 if j < len(s) and s[j] == ")" else j)
        if s[i] == "[":
            items, j = self.args(i + 1, "]", lvl)
            return items, j
        m = re.compile(r"\$?[A-Za-z_]\w*(?:(?:::|\.|->|\\)[A-Za-z_]\w*)*").match(s, i)
        if not m:
            return None, i
        name, j = m.group(0), m.end()
        parts = re.split(r"::|\.|->|\\", name)
        head = self.var(parts[0], i)
        if head is not None:                              # `x.decode('hex')`: a value with method calls
            v = head
            for p in parts[1:-1]:
                v = self.apply(p, [v])
            if len(parts) == 1:
                return v, j
            k = self.ws(j)
            if k < len(s) and s[k] == "(":
                a, j = self.args(k + 1, ")", lvl)
                return self.apply(parts[-1], [v] + a), j
            return self.apply(parts[-1], [v]), j
        k = self.ws(j)
        last = parts[-1].lower()
        if k < len(s) and s[k] == "(":
            a, j = self.args(k + 1, ")", lvl)
            if last in _CH_IMPORT and a and isinstance(a[0], bytes):   # Python __import__('zlib')
                return ("mod", a[0].decode("latin-1")), j
            if last == "getattr" and len(a) >= 2 and isinstance(a[1], bytes) and isinstance(a[0], tuple):
                return ("fn", f"{a[0][1]}.{a[1].decode('latin-1')}"), j
            return self.call(("name", name), a, i), j
        if last in _CH_ALL and k > j and k < len(s) and (s[k] in "'\"$@[(" or s[k].isalpha()):
            v, j = self.expr(k, lvl + 1)                  # Ruby/Perl paren-less call `decode64 x` / `scalar reverse`
            return self.apply(last, [v], name), j
        if last in ("scalar", "my", "our", "local", "return", "print", "echo", "puts", "do", "eval"):
            return self.expr(k, lvl + 1)
        return ("name", name), j

    def args(self, i, close, lvl):
        out, s = [], self.s
        i = self.ws(i)
        if i < len(s) and s[i] == close:
            return out, i + 1
        while i < len(s):
            v, i = self.expr(i, lvl + 1)
            out.append(v)
            i = self.ws(i)
            if i < len(s) and s[i] == ",":
                i = self.ws(i + 1)
                if i < len(s) and s[i] == close:
                    return out, i + 1
                continue
            if i < len(s) and s[i] == close:
                return out, i + 1
            if i < len(s) and s[i] == ":" and close == "]":   # slice [::-1]
                m = re.compile(r"[\s:]*(-?\d*)\s*\]").match(s, i)
                if m:
                    out = [("slice", s[i:m.end()])] if not out or out == [None] else out + [("slice", s[i:m.end()])]
                    return out, m.end()
            if i < len(s) and s[i] == ":":
                m = re.compile(r":\s*:\s*-1\s*\]").match(s, i)
                if m:
                    return out + [("slice", "::-1")], m.end()
            return out, i
        return out, i

    def postfix(self, v, i, lvl):
        s = self.s
        while True:
            j = self.ws(i)
            if s.startswith("[", j):
                m = re.compile(r"\[\s*:\s*:\s*-1\s*\]|\[\s*(-?\d+)\s*\]").match(s, j)
                if not m:
                    return v, i
                if m.group(1) is None:
                    v = v[::-1] if isinstance(v, (bytes, list)) else v
                elif isinstance(v, list):
                    try:
                        v = v[int(m.group(1))]
                    except IndexError:
                        v = None
                i = m.end()
                continue
            if s.startswith("(", j) and isinstance(v, tuple) and v[0] in ("name", "fn"):
                a, i = self.args(j + 1, ")", lvl)         # `(_)(b'..')`, `getattr(m, 'f')(..)`
                v = self.call(v, a, j)
                continue
            m = re.compile(r"(?:\.|->|&\.)\s*([A-Za-z_]\w*[!?]?)").match(s, j)
            if not m or (isinstance(v, bytes) and s[j] == "." and j > i):
                return v, i
            name, k = m.group(1).rstrip("!?"), self.ws(m.end())
            if k < len(s) and s[k] == "(":
                a, i = self.args(k + 1, ")", lvl)
            else:
                a, i = [], m.end()
            if isinstance(v, tuple) and v[0] == "mod":    # __import__('base64').b64decode(..)
                q = f"{v[1]}.{name}"
                v = self.apply(name, a, q) if k < len(s) and s[k] == "(" else ("fn", q)
                continue
            v = self.apply(name, [v] + a)

    def call(self, f, a, at):
        """Call a function value: a Python `NAME = lambda P: BODY` bound before `at` (BODY evaluated with P = the first
        argument), else the named decoder."""
        name = f[1]
        if f[0] == "name" and name.lower() not in _CH_ALL and self.depth <= 3 and re.fullmatch(r"\w+", name):
            hit = None
            for hit in re.finditer(_CH_LAMBDA.format(re.escape(name)), self.s[:at]):
                pass
            if hit:
                sub = _Chain(self.s, self.end, self.depth + 1, {hit.group(1): a[0]} if hit.group(1) and a else {})
                sub.nodes = self.nodes
                v, _ = sub.expr(hit.end())
                self.nodes, self.marshal = sub.nodes, sub.marshal or self.marshal
                return v
        return self.apply(name.rsplit(".", 1)[-1], a, name)

    def var(self, name, at):
        """The value last assigned to `name` before offset `at` (`$x = ..;`, `x = ..`, `my $x = ..`), else None."""
        if name in self.env:
            return self.env[name]
        if name.lower() in _CH_ALL or self.depth > 3:
            return None
        bare = name.lstrip("$")
        pat = re.compile(r"(?:^|[;\n{(])\s*(?:(?:my|our|local|var|let|const)\s+)?\$?" + re.escape(bare) +
                         r"\s*(?:\.=|=)(?![=~>])")
        hit = None
        for m in pat.finditer(self.s, 0, at):
            hit = m
        if not hit:
            return None
        sub = _Chain(self.s, self.end, self.depth + 1)
        sub.nodes = self.nodes
        try:
            v, _ = sub.expr(hit.end())
        except ValueError:
            return None
        self.nodes = sub.nodes
        return v if isinstance(v, (bytes, list)) else None

    # -- evaluation
    def apply(self, name, a, qual=""):
        n = (name or "").lower()
        qual = (qual or "").lower()
        v = next((x for x in a if isinstance(x, (bytes, list))), None)
        sargs = [x.decode("latin-1") for x in a[1:] if isinstance(x, bytes)] if a else []
        if n == "pack":
            fmt = next((x for x in a if isinstance(x, bytes) and re.fullmatch(rb"[A-Za-z]\*?\d*", x)), None)
            data = next((x for x in (a[1:] if a and a[0] is fmt else a) if x is not fmt), None)
            if isinstance(data, list):                    # Ruby ["..."].pack('H*')
                data = data[0] if data and isinstance(data[0], bytes) else None
            if fmt is None and len(a) >= 2 and isinstance(a[0], list):
                data, fmt = (a[0][0] if a[0] and isinstance(a[0][0], bytes) else None), a[1]
            f = (fmt or b"").decode("latin-1")[:1]
            if not isinstance(data, bytes):
                return None
            return hex_bytes(data.decode("latin-1")) if f == "H" else (b64(data.decode("latin-1")) if f == "m"
                                                                      else _ch_uu(data) if f == "u" else None)
        if n in ("unpack", "unpack1"):
            fmt = next((x for x in a[1:] if isinstance(x, bytes)), None) if len(a) > 1 else None
            data = a[0] if a else None
            if isinstance(fmt, bytes) and isinstance(data, bytes) and re.fullmatch(rb"[A-Za-z]\*?\d*", data) \
                    and not re.fullmatch(rb"[A-Za-z]\*?\d*", fmt):
                fmt, data = data, fmt                     # Perl unpack('u', $x)
            if not isinstance(data, bytes) or not isinstance(fmt, bytes):
                return None
            f = fmt.decode("latin-1")[:1]
            r = b64(data.decode("latin-1")) if f == "m" else _ch_uu(data) if f == "u" else None
            return r if n == "unpack1" or r is None else [r]
        if isinstance(v, list):
            v = v[0] if v and isinstance(v[0], bytes) else None
        if not isinstance(v, bytes):
            return None if n in _CH_ALL else v
        if n == "loads" and "marshal" in qual:           # code object: stop here, keep the blob (report only)
            self.marshal = v
            return None
        t = v.decode("latin-1")
        if n == "decode" and sargs:                       # Python codecs.decode(x, 'rot13') / x.decode('base64')
            c = sargs[0].lower().replace("-", "_")
            n = {"rot13": "rot13", "rot_13": "rot13", "base64": "b64decode", "base_64": "b64decode",
                 "hex": "unhexlify", "zlib": "decompress", "zip": "decompress", "bz2": "decompress",
                 "uu": "a2b_uu", "quopri": "quoted_printable_decode"}.get(c, "identity")
        if n in _CH_B64:
            return b64(t)
        if n in _CH_INFL or (n == "new" and "gzip" in qual):
            return _inflate(v)
        if n in _CH_HEX:
            return hex_bytes(t)
        if n in _CH_URL:
            from urllib.parse import unquote_to_bytes
            return unquote_to_bytes(t.replace("+", " ") if n in ("urldecode", "unquote_plus",
                                                                  "decode_www_form_component") else t)
        if n in ("str_rot13", "rot13"):
            return t.translate(_ROT13_S).encode("latin-1")
        if n == "tr" and len(sargs) >= 2 and sargs[0].replace(" ", "") in ("A-Za-z", "a-zA-Z") and \
                sargs[1].replace(" ", "") in ("N-ZA-Mn-za-m", "n-za-mN-ZA-M"):
            return t.translate(_ROT13_S).encode("latin-1")
        if n in ("strrev", "reverse"):
            return v[::-1]
        if n in ("convert_uudecode", "a2b_uu", "uudecode"):
            return _ch_uu(v)
        if n in ("b32decode", "base32_decode"):
            s = re.sub(r"\s+", "", t).upper().rstrip("=")
            try:
                return base64.b32decode(s + "=" * (-len(s) % 8))
            except (binascii.Error, ValueError):
                return None
        if n in ("b85decode", "a85decode"):
            try:
                return (base64.b85decode if n == "b85decode" else base64.a85decode)(t.strip())
            except (binascii.Error, ValueError):
                return None
        if n == "quoted_printable_decode":
            import quopri
            return quopri.decodestring(v)
        if n == "create_function":                        # PHP create_function('$a', $code): the body
            return next((x for x in reversed(a) if isinstance(x, bytes)), None)
        return v                                          # eval/exec/assert/print/str()/bytes()/.decode()...


def _marshal_plan(blob):
    """A plan string constant inside a marshal'd code object (`exec(marshal.loads(..))`), read without unmarshalling:
    the literal must sit right after a str/bytes type byte whose length field matches it exactly. Else None."""
    for m in re.finditer(rb"v=\d+\||\{", blob[:1 << 20]):
        st = m.start()
        for hdr, n in ((b"zZ", 1), (b"aAust", 4)):
            if st > n and blob[st - n - 1] & 0x7F in hdr:
                ln = int.from_bytes(blob[st - n:st], "little")
                run = blob[st:st + ln]
                if 8 <= ln == len(run) and looks_like_plan(run):
                    return run.decode("utf-8", "replace")
    return None


def _chain_codecs(src, depth=0, budget=0.4):
    """find_codecs entries read from decode call chains (see the section comment)."""
    _t = time
    try:
        if not src or len(src) > (1 << 18):
            return []
        end = _t.time() + budget
        starts, last = [], -1
        for m in _CH_START.finditer(src):
            nm = re.split(r"::|\.|->|\\", m.group(0).lstrip("@\\"))[-1].lower()
            if nm in _CH_ALL and m.start() >= last:
                starts.append(m.start())
                if len(starts) >= 48:
                    break
        seen = set()
        for st in starts:
            if _t.time() > end:
                break
            ch = _Chain(src, end, 0)
            try:
                v, j = ch.expr(st)
            except (ValueError, RecursionError):
                continue
            if isinstance(v, list):
                v = v[0] if v and isinstance(v[0], bytes) else None
            if v is None and ch.marshal:                  # marshal.loads(..): report the code object's plan constant
                p = _marshal_plan(ch.marshal)
                if p:
                    return [{"id": "callchain", "rep": "marshal", "transform": "identity", "key": "",
                             "material": src[st:j][:400], "plain": p}]
                continue
            if not isinstance(v, bytes) or v in seen or len(v) > (1 << 20):
                continue
            seen.add(v)
            for b in (v, _utf16(v) if b"\x00" in v else None):
                if not b:
                    continue
                b = b.encode("utf-8") if isinstance(b, str) else b
                txt = b.decode("utf-8", "ignore")
                whole = txt.lstrip("\ufeff").strip()
                plain = whole if looks_like_plan(b) and whole[:2] in ("v=", "{") else None
                for lm in ([] if plain else _CH_LIT_PLAN.finditer(txt[:1 << 16])):
                    lit = lm.group(2) or lm.group(3)
                    if looks_like_plan(lit.encode("utf-8")):    # final layer `$plan = 'v=3|..';` / `q{..}`
                        plain = lit
                        break
                if plain or looks_like_plan(b):
                    return [{"id": "callchain", "rep": "callchain", "transform": "identity", "key": "",
                             "material": src[st:j][:400], "plain": plain or whole}]
                if depth < 4 and txt != src:                       # the decoded layer is code again
                    inner = find_codecs(txt, 1) if depth == 0 else []
                    inner = [c for c in inner if c.get("plain")] or _chain_codecs(txt, depth + 1,
                                                                               max(0.05, end - _t.time()))
                    if inner:
                        return [dict(inner[0], id=f"{inner[0]['id']}@chain{depth}")]
                if re.fullmatch(r"[\x20-\x7e\s]{16,}", txt):
                    p = peel_plan(txt.strip(), budget=min(0.15, max(0.02, end - _t.time())))
                    if p:
                        return [{"id": "callchain", "rep": "callchain", "transform": "identity", "key": "",
                                 "material": src[st:j][:400], "plain": p}]
    except Exception:  # noqa: BLE001 - unknown -> nothing, never an exception
        return []
    return []


# ------------------------------------------------------------------------------------------------ equivalence
# Sibling-outlier / semantic-equivalence questions (prebuild equivalence-outlier-compare, 10-16): D8 "doesn't match its
# siblings", D15/D16 "prove which are truly equivalent, expose the variant that quietly changed the plot". D16 polyglot
# families (9 languages x {benign_utility, downloader, launcher, staged_chain}, GM-verified fields): role / attack /
# adapter agree across the family, steps / stage_count / stage_profile / obfuscation rotate through 4 obfuscation
# profiles (the "scrambling"), and exactly one member (php) changes next_language. So the plot outlier is the
# minority on a field that is otherwise near-unanimous, never a field whose values spread across the family.
EQ_KEEP = ("role", "steps", "adapter", "attack", "stage_count", "stage_profile", "next_language", "scenario",
           "nativetypes", "native_types")
EQ_DROP = ("campaign", "campaign_id", "host", "host_id", "url", "file_path", "path", "upload_url", "next_stage",
           "codec", "rep", "transform", "key", "material", "v", "id", "ids", "obfuscation", "obfuscation_profile",
           "host_profile", "wallet", "mutex", "user_agent", "file", "note", "note_name", "extension", "dest")


def _eq_field(k):
    k = re.sub(r"[^0-9a-z]+", "_", str(k).strip().lower()).strip("_")
    return {"campaign": "campaign_id", "host": "host_id", "nativetypes": "native_types"}.get(k, k)


def _eq_value(field, v):
    """Comparison form of one plan value: steps as an ordered tuple, T1059.xxx as T1059 (the interpreter sub-id is the
    host language, not the plot), everything else stripped and case-folded."""
    if v is None:
        return None
    if field == "steps":
        parts = v if isinstance(v, (list, tuple)) else re.split(r"[>,|;\s]+", str(v))
        return tuple(str(p).strip().lower() for p in parts if str(p).strip()) or None
    if isinstance(v, (list, tuple)):
        return tuple(sorted(str(x).strip().casefold() for x in v))
    s = str(v).strip()
    if field == "attack":
        s = re.sub(r"^(T1059)\.\d{3}$", r"\1", s.upper())
    return s.casefold() or None


def _eq_dict(plan):
    """A decoded plan as a dict: dict as is, 'k=v|..' or JSON text / bytes parsed; None otherwise."""
    if isinstance(plan, (bytes, bytearray)):
        plan = bytes(plan).decode("utf-8", "replace")
    if isinstance(plan, str):
        s = plan.strip()
        if s[:1] == "{":
            import json
            plan = json.loads(s)
        else:
            plan = plan_kv(s)
    return plan if isinstance(plan, dict) else None


def plan_canonical(plan, keep=EQ_KEEP, drop=EQ_DROP):
    """{field: comparison value} of one decoded plan (dict, 'k=v|..' text or JSON text); identity fields dropped.
    `keep` None = every field not in `drop`. None when the plan is unreadable or has no comparable field."""
    try:
        plan = _eq_dict(plan)
        if not plan:
            return None
        kset = {_eq_field(k) for k in keep} if keep else None
        dset = {_eq_field(k) for k in drop or ()}
        out = {}
        for k, v in plan.items():
            f = _eq_field(k)
            if f in dset or (kset is not None and f not in kset) or isinstance(v, dict):
                continue
            cv = _eq_value(f, v)
            if cv is not None:
                out.setdefault(f, cv)
        return out or None
    except Exception:  # noqa: BLE001 - a decoy plan compares as nothing
        return None


def equivalence(plans, keep=EQ_KEEP, drop=EQ_DROP, unanimity=2 / 3):
    """{member: decoded plan} -> equivalence report, or None (< 2 comparable plans).
      classes        members grouped by identical canonical plan (largest first, then by name), class_count, singletons
      majority       {field: value} for every field one value holds in >= `unanimity` of the members that carry it
      outliers       members that differ from such a near-unanimous field (the variant that "changed the plot"),
                     diffs {member: {field: its raw value}}, diff_fields (sorted union)
      plot_classes   classes over the near-unanimous fields only (scrambling fields that spread are ignored),
                     plot_class_count, equivalent (the members agreeing with every majority value)
    Field values in diffs / majority are the member's original text (exact_text answers)."""
    try:
        canon, raw = {}, {}
        for m, p in (plans or {}).items():
            c = plan_canonical(p, keep, drop)
            if c:
                canon[m] = c
                raw[m] = {_eq_field(k): v for k, v in _eq_dict(p).items()}
        if len(canon) < 2:
            return None

        def group(fields):
            g = {}
            for m in sorted(canon):
                g.setdefault(tuple((f, canon[m].get(f)) for f in fields), []).append(m)
            return sorted(g.values(), key=lambda ms: (-len(ms), ms[0]))

        fields = sorted({f for c in canon.values() for f in c})
        classes = group(fields)
        majority, diffs = {}, {}
        for f in fields:
            vals = [(m, canon[m][f]) for m in sorted(canon) if f in canon[m]]
            if len(vals) < 2:
                continue
            counts = {}
            for _, v in vals:
                counts[v] = counts.get(v, 0) + 1
            top, n = max(counts.items(), key=lambda kv: kv[1])
            if n < len(vals) and n >= unanimity * len(vals) and n > len(vals) - n:
                for m, v in vals:
                    if v != top:
                        diffs.setdefault(m, {})[f] = raw[m].get(f)
            if n >= unanimity * len(vals) and n > len(vals) - n:
                maj_m = next(m for m, v in vals if v == top)
                majority[f] = raw[maj_m].get(f)
        plot = group(sorted(majority))
        return {"classes": classes, "class_count": len(classes), "singletons": [c[0] for c in classes if len(c) == 1],
                "majority": majority, "outliers": sorted(diffs), "diffs": diffs,
                "diff_fields": sorted({f for d in diffs.values() for f in d}),
                "plot_classes": plot, "plot_class_count": len(plot),
                "equivalent": sorted(m for m in canon if m not in diffs)}
    except Exception:  # noqa: BLE001
        return None


def equivalence_answer(report, kind, accepted_values=None, what="outlier"):
    """One GM answer from an equivalence() report. kind enum -> the outlier member (matched to accepted_values by name
    or stem), integer -> class count (what='plot' -> plot classes), exact_text -> the differing field (what='field')
    or the outlier's value on it (what='value'). "none" when the family has no outlier; None when unanswerable."""
    try:
        if not report:
            return None
        if kind == "integer":
            return str(report["plot_class_count"] if what == "plot" else report["class_count"])
        outs = report["outliers"]
        if not outs:
            return "none"
        if kind == "enum" or what == "outlier":
            m = outs[0] if len(outs) == 1 else None
            if m is None:
                return None
            stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).rsplit("/", 1)[-1]).lower()
            for a in accepted_values or ():
                if stem(a) == stem(m) or stem(a) in stem(m).split("-") or stem(m) in stem(a):
                    return a
            return None if accepted_values else m
        f = report["diff_fields"]
        if len(f) != 1:
            return None
        if what == "field":
            return f[0]
        vals = {str(d[f[0]]) for d in report["diffs"].values() if f[0] in d}
        return vals.pop() if len(vals) == 1 else None
    except Exception:  # noqa: BLE001
        return None


# --- GM label regimes (prebuild batch-expansion-regime-lib) ----------------------------------------------------------
# Some GM labels flipped meaning mid-event. Each entry says when a contract is in the newer regime: `untimed` = an
# explicit run_for_time:false contract is in it, `since` = any contract whose started_at date is >= this is in it.
#   batch_expansion: old regime (D3-D14, timed D15) labels the handoff -- echo(!var!) makes any non-FOR join `delayed`;
#     statement regime (D15 untimed TT 0df5072d / Mastery 7fbfc526, D16 single 89161077 / TT a719c002 / Mastery
#     81bb44e6, all GM-verified) labels the join statement alone.
#   batch_control / vbs_control: no flip observed yet; set `untimed` / `since` here if they flip next.
LABEL_REGIMES = {
    "batch_expansion": {"untimed": True, "since": "2026-10-16"},
    "batch_control": {"untimed": False, "since": None},
    "vbs_control": {"untimed": False, "since": None},
}


def label_regime(field, contract=None):
    """'statement' when `contract` falls in `field`'s newer GM labelling regime (LABEL_REGIMES), else 'legacy'."""
    try:
        rule = LABEL_REGIMES.get(field) or {}
        c = contract if isinstance(contract, dict) else {}
        if rule.get("untimed") and c.get("run_for_time") is False:
            return "statement"
        since = rule.get("since")
        if since and str(c.get("started_at") or "")[:10] >= since:
            return "statement"
    except Exception:  # noqa: BLE001
        pass
    return "legacy"


def batch_join_pool(join_stmt):
    """Fragment-variable pool of a batch join line: `%%h%%G%%` / `%%h0%%` -> 'h', `%%FrAg0%%` -> 'frag'; None if absent."""
    s = str(join_stmt or "")
    m = re.search(r"%%([A-Za-z_]+?)%%G%%", s) or re.search(r"%%([A-Za-z_]+?)\d%%", s)
    return m.group(1).lower() if m else None


def label_expansion(join_stmt, pool=None, contract=None, echo_delayed=True):
    """GM `expansion` label for a batch join statement (`set "x=..."`, `call set ...`, `for ... do call set ...`).

    pool = the fragment-variable prefix (None: read it off the line); echo_delayed = the handoff is echo(!var!) (old
    regime only). Tables (all GM-verified):
      legacy:    FOR join -> call_double on the h pool, else for_indirect; bare `call set` over %%h..%% -> call_double;
                 echo(!var!) handoff -> delayed; other `call set` -> call_double; !a!!b! -> delayed; else percent.
      statement: FOR join -> for_indirect (any pool); bare `call set` over %%h..%% -> call_double; !a!!b! -> delayed;
                 anything else (other pools' call set, plain %a%%b%) -> percent.
    None when the line is not a join (no `=`, no %/! on the right-hand side)."""
    try:
        raw = str(join_stmt or "").strip()
        if "=" not in raw:
            return None
        rhs = raw.split("=", 1)[1]
        if not re.search(r"[%!]", rhs):
            return None
        pool = (pool or batch_join_pool(raw) or "").lower() or None
        stmt = label_regime("batch_expansion", contract) == "statement"
        if re.match(r"(?i)(?:@?\s*)for\s", raw) or re.search(r"(?i)\bdo\s+call\s+set\b", raw):
            return "for_indirect" if stmt or pool != "h" else "call_double"
        call_set = re.search(r"(?i)\bcall\s+set\b", raw)
        if call_set and "%%" in rhs and pool == "h":
            return "call_double"
        if stmt:
            return "delayed" if re.search(r"![^!\s]+!", rhs) else "percent"
        if echo_delayed:
            return "delayed"
        if call_set:
            return "call_double"
        return "delayed" if re.search(r"![^!\s]+!", rhs) else "percent"
    except Exception:  # noqa: BLE001
        return None


# --- network evidence reconcile (prebuild network-evidence-reconcile) ------------------------------------------------
# D17 "Fetch Quest": the decoded plans say where each member would fetch from, the network evidence says where the
# requests went; the answer is the indicator on only one side. Both sides are refanged + canonicalised for matching
# only (canon_host / canon_url); every reported value is the original spelling (exact_text answers are verbatim).
_RC_DEFANG = ((r"(?i)\bh(?:xx|\*\*|XX)p(s?)\b", r"http\1"), (r"(?i)\bfxp\b", "ftp"),
              (r"\s*(?:\[\s*(?:\.|dot)\s*\]|\(\s*(?:\.|dot)\s*\)|\{\s*(?:\.|dot)\s*\}|<\s*dot\s*>)\s*", "."),
              (r"\s*\[\s*:\s*\]\s*", ":"), (r"\[\s*:?//\s*\]", "://"), (r"\[\s*/\s*\]", "/"),
              (r"\s*(?:\[\s*@\s*\]|\(\s*at\s*\)|\[\s*at\s*\])\s*", "@"), (r"\\\.", "."), (r"\\/", "/"))
_RC_URL = re.compile(r"(?i)\b(?:https?|ftp|wss?)://[^\s\"'<>`|,;)\]}]+")
_RC_HOST = re.compile(r"(?i)^(?=.{1,253}$)(?:[a-z0-9_\-\u0080-￿]{1,63}\.)+(?:[a-z\u0080-￿][a-z\-\u0080-￿]"
                      r"{1,62}|xn--[a-z0-9\-]{1,59})$|^xn--[a-z0-9\-]+(?:\.[a-z0-9\-]+)+$")
_RC_IP = re.compile(r"^(?:\d{1,3}\.){3}\d{1,3}$|^[0-9a-f:]*:[0-9a-f:.]+$", re.I)
_RC_FILE_EXT = re.compile(r"(?i)\.(?:ps1|psm1|js|jse|vbs|vbe|bat|cmd|py|sh|exe|dll|dat|bin|txt|zip|hta|wsf|php|lua|pl|rb|"
                          r"ts|ahk|au3|mof|scpt|applescript|proj|xml|json|ini|log|tmp|lnk|docm|xlsm)$")
_RC_HOST_FIELDS = re.compile(r"(?i)(?:^|_)(?:host(?:name)?|domain|server|c2|sni|server_name|callback|beacon|"
                             r"query|qry_name|destination(?:_?hostname)?|fqdn)$")
_RC_PLAN_URL_FIELDS = ("url", "upload_url", "next_stage", "download_url", "fetch_url", "stage_url", "c2_url")


def refang(s):
    """'hxxps://a[.]b[.]c/x' -> 'https://a.b.c/x' (also (.), {.}, [dot], [:], [://], [@]); other text unchanged."""
    s = str(s or "").strip().strip("\"'`<>")
    for pat, rep in _RC_DEFANG:
        s = re.sub(pat, rep, s)
    return s


def _rc_idna(host):
    # IDNA mapping: fullwidth / compatibility forms fold (NFKC), and the ideographic / fullwidth / halfwidth stops
    # U+3002 U+FF0E U+FF61 separate labels like '.'
    host = re.sub("[\u3002\uff0e\uff61]", ".", unicodedata.normalize("NFKC", host)).lower()
    out = []
    for lab in host.split("."):
        if lab and any(ord(c) > 127 for c in lab):
            try:
                lab = "xn--" + lab.encode("punycode").decode("ascii")
            except Exception:  # noqa: BLE001
                pass
        out.append(lab)
    return ".".join(out).rstrip(".")


def _rc_split(s):
    """(scheme, host, port, rest) of a refanged URL or bare host[/path]; host lowercased + IDNA, no userinfo."""
    s = refang(s)
    m = re.match(r"(?i)^([a-z][a-z0-9+.\-]*)://(.*)$", s)
    scheme, body = (m.group(1).lower(), m.group(2)) if m else ("", s)
    cut = re.search(r"[/?#]", body)
    auth, rest = (body[:cut.start()], body[cut.start():]) if cut else (body, "")
    auth = auth.rsplit("@", 1)[-1]
    port = None
    if auth.startswith("["):
        host, _, tail = auth[1:].partition("]")
        if tail.startswith(":") and tail[1:].isdigit():
            port = int(tail[1:])
    else:
        host, sep, p = auth.rpartition(":")
        if not sep or not p.isdigit() or ":" in host:
            host = auth
        else:
            port = int(p)
    host = _rc_idna(host.strip().rstrip(".").lower())
    return scheme, host, port, rest


def canon_host(s):
    """Matching form of a host / URL's host: refanged, lowercased, IDNA punycode, no port / userinfo / trailing dot.
    None when there is no plausible host (a bare word without a dot, a file name)."""
    try:
        _, host, _, _ = _rc_split(s)
        if not host or not (_RC_HOST.match(host) or _RC_IP.match(host) or host == "localhost"):
            return None
        return host
    except Exception:  # noqa: BLE001
        return None


def canon_url(s):
    """Scheme-less matching form 'host[:port]/path?query' of a URL: refanged, host canonical, default port, fragment
    and trailing '/' dropped, unreserved %XX decoded, path case kept. A TLS-observed https request and the declared
    http URL of the same resource compare equal. None when it is not a URL with a host."""
    try:
        scheme, host, port, rest = _rc_split(s)
        if not canon_host(host):
            return None
        rest = rest.split("#", 1)[0]
        rest = re.sub(r"%([0-9A-Fa-f]{2})", lambda m: chr(int(m.group(1), 16)) if re.match(
            r"[A-Za-z0-9\-._~]", chr(int(m.group(1), 16))) else "%" + m.group(1).upper(), rest)
        path, q, query = rest.partition("?")
        path = re.sub(r"/{2,}", "/", path).rstrip("/")
        dflt = {"http": 80, "https": 443, "ws": 80, "wss": 443, "ftp": 21}
        if ":" in host:   # IPv6 literal: keep the brackets so a port stays unambiguous
            host = f"[{host}]"
        hp = host if port is None or port in (80, 443) or port == dflt.get(scheme) else f"{host}:{port}"
        return hp + path + (q + query if query else "")
    except Exception:  # noqa: BLE001
        return None


def _rc_field(k):
    return re.sub(r"[^0-9a-z]+", "_", str(k).strip().lower()).strip("_")


def _rc_dict(plan):
    if isinstance(plan, (bytes, bytearray)):
        plan = bytes(plan).decode("utf-8", "replace")
    if isinstance(plan, dict):
        return plan
    s = str(plan or "").strip()
    if s[:1] == "{":
        try:
            import json
            d = json.loads(s)
            return d if isinstance(d, dict) else {}
        except ValueError:
            return {}
    out = {}
    for part in re.split(r"[|\r\n]+", s):
        if "=" in part:
            k, v = part.split("=", 1)
            out.setdefault(k.strip(), v.strip())
    return out


def declared_fetches(plans):
    """{member: decoded plan (dict / 'k=v|..' / JSON text)} -> [{member, field, value, url, host, stage}]: every plan
    value that is a URL (any field) or a dotted host (host/domain/server/c2 fields), plus non-URL next_stage names
    (`stage`, matched against observed URL basenames). `value` is the plan's original spelling."""
    out = []
    for m in sorted(plans or {}):
        try:
            d = _rc_dict(plans[m])
        except Exception:  # noqa: BLE001
            continue
        for k, v in d.items():
            if not isinstance(v, (str, int, float)) or isinstance(v, bool):
                continue
            f, v = _rc_field(k), str(v).strip()
            if not v:
                continue
            r = refang(v)
            if _RC_URL.fullmatch(r) and canon_url(r):
                out.append({"member": m, "field": f, "value": v, "url": canon_url(r), "host": canon_host(r),
                            "stage": None})
            elif _RC_HOST_FIELDS.search(f) and "." in r and not _RC_FILE_EXT.search(r) and canon_host(r):
                out.append({"member": m, "field": f, "value": v, "url": None, "host": canon_host(r), "stage": None})
            elif f in _RC_PLAN_URL_FIELDS and re.fullmatch(r"[\w.\-]{1,128}", r):
                out.append({"member": m, "field": f, "value": v, "url": None, "host": None,
                            "stage": r.rsplit("/", 1)[-1].lower()})
    return out


# --- declared fetch call sites (download cradles) read from the CODE -------------------------------------------------
# D17 "the source code says where it would fetch from": when a plan has no url (or disagrees), the declared side comes
# from the call sites. Regex only (no ast / eval): string assignments build a small symbol table, the call's argument
# is rebuilt from literals joined by + & . .. , -f / .format / % / sprintf, join() and char-code arrays.
_FS_URL = re.compile(r"(?i)\b(?:https?|ftp)://[^\s\"'<>`|]+")
_FS_LIT = re.compile(r'''(?P<p>[rRbBuUfF]{0,2})(?:"(?P<d>(?:[^"\\\n]|\\.|"")*)"|'(?P<s>(?:[^'\\\n]|\\.|'')*)'|`(?P<t>(?:[^`\\]|\\.)*)`)''', re.S)
_FS_IDENT = re.compile(r"[$@%]?\{?[A-Za-z_][\w]*(?:::[A-Za-z_]\w*)*\}?%?")
_FS_WRAP = re.compile(r"(?i)^(?:new\s+)?(?:URI(?:\.parse|\.join)?|URL|(?:urllib\.request\.|urllib2\.)?Request|str|String|"
                      r"CStr|tostring|URI::HTTPS?\.build|quoted\s+form\s+of|\[(?:string|uri|system\.uri)\])\s*"
                      r"(?:\((?P<a>.*)\)|(?P<b>[^()].*))$", re.S)
_FS_CHR = re.compile(r"(?i)^(?:chrw?|chr\$|\[char\]|string\.char|String\.fromCharCode|pack\s*\(\s*['\"][CU]\*?['\"]\s*,)"
                     r"\s*\(?\s*(?P<n>[\dxa-fA-FhH&,\s]+?)\s*\)?\s*\)?$")
_FS_NUM = re.compile(r"\s*(0x[0-9a-fA-F]+|&[hH][0-9a-fA-F]+|\d+)\s*")
_FS_ASSIGN = re.compile(r"""^\s*(?:<\?php\s+)?(?:(?:export|local|my|our|var|let|const|Dim|Set|Global|Local|Private|Public|static|"""
                        r"""readonly|declare(?:\s+-\w+)?|\$global:|\$script:)\s+)*(?P<n>[$@]?[A-Za-z_]\w*)"""
                        r"""(?:\s*:\s*[\w.\[\]<>|&' ]+?)?\s*(?P<op>:=|\+=|\.=|&=|\.\.=|<-|=(?![=~>]))\s*(?P<v>.+?)\s*;?\s*$""")
_FS_AS_SET = re.compile(r"(?i)^\s*set\s+(?P<n>\w+)\s+to\s+(?P<v>.+?)\s*$")
_FS_BAT_SET = re.compile(r'''(?i)^\s*@?set\s+(?:/[a-z]\s+)?(?:"(?P<n1>[^="]+)=(?P<v1>[^"]*)"|(?P<n2>[^="\s]+)=(?P<v2>.*))$''')
_FS_COMMENT = re.compile(r"(?i)^\s*(?:#(?![!{@])|//|::|rem\b|'|;|--(?!\w)|<!--|\*|/\*)")
_FS_ECHO = re.compile(r"(?i)^\s*@?(?:echo|write-host|write-output|print|puts|console\.log|msgbox|wscript\.echo)\b")
_FS_VERB = re.compile(r"(?i)^(GET|POST|PUT|HEAD|DELETE|PATCH|OPTIONS)$")
_FS_CMD_STOP = re.compile(r"""[;|\n)]|&&|(?<![\w"'])&(?!\w)""")
# (api, regex for the call head, kind): kind 'call' = parenthesised / VB-style args, 'open' = XMLHTTP-style
# .open(method, url), 'cmd' = command line (tokens until ; | && newline)
_FS_HEAD = r"(?im)(?:^|(?<=[\s(;|&\"'`{\[,=]))"
_FS_SITES = (
    ("Invoke-WebRequest", re.compile(_FS_HEAD + r"(?:Invoke-WebRequest|iwr)(?=\s)"), "cmd"),
    ("Invoke-RestMethod", re.compile(_FS_HEAD + r"(?:Invoke-RestMethod|irm)(?=\s)"), "cmd"),
    ("Start-BitsTransfer", re.compile(_FS_HEAD + r"Start-BitsTransfer(?=\s)"), "cmd"),
    ("certutil", re.compile(_FS_HEAD + r"certutil(?:\.exe)?(?=\s[^\n]*-urlcache)"), "cmd"),
    ("bitsadmin", re.compile(_FS_HEAD + r"bitsadmin(?:\.exe)?(?=\s[^\n]*/(?:transfer|addfile))"), "cmd"),
    ("curl", re.compile(_FS_HEAD + r"(?:/usr/bin/)?curl(?:\.exe)?(?=\s)"), "cmd"),
    ("wget", re.compile(_FS_HEAD + r"(?:/usr/bin/|busybox\s+)?wget(?:\.exe)?(?=\s)"), "cmd"),
    ("mshta", re.compile(_FS_HEAD + r"mshta(?:\.exe)?(?=\s+[\"']?(?:https?|ftp)://|\s+[\"']?[$%(])"), "cmd"),
    ("regsvr32", re.compile(_FS_HEAD + r"regsvr32(?:\.exe)?(?=\s[^\n]*/i:)"), "cmd"),
    ("WebClient", re.compile(r"(?i)\.(Download(?:String|File|Data)(?:Async|TaskAsync)?|Upload(?:String|File|Data|Values)"
                             r"(?:Async|TaskAsync)?|OpenRead(?:Async)?)\s*\("), "call"),
    ("HttpClient", re.compile(r"(?i)\.((?:Get(?:String|ByteArray|Stream)?|Post|Put|Send)Async)\s*\("), "call"),
    ("WebRequest", re.compile(r"(?i)\[(?:System\.)?Net\.(?:Http)?WebRequest\]::Create\s*\("), "call"),
    ("XMLHTTP.open", re.compile(r"(?i)\.open\s*(?=[(\s])"), "open"),
    ("fetch", re.compile(r"(?<![\w.$])fetch\s*\("), "call"),
    ("http.get", re.compile(r"\b(https?)\.(get|request)\s*\("), "call"),
    ("axios", re.compile(r"\baxios(?:\.(get|post|put|delete|head|patch|request))?\s*\("), "call"),
    ("urllib.urlopen", re.compile(r"(?<![\w$])(?:urllib2?\.(?:request\.)?|request\.)?(urlopen|urlretrieve)\s*\("), "call"),
    ("requests", re.compile(r"\b(?:requests|httpx|session|s)\.(get|post|put|head|delete|patch|request)\s*\("), "call"),
    ("Net::HTTP", re.compile(r"\bNet::HTTP\.(get_response|get|post_form|post|start)\s*[(\s]"), "call"),
    ("URI.open", re.compile(r"(?<![\w.])(?:URI\.|Kernel\.)?open\s*\(\s*(?=[\"']?(?:https?|ftp)://|URI|[\"'][^\"']*#\{)"), "call"),
    ("LWP", re.compile(r"(?<![\w>$.])(get|getstore|getprint|mirror|head)\s*\(\s*(?=[\"'$])"), "call"),
    ("LWP", re.compile(r"->\s*(get|post|put|head|mirror|request)\s*\(\s*(?=[\"'$])"), "call"),
    ("file_get_contents", re.compile(r"(?i)\b(file_get_contents|fopen|readfile|file|copy|curl_init)\s*\(\s*(?=[\"'$])"), "call"),
    ("curl_setopt", re.compile(r"(?i)\bcurl_setopt\s*\(\s*\$\w+\s*,\s*CURLOPT_URL\s*,"), "call"),
    ("socket.http", re.compile(r"\b(?:http|socket\.http|https)\.request\s*\(?\s*(?=[\"'\w{])"), "call"),
    ("ngx.location.capture", re.compile(r"\bngx\.location\.capture\s*\("), "call"),
    ("Download", re.compile(r"(?i)(?<![\w.])(?:Download|UrlDownloadToFile)\s*(?:\(|,)"), "call"),
    ("InetGet", re.compile(r"(?i)(?<![\w.])(InetGet|InetRead|_INetGetSource)\s*\("), "call"),
)
_FS_UNESC = re.compile(r"\\(x[0-9a-fA-F]{2}|u\{[0-9a-fA-F]{1,6}\}|u[0-9a-fA-F]{4}|[0-7]{1,3}|.)|`([0abefnrtv`\"'$])", re.S)


def _fs_unescape(s, ps=True):
    def one(m):
        e, b = m.group(1), m.group(2)
        if b is not None:
            return {"0": "\0", "a": "\a", "b": "\b", "e": "\x1b", "f": "\f", "n": "\n", "r": "\r", "t": "\t",
                    "v": "\v"}.get(b, b) if ps else m.group(0)
        if e[0] == "x":
            return chr(int(e[1:], 16))
        if e[0] == "u" and len(e) > 1:
            return chr(int(e.strip("u{}"), 16))
        if e[0] in "01234567":
            return chr(int(e, 8) & 0xFF)
        return {"n": "\n", "r": "\r", "t": "\t", "0": "\0"}.get(e, e)
    return _FS_UNESC.sub(one, s)


def _fs_split(expr, seps):
    """Split at top level (outside quotes / brackets) on the regex `seps`; [] when brackets don't balance."""
    out, depth, i, last, q = [], 0, 0, 0, None
    n = len(expr)
    while i < n:
        c = expr[i]
        if q:
            if c == "\\" and q != "'":
                i += 2
                continue
            if c == q:
                q = None
        elif c in "\"'`":
            q = c
        elif c in "([{":
            depth += 1
        elif c in ")]}":
            depth -= 1
            if depth < 0:
                return []
        elif depth == 0:
            m = seps.match(expr, i)
            if m and m.end() > i:
                out.append(expr[last:i])
                i = last = m.end()
                continue
        i += 1
    out.append(expr[last:])
    return out


_FS_CONCAT = re.compile(r"\s*\.\.\s*|\s*\+\s*|\s+&\s+|&(?=[\"'$\w(])|\s+\.\s+|(?<=[\"')\w])\.(?=[\"'$])")
_FS_COMMA = re.compile(r"\s*,\s*")


def _fs_ints(s):
    parts = [p for p in re.split(r"[\s,]+", s.strip()) if p]
    if not parts:
        return None
    try:
        vals = [int(p, 16) if p[:2].lower() == "0x" else int(p[2:], 16) if p[:2].lower() == "&h" else int(p)
                for p in parts]
    except ValueError:
        return None
    return "".join(chr(v) for v in vals) if all(0 < v < 0x110000 for v in vals) else None


def _fs_lookup(name, env):
    k = name.strip("${}%@!")
    k = k[7:] if k.lower().startswith(("global:", "script:")) else k
    return env.get(k, env.get(k.lower()))


def _fs_interp(body, env, kind):
    """Substitute $x / ${x} / #{x} / %x% (and {x} for f-strings) when x is known; None when a reference is unknown."""
    pats = {"f": r"\{([A-Za-z_]\w*)\}", "t": r"\$\{\s*([A-Za-z_]\w*)\s*\}",
            "d": r"\$\(\s*\$?([A-Za-z_]\w*)\s*\)|\$\{([A-Za-z_]\w*)\}|#\{\s*@?([A-Za-z_]\w*)\s*\}|"
                 r"\$([A-Za-z_]\w*)(?![\w(])|%([A-Za-z_]\w*)%"}[kind]
    bad = []

    def one(m):
        v = _fs_lookup(next(g for g in m.groups() if g), env)
        if v is None:
            bad.append(m.group(0))
            return m.group(0)
        return v
    s = re.sub(pats, one, body)
    return None if bad else s


def _fs_eval(expr, env, depth=0):
    """String value of a literal-only expression, or None."""
    try:
        e = expr.strip().rstrip(";").strip()
        if not e or depth > 8 or len(e) > 8000:
            return None
        while e[0] == "(" and e[-1] == ")" and _fs_split(e[1:-1], re.compile(r"(?!)")) != []:
            e = e[1:-1].strip()
            if not e:
                return None
        e = re.sub(r"(?i)^\[(?:string|uri|system\.uri)\]\s*", "", e)
        m = _FS_LIT.fullmatch(e)
        if m:
            p = m.group("p").lower()
            if m.group("s") is not None:
                body = m.group("s").replace("''", "'") if "\\" not in m.group("s") else _fs_unescape(m.group("s"), False)
                return _fs_interp(body, env, "f") if "f" in p else body
            if m.group("t") is not None:
                return _fs_interp(_fs_unescape(m.group("t"), False), env, "t")
            body = m.group("d").replace('""', '"')
            body = body if "r" in p else _fs_unescape(body, ps="`" in body)
            if "f" in p:
                return _fs_interp(body, env, "f")
            return _fs_interp(body, env, "d") if re.search(r"[$#%]", body) else body
        if re.fullmatch(r"\d+", e):
            return e
        if _FS_IDENT.fullmatch(e):
            return _fs_lookup(e, env)
        m = _FS_CHR.match(e)
        if m:
            return _fs_ints(m.group("n").rstrip(")"))
        # -f format / .format / % / sprintf / string.format
        ps = _fs_split(e, re.compile(r"(?i)\s+-f\s+"))
        if len(ps) == 2:
            fmt = _fs_eval(ps[0], env, depth + 1)
            args = [_fs_eval(a, env, depth + 1) for a in _fs_split(ps[1].strip().lstrip("@"), _FS_COMMA)]
            if fmt is not None and None not in args:
                return re.sub(r"\{(\d+)(?:[:,][^}]*)?\}", lambda m: args[int(m.group(1))] if int(m.group(1)) < len(args)
                              else m.group(0), fmt)
            return None
        m = re.fullmatch(r"(?s)(.+?)\.format\s*\((.*)\)", e)
        if m and _FS_LIT.fullmatch(m.group(1).strip()):
            fmt = _fs_eval(m.group(1), env, depth + 1)
            args = [_fs_eval(a, env, depth + 1) for a in _fs_split(m.group(2), _FS_COMMA)]
            if fmt is not None and None not in args:
                it = iter(args)
                return re.sub(r"\{(\d*)\}", lambda mm: args[int(mm.group(1))] if mm.group(1) else next(it, ""), fmt)
            return None
        m = (re.fullmatch(r"(?is)(?:s?printf|string\.format|String\.Format)\s*\((.*)\)", e))
        pm = None if m else _fs_split(e, re.compile(r"\s*%\s*"))
        if m or (pm and len(pm) == 2 and _FS_LIT.fullmatch(pm[0].strip())):
            parts = _fs_split(m.group(1), _FS_COMMA) if m else [pm[0]] + _fs_split(pm[1].strip().strip("()"), _FS_COMMA)
            vals = [_fs_eval(a, env, depth + 1) for a in parts]
            if not parts or None in vals:
                return None
            it = iter(vals[1:])
            return re.sub(r"%[-\d.]*[sd]|\{(\d+)\}", lambda mm: (vals[1:][int(mm.group(1))] if mm.group(1) else
                                                                next(it, "")), vals[0])
        # join forms over arrays of literals / char codes
        m = (re.fullmatch(r"(?is)(?:\[char\[\]\]\s*)?@?\((?P<a>.*)\)\s*-join\s*(?P<s>.*)", e)
             or re.fullmatch(r"(?is)-join\s*(?:\[char\[\]\]\s*)?@?\((?P<a>.*)\)(?P<s>)", e)
             or re.fullmatch(r"(?is)(?P<s>[\"'][^\"']*[\"'])\.join\s*\(\s*(?:map\s*\(\s*chr\s*,\s*)?[\[(](?P<a>.*)[\])]\s*\)?\s*\)", e)
             or re.fullmatch(r"(?is)\[(?P<a>.*)\](?:\.map\s*\([^)]*fromCharCode[^)]*\)\s*)?\.join\s*\(\s*(?P<s>[^)]*)\)", e)
             or re.fullmatch(r"(?is)(?:join|implode)\s*\(\s*(?P<s>[\"'][^\"']*[\"'])\s*,\s*(?:array\s*\(|\[|\(|\{)?(?P<a>.*?)[\])}]?\s*\)", e)
             or re.fullmatch(r"(?is)table\.concat\s*\(\s*\{(?P<a>.*)\}\s*(?:,\s*(?P<s>.+))?\)", e))
        if m:
            sep = _fs_eval(m.group("s"), env, depth + 1) if (m.group("s") or "").strip() else ""
            items = _fs_split(m.group("a"), _FS_COMMA)
            if sep is None or not items:
                return None
            codes = re.search(r"(?i)char|chr|fromCharCode", e) and all(re.fullmatch(r"\s*(?:0x[0-9a-f]+|\d+)\s*", i, re.I)
                                                                       for i in items)
            if codes:
                return _fs_ints(",".join(items))
            vals = [_fs_eval(i, env, depth + 1) for i in items]
            return None if None in vals else sep.join(vals)
        m = re.fullmatch(r"(?is)bytes\s*\(\s*\[(?P<a>[\d\s,xa-fA-F]+)\]\s*\)\.decode\s*\([^)]*\)", e)
        if m:
            return _fs_ints(m.group("a"))
        m = _FS_WRAP.match(e)
        if m and (m.group("a") or m.group("b")):
            inner = m.group("a") if m.group("a") is not None else m.group("b")
            first = _fs_split(inner, _FS_COMMA)
            return _fs_eval(first[0], env, depth + 1) if first else None
        parts = _fs_split(e, _FS_CONCAT)
        if len(parts) < 2:
            parts = [p for p in _fs_split(e, re.compile(r"\s+")) if p]   # adjacent literals ("a" "b")
            if len(parts) < 2 or not all(_FS_LIT.fullmatch(p) for p in parts):
                return None
        vals = [_fs_eval(p, env, depth + 1) for p in parts]
        return None if None in vals else "".join(vals)
    except Exception:  # noqa: BLE001
        return None


def _fs_flat(src):
    """Join line continuations (PS `, VB _, batch ^, shell \\) keeping every offset, so line numbers stay true."""
    return re.sub(r"(?:(?<=\s)_|`|\^|\\)(\r?\n)", lambda m: " " * len(m.group(0)), src)


def _fs_env(flat):
    env = {}
    for ln in flat.splitlines()[:20000]:
        if len(env) > 4000:
            break
        for st in (_fs_split(ln, re.compile(r"\s*;\s*")) or [ln])[:16]:
            m = _FS_BAT_SET.match(st)
            if m:
                n, v = (m.group("n1"), m.group("v1")) if m.group("n1") else (m.group("n2"), m.group("v2"))
                v = re.sub(r"\s*&\s*rem\b.*$", "", v, flags=re.I).replace("^", "")
                v = re.sub(r"%(\w+)%|!(\w+)!", lambda mm: _fs_lookup(mm.group(1) or mm.group(2), env) or mm.group(0), v)
                env[n.strip()] = env[n.strip().lower()] = v
                continue
            m = _FS_AS_SET.match(st)
            if m:
                n, op, rhs = m.group("n"), "=", m.group("v")
            else:
                m = _FS_ASSIGN.match(st)
                if not m:
                    continue
                n, op, rhs = m.group("n"), m.group("op"), m.group("v")
            rhs = re.sub(r"\s+(?:#|//|--|;)\s[^\"'`]*$", "", rhs)
            if op == "=" and not re.match(r"""\s*[\"'`(\[$@%\w-]""", rhs):
                continue
            v = _fs_eval(rhs, env)
            if v is None and op == "=" and n[0] not in "$@" and re.fullmatch(r"[\w.:/?&=%~+-]+", rhs) and \
                    _FS_URL.fullmatch(rhs):
                v = rhs                                    # bash / AHK v1 legacy bare value
            key = n.lstrip("$@")
            if v is None:
                env.pop(key, None)
                env.pop(key.lower(), None)
                continue
            if op != "=" and op not in (":=", "<-"):
                old = _fs_lookup(key, env)
                if old is None:
                    continue
                v = old + v
            env[key] = env[key.lower()] = v[:4096]
    return env


def _fs_args(text, i):
    """Argument list text after a call head ending at offset i: balanced (...) or the rest of the logical line."""
    j = i
    while j < len(text) and text[j] in " \t":
        j += 1
    if text[i - 1:i] == "(":
        j = i - 1
    if j < len(text) and text[j] == "(":
        depth, q, k = 0, None, j
        while k < len(text) and k - j < 4000:
            c = text[k]
            if q:
                if c == "\\" and q != "'":
                    k += 1
                elif c == q:
                    q = None
            elif c in "\"'`":
                q = c
            elif c in "([{":
                depth += 1
            elif c in ")]}":
                depth -= 1
                if depth == 0:
                    return text[j + 1:k]
            elif c == "\n" and depth == 0:
                break
            k += 1
        return None
    end = text.find("\n", j)
    return text[j:end if end >= 0 else len(text)].strip()


def _fs_url_of(val):
    m = _FS_URL.search(val or "")
    return m.group(0).rstrip(".,") if m else None


def _fs_cmd(api, rest, env):
    """(url, method) from a command line's tokens."""
    cut = _fs_split(rest, _FS_CMD_STOP)
    rest = cut[0] if cut else rest
    toks = [t for t in _fs_split(rest, re.compile(r"\s+")) if t]
    url, method, prev = None, "GET", ""
    for t in toks[:64]:
        low = t.lower()
        if api == "regsvr32" and low.startswith("/i:"):
            t = t[3:]
        v = _fs_eval(t, env)
        if v is None and not re.match(r"""[\"'`($@%{]""", t):
            v = re.sub(r"%(\w+)%|!(\w+)!|\$\{?(\w+)\}?", lambda m: _fs_lookup(next(g for g in m.groups() if g), env)
                       or "\0", t)
            v = None if "\0" in v else v
        if prev in ("-x", "--request", "-method", "--method") and v and _FS_VERB.match(v):
            method = v.upper()
        elif low in ("-d", "--data", "--data-binary", "--data-raw", "--data-urlencode", "-f", "--form",
                     "--post-data", "--post-file", "/upload") and api in ("curl", "wget", "bitsadmin") and \
                not (api == "curl" and low == "-f"):
            method = "POST"
        elif low in ("-t", "--upload-file") and api == "curl":
            method = "PUT"
        elif low in ("-i", "--head") and api == "curl":
            method = "HEAD"
        elif low.startswith("--method="):
            method = t.split("=", 1)[1].upper()
        elif prev == "-transfertype" and v and v.lower() == "upload":
            method = "POST"
        if url is None and v and _fs_url_of(v) and (v.strip().lower().startswith(("http", "ftp")) or
                                                    api in ("regsvr32", "mshta")):
            url = _fs_url_of(v)
        prev = low
    return url, method


def fetch_sites(src, name=""):
    """Download-cradle call sites in a script's CODE -> [{api, url, method, line, echo}] in source order. `url` is the
    target rebuilt from the file's own literals (concat / format / join / char codes / variables assigned literals)
    or None when it comes from runtime data (e.g. the decoded plan); `echo` marks a site on an echo/print line (the
    command is only displayed). Comment lines are skipped. [] for a script with no cradle / unreadable input."""
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            src = (b.decode("utf-16", "replace") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else
                   b.decode("utf-8-sig", "replace"))
        text = _fs_flat(str(src or "")[:2_000_000])
        env = _fs_env(text)
        lines = text.split("\n")
        starts = [0]
        for ln in lines:
            starts.append(starts[-1] + len(ln) + 1)
        out, seen = [], set()
        import bisect
        for api, rx, kind in _FS_SITES:
            for m in rx.finditer(text):
                lno = bisect.bisect_right(starts, m.start())
                line = lines[lno - 1]
                if _FS_COMMENT.match(line) or (lno, m.start()) in seen:
                    continue
                args = _fs_args(text, m.end())
                if args is None:
                    continue
                url, method, sub = None, "GET", (m.group(1) if m.groups() else "") or ""
                if kind == "cmd":
                    url, method = _fs_cmd(api, args, env)
                else:
                    if kind == "call" and not text[m.end() - 1:m.end()] in "(," and api not in ("Net::HTTP", "socket.http"):
                        args = args.strip()
                    items = _fs_split(args, _FS_COMMA) or [args]
                    if kind == "open":
                        verb = _fs_eval(items[0], env) if items else None
                        if not verb or not _FS_VERB.match(verb.strip()) or len(items) < 2:
                            continue
                        method, items = verb.strip().upper(), items[1:2]
                    elif api == "requests" and sub == "request" or api == "LWP" and sub == "request":
                        verb = _fs_eval(items[0], env) if items else None
                        method, items = ((verb or "GET").upper(), items[1:2]) if verb and _FS_VERB.match(verb) else \
                            (method, items)
                    elif re.match(r"(?i)upload|post|put", sub):
                        method = "PUT" if sub.lower().startswith("put") else "POST"
                    for it in items[:4]:
                        it2 = re.sub(r"^\s*(?:url|uri)\s*[:=]>?\s*", "", it)
                        v = _fs_eval(it2, env)
                        if v is None and _FS_URL.fullmatch(it2.strip()):
                            v = it2.strip()                     # AHK v1 / AutoIt legacy bare argument
                        elif v is None and re.fullmatch(r"\s*%\w+%\s*", it2):
                            v = _fs_lookup(it2.strip(), env)
                        if v is None and it2.strip()[:1] == "{":
                            mm = re.search(r"""\burl\s*[:=]\s*(.+?)\s*(?:,\s*\w+\s*[:=]|\}$)""", it2.strip(), re.S)
                            v = _fs_eval(mm.group(1), env) if mm else None
                        if v is not None and _fs_url_of(v):
                            url = _fs_url_of(v)
                            break
                        if v is not None and api == "ngx.location.capture":
                            url = None
                            break
                    mm = re.search(r"""(?i)\bmethod\s*[:=]\s*['"]?(?:ngx\.HTTP_)?(GET|POST|PUT|HEAD|DELETE|PATCH)""", args)
                    if mm:
                        method = mm.group(1).upper()
                    if api == "URI.open" and url is None:
                        continue
                if api in ("file_get_contents", "LWP", "socket.http") and url is None:
                    continue                                    # local-file reads / plain gets
                seen.add((lno, m.start()))
                out.append({"api": api, "url": url, "method": method, "line": lno,
                            "echo": bool(_FS_ECHO.match(line))})
        out.sort(key=lambda d: d["line"])
        return out
    except Exception:  # noqa: BLE001
        return []


# --- fetch API / LOLBin -> ATT&CK + adapter label (prebuild lolbin-download-attack-table, 10-18) ---------------------
# GM history: a plan's own attack= always wins; this table only fills ids for members with no plan value. Candidates
# are ordered (first = primary). `adapter` is the canonical tool/API name (plans spell it e.g. adapter=bitsadmin.exe).
_FA_DOWNLOAD = ("T1105",)
_FA_UPLOAD = ("T1041", "T1567", "T1105")
FETCH_ATTACK = {
    # api (fetch_sites name): (adapter label, ids)
    "certutil": ("certutil.exe", ("T1105",)),
    "bitsadmin": ("bitsadmin.exe", ("T1197", "T1105")),
    "Start-BitsTransfer": ("Start-BitsTransfer", ("T1197", "T1105")),
    "mshta": ("mshta.exe", ("T1218.005", "T1105")),
    "regsvr32": ("regsvr32.exe", ("T1218.010", "T1105")),
    "rundll32": ("rundll32.exe", ("T1218.011", "T1105")),
    "msiexec": ("msiexec.exe", ("T1218.007", "T1105")),
    "curl": ("curl", _FA_DOWNLOAD), "wget": ("wget", _FA_DOWNLOAD),
    "Invoke-WebRequest": ("Invoke-WebRequest", _FA_DOWNLOAD), "Invoke-RestMethod": ("Invoke-RestMethod", _FA_DOWNLOAD),
    "WebClient": ("Net.WebClient", _FA_DOWNLOAD), "HttpClient": ("Net.Http.HttpClient", _FA_DOWNLOAD),
    "WebRequest": ("Net.WebRequest", _FA_DOWNLOAD), "XMLHTTP.open": ("MSXML2.XMLHTTP", _FA_DOWNLOAD),
    "fetch": ("fetch", _FA_DOWNLOAD), "http.get": ("http.get", _FA_DOWNLOAD), "axios": ("axios", _FA_DOWNLOAD),
    "urllib.urlopen": ("urllib.request", _FA_DOWNLOAD), "requests": ("requests", _FA_DOWNLOAD),
    "Net::HTTP": ("Net::HTTP", _FA_DOWNLOAD), "URI.open": ("open-uri", _FA_DOWNLOAD), "LWP": ("LWP", _FA_DOWNLOAD),
    "file_get_contents": ("file_get_contents", _FA_DOWNLOAD), "curl_setopt": ("php-curl", _FA_DOWNLOAD),
    "socket.http": ("socket.http", _FA_DOWNLOAD), "Download": ("UrlDownloadToFile", _FA_DOWNLOAD),
    "InetGet": ("InetGet", _FA_DOWNLOAD),
}
_FA_DECODE = re.compile(r"(?i)(?:^|\s)[-/]decode(?:hex)?\b")
_FA_UPVERB = re.compile(r"(?i)\.Upload(?:String|File|Data|Values)|-transfertype\s+upload|/upload\b|--upload-file|"
                        r"(?-i:(?:^|\s)-T\s)|-InFile\b")
_FA_EXTRA = (   # LOLBin proxies fetch_sites does not list (it stays unchanged): (api, call head)
    ("rundll32", re.compile(_FS_HEAD + r"rundll32(?:\.exe)?(?=\s[^\n]*(?:https?|ftp)://|\s[^\n]*javascript:)")),
    ("msiexec", re.compile(_FS_HEAD + r"msiexec(?:\.exe)?(?=\s[^\n]*(?:/i|/package)\b[^\n]*(?:https?|ftp)://)")),
)


def _fa_plan_attack(plan):
    try:
        d = _eq_dict(plan) if plan is not None else None
    except Exception:  # noqa: BLE001
        return None
    v = next((d[k] for k in d if str(k).strip().lower() in ("attack", "technique", "mitre", "attack_id")), None) if d \
        else None
    v = str(v).strip() if v is not None else ""
    return v or None


def fetch_attack(api, line="", method="GET", plan=None):
    """Ordered ATT&CK candidates for one fetch call site: fetch_sites' `api` (or a LOLBin name), its source line
    (certutil -decode adds T1140; upload verbs give T1041/T1567 first) and method. A plan's attack= wins and is
    returned alone. [] for an unknown api."""
    pa = _fa_plan_attack(plan)
    if pa:
        return [pa]
    key = next((k for k in FETCH_ATTACK if k.lower() == str(api or "").strip().lower().removesuffix(".exe")), None)
    if key is None:
        return []
    ids = list(FETCH_ATTACK[key][1])
    line = str(line or "")
    upload = bool(_FA_UPVERB.search(line)) or (str(method or "").upper() in ("POST", "PUT") and
                                               ids[0] == "T1105")
    if upload:      # exfil ids lead; a proxy LOLBin keeps its own id first
        ids = list(_FA_UPLOAD) if ids[0] == "T1105" else ids[:1] + list(_FA_UPLOAD)
    if key == "certutil" and _FA_DECODE.search(line):
        ids.insert(ids.index("T1105") + 1 if "T1105" in ids else len(ids), "T1140")
    out = []
    for i in ids:
        if i not in out:
            out.append(i)
    return out


def fetch_adapter(api):
    """Canonical adapter label for a fetch_sites api name (certutil -> 'certutil.exe'); None when unknown."""
    key = next((k for k in FETCH_ATTACK if k.lower() == str(api or "").strip().lower().removesuffix(".exe")), None)
    return FETCH_ATTACK[key][0] if key else None


def fetch_attack_sites(src, name="", plan=None):
    """fetch_sites(src) plus rundll32 / msiexec /i URL proxies, each site with `adapter` and ordered `attack`
    candidates (plan attack= wins). [] for unreadable input or no cradle."""
    try:
        sites = fetch_sites(src, name)
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            src = (b.decode("utf-16", "replace") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else
                   b.decode("utf-8-sig", "replace"))
        text = _fs_flat(str(src or "")[:2_000_000])
        lines = text.split("\n")
        env, starts = None, None
        have = {(d["line"], d["api"]) for d in sites}
        import bisect
        for api, rx in _FA_EXTRA:
            for m in rx.finditer(text):
                if starts is None:
                    starts = [0]
                    for ln in lines:
                        starts.append(starts[-1] + len(ln) + 1)
                lno = bisect.bisect_right(starts, m.start())
                line = lines[lno - 1]
                if _FS_COMMENT.match(line) or (lno, api) in have:
                    continue
                env = _fs_env(text) if env is None else env
                args = _fs_args(text, m.end()) or ""
                url, method = _fs_cmd("mshta" if api == "rundll32" else api, args, env)
                if url is None:
                    url = _fs_url_of(args)
                have.add((lno, api))
                sites.append({"api": api, "url": url, "method": method, "line": lno,
                              "echo": bool(_FS_ECHO.match(line))})
        sites.sort(key=lambda d: d["line"])
        decode = any(re.search(r"(?i)\bcertutil(?:\.exe)?\s", ln) and _FA_DECODE.search(ln) and
                     not _FS_COMMENT.match(ln) for ln in lines)    # download + separate `certutil -decode` step
        for d in sites:
            line = lines[d["line"] - 1] if 0 < d["line"] <= len(lines) else ""
            if d["api"] == "certutil" and decode:
                line += " -decode"
            d["adapter"] = fetch_adapter(d["api"])
            d["attack"] = fetch_attack(d["api"], line, d.get("method"), plan)
        return sites
    except Exception:  # noqa: BLE001
        return []


def fetch_attack_answer(src, plan=None, name=""):
    """Primary ATT&CK id for a member's fetch behaviour: plan attack= first, else the first non-echo site's top
    candidate. None when there is neither."""
    pa = _fa_plan_attack(plan)
    if pa:
        return pa
    for d in fetch_attack_sites(src, name):
        if not d.get("echo") and d.get("attack"):
            return d["attack"][0]
    return None


def _rc_obs_dict(d):
    """One network_indicators()-style record {kind, host, url, uri, ip, port, ...} -> (url value, host value)."""
    low = {_rc_field(k): v for k, v in d.items() if isinstance(v, (str, int))}
    url = low.get("url") or low.get("request_url") or low.get("full_uri")
    host = next((low[k] for k in ("host", "http_host", "hostname", "server_name", "sni", "query", "qry_name",
                                  "dns_qry_name", "queryname", "destinationhostname", "domain") if low.get(k)), None)
    uri = low.get("uri") or low.get("path") or low.get("request_uri")
    if not url and host and uri and str(uri).startswith("/"):
        url = f"http://{host}{uri}"
    if not host and low.get("ip") and not url:
        host = low.get("ip")
    return (str(url) if url else None), (str(host) if host else None)


# --- network evidence -> fetch indicators (pcap / pcapng / HAR / Zeek / Sysmon / proxy & DNS logs) --------------------
_NI_METHODS = r"GET|POST|PUT|HEAD|DELETE|OPTIONS|PATCH|CONNECT|TRACE|PROPFIND"
_NI_REQ = re.compile(rb"(?:^|\n)(" + _NI_METHODS.encode() + rb") (\S{1,4096}) HTTP/\d(?:\.\d)?\r?\n")
_NI_MAX_FLOW = 1 << 18
_NI_BIN_MAGIC = (b"\xd4\xc3\xb2\xa1", b"\xa1\xb2\xc3\xd4", b"\x4d\x3c\xb2\xa1", b"\xa1\xb2\x3c\x4d", b"\x0a\x0d\x0d\x0a",
                 b"ElfF")


def _ni_ip(b):
    try:
        import ipaddress
        return str(ipaddress.ip_address(bytes(b)))
    except Exception:  # noqa: BLE001
        return None


def _ni_l3(link, pkt):
    """Link-layer frame -> (ip version, ip packet bytes) or None. Ethernet(+VLAN), NULL/LOOP, raw IP, SLL, SLL2."""
    import struct
    link &= 0xFFFF
    if link == 1:
        if len(pkt) < 14:
            return None
        et, off = struct.unpack(">H", pkt[12:14])[0], 14
        while et in (0x8100, 0x88A8, 0x9100) and len(pkt) >= off + 4:
            et, off = struct.unpack(">H", pkt[off + 2:off + 4])[0], off + 4
        body = pkt[off:]
    elif link in (0, 108):
        if len(pkt) < 4:
            return None
        af = struct.unpack(">I" if link == 108 else "<I", pkt[:4])[0]
        if link == 0 and af > 0xFFFF:
            af = struct.unpack(">I", pkt[:4])[0]
        et, body = (0x0800 if af == 2 else 0x86DD if af in (10, 24, 28, 30) else 0), pkt[4:]
    elif link in (101, 12, 14, 228, 229):
        body = pkt
        et = 0x0800 if body[:1] and body[0] >> 4 == 4 else 0x86DD if body[:1] and body[0] >> 4 == 6 else 0
    elif link == 113:
        if len(pkt) < 16:
            return None
        et, body = struct.unpack(">H", pkt[14:16])[0], pkt[16:]
    elif link == 276:
        if len(pkt) < 20:
            return None
        et, body = struct.unpack(">H", pkt[:2])[0], pkt[20:]
    else:
        return None
    return (4, body) if et == 0x0800 else (6, body) if et == 0x86DD else None


def _ni_l4(ver, ip):
    """IP packet -> (proto, src ip, dst ip, l4 bytes) or None (non-first fragments skipped)."""
    import struct
    if ver == 4:
        if len(ip) < 20 or ip[0] >> 4 != 4:
            return None
        ihl, tot = (ip[0] & 15) * 4, struct.unpack(">H", ip[2:4])[0]
        if struct.unpack(">H", ip[6:8])[0] & 0x1FFF:
            return None
        end = tot if ihl <= tot <= len(ip) else len(ip)
        return ip[9], _ni_ip(ip[12:16]), _ni_ip(ip[16:20]), ip[ihl:end]
    if len(ip) < 40 or ip[0] >> 4 != 6:
        return None
    nh, off, plen = ip[6], 40, struct.unpack(">H", ip[4:6])[0]
    end = 40 + plen if 0 < plen and 40 + plen <= len(ip) else len(ip)
    for _ in range(8):
        if nh not in (0, 43, 60, 44) or len(ip) < off + 8:
            break
        if nh == 44:
            if struct.unpack(">H", ip[off + 2:off + 4])[0] & 0xFFF8:
                return None
            nh, off = ip[off], off + 8
        else:
            nh, off = ip[off], off + (ip[off + 1] + 1) * 8
    return nh, _ni_ip(ip[8:24]), _ni_ip(ip[24:40]), ip[off:end]


def _ni_frames(data):
    """pcap / pcapng bytes -> iterator of (linktype, frame bytes). Truncated tails end the walk quietly."""
    import struct
    m = data[:4]
    if m in (b"\xd4\xc3\xb2\xa1", b"\xa1\xb2\xc3\xd4", b"\x4d\x3c\xb2\xa1", b"\xa1\xb2\x3c\x4d"):
        e = "<" if m[0] in (0xD4, 0x4D) else ">"
        if len(data) < 24:
            return
        link, off = struct.unpack(e + "I", data[20:24])[0], 24
        while off + 16 <= len(data):
            incl = struct.unpack(e + "I", data[off + 8:off + 12])[0]
            if incl > 0x40000:
                return
            yield link, data[off + 16:off + 16 + incl]
            off += 16 + incl
        return
    if m != b"\x0a\x0d\x0d\x0a":
        return
    off, e, links = 0, "<", []
    while off + 12 <= len(data):
        bt = data[off:off + 4]
        if bt == b"\x0a\x0d\x0d\x0a":
            e = "<" if data[off + 8:off + 12] == b"\x4d\x3c\x2b\x1a" else ">"
            links = []
        btype, blen = struct.unpack(e + "II", data[off:off + 8])
        if blen < 12 or blen % 4 or off + blen > len(data):
            return
        body = data[off + 8:off + blen - 4]
        if btype == 1 and len(body) >= 2:
            links.append(struct.unpack(e + "H", body[:2])[0])
        elif btype == 6 and len(body) >= 20:
            iface, _, _, cap = struct.unpack(e + "IIII", body[:16])
            if iface < len(links):
                yield links[iface], body[20:20 + cap]
        elif btype == 3 and links:
            orig = struct.unpack(e + "I", body[:4])[0]
            yield links[0], body[4:4 + min(orig, len(body) - 4)]
        elif btype == 2 and len(body) >= 20:
            iface, cap = struct.unpack(e + "H", body[:2])[0], struct.unpack(e + "I", body[12:16])[0]
            if iface < len(links):
                yield links[iface], body[20:20 + cap]
        off += blen


def _ni_dns_name(msg, off):
    labels, jumps, end = [], 0, None
    while off < len(msg) and jumps < 32:
        n = msg[off]
        if n == 0:
            off += 1
            break
        if n & 0xC0 == 0xC0:
            if off + 1 >= len(msg):
                return None, len(msg)
            if end is None:
                end = off + 2
            off, jumps = ((n & 0x3F) << 8) | msg[off + 1], jumps + 1
            continue
        labels.append(msg[off + 1:off + 1 + n].decode("latin-1"))
        off += 1 + n
    return ".".join(labels), (end if end is not None else off)


def _ni_dns(msg):
    """DNS message -> [(qname, [answers: A/AAAA ip or CNAME name])]."""
    import struct
    if len(msg) < 12:
        return []
    flags, qd, an = struct.unpack(">HHH", msg[2:8])
    if qd == 0 or qd > 16 or flags & 0x7800:
        return []
    off, qs = 12, []
    for _ in range(qd):
        name, off = _ni_dns_name(msg, off)
        if not name or off + 4 > len(msg):
            return qs and [(q, []) for q in qs]
        qs.append(name)
        off += 4
    ans = []
    for _ in range(min(an, 64) if flags & 0x8000 else 0):
        _, off = _ni_dns_name(msg, off)
        if off + 10 > len(msg):
            break
        typ, _, _, rdl = struct.unpack(">HHIH", msg[off:off + 10])
        rd = msg[off + 10:off + 10 + rdl]
        if typ in (1, 28) and len(rd) in (4, 16):
            ans.append(_ni_ip(rd))
        elif typ == 5:
            ans.append(_ni_dns_name(msg, off + 10)[0])
        off += 10 + rdl
    return [(q, [a for a in ans if a] if i == 0 else []) for i, q in enumerate(qs)]


def _ni_sni(st):
    """TLS byte stream (client side) -> ClientHello server_name, or None."""
    import struct
    hs, off = b"", 0
    while off + 5 <= len(st) and st[off] == 0x16 and st[off + 1] == 3 and len(hs) < 1 << 16:
        n = struct.unpack(">H", st[off + 3:off + 5])[0]
        hs += st[off + 5:off + 5 + n]
        off += 5 + n
    if len(hs) < 42 or hs[0] != 1:
        return None
    p = 4 + 2 + 32
    p += 1 + hs[p]
    p += 2 + struct.unpack(">H", hs[p:p + 2])[0]
    p += 1 + hs[p]
    end = min(len(hs), p + 2 + struct.unpack(">H", hs[p:p + 2])[0])
    p += 2
    while p + 4 <= end:
        t, n = struct.unpack(">HH", hs[p:p + 4])
        if t == 0 and n >= 5:
            ln = struct.unpack(">H", hs[p + 7:p + 9])[0]
            return hs[p + 9:p + 9 + ln].decode("ascii", "replace") or None
        p += 4 + n
    return None


def _ni_http(st, dst, dport, src):
    out, skip = [], 0
    for mm in _NI_REQ.finditer(st):
        if mm.start() < skip:
            continue
        hend = st.find(b"\r\n\r\n", mm.end() - 2)
        hend = st.find(b"\n\n", mm.end() - 1) if hend < 0 else hend
        head = st[mm.end():hend if hend >= 0 else len(st)].decode("latin-1")
        hdr = {}
        for ln in head.splitlines():
            k, sep, v = ln.partition(":")
            if sep:
                hdr.setdefault(k.strip().lower(), v.strip())
        meth, tgt = mm.group(1).decode(), mm.group(2).decode("latin-1")
        host = hdr.get("host") or (f"{dst}:{dport}" if dport != 80 else dst)
        if meth == "CONNECT":
            url, host = None, tgt
        elif re.match(r"(?i)^[a-z][a-z0-9+.\-]*://", tgt):
            url = tgt
        else:
            url = f"http://{host}{tgt if tgt.startswith('/') else '/' + tgt}"
        out.append({"kind": "http", "host": host, "url": url, "ip": dst, "port": dport, "method": meth,
                    "user_agent": hdr.get("user-agent"), "src": src})
        try:
            skip = (hend if hend >= 0 else len(st)) + int(hdr.get("content-length") or 0)
        except ValueError:
            skip = hend
    return out


def _ni_capture(data):
    """pcap / pcapng -> records (TCP SYN conn, HTTP requests, TLS SNI, DNS questions with answers)."""
    out, flows, order, reqs, resps = [], {}, [], {}, {}
    for n, (link, fr) in enumerate(_ni_frames(data)):
        if n > 200000:
            break
        l3 = _ni_l3(link, fr)
        l4 = l3 and _ni_l4(*l3)
        if not l4:
            continue
        proto, s, d, seg = l4
        if proto == 6 and len(seg) >= 20:
            sp, dp = int.from_bytes(seg[0:2], "big"), int.from_bytes(seg[2:4], "big")
            seq, hl, fl = int.from_bytes(seg[4:8], "big"), (seg[12] >> 4) * 4, seg[13]
            if fl & 0x02 and not fl & 0x10:
                out.append({"kind": "conn", "host": None, "url": None, "ip": d, "port": dp, "method": None,
                            "user_agent": None, "src": s})
            pay = seg[hl:]
            k = (s, sp, d, dp)
            if pay:
                if k not in flows:
                    flows[k] = []
                    order.append(k)
                if sum(len(x[1]) for x in flows[k]) < _NI_MAX_FLOW:
                    flows[k].append((seq, bytes(pay)))
        elif proto == 17 and len(seg) >= 8:
            sp, dp = int.from_bytes(seg[0:2], "big"), int.from_bytes(seg[2:4], "big")
            if {sp, dp} & {53, 5353, 5355}:
                srv, cli = (d, s) if dp in (53, 5353, 5355) else (s, d)
                for q, ans in _ni_dns(seg[8:]):
                    out.append({"kind": "dns", "host": q, "url": None, "ip": next((a for a in ans if _ni_ip_ok(a)),
                                None), "port": 53, "method": None, "user_agent": None, "src": cli,
                                "answers": ans, "server": srv})
    for k in order:
        segs, st, cur = sorted(flows[k]), b"", None
        for seq, p in segs:
            if cur is None or seq >= cur:
                st += p
                cur = seq + len(p)
            elif seq + len(p) > cur:
                st += p[cur - seq:]
                cur = seq + len(p)
        s, sp, d, dp = k
        if 53 in (sp, dp):
            off = 0
            while off + 2 <= len(st):
                n = int.from_bytes(st[off:off + 2], "big")
                for q, ans in _ni_dns(st[off + 2:off + 2 + n]):
                    out.append({"kind": "dns", "host": q, "url": None, "ip": next((a for a in ans if _ni_ip_ok(a)),
                                None), "port": 53, "method": None, "user_agent": None,
                                "src": s if dp == 53 else d, "answers": ans})
                off += 2 + n
        elif st[:1] == b"\x16":
            sni = _ni_sni(st)
            if sni:
                out.append({"kind": "tls", "host": sni, "url": None, "ip": d, "port": dp, "method": None,
                            "user_agent": None, "src": s})
        elif st[:5] == b"HTTP/":
            resps[k] = _ni_http_resp(st)
        else:
            reqs[k] = _ni_http(st, d, dp, s)
            out += reqs[k]
    for (s, sp, d, dp), rs in resps.items():   # server -> client stream answers the reverse flow's requests in order
        for rq, (status, loc) in zip(reqs.get((d, dp, s, sp)) or (), rs):
            rq["status"] = status
            loc = _rd_join(rq.get("url"), loc, status)
            if loc:
                rq["location"] = loc
    return out


def _ni_http_resp(st):
    """Server -> client HTTP byte stream -> [(status, Location or None)] in order (bodies skipped by Content-Length)."""
    out, skip = [], 0
    for mm in re.finditer(rb"(?:^|\n)HTTP/\d(?:\.\d)? (\d{3})[^\r\n]*\r?\n", st):
        if mm.start() < skip or len(out) >= 4096:
            continue
        hend = st.find(b"\r\n\r\n", mm.end() - 2)
        hend = st.find(b"\n\n", mm.end() - 1) if hend < 0 else hend
        hdr = {}
        for ln in st[mm.end():hend if hend >= 0 else len(st)].decode("latin-1").splitlines():
            k, sep, v = ln.partition(":")
            if sep:
                hdr.setdefault(k.strip().lower(), v.strip())
        if mm.group(1)[:1] != b"1":   # 1xx interim responses answer no request of their own
            out.append((int(mm.group(1)), hdr.get("location") or None))
        try:
            skip = (hend if hend >= 0 else len(st)) + int(hdr.get("content-length") or 0)
        except ValueError:
            skip = hend
    return out


# --- pcap HTTP objects (Wireshark "Export Objects > HTTP"): reassembled bodies -> name / size / hashes / next stage -----
_HO_MAX_FLOW = 8 << 20
_HO_START = re.compile(rb"(?:^|(?<=\n))(?:(?P<m>" + _NI_METHODS.encode() + rb") (?P<t>\S{1,4096}) HTTP/\d(?:\.\d)?|"
                       rb"HTTP/\d(?:\.\d)? (?P<s>\d{3})[^\r\n]*)\r?\n")


def _ho_streams(data):
    """pcap / pcapng -> {(src, sport, dst, dport): payload} TCP streams, segments ordered by relative seq
    (retransmits / overlaps trimmed, wrap-safe), first-seen flow order."""
    flows, order = {}, []
    for n, (link, fr) in enumerate(_ni_frames(data)):
        if n > 200000:
            break
        l3 = _ni_l3(link, fr)
        l4 = l3 and _ni_l4(*l3)
        if not l4 or l4[0] != 6 or len(l4[3]) < 20:
            continue
        _, s, d, seg = l4
        pay = seg[(seg[12] >> 4) * 4:]
        if not pay:
            continue
        k = (s, int.from_bytes(seg[0:2], "big"), d, int.from_bytes(seg[2:4], "big"))
        if k not in flows:
            flows[k] = [0, []]
            order.append(k)
        f = flows[k]
        if f[0] < _HO_MAX_FLOW:
            f[1].append((int.from_bytes(seg[4:8], "big"), bytes(pay)))
            f[0] += len(pay)
    out = {}
    for k in order:
        segs = flows[k][1]
        base = segs[0][0]
        rel = sorted((((q - base + (1 << 31)) & 0xFFFFFFFF) - (1 << 31), -len(p), p) for q, p in segs)
        st, cur = bytearray(), None
        for q, _, p in rel:
            if cur is None or q >= cur:
                st += p
                cur = q + len(p)
            elif q + len(p) > cur:
                st += p[cur - q:]
                cur = q + len(p)
        out[k] = bytes(st)
    return out


def _ho_dechunk(st, i):
    """chunked transfer-coding at st[i:] -> (body, next offset, complete)."""
    out = bytearray()
    while i < len(st):
        e = st.find(b"\n", i)
        if e < 0:
            break
        try:
            n = int(st[i:e].split(b";")[0].strip(), 16)
        except ValueError:
            return bytes(out), i, False
        i = e + 1
        if n == 0:
            while True:                                  # trailer fields up to the blank line
                e = st.find(b"\n", i)
                if e < 0:
                    return bytes(out), len(st), True
                ln, i = st[i:e].strip(), e + 1
                if not ln:
                    return bytes(out), i, True
        out += st[i:i + n]
        if i + n > len(st):
            return bytes(out), len(st), False
        i += n
        i += 2 if st[i:i + 2] == b"\r\n" else 1 if st[i:i + 1] == b"\n" else 0
    return bytes(out), len(st), False


def _ho_messages(st, methods=None, limit=1024):
    """HTTP/1.x stream -> [(method, target, status, headers, body as transferred (de-chunked), complete)].
    `methods` (the paired request methods, in order) keeps a HEAD response from eating the next message."""
    out, i, mi = [], 0, 0
    while len(out) < limit:
        m = _HO_START.search(st, i)
        if not m:
            break
        hend, sep = st.find(b"\r\n\r\n", m.end() - 2), 4
        if hend < 0:
            hend, sep = st.find(b"\n\n", m.end() - 1), 2
        if hend < 0:
            hend, sep = len(st), 0
        hdr = {}
        for ln in st[m.end():hend].decode("latin-1").splitlines():
            k, c, v = ln.partition(":")
            if c:
                hdr.setdefault(k.strip().lower(), v.strip())
        b0, status = min(hend + sep, len(st)), int(m.group("s")) if m.group("s") else None
        meth = m.group("m").decode() if m.group("m") else None
        if status is not None and status >= 200 and methods is not None:
            meth, mi = (methods[mi] if mi < len(methods) else None), mi + 1
        cl = (hdr.get("content-length") or "").split(",")[0].strip()
        if (status is not None and (status < 200 or status in (204, 304))) or (status and meth == "HEAD"):
            body, nxt, ok = b"", b0, True
        elif "chunked" in (hdr.get("transfer-encoding") or "").lower():
            body, nxt, ok = _ho_dechunk(st, b0)
        elif cl.isdigit():
            body = st[b0:b0 + int(cl)]
            nxt, ok = b0 + len(body), len(body) == int(cl)
        elif status is not None:                         # no length: body runs to connection close
            body, nxt, ok = st[b0:], len(st), True
        else:
            body, nxt, ok = b"", b0, True
        out.append((None if status is not None else meth, m.group("t").decode("latin-1") if m.group("t") else None,
                    status, hdr, body, ok))
        i = max(nxt, m.end())
    return out


def _ho_content_decode(body, enc):
    """Content-Encoding (gzip / x-gzip / deflate / br / zstd, stacked codings undone last-first) -> bytes or None."""
    import zlib
    for c in reversed([x.strip().lower() for x in (enc or "").split(",") if x.strip()]):
        try:
            if c in ("gzip", "x-gzip"):
                body = zlib.decompressobj(31).decompress(body, 1 << 26)
            elif c == "deflate":
                try:
                    body = zlib.decompressobj(15).decompress(body, 1 << 26)
                except zlib.error:
                    body = zlib.decompressobj(-15).decompress(body, 1 << 26)
            elif c == "br":
                import brotli
                body = brotli.decompress(body)
            elif c in ("zstd", "x-zstd"):
                import zstandard
                body = zstandard.ZstdDecompressor().decompressobj().decompress(body)
            elif c not in ("identity", ""):
                return None
        except Exception:  # noqa: BLE001 - truncated / mislabelled coding
            return None
    return body


def http_objects(data, plans=False, budget=0.8):
    """pcap / pcapng bytes -> HTTP objects in capture order, like Wireshark "Export Objects > HTTP" (TCP reassembled
    by seq, de-chunked, Content-Encoding undone): [{direction: response|request, method, uri, url, host, status,
    content_type, content_encoding, file_name (Content-Disposition, else last URI path segment), size, md5, sha1,
    sha256 (of the decoded body), wire_size / wire_sha256 (as transferred, de-chunked), complete, src, dst, port,
    body}]. Responses pair with the reverse flow's requests in order; request bodies (POST/PUT uploads) are objects
    too. plans=True adds `plain` / `codec` for a body that is itself a staged script (find_codecs on the body: the
    fetched next stage). [] for anything that is not a capture."""
    import hashlib
    import time
    from urllib.parse import unquote
    try:
        data = bytes(data or b"")
        if data[:4] not in (b"\xd4\xc3\xb2\xa1", b"\xa1\xb2\xc3\xd4", b"\x4d\x3c\xb2\xa1", b"\xa1\xb2\x3c\x4d",
                            b"\x0a\x0d\x0d\x0a"):
            return []
        end = time.time() + budget
        streams = _ho_streams(data)
        reqs, out = {}, []
        for k, st in streams.items():
            m = _HO_START.search(st)
            if m and m.group("m"):
                reqs[k] = _ho_messages(st)
        for k, st in streams.items():
            if time.time() > end:
                break
            s, sp, d, dp = k
            if k in reqs:
                rq_list, rs_list, cli, srv, port = reqs[k], [], s, d, dp
                rq_list = [r for r in rq_list if r[4]]
                pairs = [(r, None) for r in rq_list]
            else:
                m = _HO_START.search(st)
                if not m or not m.group("s"):
                    continue
                rq_list = reqs.get((d, dp, s, sp)) or []
                rs_list = _ho_messages(st, [r[0] for r in rq_list])
                cli, srv, port = d, s, sp
                pairs, j = [], 0
                for r in rs_list:
                    if r[2] >= 200:
                        pairs.append((rq_list[j] if j < len(rq_list) else None, r))
                        j += 1
            for rq, rs in pairs:
                msg = rs or rq
                hdr, wire = msg[3], msg[4]
                body = _ho_content_decode(wire, hdr.get("content-encoding"))
                tgt = rq[1] if rq else None
                host = (rq[3].get("host") if rq else None) or (f"{srv}:{port}" if port != 80 else srv)
                if tgt and re.match(r"(?i)^[a-z][a-z0-9+.\-]*://", tgt):
                    url = tgt
                    uri = "/" + tgt.split("://", 1)[1].partition("/")[2]
                else:
                    uri = tgt
                    url = f"http://{host}{tgt if tgt.startswith('/') else '/' + tgt}" if tgt else None
                path = unquote((uri or "").split("?", 1)[0].split("#", 1)[0])
                name = _rc_cd_name(hdr.get("content-disposition")) or (path.rsplit("/", 1)[-1] or None)
                b = body if body is not None else wire
                o = {"direction": "response" if rs else "request", "method": rq[0] if rq else None, "uri": uri,
                     "url": url, "host": host, "status": rs[2] if rs else None,
                     "content_type": (hdr.get("content-type") or "").split(";")[0].strip().lower() or None,
                     "content_encoding": hdr.get("content-encoding"), "file_name": name, "size": len(b),
                     "md5": hashlib.md5(b).hexdigest(), "sha1": hashlib.sha1(b).hexdigest(),
                     "sha256": hashlib.sha256(b).hexdigest(), "wire_size": len(wire),
                     "wire_sha256": hashlib.sha256(wire).hexdigest(), "complete": bool(msg[5] and body is not None),
                     "src": cli, "dst": srv, "port": port, "body": b}
                if plans and b and time.time() < end:
                    for c in find_codecs(b, 1):
                        if c.get("plain"):
                            o["plain"], o["codec"] = c["plain"], {x: c.get(x) for x in ("id", "rep", "transform")}
                            break
                out.append(o)
        return out
    except Exception:  # noqa: BLE001 - impostor / truncated capture: nothing, never an exception
        return []


def _ni_ip_ok(a):
    return bool(a) and bool(re.fullmatch(r"[0-9.]+|[0-9a-fA-F:]*:[0-9a-fA-F:.]*", a))


def _ni_rec(kind, host=None, url=None, ip=None, port=None, method=None, ua=None, src=None, **kw):
    try:
        port = int(port) if port not in (None, "", "-") else None
    except (TypeError, ValueError):
        port = None
    r = {"kind": kind, "host": host or None, "url": url or None, "ip": ip or None, "port": port,
         "method": method or None, "user_agent": ua or None, "src": src or None}
    r.update({k: v for k, v in kw.items() if v})
    return r


def _ni_zeek(row):
    g = lambda *ks: next((row[k] for k in ks if row.get(k) not in (None, "", "-", "(empty)")), None)  # noqa: E731
    ip, port, src = g("id.resp_h", "id_resp_h"), g("id.resp_p", "id_resp_p"), g("id.orig_h", "id_orig_h")
    if g("uri", "method"):
        host, uri = g("host") or ip, g("uri") or "/"
        url = uri if re.match(r"(?i)^https?://", uri) else f"http://{host}{uri}" if host else None
        fn = g("resp_filenames", "orig_filenames")
        fn = ",".join(fn) if isinstance(fn, list) else fn
        return _ni_rec("http", host, url, ip, port, g("method"), g("user_agent"), src, filename=fn,
                       status=g("status_code"), location=_rd_join(url, g("location", "redirect_location",
                                                                         "redirect_url"), g("status_code")))
    if g("query"):
        ans = g("answers")
        ans = ans if isinstance(ans, list) else [a for a in str(ans or "").split(",") if a]
        return _ni_rec("dns", g("query"), None, next((a for a in ans if _ni_ip_ok(a)), None), 53, src=src,
                       answers=ans)
    if g("server_name"):
        return _ni_rec("tls", g("server_name"), None, ip, port, src=src)
    if ip:
        return _ni_rec("conn", None, None, ip, port, src=src)
    return None


def _ni_csv_split(ln, sep):
    if sep == "\t":
        return ln.split("\t")
    return [(q.replace('""', '"') if q is not None and q != "" or a == "" else a).strip()
            for q, a in re.findall(r'(?:^|' + re.escape(sep) + r')\s*(?:"((?:[^"]|"")*)"|([^' + re.escape(sep) +
                                    r']*))', ln)]


def _ni_sysmon(xml):
    out = []
    for ev in re.findall(r"(?s)<Event[\s>].*?</Event>", xml)[:50000]:
        mm = re.search(r"<EventID[^>]*>\s*(\d+)\s*<", ev)
        if not mm or mm.group(1) not in ("3", "22"):
            continue
        import html
        d = {k: html.unescape(v) for k, v in re.findall(r"<Data Name=['\"](\w+)['\"]\s*>([^<]*)</Data>", ev)}
        img = d.get("Image")
        if mm.group(1) == "3":
            out.append(_ni_rec("conn", d.get("DestinationHostname") if d.get("DestinationHostname") not in ("-", "")
                               else None, None, d.get("DestinationIp"), d.get("DestinationPort"), src=d.get("SourceIp"),
                               image=img))
        elif d.get("QueryName"):
            ans = [a.strip() for a in re.sub(r"type:\s*\d+\s*", "", d.get("QueryResults") or "").split(";")
                   if a.strip() and a.strip() != "-"]
            ans = [a[7:] if a.startswith("::ffff:") else a for a in ans]
            out.append(_ni_rec("dns", d["QueryName"], None, next((a for a in ans if _ni_ip_ok(a)), None), 53,
                               answers=ans, image=img))
    return out


def _ni_sysmon_json(rows):
    """Sysmon EID 3 / 22 exported as JSON (flat {EventID, Image, DestinationIp ..}, {System:{EventID}, EventData:{..}},
    xmltodict {Event:{EventData:{Data:[{@Name, #text}]}}}, winlogbeat winlog.event_data, EvtxECmd Payload) -> records;
    None when no row is Sysmon-shaped."""
    def walk(x, d, depth=0):
        if depth > 8:
            return
        if isinstance(x, dict):
            nm = next((x[k] for k in ("@Name", "Name", "name", "@name") if isinstance(x.get(k), str)), None)
            vv = next((x[k] for k in ("#text", "text", "value", "Value", "$") if k in x), None)
            if nm and isinstance(vv, (str, int)):
                d.setdefault(nm, str(vv))
            for k, v in x.items():
                if isinstance(v, str) and k.lower() == "message" and re.search(r"(?m)^\s*(?:Image|QueryName):", v):
                    for mk, mv in re.findall(r"(?m)^\s*(\w+):[ \t]*(.*?)\s*$", v[:65536]):
                        d.setdefault(mk, mv)   # Get-WinEvent | ConvertTo-Json: rendered 'Key: value' lines
                if isinstance(v, (str, int)) and not isinstance(v, bool):
                    d.setdefault(k, str(v))
                    if k.lower() in ("eventid", "event_id", "id", "eventcode"):
                        d.setdefault("EventID", str(v))
                elif k.lower() == "payload" and isinstance(v, str) and v.lstrip()[:1] == "{":
                    try:
                        import json
                        walk(json.loads(v), d, depth + 1)
                    except ValueError:
                        pass
                else:
                    walk(v, d, depth + 1)
        elif isinstance(x, list):
            for v in x[:256]:
                walk(v, d, depth + 1)
    out, hit = [], False
    for row in rows[:50000]:
        d = {}
        walk(row, d)
        low = {re.sub(r"[^a-z]", "", k.lower()): v for k, v in d.items()}
        low = {k: v for k, v in low.items() if v not in ("", "-")} | {k: low[k] for k in ("eventid",) if k in low}
        eid = str(low.get("eventid") or "").strip()
        if not (low.get("destinationip") or low.get("queryname")) or \
                not (eid in ("3", "22") or (not eid and "image" in low)):
            continue
        hit = True
        img = low.get("image")
        if (eid == "3" or not eid) and low.get("destinationip"):
            out.append(_ni_rec("conn", low.get("destinationhostname"), None, low.get("destinationip"),
                               low.get("destinationport"), src=low.get("sourceip"), image=img))
        elif low.get("queryname"):
            ans = [a.strip() for a in re.sub(r"type:\s*\d+\s*", "", low.get("queryresults") or "").split(";")
                   if a.strip() and a.strip() != "-"]
            ans = [a[7:] if a.startswith("::ffff:") else a for a in ans]
            out.append(_ni_rec("dns", low["queryname"], None, next((a for a in ans if _ni_ip_ok(a)), None), 53,
                               answers=ans, image=img))
    return out if hit else None


def _ni_w3c_split(ln):
    return [a if a else q for q, a in re.findall(r'"([^"]*)"|(\S+)', ln)]


def _ni_text(s):
    import json
    st = s.lstrip("﻿").strip()
    if st[:1] in "[{":
        try:
            j = json.loads(st)
            if isinstance(j, dict) and isinstance(j.get("log"), dict):
                out = []
                for e in j["log"].get("entries") or ():
                    rq = (e or {}).get("request") or {}
                    u = rq.get("url")
                    if not u:
                        continue
                    ua = next((h.get("value") for h in rq.get("headers") or () if isinstance(h, dict)
                               and str(h.get("name", "")).lower() == "user-agent"), None)
                    sp = _rc_split(u)
                    rs = (e.get("response") or {}) if isinstance(e.get("response"), dict) else {}
                    cd = next((h.get("value") for h in (rs.get("headers") or ())
                               if isinstance(h, dict) and str(h.get("name", "")).lower() == "content-disposition"), None)
                    loc = rs.get("redirectURL") or next((h.get("value") for h in (rs.get("headers") or ())
                                                         if isinstance(h, dict)
                                                         and str(h.get("name", "")).lower() == "location"), None)
                    out.append(_ni_rec("http", sp[1], u, e.get("serverIPAddress"), sp[2], rq.get("method"), ua,
                                       filename=_rc_cd_name(cd), status=rs.get("status"),
                                       location=_rd_join(u, loc, rs.get("status"))))
                return out
            rows = j if isinstance(j, list) else [j]
            if len(rows) == 1 and isinstance(rows[0], dict):   # {"Events": [...]} / {"records": [...]} wrappers
                inner = next((v for v in rows[0].values() if isinstance(v, list) and v and isinstance(v[0], dict)),
                             None)
                rows = inner if inner and not _ni_zeek(rows[0]) else rows
            sj = _ni_sysmon_json([x for x in rows if isinstance(x, dict)])
            if sj is not None:
                return sj
            return [r for r in (_ni_zeek(x) for x in rows if isinstance(x, dict)) if r]
        except ValueError:
            pass
        if st[:1] == "{":
            rows = []
            for ln in st.splitlines()[:200000]:
                try:
                    x = json.loads(ln)
                except ValueError:
                    continue
                if isinstance(x, dict):
                    rows.append(x)
            if rows:
                sj = _ni_sysmon_json(rows)
                return sj if sj is not None else [r for r in map(_ni_zeek, rows) if r]
    if re.search(r"<EventID[^>]*>\s*(?:3|22)\s*<", s):
        return _ni_sysmon(s)
    lines = s.splitlines()[:200000]
    out, fields, w3c = [], None, None
    for ln in lines:
        if ln.startswith("#fields"):
            fields = ln.split("\t")[1:]
        elif ln.startswith("#Fields:"):
            w3c = ln[8:].split()
        elif fields and ln and not ln.startswith("#"):
            r = _ni_zeek(dict(zip(fields, ln.split("\t"))))
            if r:
                out.append(r)
        elif w3c and ln and not ln.startswith("#"):
            d = {k.lower(): v for k, v in zip(w3c, _ni_w3c_split(ln)) if v != "-"}
            host = d.get("cs-host") or d.get("r-host") or d.get("cs-uri-host") or d.get("s-ip")
            stem, q = d.get("cs-uri-stem") or d.get("cs-uri-path"), d.get("cs-uri-query")
            full = d.get("cs-uri") or d.get("cs-url")
            if full and re.match(r"(?i)^[a-z][\w+.\-]*://", full):
                sp = _rc_split(full)
                out.append(_ni_rec("http", sp[1], full, d.get("r-ip") or d.get("s-ip"), sp[2],
                                   d.get("cs-method"), (d.get("cs(user-agent)") or "").replace("+", " "),
                                   d.get("c-ip")))
            elif host and stem:
                out.append(_ni_rec("http", host, f"http://{host}{stem}" + (f"?{q}" if q and q != "-" else ""),
                                   d.get("s-ip"), d.get("s-port"), d.get("cs-method"),
                                   (d.get("cs(user-agent)") or "").replace("+", " "), d.get("c-ip")))
    if fields or w3c:
        return out
    if lines and re.search(r"(?i)[,\t;](?:\"?)(?:url|uri|request_?url|host|hostname|query|domain|dest\w*|"
                           r"server_?name|sni)(?:\"?)(?:[,\t;]|$)", lines[0]):
        sep = "\t" if "\t" in lines[0] else ";" if lines[0].count(";") > lines[0].count(",") else ","
        hdr = [_rc_field(h) for h in _ni_csv_split(lines[0], sep)]
        for ln in lines[1:]:
            if not ln.strip():
                continue
            d = {k: v for k, v in zip(hdr, _ni_csv_split(ln, sep)) if v not in ("", "-")}
            u, h = _rc_obs_dict(d)
            ip = d.get("dest_ip") or d.get("destination_ip") or d.get("dst_ip") or d.get("ip")
            port = d.get("dest_port") or d.get("destination_port") or d.get("dst_port") or d.get("port")
            kind = "http" if u else "dns" if (d.get("query") or d.get("qry_name")) else "tls" \
                if (d.get("sni") or d.get("server_name")) else "conn" if not h or h == ip else "http"
            if u or h or ip:
                out.append(_ni_rec(kind, h if h != ip else None, u, ip, port, d.get("method"),
                                   d.get("user_agent") or d.get("useragent"), d.get("src_ip") or d.get("client_ip")))
        return out
    for ln in lines:
        mm = re.match(r"^\s*\d{9,}(?:\.\d+)?\s+\d+\s+(\S+)\s+[A-Z_]+/\d{3}\s+\d+\s+([A-Z]+)\s+(\S+)"
                      r"(?:\s+\S+\s+[A-Z_]+/(\S+))?", ln)
        if mm:   # squid native access.log: ts elapsed client code/status bytes METHOD URL [ident hier/peer type]
            meth, tgt = mm.group(2), mm.group(3)
            sp = _rc_split(tgt if "://" in tgt else "https://" + tgt)
            out.append(_ni_rec("http", sp[1], tgt if "://" in tgt else None,
                               mm.group(4) if mm.group(4) and _ni_ip_ok(mm.group(4)) else None, sp[2], meth,
                               src=mm.group(1)))
            continue
        mm = re.search(r"\bquery(?:\[(\w+)\])?:\s+([\w.\-]+)\s+(?:IN\s+\w+|from\s+(\S+))", ln)
        if mm:   # BIND query log / dnsmasq
            out.append(_ni_rec("dns", mm.group(2), None, None, 53, src=mm.group(3)))
            continue
        mm = re.match(r'^(?:(\S+) )?(\S+) \S+ \S+ \[[^\]]+\] "(' + _NI_METHODS + r') (\S+) [^"]*" \d{3} \S+'
                      r'(?: "[^"]*" "([^"]*)")?', ln)
        if mm and "://" in mm.group(4):   # proxy in combined log format with absolute targets
            sp = _rc_split(mm.group(4))
            out.append(_ni_rec("http", sp[1], mm.group(4), None, sp[2], mm.group(3), mm.group(5), mm.group(2)))
        elif mm and mm.group(3) == "CONNECT" and re.fullmatch(r"[\w.\-\[\]:]+:\d{1,5}", mm.group(4)):
            sp = _rc_split("https://" + mm.group(4))   # proxy tunnel: host:port, no URL
            out.append(_ni_rec("tls", sp[1], None, None, sp[2], "CONNECT", mm.group(5), mm.group(2)))
        elif mm and mm.group(1) and mm.group(4).startswith("/"):   # vhost_combined: vhost[:port] client - - [..]
            vh = re.fullmatch(r"([\w.\-]+|\[[0-9a-fA-F:.]+\])(?::(\d{1,5}))?", mm.group(1))
            if vh and "." in vh.group(1) or vh and vh.group(1)[:1] == "[":
                hp = vh.group(1) + (f":{vh.group(2)}" if vh.group(2) and vh.group(2) not in ("80", "443") else "")
                url = ("https" if vh.group(2) == "443" else "http") + f"://{hp}{mm.group(4)}"
                out.append(_ni_rec("http", vh.group(1), url, None, vh.group(2), mm.group(3), mm.group(5),
                                   mm.group(2)))
    if not out:
        for u in _RC_URL.findall(refang(s)):
            u = u.rstrip(".,")
            out.append(_ni_rec("http", _rc_split(u)[1], u))
        for h in re.findall(r"(?im)^\s*host:\s*(\S+)", s):
            out.append(_ni_rec("http", h))
    return out


def _ni_evtx(data):
    try:
        from Evtx.Evtx import FileHeader
        fh, xs, t0 = FileHeader(data, 0), [], time.time()
        for ch in fh.chunks():
            for rec in ch.records():
                x = rec.xml()
                if "<EventID" in x and re.search(r"<EventID[^>]*>\s*(?:3|22)\s*<", x):
                    xs.append(x)
            if time.time() - t0 > 3:
                break
        return _ni_sysmon("\n".join(xs))
    except Exception:  # noqa: BLE001
        return []


def network_indicators(data, name=""):
    """Network evidence -> [{kind: http|dns|tls|conn, host, url, ip, port, method, user_agent, src, ...}] (deduped,
    first-seen order; dns records add `answers`, Sysmon records `image`). Sniffed by magic/shape, not by `name`:
    pcap (D4C3B2A1/A1B2C3D4, ns variants) / pcapng (0A0D0D0A): TCP SYN dst ip:port, reassembled HTTP request lines
    + Host (absolute proxy targets kept), TLS ClientHello SNI, DNS (UDP/TCP 53) qname + A/AAAA/CNAME answers;
    EVTX / Sysmon XML (EID 3 DestinationIp/Port/Hostname, EID 22 QueryName/QueryResults); HAR; Zeek TSV/JSON
    (http/dns/ssl/conn); W3C #Fields; CSV/TSV with url/host/query columns; squid / BIND / dnsmasq / combined proxy
    lines; else free-text URLs and Host: headers. [] when nothing network-shaped is in it. Feed the list straight
    into observed_fetches() / reconcile()."""
    try:
        if isinstance(data, (bytearray, memoryview)):
            data = bytes(data)
        if isinstance(data, bytes):
            data = data[:1 << 26]
            if data[:4] in (b"\xd4\xc3\xb2\xa1", b"\xa1\xb2\xc3\xd4", b"\x4d\x3c\xb2\xa1", b"\xa1\xb2\x3c\x4d",
                            b"\x0a\x0d\x0d\x0a"):
                recs = _ni_capture(data)
            elif data[:8] == b"ElfFile\x00":
                recs = _ni_evtx(data)
            else:
                if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
                    txt = data.decode("utf-16", "replace")
                elif len(data) > 4 and data[1:4:2] == b"\x00\x00" and data[0]:
                    txt = data.decode("utf-16-le", "replace")
                else:
                    txt = data.decode("utf-8", "replace")
                if txt.count("�") > max(16, len(txt) // 20):
                    return []
                recs = _ni_text(txt)
        elif isinstance(data, str):
            recs = _ni_text(data)
        else:
            return []
        out, seen = [], {}
        for r in recs:
            if not r or not (r.get("host") or r.get("url") or r.get("ip")):
                continue
            key = (r["kind"], r.get("host"), r.get("url"), r.get("method")) if r["kind"] in ("dns", "http", "tls") \
                else (r["kind"], r.get("ip"), r.get("port"), r.get("host"))
            if key in seen:
                old = seen[key]
                for a in r.get("answers") or ():
                    if a not in old.setdefault("answers", []):
                        old["answers"].append(a)
                if not old.get("ip") and r.get("ip"):
                    old["ip"] = r["ip"]
                if not old.get("location") and r.get("location"):
                    old["location"], old["status"] = r["location"], r.get("status")
                continue
            seen[key] = r
            out.append(r)
        return out
    except Exception:  # noqa: BLE001
        return []


def observed_fetches(observed):
    """Network evidence -> [{value, url, host, kind}]. Accepts network_indicators() output (list of dicts), a list
    of URL / host strings, HAR JSON (log.entries[].request.url), Zeek TSV (#fields; host+uri / query / server_name),
    or free text (every URL, then 'Host:' headers). Original spelling kept in `value`."""
    recs = []
    try:
        if isinstance(observed, (bytes, bytearray)) and bytes(observed[:4]) in _NI_BIN_MAGIC:
            observed = network_indicators(observed)   # pcap / pcapng / EVTX: binary evidence, records out
        if isinstance(observed, (bytes, bytearray)):
            observed = bytes(observed[:1 << 24]).decode("utf-8", "replace")
        if isinstance(observed, str) and re.search(r"<EventID[^>]*>\s*(?:3|22)\s*<", observed[:1 << 20]):
            observed = network_indicators(observed)   # Sysmon network-connect / DNS-query XML
        if isinstance(observed, str) and _of_log_shaped(observed):
            observed = network_indicators(observed) or observed   # Sysmon JSON / W3C / squid / combined logs
        if isinstance(observed, str):
            s = observed.lstrip("﻿").strip()
            if s[:1] in "[{":
                try:
                    import json
                    j = json.loads(s)
                    if isinstance(j, dict) and isinstance(j.get("log"), dict):
                        j = [e.get("request") or {} for e in j["log"].get("entries") or () if isinstance(e, dict)]
                    observed = j if isinstance(j, list) else [j]
                except ValueError:
                    pass
        if isinstance(observed, str):
            lines = observed.splitlines()
            fields = None
            for ln in lines:
                if ln.startswith("#fields"):
                    fields = ln.split("\t")[1:]
                elif fields and ln and not ln.startswith("#"):
                    row = dict(zip(fields, ln.split("\t")))
                    row = {k: v for k, v in row.items() if v not in ("-", "(empty)", "")}
                    recs.append((_rc_obs_dict(row), "zeek"))
            if fields is None:
                for u in _RC_URL.findall(refang(observed)):
                    if not u.startswith("http://schemas.microsoft.com/win/2004/08/events/"):   # Event xmlns
                        recs.append(((u.rstrip(".,"), None), "url"))
                for h in re.findall(r"(?im)^\s*host:\s*(\S+)", observed):
                    recs.append(((None, h), "host"))
        if isinstance(observed, (list, tuple)) and observed and all(isinstance(x, dict) and "kind" not in x
                                                                    for x in observed[:64]):
            sj = _ni_sysmon_json(list(observed))   # parsed Sysmon JSON export rows
            observed = sj if sj is not None else observed
        if isinstance(observed, (list, tuple, set)):
            # a bare TCP-connect record to an IP some DNS answer / HTTP / TLS record already names adds no host
            named = {str(a) for x in observed if isinstance(x, dict) and x.get("kind") in ("dns", "http", "tls")
                     for a in list(x.get("answers") or ()) + [x.get("ip")] if a}
            for x in observed:
                if isinstance(x, dict) and x.get("kind") == "conn" and not x.get("host") and str(x.get("ip")) in named:
                    continue
                if isinstance(x, dict):
                    recs.append((_rc_obs_dict(x), str(x.get("kind") or "rec"), x.get("image")))
                elif isinstance(x, str):
                    r = refang(x)
                    recs.append(((x, None) if _RC_URL.fullmatch(r) else (None, x), "str"))
    except Exception:  # noqa: BLE001
        pass
    out = []
    for (u, h), kind, *img in recs:
        cu = canon_url(u) if u else None
        ch = canon_host(u) if cu else canon_host(h) if h else None
        if cu or ch:
            out.append({"value": u if cu else h, "url": cu, "host": ch, "kind": kind})
            if img and img[0]:
                out[-1]["image"] = str(img[0])   # Sysmon Image: the process that fetched
    return out


def _of_log_shaped(s):
    """Text that network_indicators() reads as a log, not prose: Sysmon JSON (EventID 3 / 22 with DestinationIp /
    QueryName), a W3C '#Fields:' header, or >= half of the first lines in squid native / (vhost_)combined shape."""
    head = s[:1 << 16]
    st = head.lstrip("\ufeff").lstrip()
    if st[:1] in "[{" and re.search(r"(?:DestinationIp|QueryName)\b", head) and \
            re.search(r'(?i)"(?:EventID|event_id|Id|EventCode)"\s*:\s*"?(?:3|22)\b', head):
        return True
    if re.search(r"(?m)^#Fields:", head):
        return True
    lines = [ln for ln in head.splitlines()[:40] if ln.strip() and not ln.startswith("#")]
    if not lines:
        return False
    pat = re.compile(r'^\s*\d{9,}(?:\.\d+)?\s+\d+\s+\S+\s+[A-Z_]+/\d{3}\s+\d+\s+[A-Z]+\s+\S+|'
                     r'^(?:\S+ )?\S+ \S+ \S+ \[[^\]]+\] "(?:' + _NI_METHODS + r') \S+ [^"]*" \d{3} ')
    return sum(1 for ln in lines if pat.match(ln)) * 2 >= len(lines)


def fetch_processes(observed):
    """Network evidence -> {observed value: process image} for Sysmon EID 3 / 22 records (first image seen per value),
    so an 'only one side' answer can name the process that fetched. {} when the evidence carries no Image."""
    out = {}
    for x in observed_fetches(observed):
        if x.get("image"):
            out.setdefault(x["value"], x["image"])
    return out


# Target process-telemetry-windows (D18 'native telemetry keeps its own record of events'): process start / end
# records from Sysmon EID 1 / 5 and Security 4688 / 4689, read from EVTX, exported XML, JSON (flat, xmltodict,
# winlogbeat / ECS, EvtxECmd Payload, Get-WinEvent Message) or Splunk-style key=value / rendered 'Key: value' text.
_PE_EIDS = {"1": "start", "4688": "start", "5": "end", "4689": "end"}
_PE_ECS = ("process", "user", "event", "host", "agent", "ecs", "winlog", "log", "@timestamp", "_source")
_PE_DATA = ("eventdata", "event_data", "system", "userdata", "payload", "data", "eventdatafields", "properties")
_PE_HINT = re.compile(r"(?im)<EventID[^>]*>\s*(?:1|5|4688|4689)\s*<|\bEvent(?:ID|Code|_id)\W{0,4}(?:1|5|4688|4689)\b|"
                      r"\bevent\.code\W{0,4}(?:1|5|4688|4689)\b|process\.(?:pid|command_line|entity_id)|"
                      r"\"command_line\"|New[ _]Process[ _](?:ID|Name)|Creator[ _]Process[ _]ID|NewProcessId\b|"
                      r"ParentProcess(?:Guid|Id)\b|ProcessGuid\b|^\s*Process Create:|ProcessName\b")


def _pe_int(v):
    s = str(v if v is not None else "").strip()
    try:
        return int(s, 16) if re.fullmatch(r"0[xX][0-9a-fA-F]+", s) else int(s) if re.fullmatch(r"\d+", s) else None
    except ValueError:
        return None


def _pe_norm(k):
    return re.sub(r"[^a-z]", "", str(k).lower())


def _pe_build(d, flat):
    """One record from `d` (event-data names, letters-only lowercase keys) + `flat` (dotted ECS paths), else None."""
    g = lambda *ks: next((d[k] for k in ks if d.get(k) not in (None, "", "-")), None)  # noqa: E731
    f = lambda *ks: next((flat[k] for k in ks if flat.get(k) not in (None, "", "-")), None)  # noqa: E731
    eid = str(g("eventid", "eventcode", "id") or f("winlog.event_id", "event.code") or "").strip()
    if eid not in _PE_EIDS:
        eid = "4688" if g("newprocessid") else "1" if g("parentprocessguid", "parentprocessid") else ""
    sec = eid in ("4688", "4689")
    if eid == "4688":
        pid, ppid = g("newprocessid"), g("processid", "creatorprocessid")
        image, pimage = g("newprocessname"), g("parentprocessname", "creatorprocessname")
        cmd = g("commandline", "processcommandline")
    elif eid == "4689":
        pid, ppid, image, pimage, cmd = g("processid"), None, g("processname"), None, None
    else:
        pid, ppid, image, pimage = g("processid"), g("parentprocessid"), g("image"), g("parentimage")
        cmd = g("commandline")
    ev = _PE_EIDS.get(eid)
    if not ev:
        typ = " ".join(str(x) for x in (f("event.type"), f("event.action")) if x).lower()
        ev = "start" if re.search(r"start|creat|exec|spawn", typ) else "end" if re.search(r"end|stop|termin|exit",
                                                                                          typ) else None
        ev = ev or ("start" if not typ and f("process.pid") and f("process.parent.pid") else None)
    if not ev:
        return None
    pid = pid if pid is not None else f("process.pid")
    if ppid is None and ev == "start":
        ppid = f("process.parent.pid", "process.ppid")
    if pid is None and not image:
        return None
    user = g("user") if not sec else None
    if sec and not user:
        un = g("subjectusername", "accountname")
        dom = g("subjectdomainname", "accountdomain")
        user = f"{dom}\\{un}" if un and dom else un
    hashes = g("hashes") or ",".join(f"{k.split('.')[-1].upper()}={v}" for k, v in flat.items()
                                     if k.startswith("process.hash.") and v not in (None, "")) or None
    return {"ts": g("utctime", "systemtime", "timecreated", "time") or f("@timestamp", "event.created", "timestamp"),
            "pid": _pe_int(pid), "ppid": _pe_int(ppid), "pid_raw": None if pid is None else str(pid),
            "ppid_raw": None if ppid is None else str(ppid),
            "image": image or f("process.executable"), "cmdline": cmd or f("process.command_line"),
            "parent_image": pimage or f("process.parent.executable"),
            "parent_cmdline": g("parentcommandline") or f("process.parent.command_line"),
            "guid": g("processguid") or f("process.entity_id"),
            "parent_guid": g("parentprocessguid") or f("process.parent.entity_id"),
            "user": user or f("user.name"), "integrity": g("integritylevel", "mandatorylabel"),
            "hashes": hashes, "event": ev, "eid": int(eid) if eid else None,
            "src": "security" if sec else "sysmon" if eid else "ecs", **_pe_creator(g, sec)}


def _pe_creator(g, sec):
    """Explicit real-creator fields on a non-4688 record (CreatorProcessId / CreatorProcessGuid / RealParent..):
    {creator_pid, creator_pid_raw, creator_guid, creator_image}, only the keys present ({} for ordinary records)."""
    if sec:
        return {}
    out = {}
    c = g("creatorprocessid", "realparentprocessid", "actualparentprocessid", "trueparentprocessid",
          "callerprocessid", "creatorpid")
    if c is not None and _pe_int(c) is not None:
        out["creator_pid"], out["creator_pid_raw"] = _pe_int(c), str(c)
    c = g("creatorprocessguid", "realparentprocessguid", "actualparentprocessguid")
    if c:
        out["creator_guid"] = c
    c = g("creatorprocessname", "creatorimage", "realparentimage", "actualparentimage", "realparentprocessname")
    if c:
        out["creator_image"] = c
    return out


def _pe_xml(xml):
    import html
    out = []
    for e in re.findall(r"(?s)<Event[\s>].*?</Event>", xml)[:50000]:
        mm = re.search(r"<EventID[^>]*>\s*(\d+)\s*<", e)
        if not mm or mm.group(1) not in _PE_EIDS:
            continue
        d = {_pe_norm(k): html.unescape(a or b) for k, a, b in
             re.findall(r"<Data Name=['\"](\w+)['\"]\s*(?:/>()|>([^<]*)</Data>)", e)}
        d["eventid"] = mm.group(1)
        t = re.search(r"<TimeCreated[^>]*SystemTime=['\"]([^'\"]+)", e)
        if t:
            d["systemtime"] = t.group(1)
        r = _pe_build(d, {})
        if r:
            out.append(r)
    return out


def _pe_json_row(row):
    if isinstance(row.get("_source"), dict):
        row = row["_source"]
    d, flat = {}, {}

    def walk(x, path, keep, depth=0):
        if depth > 10:
            return
        if isinstance(x, dict):
            nm = next((x[k] for k in ("@Name", "Name", "name", "@name") if isinstance(x.get(k), str)), None)
            vv = next((x[k] for k in ("#text", "text", "value", "Value", "$") if k in x), None)
            if nm and isinstance(vv, (str, int)) and not isinstance(vv, bool):
                d.setdefault(_pe_norm(nm), str(vv))
            for k, v in x.items():
                p = f"{path}.{k}" if path else str(k)
                if k in ("#text", "$") and isinstance(v, (str, int)) and path:
                    flat.setdefault(path.lower(), v)
                    if keep:
                        d.setdefault(_pe_norm(path.split(".")[-1]), str(v))
                    continue
                kp = keep or not path and str(k).split(".")[0].lower() not in _PE_ECS or k.lower() in _PE_DATA
                if isinstance(v, str) and k.lower() == "message" and re.search(
                        r"(?m)^\s*(?:Image|CommandLine|New Process ID|Process ID|ProcessId):", v):
                    for mk, mv in re.findall(r"(?m)^\s*([A-Za-z][\w ]*?):[ \t]*(.*?)\s*$", v[:65536]):
                        if mv:
                            d.setdefault(_pe_norm(mk), mv)
                if k.lower() == "payload" and isinstance(v, str) and v.lstrip()[:1] == "{":
                    try:   # EvtxECmd: the event XML as a JSON string
                        import json
                        walk(json.loads(v), p, True, depth + 1)
                    except ValueError:
                        pass
                elif isinstance(v, (str, int)) and not isinstance(v, bool):
                    flat.setdefault(p.lower(), v)
                    if kp:
                        d.setdefault(_pe_norm(k), str(v))
                elif isinstance(v, (dict, list)):
                    walk(v, p, kp, depth + 1)
        elif isinstance(x, list):
            for v in x[:256]:
                walk(v, path, keep, depth + 1)
    walk(row, "", False)
    return _pe_build(d, flat)


def _pe_kv(text):
    """Splunk-style `k=v` / `k="v"` events and rendered 'Key: value' blocks: a new record at each EventCode/EventID."""
    recs, cur = [], {}
    kv = re.compile(r"""(?<![\w.])([A-Za-z_][\w.]*)=(?:"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+))""")
    for ln in text.splitlines()[:200000]:
        pairs = [(k, a if a or b or c else "", b, c) for k, a, b, c in kv.findall(ln)]
        dt = None if pairs else \
            re.match(r"^\s*(\d{1,4}[/-]\d{1,2}[/-]\d{1,4}[ T]\d{1,2}:\d{2}:\d{2}(?:\.\d+)?(?: ?[AP]M)?)\s*$", ln)
        if dt:                          # Splunk classic WinEventLog header line: a new event starts here
            if cur.get("eventid"):
                recs.append(cur)
            cur = {"time": dt.group(1)}
            continue
        rend = None if pairs else re.match(r"^\s*([A-Za-z][\w ]*?):[ \t]+(\S.*?)\s*$", ln)
        items = [(k, (a.replace('\\"', '"') if a else b or c)) for k, a, b, c in pairs] if pairs else \
            [(rend.group(1), rend.group(2))] if rend else []
        if pairs and cur.get("eventid") and any(_pe_norm(k) in ("eventcode", "eventid") for k, *_ in pairs):
            recs.append(cur)    # one k=v event per line: `_time=.. host=..` before EventCode belong to this one
            cur = {}
        for k, v in items:
            nk = _pe_norm(k)
            if nk in ("eventcode", "eventid") and cur.get("eventid"):
                recs.append(cur)
                cur = {}
            if nk in ("eventcode", "eventid"):
                nk = "eventid"
            cur.setdefault(nk, v)
    if cur:
        recs.append(cur)
    out = []
    for d in recs:
        r = _pe_build(d, {}) if d.get("eventid") in _PE_EIDS else None
        if r:
            out.append(r)
    return out


def _pe_evtx(data, budget=2.0):
    try:
        from Evtx.Evtx import FileHeader
        fh, xs, t0 = FileHeader(data, 0), [], time.time()
        for ch in fh.chunks():
            for rec in ch.records():
                try:
                    x = rec.xml()
                except Exception:  # noqa: BLE001 - one damaged record
                    continue
                if re.search(r"<EventID[^>]*>\s*(?:1|5|4688|4689)\s*<", x):
                    xs.append(x)
            if time.time() - t0 > budget:
                break
        return _pe_xml("\n".join(xs))
    except Exception:  # noqa: BLE001
        return []


# Target process-telemetry-linux-text: the same record shape from Linux-side process telemetry -- auditd (SYSCALL
# execve + EXECVE argv (hex-encoded when quoted args would break) + PROCTITLE (hex, NUL-joined) grouped by
# msg=audit(ts:serial)), `ps -ef` / `ps -eo pid,ppid,cmd` / `ps auxf` (`\_` forest indentation = parent), `pstree -p`
# / `pstree -ap`, osquery process_events / processes JSON and Procmon CSV `Process Create` / `Process Start` rows.
# (Sysmon-for-Linux XML is the Windows EID 1 / 5 shape and reads through _pe_xml.)
_PL_HINT = re.compile(r"(?im)\btype=(?:SYSCALL|EXECVE|PROCTITLE|130[09]|1327)\s+(?:msg=)?audit\(|"
                      r"^\s*(?:(?:UID|USER)\s+)?PID\s+(?:PPID|%CPU)\s|^\s*PID\s+PPID\b|"
                      r"\w\(\d+(?:,\w+)?\)(?:---|-\+-|───|─┬─)|^\s*\S+?,\d+(?:\s|$)|"
                      r"\"parent\"\s*:\s*\"?-?\d+|\"Process (?:Create|Start)\"\s*,")
_PL_AU_TYPES = {"1300": "SYSCALL", "1309": "EXECVE", "1327": "PROCTITLE", "1307": "CWD", "1302": "PATH"}
_PL_EXEC_NR = {"59", "322", "11", "358", "221", "281", "execve", "execveat"}


def _pl_rec(**kw):
    pid, ppid = kw.pop("pid", None), kw.pop("ppid", None)
    r = {"ts": None, "pid": _pe_int(pid), "ppid": _pe_int(ppid), "pid_raw": None if pid is None else str(pid),
         "ppid_raw": None if ppid is None else str(ppid), "image": None, "cmdline": None, "parent_image": None,
         "parent_cmdline": None, "guid": None, "parent_guid": None, "user": None, "integrity": None, "hashes": None,
         "event": "start", "eid": None, "src": None}
    r.update(kw)
    return r


def _pl_auval(v, interp):
    """auditd field value: "quoted" -> as is; raw-mode unquoted even-length hex -> its bytes (NULs -> spaces)."""
    if v[:1] == '"' and v[-1:] == '"' and len(v) >= 2:
        return v[1:-1]
    if not interp and re.fullmatch(r"(?:[0-9A-Fa-f]{2})+", v or ""):
        return bytes.fromhex(v).decode("utf-8", "replace")
    return None if v == "(null)" else v


def _pl_auditd(txt):
    kv = re.compile(r"""([\w\[\]]+)=("[^"]*"|'[^']*'|\S+)""")
    grp, order = {}, []
    for ln in txt.splitlines()[:400000]:
        m = re.search(r"\btype=(\w+)\s+(?:msg=)?audit\(([^)]*)\)\s*:?\s*(.*)", ln.split("\x1d")[0])
        if not m:
            continue
        typ = _PL_AU_TYPES.get(m.group(1), m.group(1).upper())
        if typ not in ("SYSCALL", "EXECVE", "PROCTITLE", "CWD", "PATH"):
            continue
        stamp = m.group(2)
        g = grp.get(stamp)
        if g is None:
            g = grp[stamp] = {"interp": bool(re.search(r"[/ ]", stamp)) or ") : " in ln}
            order.append(stamp)
        f = {}
        for k, v in kv.findall(m.group(3)):
            f.setdefault(k, v)
        if typ == "PATH" and f.get("item") not in (None, "0"):
            continue
        g.setdefault(typ, f)
    out = []
    for stamp in order[:100000]:
        g, ip = grp[stamp], grp[stamp]["interp"]
        sc, ex = g.get("SYSCALL") or {}, g.get("EXECVE")
        if not ex and str(sc.get("syscall", "")).lower() not in _PL_EXEC_NR:
            continue
        if sc.get("success") == "no":
            continue
        args = []
        if ex:
            n = _pe_int(ex.get("argc")) or 0
            for i in range(min(n or 4096, 4096)):
                if f"a{i}" in ex:
                    args.append(_pl_auval(ex[f"a{i}"], ip) or "")
                elif f"a{i}[0]" in ex:   # long argument: a2_len=N a2[0]=hex a2[1]=hex ...
                    parts, j = [], 0
                    while f"a{i}[{j}]" in ex:
                        parts.append(ex[f"a{i}[{j}]"].strip('"'))
                        j += 1
                    s = "".join(parts)
                    args.append(bytes.fromhex(s).decode("utf-8", "replace")
                                if not ip and re.fullmatch(r"(?:[0-9A-Fa-f]{2})+", s) else s)
                elif not n:
                    break
        cmd = " ".join(args) if args else None
        pt = (g.get("PROCTITLE") or {}).get("proctitle")
        if not cmd and pt:
            cmd = pt.strip('"') if pt[:1] == '"' or ip else \
                bytes.fromhex(pt).replace(b"\x00", b" ").decode("utf-8", "replace").strip() \
                if re.fullmatch(r"(?:[0-9A-Fa-f]{2})+", pt) else pt
        image = _pl_auval(sc["exe"], ip) if sc.get("exe") else None
        if not image and g.get("PATH", {}).get("name"):
            image = _pl_auval(g["PATH"]["name"], ip)
        ts = stamp.rsplit(":", 1)[0]
        cwd = _pl_auval(g["CWD"]["cwd"], ip) if g.get("CWD", {}).get("cwd") else None
        out.append(_pl_rec(pid=sc.get("pid"), ppid=sc.get("ppid"), ts=ts, image=image or (args[0] if args else None),
                           cmdline=cmd, user=sc.get("UID", "").strip('"') or sc.get("uid"), src="auditd",
                           args=args, cwd=cwd, serial=stamp.rsplit(":", 1)[-1], auid=sc.get("auid"),
                           comm=_pl_auval(sc["comm"], ip) if sc.get("comm") else None))
    return out


def _pl_ps(txt):
    lines = txt.splitlines()[:400000]
    hi = next((i for i, ln in enumerate(lines[:2000]) if re.match(r"^\s*(?:[A-Z%]+\s+)*PID\s+(?:[A-Z%]+\s+)*"
                                                                 r"(?:CMD|COMMAND|ARGS|COMM)\s*$", ln)), None)
    if hi is None:
        return []
    cols = lines[hi].split()
    n, last = len(cols), cols[-1]
    ix = {c: i for i, c in enumerate(cols)}
    row = re.compile(r"^(\s*\S+(?:\s+\S+){%d})(.*)$" % (n - 2)) if n >= 2 else None
    out, stack = [], []
    for ln in lines[hi + 1:]:
        if not ln.strip():
            continue
        m = row.match(ln) if row else None
        if not m:
            if out and re.match(r"^\s*(?:[A-Z%]+\s+)*PID\s", ln):
                continue
            break
        fs, rest = m.group(1).split(), m.group(2)
        if _pe_int(fs[ix["PID"]]) is None:
            break
        fm = re.match(r"^(\s*(?:[|│]\s*)*)\\_\s?", rest)
        cmd = rest[fm.end():].strip() if fm else rest.strip()
        ind = len(m.group(1)) + fm.end() if fm else -1
        while stack and stack[-1][0] >= ind:
            stack.pop()
        ppid = fs[ix["PPID"]] if "PPID" in ix else (stack[-1][1] if stack and fm else None)
        stack.append((ind, fs[ix["PID"]]))
        user = fs[ix["UID"]] if "UID" in ix else fs[ix["USER"]] if "USER" in ix else None
        tok = cmd.split()[0] if cmd.split() else None
        ts = fs[ix[k]] if (k := next((k for k in ("STIME", "START", "STARTED") if k in ix), None)) else None
        out.append(_pl_rec(pid=fs[ix["PID"]], ppid=ppid, ts=ts, image=tok if last != "COMM" else cmd,
                           cmdline=cmd if last != "COMM" else None, user=user, src="ps"))
    return out


_PL_TREE_NODE = re.compile(r"(\{[^{}()\n]*\}|[^\s()|`+\-─┬┴├└│{}][^\s()]*?)\((\d+)(?:,([\w.\-]+))?\)")


def _pl_pstree(txt):
    out, branch = [], {}
    lines = txt.splitlines()[:200000]
    if not any(_PL_TREE_NODE.search(ln) for ln in lines[:50]):
        return _pl_pstree_a(lines)
    for ln in lines:
        prev, pend = None, 0
        for m in _PL_TREE_NODE.finditer(ln):
            gap = ln[pend:m.start()]
            if prev is not None and re.search(r"[-─+┬]", gap):
                parent = prev
            else:
                bc = max(ln.rfind(c, 0, m.start()) for c in "|`├└│")
                parent = branch.get(bc) if bc >= 0 else None
                if prev is not None and parent is None:
                    break
            if prev is None and gap.strip() and not re.fullmatch(r"[\s|`\-─├└│+┬]*", gap):
                break
            nm = m.group(1)
            out.append(_pl_rec(pid=m.group(2), ppid=parent, image=nm, user=m.group(3), src="pstree"))
            nxt = ln[m.end():m.end() + 3]
            for c in ("+", "┬"):
                if c in nxt:
                    branch[m.end() + nxt.index(c)] = m.group(2)
            prev, pend = m.group(2), m.end()
    return out


def _pl_pstree_a(lines):
    """`pstree -ap`: one `name,pid args` per line, indentation = depth."""
    out, stack = [], []
    for ln in lines:
        m = re.match(r"^([\s|`│├└\-─]*)(\{?[^\s,(){}]+\}?),(\d+)(?:,[\w.\-]+)?(?:\s+(.*))?$", ln)
        if not m:
            continue
        ind = len(m.group(1))
        while stack and stack[-1][0] >= ind:
            stack.pop()
        out.append(_pl_rec(pid=m.group(3), ppid=stack[-1][1] if stack else None, image=m.group(2),
                           cmdline=(m.group(2) + " " + m.group(4)) if m.group(4) else m.group(2), src="pstree"))
        stack.append((ind, m.group(3)))
    return out if len(out) >= 2 else []


def _pl_osq_row(x):
    c = x.get("columns") if isinstance(x.get("columns"), dict) else x
    if not isinstance(c, dict) or "pid" not in c or not ({"parent", "ppid"} & set(c)) or \
            not ({"cmdline", "path", "name"} & set(c)):
        return None
    act = str(x.get("action") or "added").lower()
    ts = c.get("time") or x.get("unixTime") or x.get("calendarTime")
    return _pl_rec(pid=c.get("pid"), ppid=c.get("parent", c.get("ppid")), ts=None if ts is None else str(ts),
                   image=c.get("path") or c.get("name"), cmdline=c.get("cmdline") or None,
                   user=c.get("username") or (None if c.get("uid") is None else str(c.get("uid"))),
                   event="end" if act == "removed" else "start", src="osquery", cwd=c.get("cwd"))


def _pl_osquery(txt):
    import json
    try:
        j = json.loads(txt)
        rows = j if isinstance(j, list) else [j]
    except ValueError:
        rows = []
        for ln in txt.splitlines()[:200000]:
            try:
                rows.append(json.loads(ln))
            except ValueError:
                continue
    flat = []
    for x in rows[:200000]:
        if isinstance(x, dict) and isinstance(x.get("snapshot"), list):
            flat += [dict(y, unixTime=x.get("unixTime")) for y in x["snapshot"] if isinstance(y, dict)]
        elif isinstance(x, dict) and isinstance(x.get("diffResults"), dict):
            for a in ("added", "removed"):
                flat += [{"columns": y, "action": a} for y in x["diffResults"].get(a) or [] if isinstance(y, dict)]
        elif isinstance(x, dict):
            flat.append(x)
    return [r for r in (_pl_osq_row(x) for x in flat) if r]


_PL_CSV_FIELD = re.compile(r'\s*(?:"((?:[^"]|"")*)"|([^,]*))\s*(,|$)')


def _pl_csv_split(ln):
    out, pos = [], 0
    while pos <= len(ln):
        m = _PL_CSV_FIELD.match(ln, pos)
        if not m:
            return out
        out.append(m.group(1).replace('""', '"') if m.group(1) is not None else m.group(2))
        if not m.group(3):
            break
        pos = m.end()
    return out


def _pl_procmon(txt):
    lines = txt.lstrip("﻿").splitlines()[:400000]
    hdr = _pl_csv_split(lines[0]) if lines else []
    ix = {_pe_norm(h): i for i, h in enumerate(hdr)}
    if not {"operation", "pid", "detail"} <= set(ix):
        return []
    col = lambda r, k: r[ix[k]] if k in ix and ix[k] < len(r) else None  # noqa: E731
    creates, starts, ends = [], {}, []
    for ln in lines[1:]:
        r = _pl_csv_split(ln)
        op, det = (col(r, "operation") or "").strip(), col(r, "detail") or ""
        ts = col(r, "timeofday") or col(r, "datetime") or col(r, "time")
        if op == "Process Create":
            m = re.match(r"\s*PID:\s*(\d+),\s*Command line:\s?(.*)$", det, re.S)
            if m:
                creates.append(_pl_rec(pid=m.group(1), ppid=col(r, "pid"), ts=ts, image=col(r, "path"),
                                       cmdline=m.group(2) or None, parent_image=col(r, "imagepath") or
                                       col(r, "processname"), user=None, src="procmon"))
        elif op == "Process Start":
            m = re.match(r"\s*Parent PID:\s*(\d+)(?:,\s*Command line:\s?(.*?))?(?:,\s*Current directory:.*)?$",
                         det, re.S)
            if m:
                starts.setdefault(col(r, "pid"), _pl_rec(
                    pid=col(r, "pid"), ppid=m.group(1), ts=ts, image=col(r, "imagepath") or col(r, "processname"),
                    cmdline=m.group(2) or col(r, "commandline") or None, user=col(r, "user"), src="procmon"))
        elif op == "Process Exit":
            ends.append(_pl_rec(pid=col(r, "pid"), ts=ts, image=col(r, "imagepath") or col(r, "processname"),
                                event="end", src="procmon"))
    seen = {r["pid_raw"] for r in creates}
    return creates + [r for k, r in starts.items() if k not in seen] + ends


def _pl_events(txt):
    """Linux-side / Procmon process telemetry text -> process_events() records (+ src auditd|ps|pstree|osquery|
    procmon; auditd adds args / cwd / serial / auid / comm). [] when nothing reads."""
    head = txt[:1 << 20]
    if not _PL_HINT.search(head):
        return []
    out = []
    if re.search(r"\btype=(?:SYSCALL|EXECVE|PROCTITLE|130[09]|1327)\s+(?:msg=)?audit\(", head):
        out = _pl_auditd(txt)
    if not out and head.lstrip()[:1] in "[{":
        out = _pl_osquery(txt)
    if not out and re.search(r"\"?Operation\"?\s*,", head[:4096]):
        out = _pl_procmon(txt)
    if not out and re.search(r"(?m)^\s*(?:[A-Z%]+\s+)*PID\s", head):
        out = _pl_ps(txt)
    if not out:
        out = _pl_pstree(txt)
    by = {}
    for r in out:   # parent image / command line from the latest earlier start of the parent pid
        if r["event"] == "start" and r["ppid"] is not None and r["ppid"] in by:
            p = by[r["ppid"]]
            r["parent_image"] = r["parent_image"] or p["image"]
            r["parent_cmdline"] = r["parent_cmdline"] or p["cmdline"]
        if r["event"] == "start" and r["pid"] is not None:
            by[r["pid"]] = r
    return out


def process_events(data, name=""):
    """Process telemetry -> [{ts, pid, ppid, pid_raw, ppid_raw, image, cmdline, parent_image, parent_cmdline, guid,
    parent_guid, user, integrity, hashes, event: start|end, eid, src: sysmon|security|ecs}] in record order.
    Sysmon EID 1 (ProcessId / ParentProcessId / ProcessGuid / ParentProcessGuid / Image / ParentImage / CommandLine /
    ParentCommandLine / User / IntegrityLevel / Hashes / UtcTime), EID 5 (terminate); Security 4688 (NewProcessId =
    the new pid, ProcessId = the CREATOR pid, both hex; NewProcessName, ParentProcessName, CommandLine,
    MandatoryLabel) and 4689 (ProcessId, ProcessName). Inputs: EVTX bytes, exported XML, JSON / NDJSON (flat,
    xmltodict, winlogbeat winlog.event_data, ECS process.pid / process.parent.pid / process.entity_id, EvtxECmd
    Payload, Get-WinEvent Message), Splunk k=v or rendered 'Key: value' text. Hex pids ('0x1a2c') -> int in pid /
    ppid, the original spelling kept in pid_raw / ppid_raw (answer with that). [] when nothing process-shaped."""
    try:
        if isinstance(data, (bytearray, memoryview)):
            data = bytes(data)
        if isinstance(data, bytes):
            data = data[:1 << 26]
            if data[:8] == b"ElfFile\x00":
                return _pe_evtx(data)
            if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
                txt = data.decode("utf-16", "replace")
            elif len(data) > 4 and data[1:4:2] == b"\x00\x00" and data[0]:
                txt = data.decode("utf-16-le", "replace")
            else:
                txt = data.decode("utf-8", "replace")
        elif isinstance(data, str):
            txt = data
        else:
            return []
        st = txt.lstrip("﻿").strip()
        return _pe_text(st) or _pl_events(st)
    except Exception:  # noqa: BLE001 - impostor / truncated log: nothing, never an exception
        return []


def _pe_text(st):
    try:
        if not _PE_HINT.search(st[:1 << 20]):
            return []
        if re.search(r"<EventID[^>]*>", st[:1 << 20]):
            return _pe_xml(st)
        if st[:1] in "[{":
            import json
            try:
                j = json.loads(st)
                rows = j if isinstance(j, list) else [j]
                if len(rows) == 1 and isinstance(rows[0], dict) and not _pe_json_row(rows[0]):
                    inner = next((v for v in rows[0].values() if isinstance(v, list) and v and isinstance(v[0], dict)),
                                 None)
                    if inner is None and isinstance((rows[0].get("hits") or {}).get("hits"), list):
                        inner = rows[0]["hits"]["hits"]
                    rows = inner or rows
            except ValueError:
                rows = []
                for ln in st.splitlines()[:200000]:
                    try:
                        x = json.loads(ln)
                    except ValueError:
                        continue
                    rows.append(x)
            return [r for r in (_pe_json_row(x) for x in rows[:50000] if isinstance(x, dict)) if r]
        return _pe_kv(st)
    except Exception:  # noqa: BLE001 - impostor / truncated log: nothing, never an exception
        return []


def process_tree(events, pid=None):
    """Observed process tree from process_events() records (or the raw log). With `pid` (int or '0x..'): the legacy
    ancestry list [record, parent, ...]. Without: {nodes: {key: node}, edges: [(parent_key, child_key)], roots,
    orphans, leaves, children: {key: [child keys]}, parent: {key: parent_key|None}, depth: {key: int, root = 0},
    max_depth, chains: {leaf: [root..leaf]}, order: [keys by start]}. Key = ProcessGuid (braces stripped, lower) when
    present, else (pid, start ts) so pid reuse never merges two processes. Parent = the ParentProcessGuid node, else
    the node with pid == ppid (4688: the CREATOR ProcessId) alive at the child's start (started before, not ended
    before). Orphan ('Orphan Process') = a parent reference that resolves to nothing: node['orphan'] = 'missing'
    (pid/guid never seen) | 'exited' (that pid/guid had exited before the child started). An empty tree on junk."""
    try:
        if isinstance(events, (bytes, bytearray, memoryview, str)):
            events = process_events(events)
        if pid is not None:
            starts = [e for e in events if e.get("event") == "start"]
            want, out, seen = _pe_int(pid) if not isinstance(pid, int) else pid, [], set()
            while want is not None and want not in seen and len(out) < 64:
                seen.add(want)
                r = next((e for e in reversed(starts) if e.get("pid") == want), None)
                if not r:
                    break
                out.append(r)
                want = r.get("ppid")
            return out
        return _pt_build(list(events or [])[:200000])
    except Exception:  # noqa: BLE001
        return [] if pid is not None else {}


def _pt_ts(v):
    """Event time -> epoch seconds (ISO 8601 with 7-digit fractions / Z / offset, 'M/D/YYYY h:mm:ss PM', epoch)."""
    import datetime as _dt
    s = str(v or "").strip()
    if not s:
        return None
    if re.fullmatch(r"\d{9,13}(?:\.\d+)?", s):
        f = float(s)
        return f / 1000 if f > 1e11 else f
    m = re.match(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d):(\d\d)(?:[.,](\d+))?\s*(Z|[+-]\d\d:?\d\d)?", s)
    try:
        if m:
            y, mo, d, h, mi, se, fr, tz = m.groups()
            t = _dt.datetime(int(y), int(mo), int(d), int(h), int(mi), int(se), int((fr or "0")[:6].ljust(6, "0")),
                             tzinfo=_dt.timezone.utc).timestamp()
            if tz and tz != "Z":
                z = tz.replace(":", "")
                t -= (1 if z[0] == "+" else -1) * (int(z[1:3]) * 3600 + int(z[3:5]) * 60)
            return t
        m = re.match(r"(\d{1,2})/(\d{1,2})/(\d{4})[ T](\d{1,2}):(\d\d):(\d\d)(?:\.(\d+))?\s*([AaPp][Mm])?", s)
        if m:
            mo, d, y, h, mi, se, fr, ap = m.groups()
            h = int(h) % 12 + (12 if ap and ap.upper() == "PM" else 0) if ap else int(h)
            return _dt.datetime(int(y), int(mo), int(d), h, int(mi), int(se), int((fr or "0")[:6].ljust(6, "0")),
                                tzinfo=_dt.timezone.utc).timestamp()
    except ValueError:
        return None
    return None


def _pt_guid(g):
    s = str(g or "").strip().strip("{}").lower()
    return s if s and s.strip("0-") else None


def _pt_build(events):
    evs = [e for e in events if isinstance(e, dict) and e.get("event") in ("start", "end")]
    tss = [_pt_ts(e.get("ts")) for e in evs]
    timed = bool(evs) and all(t is not None for t in tss)
    order = sorted(range(len(evs)), key=lambda i: (tss[i], i) if timed else (i,))
    nodes, by_guid, by_pid, keys, ended_guid = {}, {}, {}, [], {}
    for i in order:
        e, t = evs[i], (tss[i] if timed else i)
        g = _pt_guid(e.get("guid"))
        if e["event"] == "end":
            n = nodes.get(by_guid.get(g)) if g else None
            if n is None and e.get("pid") is not None:
                n = next((nodes[k] for k in reversed(by_pid.get(e["pid"], [])) if nodes[k]["end"] is None), None)
            if n is not None and n["end"] is None:
                n["end"] = t
            elif g:
                ended_guid[g] = t
            continue
        key = g if g and g not in by_guid else (e.get("pid"), e.get("ts") if e.get("ts") is not None else i)
        while key in nodes:
            key = (key, i)
        nodes[key] = {"key": key, "pid": e.get("pid"), "pid_raw": e.get("pid_raw"), "ppid": e.get("ppid"),
                      "ppid_raw": e.get("ppid_raw"), "image": e.get("image"), "cmdline": e.get("cmdline"),
                      "parent_image": e.get("parent_image"), "guid": g, "parent_guid": _pt_guid(e.get("parent_guid")),
                      "user": e.get("user"), "ts": e.get("ts"), "start": t, "end": None, "parent": None,
                      "orphan": None, "rec": e}
        keys.append(key)
        if g:
            by_guid.setdefault(g, key)
        if e.get("pid") is not None:
            by_pid.setdefault(e["pid"], []).append(key)
    children = {k: [] for k in keys}
    edges = []
    for k in keys:
        n = nodes[k]
        par, why = None, None
        pg = n["parent_guid"]
        if pg:
            pk = by_guid.get(pg)
            if pk is not None and pk != k and nodes[pk]["start"] <= n["start"]:
                par = pk
            else:
                why = "exited" if pg in ended_guid and ended_guid[pg] <= n["start"] else "missing"
        if par is None and not (pg and why) and n["ppid"] is not None:
            cands = [c for c in by_pid.get(n["ppid"], []) if c != k and nodes[c]["start"] <= n["start"]]
            alive = [c for c in cands if nodes[c]["end"] is None or nodes[c]["end"] >= n["start"]]
            if alive:
                par = alive[-1]
            else:
                why = "exited" if cands else "missing"
        n["parent"], n["orphan"] = par, (why if par is None else None)
        if par is not None:
            children[par].append(k)
            edges.append((par, k))
    parent = {k: nodes[k]["parent"] for k in keys}
    depth, chains = {}, {}
    for k in keys:
        ch, seen, c = [], set(), k
        while c is not None and c not in seen and len(ch) < 512:
            seen.add(c)
            ch.append(c)
            c = parent[c]
        depth[k] = len(ch) - 1
        if not children[k]:
            chains[k] = ch[::-1]
    roots = [k for k in keys if parent[k] is None]
    return {"nodes": nodes, "edges": edges, "roots": roots, "orphans": [k for k in keys if nodes[k]["orphan"]],
            "leaves": [k for k in keys if not children[k]], "children": children, "parent": parent, "depth": depth,
            "max_depth": max(depth.values()) if depth else 0, "chains": chains, "order": keys}


def process_chain(tree, node):
    """[root .. node] keys for any node (key, pid, guid or image basename resolving to one node)."""
    try:
        ks = _pt_find(tree, node)
        if len(ks) != 1:
            return []
        ch, c = [], ks[0]
        while c is not None and c not in ch and len(ch) < 512:
            ch.append(c)
            c = tree["parent"].get(c)
        return ch[::-1]
    except Exception:  # noqa: BLE001
        return []


def _pt_base(img):
    return re.split(r"[\\/]", str(img or "").rstrip("\\/"))[-1]


def _pt_find(tree, what):
    """Node keys matching `what`: a node key, guid, pid (int / '0x..' / decimal text), image basename or full path
    (case-insensitive); several matches in start order."""
    nodes = tree.get("nodes") or {}
    if what in nodes:
        return [what]
    if isinstance(what, dict) and what.get("key") in nodes:
        return [what["key"]]
    s = str(what if what is not None else "").strip()
    if not s:
        return []
    order = tree.get("order") or list(nodes)
    g = _pt_guid(s)
    hit = [k for k in order if g and nodes[k]["guid"] == g]
    if hit:
        return hit
    p = what if isinstance(what, int) else _pe_int(s)
    if p is not None:
        hit = [k for k in order if nodes[k]["pid"] == p]
        if hit:
            return hit
    low = s.lower()
    hit = [k for k in order if str(nodes[k]["image"] or "").lower() == low]
    return hit or [k for k in order if _pt_base(nodes[k]["image"]).lower() == _pt_base(s).lower()]


def _pt_repr(n, accepted=None):
    """A node in the answer's spelling: the accepted value it matches (basename / path / pid / guid, case-insensitive)
    or, with no accepted list, its image basename as logged (pid_raw when the image is unknown)."""
    if accepted:
        forms = {str(n.get("image") or "").lower(), _pt_base(n.get("image")).lower(), str(n.get("guid") or ""),
                 str(n.get("pid_raw") or "").lower(), str(n.get("pid") if n.get("pid") is not None else "")}
        if n.get("pid") is not None:
            forms.add(hex(n["pid"]))
        forms.discard("")
        for a in accepted:
            al = str(a).strip().lower()
            if al in forms or _pt_guid(al) in forms or (_pe_int(al) is not None and _pe_int(al) == n.get("pid")):
                return a
        return None
    return _pt_base(n.get("image")) or n.get("pid_raw") or (str(n["pid"]) if n.get("pid") is not None else None)


def process_tree_answer(tree, kind, accepted_values=None, what=None):
    """Answer a process-tree question. kind: root | leaf | parent(-of) | children(-of) | child-count | depth |
    max-depth | count | orphan | orphan-parent | chain | ancestor(s). `what` names the node (pid, guid, image
    basename or path; case-insensitive). Images compared case-insensitively, answered in the log's spelling (or the
    matching accepted value). One value -> str, several -> list in start order; chain -> [root..node]. 'none' when
    the field is absent (parent of a root, children of a leaf, no orphan), None when it cannot answer (unknown /
    ambiguous node, empty tree)."""
    try:
        if isinstance(tree, (bytes, bytearray, memoryview, str)) or isinstance(tree, list):
            tree = process_tree(tree)
        nodes = (tree or {}).get("nodes")
        if not nodes:
            return None
        acc = [a for a in (accepted_values or []) if str(a).strip()] or None
        kd = re.sub(r"[^a-z]", "", str(kind or "").lower()).replace("of", "") if kind else ""
        kd = {"parents": "parent", "child": "children", "kids": "children", "roots": "root", "leaves": "leaf",
              "leafs": "leaf", "orphans": "orphan", "ancestors": "chain", "ancestor": "chain", "ancestry": "chain",
              "lineage": "chain", "depthtree": "maxdepth", "treedepth": "maxdepth", "numchildren": "childcount",
              "childrencount": "childcount", "orphanparents": "orphanparent"}.get(kd, kd)

        def rep(keys):
            vals = []
            for k in keys:
                v = _pt_repr(nodes[k], acc)
                if v is not None and v not in vals:
                    vals.append(v)
            return vals

        def one(vals, absent="none"):
            return absent if not vals else vals[0] if len(vals) == 1 else vals

        def target():   # same image twice: answerable only when every match gives the same answer (below)
            return _pt_find(tree, what)
        if kd in ("root", "leaf", "orphan"):
            base = tree["roots"] if kd == "root" else tree["leaves"] if kd == "leaf" else tree["orphans"]
            if what is not None and kd == "root":
                ch = {process_chain(tree, k)[0] for k in target() if process_chain(tree, k)}
                base = [k for k in tree["order"] if k in ch]
            if kd == "orphan" and len(base) > 1 and not acc:
                ex = [k for k in base if nodes[k]["orphan"] == "exited"]
                base = ex or base
            return one(rep(base))
        if kd == "orphanparent":
            return one([v for v in dict.fromkeys(_pt_base(nodes[k]["parent_image"]) or nodes[k]["ppid_raw"]
                                                 for k in tree["orphans"]) if v])
        if kd == "count":
            w = str(what or "").lower()
            if not w or w in ("nodes", "processes", "process", "all"):
                return str(len(nodes))
            if w in ("roots", "orphans", "leaves", "edges"):
                return str(len(tree[w]))
            return str(len(_pt_find(tree, what)))
        if kd == "maxdepth" or (kd == "depth" and what is None):
            return str(tree["max_depth"])
        ks = target()
        if not ks:
            return None
        res = []
        for k in ks:
            if kd == "parent":
                p = tree["parent"][k]
                r = tuple(rep([p])) if p is not None else ("none",)
            elif kd == "children":
                r = tuple(rep(tree["children"][k])) or ("none",)
            elif kd == "childcount":
                r = (str(len(tree["children"][k])),)
            elif kd == "depth":
                r = (str(tree["depth"][k]),)
            elif kd == "chain":
                r = tuple(rep(process_chain(tree, k)))
            else:
                return None
            if r not in res:
                res.append(r)
        if len(res) != 1:
            return None
        r = list(res[0])
        if kd == "chain":
            return r
        return r[0] if len(r) == 1 else r
    except Exception:  # noqa: BLE001
        return None


def _proc_codecs(src, raw, _depth):
    """Codecs inside process-telemetry command lines (Sysmon 1 / 4688 XML, JSON, k=v): the log escapes the script's
    quotes (`&quot;`, `\\"`), so the descriptor only reads after process_events() unescapes each command line."""
    if not (_PE_HINT.search((src or "")[:1 << 20]) or _PL_HINT.search((src or "")[:1 << 20])):
        return []
    out, seen, t0 = [], set(), time.time()
    for e in process_events(raw if raw is not None else src):
        for c in (e.get("cmdline"), e.get("parent_cmdline")):
            if not c or len(c) < 16 or c in seen or time.time() - t0 > 1.0:
                continue
            seen.add(c)
            out += [dict(x, id=f"{x.get('id')}@proc") for x in find_codecs(c, _depth + 1) if x.get("plain")]
        if out:
            break
    return out


_RC_KINDS = ("ips", "user_agents", "file_names", "ports")
_RC_UA_FIELDS = re.compile(r"(?i)(?:^|_)(?:user_?agent|ua|agent)$")
_RC_PORT_FIELDS = re.compile(r"(?i)(?:^|_)(?:port|[lr]port|dst_?port|dest_?port|c2_?port)$")
_RC_IP_FIELDS = re.compile(r"(?i)(?:^|_)(?:ip|ipv[46]|addr(?:ess)?|dst|dest|c2|server|host|callback)(?:_ip|_addr)?$")
_RC_NAME_FIELDS = re.compile(r"(?i)^(?:file_?path|path|file|file_?name|filename|drop(?:_path|_file)?|"
                             r"dest(?:ination)?(?:_path)?|payload|stage|next_stage|dropper|"
                             r"(?:out|output|save|write|target|staging|stage|dropped|local)_?(?:path|file|name))$")
_RC_DFLT_PORT = {"http": 80, "https": 443, "ws": 80, "wss": 443, "ftp": 21}


def _rc_ip(v):
    """'10.0.0.5' / '[2001:db8::1]' / '::ffff:1.2.3.4' / '1.2.3.4:8080' / defanged '1[.]2[.]3[.]4' -> canonical IP, else None."""
    try:
        import ipaddress
        s = refang(str(v)).strip()
        if s.startswith("[") and "]" in s:
            s = s[1:s.index("]")]
        elif s.count(":") == 1 and "." in s:
            s = s.split(":", 1)[0]
        a = ipaddress.ip_address(s)
        if a.version == 6 and a.ipv4_mapped:
            a = a.ipv4_mapped
        return str(a)
    except Exception:  # noqa: BLE001
        return None


def _rc_cd_name(cd):
    """Content-Disposition value -> filename (filename*=UTF-8''x wins over filename=), else None."""
    if not cd:
        return None
    from urllib.parse import unquote
    m = re.search(r"(?i)filename\*\s*=\s*[\w\-]*'[^']*'([^;\s]+)", str(cd))
    if m:
        return unquote(m.group(1)).strip("\"'")
    m = re.search(r'(?i)filename\s*=\s*(?:"((?:[^"\\]|\\.)*)"|([^;\s]+))', str(cd))
    return (m.group(1) if m.group(1) is not None else m.group(2)).strip() if m else None


def _rc_basename(v, need_ext=True):
    s = str(v or "").strip().strip("\"'").split("?", 1)[0].split("#", 1)[0]
    b = re.split(r"[\\/]", s)[-1].strip()
    if not b or len(b) > 255 or (need_ext and not re.search(r"\.[A-Za-z0-9]{1,8}$", b)):
        return None
    return b


def _rc_url_bits(u):
    """URL -> (ip or None, port or None, basename or None) for the extra indicator kinds."""
    from urllib.parse import unquote
    scheme, host, port, rest = _rc_split(u)
    port = port if port is not None else _RC_DFLT_PORT.get(scheme)
    return _rc_ip(host), port, _rc_basename(unquote(rest.split("?", 1)[0]))


def _rc_kinds_declared(plans):
    """{kind: {canonical: (declared spelling, member)}} for ips / user_agents / file_names / ports."""
    out = {k: {} for k in _RC_KINDS}

    def add(kind, canon, val, m):
        if canon is not None and canon != "":
            out[kind].setdefault(canon, (val, m))
    for m in sorted(plans or {}):
        try:
            d = _rc_dict(plans[m])
        except Exception:  # noqa: BLE001
            continue
        for k, v in d.items():
            try:
                if not isinstance(v, (str, int)) or isinstance(v, bool):
                    continue
                f, v = _rc_field(k), str(v).strip()
                if not v:
                    continue
                r = refang(v)
                if _RC_URL.fullmatch(r):
                    ip, port, base = _rc_url_bits(r)
                    if ip:
                        add("ips", ip, _rc_split(r)[1], m)
                    if port:
                        add("ports", str(port), str(port), m)
                    if base:
                        add("file_names", base.lower(), base, m)
                    continue
                if _RC_UA_FIELDS.search(f):
                    add("user_agents", " ".join(v.split()), v, m)
                    continue
                if _RC_PORT_FIELDS.search(f) and re.fullmatch(r"\d{1,5}", v) and 0 < int(v) < 65536:
                    add("ports", str(int(v)), v, m)
                    continue
                ip = _rc_ip(r)
                if ip and (_RC_IP_FIELDS.search(f) or re.fullmatch(r"[\d.]+|\[?[0-9a-fA-F:.]+\]?", r)):
                    add("ips", ip, v, m)
                    mm = re.fullmatch(r"\[?[^\]]+\]?:(\d{1,5})", r)
                    if mm and ("." in r or r.startswith("[")):
                        add("ports", str(int(mm.group(1))), mm.group(1), m)
                    continue
                if _RC_NAME_FIELDS.match(f) and not re.match(r"(?i)^[a-z][a-z0-9+.\-]*://", r):
                    base = _rc_basename(v)
                    if base:
                        add("file_names", base.lower(), base, m)
            except Exception:  # noqa: BLE001
                continue
    return out


def _rc_kinds_observed(observed):
    """{kind: {canonical: observed spelling}} for ips / user_agents / file_names / ports from the evidence."""
    out = {k: {} for k in _RC_KINDS}
    try:
        recs = observed
        if isinstance(recs, dict):
            import json
            recs = network_indicators(json.dumps(recs)) if isinstance(recs.get("log"), dict) else [recs]
        elif isinstance(recs, (bytes, bytearray, memoryview, str)):
            recs = network_indicators(recs)
        if not isinstance(recs, (list, tuple, set)):
            return out
        for x in list(recs)[:200000]:
            if isinstance(x, str):
                r = refang(x)
                if _RC_URL.fullmatch(r):
                    x = {"kind": "http", "url": x}
                elif _rc_ip(x):
                    x = {"kind": "conn", "ip": x}
                else:
                    continue
            if not isinstance(x, dict):
                continue
            low = {_rc_field(k): v for k, v in x.items()}
            kind = str(low.get("kind") or "")
            ips = [low.get(k) for k in ("ip", "dest_ip", "destination_ip", "destinationip", "dst_ip", "id_resp_h",
                                        "serveripaddress", "server_ip", "s_ip") if low.get(k)]
            ans = low.get("answers") or ()
            ips += list(ans) if isinstance(ans, (list, tuple)) else str(ans).split(",")
            for a in ips:
                c = _rc_ip(a)
                if c:
                    out["ips"].setdefault(c, str(a).strip())
            url = low.get("url") or low.get("request_url") or low.get("full_uri")
            uport = ubase = None
            if url and _RC_URL.fullmatch(refang(str(url))):
                uip, uport, ubase = _rc_url_bits(refang(str(url)))
                if uip:
                    out["ips"].setdefault(uip, _rc_split(str(url))[1])
            elif low.get("uri"):
                ubase = _rc_basename(str(low["uri"]))
            ua = next((low[k] for k in ("user_agent", "useragent", "http_user_agent", "cs_user_agent")
                       if isinstance(low.get(k), str) and low[k].strip() not in ("", "-")), None)
            if ua:
                out["user_agents"].setdefault(" ".join(ua.split()), ua)
            if kind != "dns":
                p = next((low[k] for k in ("port", "dest_port", "destination_port", "destinationport", "dst_port",
                                           "id_resp_p") if low.get(k) not in (None, "", "-")), None) or uport
                if p is not None and re.fullmatch(r"\d{1,5}", str(p).strip()) and 0 < int(p) < 65536:
                    out["ports"].setdefault(str(int(p)), str(int(p)))
            names = [ubase] if ubase else []
            for k in ("filename", "file_name", "resp_filenames", "orig_filenames"):
                v = low.get(k)
                names += list(v) if isinstance(v, (list, tuple)) else str(v).split(",") if v else []
            cd = _rc_cd_name(low.get("content_disposition"))
            if cd:
                names.append(cd)
            for n in names:
                b = _rc_basename(n)
                if b:
                    out["file_names"].setdefault(b.lower(), b)
    except Exception:  # noqa: BLE001
        pass
    return out


# --- redirects + DNS resolution (prebuild http-redirect-dns-resolve) --------------------------------------------------
# "Where the requests actually went" can differ from the declared URL by a 30x Location hop or a CNAME. HAR
# (response.redirectURL / Location header + status), pcap HTTP responses (paired in order with the reverse flow's
# requests) and Zeek http status/location give url -> next url; DNS answers (pcap / Zeek / Sysmon EID 22) give
# host -> [CNAME .., A/AAAA]. reconcile() adds every redirect target as an observed URL (the observed-only value when no
# plan names it) and counts a declared URL as fetched when the evidence only shows a URL-less TLS / TCP connection to
# its host, a CNAME of it, or an IP it resolved to.
def _rd_join(url, loc, status=None):
    """Absolute redirect target of a response (Location resolved against the request URL), else None. A Location on a
    non-3xx status (201 Created, 200 with a stray header) is no redirect."""
    try:
        loc = str(loc or "").strip()
        st = str(status or "").strip()
        if not loc or loc == "-" or (st and st not in ("0", "-") and not re.fullmatch(r"30[0-35-8]", st)):
            return None
        if url and not re.match(r"(?i)^[a-z][a-z0-9+.\-]*://", loc):
            from urllib.parse import urljoin
            loc = urljoin(refang(str(url)), loc)
        return loc
    except Exception:  # noqa: BLE001
        return None


def _rd_records(observed):
    if isinstance(observed, dict):
        import json
        observed = json.dumps(observed) if isinstance(observed.get("log"), dict) else [observed]
    if isinstance(observed, (bytes, bytearray, memoryview, str)):
        return network_indicators(observed)
    return [x for x in observed if isinstance(x, dict)] if isinstance(observed, (list, tuple)) else []


def _rd_maps(observed):
    """-> (hops {canon url: (canon next url, next spelling, url spelling)}, alias {canon host: [CNAME / IP spellings]},
    host spellings {canon host: spelling}, dst {IPs reached by a URL-less TLS / TCP connection},
    reached {canon hosts named by a URL-less TLS / conn record})."""
    hops, alias, spell, dst, reached, named = {}, {}, {}, set(), set(), set()
    try:
        for x in _rd_records(observed)[:200000]:
            low = {_rc_field(k): v for k, v in x.items()}
            kind = str(low.get("kind") or "")
            url = low.get("url") or low.get("request_url") or low.get("full_uri")
            loc = next((low[k] for k in ("location", "redirect_url", "redirecturl", "redirect_location")
                        if isinstance(low.get(k), str)), None)
            nxt = _rd_join(url, loc, low.get("status") or low.get("status_code")) if url else None
            if nxt:
                cu, cn = canon_url(str(url)), canon_url(nxt)
                if cu and cn and cu != cn:
                    hops.setdefault(cu, (cn, nxt, str(url)))
            host = low.get("host") or low.get("query") or low.get("queryname")
            h = canon_host(str(host)) if host else None
            ans = low.get("answers") or ()
            ans = ans if isinstance(ans, (list, tuple)) else str(ans).split(",")
            if kind == "dns":
                for a in ans if h else ():
                    a = str(a).strip().rstrip(".")
                    if a and a not in alias.setdefault(h, []) and (_rc_ip(a) or canon_host(a)):
                        spell.setdefault(h, str(host))
                        alias[h].append(a)
                continue
            ip = _rc_ip(low.get("ip")) if low.get("ip") else None
            if kind == "conn" and not h:
                if ip:
                    dst.add(ip)
                continue
            if ip:
                named.add(ip)
            if kind in ("conn", "tls") or (kind == "http" and not url):
                if h and h != ip:
                    reached.add(h)
            elif kind == "http" and url and ip:   # HAR serverIPAddress / pcap dst: host -> ip
                hu = canon_host(str(url))
                if hu and hu != ip and ip not in alias.setdefault(hu, []):
                    spell.setdefault(hu, _rc_split(str(url))[1])
                    alias[hu].append(ip)
    except Exception:  # noqa: BLE001
        pass
    # a bare TCP connect only stands for a fetch when no URL / SNI-carrying record explains its IP (shared-IP hosts)
    return hops, alias, spell, dst - named, reached


def _rd_resolve(h, alias):
    """canon host -> [CNAME .., IP ..] spellings, following CNAME chains (bounded, loop-safe)."""
    out, todo, seen = [], [h], {h}
    while todo and len(seen) < 64:
        for a in alias.get(todo.pop(0), ()):
            c = _rc_ip(a) or canon_host(a)
            if c and c not in seen:
                seen.add(c)
                out.append(a)
                if not _rc_ip(a):
                    todo.append(c)
    return out


def _rd_chains(hops):
    out = {}
    for cu, (cn, nsp, sp) in hops.items():
        chain, seen = [], {cu}
        while cn and cn not in seen and len(chain) < 16:
            chain.append(nsp)
            seen.add(cn)
            cn, nsp = hops.get(cn, (None, None, None))[:2]
        out[sp] = chain
    return out


def resolve_chain(observed):
    """Network evidence (HAR / pcap / pcapng / Zeek / network_indicators() records) -> {url: [hop, .., final url]}:
    every request URL answered by a 30x redirect, mapped to the Location targets it leads through (relative Locations
    resolved against the request; loops cut). Spellings are the evidence's own. {} when nothing redirects."""
    try:
        return _rd_chains(_rd_maps(observed)[0])
    except Exception:  # noqa: BLE001
        return {}


def resolve_hosts(observed):
    """Network evidence -> {host: [CNAME .., A/AAAA ..]} from DNS answers (CNAME chains followed) and HAR / pcap
    request IPs. {} when nothing resolves."""
    try:
        _, alias, spell, _, _ = _rd_maps(observed)
        return {spell.get(h, h): r for h in alias for r in [_rd_resolve(h, alias)] if r}
    except Exception:  # noqa: BLE001
        return {}


def reconcile(plans, observed):
    """Declared fetch targets (decoded plans of every member) vs observed network evidence -> report, or None when
    either side is empty.
      hosts / urls   {declared_only, observed_only, both}: original spellings (declared side's spelling for `both`),
                     sorted by canonical form. URL level compares only records that carry a URL; DNS/TLS/conn records
                     confirm a host, never a URL.
      one_sided      urls.declared_only + urls.observed_only, or the host-level difference when the URL level is clean
      indicator      the single one-sided value (URL level first, then host level), else None
      members        {member: [declared values]}; member_of {declared value: member}
      unfetched      members with declared URLs none of which was observed (the fetch that never happened);
      unseen_hosts   members none of whose declared hosts shows up anywhere in the evidence
      stages         {stage name: observed URL value} for non-URL next_stage names seen as an observed URL basename
      ips / user_agents / file_names / ports
                     the same {declared_only, observed_only, both} shape for non-URL indicators: plan IP literals /
                     URL IP hosts vs conn/http dst + DNS A/AAAA answers; plan user_agent fields vs HAR / Zeek / W3C /
                     pcap User-Agent; plan file_path / next_stage / URL basenames vs observed URI basenames +
                     Content-Disposition / Zeek *_filenames; plan port fields + URL ports vs dst ports (DNS excluded).
                     Never part of one_sided / indicator (those stay URL / host).
      redirects      resolve_chain(): {request url: [Location hop, .., final url]}; every redirect target joins the
                     observed URLs (a target no plan names is observed-only)
      final_urls     {declared value: final url} for declared URLs that redirect
      resolved       {declared value: [CNAME .., IP ..]} from the evidence's DNS answers / request IPs
      fetched_via    {declared value: 'tls' | 'cname' | 'ip'}: declared URLs (hosts) with no URL-level evidence counted
                     as fetched (seen) through a URL-less TLS / TCP connection to the host, a CNAME of it, or an IP
                     it resolved to
      counts         sizes of every set above (+ <kind>_one_sided)"""
    try:
        dec, obs = declared_fetches(plans), observed_fetches(observed)
        xd, xo, xm = _rc_kinds_declared(plans), _rc_kinds_observed(observed), {}
        hops, alias, _, rd_dst, rd_reached = _rd_maps(observed)
        seen_u = {x["url"] for x in obs if x["url"]}
        for cu, (cn, nsp, _) in hops.items():   # a redirect target is where the request went, logged or not
            if cn not in seen_u:
                seen_u.add(cn)
                obs.append({"value": nsp, "url": cn, "host": canon_host(nsp), "kind": "redirect"})
        if not dec or not obs:
            if not (any(xd[k] for k in _RC_KINDS) and any(xo[k] for k in _RC_KINDS)):
                return None

        def sides(level):
            def spell(x):
                return _rc_split(x["value"])[1] if level == "host" and x["url"] else x["value"]
            d, o = {}, {}
            for x in dec:
                if x[level]:
                    d.setdefault(x[level], spell(x))
            for x in obs:
                if x[level]:
                    o.setdefault(x[level], spell(x))
            return {"declared_only": [d[k] for k in sorted(set(d) - set(o))],
                    "observed_only": [o[k] for k in sorted(set(o) - set(d))],
                    "both": [d[k] for k in sorted(set(d) & set(o))]}, set(d), set(o)

        # a declared URL with no URL-level evidence for its host still counts as fetched when a URL-less TLS / conn
        # record reached its host, a CNAME of it, or an IP it resolved to; a declared host whose CNAME is observed
        # counts as seen. Matching only: the declared spelling is reported, the CNAME / IP adds no observed value.
        url_hosts = {x["host"] for x in obs if x["url"]}
        obs_h = {x["host"] for x in obs if x["host"]}
        via, final, resolved = {}, {}, {}
        for x in dec:
            r = _rd_resolve(x["host"], alias) if x["host"] else []
            if r:
                resolved.setdefault(x["value"], r)
            cr = {_rc_ip(a) or canon_host(a) for a in r}
            if x["url"] and x["url"] not in seen_u and x["host"] not in url_hosts:
                if x["host"] in rd_reached or cr & rd_reached:
                    via[x["value"]] = "cname" if x["host"] not in rd_reached else "tls"
                elif cr & rd_dst:
                    via[x["value"]] = "ip"
                if x["value"] in via:
                    obs.append({"value": x["value"], "url": x["url"], "host": x["host"], "kind": "resolved"})
            elif x["host"] and not x["url"] and x["host"] not in obs_h and cr & obs_h:
                via[x["value"]] = "cname"
                obs.append({"value": x["value"], "url": None, "host": x["host"], "kind": "resolved"})
            if x["url"] in hops:
                cn, last, walked = hops[x["url"]][0], hops[x["url"]][1], {x["url"]}
                while cn in hops and cn not in walked and len(walked) < 17:
                    walked.add(cn)
                    cn, last = hops[cn][:2]
                final[x["value"]] = last
        urls, du, ou = sides("url")
        hosts, dh, oh = sides("host")
        one = urls["declared_only"] + urls["observed_only"]
        if not one:
            one = hosts["declared_only"] + hosts["observed_only"]
        members, member_of, unfetched, unseen = {}, {}, [], []
        for m in sorted({x["member"] for x in dec}):
            xs = [x for x in dec if x["member"] == m and (x["url"] or x["host"])]
            if not xs:
                continue
            members[m] = [x["value"] for x in xs]
            for x in xs:
                member_of.setdefault(x["value"], m)
            us = [x["url"] for x in xs if x["url"]]
            if us and not any(u in ou for u in us):
                unfetched.append(m)
            if not any(x["host"] in oh for x in xs if x["host"]):
                unseen.append(m)
        base = {}
        for x in obs:
            if x["url"]:
                base.setdefault(x["url"].split("?", 1)[0].rsplit("/", 1)[-1].lower(), x["value"])
        stages = {x["value"]: base[x["stage"]] for x in dec if x["stage"] and x["stage"] in base}
        rep = {"hosts": hosts, "urls": urls, "one_sided": one, "indicator": one[0] if len(one) == 1 else None,
               "members": members, "member_of": member_of, "unfetched": unfetched, "unseen_hosts": unseen,
               "stages": stages, "redirects": _rd_chains(hops), "final_urls": final, "resolved": resolved,
               "fetched_via": via}
        for lv in _RC_KINDS:
            d, o = {c: v for c, (v, _) in xd[lv].items()}, xo[lv]
            rep[lv] = {"declared_only": [d[k] for k in sorted(set(d) - set(o))],
                       "observed_only": [o[k] for k in sorted(set(o) - set(d))],
                       "both": [d[k] for k in sorted(set(d) & set(o))]}
            for v, m in xd[lv].values():
                member_of.setdefault(v, m)
        rep["counts"] = {f"{lv}_{k}": len(v) for lv in ("hosts", "urls") + _RC_KINDS for k, v in rep[lv].items()}
        rep["counts"].update(one_sided=len(one), unfetched=len(unfetched), unseen_hosts=len(unseen),
                             declared_members=len(members), redirects=len(rep["redirects"]),
                             final_urls=len(final), fetched_via=len(via))
        rep["counts"].update({f"{lv}_one_sided": len(rep[lv]["declared_only"]) + len(rep[lv]["observed_only"])
                              for lv in _RC_KINDS})
        return rep
    except Exception:  # noqa: BLE001
        return None


def reconcile_answer(report, kind, accepted_values=None, what="indicator"):
    """One GM answer from a reconcile() report.
      exact_text  what='indicator' (the one-sided value), or '<level>.<side>' e.g. 'urls.observed_only' /
                  'hosts.declared_only' (its single value)
      enum        the member whose fetch never happened (what='unfetched' / 'unseen_hosts'), or the member that
                  declared the one-sided indicator; matched to accepted_values by name or stem
      integer     counts[what] (what='indicator' -> one_sided)
      redirects / final_urls / resolved / fetched_via: exact_text the final hop (last CNAME / IP for `resolved`,
                  the via-kind for `fetched_via`) of the single entry, integer the entry count, enum its member
      ips / user_agents / file_names / ports: what='<kind>.<side>' (e.g. 'user_agents.observed_only') or '<kind>'
                  alone (declared_only + observed_only); exact_text its single value, integer its size, enum the
                  member that declared it
    "none" when the requested set is empty; None when unanswerable (no report, or several candidates)."""
    try:
        if not report:
            return None
        lv0 = what.partition(".")[0]
        if lv0 in ("redirects", "final_urls", "resolved", "fetched_via"):
            vals = report.get(lv0) or {}
            if kind == "integer":
                return str(len(vals))
            if not vals:
                return "none" if kind != "enum" else None
            if len(vals) != 1:
                return None
            k0, v = next(iter(vals.items()))
            if kind == "enum":
                m = report["member_of"].get(k0)
                return next((a for a in accepted_values or () if str(a) == m), None if accepted_values else m)
            return (v[-1] if v else None) if isinstance(v, list) else v
        if lv0 in _RC_KINDS:
            lv, _, side = what.partition(".")
            if lv not in report:
                return None
            vals = report[lv][side] if side else report[lv]["declared_only"] + report[lv]["observed_only"]
            if kind == "integer":
                return str(len(vals))
            if not vals:
                return "none" if kind != "enum" else None
            if len(vals) != 1:
                return None
            if kind != "enum":
                return vals[0]
            m = report["member_of"].get(vals[0])
            if not m:
                return None
            stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).replace("\\", "/").rsplit("/", 1)[-1]).lower()
            for a in accepted_values or ():
                if str(a) == m or stem(a) == stem(m):
                    return a
            return None if accepted_values else m
        if kind == "integer":
            return str(report["counts"]["one_sided" if what == "indicator" else what])
        if kind == "enum":
            if what in ("unfetched", "unseen_hosts"):
                ms = report[what]
            else:
                ind = report["indicator"]
                ms = [report["member_of"][ind]] if ind in report["member_of"] else []
            if not ms:
                return "none" if what in ("unfetched", "unseen_hosts") else None
            if len(ms) != 1:
                return None
            m = ms[0]
            stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).replace("\\", "/").rsplit("/", 1)[-1]).lower()
            for a in accepted_values or ():
                if str(a) == m or stem(a) == stem(m):
                    return a
            return None if accepted_values else m
        if what == "indicator":
            vals = report["one_sided"]
        else:
            lv, _, side = what.partition(".")
            vals = report[lv][side]
        if not vals:
            return "none"
        return vals[0] if len(vals) == 1 else None
    except Exception:  # noqa: BLE001
        return None


# --- download / handoff graph (cross-file) ---------------------------------------------------------------------------
_DG_FILE_FIELDS = re.compile(r"(?i)^(?:file_?path|path|file|drop(?:_path|_file)?|dest(?:ination)?(?:_path)?|"
                             r"(?:out|output|save|write|target|staging|stage|dropped|local)_?(?:path|file))$")
_DG_STEP_FETCH = re.compile(r"(?i)acquire_remote|http_client|download|fetch|web_request|remote_fetch")
_DG_STEP_WRITE = re.compile(r"(?i)write_file|drop_file|save_file|write_disk|write_stage")


def _dg_member(d):
    """One decoded plan dict -> {language, next_language, next_stage, urls:[(field, value)], file_paths, steps, ...}."""
    low = {}
    for k, v in d.items():
        if isinstance(v, (list, tuple)) and k.lower() == "steps":
            v = ",".join(str(x) for x in v)
        if isinstance(v, (str, int, float)) and not isinstance(v, bool) and str(v).strip():
            low.setdefault(_rc_field(k), str(v).strip())
    r = {"language": low.get("language"), "next_language": low.get("next_language"),
         "next_stage": low.get("next_stage"), "urls": [], "file_paths": [], "steps": [],
         "stage_count": int(low["stage_count"]) if re.fullmatch(r"\d{1,4}", low.get("stage_count", "")) else None}
    r["steps"] = [s for s in re.split(r"[\s,;>|]+", low.get("steps", "")) if s]
    for f, v in low.items():
        u = refang(v)
        if f != "next_stage" and _RC_URL.fullmatch(u) and canon_url(u):
            r["urls"].append((f, v))
        elif _DG_FILE_FIELDS.match(f) and re.search(r"[\\/]|\.\w{1,6}$", v) and not _RC_URL.match(u):
            r["file_paths"].append(v)
    return r


def _dg_walk(edges):
    """{src: [dst..]} -> the single linear path from the unique root covering every node, else None."""
    nodes = set(edges) | {d for ds in edges.values() for d in ds}
    if not nodes or any(len(set(ds)) > 1 for ds in edges.values()):
        return None
    has_in = {d for ds in edges.values() for d in ds}
    roots = [n for n in nodes if n not in has_in]
    if len(roots) != 1:
        return None
    out, n = [], roots[0]
    while n is not None and n not in out:
        out.append(n)
        n = (edges.get(n) or [None])[0]
    return out if len(out) == len(nodes) else None


def download_graph(plans):
    """{member: decoded plan (dict / 'k=v|..' / JSON)} -> cross-file download/handoff graph report, or None when no
    plan carries a url / file_path / next_language / next_stage.
      members       {member: {language, next_language, next_stage, urls, hosts, file_paths, steps, stage_count}}
      edges         [{src, dst, kind}] kind: fetch (member->url; upload for upload_url / exfil fields), write
                    (url->file_path, or member->file_path when the member fetches nothing), handoff
                    (member->next_language), stage (member->next_stage)
      chain         languages in order following language -> next_language across files (None unless one linear path)
      member_chain  members in order: next_stage naming a member (name / stem), else the one member whose language is
                    the next_language (None unless one linear path); root / leaf = its ends (falls back to the
                    single member of the chain's first / last language)
      unique        {url, host, file_path: [members holding a value no other member shares]} -- only filled when at
                    least one value IS shared (otherwise "unique" means nothing); shared {kind: [values]}
      counts        members, urls, hosts, file_paths, languages, stages, edges, <kind>_edges, chain_length,
                    member_chain_length, stage_count_sum, stage_count_max"""
    try:
        mem = {}
        for m in sorted(plans or {}):
            try:
                g = _dg_member(_rc_dict(plans[m]))
            except Exception:  # noqa: BLE001
                continue
            if g["urls"] or g["file_paths"] or g["next_language"] or g["next_stage"]:
                g["hosts"] = sorted({canon_host(refang(v)) for _, v in g["urls"]} - {None})
                mem[m] = g
        if not mem:
            return None
        edges = []
        for m, g in mem.items():
            fetch = [v for f, v in g["urls"] if not re.search(r"upload|exfil|post|beacon|callback", f)]
            for f, v in g["urls"]:
                edges.append({"src": m, "dst": v, "kind": "fetch" if v in fetch else "upload"})
            writes = not g["steps"] or any(_DG_STEP_WRITE.search(s) for s in g["steps"])
            for p in g["file_paths"]:
                if writes and len(fetch) == 1:
                    edges.append({"src": fetch[0], "dst": p, "kind": "write"})
                else:
                    edges.append({"src": m, "dst": p, "kind": "write"})
            if g["next_language"]:
                edges.append({"src": m, "dst": g["next_language"], "kind": "handoff"})
            if g["next_stage"]:
                edges.append({"src": m, "dst": g["next_stage"], "kind": "stage"})
        # language chain (case-insensitive, first spelling kept); self-handoffs (same_language) are not chain links
        spell, lang_e = {}, {}
        for g in mem.values():
            a, b = g["language"], g["next_language"]
            for x in (a, b):
                if x:
                    spell.setdefault(x.lower(), x)
            if a and b and a.lower() != b.lower():
                lang_e.setdefault(a.lower(), [])
                if b.lower() not in lang_e[a.lower()]:
                    lang_e[a.lower()].append(b.lower())
        lw = _dg_walk(lang_e)
        chain = [spell[x] for x in lw] if lw else None
        # member chain
        stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).replace("\\", "/").rsplit("/", 1)[-1]).lower()
        by_name = {}
        for m in mem:
            for k in (m.lower(), m.replace("\\", "/").rsplit("/", 1)[-1].lower(), stem(m)):
                by_name.setdefault(k, set()).add(m)
        by_lang = {}
        for m, g in mem.items():
            if g["language"]:
                by_lang.setdefault(g["language"].lower(), set()).add(m)
        mem_e = {}
        for m, g in mem.items():
            nxt = None
            ns = (g["next_stage"] or "").replace("\\", "/").rsplit("/", 1)[-1].lower()
            for k in (ns, stem(ns)) if ns else ():
                if len(by_name.get(k, ())) == 1:
                    nxt = next(iter(by_name[k]))
                    break
            nl = (g["next_language"] or "").lower()
            if nxt is None and nl and nl != (g["language"] or "").lower() and len(by_lang.get(nl, ())) == 1:
                nxt = next(iter(by_lang[nl]))
            if nxt and nxt != m:
                mem_e[m] = [nxt]
        mchain = _dg_walk(mem_e)
        if mchain and len(mchain) < 2:
            mchain = None
        root = leaf = None
        if mchain:
            root, leaf = mchain[0], mchain[-1]
        elif chain:
            r0, l0 = by_lang.get(chain[0].lower(), set()), by_lang.get(chain[-1].lower(), set())
            root = next(iter(r0)) if len(r0) == 1 else None
            leaf = next(iter(l0)) if len(l0) == 1 else None
        unique, shared = {}, {}
        for kind, get in (("url", lambda g: [v for _, v in g["urls"]]), ("host", lambda g: g["hosts"]),
                          ("file_path", lambda g: g["file_paths"])):
            key = (lambda v: canon_url(refang(v))) if kind == "url" else (lambda v: str(v).lower())
            hold = {}
            for m, g in mem.items():
                for v in get(g):
                    hold.setdefault(key(v), (v, set()))[1].add(m)
            shared[kind] = sorted(v for v, ms in hold.values() if len(ms) > 1)
            have = [m for m, g in mem.items() if get(g)]
            unique[kind] = (sorted(m for m in have if any(len(hold[key(v)][1]) == 1 for v in get(mem[m])))
                            if shared[kind] else [])
        sc = [g["stage_count"] for g in mem.values() if g["stage_count"] is not None]
        all_urls = {canon_url(refang(v)) for g in mem.values() for _, v in g["urls"]}
        rep = {"members": mem, "edges": edges, "chain": chain, "member_chain": mchain, "root": root, "leaf": leaf,
               "unique": unique, "shared": shared}
        counts = {"members": len(mem), "urls": len(all_urls - {None}),
                  "hosts": len({h for g in mem.values() for h in g["hosts"]}),
                  "file_paths": len({p.lower() for g in mem.values() for p in g["file_paths"]}),
                  "languages": len(spell), "stages": len({g["next_stage"].lower() for g in mem.values()
                                                          if g["next_stage"]}),
                  "edges": len(edges), "chain_length": len(chain or ()), "member_chain_length": len(mchain or ()),
                  "stage_count_sum": sum(sc), "stage_count_max": max(sc) if sc else 0}
        for k in ("fetch", "upload", "write", "handoff", "stage"):
            counts[f"{k}_edges"] = sum(1 for e in edges if e["kind"] == k)
        rep["counts"] = counts
        return rep
    except Exception:  # noqa: BLE001
        return None


def download_graph_answer(report, kind, what="chain", accepted_values=None, sep=">"):
    """One GM answer from a download_graph() report.
      ordered_tokens  what='chain' (languages) / 'member_chain', joined with `sep`
      integer         counts[what] (e.g. 'hosts', 'edges', 'fetch_edges', 'stages', 'chain_length')
      enum            what='root' / 'leaf' (member at the chain's ends), 'unique_url' / 'unique_host' /
                      'unique_file_path' (the one member whose value nobody shares), 'root_language' /
                      'leaf_language'; matched to accepted_values by name, stem or case
      exact_text      '<root|leaf>.<url|host|file_path|next_stage|next_language|language>' (that member's single value)
    None when unanswerable (no report, no single linear chain, several candidates)."""
    try:
        if not report:
            return None
        stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).replace("\\", "/").rsplit("/", 1)[-1]).lower()

        def pick(v):
            if v is None:
                return None
            for a in accepted_values or ():
                if str(a) == v or str(a).lower() == str(v).lower() or stem(a) == stem(v):
                    return a
            return None if accepted_values else v
        if kind == "integer":
            return str(report["counts"][what]) if what in report["counts"] else None
        if kind == "ordered_tokens":
            ch = report.get("member_chain" if what == "member_chain" else "chain")
            return sep.join(ch) if ch else None
        if kind == "enum":
            if what in ("root", "leaf"):
                return pick(report[what])
            if what in ("root_language", "leaf_language"):
                ch = report.get("chain")
                return pick(ch[0 if what == "root_language" else -1]) if ch else None
            if what.startswith("unique_"):
                ms = report["unique"].get(what[len("unique_"):]) or []
                return pick(ms[0]) if len(ms) == 1 else None
            return None
        end, _, fld = what.partition(".")
        m = report.get(end) if end in ("root", "leaf") else None
        g = report["members"].get(m) if m else None
        if not g:
            return None
        vals = ([v for _, v in g["urls"]] if fld == "url" else g["hosts"] if fld == "host" else
                g["file_paths"] if fld == "file_path" else [g.get(fld)] if g.get(fld) else [])
        return vals[0] if len(vals) == 1 else None
    except Exception:  # noqa: BLE001
        return None


# --- declared (static) process tree: who the source says spawns whom ------------------------------------------------
# parent = the member's host interpreter (host_profile first, then language, then file extension); plan edges come from
# next_language when the steps dispatch a process / language / script; code edges from the spawn call sites in the
# member's own CODE, with arguments rebuilt by the fetch_sites literal folder (_fs_env / _fs_eval).
PT_LANG_IMAGE = {
    "jscript": "wscript.exe", "vbscript": "wscript.exe", "wsf": "wscript.exe", "jse": "wscript.exe",
    "vbe": "wscript.exe", "wsh": "wscript.exe", "hta": "mshta.exe", "batch": "cmd.exe", "cmd": "cmd.exe",
    "bat": "cmd.exe", "powershell": "powershell.exe", "pwsh": "pwsh.exe", "python": "python.exe",
    "javascript": "node.exe", "node": "node.exe", "nodejs": "node.exe", "typescript": "node.exe", "perl": "perl.exe",
    "ruby": "ruby.exe", "lua": "lua.exe", "php": "php.exe", "auto_hotkey": "AutoHotkey64.exe",
    "autohotkey": "AutoHotkey64.exe", "ahk": "AutoHotkey64.exe", "autoit": "AutoIt3.exe", "au3": "AutoIt3.exe",
    "applescript": "osascript", "msbuild_xml": "MSBuild.exe", "msbuild": "MSBuild.exe", "sct": "regsvr32.exe",
    "scriptlet": "regsvr32.exe", "wmi_mof": "scrcons.exe", "mof": "scrcons.exe", "bash": "bash", "sh": "sh",
    "zsh": "zsh", "tcl": "tclsh", "google_apps_script": "apps_script", "xsl": "msxsl.exe", "xslt": "msxsl.exe",
}
PT_EXT_LANG = {
    "js": "jscript", "jse": "jscript", "vbs": "vbscript", "vbe": "vbscript", "wsf": "wsf", "hta": "hta",
    "bat": "batch", "cmd": "batch", "ps1": "powershell", "psm1": "powershell", "psd1": "powershell", "py": "python",
    "pyw": "python", "mjs": "javascript", "cjs": "javascript", "ts": "typescript", "pl": "perl", "pm": "perl",
    "rb": "ruby", "lua": "lua", "php": "php", "ahk": "auto_hotkey", "au3": "autoit", "applescript": "applescript",
    "scpt": "applescript", "proj": "msbuild_xml", "csproj": "msbuild_xml", "targets": "msbuild_xml", "sct": "sct",
    "mof": "wmi_mof", "sh": "bash", "bash": "bash", "zsh": "zsh", "gs": "google_apps_script", "tcl": "tcl",
    "xsl": "xsl", "exe": None,
}
PT_HOST_IMAGE = (   # host_profile (prefix / pattern) -> the process that hosts the member
    (r"^wsf|^wsh|^wscript", "wscript.exe"), (r"^cscript", "cscript.exe"), (r"^hta|mshta", "mshta.exe"),
    (r"^sct|scriptlet|regsvr32", "regsvr32.exe"), (r"php[_-]?(?:webshell|cgi|fpm)", "php-cgi.exe"),
    (r"perl[_-]?cgi", "perl.exe"), (r"ruby[_-]?rack", "ruby.exe"), (r"openresty|nginx", "nginx.exe"),
    (r"google|apps?_?script|sidebar", "apps_script"), (r"msbuild", "MSBuild.exe"),
    (r"wmi|mof", "scrcons.exe"), (r"office|vba|macro|word|excel", "winword.exe"),
)
_PT_DISPATCH = re.compile(r"(?i)^(?:dispatch_(?:process|language|next_stage|script)|handoff_\w+|launch_\w+|"
                          r"execute_(?:process|stage|file)|spawn_\w+|run_(?:process|stage|file))$")
_PT_EXE = re.compile(r"""(?i)^\s*["']?((?:[A-Za-z]:)?[^\s"'|&;<>]*?([^\\/\s"'|&;<>]+))["']?(?:\s|$)""")
_PT_SITES = (   # (api, regex, kind, source gate) kind: call (first arg = cmdline), se (file + args), cmd (rest of line)
    ("WScript.Shell.Run", re.compile(r"(?i)\.Run\s*\(?"), "call", "wscript.shell"),
    ("WScript.Shell.Exec", re.compile(r"(?i)\.Exec\s*\(?"), "call", "wscript.shell"),
    ("ShellExecute", re.compile(r"(?i)\bShellExecute(?:Wait)?\s*\(?"), "se", ""),
    ("Win32_Process.Create", re.compile(r"(?i)\.Create\s*\("), "call", "win32_process"),
    ("Start-Process", re.compile(r"(?i)(?:^|(?<=[\s;|({]))(?:Start-Process|saps)\b"), "ps", ""),
    ("child_process", re.compile(r"\b(?:spawnSync|spawn|execFileSync|execFile|execSync|exec|fork)\s*\("), "call",
     "child_process"),
    ("subprocess", re.compile(r"\bsubprocess\.(?:run|call|Popen|check_call|check_output|getoutput)\s*\("), "call", ""),
    ("os.system", re.compile(r"\bos\.(?:system|popen|startfile|exec[lv]p?e?|spawn[lv]p?e?)\s*\("), "call", ""),
    ("os.execute", re.compile(r"\b(?:os\.execute|io\.popen)\s*\("), "call", ""),
    ("system", re.compile(r"(?<![\w.$>:])(?:system|exec|shell_exec|passthru|popen|proc_open|spawn|IO\.popen|"
                          r"Open3\.\w+)\s*\(?(?=\s*[\"'(\[$@%])"), "call", ""),
    ("qx", re.compile(r"(?<![\w$@%])(?:qx|%x)\s*([{(\[<|/!])"), "qx", ""),
    ("backticks", re.compile(r"(?<![\w\\])`(?=[^`\n]*\b(?:cmd|powershell|pwsh|cscript|wscript|mshta|python|node|perl|"
                             r"ruby|bash|sh|curl|wget)\b)"), "bt", ""),
    ("Run", re.compile(r"(?im)^\s*(?:\w+\s*:?=\s*)?Run(?:Wait)?\b\s*[,(]?"), "call", ""),
    ("do shell script", re.compile(r"(?i)\bdo\s+shell\s+script\s+"), "call", ""),
    ("MSBuild.Exec", re.compile(r"""(?i)<Exec\b[^>]*?\bCommand\s*=\s*(?=["'])"""), "call", ""),
    ("cmd /c", re.compile(r"(?i)(?:^|(?<=[\s(;&|@]))cmd(?:\.exe)?\s+(?=/[ckCK]\b)"), "cmd", ""),
    ("start", re.compile(r"(?im)^\s*@?start\s+"), "cmd", ""),
    ("schtasks /create", re.compile(r"(?i)\bschtasks(?:\.exe)?\s+(?=/create\b)"), "cmd", ""),
    ("wmic process call create", re.compile(r"(?i)\bwmic(?:\.exe)?\s+(?=process\s+call\s+create\b)"), "cmd", ""),
)
_PT_INTERP_LINE = re.compile(r"(?im)^\s*@?(?:call\s+)?(?P<img>(?:[\w.\\:/-]*[\\/])?(?:powershell|pwsh|cscript|wscript|"
                             r"mshta|rundll32|regsvr32|msbuild|python3?|node|perl|ruby|lua|php|osascript|bash|sh)"
                             r"(?:\.exe)?)\s+(?=\S)")


_PT_SHELLWIN = re.compile(r"(?i)\bShell(?:Windows|BrowserWindow)\b|9BA05972-F6A8-11CF-A442-00A0C90A8F39|"
                          r"C08AFD90-F2A1-11D1-8455-00A0C91F3880")
_PT_PROXY_GATE = re.compile(r"(?i)ExecuteShellCommand|\bsc(?:\.exe)?\s+(?:\\\\\S+\s+)?create\b|New-Service|"
                            r"New-ScheduledTaskAction|CommandLineTemplate")


def pt_image(language=None, host_profile=None, member=""):
    """Host process image for a member: host_profile pattern, else language, else the file extension; None unknown."""
    hp = str(host_profile or "").strip().lower()
    if hp and hp not in ("standalone", "none", "native", "local", "default"):
        for rx, img in PT_HOST_IMAGE:
            if re.search(rx, hp):
                return img
        for tok in re.split(r"[_\-\s]+", hp):
            if tok in PT_LANG_IMAGE and tok not in ("javascript", "jscript", "vbscript", "mixed"):
                return PT_LANG_IMAGE[tok]
    lang = re.sub(r"[^0-9a-z]+", "_", str(language or "").strip().lower()).strip("_")
    if lang in PT_LANG_IMAGE:
        return PT_LANG_IMAGE[lang]
    ext = str(member or "").rsplit(".", 1)[-1].lower() if "." in str(member or "") else ""
    lang = PT_EXT_LANG.get(ext)
    return PT_LANG_IMAGE.get(lang) if lang else None


def _pt_child(cmdline):
    """First program of a command line -> its image (a script path maps to its host interpreter)."""
    m = _PT_EXE.match(cmdline or "")
    if not m:
        return None
    base = m.group(2).strip().rstrip(",)")
    if not base or not re.search(r"[A-Za-z]", base):
        return None
    ext = base.rsplit(".", 1)[-1].lower() if "." in base else ""
    if ext in PT_EXT_LANG and ext != "exe" and PT_EXT_LANG[ext]:
        return PT_LANG_IMAGE.get(PT_EXT_LANG[ext])
    low = base.lower()
    if not ext and low in ("powershell", "pwsh", "cscript", "wscript", "mshta", "cmd", "rundll32", "regsvr32",
                           "msbuild", "schtasks", "wmic", "msiexec", "certutil", "bitsadmin", "python", "node"):
        return low + ".exe"
    return base


def _pt_in_string(line, col):
    """True when column `col` of `line` sits inside a quoted literal (crude, per line)."""
    q = None
    i = 0
    while i < col and i < len(line):
        c = line[i]
        if q:
            if c == "\\" and q != "'":
                i += 1
            elif c == q:
                q = None
        elif c in "\"'":
            q = c
        i += 1
    return q is not None


def _pt_value(expr, env, text):
    """Rebuild one argument: the full folded literal, else the head literal of the variable's first assignment."""
    expr = (expr or "").strip()
    v = _fs_eval(expr, env)
    if v is not None:
        return v, True
    head = re.match(r"[$@%]?\{?([A-Za-z_]\w*)", expr)
    if head:
        am = re.search(r"(?m)(?:^|[\s;(,])[$]?" + re.escape(head.group(1)) + r"\s*(?::=|=)(?!=)\s*", text)
        if am:
            lm = _FS_LIT.match(text, am.end())
            if lm:
                lit = lm.group("d") if lm.group("d") is not None else lm.group("s") if lm.group("s") is not None \
                    else lm.group("t")
                return _fs_unescape(lit or ""), False
    lm = _FS_LIT.match(expr)
    if lm:
        lit = lm.group("d") if lm.group("d") is not None else lm.group("s") if lm.group("s") is not None \
            else lm.group("t")
        return _fs_unescape(lit or ""), False
    return None, False


def _pt_ps_args(args, env, text):
    """Start-Process [-FilePath] X [-ArgumentList] Y -> 'X Y'."""
    toks = _fs_split(args, re.compile(r"\s+")) or []
    named, pos, i = {}, [], 0
    while i < len(toks):
        t = toks[i]
        if t.startswith("-") and re.fullmatch(r"-\w+", t):
            n = t[1:].lower()
            if n in ("wait", "nonewwindow", "passthru", "usenewenvironment") or i + 1 >= len(toks):
                i += 1
                continue
            named[n] = toks[i + 1]
            i += 2
            continue
        pos.append(t)
        i += 1
    fp = next((named[k] for k in named if "filepath".startswith(k) or k in ("path", "fp")), pos[0] if pos else None)
    al = next((named[k] for k in named if "argumentlist".startswith(k) or k == "args"), pos[1] if len(pos) > 1 else None)
    f, ok = _pt_value(fp, env, text) if fp else (None, False)
    if f is None:
        return None, False
    if al:
        if "," in al and al.strip()[:2] != "@(":
            parts = [_pt_value(p, env, text) for p in (_fs_split(al, _FS_COMMA) or [al])]
            a = " ".join(p for p, _ in parts if p is not None)
            ok = ok and all(o for _, o in parts)
        else:
            a, o = _pt_value(re.sub(r"^@\((.*)\)$", r"\1", al.strip(), flags=re.S), env, text)
            ok = ok and o
        return f + (" " + a if a else ""), ok
    return f, ok


def code_spawns(src, name="", parent=None):
    """Process-creation call sites in a script's CODE -> [{api, parent_image, child_image, cmdline, line, folded}] in
    source order. `cmdline` is rebuilt from the file's own literals (None when runtime data); `folded` False when only
    the head literal was recovered. Comment / echo lines and call heads inside string literals are skipped; a
    Win32_Process.Create / wmic / schtasks /tr child is parented to WmiPrvSE.exe / svchost.exe (plus the member ->
    wmic.exe / schtasks.exe edge). [] for unreadable input."""
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            src = (b.decode("utf-16", "replace") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else
                   b.decode("utf-8-sig", "replace"))
        text = _fs_flat(str(src or "")[:1_000_000])
        low = text.lower()
        if not parent and re.search(r"\brequire\s*\(|\bchild_process\b|^\s*import\s.+\bfrom\s", text, re.M) and \
                str(name or "").lower().endswith((".js", ".mjs", ".cjs", ".ts")):
            parent = "node.exe"
        parent = parent or pt_image(member=name)
        env = _fs_env(text)
        lines = text.split("\n")
        starts = [0]
        for ln in lines:
            starts.append(starts[-1] + len(ln) + 1)
        import bisect
        ext = str(name or "").rsplit(".", 1)[-1].lower()
        out, seen = [], set()

        def add(api, par, cmd, lno, folded, child=None):
            child = child or _pt_child(cmd)
            if not child:
                return
            key = (lno, child.lower(), api)
            if key in seen:
                return
            seen.add(key)
            out.append({"api": api, "parent_image": par, "child_image": child,
                        "cmdline": cmd.strip() if cmd and folded else None, "line": lno, "folded": bool(folded)})

        sites = list(_PT_SITES)
        if ext in ("bat", "cmd") or parent == "cmd.exe":
            sites.append(("direct", _PT_INTERP_LINE, "cmd", ""))
        for api, rx, kind, gate in sites:
            if gate and gate not in low:
                continue
            for m in rx.finditer(text):
                if len(out) > 200:
                    break
                lno = bisect.bisect_right(starts, m.start())
                line = lines[lno - 1]
                col = m.start() - starts[lno - 1]
                if _FS_COMMENT.match(line) or _FS_ECHO.match(line) and kind != "cmd":
                    continue
                if kind not in ("qx", "bt") and _pt_in_string(line, col) and not (
                        kind == "cmd" and ext in ("bat", "cmd")):
                    continue
                if api == "Run" and not (ext in ("ahk", "au3") or "autoit" in low or "#requires autohotkey" in low):
                    continue
                if api == "system" and ext in ("js", "mjs", "cjs", "ts", "ps1", "vbs") and "child_process" not in low:
                    continue
                cmd, folded = None, False
                if kind == "qx":
                    close = {"{": "}", "(": ")", "[": "]", "<": ">"}.get(m.group(1), m.group(1))
                    j = text.find(close, m.end())
                    if j < 0 or "\n" in text[m.end():j]:
                        continue
                    cmd, folded = text[m.end():j], True
                elif kind == "bt":
                    j = text.find("`", m.end())
                    if j < 0:
                        continue
                    cmd, folded = text[m.end():j], True
                elif kind == "cmd":
                    rest = line[col + (m.end() - m.start()):]
                    rest = re.sub(r"%(\w+)%|!(\w+)!", lambda mm: _fs_lookup(mm.group(1) or mm.group(2), env)
                                  or mm.group(0), rest).strip()
                    if api == "direct":
                        cmd, folded = m.group("img") + " " + rest, True
                        add(api, parent, cmd, lno, folded)
                        continue
                    if api == "cmd /c":
                        add(api, parent, "cmd.exe " + rest, lno, True, child="cmd.exe")
                        continue
                    if api == "start":
                        rest = re.sub(r'^(?:"[^"]*"\s+)?(?:/\w+\s+)*', "", rest)
                        add(api, parent, rest, lno, True)
                        continue
                    if api == "schtasks /create":
                        add(api, parent, "schtasks.exe " + rest, lno, True, child="schtasks.exe")
                        tm = re.search(r"""(?i)/tr\s+(?:"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+))""", rest)
                        if tm:
                            tr = (tm.group(1) or tm.group(2) or tm.group(3) or "").replace('\\"', '"')
                            add("schtasks /tr", "svchost.exe", tr, lno, True)
                        continue
                    if api == "wmic process call create":
                        add(api, parent, "wmic.exe " + rest, lno, True, child="wmic.exe")
                        cm = re.search(r"""(?i)\bcreate\s+(?:"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+))""", rest)
                        if cm:
                            add("Win32_Process.Create", "WmiPrvSE.exe", cm.group(1) or cm.group(2) or cm.group(3),
                                lno, True)
                        continue
                    continue
                else:
                    args = _fs_args(text, m.end())
                    if args is None:
                        continue
                    if kind == "ps":
                        cmd, folded = _pt_ps_args(args, env, text)
                    else:
                        items = _fs_split(args, _FS_COMMA) or [args]
                        if api == "child_process" and items and items[0].strip()[:1] in "[":
                            items = [items[0].strip()[1:]]
                        if api in ("subprocess", "system", "os.system") and items and items[0].strip()[:1] == "[":
                            inner = items[0].strip()[1:].rsplit("]", 1)[0]
                            parts = [_pt_value(p, env, text) for p in (_fs_split(inner, _FS_COMMA) or [inner])]
                            if parts and parts[0][0] is not None:
                                cmd = " ".join(p for p, _ in parts if p is not None)
                                folded = all(o for _, o in parts)
                        if cmd is None and items:
                            cmd, folded = _pt_value(items[0], env, text)
                        if api == "child_process" and cmd is not None and len(items) > 1 and \
                                items[1].strip()[:1] == "[":
                            inner = items[1].strip()[1:].rsplit("]", 1)[0]
                            parts = [_pt_value(p, env, text) for p in (_fs_split(inner, _FS_COMMA) or [inner])]
                            cmd += "".join(" " + p for p, _ in parts if p is not None)
                            folded = folded and all(o for _, o in parts)
                        if kind == "se" and cmd is not None and len(items) > 1:
                            a, o = _pt_value(items[1], env, text)
                            if a:
                                cmd, folded = cmd + " " + a, folded and o
                if cmd is None:
                    continue
                if api == "child_process" and re.search(r"\bfork\s*\($", text[m.start():m.end()]):
                    add(api, parent, "node.exe " + cmd, lno, folded, child="node.exe")
                    continue
                if api == "Win32_Process.Create":
                    add(api, "WmiPrvSE.exe", cmd, lno, folded)
                    continue
                if api == "ShellExecute" and _PT_SHELLWIN.search(text):
                    add("ShellWindows.ShellExecute", "explorer.exe", cmd, lno, folded)
                    continue
                add(api, parent, cmd, lno, folded)
        if _PT_PROXY_GATE.search(text):
            _pt_proxy_edges(text, lines, starts, add)
        out.sort(key=lambda d: d["line"])
        return out
    except Exception:  # noqa: BLE001
        return []


def declared_spawns(plans_by_member, sources=None):
    """Static process tree from plans + sources -> [{member, parent_image, child_image, cmdline, api, line, source}].
      plan edges   (source 'plan', line None): host image (pt_image(language, host_profile, member)) -> the
                   next_language interpreter when the plan's steps dispatch (dispatch_process / dispatch_language /
                   handoff_script / dispatch_next_stage ...); cmdline = next_stage / file_path when the plan names one;
                   api = the dispatching step
      code edges   (source 'code'): code_spawns(sources[member]) with the member's host image as parent
    plans_by_member {member: plan dict / 'k=v|..' / JSON}; sources {member: text/bytes} (optional; members with a
    source but no plan still get their code edges). [] when nothing declares a spawn."""
    try:
        out = []
        plans_by_member = plans_by_member or {}
        sources = sources or {}
        for m in sorted(set(plans_by_member) | set(sources)):
            d = {}
            if m in plans_by_member:
                try:
                    d = {_rc_field(k): v for k, v in _rc_dict(plans_by_member[m]).items()}
                except Exception:  # noqa: BLE001
                    d = {}
            steps = d.get("steps") or ""
            steps = [str(s) for s in steps] if isinstance(steps, (list, tuple)) else \
                [s for s in re.split(r"[\s,;>|]+", str(steps)) if s]
            parent = pt_image(d.get("language"), d.get("host_profile"), m)
            nl = str(d.get("next_language") or "").strip()
            disp = [s for s in steps if _PT_DISPATCH.match(s)]
            if nl and disp and nl.lower() not in ("none", "null", "n/a"):
                child = pt_image(nl) or nl
                tgt = next((str(d[k]) for k in ("next_stage", "file_path", "path", "drop_path") if d.get(k)), None)
                out.append({"member": m, "parent_image": parent, "child_image": child,
                            "cmdline": f"{child} {tgt}" if tgt else None, "api": disp[-1], "line": None,
                            "source": "plan"})
            if m in sources:
                for s in code_spawns(sources[m], m, parent):
                    out.append({"member": m, "parent_image": s["parent_image"], "child_image": s["child_image"],
                                "cmdline": s["cmdline"], "api": s["api"], "line": s["line"], "source": "code"})
        return out
    except Exception:  # noqa: BLE001
        return []


# --- handoff graph: where each static handoff (next_language / next_stage) actually leads across the corpus ----------
# next_language -> the member(s) of that language (plan language=, else the file family: polyglot-<lang>-*, extension,
# a language token in the name); code side = the language the member's own code spawns / writes (code_spawns + script
# file literals on write lines); a member whose declared next_language is not among its code targets is a mismatch.
_HG_ALIAS = {
    "powershell": ("powershell", "pwsh", "ps", "ps1", "psm1", "posh", "powershell_exe"),
    "batch": ("batch", "bat", "cmd", "cmd_exe", "batchfile"), "jscript": ("jscript", "js", "jse", "wsh_jscript"),
    "vbscript": ("vbscript", "vbs", "vbe", "wsh_vbscript"), "python": ("python", "py", "python3", "pyw", "python_exe"),
    "bash": ("bash", "sh", "shell", "posix_sh", "bin_sh"), "javascript": ("javascript", "node", "nodejs", "mjs", "cjs"),
    "typescript": ("typescript", "ts"), "perl": ("perl", "pl"), "ruby": ("ruby", "rb"), "lua": ("lua",),
    "php": ("php",), "autoit": ("autoit", "au3"), "auto_hotkey": ("auto_hotkey", "autohotkey", "ahk"),
    "applescript": ("applescript", "scpt", "osascript"), "msbuild_xml": ("msbuild_xml", "msbuild", "csproj", "proj"),
    "hta": ("hta", "mshta"), "wsf": ("wsf",), "wmi_mof": ("wmi_mof", "mof"), "tcl": ("tcl", "tclsh"), "zsh": ("zsh",),
    "sct": ("sct", "scriptlet"), "google_apps_script": ("google_apps_script", "apps_script", "gs"),
    # compiled-lang-source-route families (polyglot-go-* / -rust- / -swift- / -jxa- / -nim- / -zig- / -dart-)
    "go": ("go", "golang"), "rust": ("rust", "rs"), "swift": ("swift",), "nim": ("nim",), "zig": ("zig",),
    "dart": ("dart",), "jxa": ("jxa", "javascript_for_automation", "osascript_js"),
}
_HG_CANON = {a: k for k, al in _HG_ALIAS.items() for a in al}
_HG_LOOSE = {"jscript": "js", "javascript": "js", "typescript": "js", "bash": "sh", "zsh": "sh"}
_HG_IMG = {"powershell.exe": ("powershell",), "pwsh.exe": ("powershell",), "cmd.exe": ("batch",),
           "python.exe": ("python",), "pythonw.exe": ("python",), "py.exe": ("python",), "node.exe": ("javascript",),
           "wscript.exe": ("jscript", "vbscript", "wsf"), "cscript.exe": ("jscript", "vbscript", "wsf"),
           "mshta.exe": ("hta",), "perl.exe": ("perl",), "ruby.exe": ("ruby",), "lua.exe": ("lua",), "php.exe": ("php",),
           "autoit3.exe": ("autoit",), "autohotkey64.exe": ("auto_hotkey",), "autohotkey.exe": ("auto_hotkey",),
           "osascript": ("applescript",), "msbuild.exe": ("msbuild_xml",), "bash": ("bash",), "sh": ("bash",),
           "zsh": ("zsh",), "tclsh": ("tcl",), "regsvr32.exe": ("sct",)}
_HG_SCRIPT_LIT = re.compile(r"""(?i)["']([^"'\r\n]{0,240}?\.(ps1|psm1|bat|cmd|vbs|vbe|js|jse|mjs|cjs|py|pyw|sh|"""
                            r"""hta|wsf|pl|rb|lua|php|au3|ahk|ts|scpt|applescript|sct|tcl))["']""")
_HG_WRITE = re.compile(r"(?i)Out-File|Set-Content|Add-Content|WriteAllText|WriteAllBytes|SaveToFile|CreateTextFile|"
                       r"OpenTextFile|writeFile(?:Sync)?|createWriteStream|\bopen\s*\([^)]*,\s*[\"'][wa]|write_text|"
                       r"write_bytes|\becho\b[^\n]*>|\bcopy\b|Copy-Item|Move-Item|\bcp\s|\bmv\s|\btee\b|>\s*[\"']?\S+\.\w")
_HG_NONE = ("", "none", "null", "n/a", "na", "-", "terminal", "end", "same_language")


def hg_lang(x):
    """Language name / alias / extension / interpreter image -> canonical family key (None unknown)."""
    k = re.sub(r"[^0-9a-z]+", "_", str(x or "").strip().lower()).strip("_")
    if not k:
        return None
    if k in _HG_CANON:
        return _HG_CANON[k]
    k2 = re.sub(r"_exe$", "", k)
    return _HG_CANON.get(k2) or (k if k in PT_LANG_IMAGE else None)


def _hg_member_lang(m):
    """File family of a member name: polyglot-<lang>-*, the extension, else one language token in the stem."""
    base = str(m or "").replace("\\", "/").rsplit("/", 1)[-1].lower()
    mm = re.match(r"(?:polyglot|host|stage|legacy)[-_]([a-z0-9_]+?)[-_.]", base)
    if mm and hg_lang(mm.group(1)):
        return hg_lang(mm.group(1))
    ext = base.rsplit(".", 1)[-1] if "." in base else ""
    if ext in ("js",):
        return "jscript"
    if ext and ext not in ("txt", "dat", "bin", "json", "log", "exe", "dll") and hg_lang(PT_EXT_LANG.get(ext) or ext):
        return hg_lang(PT_EXT_LANG.get(ext) or ext)
    toks = {hg_lang(t) for t in re.split(r"[-_.]+", base.rsplit(".", 1)[0]) if len(t) > 2 and hg_lang(t)}
    return next(iter(toks)) if len(toks) == 1 else None


def _hg_code_targets(src, member, parent):
    """Languages the member's own code hands off to: spawn cmdlines (script file / inner interpreter first, else the
    child image) + script-file literals on write lines. [(lang, evidence)]"""
    out = []
    try:
        for s in code_spawns(src, member, parent):
            cmd = str(s.get("cmdline") or "")
            langs = [PT_EXT_LANG.get(e.lower()) for e in re.findall(
                r"(?i)\.(ps1|psm1|bat|cmd|vbs|vbe|js|jse|mjs|cjs|py|pyw|sh|hta|wsf|pl|rb|lua|php|au3|ahk|ts|scpt)\b", cmd)]
            langs = [hg_lang(x) for x in langs if x]
            if not langs:
                toks = [t.strip("\"'").replace("\\", "/").rsplit("/", 1)[-1].lower() for t in cmd.split()]
                inner = [_HG_IMG.get(t if t.endswith(".exe") or t in _HG_IMG else t + ".exe") for t in toks]
                inner = [i for i in inner if i and len(i) == 1]
                langs = [inner[-1][0]] if inner else list(_HG_IMG.get(str(s.get("child_image") or "").lower(), ()))
            for lg in langs:
                out.append((lg, "spawn:" + str(s.get("api"))))
        text = src.decode("utf-8", "replace") if isinstance(src, (bytes, bytearray)) else str(src or "")
        for ln in text[:1_000_000].split("\n")[:50000]:
            if len(ln) > 20000 or _FS_COMMENT.match(ln) or not _HG_WRITE.search(ln):
                continue
            for mm in _HG_SCRIPT_LIT.finditer(ln):
                lg = hg_lang(PT_EXT_LANG.get(mm.group(2).lower()) or mm.group(2))
                if lg:
                    out.append((lg, "write:" + mm.group(1)))
    except Exception:  # noqa: BLE001
        pass
    return out


def handoff_graph(plans_by_member, sources=None):
    """Corpus-level handoff graph: where each member's static handoff actually leads.
    plans_by_member {member: plan dict / 'k=v|..' / JSON}; sources {member: text/bytes} (optional, code side).
      members     {member: {language, next_language, next_stage, code_targets:[lang], resolved:[member]}}
      edges       [(member, next_language, resolved_members)] -- next_stage naming a member wins; else the other
                  members of the next_language (plan language=, file family; loose jscript~javascript, bash~zsh as a
                  fallback; several -> narrowed by the code-side target); [] = leads outside the corpus / self
      chains      [[member..]] from each root (no incoming edge) along single resolved edges to a terminal / cycle
      terminals   [member] (no handoff, external, self-handoff); ambiguous: [member] whose handoff resolves to
                  several members (a chain ending there has no answer); terminal_languages: [lang] of the terminals
                  reached from a root (the bridge's end languages)
      cycles      [[member..]] (rotation starting at the smallest name)
      mismatches  [{member, declared, code}] -- declared next_language not among the code-side spawn/write languages
      counts      members, edges, resolved_edges, chains, terminals, cycles, mismatches, longest_chain
    None when no member declares a handoff."""
    try:
        plans_by_member = plans_by_member or {}
        sources = sources or {}
        mem = {}
        for m in sorted(set(plans_by_member) | set(sources)):
            d = {}
            if m in plans_by_member:
                try:
                    d = {_rc_field(k): v for k, v in _rc_dict(plans_by_member[m]).items()}
                except Exception:  # noqa: BLE001
                    d = {}
            nl = str(d.get("next_language") or "").strip()
            ns = str(d.get("next_stage") or "").strip()
            lang = hg_lang(d.get("language")) or _hg_member_lang(m)
            parent = pt_image(d.get("language"), d.get("host_profile"), m)
            ct = _hg_code_targets(sources[m], m, parent) if m in sources else []
            mem[m] = {"language": lang, "language_raw": str(d.get("language") or "") or None,
                      "next_language": None if nl.lower() in _HG_NONE else nl,
                      "next_stage": None if ns.lower() in _HG_NONE else ns,
                      "code_targets": list(dict.fromkeys(lg for lg, _ in ct)),
                      "code_evidence": [e for _, e in ct][:12], "resolved": []}
        if not any(g["next_language"] or g["next_stage"] for g in mem.values()):
            return None
        stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).replace("\\", "/").rsplit("/", 1)[-1]).lower()
        by_name = {}
        for m in mem:
            for k in {m.lower(), m.replace("\\", "/").rsplit("/", 1)[-1].lower(), stem(m)}:
                by_name.setdefault(k, set()).add(m)
        edges = []
        for m, g in mem.items():
            res = []
            if g["next_stage"]:
                ns = g["next_stage"].replace("\\", "/").rsplit("/", 1)[-1].lower()
                for k in (ns, stem(ns)):
                    if len(by_name.get(k, ())) == 1:
                        res = sorted(by_name[k] - {m})
                        break
            nlc = hg_lang(g["next_language"]) if g["next_language"] else None
            if not res and nlc:
                res = sorted(o for o, h in mem.items() if o != m and h["language"] == nlc)
                if not res and nlc in _HG_LOOSE:
                    res = sorted(o for o, h in mem.items() if o != m and h["language"] and
                                 _HG_LOOSE.get(h["language"]) == _HG_LOOSE[nlc])
                if len(res) > 1 and sources.get(m) is not None:   # the code's own written / spawned file name
                    text = sources[m].decode("utf-8", "replace") if isinstance(sources[m], (bytes, bytearray)) \
                        else str(sources[m])
                    lit = {stem(x.group(1)) for x in _HG_SCRIPT_LIT.finditer(text[:1_000_000])}
                    hit = [o for o in res if stem(o) in lit]
                    if len(hit) == 1:
                        res = hit
            if g["next_language"] or g["next_stage"]:
                edges.append((m, g["next_language"] or g["next_stage"], res))
            g["resolved"] = res
        nxt = {m: g["resolved"][0] for m, g in mem.items() if len(g["resolved"]) == 1}
        has_in = {o for g in mem.values() for o in g["resolved"]}
        # cycles over the single-successor map
        cycles, seen = [], set()
        for s in mem:
            path, n = [], s
            while n is not None and n not in path and n not in seen:
                path.append(n)
                n = nxt.get(n)
            if n is not None and n in path:
                cyc = path[path.index(n):]
                i = cyc.index(min(cyc))
                cycles.append(cyc[i:] + cyc[:i])
            seen.update(path)
        cycles = sorted({tuple(c) for c in cycles})
        cycles = [list(c) for c in cycles]
        roots = [m for m, g in mem.items() if m not in has_in and (g["next_language"] or g["next_stage"])]
        chains = []
        for r in roots:
            path, n = [], r
            while n is not None and n not in path:
                path.append(n)
                n = nxt.get(n)
            chains.append(path)
        ambiguous = sorted(m for m, g in mem.items() if len(g["resolved"]) > 1)
        terminals = sorted(m for m in mem if m not in nxt and m not in ambiguous and
                           (m in has_in or mem[m]["next_language"] or mem[m]["next_stage"]))
        ends = [c[-1] for c in chains if c[-1] in terminals]
        tlang = list(dict.fromkeys(mem[e]["language"] for e in ends if mem[e]["language"]))
        mism = []
        for m, g in mem.items():
            nlc = hg_lang(g["next_language"]) if g["next_language"] else None
            if not nlc or not g["code_targets"]:
                continue
            ct = [c for c in g["code_targets"] if c != g["language"]] or g["code_targets"]
            loose = {_HG_LOOSE.get(c, c) for c in ct}
            if nlc not in ct and _HG_LOOSE.get(nlc, nlc) not in loose:
                mism.append({"member": m, "declared": g["next_language"], "code": ct[0], "code_all": ct})
        rep = {"members": mem, "edges": edges, "chains": chains, "roots": roots, "terminals": terminals,
               "ambiguous": ambiguous,
               "terminal_languages": tlang, "cycles": cycles, "mismatches": mism}
        rep["counts"] = {"members": len(mem), "edges": len(edges),
                         "resolved_edges": sum(1 for e in edges if e[2]), "chains": len(chains),
                         "terminals": len(terminals), "cycles": len(cycles), "mismatches": len(mism),
                         "longest_chain": max((len(c) for c in chains), default=0),
                         "roots": len(roots)}
        return rep
    except Exception:  # noqa: BLE001
        return None


def handoff_answer(g, kind, accepted_values=None, what="terminal_language", sep=">"):
    """One GM answer from a handoff_graph() report.
      what  'terminal' / 'terminal_language' / 'root' / 'root_language' (of the single chain, else the longest unique
            one), 'chain' (members) / 'language_chain', 'chain_length' (members in it), 'resolves:<member>' (the
            member its handoff leads to), 'resolves_language:<member>', 'mismatch' (member whose declared
            next_language disagrees with its code), 'mismatch_declared' / 'mismatch_code', 'cycle' (members, sep),
            'cycle_member' (one-member answer when one cycle), or a counts key ('cycles', 'mismatches', 'edges', ...)
      kind  enum (matched to accepted_values by name / stem / language alias), exact_text, integer, ordered_tokens,
            list (comma-joined)
    'none' when the asked-for thing is absent (no cycle / no mismatch); None when unanswerable or ambiguous."""
    try:
        if not g:
            return None
        stem = lambda s: re.sub(r"\.[A-Za-z0-9_]+$", "", str(s).replace("\\", "/").rsplit("/", 1)[-1]).lower()

        def pick(v):
            if v is None:
                return None
            for a in accepted_values or ():
                if str(a) == str(v) or str(a).lower() == str(v).lower() or stem(a) == stem(v):
                    return a
            for a in accepted_values or ():
                if hg_lang(a) and hg_lang(a) == hg_lang(v):
                    return a
            return None if accepted_values else v

        def out(vals):
            if kind in ("ordered_tokens", "list", "set"):
                return (sep if kind == "ordered_tokens" else ",").join(str(x) for x in vals) if vals else None
            if kind == "integer":
                return str(len(vals))
            return pick(vals[0]) if len(vals) == 1 else None
        mem = g["members"]
        chains = g["chains"]
        if len(chains) == 1:
            ch = chains[0]
        else:
            ln = sorted((len(c) for c in chains), reverse=True)
            ch = next((c for c in chains if len(c) == ln[0]), None) if ln and (len(ln) == 1 or ln[0] > ln[1]) else None
        if ch and ch[-1] in g.get("ambiguous", ()):
            ch = None
        w, _, arg = str(what).partition(":")
        lng = lambda m: mem[m]["language_raw"] or mem[m]["language"]
        if w in ("chain", "member_chain"):
            return out(ch) if ch else None
        if w == "language_chain":
            return out([lng(m) for m in ch]) if ch and all(lng(m) for m in ch) else None
        if w == "chain_length":
            return str(len(ch)) if ch else None
        if w in ("terminal", "terminal_language", "leaf", "leaf_language"):
            if not ch or ch[-1] not in g["terminals"]:
                return None
            return out([lng(ch[-1]) if w.endswith("language") else ch[-1]])
        if w in ("root", "root_language"):
            return out([lng(ch[0]) if w.endswith("language") else ch[0]]) if ch else None
        if w in ("resolves", "resolves_language"):
            m = next((x for x in mem if x == arg or x.lower() == arg.lower() or stem(x) == stem(arg)), None)
            if not m or not (mem[m]["next_language"] or mem[m]["next_stage"]):
                return None
            r = mem[m]["resolved"]
            if not r:
                return "none"
            return out([lng(x) for x in r] if w.endswith("language") else r)
        if w.startswith("mismatch") and w != "mismatches":
            mm = g["mismatches"]
            if not mm:
                return "none"
            if len(mm) > 1 and kind not in ("list", "set", "integer"):
                return None
            key = {"mismatch": "member", "mismatch_declared": "declared", "mismatch_code": "code"}.get(w, "member")
            return out([x[key] for x in mm])
        if w in ("cycle", "cycle_member"):
            if not g["cycles"]:
                return "none"
            if len(g["cycles"]) != 1:
                return None
            c = g["cycles"][0]
            return out(c) if w == "cycle" and kind != "enum" else (out(c) if len(c) == 1 or kind != "enum" else None)
        if w in g["counts"]:
            return str(g["counts"][w])
        return None
    except Exception:  # noqa: BLE001
        return None


