def _pt_key(s):
    return re.sub(r"[^0-9a-z]+", "", str(s or "").lower())


def spawn_parent_candidates(api):
    """Spawn API / launcher name (code_spawns api, 'wmic process call create', 'Register-ScheduledTask',
    'MMC20.Application', 'sc create', 'Run key', 'macro', 'Apps Script' ...) -> the parent images telemetry records
    for its child, most likely first ([] = no local process: cloud script). None when the API is not a proxy (the
    calling script itself is the parent)."""
    try:
        k = _pt_key(api)
        if not k:
            return None
        for key, names, _cue, parents, _att in PT_SPAWN_PARENTS:
            if k == key.replace("_", "") or any(n in k for n in names):
                if key == "office_macro":
                    hint = next((img for h, img in _PT_OFFICE_HINT if h.replace("_", "") in k), None)
                    return ([hint] if hint else []) + [p for p in parents if p != hint]
                return list(parents)
        return None
    except Exception:  # noqa: BLE001
        return None


def spawn_proxies(src):
    """Proxy-launch cues in a script's code -> [{key, cue, line, parents, attack}] in source order (first hit per
    family): the process the telemetry will record as the parent of what this script launches through WMI, the
    Task Scheduler, DCOM (MMC20 / ShellWindows), the SCM, Run keys, Office macros, LOLBin hosts, or [] parents for
    cloud scripts. Comment lines are skipped. [] when nothing proxies."""
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            src = (b.decode("utf-16", "replace") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else
                   b.decode("utf-8-sig", "replace"))
        text = _fs_flat(str(src or "")[:1_000_000])
        lines = text.split("\n")
        hits = {}
        for key, rx in _PT_SPAWN_RX:
            for lno, ln in enumerate(lines[:50000], 1):
                if len(ln) > 20000 or _FS_COMMENT.match(ln):
                    continue
                m = rx.search(ln)
                if m:
                    hits[key] = (lno, m.start(), m.group(0).strip())
                    break
        if "wmi_event_subscription" in hits and ("wmi_script_consumer" in hits or "wmi_cmdline_consumer" in hits):
            hits.pop("wmi_event_subscription")
        out = []
        for key, names, _cue, parents, att in PT_SPAWN_PARENTS:
            if key not in hits:
                continue
            lno, col, cue = hits[key]
            ps = list(parents)
            if key == "office_macro":
                hint = next((img for h, img in _PT_OFFICE_HINT if h in cue.lower()), None)
                ps = ([hint] if hint else []) + [p for p in parents if p != hint]
            out.append({"key": key, "cue": cue, "line": lno, "parents": ps, "attack": list(att), "_col": col})
        out.sort(key=lambda d: (d["line"], d.pop("_col")))
        return out
    except Exception:  # noqa: BLE001
        return []


def ppid_spoof(src):
    """PPID-spoofing code cues (T1134.004) -> {cues: [names in source order], spoofed_parent: image | None,
    attack: 'T1134.004' | 'none'}. Spoofing = the parent-process attribute (UpdateProcThreadAttribute +
    PROC_THREAD_ATTRIBUTE_PARENT_PROCESS / 0x00020000) or STARTUPINFOEX + EXTENDED_STARTUPINFO_PRESENT (0x00080000)
    with an OpenProcess(PROCESS_CREATE_PROCESS 0x0080) handle. spoofed_parent = the process whose handle is opened
    (Get-Process explorer / GetProcessesByName("svchost") / a quoted '<name>.exe'). {} for unreadable input."""
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)
            src = (b.decode("utf-16", "replace") if b[:2] in (b"\xff\xfe", b"\xfe\xff") else
                   b.decode("utf-8-sig", "replace"))
        text = str(src or "")[:1_000_000]
        code = "\n".join(ln for ln in text.split("\n") if not _FS_COMMENT.match(ln))
        found = []
        for name, rx in _PPID_RX:
            m = rx.search(code)
            if m:
                found.append((m.start(), name))
        names = {n for _, n in found}
        attr = "UpdateProcThreadAttribute" in names and "PROC_THREAD_ATTRIBUTE_PARENT_PROCESS" in names
        ext = "STARTUPINFOEX" in names and "EXTENDED_STARTUPINFO_PRESENT" in names and \
            ("PROCESS_CREATE_PROCESS" in names or "UpdateProcThreadAttribute" in names)
        spoof = (attr or ext) and ("CreateProcess" in names or "STARTUPINFOEX" in names)
        par = None
        if spoof:
            for m in _PPID_TARGET.finditer(code):
                v = m.group(1) or m.group(2)
                if v and v.lower() not in ("id", "name", "handle", "process", "processname"):
                    par = v if v.lower().endswith(".exe") else v + ".exe"
                    break
        return {"cues": [n for _, n in sorted(found)], "spoofed_parent": par,
                "attack": "T1134.004" if spoof else "none"}
    except Exception:  # noqa: BLE001
        return {}


def spawn_parent_answer(src, kind="parent", plan=None, accepted_values=None):
    """Answer 'which process will the telemetry record as the parent' / 'which technique' for a script.
    kind: parent (expected recorded parent: the spoofed parent, else the proxy parents in order) | attack (plan
    attack= wins; else T1134.004 when the code spoofs its PPID, else the proxy family's techniques) | family.
    Candidates in order (a list when several); the matching accepted value when given. 'none' when the code has no
    proxy / spoof cue (or a cloud script runs no local process), None on error."""
    try:
        kd = _pt_key(kind)
        acc = [a for a in (accepted_values or []) if str(a).strip()] or None
        sp = ppid_spoof(src) or {}
        px = spawn_proxies(src)
        if any(a in kd for a in ("attack", "technique", "mitre", "ttp")):
            pa = None
            if plan is not None:
                try:
                    pa = str({_rc_field(k): v for k, v in _rc_dict(plan).items()}.get("attack") or "").strip()
                except Exception:  # noqa: BLE001
                    pa = None
            vals = [pa.upper()] if pa and pa.lower() not in ("none", "null", "n/a") else []
            if sp.get("attack") == "T1134.004":
                vals.append("T1134.004")
            for p in px:
                vals += p["attack"]
        elif "famil" in kd or "key" in kd or "method" in kd:
            vals = [p["key"] for p in px]
        else:
            vals = [sp["spoofed_parent"]] if sp.get("spoofed_parent") else []
            for p in px:
                vals += p["parents"]
        seen = []
        for v in vals:
            if v and v.lower() not in [s.lower() for s in seen]:
                seen.append(v)
        if acc:
            seen = [next(a for a in acc if str(a).strip().lower() == v.lower() or
                         _rcp_base(a) == _rcp_base(v)) for v in seen
                    if any(str(a).strip().lower() == v.lower() or _rcp_base(a) == _rcp_base(v) for a in acc)]
        if not seen:
            return "none"
        return seen[0] if len(seen) == 1 else seen
    except Exception:  # noqa: BLE001
        return None


def _pt_proxy_edges(text, lines, starts, add):
    """Code sites whose child the OS parents to a broker: MMC20 ExecuteShellCommand -> mmc.exe, sc create binPath= /
    New-Service -BinaryPathName -> services.exe, New-ScheduledTaskAction -Execute -> svchost.exe, a WMI
    CommandLineEventConsumer CommandLineTemplate -> WmiPrvSE.exe."""
    import bisect
    env = None
    lit = r"""(?:"((?:[^"\\]|\\.)*)"|'([^']*)'|([^\s;,)}]+))"""
    for api, rx, par in _PT_PROXY_SITES:
        for m in rx.finditer(text):
            lno = bisect.bisect_right(starts, m.start())
            line = lines[lno - 1]
            if _FS_COMMENT.match(line) or _FS_ECHO.match(line):
                continue
            if api == "MMC20.ExecuteShellCommand":
                args = _fs_args(text, m.end())
                items = _fs_split(args or "", _FS_COMMA) or []
                if not items:
                    continue
                env = env if env is not None else _fs_env(text)
                c, ok = _pt_value(items[0], env, text)
                if c is None:
                    continue
                if len(items) > 2:
                    a, o = _pt_value(items[2], env, text)
                    c, ok = (c + " " + a, ok and o) if a else (c, ok)
                add(api, par, c, lno, ok)
                continue
            rest = text[m.end():starts[lno] if lno < len(starts) else len(text)]
            if api == "New-ScheduledTaskAction":
                em = re.search(r"(?i)-Execute\s+" + lit, rest)
                if not em:
                    continue
                am = re.search(r"(?i)-Argument\s+" + lit, rest)
                pick = lambda mm: next(g for g in mm.groups() if g is not None)  # noqa: E731
                c = pick(em).replace('\\"', '"') + (" " + pick(am).replace('\\"', '"') if am else "")
                add(api, par, c, lno, True)
                continue
            lm = re.match(lit, rest)
            if not lm:
                continue
            c = next(g for g in lm.groups() if g is not None)
            c = c.replace('\\"', '"').replace("\\\\", "\\") if lm.group(1) is not None else c
            add(api, par, c, lno, True)


_PT_PROXY_SITES = (
    ("MMC20.ExecuteShellCommand", re.compile(r"(?i)\.ExecuteShellCommand\s*\(?"), "mmc.exe"),
    ("sc create", re.compile(r"(?i)\bsc(?:\.exe)?\s+(?:\\\\\S+\s+)?create\s+\S+[^\n]*?\bbinpath=\s*"), "services.exe"),
    ("New-Service", re.compile(r"(?i)\bNew-Service\b[^\n]*?-BinaryPathName\s+"), "services.exe"),
    ("New-ScheduledTaskAction", re.compile(r"(?i)\bNew-ScheduledTaskAction\b"), "svchost.exe"),
    ("CommandLineEventConsumer", re.compile(r"(?i)\bCommandLineTemplate\s*[=:]\s*"), "WmiPrvSE.exe"),
)


# --- process-tree-reconcile: declared (static) vs observed process tree; PPID spoofing (T1134.004) ---------------------
def _rcp_base(img):
    """Image -> comparable basename: last path part, lower, quotes / trailing '.exe' dropped ('' when unknown)."""
    b = _pt_base(str(img or "").strip().strip("\"'")).lower()
    return b[:-4] if b.endswith(".exe") else b


def _rcp_canon(cmd):
    """Command line -> matching form: first token reduced to its image basename, cmd carets / doubled quotes gone,
    quotes stripped, whitespace collapsed, lower-case ('' when absent)."""
    s = str(cmd or "").strip().replace("^", "").replace('""', '"')
    m = re.match(r'\s*(?:"([^"]+)"|(\S+))(.*)$', s, re.S)
    if not m:
        return ""
    head = _rcp_base(m.group(1) or m.group(2))
    return re.sub(r"\s+", " ", (head + " " + m.group(3).replace('"', "").replace("'", "")).strip().lower())


def _rcp_procs(observed):
    """process_events() starts merged per real process: a Sysmon EID 1 and a Security 4688 record of the same pid +
    image (within 5 s) are one process; the 4688 creator ProcessId then rides along as the creator."""
    evs = observed if isinstance(observed, list) else process_events(observed)
    starts = [e for e in evs if isinstance(e, dict) and e.get("event") == "start"][:50000]
    ends = [e for e in evs if isinstance(e, dict) and e.get("event") == "end"][:50000]
    procs = []
    for i, e in enumerate(starts):
        t = _pt_ts(e.get("ts"))
        hit = None
        for p in procs:
            if p["pid"] is not None and p["pid"] == e.get("pid") and \
                    _rcp_base(p["image"]) == _rcp_base(e.get("image")) and \
                    (p["t"] is None or t is None or abs(p["t"] - t) <= 5) and e.get("src") not in p["srcs"]:
                hit = p
                break
        if hit is None:
            hit = {"pid": e.get("pid"), "pid_raw": e.get("pid_raw"), "image": e.get("image"), "t": t, "i": i,
                   "cmdline": e.get("cmdline"), "guid": _pt_guid(e.get("guid")), "srcs": [], "rec_ppid": None,
                   "rec_ppid_raw": None, "rec_pimage": None, "rec_pguid": None, "creator": None, "creator_raw": None,
                   "creator_guid": None, "creator_image": None, "end": None}
            procs.append(hit)
        hit["srcs"].append(e.get("src"))
        hit["cmdline"] = hit["cmdline"] or e.get("cmdline")
        hit["guid"] = hit["guid"] or _pt_guid(e.get("guid"))
        if e.get("src") == "security" and len(hit["srcs"]) > 1:      # 4688 next to a Sysmon record: the creator
            hit["creator"], hit["creator_raw"] = e.get("ppid"), e.get("ppid_raw")
            hit["creator_image"] = hit["creator_image"] or e.get("parent_image")
            continue
        if e.get("src") != "security" and hit["rec_ppid"] is not None and hit["srcs"][0] == "security":
            hit["creator"], hit["creator_raw"] = hit["rec_ppid"], hit["rec_ppid_raw"]  # 4688 came first
            hit["creator_image"] = hit["creator_image"] or hit["rec_pimage"]
            hit["rec_ppid"] = hit["rec_pimage"] = None
        if hit["rec_ppid"] is None:
            hit["rec_ppid"], hit["rec_ppid_raw"] = e.get("ppid"), e.get("ppid_raw")
            hit["rec_pimage"], hit["rec_pguid"] = e.get("parent_image"), _pt_guid(e.get("parent_guid"))
        if e.get("creator_pid") is not None:
            hit["creator"], hit["creator_raw"] = e["creator_pid"], e.get("creator_pid_raw")
        hit["creator_guid"] = hit["creator_guid"] or _pt_guid(e.get("creator_guid"))
        hit["creator_image"] = hit["creator_image"] or e.get("creator_image")
    for e in ends:
        t, g = _pt_ts(e.get("ts")), _pt_guid(e.get("guid"))
        for p in reversed(procs):
            if p["end"] is None and ((g and p["guid"] == g) or (not g and p["pid"] == e.get("pid"))) and \
                    (t is None or p["t"] is None or p["t"] <= t):
                p["end"] = t
                break
    return procs


def _rcp_resolve(procs, me, pid=None, guid=None):
    """The process a parent reference names at `me`'s start: guid first, else the pid alive then. None unknown."""
    if guid:
        hit = next((p for p in procs if p is not me and p["guid"] == guid), None)
        if hit:
            return hit
    if pid is None:
        return None
    t = me["t"]
    cands = [p for p in procs if p is not me and p["pid"] == pid and
             (t is None or p["t"] is None or p["t"] <= t) and (t is None or p["end"] is None or p["end"] >= t)]
    return cands[-1] if cands else None


def _rcp_proxy_ok(d, rec):
    """A declared row launched through a broker API (its `api` / `proxy_parents`) whose recorded parent is that
    broker (WmiPrvSE.exe for Win32_Process.Create, svchost.exe / taskeng.exe for a task ...) is not a mismatch."""
    src = d.get("src") or {}
    cands = src.get("proxy_parents") or spawn_parent_candidates(src.get("api")) or []
    return _rcp_base(rec) in {_rcp_base(c) for c in cands}


def _rcp_declared(declared):
    """declared_spawns() rows / {child: parent} / (parent, child[, cmdline]) tuples -> [{parent, child, cmdline}]."""
    out = []
    if isinstance(declared, dict):
        declared = [{"parent_image": v, "child_image": k} for k, v in declared.items()]
    for d in list(declared or [])[:5000]:
        if isinstance(d, dict):
            c = d.get("child_image") or d.get("child") or d.get("image")
            p = d.get("parent_image") or d.get("parent")
            cl = d.get("cmdline")
        elif isinstance(d, (list, tuple)) and len(d) >= 2:
            p, c, cl = d[0], d[1], (d[2] if len(d) > 2 else None)
        else:
            continue
        if c:
            out.append({"parent": p, "child": c, "cmdline": cl, "src": d if isinstance(d, dict) else None})
    return out


def reconcile_processes(declared, observed):
    """Declared process tree vs observed telemetry ("the child claiming a parent it never had").
    declared: declared_spawns() rows, {child: parent}, or (parent, child[, cmdline]) tuples (None: telemetry only).
    observed: the raw log (bytes / text; anything process_events() reads) or its record list.
    -> {matched: [{child, declared_parent, recorded_parent, pid, guid, cmdline}],
        parent_mismatch: [{child, declared_parent, recorded_parent, real_parent_if_known, pid, guid, reasons}],
        declared_only (declared spawns that never ran), observed_only (unexpected processes: unmatched and not the
        parent of a matched one), orphans (recorded parent never seen / exited), spoofed (bool), attack}.
    A child is matched by image basename, then canonical cmdline, then recorded parent == declared parent, then time
    order. reasons: 'declared' (recorded parent != declared parent), 'creator' (the real creator -- 4688 ProcessId
    next to a Sysmon EID 1 of the same process, or a CreatorProcessId / CreatorProcessGuid field -- differs from
    the recorded ParentProcessId / ParentImage), 'parent_image' (ParentImage disagrees with the process that
    ParentProcessId / ParentProcessGuid resolves to). Images are answered in the log's spelling (basename).
    {} when the log has no process records."""
    try:
        procs = _rcp_procs(observed)
        if not procs:
            return {}
        img = lambda p: _pt_base(p["image"]) if p and p.get("image") else None  # noqa: E731
        info = []
        for p in procs:
            rp = _rcp_resolve(procs, p, p["rec_ppid"], p["rec_pguid"])
            rec = _pt_base(p["rec_pimage"]) if p["rec_pimage"] else img(rp)
            real, reasons = None, []
            if p["creator"] is not None or p["creator_guid"]:
                cp = _rcp_resolve(procs, p, p["creator"], p["creator_guid"])
                real = img(cp) or (_pt_base(p["creator_image"]) if p["creator_image"] else None)
                if (p["creator"] is not None and p["rec_ppid"] is not None and p["creator"] != p["rec_ppid"]) or \
                        (p["creator_guid"] and p["rec_pguid"] and p["creator_guid"] != p["rec_pguid"]) or \
                        (real and rec and _rcp_base(real) != _rcp_base(rec)):
                    reasons.append("creator")
            elif p["creator_image"]:
                real = _pt_base(p["creator_image"])
                if rec and _rcp_base(real) != _rcp_base(rec):
                    reasons.append("creator")
            if p["rec_pimage"] and rp is not None and rp.get("image") and \
                    _rcp_base(p["rec_pimage"]) != _rcp_base(rp["image"]):
                reasons.append("parent_image")
            orphan = None
            if rp is None and (p["rec_ppid"] is not None or p["rec_pguid"]):
                gone = [q for q in procs if q is not p and ((p["rec_pguid"] and q["guid"] == p["rec_pguid"]) or
                                                             (p["rec_ppid"] is not None and q["pid"] == p["rec_ppid"]))]
                orphan = "exited" if gone else "missing"
            info.append({"p": p, "rp": rp, "rec": rec, "real": real, "reasons": reasons, "orphan": orphan})

        def row(x, dp=None):
            p = x["p"]
            return {"child": img(p) or p["pid_raw"], "declared_parent": _pt_base(dp) if dp else None,
                    "recorded_parent": x["rec"], "real_parent_if_known": x["real"], "pid": p["pid_raw"],
                    "guid": p["guid"], "cmdline": p["cmdline"], "reasons": list(x["reasons"])}

        decl = _rcp_declared(declared)
        used, matched, mism, dec_only = set(), [], [], []
        for d in decl:
            cb, cc, pb = _rcp_base(d["child"]), _rcp_canon(d["cmdline"]), _rcp_base(d["parent"])
            best = None
            for j, x in enumerate(info):
                if j in used or _rcp_base(x["p"]["image"]) != cb:
                    continue
                oc = _rcp_canon(x["p"]["cmdline"])
                sc = (4 if cc and oc == cc else 2 if cc and oc and (cc in oc or oc in cc) else 0) + \
                    (1 if pb and pb in (_rcp_base(x["rec"]), _rcp_base(x["real"])) else 0)
                if best is None or sc > best[0]:
                    best = (sc, j)
            if best is None:
                dec_only.append({"child": _pt_base(d["child"]), "declared_parent": _pt_base(d["parent"]) if d["parent"]
                                 else None, "cmdline": d["cmdline"]})
                continue
            used.add(best[1])
            x = info[best[1]]
            r = row(x, d["parent"])
            matched.append({k: r[k] for k in ("child", "declared_parent", "recorded_parent", "pid", "guid", "cmdline")})
            if pb and x["rec"] and _rcp_base(x["rec"]) != pb and not _rcp_proxy_ok(d, x["rec"]):
                r["reasons"].insert(0, "declared")
            if r["reasons"]:
                mism.append(r)
        for j, x in enumerate(info):
            if j not in used and x["reasons"]:
                mism.append(row(x))
        mism.sort(key=lambda r: next(i for i, x in enumerate(info) if x["p"]["pid_raw"] == r["pid"] and
                                     (img(x["p"]) or x["p"]["pid_raw"]) == r["child"]))
        parents, byp = set(), {id(x["p"]): x for x in info}
        todo = [info[j]["p"] for j in used]
        while todo and len(parents) < 50000:     # every ancestor (recorded or real) of a matched child is expected
            p = todo.pop()
            for q in (byp[id(p)]["rp"], _rcp_resolve(procs, p, p["creator"], p["creator_guid"])):
                if q is not None and id(q) not in parents:
                    parents.add(id(q))
                    todo.append(q)
        obs_only = [row(x) for j, x in enumerate(info) if decl and j not in used and id(x["p"]) not in parents]
        orphans = [dict(row(x), orphan=x["orphan"]) for x in info if x["orphan"]]
        spoof = any(set(r["reasons"]) & {"creator", "declared", "parent_image"} for r in mism)
        return {"matched": matched, "parent_mismatch": mism, "declared_only": dec_only, "observed_only": obs_only,
                "orphans": orphans, "spoofed": spoof, "attack": "T1134.004" if spoof else "none",
                "processes": len(procs)}
    except Exception:  # noqa: BLE001 - impostor / truncated input: nothing, never an exception
        return {}


def reconcile_processes_answer(r, kind, accepted_values=None, what=None, declared=None):
    """Answer a declared-vs-observed question from reconcile_processes() (or the raw log, with `declared`).
    kind: child (spoofed child image) | pid | guid | claimed-parent (recorded / fake parent) | true-parent (real
    creator, else the declared parent) | declared-parent | count (what: mismatch (default) | matched | declared_only
    | observed_only | orphans | processes) | declared-only (never ran) | observed-only (unexpected) | orphan | attack
    (T1134.004 when a parent was spoofed). `what` narrows to one child (image basename / path / pid). Values in the
    log's spelling or the matching accepted value; several -> list. 'none' when the field is absent (no mismatch),
    None when it cannot answer."""
    try:
        if not isinstance(r, dict) or "parent_mismatch" not in r:
            r = reconcile_processes(declared, r)
        if not r:
            return None
        acc = [a for a in (accepted_values or []) if str(a).strip()] or None
        kd = re.sub(r"[^a-z]", "", str(kind or "").lower())
        alias = [("attack", ("attack", "technique", "mitre", "ttp", "attck")),
                 ("count", ("count", "number", "howmany", "total")),
                 ("declaredonly", ("declaredonly", "neverran", "notobserved", "missing", "didnotrun", "notrun")),
                 ("observedonly", ("observedonly", "unexpected", "undeclared", "extra")),
                 ("orphan", ("orphan",)),
                 ("trueparent", ("trueparent", "realparent", "actualparent", "creator", "spawnedby", "realcreator")),
                 ("declaredparent", ("declaredparent", "expectedparent", "staticparent", "intendedparent")),
                 ("claimedparent", ("claimed", "recorded", "fake", "spoofedparent", "reportedparent", "loggedparent",
                                    "fakeparent", "parent")),
                 ("guid", ("guid",)), ("pid", ("pid", "processid", "id")),
                 ("child", ("child", "image", "process", "spoofed", "name"))]
        kd = next((k for k, al in alias if any(a in kd for a in al)), kd)
        if kd == "attack":
            v = r.get("attack") or "none"
            if acc and v != "none":
                return next((a for a in acc if str(a).strip().upper() == v), v)
            return v
        if kd == "count":
            w = re.sub(r"[^a-z]", "", str(what or "mismatch").lower())
            key = next((k for k in ("matched", "declared_only", "observed_only", "orphans", "processes")
                        if k.replace("_", "") in w or (k == "orphans" and "orphan" in w)), "parent_mismatch")
            v = r.get(key)
            return str(v if isinstance(v, int) else len(v or []))
        rows = r.get({"declaredonly": "declared_only", "observedonly": "observed_only", "orphan": "orphans"}
                     .get(kd, "parent_mismatch")) or []
        if what is not None:
            w = str(what).strip()
            wp = _pe_int(w)
            rows = [x for x in rows if _rcp_base(x.get("child")) == _rcp_base(w) or
                    (wp is not None and _pe_int(x.get("pid")) == wp)]
        field = {"pid": "pid", "guid": "guid", "claimedparent": "recorded_parent", "declaredparent": "declared_parent",
                 "trueparent": "real_parent_if_known"}.get(kd, "child")
        vals = []
        for x in rows:
            v = x.get(field)
            if kd == "trueparent" and not v:
                v = x.get("declared_parent")
            if v is None or v == "":
                continue
            if acc:
                vb, vp = _rcp_base(v), _pe_int(v)
                v = next((a for a in acc if _rcp_base(a) == vb or str(a).strip().lower() == str(v).lower() or
                          (vp is not None and _pe_int(str(a).strip()) == vp)), None)
                if v is None:
                    continue
            if v not in vals:
                vals.append(v)
        if not vals:
            return "none" if not rows or kd != "trueparent" else None
        return vals[0] if len(vals) == 1 else vals
    except Exception:  # noqa: BLE001
        return None


# --- cmdline-canon: canonical command lines for matching declared vs observed spawns (process-tree / fetch-site) -------
# split_cmdline(s) follows CommandLineToArgvW (argv[0] up to the closing quote, 2n / 2n+1 backslashes before '"', a '""'
# run inside quotes yields '"' and leaves quote mode -- Wine's shell32 algorithm); posix=True reads sh quoting ('..',
# "..", \x) without shlex. canon_cmdline(s): outer quotes off, %VAR% / $env:VAR / ${env:VAR} via _PS_ENV, cmd carets
# and in-word '""' gone, image -> lower basename without .exe, cmd switches lower-case and the /c /k payload canonised
# recursively, powershell parameters -> full lower names (-enc/-e/-ec -> -command <UTF-16LE text>), system path
# prefixes (any case, / or \, PROGRA~1) -> one spelling, whitespace collapsed. Args keep their case. Never raises;
# None for a non-string / empty line. Reachable from decode(material, rep="cmdline", transform="canon"|"argv"|
# "argv_posix") so declared-codec fixtures exercise it; existing callers (_rcp_canon) are unchanged.
_CL_ENV = re.compile(r"%([A-Za-z_][\w()]*)%|\$\{env:([A-Za-z_]\w*)\}|\$env:([A-Za-z_]\w*)", re.I)
_CL_PATHS = ((r"[a-z]:[\\/]+windows[\\/]+system32[\\/]+", "C:\\Windows\\System32\\"),
             (r"[a-z]:[\\/]+windows[\\/]+syswow64[\\/]+", "C:\\Windows\\SysWOW64\\"),
             (r"[a-z]:[\\/]+windows[\\/]+sysnative[\\/]+", "C:\\Windows\\System32\\"),
             (r"[a-z]:[\\/]+windows(?=[\\/]|$)", "C:\\Windows"),
             (r"[a-z]:[\\/]+(?:program files \(x86\)|progra~2)(?=[\\/]|$)", "C:\\Program Files (x86)"),
             (r"[a-z]:[\\/]+(?:program files|progra~1)(?=[\\/]|$)", "C:\\Program Files"),
             (r"[a-z]:[\\/]+(?:programdata|progra~3)(?=[\\/]|$)", "C:\\ProgramData"),
             (r"[a-z]:[\\/]+users(?=[\\/]|$)", "C:\\Users"))
_CL_PATHS = tuple((re.compile(p, re.I), r) for p, r in _CL_PATHS)
_CL_PS = ("command", "encodedcommand", "executionpolicy", "file", "noprofile", "noninteractive", "nologo", "noexit",
          "windowstyle", "sta", "mta", "version", "inputformat", "outputformat", "configurationname", "workingdirectory",
          "commandwithargs", "settingsfile", "login", "interactive", "help")
_CL_PS_ALIAS = {"e": "encodedcommand", "ec": "encodedcommand", "enc": "encodedcommand", "c": "command",
                "f": "file", "ep": "executionpolicy", "ex": "executionpolicy", "w": "windowstyle", "nop": "noprofile",
                "noni": "noninteractive", "nol": "nologo", "noe": "noexit", "v": "version", "wd": "workingdirectory"}
_CL_PS_VAL = {"executionpolicy", "file", "windowstyle", "version", "inputformat", "outputformat", "configurationname",
              "workingdirectory", "settingsfile"}


def split_cmdline(s, posix=False):
    """Command line -> argv list (Windows CommandLineToArgvW rules, or POSIX sh quoting with posix=True); None for a
    non-string. Pure python, linear, never raises."""
    if not isinstance(s, str):
        return None
    try:
        return _cl_split_posix(s) if posix else _cl_split_win(s)
    except Exception:  # noqa: BLE001
        return None


def _cl_split_win(s):
    out, i, n = [], 0, len(s)
    while i < n and s[i] in " \t":
        i += 1
    if i >= n:
        return out
    if s[i] == '"':                                      # argv[0]: no backslash / doubled-quote processing
        j = s.find('"', i + 1)
        j = n if j < 0 else j
        out.append(s[i + 1:j])
        i = j + 1
    else:
        j = i
        while j < n and s[j] not in " \t":
            j += 1
        out.append(s[i:j])
        i = j
    cur, have, qcount, bs = [], False, 0, 0
    while i < n:
        c = s[i]
        if c in " \t" and not qcount % 2:
            cur.extend("\\" * bs)
            bs = 0
            if have:
                out.append("".join(cur))
                cur, have = [], False
            i += 1
            continue
        if c == "\\":
            bs += 1
            have = True
            i += 1
            continue
        if c == '"':
            cur.extend("\\" * (bs // 2))
            have = True
            if bs % 2:
                cur.append('"')
                bs = 0
                i += 1
                continue
            bs = 0
            qcount += 1
            i += 1
            while i < n and s[i] == '"':                 # Wine shell32: count the run of quotes
                qcount += 1
                if qcount == 3:
                    cur.append('"')
                    qcount = 0
                i += 1
            if qcount == 2:
                qcount = 0
            continue
        cur.extend("\\" * bs)
        bs = 0
        cur.append(c)
        have = True
        i += 1
    cur.extend("\\" * bs)
    if have:
        out.append("".join(cur))
    return out


def _cl_split_posix(s):
    out, cur, have, i, n = [], [], False, 0, len(s)
    while i < n:
        c = s[i]
        if c in " \t\r\n":
            if have:
                out.append("".join(cur))
                cur, have = [], False
        elif c == "'":
            j = s.find("'", i + 1)
            j = n if j < 0 else j
            cur.append(s[i + 1:j])
            have, i = True, j
        elif c == '"':
            i += 1
            while i < n and s[i] != '"':
                if s[i] == "\\" and i + 1 < n and s[i + 1] in '$`"\\\n':
                    i += 1
                    if s[i] != "\n":
                        cur.append(s[i])
                else:
                    cur.append(s[i])
                i += 1
            have = True
        elif c == "\\":
            if i + 1 < n and s[i + 1] != "\n":
                cur.append(s[i + 1])
                have = True
            i += 1
        else:
            cur.append(c)
            have = True
        i += 1
    if have:
        out.append("".join(cur))
    return out


def _cl_env(s):
    def sub(m):
        v = _PS_ENV.get((m.group(1) or m.group(2) or m.group(3) or "").lower())
        return v if v is not None else m.group(0)
    return _CL_ENV.sub(sub, s)


def _cl_cmd_unescape(s):
    """cmd.exe reading: '^x' -> 'x' outside double quotes; '""' glued inside a word dropped (`po""wer`)."""
    s = re.sub(r'(?<=[^\s"])""(?=[^\s"])', "", s)
    out, q, i, n = [], False, 0, len(s)
    while i < n:
        c = s[i]
        if c == '"':
            q = not q
        elif c == "^" and not q:
            if i + 1 < n:
                out.append(s[i + 1])
            i += 2
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _cl_path(a):
    for rx, rep in _CL_PATHS:
        m = rx.match(a)
        if m:
            a = rep + a[m.end():]
            break
    if re.match(r"[A-Za-z]:[\\/]|\\\\", a):
        a = a[:2] + re.sub(r"[\\/]+", r"\\", a[2:])
        a = a[0].upper() + a[1:] if a[1] == ":" else a
    return a


def _cl_quote(a):
    return '"' + a + '"' if not a or re.search(r"\s", a) else a


def _cl_image(a):
    b = re.split(r"[\\/]", a.strip().strip("\"'"))[-1].lower()
    return b[:-4] if b.endswith(".exe") else b


def _cl_tail(s, k):
    """Raw remainder of `s` after its first k Windows-split tokens (for cmd /c and powershell -command)."""
    i, n = 0, len(s)
    for _ in range(k):
        while i < n and s[i] in " \t":
            i += 1
        q = False
        while i < n and (q or s[i] not in " \t"):
            if s[i] == '"':
                q = not q
            i += 1
    return s[i:].strip()


def _cl_ws(s):
    return re.sub(r"\s+", " ", s).strip()


def _cl_ps_param(a):
    if not a or a[0] not in "-/" or len(a) < 2:
        return None
    p = a[1:].lower().rstrip(":")
    if p in _CL_PS_ALIAS:
        return _CL_PS_ALIAS[p]
    hits = [x for x in _CL_PS if x.startswith(p)]
    return hits[0] if len(hits) == 1 or p in _CL_PS else None


def _cl_b64_utf16(v):
    try:
        b = base64.b64decode(re.sub(r"\s+", "", v) + "=" * (-len(re.sub(r"\s+", "", v)) % 4), validate=True)
        if len(b) < 2 or len(b) % 2:
            return None
        t = b.decode("utf-16-le").lstrip("\ufeff")
        return t if t and all(ch.isprintable() or ch in "\r\n\t" for ch in t) else None
    except (binascii.Error, ValueError, UnicodeDecodeError):
        return None


def canon_cmdline(s, _depth=0):
    """Declared / observed command line -> one canonical string (see the block comment above); None when unreadable."""
    try:
        if not isinstance(s, str):
            return None
        s = s.replace("\x00", "").lstrip("\ufeff").strip()
        for q in ('"', "'"):                              # outer quotes around the WHOLE line
            if len(s) > 1 and s[0] == q and s[-1] == q and q not in s[1:-1] and re.search(r"\s", s):
                s = s[1:-1].strip()
        s = _cl_cmd_unescape(_cl_env(s))
        argv = _cl_split_win(s)
        if not argv or not argv[0].strip():
            return None
        img = _cl_image(argv[0])
        out = [img]
        if img == "cmd":
            for k in range(1, len(argv)):
                a = argv[k]
                if re.fullmatch(r"/[A-Za-z](?::\w+)?", a):
                    out.append(a.lower())
                    if a.lower() in ("/c", "/k", "/r"):
                        rest = _cl_tail(s, k + 1)
                        if len(rest) > 1 and rest[0] == '"' and rest[-1] == '"':
                            rest = rest[1:-1]
                        inner = canon_cmdline(rest, _depth + 1) if _depth < 4 and rest else None
                        if inner or rest:
                            out.append(inner or _cl_ws(rest))
                        break
                else:
                    out.append(_cl_quote(_cl_path(a)))
            return _cl_ws(" ".join(out))
        if img in ("powershell", "pwsh", "powershell_ise"):
            k = 1
            while k < len(argv):
                a, p = argv[k], _cl_ps_param(argv[k])
                if p == "encodedcommand" and k + 1 < len(argv):
                    t = _cl_b64_utf16(argv[k + 1])
                    if t is not None:
                        out += ["-command", _cl_ws(t)]
                        k += 2
                        continue
                    out += ["-encodedcommand", argv[k + 1]]
                    k += 2
                    continue
                if p == "command":
                    rest = _cl_tail(s, k + 1)
                    if len(rest) > 1 and rest[0] == '"' and rest[-1] == '"' and '"' not in rest[1:-1]:
                        rest = rest[1:-1]
                    out += ["-command", _cl_ws(rest)] if rest else ["-command"]
                    break
                if p is None and a[:1] not in "-/":              # bare script text = implicit -command
                    out += ["-command", _cl_ws(_cl_tail(s, k))]
                    break
                if p is None:
                    out.append(a)
                    k += 1
                    continue
                out.append("-" + p)
                if p in _CL_PS_VAL and k + 1 < len(argv):
                    v = argv[k + 1]
                    out.append(_cl_quote(_cl_path(v)) if p in ("file", "workingdirectory", "settingsfile")
                               else _cl_quote(v.lower()))
                    k += 1
                k += 1
            return _cl_ws(" ".join(out))
        out += [_cl_quote(_cl_path(a)) for a in argv[1:]]
        return _cl_ws(" ".join(out))
    except Exception:  # noqa: BLE001
        return None


def _cl_decode(material, rep, transform):
    """decode() hook for rep 'cmdline': transform canon -> canon_cmdline, argv / argv_posix -> JSON argv list."""
    import json
    t = re.sub(r"[^a-z]", "", (transform or "").lower())
    if t in ("canon", "canonical", "canonicalize", "normalize"):
        return canon_cmdline(material)
    if t in ("argv", "split", "argvwin", "splitwin", "argvposix", "splitposix"):
        a = split_cmdline(material, posix=t.endswith("posix"))
        return None if a is None else json.dumps(a, ensure_ascii=False)
    return None


# ------------------------------------------------------------------------------------------------ nested string carrier
# Target nested-string-carrier-unescape (D19 ASPX `private static readonly string EmbeddedCsx_<id> = "// HUNTRESS..\n
# #nullable enable\n..string descriptor_<id> = \"..\";\n";`): the inner script rides as an escaped string literal of
# its host. inner_scripts() lexes the host's string literals in every host string syntax (C-family backslash escapes,
# C# verbatim / raw / interpolated, VB `""` + `& vbCrLf & _` concatenation, PS here-strings + backtick escapes,
# Python triple / raw / implicit concatenation, JS template literals, PHP heredoc / nowdoc, Perl q{}/qq{}, Ruby %q()
# / heredoc `<<~`), plus whole-text unwraps (XML entities + CDATA, Java pre-lex `\uXXXX`, base64 / hex of a whole
# inner file), recursing to depth 3. _nested_codecs() runs the normal readings on every unescaped text that names a
# marker / descriptor / codec. find_codecs() consults it only when nothing else produced a plan (or when a nested
# reading strictly extends a truncated outer plan), so every earlier reading is unchanged. Bounded, never raises.
_NS_OPEN = re.compile(r"""<<<|<<[~-]?(?=["'A-Za-z_])|\$@"|@\$"|\$"{3,}|"{3,}|'{3}|@"|@'|\$"|(?<![\w$])[rRbBuUfF]{1,2}(?=["'])|"|'|`|"""
                      r"""(?<![\w$])%[qQwW]?[({\[<|!]|(?<![\w$>:-])qq?\s*[({\[<|!/]|\[=*\[|//|/\*|(?:^|(?<=\s))#|^[ \t]*(?i:rem)\b""", re.M)
_NS_C_ESC = re.compile(r"""\\(u\{[0-9a-fA-F]{1,6}\}|x\{[0-9a-fA-F]{1,6}\}|u[0-9a-fA-F]{4}|U[0-9a-fA-F]{8}|x[0-9a-fA-F]{1,4}|"""
                       r"""[0-7]{1,3}|\r?\n|.)""", re.S)
_NS_C_SIMPLE = {"n": "\n", "r": "\r", "t": "\t", "a": "\a", "b": "\b", "f": "\f", "v": "\v", "e": "\x1b", "0": "\0",
                "\\": "\\", '"': '"', "'": "'", "`": "`", "$": "$", "/": "/", "?": "?", "{": "{", "}": "}", "@": "@"}
_NS_PS_ESC = {"n": "\n", "r": "\r", "t": "\t", "0": "\0", "a": "\a", "b": "\b", "f": "\f", "v": "\v", "e": "\x1b"}
_NS_CONST = re.compile(r"""(?i:vbCrLf|vbNewLine|vbLf|vbCr|vbTab|vbNullString|vbNullChar|PHP_EOL|Environment\.NewLine|"""
                       r"""os\.linesep|\$\(?\[(?:Environment|System\.Environment)\]::NewLine\)?)\b|"""
                       r"""(?i:chrw?\$?|chr|char)\s*\(\s*(?P<n>\d{1,7}|&H[0-9a-fA-F]{1,6})\s*\)|\[char\]\s*(?P<p>\d{1,7})|"""
                       r"""String\.fromCharCode\s*\(\s*(?P<j>\d{1,7})\s*\)""")
_NS_CONST_V = {"vbcrlf": "\r\n", "vbnewline": "\r\n", "vblf": "\n", "vbcr": "\r", "vbtab": "\t", "vbnullstring": "",
               "vbnullchar": "\0", "php_eol": "\n", "environment.newline": "\r\n", "os.linesep": "\n"}
_NS_CONCAT = re.compile(r"""(?:[ \t]*(?:&|\+|\.\.?(?![\w.])|<<)?[ \t]*(?:(?<=\s)_[ \t]*\r?\n|`[ \t]*\r?\n|\\[ \t]*\r?\n)?\s*)""")
_NS_LOSSY = re.compile(r"HUNTRESS_ANALYSIS_V\d+:\w+-[^\s\"'<]*(?:\\[uUx0-7]|&#|`)")
_NS_HINT = re.compile(r"HUNTRESS_ANALYSIS|descriptor[_-]|\b(?:Codec|CODEC)_|HUNTRESS-CODEC", re.I)
_NS_B64 = re.compile(r"[A-Za-z0-9+/\-_\s]{32,}={0,2}")
_NS_HEXRE = re.compile(r"(?:[0-9a-fA-F]{2}[\s:,]?){16,}")
_NS_VB_CUE = re.compile(r"""(?im)\bvbCrLf\b|^[ \t]*(?:Dim|Set|Sub|Function|End\s+(?:Sub|Function))\b|&[ \t]*_[ \t]*\r?$|"""
                        r"""Language\s*=\s*["']?(?:VB|VBScript)\b|CreateObject\(""")
_NS_PS_CUE = re.compile(r"""(?im)^[ \t]*\$[\w:]+\s*=|@['"][ \t]*\r?$|\b(?:Write-Host|Write-Output|Set-Content|Invoke-Expression|"""
                        r"""param\s*\(|function\s+[\w-]+\s*\{|-join\b)""")
_NS_LANG_VB = re.compile(r"""(?is)<%@[^>]*Language\s*=\s*["']?(?:VB|VBScript)|<script\b[^>]*language\s*=\s*["']?(?:VB|VBScript)""")


def _ns_surr(s):
    try:
        return s.encode("utf-16-le", "surrogatepass").decode("utf-16-le", "replace")
    except Exception:  # noqa: BLE001
        return s


def _ns_cesc(body, csx=False, interp=False):
    """C-family backslash unescape (C#/Java/JS/JSON/Python/PHP/Perl/Ruby). csx: C# `\\xH{1,4}` (else 2 hex digits)."""
    def rep(m):
        e = m.group(1)
        c = e[0]
        try:
            if c in "uU" and len(e) > 1:
                return chr(int(e[2:-1] if e[1] == "{" else e[1:], 16))
            if c == "x" and len(e) > 1:
                if e[1] == "{":
                    return chr(int(e[2:-1], 16))
                h = e[1:] if csx else e[1:3]
                return chr(int(h, 16)) + ("" if csx else e[3:])
            if c in "01234567" and (len(e) > 1 or c != "0"):
                return chr(int(e, 8))
        except (ValueError, OverflowError):
            return m.group(0)
        if e in ("\n", "\r\n"):
            return ""
        return _NS_C_SIMPLE.get(e, "\\" + e)
    out = _ns_surr(_NS_C_ESC.sub(rep, body))
    return out.replace("{{", "{").replace("}}", "}") if interp else out


def _ns_psesc(body):
    def rep(m):
        e = m.group(1)
        if e.startswith("u{"):
            try:
                return chr(int(e[2:-1], 16))
            except (ValueError, OverflowError):
                return m.group(0)
        return _NS_PS_ESC.get(e, e)
    return re.sub(r"`(u\{[0-9a-fA-F]{1,6}\}|.)", rep, body.replace('""', '"'), flags=re.S)


def _ns_dedent(body, closing_ws=None):
    lines = body.split("\n")
    if closing_ws is None:
        ind = [len(x) - len(x.lstrip(" \t")) for x in lines if x.strip()]
        n = min(ind) if ind else 0
    else:
        n = len(closing_ws)
    return "\n".join(x[n:] if x[:n].strip() == "" else x.lstrip(" \t") for x in lines)


def _ns_quoted(s, i, q, esc, double, multiline=True):
    """End index (after the closing quote) and raw body of a q-quoted literal opened at s[i] == q, else (None, None)."""
    j, n, lim = i + 1, len(s), min(len(s), i + (1 << 20))
    while j < lim:
        c = s[j]
        if esc and c == esc:
            j += 2
            continue
        if c == q:
            if double and j + 1 < n and s[j + 1] == q:
                j += 2
                continue
            return j + 1, s[i + 1:j]
        if c == "\n" and not multiline:
            return None, None
        j += 1
    return None, None


def _ns_heredoc(s, i, m):
    """PHP `<<<TAG` / `<<<'TAG'`, Ruby/Perl/sh `<<~TAG` `<<-TAG` `<<'TAG'`: (end, [(value, syntax)]) or (None, [])."""
    php = m == "<<<"
    hm = re.compile(r"""[ \t]*(["']?)([A-Za-z_]\w*)\1""").match(s, i + len(m))
    if not hm:
        return None, []
    tag, quote = hm.group(2), hm.group(1)
    nl = s.find("\n", hm.end())
    if nl < 0:
        return None, []
    cm = re.compile(r"^([ \t]*)" + re.escape(tag) + r"\b", re.M).search(s, nl + 1)
    if not cm:
        return None, []
    body = s[nl + 1:max(nl + 1, cm.start() - 1)]
    if body.endswith("\r"):
        body = body[:-1]
    if php:
        body = _ns_dedent(body, cm.group(1))
        syn = "php_nowdoc" if quote == "'" else "php_heredoc"
    else:
        if m.endswith("~"):
            body = _ns_dedent(body)
        syn = "heredoc_raw" if quote == "'" else "heredoc"
    val = body if quote == "'" else _ns_cesc(body)
    return cm.end(), [(val, syn)] + ([(body, syn + "_raw")] if val != body else [])


_NS_PAIR = {"(": ")", "{": "}", "[": "]", "<": ">"}


def _ns_balanced(s, i, op):
    cl = _NS_PAIR.get(op, op)
    depth, j, lim = 1, i, min(len(s), i + (1 << 20))
    while j < lim:
        c = s[j]
        if c == "\\":
            j += 2
            continue
        if c == cl and op != cl or (c == cl and op == cl):
            depth -= 1
            if depth == 0:
                return j + 1, s[i:j]
        elif c == op and op != cl:
            depth += 1
        j += 1
    return None, None


def _ns_literal(s, i, m, dialect):
    """Parse the literal whose opener `m` sits at s[i]: (end, [(value, syntax), ..]); (None, []) when it is none.
    Comments return (end, [])."""
    if m in ("//", "#") or m.lower().lstrip(" \t") == "rem":
        if m == "#" and dialect == "vb":
            return None, []
        e = s.find("\n", i)
        return (len(s) if e < 0 else e), []
    if m == "/*":
        e = s.find("*/", i + 2)
        return (len(s) if e < 0 else e + 2), []
    if m.startswith("<<"):
        return _ns_heredoc(s, i, m)
    if m.startswith("[") and m.endswith("["):                                    # Lua long bracket
        close = "]" + "=" * (len(m) - 2) + "]"
        e = s.find(close, i + len(m))
        if e < 0:
            return None, []
        body = s[i + len(m):e]
        return e + len(close), [(body[1:] if body.startswith("\n") else body, "lua_long")]
    if m.startswith("%") or m.lstrip("q").strip() != m.strip() or m[:1] == "q":
        op = m[-1]
        e, body = _ns_balanced(s, i + len(m), op)
        if e is None:
            return None, []
        raw = m[:2] in ("%q", "%w") or (m[0] == "q" and m[:2] != "qq")
        if raw:
            return e, [(re.sub(r"\\([\\" + re.escape(op + _NS_PAIR.get(op, op)) + "])", r"\1", body), "q_literal")]
        return e, [(_ns_cesc(body), "qq_literal")]
    if dialect == "ps" and m in ('@"', "@'"):                                  # PS here-string
        q = m[1]
        hm = re.compile(r"[ \t]*\r?\n").match(s, i + 2)
        if hm:
            cm = re.compile(r"\r?\n" + q + "@").search(s, hm.end())
            if cm:
                body = s[hm.end():cm.start()]
                return cm.end(), [(_ns_psesc(body) if q == '"' else body, "ps_here_" + ("dq" if q == '"' else "sq"))]
        return None, []
    if m in ('@"', '$@"', '@$"'):                                               # C# verbatim (interpolated)
        e, body = _ns_quoted(s, i + len(m) - 1, '"', None, True)
        if e is None:
            return None, []
        v = body.replace('""', '"')
        return e, [(v.replace("{{", "{").replace("}}", "}") if "$" in m else v, "cs_verbatim")]
    if m.lstrip("$").startswith('"""') or m == "'''":                           # C# raw / Python triple / Java block
        k = len(m.lstrip("$"))
        q = m[-1] * k
        e = s.find(q, i + len(m))
        if e < 0:
            return None, []
        while e + k < len(s) and s[e + k] == q[0]:
            e += 1
        body = s[i + len(m):e]
        outs = []
        if body.lstrip(" \t").startswith(("\n", "\r\n")):                       # C# raw / Java text block: dedent
            last = body.rsplit("\n", 1)
            cws = last[1] if len(last) == 2 and not last[1].strip() else None
            core = body.split("\n", 1)[1] if "\n" in body else body
            if cws is not None:
                core = core[:len(core) - len(cws)] if core.endswith(cws) else core
                core = core[:-2] if core.endswith("\r\n") else core[:-1] if core.endswith("\n") else core
            outs.append((_ns_dedent(core, cws), "cs_raw"))
        outs.append((_ns_cesc(body), "py_triple"))
        outs.append((body, "raw_triple"))
        return e + k, outs
    if m[-1:] in "\"'" and m[:-1] and m[:-1].isalpha():                          # Python prefixes r b u f / C# $"
        pass
    if len(m) in (1, 2) and m.isalpha():                                         # r'..' b"..": prefix + quote
        q = s[i + len(m)] if i + len(m) < len(s) else ""
        if q not in "\"'":
            return None, []
        if s.startswith(q * 3, i + len(m)):
            e, outs = _ns_literal(s, i + len(m), q * 3, dialect)
            if e is None:
                return None, []
            return e, ([(o[0], "py_raw_triple") for o in outs if o[1] == "raw_triple"]
                       if "r" in m.lower() else [o for o in outs if o[1] == "py_triple"])
        e, body = _ns_quoted(s, i + len(m), q, "\\", False, multiline=False)
        if e is None:
            return None, []
        if "r" in m.lower():
            return e, [(body, "py_raw")]
        return e, [(_ns_cesc(body, interp="f" in m.lower()), "py_prefixed")]
    if m == '$"':                                                                # C# interpolated regular
        e, body = _ns_quoted(s, i + 1, '"', "\\", False, multiline=False)
        if e is None:
            return None, []
        return e, [(_ns_cesc(body, csx=True, interp=True), "cs_interpolated")]
    if m == "`":
        if dialect == "ps":
            return None, []
        e, body = _ns_quoted(s, i, "`", "\\", False)
        if e is None:
            return None, []
        return e, [(_ns_cesc(body), "js_template")]
    if m in ('"', "'", '@"', "@'"):
        q = m[-1]
        if dialect == "vb":
            if q == "'":                                                         # VB comment
                e = s.find("\n", i)
                return (len(s) if e < 0 else e), []
            e, body = _ns_quoted(s, i, '"', None, True, multiline=False)
            return (e, [(body.replace('""', '"'), "vb")]) if e is not None else (None, [])
        if dialect == "ps":
            e, body = _ns_quoted(s, i, q, "`" if q == '"' else None, True)
            if e is None:
                return None, []
            return e, [(_ns_psesc(body), "ps_dq") if q == '"' else (body.replace("''", "'"), "ps_sq")]
        e, body = _ns_quoted(s, i, q, "\\", False, multiline=(q == '"'))
        if e is None:
            return None, []
        v = _ns_cesc(body)
        outs = [(v, "c_escaped")]
        vx = _ns_cesc(body, csx=True)
        if vx != v:
            outs.append((vx, "cs_regular"))
        if q == "'":
            vp = re.sub(r"\\([\\'])", r"\1", body)
            if vp != v:
                outs.append((vp, "php_single"))
        return e, outs
    return None, []


def _ns_atom_const(s, i):
    m = _NS_CONST.match(s, i)
    if not m:
        return None, None
    n = m.group("n") or m.group("p") or m.group("j")
    if n is not None:
        try:
            v = int(n[2:], 16) if n[:2].lower() == "&h" else int(n)
            return m.end(), chr(v)
        except (ValueError, OverflowError):
            return None, None
    return m.end(), _NS_CONST_V.get(m.group(0).lower(), "\r\n" if "newline" in m.group(0).lower() else "\n")


def _ns_literals(s, dialect, limit=600):
    """[(host_var, value, syntax)] of every string literal (and its concatenation run) in s, lexed in `dialect`."""
    out, i, n, cnt = [], 0, len(s), 0
    while i < n and cnt < limit:
        m = _NS_OPEN.search(s, i)
        if not m:
            break
        tok = m.group(0)
        st = m.start() + (len(tok) - len(tok.lstrip(" \t")) if tok.lower().strip().startswith("rem") else 0)
        if dialect != "vb" and tok.strip().lower() == "rem" or (dialect == "vb" and tok in ("//", "/*", "`")):
            i = m.end()
            continue
        if dialect == "ps" and tok in ("//", "/*"):
            i = m.end()
            continue
        if dialect != "ps" and tok in ("#",) and s[m.end():m.end() + 1] in ("{", "["):
            i = m.end()
            continue
        e, vals = _ns_literal(s, st, tok.strip() if tok.strip().lower() == "rem" else tok, dialect)
        if e is None:
            i = m.end()
            continue
        if not vals:
            i = max(e, m.end())
            continue
        cnt += 1
        pre = s[max(0, st - 120):st]
        vm = re.search(r"([A-Za-z_$@][\w.$:]*)\s*(?:\]|\))?\s*(?::=|=>|\.=|\+=|=|:|\(|,)\s*(?:\(\s*)?$", pre)
        var = vm.group(1) if vm else ""
        run, j = [vals[0][0]], e
        while j < n and len(run) < 4096:                            # concatenation / implicit adjacency run
            cm = _NS_CONCAT.match(s, j)
            k = cm.end() if cm else j
            if k == j and not s.startswith(("&", "+"), j):
                break
            sep = s[j:k]
            if not sep.strip() and "\n" in sep and dialect in ("vb", "ps"):
                break
            if not sep.strip() and "\n" in sep and not re.search(r"\(\s*$", pre[-40:]):
                break
            ce, cv = _ns_atom_const(s, k)
            if ce is not None:
                run.append(cv)
                j = ce
                continue
            om = _NS_OPEN.match(s, k)
            if not om or om.group(0) in ("//", "/*", "#", "<<<") or om.group(0).startswith("<<"):
                break
            le, lv = _ns_literal(s, k, om.group(0), dialect)
            if le is None or not lv:
                break
            run.append(lv[0][0])
            j = le
        for v, syn in vals:
            out.append((var, v, syn))
        if len(run) > 1:
            out.append((var, "".join(run), vals[0][1] + "+concat"))
        i = max(j, m.end())
    return out


def _ns_whole(s):
    """Whole-text unwraps: XML (CDATA + entities), Java pre-lex unicode escapes. [(syntax, text)]."""
    out = []
    if "<![CDATA[" in s or re.search(r"&(?:#x?[0-9a-fA-F]{1,6}|lt|gt|amp|quot|apos);", s):
        import html
        parts = re.split(r"<!\[CDATA\[(.*?)\]\]>", s, flags=re.S)
        t = "".join(p if k % 2 else html.unescape(p) for k, p in enumerate(parts))
        if t != s:
            out.append(("xml", t))
        out += [("cdata", p) for p in parts[1::2][:64] if len(p.strip()) >= 16]
    if re.search(r"(?<!\\)(?:\\\\)*\\u+[0-9a-fA-F]{4}", s):
        t = _ns_surr(re.sub(r"(?<!\\)((?:\\\\)*)\\u+([0-9a-fA-F]{4})", lambda m: m.group(1) + chr(int(m.group(2), 16)), s))
        if t != s:
            out.append(("java_unicode", t))
    return out


def _ns_blob(v):
    """A literal holding base64 / hex of a whole inner file: [(syntax, text)]."""
    out = []
    w = v.strip()
    if len(w) < 32 or len(w) > (1 << 21):
        return out
    if _NS_HEXRE.fullmatch(w) or re.fullmatch(r"(?:\\x[0-9a-fA-F]{2}){16,}", w):
        h = re.sub(r"\\x|[\s:,]", "", w)
        try:
            t = _leaf_text(bytes.fromhex(h)) if len(h) % 2 == 0 else None
        except ValueError:
            t = None
        if t and t != w:
            out.append(("hex", t))
    if not out and _NS_B64.fullmatch(w):
        t = normalize(w)
        if t and t != w:
            out.append(("base64", t))
    return out


def inner_scripts(src, depth=3, budget=0.4, limit=200):
    """Every inner script carried as an (escaped / encoded) string literal of its host, recursively to `depth`:
    [(host_var, unescaped_text, syntax)]. Only texts that differ from their raw host bytes and look like more than a
    word (a newline, or 16+ chars). Never raises."""
    res = []
    try:
        if isinstance(src, (bytes, bytearray)):
            src = bytes(src).decode("utf-8", "ignore")
        end = time.time() + budget
        seen = {src}
        frontier = [("", src or "", "host")]
        for _ in range(depth):
            nxt = []
            for _var, text, _syn in frontier:
                if time.time() > end or len(res) >= limit:
                    break
                text = text[:1 << 20]
                dialects = ["c"]
                if _NS_LANG_VB.search(text[:4096]) or _NS_VB_CUE.search(text):
                    dialects.insert(0, "vb")
                if _NS_PS_CUE.search(text):
                    dialects.append("ps")
                cands = [("", t, syn) for syn, t in _ns_whole(text)]
                for d in dialects:
                    if time.time() > end:
                        break
                    cands += _ns_literals(text, d)
                for var, v, syn in list(cands):
                    if len(v) >= 32:
                        cands += [(var, t, syn + ">" + bs) for bs, t in _ns_blob(v)]
                for var, v, syn in cands:
                    if v in seen or len(v) < 16:
                        continue
                    seen.add(v)
                    item = (var, v, syn)
                    res.append(item)
                    nxt.append(item)
                    if len(res) >= limit:
                        break
            frontier = nxt
            if not frontier:
                break
    except Exception:  # noqa: BLE001
        return res
    return res


def _ns_names_only(text):
    """_find_codecs_text with declared names only (no name-agnostic fallback): the host-level readers already ran
    the fallbacks over the raw document, a junk decoy codec must not cost them twice."""
    global FALLBACK
    old, FALLBACK = FALLBACK, False
    try:
        return _find_codecs_text(text)
    finally:
        FALLBACK = old


def _nested_codecs(src, budget=0.6):
    """find_codecs readings of every inner script that names a marker / descriptor / codec (deduped by plan)."""
    out, seen = [], set()
    try:
        end = time.time() + budget
        for var, text, syn in inner_scripts(src, budget=budget * 0.5):
            if time.time() > end:
                break
            if not _NS_HINT.search(text):
                continue
            # a whole-document unwrap (XML / Java pre-lex) is the host again: the core marker / descriptor readers only
            # (its literals are lexed again at the next depth); a big one is cut to its marker-bearing lines
            whole = syn in ("xml", "java_unicode") or len(text) > (1 << 15)
            if whole and len(text) > 4096:
                text = "\n".join(ln for ln in text.splitlines() if _NS_HINT.search(ln))[:1 << 16]
            for c in (_ns_names_only(text) if whole else find_codecs(text, 1)):
                p = c.get("plain")
                if p and p not in seen:
                    seen.add(p)
                    out.append(dict(c, id=f"{c.get('id')}@{var or syn}"))
    except Exception:  # noqa: BLE001
        return out
    return out


# ------------------------------------------------------------------------------------------------ CI pipeline step bodies
# Target pipeline-step-inner-scripts (D20 "trace the modeled build into its prior-language stages"): a Jenkinsfile
# (declarative / scripted Groovy: `sh '''..'''`, `sh(script: "..", returnStdout: true)`, bat / powershell / pwsh,
# `script { .. }`, `node('label')`, `agent { label 'x' }` / `docker { image 'x' }`) or a CI YAML (GitHub Actions
# `run:` + `shell:` / `actions/github-script` `script:`, GitLab `script:` lists, Azure `- bash:` / `- powershell:` /
# task inputs, CircleCI `run: command:`, Bitbucket `script:`, Drone `commands:`) carries prior-language scripts in its
# step bodies. pipeline_steps() reads them with the host's own string semantics (Groovy escapes + GString `${x}` from
# literal environment / def bindings, YAML block / folded / quoted scalars); _pipeline_codecs() runs find_codecs on
# every body. Readings are only prepended when the host escape changed the body (the raw-host readers read it lossy)
# or nothing else found a plan. Pure Python, bounded, never raises.

_CI_CUE = re.compile(r"\bpipeline\s*\{|\bnode\s*\(|\bstage\s*\(\s*['\"]|^[ \t]*-?[ \t]*(?:jobs|steps|stages|script|"
                     r"before_script|after_script|commands|run|bash|powershell|pwsh|runs-on|pipelines)[ \t]*:", re.M)
_CI_LANG = {"sh": "bash", "bash": "bash", "zsh": "bash", "dash": "bash", "ash": "bash", "bat": "batch", "cmd": "batch",
            "powershell": "powershell", "pwsh": "powershell", "ps": "powershell", "python": "python",
            "python3": "python", "py": "python", "node": "node", "github-script": "node", "groovy": "groovy",
            "perl": "perl", "ruby": "ruby"}
_CI_TASK = {"bash": "bash", "shellscript": "bash", "powershell": "powershell", "azurepowershell": "powershell",
            "cmdline": "cmd", "pythonscript": "python", "azurecli": "bash"}
_CI_GSTEPS = ("sh", "bat", "powershell", "pwsh")
_CI_GESC = re.compile(r"\\(u[0-9a-fA-F]{4}|[0-3][0-7]{0,2}|\r?\n|.)", re.S)
_CI_GVAR = re.compile(r"(?<!\\)((?:\\\\)*)\$(?:\{\s*([A-Za-z_][\w.]*)\s*\}|([A-Za-z_][\w]*(?:\.[A-Za-z_]\w*)*))")
_CI_GBIND = re.compile(r"""(?m)^[ \t]*(?:(?:def|final|String|static|private)[ \t]+)*(?:env\.)?([A-Za-z_]\w*)[ \t]*=[ \t]*"""
                       r"""('(?:[^'\\\n]|\\.)*'|"(?:[^"\\$\n]|\\.)*")[ \t]*;?[ \t]*$""")
_CI_YBODY = {"run": "run", "script": "script", "before_script": "script", "after_script": "script",
             "commands": "script", "command": "run", "bash": "bash", "powershell": "powershell", "pwsh": "pwsh",
             "inlinescript": "script", "inline": "script", "cmd": "cmd"}
_CI_YLINE = re.compile(r"( *)(?:(-)(?: +|$))?")
_CI_YKEY = re.compile(r"""("[^"\n]*"|'[^'\n]*'|[^\s:#'"\[\]{},&*!|>-][^:#\n]*?)[ \t]*:(?=[ \t]|$)[ \t]*(.*)$""")
_CI_YDQ = {"n": "\n", "t": "\t", "r": "\r", "0": "\0", "\\": "\\", '"': '"', "/": "/", " ": " ", "e": "\x1b",
           "a": "\a", "b": "\b", "v": "\v", "f": "\f", "N": "\x85", "_": "\xa0", "L": "\u2028", "P": "\u2029"}


def _ci_lang(shell, default="bash"):
    w = re.split(r"[\s{]", (shell or "").strip().lower(), 1)[0].rsplit("/", 1)[-1]
    w = re.sub(r"(?:\.exe|@\d+)$", "", w)
    return _CI_LANG.get(w) or _CI_LANG.get(re.sub(r"[\d.]+$", "", w)) or (default if not w else w)


def _ci_gstr(s, i):
    """(inner, quote, end) of the Groovy string literal at s[i], or None."""
    for q in ("'''", '"""'):
        if s.startswith(q, i):
            j = i + 3
            while j < len(s):
                if s[j] == "\\":
                    j += 2
                    continue
                if s.startswith(q, j):
                    return s[i + 3:j], q, j + 3
                j += 1
            return None
    c = s[i:i + 1]
    if c in ("'", '"'):
        j = i + 1
        while j < len(s) and s[j] != "\n":
            if s[j] == "\\":
                j += 2
                continue
            if s[j] == c:
                return s[i + 1:j], c, j + 1
            j += 1
        return None
    if s.startswith("$/", i):
        k = s.find("/$", i + 2)
        return (s[i + 2:k], "$/", k + 2) if k > 0 else None
    return None


def _ci_gunescape(t, q, env):
    """Groovy string semantics: GString `${x}` / `$x` from literal bindings (else kept), then backslash escapes."""
    if q == "$/":
        return t.replace("$$", "$").replace("$/", "/")
    if q in ('"', '"""'):
        def sub(m):
            name = m.group(2) or m.group(3)
            v = env.get(re.sub(r"^(?:env|params)\.", "", name))
            return m.group(1) + v if v is not None else m.group(0)
        t = _CI_GVAR.sub(sub, t)

    def esc(m):
        x = m.group(1)
        if x[0] == "u":
            return chr(int(x[1:], 16))
        if x[0] in "0123":
            return chr(int(x, 8))
        if x[0] in "\r\n":
            return ""
        return {"n": "\n", "t": "\t", "r": "\r", "b": "\b", "f": "\f", "s": " "}.get(x, x)
    return _CI_GESC.sub(esc, t)


def _ci_glits(s, i, env, stop):
    """Value at s[i]: one Groovy literal or a `'a' + "b"` concatenation -> (text, raw, end) or (None, None, i)."""
    parts, raws, j = [], [], i
    while j < len(s):
        r = _ci_gstr(s, j)
        if not r:
            break
        parts.append(_ci_gunescape(r[0], r[1], env))
        raws.append(r[0])
        m = re.compile(r"[ \t\r\n]*\+[ \t\r\n]*").match(s, r[2])
        if not m:
            j = r[2]
            break
        j = m.end()
    return ("".join(parts), "".join(raws), j) if parts else (None, None, i)


def _ci_jenkins(src):
    env = {}
    for m in _CI_GBIND.finditer(src[:1 << 18]):
        r = _ci_gstr(m.group(2), 0)
        if r:
            env.setdefault(m.group(1), _ci_gunescape(r[0], r[1] if r[1] == "'" else "'", {}))
    out, stack, pend, i, n = [], [{"stage": None, "agent": None}], {}, 0, len(src)
    ident = re.compile(r"[A-Za-z_]\w*")
    while i < n and len(out) < 128:
        c = src[i]
        if src.startswith("//", i):
            k = src.find("\n", i)
            i = n if k < 0 else k
            continue
        if src.startswith("/*", i):
            k = src.find("*/", i + 2)
            i = n if k < 0 else k + 2
            continue
        if c in "'\"" or src.startswith("$/", i):
            r = _ci_gstr(src, i)
            i = r[2] if r else i + 1
            continue
        if c == "{":
            fr = dict(stack[-1])
            fr.update(pend)
            pend = {}
            stack.append(fr)
            i += 1
            continue
        if c == "}":
            if len(stack) > 1:
                stack.pop()
            i += 1
            continue
        if (c.isalpha() or c == "_") and not (i and (src[i - 1].isalnum() or src[i - 1] in "_.$")):
            w = ident.match(src, i)
            word, j = w.group(0), w.end()
            if word == "stage":
                m = re.compile(r"\s*\(\s*(?:name\s*:\s*)?").match(src, j)
                r = _ci_gstr(src, m.end()) if m else None
                if r:
                    pend["stage"] = _ci_gunescape(r[0], r[1], env)
                    j = r[2]
            elif word == "node":
                m = re.compile(r"\s*(\()?\s*").match(src, j)
                r = _ci_gstr(src, m.end())
                if r:
                    pend["agent"], j = _ci_gunescape(r[0], r[1], env), r[2]
                elif m.group(1) or src[m.end():m.end() + 1] == "{":
                    pend["agent"] = "any"
            elif word == "agent":
                seg = src[j:j + 600]
                m = re.match(r"\s+(any|none)\b", seg) or re.match(
                    r"""\s*\{\s*(?:(?:docker|node|dockerfile|kubernetes)\s*\{[^{}]*?)?(?:label|image|filename)\s*"""
                    r""":?\s*['"]([^'"\n]*)['"]""", seg) or re.match(r"""\s*\{\s*(docker|any|none)\b(?:\s*['"]([^'"\n]*)['"])?""", seg)
                if m:
                    stack[-1]["agent"] = m.group(m.lastindex)
            elif word in _CI_GSTEPS:
                m = re.compile(r"[ \t]*(\()?\s*").match(src, j)
                k, body, raw = m.end(), None, None
                paren = bool(m.group(1))
                if not paren and not (src[k:k + 1] in "'\"$" or re.match(r"script\s*:", src[k:k + 12])):
                    i = j
                    continue
                for _ in range(8):
                    km = re.compile(r"([A-Za-z_]\w*)\s*:\s*").match(src, k)
                    name = km.group(1) if km else None
                    v, rv, e = _ci_glits(src, km.end() if km else k, env, None)
                    if v is None:
                        e2 = re.compile(r"[^,)\n]*").match(src, km.end() if km else k).end()
                        e = e2 if e2 > k else k + 1
                    elif name in (None, "script") and body is None:
                        body, raw = v, rv
                    sep = re.compile(r"\s*,\s*" if paren else r"[ \t]*,\s*").match(src, e)
                    if not sep:
                        k = e
                        break
                    k = sep.end()
                if body is not None:
                    fr = stack[-1]
                    she = re.match(r"#!\s*(?:/usr)?/bin/(?:env\s+)?(\S+)", body.lstrip())
                    out.append({"stage": pend.get("stage", fr["stage"]), "step_kind": word, "shell": word,
                                "lang": _ci_lang(she.group(1) if she else word), "body": body,
                                "agent_label": pend.get("agent", fr["agent"]), "cooked": body != raw})
                i = max(k, j)
                continue
            elif word == "script" and src[j:j + 40].lstrip().startswith("{"):
                b0 = src.index("{", j)
                d, e = 0, b0
                while e < n:
                    r = _ci_gstr(src, e) if src[e] in "'\"" else None
                    if r:
                        e = r[2]
                        continue
                    d += {"{": 1, "}": -1}.get(src[e], 0)
                    if d == 0:
                        break
                    e += 1
                fr = stack[-1]
                out.append({"stage": fr["stage"], "step_kind": "script", "shell": "groovy", "lang": "groovy",
                            "body": src[b0 + 1:e], "agent_label": fr["agent"], "cooked": False})
            i = j
            continue
        i += 1
    return out


def _ci_ydq(t):
    """YAML double-quoted scalar body: line folding + escapes."""
    t = re.sub(r"[ \t]*\\\r?\n[ \t]*", "", t)
    t = re.sub(r"[ \t]*\r?\n[ \t]*", lambda m: "\n", t)
    t = re.sub(r"\n(\n*)", lambda m: m.group(1) or " ", t)

    def esc(m):
        x = m.group(1)
        if x[0] in "xuU":
            return chr(int(x[1:], 16))
        return _CI_YDQ.get(x, "\\" + x)
    return re.sub(r"\\(x[0-9a-fA-F]{2}|u[0-9a-fA-F]{4}|U[0-9a-fA-F]{8}|.)", esc, t)


def _ci_yscalar(lines, i, rest, base):
    """(value, cooked, next_line) of the YAML value `rest` on lines[i] whose node sits at column `base`."""
    r = rest.strip()
    r = _YAML_PROPS.sub("", r, 1) if r[:1] in "!&" else r
    m = re.match(r"([|>])([1-9]?)([+-]?)([1-9]?)[ \t]*(?:#.*)?$", r)
    if m:
        j, body = i + 1, []
        while j < len(lines) and (not lines[j].strip() or len(lines[j]) - len(lines[j].lstrip(" ")) > base):
            body.append(lines[j])
            j += 1
        while body and not body[-1].strip():
            body.pop()
            j -= 1
        explicit = m.group(2) or m.group(4)
        ind = base + int(explicit) if explicit else min((len(x) - len(x.lstrip(" ")) for x in body if x.strip()),
                                                        default=0)
        txt = [x[ind:] if x.strip() else "" for x in body]
        if m.group(1) == ">":
            folded, prev = "", None
            for ln in txt:
                if prev is None:
                    folded = ln
                elif not ln or ln[:1] in " \t" or not prev or prev[:1] in " \t":
                    folded += "\n" + ln
                else:
                    folded += " " + ln
                prev = ln
            txt = [folded]
        v = "\n".join(txt)
        v = v + ("" if m.group(3) == "-" else "\n") if v else v
        return v, m.group(1) == ">", j
    if r[:1] in ("'", '"'):
        q, buf, j = r[0], r[1:], i
        while True:
            k = 0
            while True:
                k = buf.find(q, k)
                if k < 0:
                    break
                if q == "'" and buf.startswith("''", k):
                    k += 2
                    continue
                if q == '"' and (len(buf[:k]) - len(buf[:k].rstrip("\\"))) % 2:
                    k += 1
                    continue
                break
            if k >= 0 or j + 1 >= len(lines) or j - i > 512:
                break
            j += 1
            buf += "\n" + lines[j]
        if k < 0:
            return None, False, i + 1
        buf = buf[:k]
        if q == "'":
            v = re.sub(r"\n(\n*)", lambda mm: mm.group(1) or " ", re.sub(r"[ \t]*\n[ \t]*", "\n", buf)).replace("''", "'")
            return v, "\n" in buf, j + 1
        return _ci_ydq(buf), "\\" in buf or "\n" in buf, j + 1
    if r[:1] == "[":
        e = r.rfind("]")
        items = [a or b or c for a, b, c in _YAML_FLOW_ITEM.findall(r[1:e if e > 0 else len(r)])]
        return "\n".join(items), False, i + 1
    if not r or r.startswith("#"):
        return None, False, i + 1
    v, j = re.sub(r"[ \t]+#.*$", "", r), i + 1
    while j < len(lines) and lines[j].strip() and len(lines[j]) - len(lines[j].lstrip(" ")) > base and \
            not _CI_YKEY.match(lines[j].strip()) and not lines[j].strip().startswith(("- ", "#")):
        v += " " + lines[j].strip()
        j += 1
    return v, j > i + 1, j


def _ci_yentries(src):
    lines = src.replace("\t", "  ").splitlines()[:20000]
    ents, i = [], 0
    while i < len(lines):
        line = lines[i]
        s = line.strip()
        if not s or s.startswith("#") or s in ("---", "..."):
            i += 1
            continue
        m = _CI_YLINE.match(line)
        col, dcol = m.end(), (len(m.group(1)) if m.group(2) else None)
        km = _CI_YKEY.match(line, col)
        if km:
            key = km.group(1).strip("'\"")
            val, cooked, nxt = _ci_yscalar(lines, i, km.group(2), col)
        elif dcol is not None:
            key = None
            val, cooked, nxt = _ci_yscalar(lines, i, line[col:], dcol)
        else:
            i += 1
            continue
        ents.append({"i": i, "col": col, "dcol": dcol, "key": key, "val": val, "cooked": cooked})
        i = max(nxt, i + 1)
    return ents


def _ci_ymap(ents, x):
    """(head index, {key: entry}) of the mapping holding ents[x]."""
    e, head, sib = ents[x], x, {}
    if e["dcol"] is None:
        for y in range(x - 1, max(-1, x - 400), -1):
            f = ents[y]
            if f["col"] > e["col"]:
                continue
            if f["col"] < e["col"]:
                break
            if f["key"]:
                sib.setdefault(f["key"], y)
            head = y
            if f["dcol"] is not None:
                break
    for y in range(head + 1, min(len(ents), head + 400)):
        f = ents[y]
        if f["col"] > e["col"]:
            continue
        if f["col"] < e["col"] or f["dcol"] is not None:
            break
        if f["key"]:
            sib.setdefault(f["key"], y)
    if ents[head]["key"]:
        sib.setdefault(ents[head]["key"], head)
    sib.setdefault(e["key"], x) if e["key"] else None
    return head, sib


def _ci_ykids(ents, x):
    e, kids = ents[x], []
    for y in range(x + 1, min(len(ents), x + 2000)):
        f = ents[y]
        if f["col"] <= e["col"] and not (f["dcol"] is not None and f["dcol"] >= (e["dcol"] if e["dcol"] is not None
                                                                                  else e["col"]) and
                                          e["key"] and f["col"] > e["col"] - 0):
            break
        kids.append(y)
    if not kids:
        return []
    c0 = min(ents[y]["col"] for y in kids)
    return [y for y in kids if ents[y]["col"] == c0]


def _ci_yparent(ents, head):
    h = ents[head]
    ind = h["dcol"] if h["dcol"] is not None else h["col"]
    for y in range(head - 1, max(-1, head - 4000), -1):
        f = ents[y]
        if f["col"] > ind or (h["dcol"] is not None and f["dcol"] == h["dcol"]) or not f["key"]:
            continue
        if f["col"] < ind or (h["dcol"] is not None and f["col"] <= ind):
            return y
    return None


def _ci_yval(ents, y):
    """Scalar of ents[y], else its block-sequence items / `name|vmImage|image|label` child."""
    v = ents[y]["val"]
    if v is not None:
        return v
    ks = _ci_ykids(ents, y)
    items = [ents[k]["val"] for k in ks if ents[k]["dcol"] is not None and not ents[k]["key"] and ents[k]["val"]]
    if items:
        return ",".join(items)
    for k in ks:
        if ents[k]["key"] in ("vmImage", "name", "image", "label", "labels", "group") and ents[k]["val"]:
            return ents[k]["val"]
    return None


def _ci_yaml(src):
    ents, out, envmap = _ci_yentries(src), [], {}
    for x, e in enumerate(ents):
        if (e["key"] or "").lower() in ("env", "variables") and e["val"] is None:
            for k in _ci_ykids(ents, x):
                if ents[k]["key"] and ents[k]["val"] is not None:
                    envmap.setdefault(ents[k]["key"], ents[k]["val"])

    def expand(m):
        v = envmap.get(m.group(1) or m.group(2))
        return m.group(0) if v is None else v
    for x, e in enumerate(ents):
        kind = _CI_YBODY.get((e["key"] or "").lower())
        if not kind or len(out) >= 128:
            continue
        body, cooked = e["val"], e["cooked"]
        _head, sib = _ci_ymap(ents, x)
        if body is None:
            ks = _ci_ykids(ents, x)
            if ks and ents[ks[0]]["dcol"] is not None and not ents[ks[0]]["key"]:
                vals = [ents[k] for k in ks if not ents[k]["key"] and ents[k]["val"] is not None]
                body = "\n".join(v["val"].rstrip("\n") for v in vals) + "\n" if vals else None
                cooked = any(v["cooked"] for v in vals)
            elif ks:
                sub = {ents[k]["key"]: k for k in ks if ents[k]["key"]}
                k = next((sub[n] for n in ("command", "script", "inlineScript", "inline") if n in sub), None)
                if k is None or ents[k]["val"] is None:
                    continue
                body, cooked = ents[k]["val"], ents[k]["cooked"]
                if "shell" in sub:
                    sib = dict(sib, shell=sub["shell"])
        if not body or not body.strip():
            continue
        if envmap and ("${{" in body or "$(" in body):
            b2 = re.sub(r"\$\{\{\s*(?:env|vars)\.([\w-]+)\s*\}\}|\$\(([\w.]+)\)", expand, body)
            body, cooked = b2, cooked or b2 != body
        chain, path, h, seen = [sib], [], _head, 0
        while h is not None and seen < 16:
            p = _ci_yparent(ents, h)
            if p is None:
                break
            path.append(ents[p]["key"])
            h, s = _ci_ymap(ents, p)
            chain.append(s)
            seen += 1
        get = lambda m, k: _ci_yval(ents, m[k]) if k in m else None  # noqa: E731
        agent = next((get(m, k) for m in chain for k in ("runs-on", "image", "pool", "tags", "agent", "docker",
                                                         "executor", "machine", "container") if get(m, k)), None)
        stage = next((get(m, k) for m in chain[:2] for k in ("name", "displayName", "step", "stage") if get(m, k)), None)
        if stage is None:
            stage = next((k for k in path if k and k.lower() not in (
                "steps", "script", "jobs", "stages", "pipelines", "pipeline", "default", "branches", "with", "inputs",
                "run", "commands", "before_script", "after_script", "workflows", "parallel", "step", "custom",
                "pull-requests", "tags", "defaults")), None)
        win = "windows" in (agent or "").lower() or "win" in re.split(r"[\W_]+", (agent or "").lower())
        shell, uses, task = get(sib, "shell"), get(sib, "uses") or "", ""
        for m in chain:
            if "task" in m:
                task = get(m, "task") or ""
                break
        if shell is None and "run" in path[:1] and "shell" in chain[1:2][0] if len(chain) > 1 else False:
            shell = get(chain[1], "shell")
        if "github-script" in uses or "github-script" in (get(chain[1], "uses") or "" if len(chain) > 1 else ""):
            shell = "github-script"
        elif shell is None and task:
            shell = _CI_TASK.get(re.sub(r"@\d+$", "", task.strip().lower()))
        if shell is None:
            shell = kind if kind in ("bash", "powershell", "pwsh", "cmd") else (
                ("cmd" if kind == "script" and "steps" in path[:1] else "pwsh") if win else "bash")
        out.append({"stage": stage, "step_kind": e["key"], "shell": shell, "lang": _ci_lang(shell), "body": body,
                    "agent_label": agent, "cooked": cooked})
    return out


def pipeline_steps(name, src):
    """CI/build pipeline step bodies: [{stage, step_kind, shell, lang, body, agent_label}] of a Jenkinsfile (Groovy)
    or a GitHub Actions / GitLab / Azure / CircleCI / Bitbucket / Drone YAML. [] when it is none. Never raises."""
    try:
        if isinstance(src, (bytes, bytearray)):
            src = bytes(src).decode("utf-8", "ignore")
        src = (src or "")[:1 << 20].lstrip("\ufeff")
        nm = (name or "").lower()
        groovy = nm.endswith((".groovy", ".jenkinsfile", ".gvy")) or "jenkinsfile" in nm or bool(
            re.search(r"\bpipeline\s*\{|\bnode\s*(?:\(|\{)|\bstage\s*\(\s*['\"]", src[:1 << 16]))
        yaml_ = nm.endswith((".yml", ".yaml")) or bool(re.search(r"(?m)^[ \t]*-?[ \t]*[\w.-]+[ \t]*:[ \t]*(?:[|>][-+]?)?[ \t]*$",
                                                                 src[:1 << 16]))
        steps = (_ci_jenkins(src) if groovy else []) or (_ci_yaml(src) if yaml_ and not groovy else [])
        return [{k: v for k, v in s.items() if k != "cooked"} for s in steps] if steps else []
    except Exception:  # noqa: BLE001
        return []


def _pipeline_steps_raw(src):
    try:
        if re.search(r"\bpipeline\s*\{|\bnode\s*(?:\(|\{)|\bstage\s*\(\s*['\"]", src[:1 << 16]):
            return _ci_jenkins(src)
        return _ci_yaml(src)
    except Exception:  # noqa: BLE001
        return []


def _pipeline_codecs(src, budget=0.5):
    """find_codecs readings of every prior-language pipeline step body: [(codec, cooked)]."""
    out, seen = [], set()
    end = time.time() + budget
    for s in _pipeline_steps_raw(src):
        if time.time() > end:
            break
        if s["lang"] == "groovy" or not _NS_HINT.search(s["body"]):
            continue
        for c in find_codecs(s["body"], 1):
            p = c.get("plain")
            if p and p not in seen:
                seen.add(p)
                out.append((dict(c, id=f"{c.get('id')}@{s['stage'] or ''}/{s['step_kind']}"), s["cooked"]))
    return out


# ------------------------------------------------------------------------------------------------ .NET assembly carriers
# Target dotnet-assembly-strings (escalation of D19 managed-assembly-bridge): a script carries real managed bytes --
# PS `[Reflection.Assembly]::Load([Convert]::FromBase64String('TVqQ..'))`, C# `Assembly.Load(new byte[]{77,90,144,..})`,
# hex `4d5a90..`, gzip `H4sI..` / `31,139,8,..` of an MZ -- and hides the plan in the assembly's metadata: a `#US` user
# string (ldstr literal, compressed-length-prefixed UTF-16LE), a ManifestResource (raw blob or a `.resources` container,
# magic 0xBEEFCACE), or a Costura `costura.*.dll.compressed` (raw deflate of a nested assembly). dotnet_strings() walks
# the BSJB metadata root (pure Python, so a bare metadata blob reads too; dnfile only for the tables of a PE);
# _dotnet_codecs() finds the carriers in a script and peels every user string / resource. Only consulted when nothing
# else produced a plan. Bounded, never raises.

_DN_CARRIER = re.compile(r"(?:TV[pq]QAA|H4sI)[A-Za-z0-9+/]{40,}={0,2}|(?i:4d5a90|1f8b08)[0-9a-fA-F]{80,}"
                         r"|\b(?:77|0x4[dD])\s*,\s*(?:90|0x5[aA])\s*,\s*(?:144|80|0x90|0x50)\s*,[\s\d,xXa-fA-F]{60,}"
                         r"|\b(?:31|0x1[fF])\s*,\s*(?:139|0x8[bB])\s*,\s*(?:8|0x08|0x8)\s*,[\s\d,xXa-fA-F]{60,}")


def _dn_cuint(b, i):
    """ECMA-335 II.23.2 compressed unsigned int at b[i] -> (value, next index)."""
    x = b[i]
    if x < 0x80:
        return x, i + 1
    if x < 0xC0:
        return ((x & 0x3F) << 8) | b[i + 1], i + 2
    return ((x & 0x1F) << 24) | (b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3], i + 4


def _dn_streams(b, root):
    """{name: bytes} of the metadata streams under the BSJB root at b[root]."""
    vlen = int.from_bytes(b[root + 12:root + 16], "little")
    i = root + 16 + vlen
    n = int.from_bytes(b[i + 2:i + 4], "little")
    i += 4
    out = {}
    for _ in range(min(n, 16)):
        off, size = int.from_bytes(b[i:i + 4], "little"), int.from_bytes(b[i + 4:i + 8], "little")
        j = b.index(b"\x00", i + 8, i + 8 + 32)
        name = b[i + 8:j].decode("ascii", "replace")
        i = (j + 4) & ~3
        if root + off + size <= len(b):
            out.setdefault(name, b[root + off:root + off + size])
    return out


def _dn_7bit(b, i):
    v = s = 0
    while s < 35:
        x = b[i]
        i += 1
        v |= (x & 0x7F) << s
        s += 7
        if x < 0x80:
            break
    return v, i


def _dn_resources_container(b):
    """{name: bytes|str} of a System.Resources `.resources` blob (ResourceReader, magic 0xBEEFCACE)."""
    out = {}
    if b[:4] != b"\xce\xca\xef\xbe":
        return out
    i = 12 + int.from_bytes(b[8:12], "little")
    n, ntypes = int.from_bytes(b[i + 4:i + 8], "little"), int.from_bytes(b[i + 8:i + 12], "little")
    i += 12
    types = []
    for _ in range(min(ntypes, 256)):
        ln, i = _dn_7bit(b, i)
        types.append(b[i:i + ln].decode("utf-8", "replace"))
        i += ln
    while i % 8 and b[i:i + 1] in (b"P", b"A", b"D"):     # 'PAD' padding to 8-byte alignment
        i += 1
    n = min(n, 4096)
    i += 8 * n                                              # name hashes + name positions
    data_off = int.from_bytes(b[i:i + 4], "little")
    names_at = i + 4
    for k in range(n):
        pos = int.from_bytes(b[i - 4 * n + 4 * k:i - 4 * n + 4 * k + 4], "little")
        j = names_at + pos
        ln, j = _dn_7bit(b, j)
        name = b[j:j + ln].decode("utf-16-le", "replace")
        d = data_off + int.from_bytes(b[j + ln:j + ln + 4], "little")
        tc, d = _dn_7bit(b, d)
        if tc == 1 or (ntypes and tc >= 0x40 and "String" in (types[tc - 0x40] if tc - 0x40 < len(types) else "")):
            ln2, d = _dn_7bit(b, d)
            out[name] = b[d:d + ln2].decode("utf-8", "replace")
        elif tc in (0x20, 0x21):
            ln2 = int.from_bytes(b[d:d + 4], "little")
            out[name] = b[d + 4:d + 4 + ln2]
    return out


def dotnet_strings(data, _depth=0):
    """Managed metadata of a .NET PE or a bare BSJB metadata blob: {us: [user strings], strings: [#Strings],
    resources: {name: bytes|str}, typedefs: [ns.name], methods: [names]}; None when it is not managed code."""
    import zlib
    try:
        b = bytes(data or b"")
        if b[:2] == b"MZ":
            import pefile
            pe = pefile.PE(data=b, fast_load=True)
            dd = pe.OPTIONAL_HEADER.DATA_DIRECTORY
            if len(dd) <= 14 or not dd[14].VirtualAddress:
                return None
            cli = pe.get_data(dd[14].VirtualAddress, 72)
            md_rva, md_size = int.from_bytes(cli[8:12], "little"), int.from_bytes(cli[12:16], "little")
            res_rva, res_size = int.from_bytes(cli[24:28], "little"), int.from_bytes(cli[28:32], "little")
            md = pe.get_data(md_rva, md_size)
        else:
            pe, res_rva, res_size = None, 0, 0
            i = b.find(b"BSJB")
            md = b[i:] if i >= 0 else b""
        if md[:4] != b"BSJB":
            return None
        st = _dn_streams(md, 0)
        us, h = [], st.get("#US", b"")
        i = 1
        while i < len(h) and len(us) < 20000:
            ln, i = _dn_cuint(h, i)
            if ln > 1:
                us.append(h[i:i + ln - 1].decode("utf-16-le", "replace"))
            i += ln
        strs = [s.decode("utf-8", "replace") for s in st.get("#Strings", b"").split(b"\x00") if s][:20000]
        out = {"us": us, "strings": strs, "resources": {}, "typedefs": [], "methods": []}
        if pe is not None:
            import dnfile
            dn = dnfile.dnPE(data=b)
            t = dn.net.mdtables if dn.net else None
            for r in (getattr(t, "TypeDef", None) or [])[:4096]:
                out["typedefs"].append(".".join(x for x in (str(r.TypeNamespace or ""), str(r.TypeName or "")) if x))
            out["methods"] = [str(m.Name) for m in (getattr(t, "MethodDef", None) or [])[:8192]]
            for r in (getattr(t, "ManifestResource", None) or [])[:256]:
                if r.Implementation and getattr(r.Implementation, "row_index", 0):
                    continue                                     # lives in another file / assembly
                blob = pe.get_data(res_rva + r.Offset, min(res_size, 4))
                ln = int.from_bytes(blob, "little")
                if 0 < ln <= min(res_size, 32 << 20):
                    out["resources"][str(r.Name)] = pe.get_data(res_rva + r.Offset + 4, ln)
            for name, v in list(out["resources"].items()):
                if isinstance(v, bytes) and v[:4] == b"\xce\xca\xef\xbe":
                    try:
                        out["resources"].update({f"{name}/{k}": x for k, x in _dn_resources_container(v).items()})
                    except Exception:  # noqa: BLE001 - malformed container: keep the raw blob
                        pass
                if _depth < 1 and isinstance(v, bytes) and name.lower().startswith("costura.") and \
                        name.lower().endswith(".compressed"):
                    inner = dotnet_strings(zlib.decompressobj(-15).decompress(v, 32 << 20), _depth + 1)
                    if inner:
                        out["us"] += inner["us"]
                        out["resources"].update({f"{name}/{k}": x for k, x in inner["resources"].items()})
        return out
    except Exception:  # noqa: BLE001 - truncated / impostor: not managed code
        return None


def _dn_payload(tok):
    """The managed bytes (MZ / BSJB) behind one carrier token, or None."""
    import zlib
    t = tok.strip()
    try:
        if t[:1].isdigit() and "," in t or t[:2].lower() == "0x":
            b = bytes(int(x, 16 if x[:2].lower() == "0x" else 10) & 0xFF for x in re.split(r"[\s,]+", t) if x)
        elif re.fullmatch(r"[0-9a-fA-F]+", t):
            b = bytes.fromhex(t[:len(t) & ~1])
        else:
            b = base64.b64decode(t + "=" * (-len(t) % 4))
        if b[:2] == b"\x1f\x8b":
            b = zlib.decompressobj(31).decompress(b, 32 << 20)
    except Exception:  # noqa: BLE001
        return None
    return b if b[:2] == b"MZ" or b[:4] == b"BSJB" else None


def _dotnet_codecs(src, raw=None, depth=0, budget=1.0):
    """Plans hidden in .NET assemblies a script carries (see dotnet_strings)."""
    out = []
    try:
        end = time.time() + budget
        blobs = [raw] if raw and raw[:2] == b"MZ" else []
        blobs += [p for p in (_dn_payload(m.group(0)) for m in _DN_CARRIER.finditer((src or "")[:8 << 20]))
                  if p][:8]
        for k, b in enumerate(blobs):
            info = dotnet_strings(b)
            if not info:
                continue
            texts = [("us", s) for s in info["us"]]
            for name, v in info["resources"].items():
                if isinstance(v, bytes):
                    u = _utf16(v) if v[:2] in (b"\xff\xfe", b"\xfe\xff") else None
                    v = (u or v).decode("utf-8", "ignore")
                texts.append((f"res:{name}", v))
            for name, text in texts:
                if time.time() > end:
                    break
                plain = peel_plan(text, budget=min(0.15, max(0.02, end - time.time()))) if len(text) >= 8 else None
                if plain:
                    return [{"id": f"dotnet@{name}", "rep": "dotnet_assembly", "transform": "identity", "key": "",
                             "material": text, "plain": plain}]
            joined = "\n".join(t for _, t in texts)
            if depth < 1 and joined.strip() and time.time() < end:
                for c in find_codecs(joined, depth + 1):
                    if c.get("plain"):
                        return [dict(c, id=f"{c.get('id')}@dotnet")]
    except Exception:  # noqa: BLE001
        return out
    return out


# ------------------------------------------------------------------------------------------------ managed bridge hosts
# Target managed-bridge-hosts (sibling of the D19 `aspx_inline_csharp` host, the D14 MSBuild inline task and the D8
# php_webshell): a .NET-hosted script surface carries its C# / VB / JScript as an inner text -- PS `Add-Type
# -TypeDefinition @"..."@` / `-MemberDefinition` / `CompileAssemblyFromSource(` / `[ScriptBlock]::Create(`, `.ashx` /
# `.asmx` `<%@ WebHandler|WebService Language="C#" Class=..%>` + code, Razor `.cshtml` `@{ .. }` / `@functions { .. }`,
# classic ASP `<%@ Language=VBScript %>` `<% .. %>` / `<script language="JScript" runat="server">`, InstallUtil
# `[RunInstaller(true)]` / RegAsm-RegSvcs `[ComRegisterFunction]` sources, Workflow Compiler XOML `<x:Code><![CDATA[..]]>`,
# and `csc.exe` fed by a batch `echo .. >> x.cs` file (carets / `%%` unescaped, the file rebuilt line by line).
# managed_host() names the host profile (`<container>_<inline>_<lang>`, the D19 spelling) and returns the inner texts;
# _managed_host_codecs() reads them through find_codecs. Only consulted when nothing else produced a plan.

_MH_LANG = (("csharp", r"c#|cs|csharp|c\s*sharp"), ("vbnet", r"vb|vb\.?net|visualbasic"), ("jscript", r"jscript|js|javascript"),
            ("vbscript", r"vbscript|vbs"), ("perlscript", r"perlscript"))
_MH_CUE = re.compile(r"""(?is)<%|@(?:functions|code)\s*\{|(?m:^[ \t]*@\{)|@(?:model|page)\b|\bAdd-Type\b|CompileAssemblyFromSource|\[ScriptBlock\]::Create|"""
                     r"""\[(?:System\.ComponentModel\.)?RunInstaller|\[(?:System\.Runtime\.InteropServices\.)?ComRegisterFunction|"""
                     r"""\bServicedComponent\b|x:Code\b|\b(?:csc|vbc|jsc)(?:\.exe)?\b|runat\s*=\s*["']?server|<jsp:(?:declaration|scriptlet|expression)\b""")
# JSP (target jvm-script-host-route): `<%@ page language="java" import=.. %>` / `pageEncoding=` / JSPX `<jsp:..>` elements
_MH_JSP = re.compile(r"""(?is)<%@\s*page\b[^%]*?\b(?:language\s*=\s*["']?java\b|import\s*=|pageEncoding\s*=)|"""
                     r"""<%@\s*(?:taglib|tag|include)\b|<jsp:(?:root|declaration|scriptlet|expression|directive)\b""")
_MH_DIRECTIVE = re.compile(r"""(?is)<%@\s*(Page|WebHandler|WebService|Control|Master|Application|Language)\b([^%]*)%>""")
_MH_ATTR_LANG = re.compile(r"""(?i)\bLanguage\s*=\s*["']?([\w#.\s]+?)["'\s%>]""")


_MH_FOLD = re.compile(r'(?<=[^"\s])"[ \t]*[&+][ \t]*(?:_[ \t]*)?(?:\r?\n[ \t]*)?"(?=[^"\s])')


def _mh_lang(s, default=None):
    v = (s or "").strip().lower()
    for name, rx in _MH_LANG:
        if re.fullmatch(rx, v):
            return name
    return default


def _mh_balanced(s, i):
    """Body of the `{ .. }` opening at s[i] (string / char / comment aware enough for C#), or None."""
    depth, j, n = 0, i, min(len(s), i + (1 << 20))
    while j < n:
        c = s[j]
        if c == '"' or c == "'":
            k = j + 1
            while k < n and s[k] != c and s[k] != "\n":
                k += 2 if s[k] == "\\" else 1
            j = k
        elif s.startswith("//", j):
            k = s.find("\n", j)
            j = n if k < 0 else k
        elif c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return s[i + 1:j]
        j += 1
    return None


def _mh_ps_arg(s, i, end=None):
    """PowerShell argument at s[i:]: a here-string / quoted literal (unescaped) or `$var` (its last literal value)."""
    m = re.compile(r"""\s*(@"\r?\n(.*?)\r?\n[ \t]*"@|@'\r?\n(.*?)\r?\n[ \t]*'@|"((?:[^"`]|`.|"")*)"|'((?:[^']|'')*)'|"""
                   r"""\$\{?([\w:]+)\}?)""", re.S).match(s, i)
    if not m:
        return None
    if m.group(2) is not None:
        return _ns_psesc(m.group(2).replace('""', '\0')).replace("\0", '""')
    if m.group(3) is not None:
        return m.group(3)
    if m.group(4) is not None:
        return _ns_psesc(m.group(4))
    if m.group(5) is not None:
        return m.group(5).replace("''", "'")
    var = re.escape(m.group(6).split(":")[-1])
    last = None
    for a in re.finditer(r"(?im)\$(?:\w+:)?" + var + r"\s*=\s*", s[:m.start()]):
        last = a.end()
    return _mh_ps_arg(s, last) if last is not None and last != i else None


def _mh_batch_files(s):
    """{target file: text} rebuilt from batch `echo .. >> f` / `>>f echo ..` / `(echo ..) > f` lines."""
    files = {}
    def unb(t):
        t = re.sub(r"\^(.)", r"\1", t.replace("%%", "\0")).replace("\0", "%")
        return t[:-1] if t.endswith(" ") else t
    lines = s.replace("\r\n", "\n").split("\n")
    k = 0
    while k < len(lines) and k < 20000:
        ln = lines[k].strip()
        k += 1
        m = re.match(r"(?i)^@?\(\s*$", ln)
        if m:                                           # ( echo a & echo b ...\n ) > file
            body = []
            while k < len(lines) and not re.match(r"^\s*\)", lines[k]):
                body.append(lines[k].strip())
                k += 1
            tail = lines[k] if k < len(lines) else ""
            k += 1
            t = re.match(r"""^\s*\)\s*(>>?)\s*"?([^"\s]+)""", tail)
            if t:
                for b in body:
                    e = re.match(r"(?i)^@?echo(?:[ .(:;,=]|$)(.*)", b)
                    if e:
                        files.setdefault(t.group(2).lower(), []).append(unb(e.group(1)))
            continue
        m = (re.match(r"""(?i)^@?echo[ .(:;,=](.*?)\s*(?<!\^)(>>?)\s*"?([^"\s>]+)"?\s*$""", ln) or
             re.match(r"""(?i)^(>>?)\s*"?([^"\s]+)"?\s+@?echo[ .(:;,=](.*)$""", ln))
        if not m:
            continue
        if m.group(1) in (">", ">>"):
            op, fn, txt = m.group(1), m.group(2), m.group(3)
        else:
            txt, op, fn = m.group(1), m.group(2), m.group(3)
        fn = fn.lower()
        if op == ">" or fn not in files:
            files[fn] = []
        files[fn].append(unb(txt))
    return {fn: "\n".join(v) for fn, v in files.items()}


def managed_host(name, src):
    """Classify a .NET-hosted script surface and extract its inner code. `src` = text or bytes, `name` its file name.
    -> {"profile_guess": `<container>_<inline>_<lang>` or None, "lang": inner language or None,
        "inner_texts": [(where, text)]}. Not a managed host -> profile_guess None, inner_texts []. Never raises."""
    out = {"profile_guess": None, "lang": None, "inner_texts": []}
    try:
        if isinstance(src, (bytes, bytearray)):
            src = bytes(src).decode("utf-8", "ignore")
        s = (src or "")[:1 << 21].lstrip("﻿")
        ext = (name or "").rsplit(".", 1)[-1].lower() if "." in (name or "") else ""
        if not _MH_CUE.search(s):
            return out
        texts, prof, lang = [], None, None
        d = _MH_DIRECTIVE.search(s[:1 << 16])
        # 0. JSP pages: <%! declarations %> / <% scriptlets %> / <%= expressions %> (+ JSPX elements), Java inside
        if ext in ("jsp", "jspx", "jspf") or _MH_JSP.search(s[:1 << 16]):
            import html
            for bm in re.finditer(r"(?s)<%(?![@-])[!=]?(.*?)%>", s):
                if bm.group(1).strip():
                    texts.append(("jsp_" + {"!": "declaration", "=": "expression"}.get(s[bm.start() + 2], "scriptlet"),
                                  bm.group(1)))
            for xm in re.finditer(r"(?is)<jsp:(declaration|scriptlet|expression)\b[^>]*>(.*?)</jsp:\1\s*>", s):
                cd = re.findall(r"(?s)<!\[CDATA\[(.*?)\]\]>", xm.group(2))
                texts.append(("jspx_" + xm.group(1).lower(), "\n".join(cd) if cd else html.unescape(xm.group(2))))
            if texts:
                out.update(profile_guess="jsp_scriptlet", lang="java",
                           inner_texts=[(w, t) for w, t in texts if t and t.strip()][:64])
                return out
        # 1. ASP.NET / classic ASP pages: directive + <script runat=server> + <% %> blocks
        if d or ext in ("aspx", "ashx", "asmx", "ascx", "master", "asax", "asp", "asa"):
            kind = (d.group(1).lower() if d else "")
            la = _MH_ATTR_LANG.search(d.group(0) + " ") if d else None
            lang = _mh_lang(la.group(1) if la else "", None)
            for sm in re.finditer(r"""(?is)<script\b([^>]*\brunat\s*=\s*["']?server[^>]*)>(.*?)</script\s*>""", s):
                sl = _MH_ATTR_LANG.search(sm.group(1) + " ")
                lang = lang or _mh_lang(sl.group(1) if sl else "", None)
                texts.append(("script_runat", sm.group(2)))
            for bm in re.finditer(r"(?s)<%(?![@-])=?(.*?)%>", s):
                if bm.group(1).strip():
                    texts.append(("asp_block", bm.group(1)))
            if d and kind in ("webhandler", "webservice"):
                texts.append((kind, s[d.end():]))
            classic = kind == "language" or ext in ("asp", "asa") or (
                not d and not re.search(r"(?i)\bpage\b|\.aspx", s[:4096]))
            if classic:
                lang = lang or "vbscript"
                prof = f"asp_inline_{'jscript' if lang in ('jscript', 'csharp') else lang}"
            else:
                cont = {"webhandler": "ashx", "webservice": "asmx", "control": "ascx", "master": "master",
                        "application": "asax"}.get(kind, ext if ext in ("ashx", "asmx", "ascx") else "aspx")
                lang = lang or "csharp"
                prof = f"{cont}_inline_{lang}"
        # 2. Razor
        elif ext in ("cshtml", "vbhtml", "razor") or re.search(r"(?m)^\s*@(?:functions|code)\s*\{|^\s*@\{|@model\b|@page\b", s):
            for m in re.finditer(r"@(?:functions|code)?\s*\{", s):
                b = _mh_balanced(s, m.end() - 1)
                if b and b.strip():
                    texts.append(("razor_block", b.replace("@@", "@")))
            if texts:
                lang = "vbnet" if ext == "vbhtml" else "csharp"
                prof = f"{'razor' if ext == 'razor' else 'cshtml'}_inline_{lang}"
        # 3. Workflow Compiler XOML
        if not prof and (ext == "xoml" or re.search(r"(?i)<x:Code\b|\.xoml\b|Microsoft\.Workflow\.Compiler", s)):
            import html
            for m in re.finditer(r"(?is)<x:Code\b[^>]*>(.*?)</x:Code\s*>", s):
                b = m.group(1)
                cd = re.findall(r"(?s)<!\[CDATA\[(.*?)\]\]>", b)
                texts.append(("xoml_code", "\n".join(cd) if cd else html.unescape(b)))
            if texts:
                lang = "vbnet" if re.search(r"(?i)\bVisualBasic\b|Language\s*=\s*\"?VB", s[:1 << 14]) else "csharp"
                prof = f"xoml_inline_{lang}"
        # 4. PowerShell compile bridges
        if not prof and re.search(r"(?i)\bAdd-Type\b|CompileAssemblyFromSource|\[ScriptBlock\]::Create", s):
            for m in re.finditer(r"(?i)-(TypeDefinition|MemberDefinition)\b\s*:?|CompileAssemblyFromSource\s*\([^,]*,"
                                 r"|\[ScriptBlock\]::Create\s*\(|(?:(?<=Add-Type)|(?<=Add-Type\s))\s+(?=[@\"'$])", s):
                v = _mh_ps_arg(s, m.end())
                if v and len(v.strip()) >= 8:
                    kind = (m.group(1) or "").lower() or ("scriptblock" if "Create" in m.group(0) else "source")
                    texts.append((kind, v))
            if texts:
                la = re.search(r"(?i)-Language\s+['\"]?(\w+)", s)
                lang = _mh_lang(la.group(1) if la else "", "csharp")
                if all(k == "scriptblock" for k, _ in texts):
                    lang = "powershell"
                hit = re.search(r"(?i)CompileAssemblyFromSource|\[ScriptBlock\]::Create|-MemberDefinition", s)
                via = {"compileassemblyfromsource": "codedom", "[scriptblock]::create": "scriptblock",
                       "-memberdefinition": "member"}.get(re.sub(r"\s", "", hit.group(0)).lower() if hit else "", "add_type")
                prof = f"powershell_{via}_{lang}"
        # 5. csc / vbc / jsc fed from a batch echo-redirected source file
        if not prof and re.search(r"(?i)\b(?:csc|vbc|jsc)(?:\.exe)?\b", s) and re.search(r"(?im)^\s*@?\(?\s*echo\b|>>?\s*\S+\s+echo\b", s):
            files = _mh_batch_files(s)
            for fn, t in files.items():
                if fn.endswith((".cs", ".vb", ".js", ".tmp", ".txt")) or re.search(r"(?i)\b(?:class|using|Imports)\b", t):
                    texts.append((fn, t))
            if texts:
                comp = re.search(r"(?i)\b(csc|vbc|jsc)(?:\.exe)?\b", s).group(1).lower()
                lang = {"csc": "csharp", "vbc": "vbnet", "jsc": "jscript"}[comp]
                prof = f"batch_{comp}_{lang}"
        # 6. InstallUtil / RegAsm / RegSvcs bypass sources (the source is the inner text)
        if not prof:
            for rx, p in ((r"\[\s*(?:System\.ComponentModel\.)?RunInstaller\s*\(\s*true\s*\)", "installutil_installer"),
                          (r"\[\s*(?:System\.Runtime\.InteropServices\.)?ComRegisterFunction", "regasm_comregister"),
                          (r":\s*(?:System\.EnterpriseServices\.)?ServicedComponent\b", "regsvcs_serviced")):
                if re.search(rx, s):
                    lang = "vbnet" if re.search(r"(?im)^\s*Imports\s+System|<RunInstaller\(True\)>", s) else "csharp"
                    prof = f"{p}_{lang}"
                    texts.append((p.split("_")[0], s))
                    break
        out.update(profile_guess=prof, lang=lang if prof else None,
                   inner_texts=[(w, t) for w, t in texts if t and t.strip()][:64])
    except Exception:  # noqa: BLE001 - impostor / truncated: nothing
        return {"profile_guess": None, "lang": None, "inner_texts": []}
    return out


def _managed_host_codecs(src, raw=None, depth=0, name="", budget=0.6):
    """find_codecs readings of a managed host's inner texts (first plan wins; tagged `@managed:<profile>:<where>`)."""
    try:
        end = time.time() + budget
        host = managed_host(name, raw if raw is not None else src)
        for where, text in host["inner_texts"]:
            if time.time() > end:
                break
            if text == src:
                continue
            folded = _MH_FOLD.sub("", text)        # `"a" & _ / "a" +` continued literals: one literal
            for c in (find_codecs(folded, depth + 1) if folded != text else []) + find_codecs(text, depth + 1):
                if c.get("plain"):
                    return [dict(c, id=f"{c.get('id')}@managed:{host['profile_guess']}:{where}")]
    except Exception:  # noqa: BLE001
        return []
    return []


# ------------------------------------------------------------------------------------------------ prior-language hosts
# Target prior-language-host-battery (sibling of the D20 `host-classic-asp-vbscript.vbs`, the first host for an OLD
# language): a host file wraps a D1-D20 language -- classic ASP (`<%@ Language=VBScript|JScript %>` / `<script
# language=.. runat=server>`), Windows Script Component `.wsc` (`<component><registration progid=..><script
# language=..><![CDATA[..]]>`), Jupyter `.ipynb` (JSON-escaped Python cell sources), systemd `ExecStart=/bin/bash -c '..'`
# (`%%` escape), crontab `* * * * * bash -c ".."`, `.desktop` `Exec=sh -c`, Electron `preload.js` (contextBridge),
# Nmap NSE (`description = [[..]]`), Redis `EVAL ".."`, Task Scheduler XML `<Exec><Command>..<Arguments>`, GPO
# `scripts.ini` / `psscripts.ini` `NCmdLine=` / `NParameters=`. prior_host() names the container (the D20 spelling
# `classic_asp`, ...) and returns the inner texts; _prior_host_codecs() reads them through find_codecs. Consulted only
# when nothing else produced a plan, or (WSC / ASP `"a" & _` continuation) when a plan-shaped piece reads lossy.

_PH_CUE = re.compile(r"""(?ism)<%|runat\s*=\s*["']?server|<component\b|<scriptlet\b|"nbformat"\s*:|"cell_type"\s*:|"""
                     r"""^[ \t]*Exec(?:Start(?:Pre|Post)?|Stop(?:Post)?|Reload|Condition)?[ \t]*=|^[ \t]*\[(?:Service|Unit|"""
                     r"""Desktop Entry|Startup|Shutdown|Logon|Logoff)\]|^[ \t]*(?:@(?:reboot|hourly|daily|weekly|monthly|"""
                     r"""yearly|annually|midnight)|(?:[\d*/,-]+[ \t]+){4}[\d*/,a-z-]+)[ \t]+\S|contextBridge|ipcRenderer|"""
                     r"""\brequire\s*\(\s*['"]electron['"]|^[ \t]*description[ \t]*=[ \t]*\[=*\[|\bportrule\b|"""
                     r"""^[ \t]*EVAL(?:SHA)?[ \t]|<Task\b[^>]*task|<Exec>|^[ \t]*\d+(?:CmdLine|Parameters)[ \t]*=""")
_PH_CRON = re.compile(r"(?m)^[ \t]*(?:@(?:reboot|hourly|daily|weekly|monthly|yearly|annually|midnight)|"
                      r"(?:[\d*/,-]+[ \t]+){4}[\d*/,a-zA-Z-]+)[ \t]+(?:(?!bash|sh\b|/)[a-z_][\w-]*[ \t]+(?=\S))?(?P<cmd>\S.*)$")
_PH_SHC = re.compile(r"""(?:^|[\s;&|(])(?:/(?:usr/)?bin/)?(?:env[ \t]+)?(?:ba|z|da|k)?sh[ \t]+(?:-\w+[ \t]+)*-\w*c[ \t]+""")


def _ph_shell_word(s, i):
    """The shell word at s[i:] ('..' / ".." with backslash escapes / bare), unquoted; None if absent."""
    m = re.compile(r"""\s*(?:'([^']*)'|"((?:[^"\\]|\\.)*)"|((?:[^\s"'\\]|\\.)+))""", re.S).match(s, i)
    if not m:
        return None
    if m.group(1) is not None:
        return m.group(1)
    if m.group(2) is not None:
        return re.sub(r'\\([$`"\\\n])', r"\1", m.group(2))
    return re.sub(r"\\(.)", r"\1", m.group(3))


def _ph_shell_bodies(cmd):
    """[cmd] + the `sh|bash -c '<body>'` bodies of a host command line (unquoted)."""
    out = [cmd]
    for m in _PH_SHC.finditer(cmd):
        b = _ph_shell_word(cmd, m.end())
        if b and b.strip():
            out.append(b)
    return out


def prior_host(name, src):
    """Classify a host file wrapping an older script language and extract its inner code. `src` = text or bytes.
    -> {"profile_guess": container name (`classic_asp`, `wsc_component`, `jupyter_notebook`, `systemd_unit`,
        `cron_entry`, `desktop_entry`, `electron_preload`, `nmap_nse`, `redis_eval`, `scheduled_task_xml`,
        `gpo_scripts_ini`) or None, "lang": inner language or None, "profile_lang": `<container>_<lang>` or None,
        "inner_texts": [(where, text)]}. Not such a host -> profile_guess None, inner_texts []. Never raises."""
    out = {"profile_guess": None, "lang": None, "profile_lang": None, "inner_texts": []}
    try:
        if isinstance(src, (bytes, bytearray)):
            b = bytes(src)[:1 << 22]
            u = _utf16(b) if (b[:2] in (b"\xff\xfe", b"\xfe\xff") or b[1:64:2].count(0) > 20) else None
            src = (u or b).decode("utf-8", "ignore")
        s = (src or "")[:1 << 21].lstrip("﻿")
        ext = (name or "").rsplit(".", 1)[-1].lower() if "." in (name or "") else ""
        if not _PH_CUE.search(s[:1 << 20]):
            return out
        import html
        import json
        texts, prof, lang = [], None, None
        head = s[:1 << 16]
        # 1. Windows Script Component / scriptlet: <script language=..> bodies (CDATA or XML-escaped)
        if ext in ("wsc", "sct") or re.search(r"(?is)<component\b.*?<(?:registration|public|script)\b|<scriptlet\b", head):
            for m in re.finditer(r"(?is)<script\b([^>]*)>(.*?)</script\s*>", s):
                la = re.search(r"""(?i)\blanguage\s*=\s*["']?([\w.]+)""", m.group(1))
                lang = lang or _mh_lang(la.group(1) if la else "", None)
                cd = re.findall(r"(?s)<!\[CDATA\[(.*?)\]\]>", m.group(2))
                texts.append(("wsc_script", "\n".join(cd) if cd else html.unescape(m.group(2))))
            prof = "wsc_component" if texts else None
            lang = lang or ("jscript" if prof else None)
        # 2. Jupyter notebook: cell sources (list of lines or one string), code cells joined as well
        if not prof and (ext == "ipynb" or re.search(r'"nbformat"\s*:|"cell_type"\s*:', head)):
            nb = json.loads(s)
            cells = nb.get("cells") or [c for w in nb.get("worksheets") or [] for c in w.get("cells") or []]
            code = []
            for c in cells[:4096]:
                src_ = c.get("source", c.get("input", ""))
                t = "".join(src_) if isinstance(src_, list) else str(src_ or "")
                if t.strip():
                    texts.append(("ipynb_" + str(c.get("cell_type") or "cell"), t))
                    if c.get("cell_type") == "code":
                        code.append(t)
            if len(code) > 1:
                texts.append(("ipynb_code", "\n".join(code)))
            md = nb.get("metadata") or {}
            lang = str((md.get("language_info") or {}).get("name") or (md.get("kernelspec") or {}).get("language")
                       or "python").lower()
            prof = "jupyter_notebook"
        # 3. classic ASP (not ASP.NET): reuse the managed-host page reader
        if not prof and (ext in ("asp", "asa") or re.search(r"(?is)<%@\s*Language\s*=|<script\b[^>]*runat\s*=", head)):
            mh = managed_host(name, s)
            if (mh["profile_guess"] or "").startswith("asp_inline_"):
                texts, lang, prof = list(mh["inner_texts"]), mh["lang"], "classic_asp"
        # 4. Task Scheduler XML: <Exec><Command>..</Command><Arguments>..</Arguments>
        if not prof and re.search(r"(?is)<Task\b[^>]*windows/2004/02/mit/task|<Actions\b.*?<Exec>", head):
            for m in re.finditer(r"(?is)<Exec>(.*?)</Exec\s*>", s):
                cm = re.search(r"(?is)<Command>(.*?)</Command\s*>", m.group(1))
                am = re.search(r"(?is)<Arguments>(.*?)</Arguments\s*>", m.group(1))
                cmd = html.unescape(((cm.group(1) if cm else "") + " " + (am.group(1) if am else "")).strip())
                texts.extend(("task_exec", t) for t in _ph_shell_bodies(cmd))
                lang = lang or (re.sub(r"(?i)\.exe$", "", re.split(r"[\\/]", cm.group(1).strip())[-1]).lower()
                                if cm and cm.group(1).strip() else None)
            prof = "scheduled_task_xml" if texts else None
        # 5. GPO scripts.ini / psscripts.ini: NCmdLine= + NParameters=
        if not prof and re.search(r"(?im)^[ \t]*\d+(?:CmdLine|Parameters)[ \t]*=", s):
            kv = {}
            for m in re.finditer(r"(?im)^[ \t]*(\d+)(CmdLine|Parameters)[ \t]*=[ \t]*(.*?)[ \t]*\r?$", s):
                kv.setdefault(m.group(1), {})[m.group(2).lower()] = m.group(3)
            for k, v in kv.items():
                cmd = (v.get("cmdline", "") + " " + v.get("parameters", "")).strip()
                texts.extend(("gpo_script", t) for t in _ph_shell_bodies(cmd))
            ps = ext == "ini" and re.search(r"(?i)psscripts|powershell|pwsh|\.ps1", s)
            lang = "powershell" if ps else "batch"
            prof = "gpo_scripts_ini" if texts else None
        # 6. systemd unit / .desktop entry: Exec*= values (systemd `%%` / `-@:+!` prefixes)
        if not prof and re.search(r"(?im)^[ \t]*\[(?:Service|Unit|Timer|Socket|Desktop Entry)\][ \t]*\r?$", head):
            desk = bool(re.search(r"(?im)^[ \t]*\[Desktop Entry\]", head)) or ext == "desktop"
            for m in re.finditer(r"(?im)^[ \t]*(Exec\w*)[ \t]*=[ \t]*[-@:+!]*(.*?)[ \t]*\r?$", s):
                cmd = m.group(2).replace("%%", "%")
                texts.extend((m.group(1).lower(), t) for t in _ph_shell_bodies(cmd))
            prof = ("desktop_entry" if desk else "systemd_unit") if texts else None
        # 7. crontab lines
        if not prof and (ext in ("cron", "crontab") or re.search(r"(?m)^[ \t]*(?:@reboot|(?:[\d*/,-]+[ \t]+){5}\S)", s)):
            for m in _PH_CRON.finditer(s):
                texts.extend(("cron_cmd", t) for t in _ph_shell_bodies(m.group("cmd").replace("\\%", "%")))
            prof = "cron_entry" if texts else None
        # 8. Redis EVAL "<lua>" numkeys ..
        if not prof and re.search(r"(?im)^[ \t]*EVAL(?:_RO)?[ \t]", s):
            for m in re.finditer(r"(?im)^[ \t]*EVAL(?:_RO)?[ \t]+", s):
                b = _ph_shell_word(s, m.end())
                if b and b.strip():
                    texts.append(("redis_eval", b))
            prof, lang = ("redis_eval", "lua") if texts else (None, None)
        # 9. Nmap NSE / Electron preload: the file itself is the inner language
        if not prof and (ext == "nse" or re.search(r"(?m)^[ \t]*description[ \t]*=[ \t]*\[=*\[", head)
                         and re.search(r"\b(?:portrule|hostrule|prerule|postrule|action)[ \t]*=", s)):
            prof, lang = "nmap_nse", "lua"
            texts.append(("nse", s))
        if not prof and re.search(r"""contextBridge|ipcRenderer|\brequire\s*\(\s*['"]electron['"]""", head):
            prof, lang = ("electron_preload" if re.search(r"contextBridge|preload", head) or "preload" in (name or "")
                          else "electron_main"), "node"
            texts.append(("electron", s))
        if prof:
            if lang in (None, "sh", "bash") and prof in ("systemd_unit", "cron_entry", "desktop_entry"):
                lang = "sh" if prof == "desktop_entry" else "bash"
            out.update(profile_guess=prof, lang=lang, profile_lang=f"{prof}_{lang}" if lang else prof,
                       inner_texts=[(w, t) for w, t in texts if t and t.strip()][:64])
    except Exception:  # noqa: BLE001 - impostor / truncated: nothing
        return {"profile_guess": None, "lang": None, "profile_lang": None, "inner_texts": []}
    return out


def _prior_host_codecs(src, raw=None, depth=0, name="", budget=0.6):
    """find_codecs readings of a prior-language host's inner texts (first plan wins; `@host:<profile>:<where>`)."""
    try:
        end = time.time() + budget
        host = prior_host(name, raw if raw is not None else src)
        for where, text in host["inner_texts"]:
            if time.time() > end:
                break
            if text == src:
                continue
            folded = _MH_FOLD.sub("", text)        # `"a" & _ / "a" +` continued literals: one literal
            for c in (find_codecs(folded, depth + 1) if folded != text else []) + find_codecs(text, depth + 1):
                if c.get("plain"):
                    return [dict(c, id=f"{c.get('id')}@host:{host['profile_guess']}:{where}")]
    except Exception:  # noqa: BLE001
        return []
    return []


# ------------------------------------------------------------------------------------------------ .NET literal folding
# C# / VB.NET / F# descriptors assembled at runtime instead of written as one literal (target csharp-literal-fold):
# `string.Concat(..)`, `string.Join("", new[] {..})`, `new string(new char[] {'v','=',..})`, `(char)0x76`,
# `Encoding.UTF8.GetString(new byte[] {..})`, `Convert.FromBase64String` / `FromHexString`, `BitConverter.ToString`,
# `new StringBuilder().Append(..)` chains, `$"{a}{b}"` over const locals, `.Reverse()` / `Array.Reverse`,
# `ToCharArray()` + `^ key` loops / `.Select(c => ..)` with literal keys, `v`, verbatim / raw strings; VB
# `ChrW(118) & ..`, `StrReverse`, `For i = .. To ..`; F# `String.concat "" [..]`, `char 118`, `[| 'v'; .. |]`.
# A bounded tokenizer + Pratt evaluator over literals and const locals (no compiler); anything it cannot fold is skipped.

class _CsCh(int):
    """A C# `char` (int arithmetic, string concatenation as its character)."""


class _CsSB:
    def __init__(self, s=""):
        self.s = s


class _CsFn:
    def __init__(self, params, start, ev):
        self.params, self.start, self.ev = params, start, ev

    def __call__(self, *args):
        return self.ev.apply(self, args)


class _CsStop(Exception):
    pass


_CS_CUE = re.compile(r"""string\.Concat|String\.Join|string\.Join|new\s+string\s*\(|\(char\)|\bGetString\s*\(|FromBase64String|"""
                     r"""FromHexString|BitConverter\.|StringBuilder|\$@?"|@\$"|\.Reverse\s*\(|ToCharArray|\bChrW?\s*\(|"""
                     r"""String\.concat|\\u00[2-7][0-9a-fA-F]|\bchar\s+\d|\[\|\s*'|"{3}|StrReverse|\bNew\s+String\("""
                     r"""|\bnew\s+String\s*\(|\.append\s*\(|\bget(?:Mime|Url)?Decoder\s*\(|\bString\.(?:join|valueOf)\s*\(|parseHex\s*\(""")
_CS_DESC_NAME = re.compile(r"descriptor", re.I)
# BeanShell / loose Java (target kotlin-beanshell-literal-route): `.bsh` scripts with untyped `x = "..";` binders,
# `new StringBuffer(x).reverse()`, `.replace(..)`, `source("..")` / `exec("..")`, and Java `\\uXXXX` escapes that javac /
# bsh translate BEFORE lexing (`\\u0022` is a quote) -- unescaped, then rescanned by the same folder.
_BSH_CUE = re.compile(r"""(?m)\bStringBuffer\b|\.reverse\s*\(\s*\)|\.replace\s*\(|\.substring\s*\(|\.concat\s*\(|"""
                      r"""^[ \t]*(?:source|exec|eval)\s*\(|^[ \t]*[A-Za-z_]\w*[ \t]*\+=[ \t]*["\w]|(?<!\\)(?:\\\\)*\\u+00(?:22|27|2[bB]|3[bBdD]|28|29)""")
_JV_UESC = re.compile(r"(?<!\\)((?:\\\\)*)\\u+([0-9a-fA-F]{4})")


def _jv_unicode_pre(src):
    """Java / BeanShell lexical translation: `\\uXXXX` (odd backslash run, 1+ `u`) -> the char, before lexing."""
    if "\\u" not in src:
        return src
    return _JV_UESC.sub(lambda m: m.group(1) + chr(int(m.group(2), 16)), src)


_CS_ESC = {"n": "\n", "r": "\r", "t": "\t", "0": "\0", "a": "\a", "b": "\b", "f": "\f", "v": "\v", "e": "\x1b",
           "\\": "\\", "'": "'", '"': '"'}
_CS_TOK = re.compile(r"""(?P<ws>\s+)|(?P<cm>//[^\n]*|/\*.*?\*/|\(\*.*?\*\))|"""
                     r"""(?P<raw>\$*"{3,})|(?P<vs>\$?@\$?"(?:[^"]|"")*")|(?P<is>\$"(?:[^"\\\n]|\\.)*")|"""
                     r"""(?P<s>"(?:[^"\\\n]|\\.)*"[cB]?)|(?P<ch>'(?:\\(?:u[0-9a-fA-F]{4}|x[0-9a-fA-F]{1,4}|U[0-9a-fA-F]{8}|\d{3}|.)|[^'\\\n])')|"""
                     r"""(?P<hx>0[xX][0-9a-fA-F_]+|&[hH][0-9a-fA-F]+|0[bB][01_]+)[uUlLyYsSnN%&]*|(?P<num>\d[\d_]*)(?:[uUlLyYsSnN%]{1,2}\b)?|"""
                     r"""(?P<id>@?[A-Za-z_]\w*)|"""
                     r"""(?P<p>\^\^\^|&&&|\|\|\||<<<|>>>|=>|->|<-|==|!=|<=|>=|&&|\|\||\^=|\+=|-=|&=|\|=|\+\+|--|::|\[\||\|\]|\.\.|\|>|\?\?|\S)""",
                     re.S)
_CS_VB_STR = re.compile(r'"((?:[^"]|"")*)"(c\b)?', re.I)


def _cs_unesc(body):
    out, i = [], 0
    while i < len(body):
        c = body[i]
        if c != "\\" or i + 1 >= len(body):
            out.append(c)
            i += 1
            continue
        n = body[i + 1]
        m = re.match(r"u([0-9a-fA-F]{4})|U([0-9a-fA-F]{8})|x([0-9a-fA-F]{1,4})|(\d{3})", body[i + 1:i + 10])
        if m and n in "uUx":
            out.append(chr(int(m.group(1) or m.group(2) or m.group(3), 16) % 0x110000))
            i += 1 + m.end()
        elif m and m.group(4) and not m.group(4).startswith("0"):
            out.append(chr(int(m.group(4)) & 0xFFFF))                # F# trigraph \DDD
            i += 4
        else:
            out.append(_CS_ESC.get(n, n))
            i += 2
    return "".join(out)


def _cs_tokens(src, vb, limit=60000):
    """[(kind, value)]: s (str), ch (_CsCh), n (int), is (interpolated parts), id, p (punct)."""
    toks, i, n = [], 0, len(src)
    while i < n and len(toks) < limit:
        if vb and src[i] == "'":                                    # VB comment
            j = src.find("\n", i)
            i = n if j < 0 else j
            continue
        if vb and src[i] == '"':
            m = _CS_VB_STR.match(src, i)
            if not m:
                break
            v = m.group(1).replace('""', '"')
            toks.append(("ch", _CsCh(ord(v[0]))) if m.group(2) and v else ("s", v))
            i = m.end()
            continue
        m = _CS_TOK.match(src, i)
        if not m:
            break
        k = m.lastgroup
        g = m.group(0)
        i = m.end()
        if k in ("ws", "cm"):
            continue
        if k == "raw":
            dollars = len(g) - len(g.lstrip("$"))
            q = g[dollars:]
            j = src.find(q, i)
            if j < 0:
                break
            body = src[i:j]
            i = j + len(q)
            if "\n" in body:                                         # multi-line raw: dedent by the closing line
                lines = body.split("\n")
                ind = lines[-1] if not lines[-1].strip() else ""
                body = "\n".join(x[len(ind):] if x.startswith(ind) else x for x in lines[1:-1 if ind or not lines[-1].strip() else None])
            elif len(q) == 3 and not dollars and q == '"""':        # F# triple-quoted single line
                pass
            toks.append(("is", _cs_interp(body, False, max(1, dollars))) if dollars else ("s", body))
        elif k == "vs":
            body = g[g.index('"') + 1:-1].replace('""', '"')
            toks.append(("is", _cs_interp(body, False)) if "$" in g[:3] else ("s", body))
        elif k == "is":
            toks.append(("is", _cs_interp(g[2:-1], True)))
        elif k == "s":
            suf = g[-1] if g[-1] in "cB" else ""
            v = _cs_unesc(g[1:len(g) - 1 - len(suf)])
            if suf == "c" and v:
                toks.append(("ch", _CsCh(ord(v[0]))))
            elif suf == "B":
                toks.append(("arr", [b & 0xFF for b in v.encode("latin-1", "replace")]))
            else:
                toks.append(("s", v))
        elif k == "ch":
            v = _cs_unesc(g[1:-1])
            toks.append(("ch", _CsCh(ord(v[0]) if v else 0)))
        elif k == "hx":
            h = m.group("hx").replace("_", "")
            toks.append(("n", int(h[2:], 2) if h[1] in "bB" else int(h[2:], 16)))
        elif k == "num":
            toks.append(("n", int(m.group("num").replace("_", ""))))
        elif k == "id":
            if g == "_" and vb:
                continue                                             # VB line continuation
            toks.append(("id", g.lstrip("@")))
        else:
            toks.append(("p", g))
    toks.append(("eof", None))
    return toks


def _cs_interp(body, esc, braces=1):
    """Parts of an interpolated string: str pieces and ("expr", text) holes (format / alignment dropped)."""
    parts, buf, i = [], [], 0
    op, cl = "{" * braces, "}" * braces
    while i < len(body):
        if body.startswith(op, i) and not (braces == 1 and body.startswith("{{", i)):
            depth, j = 0, i + braces
            k = j
            while k < len(body):
                if body[k] == "{":
                    depth += 1
                elif body[k] == "}":
                    if depth == 0:
                        break
                    depth -= 1
                k += 1
            expr = re.split(r"[:,](?=[^\"']*$)", body[j:k])[0] if '"' not in body[j:k] else body[j:k]
            parts.append("".join(buf))
            parts.append(("expr", expr))
            buf = []
            i = k + braces
            continue
        if braces == 1 and body.startswith(("{{", "}}"), i):
            buf.append(body[i])
            i += 2
            continue
        buf.append(body[i])
        i += 1
    parts.append("".join(buf))
    text = "".join(parts[0::2]) if len(parts) == 1 else None
    if esc:
        parts = [_cs_unesc(p) if isinstance(p, str) else p for p in parts]
    return parts if text is None else parts


def _cs_str(v):
    if isinstance(v, str):
        return v
    if isinstance(v, _CsCh):
        return chr(v % 0x110000)
    if isinstance(v, bool):
        return "True" if v else "False"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, _CsSB):
        return v.s
    if isinstance(v, list):
        if all(isinstance(x, _CsCh) for x in v):
            return "".join(chr(x % 0x110000) for x in v)
        return "System." + ("Byte[]" if all(isinstance(x, int) for x in v) else "Object[]")
    raise _CsStop("str")


def _cs_chars(v):
    if isinstance(v, str):
        return [_CsCh(ord(c)) for c in v]
    if isinstance(v, list):
        return list(v)
    raise _CsStop("seq")


def _cs_bytes(v):
    if isinstance(v, list):
        return bytes(int(x) & 0xFF for x in v)
    raise _CsStop("bytes")


_CS_ENC = {"utf8": "utf-8", "ascii": "ascii", "unicode": "utf-16-le", "bigendianunicode": "utf-16-be",
           "utf32": "utf-32-le", "latin1": "latin-1", "default": "utf-8", "utf7": "utf-7"}
_CS_CASTS = {"char": lambda x: _CsCh(int(x) & 0xFFFF), "byte": lambda x: int(x) & 0xFF, "sbyte": lambda x: int(x) & 0xFF,
             "int": int, "uint": lambda x: int(x) & 0xFFFFFFFF, "short": int, "ushort": lambda x: int(x) & 0xFFFF,
             "long": int, "ulong": int, "string": _cs_str, "Char": lambda x: _CsCh(int(x) & 0xFFFF),
             "Byte": lambda x: int(x) & 0xFF, "Int32": int, "String": _cs_str}


class _CsEval:
    """Pratt evaluator of a .NET expression subset over a token list (pos-based, re-entrant for lambdas)."""

    def __init__(self, toks, env, vb, fs, deadline):
        self.t, self.env, self.vb, self.fs, self.deadline, self.pos = toks, env, vb, fs, deadline, 0

    def peek(self, k=0):
        return self.t[min(self.pos + k, len(self.t) - 1)]

    def take(self):
        tk = self.t[self.pos]
        self.pos = min(self.pos + 1, len(self.t) - 1)
        return tk

    def isp(self, v, k=0):
        tk = self.peek(k)
        return tk[0] == "p" and tk[1] == v

    def isid(self, v, k=0):
        tk = self.peek(k)
        return tk[0] == "id" and (tk[1] == v if not self.vb else tk[1].lower() == v.lower())

    def expect(self, v):
        if not self.isp(v):
            raise _CsStop(v)
        self.take()

    # binary levels, lowest first: VB `&` concat sits below `+`
    def expr(self):
        if time.time() > self.deadline:
            raise _CsStop("time")
        if self.peek()[0] == "id" and self.isp("=>", 1):
            return self.lam([self.take()[1]], "=>")
        if self.isid("fun") and self.fs:
            self.take()
            ps = []
            while self.peek()[0] == "id":
                ps.append(self.take()[1])
            return self.lam(ps, "->")
        if self.isid("Function") and self.vb and self.isp("(", 1):
            self.take()
            self.take()
            ps = []
            while self.peek()[0] == "id":
                ps.append(self.take()[1])
                if self.isid("As"):
                    self.take()
                    self.take()
                if self.isp(","):
                    self.take()
            self.expect(")")
            return self.lam(ps, None)
        if self.isp("(") and self.peek(1)[0] == "id" and self.isp(")", 2) and self.isp("=>", 3):
            self.take()
            p = self.take()[1]
            self.take()
            return self.lam([p], "=>")
        v = self.binary(0)
        while self.isp("|>") and self.fs:
            self.take()
            f = self.binary(0)
            v = f(v) if callable(f) else _cs_fail()
        return v

    def lam(self, params, arrow):
        if arrow:
            self.expect(arrow)
        fn = _CsFn(params, self.pos, self)
        saved = dict(self.env)
        for p in params:
            self.env[p] = _CsCh(65)
        try:
            self.binary(0)
        finally:
            self.env.clear()
            self.env.update(saved)
        return fn

    def apply(self, fn, args):
        pos, saved = self.pos, dict(self.env)
        try:
            for p, a in zip(fn.params, args):
                self.env[p] = a
            self.pos = fn.start
            return self.binary(0)
        finally:
            self.pos = pos
            self.env.clear()
            self.env.update(saved)

    _LEVELS = (("||", "OrElse"), ("&&", "AndAlso"), ("|", "|||", "Or"), ("^", "^^^", "Xor"), ("&", "&&&", "And"),
               ("==", "!=", "=", "<>"), ("<<", ">>", "<<<", ">>>"), ("+", "-"), ("*", "/", "%", "Mod"))

    def binop(self, lvl):
        tk = self.peek()
        ops = self._LEVELS[lvl]
        if tk[0] == "p" and tk[1] in ops:
            if tk[1] == "=" and not self.vb:
                return None
            if tk[1] == "&" and self.vb:
                return None
            return tk[1]
        if tk[0] == "id" and self.vb and tk[1].capitalize() in ops or tk[0] == "id" and tk[1] in ("Xor", "Mod", "Or", "And") and tk[1] in ops:
            return tk[1].capitalize()
        return None

    def binary(self, lvl):
        if lvl == 3.5:
            pass
        if self.vb and lvl == 6:                                     # VB `&` concat: between shifts and `+`
            v = self.binary(7)
            while self.isp("&"):
                self.take()
                v = _cs_str(v) + _cs_str(self.binary(7))
            return v
        if lvl >= len(self._LEVELS):
            return self.unary()
        v = self.binary(lvl + 1)
        while True:
            op = self.binop(lvl)
            if op is None:
                return v
            self.take()
            r = self.binary(lvl + 1)
            v = _cs_binop(op, v, r, self.fs)

    def unary(self):
        tk = self.peek()
        if tk[0] == "p" and tk[1] in ("-", "~", "!", "+"):
            self.take()
            v = self.unary()
            return {"-": lambda x: -x, "~": lambda x: ~x, "!": lambda x: not x, "+": lambda x: x}[tk[1]](int(v))
        if tk[0] == "id" and self.vb and tk[1].lower() == "not":
            self.take()
            return ~int(self.unary())
        if self.isp("(") and self.peek(1)[0] == "id" and self.peek(1)[1] in _CS_CASTS and self.isp(")", 2) and \
                self.peek(3)[0] in ("id", "n", "ch", "s", "p") and not (self.peek(3)[0] == "p" and self.peek(3)[1] not in "(-~"):
            self.pos += 3
            return _CS_CASTS[self.peek(-2)[1]](self.unary())
        if self.isp("(") and self.isid("char", 1) and self.isp("[", 2) and self.isp("]", 3) and self.isp(")", 4):
            self.pos += 5
            return _cs_chars(self.unary())
        return self.postfix(self.primary())

    def args(self, close=")"):
        out = []
        if self.isp(close):
            self.take()
            return out
        while True:
            if self.peek()[0] == "id" and self.isp(":", 1) and not self.fs:
                self.pos += 2                                        # named argument
            out.append(self.expr())
            if self.isp(","):
                self.take()
                continue
            self.expect(close)
            return out

    def items(self, close, seps=(",", ";")):
        out = []
        while not self.isp(close):
            if self.peek()[0] == "eof":
                raise _CsStop("eof")
            out.append(self.expr())
            if self.peek()[0] == "p" and self.peek()[1] in seps:
                self.take()
        self.take()
        return out

    def postfix(self, v):
        while True:
            if self.isp(".") and self.peek(1)[0] == "id":
                self.take()
                name = self.take()[1]
                a = self.args() if self.isp("(") and self.take() else None
                v = _cs_method(v, name, a, self)
            elif self.isp(".") and self.isp("[", 1) and self.fs:
                self.pos += 2
                i = self.expr()
                self.expect("]")
                v = _cs_index(v, i)
            elif self.isp("[") and not self.fs:
                self.take()
                i = self.expr()
                self.expect("]")
                v = _cs_index(v, i)
            elif self.isp("(") and isinstance(v, (list, str)) and self.vb:
                self.take()
                a = self.args()
                v = _cs_index(v, a[0]) if len(a) == 1 else _cs_fail()
            elif self.isp("(") and callable(v) and not self.fs:
                self.take()
                v = v(*self.args())
            elif callable(v) and self.fs and self.peek()[0] in ("s", "ch", "n", "id", "is", "arr") or \
                    callable(v) and self.fs and self.peek()[0] == "p" and self.peek()[1] in ("(", "[", "[|"):
                v = v(self.fs_atom())
            else:
                return v

    def fs_atom(self):
        return self.postfix_nocall(self.primary())

    def postfix_nocall(self, v):
        while self.isp(".") and (self.peek(1)[0] == "id" or self.isp("[", 1)):
            if self.isp("[", 1):
                self.pos += 2
                i = self.expr()
                self.expect("]")
                v = _cs_index(v, i)
                continue
            self.take()
            name = self.take()[1]
            a = self.args() if self.isp("(") and self.take() else None
            v = _cs_method(v, name, a, self)
        return v

    def primary(self):
        k, val = self.take()
        if k == "s":
            return val
        if k in ("ch", "n"):
            return val
        if k == "arr":
            return list(val)
        if k == "is":
            out = []
            for p in val:
                if isinstance(p, str):
                    out.append(p)
                else:
                    sub = _CsEval(_cs_tokens(p[1], self.vb), self.env, self.vb, self.fs, self.deadline)
                    out.append(_cs_str(sub.expr()))
            return "".join(out)
        if k == "p":
            if val == "(":
                v = self.expr()
                if self.isp(","):                                    # tuple: keep the first (F# (a, b) args)
                    self.take()
                    rest = self.items(")")
                    return [v] + rest
                self.expect(")")
                return v
            if val in ("[|", "[") or (val == "{" and True):
                return self.items({"[|": "|]", "[": "]", "{": "}"}[val])
            raise _CsStop(val)
        if k != "id":
            raise _CsStop(k)
        low = val.lower() if self.vb else val
        if low in ("new", "New"):
            return self.new()
        if low == "nameof":
            self.expect("(")
            n = self.take()[1]
            self.expect(")")
            return n
        if val in self.env:
            return self.env[val]
        if val == "global" and self.isp("::"):
            self.take()
            val = self.take()[1]
        parts = [val]
        while self.isp(".") and self.peek(1)[0] == "id" and _cs_func(".".join(parts + [self.peek(1)[1]]), self.vb, True):
            self.take()
            parts.append(self.take()[1])
        f = _cs_func(".".join(parts), self.vb)
        if f is None:
            raise _CsStop(".".join(parts))
        if not callable(f) or isinstance(f, _CsCh):
            return f
        if self.fs and not self.isp("("):
            return f
        return f

    def new(self):
        typ = []
        while self.peek()[0] == "id" or self.isp(".") or self.isp("[") and self.isp("]", 1) or self.isp("<"):
            if self.isp("["):
                self.pos += 2
                typ.append("[]")
            elif self.isp("<"):
                while not self.isp(">") and self.peek()[0] != "eof":
                    self.take()
                self.take()
            else:
                typ.append(self.take()[1])
        if self.isp("[") and not typ or self.isp("[") and typ:      # new[] / new byte[n]
            self.take()
            if self.isp("]"):
                self.take()
            else:
                self.expr()
                self.expect("]")
            typ.append("[]")
        name = "".join(typ).split(".")[-1].lower()
        if self.isp("("):
            self.take()
            a = self.args()
            if name.startswith("stringbuilder"):
                return _CsSB(_cs_str(a[0]) if a and not isinstance(a[0], int) or a and isinstance(a[0], _CsCh) else "")
            if name.startswith("string"):
                if len(a) == 2 and isinstance(a[0], _CsCh):
                    return chr(a[0]) * int(a[1])
                if a and isinstance(a[0], list) and a[0] and not any(isinstance(x, _CsCh) for x in a[0]):
                    return _cs_bytes(a[0]).decode(_jv_charset(a[1]) if len(a) == 2 else "utf-8")  # Java new String(byte[])
                return "".join(chr(int(x) % 0x110000) for x in _cs_chars(a[0])) if a else ""
            if name.startswith("list"):
                v = list(_cs_chars(a[0])) if a else []
                return self.items("}") if self.isp("{") and self.take() else v
            if self.isp("{"):
                self.take()
                return self.items("}")
            raise _CsStop(name)
        if self.isp("{"):
            self.take()
            v = self.items("}")
            if name.startswith("char"):
                return [_CsCh(int(x) & 0xFFFF) for x in v]
            if name.startswith("byte"):
                return [int(x) & 0xFF for x in v]
            return v
        if name.startswith("stringbuilder"):
            return _CsSB()
        raise _CsStop(name)


def _cs_fail(*a):
    raise _CsStop("fail")


def _cs_binop(op, a, b, fs):
    if op == "+":
        if isinstance(a, (str, _CsSB)) or isinstance(b, (str, _CsSB)):
            return _cs_str(a) + _cs_str(b)
        if isinstance(a, list) or isinstance(b, list):
            raise _CsStop("+")
        return int(a) + int(b)
    if op == "^" and (isinstance(a, str) or isinstance(b, str)):
        return _cs_str(a) + _cs_str(b)                               # F# `^` string concatenation
    if isinstance(a, (str, list, _CsSB)) or isinstance(b, (str, list, _CsSB)):
        if op in ("==", "="):
            return a == b
        if op in ("!=", "<>"):
            return a != b
        raise _CsStop(op)
    a, b = int(a), int(b)
    return {"-": lambda: a - b, "*": lambda: a * b, "/": lambda: int(a / b) if b else _cs_fail(), "%": lambda: a % b if b else _cs_fail(),
            "Mod": lambda: a % b if b else _cs_fail(), "^": lambda: a ^ b, "^^^": lambda: a ^ b, "Xor": lambda: a ^ b,
            "&": lambda: a & b, "&&&": lambda: a & b, "And": lambda: a & b, "|": lambda: a | b, "|||": lambda: a | b,
            "Or": lambda: a | b, "<<": lambda: a << b, "<<<": lambda: a << b, ">>": lambda: a >> b, ">>>": lambda: a >> b,
            "==": lambda: a == b, "=": lambda: a == b, "!=": lambda: a != b, "<>": lambda: a != b,
            "&&": lambda: a and b, "AndAlso": lambda: a and b, "||": lambda: a or b, "OrElse": lambda: a or b}[op]()


def _cs_index(v, i):
    if isinstance(v, str):
        return _CsCh(ord(v[int(i)]))
    if isinstance(v, list):
        return v[int(i)]
    raise _CsStop("idx")


def _cs_join(sep, items):
    if len(items) == 1 and isinstance(items[0], list):
        items = items[0]
    return _cs_str(sep).join(_cs_str(x) for x in items)


def _cs_concat(*items):
    if len(items) == 1 and isinstance(items[0], list):
        items = items[0]
    return "".join(_cs_str(x) for x in items)


def _cs_reverse_inplace(a, *rng):
    if not isinstance(a, list):
        raise _CsStop("rev")
    s, n = (int(rng[0]), int(rng[1])) if len(rng) == 2 else (0, len(a))
    a[s:s + n] = a[s:s + n][::-1]
    return None


def _cs_tochar(x, *base):
    return _CsCh(int(x, int(base[0])) if base else (ord(x[0]) if isinstance(x, str) else int(x)))


def _cs_toint(x, *base):
    return int(x, int(base[0])) if base else (int(x) if not isinstance(x, str) else int(x.strip()))


def _cs_func(name, vb, prefix=False):
    """A known .NET / VB / F# static (callable or value) by dotted name; prefix=True: is `name` a prefix of one."""
    n = re.sub(r"^(?:global::)?(?:System\.)?(?:Text\.)?(?:Linq\.)?(?:Microsoft\.VisualBasic\.)?(?:Strings\.)?", "", name)
    n = re.sub(r"^java\.(?:util|lang|nio\.charset)\.", "", n)
    if n.startswith("FSharp.Core."):
        n = n[12:]
    table = _CS_FUNCS
    if prefix:
        return any(k == n or k.startswith(n + ".") for k in table) or n in ("System", "Text", "Linq", "Microsoft",
                                                                              "VisualBasic", "Strings", "Encoding",
                                                                              "java", "java.util", "java.lang", "java.nio",
                                                                              "java.nio.charset") \
            or bool(re.fullmatch(r"Encoding\.\w+(?:\.Get(?:String|Bytes))?", n))
    key = n if n in table else (n.lower() if vb else None)
    if key in table:
        return table[key]
    if vb:
        for k in table:
            if k.lower() == n.lower():
                return table[k]
    m = re.fullmatch(r"Encoding\.(\w+)\.(GetString|GetBytes)", n)
    if m and m.group(1).lower() in _CS_ENC:
        enc = _CS_ENC[m.group(1).lower()]
        if m.group(2) == "GetString":
            return lambda b, *r: _cs_bytes(b)[int(r[0]):int(r[0]) + int(r[1])].decode(enc) if r else _cs_bytes(b).decode(enc)
        return lambda s: list(_cs_str(s).encode(enc))
    return None


def _cs_b64(s):
    return list(base64.b64decode(re.sub(r"\s+", "", _cs_str(s)), validate=True))


_CS_FUNCS = {
    "string.Concat": _cs_concat, "String.Concat": _cs_concat, "string.Join": _cs_join, "String.Join": _cs_join,
    "string.Empty": "", "String.Empty": "", "Environment.NewLine": "\r\n",
    "string.Format": lambda f, *a: re.sub(r"\{(\d+)(?:[,:][^}]*)?\}", lambda m: _cs_str(a[int(m.group(1))]), _cs_str(f)),
    "String.Format": lambda f, *a: re.sub(r"\{(\d+)(?:[,:][^}]*)?\}", lambda m: _cs_str(a[int(m.group(1))]), _cs_str(f)),
    "Convert.FromBase64String": _cs_b64, "Convert.ToBase64String": lambda b: base64.b64encode(_cs_bytes(b)).decode(),
    "Convert.FromHexString": lambda s: list(bytes.fromhex(_cs_str(s))),
    "Convert.ToHexString": lambda b: _cs_bytes(b).hex().upper(), "Convert.ToChar": _cs_tochar,
    "Convert.ToByte": lambda x, *b: _cs_toint(x, *b) & 0xFF, "Convert.ToInt32": _cs_toint, "Convert.ToString": _cs_str,
    "BitConverter.ToString": lambda b, *r: "-".join("%02X" % x for x in _cs_bytes(b)),
    "char.ConvertFromUtf32": lambda x: chr(int(x)), "Char.ConvertFromUtf32": lambda x: chr(int(x)),
    "Array.Reverse": _cs_reverse_inplace, "Enumerable.Reverse": lambda s: _cs_chars(s)[::-1],
    "ChrW": lambda x: _CsCh(int(x) & 0xFFFF), "Chr": lambda x: _CsCh(int(x) & 0xFF), "AscW": lambda c: ord(_cs_str(c)[0]),
    "Asc": lambda c: ord(_cs_str(c)[0]), "CStr": _cs_str, "CChar": lambda c: _CsCh(ord(_cs_str(c)[0])),
    "CInt": int, "CByte": lambda x: int(x) & 0xFF, "StrReverse": lambda s: _cs_str(s)[::-1],
    "Join": lambda a, sep=" ": _cs_join(sep, [a]), "Mid": lambda s, a, n=None: _cs_str(s)[int(a) - 1:None if n is None else int(a) - 1 + int(n)],
    # F#
    "String.concat": lambda sep: (lambda items: _cs_join(sep, [list(items)])), "char": lambda x: _CsCh(ord(x[0]) if isinstance(x, str) else int(x) & 0xFFFF),
    "string": _cs_str, "int": lambda x: int(x), "byte": lambda x: int(x) & 0xFF,
    "Array.rev": lambda a: list(a)[::-1], "List.rev": lambda a: list(a)[::-1], "Seq.rev": lambda a: _cs_chars(a)[::-1],
    "String.Concat.": _cs_concat, "System.String": lambda a: "".join(chr(int(x)) for x in _cs_chars(a)),
    "String": lambda a: "".join(chr(int(x)) for x in _cs_chars(a)),
    "Array.map": lambda f: (lambda a: [f(x) for x in a]), "List.map": lambda f: (lambda a: [f(x) for x in a]),
    "Seq.map": lambda f: (lambda a: [f(x) for x in _cs_chars(a)]), "String.map": lambda f: (lambda s: _cs_str([f(x) for x in _cs_chars(s)])),
    "Array.ofSeq": list, "List.ofSeq": list, "Seq.toArray": list, "String.Join.": _cs_join,
    # Java (target jvm-script-host-route: JSP / single-file Java descriptors assembled at runtime)
    "Base64.getDecoder": lambda: _JvObj("b64"), "Base64.getMimeDecoder": lambda: _JvObj("b64mime"),
    "Base64.getUrlDecoder": lambda: _JvObj("b64url"), "HexFormat.of": lambda: _JvObj("hex"),
    "String.join": lambda sep, *xs: _cs_join(sep, list(xs)), "String.valueOf": _cs_str, "String.copyValueOf": _cs_str,
    "Character.toString": lambda x: chr(int(x) % 0x110000), "Integer.parseInt": _cs_toint, "Integer.valueOf": _cs_toint,
    "StandardCharsets.UTF_8": "UTF-8", "StandardCharsets.US_ASCII": "US-ASCII", "StandardCharsets.ISO_8859_1": "ISO-8859-1",
    "StandardCharsets.UTF_16LE": "UTF-16LE", "StandardCharsets.UTF_16BE": "UTF-16BE",
}


class _JvObj:
    """A Java helper object (`Base64.getDecoder()`, `HexFormat.of()`)."""
    def __init__(self, kind):
        self.kind = kind


def _jv_charset(cs):
    v = _cs_str(cs).strip().lower().replace("_", "-")
    if v not in ("utf-8", "utf8", "us-ascii", "ascii", "iso-8859-1", "latin1", "utf-16le", "utf-16be", "utf-16"):
        raise _CsStop("charset")
    return v


# Java method spellings with C# semantics (camelCase never collides with the PascalCase .NET names)
_JV_METHOD = {"append": "Append", "toString": "ToString", "insert": "Insert", "length": "Length", "trim": "Trim",
              "toCharArray": "ToCharArray", "toUpperCase": "ToUpper", "toLowerCase": "ToLower"}


def _jv_method(v, name, a):
    """Java-only methods (Groovy `.reverse()` / `.decodeBase64()` / `.decodeHex()` too). NotImplemented: not one."""
    if isinstance(v, _JvObj):
        if name == "decode" and a and v.kind.startswith("b64"):
            t = _cs_bytes(a[0]) if isinstance(a[0], list) else _cs_str(a[0]).encode("latin-1")
            t = re.sub(rb"\s+", b"", t) if v.kind == "b64mime" else t
            t = t.translate(bytes.maketrans(b"-_", b"+/")) if v.kind == "b64url" else t
            return list(base64.b64decode(t + b"=" * (-len(t) % 4) if v.kind != "b64" else t, validate=True))
        if name == "parseHex" and a:
            return list(bytes.fromhex(_cs_str(a[0])))
        raise _CsStop(name)
    if isinstance(v, _CsSB) and name == "reverse" and not a:
        v.s = v.s[::-1]
        return v
    if isinstance(v, (str, list)) and name == "reverse" and not a:      # Groovy String / List .reverse()
        return v[::-1]
    if isinstance(v, str) and name == "decodeBase64" and not a:          # Groovy
        return list(base64.b64decode(re.sub(r"\s+", "", v), validate=True))
    if isinstance(v, str) and name == "decodeHex" and not a:             # Groovy
        return list(bytes.fromhex(v))
    if name == "getBytes" and isinstance(v, (str, _CsSB)):
        return list(_cs_str(v).encode(_jv_charset(a[0]) if a else "utf-8"))
    if isinstance(v, (str, _CsSB)) and name == "substring" and a:         # Java: (begin[, end])
        s = _cs_str(v)
        return s[int(a[0]):] if len(a) == 1 else s[int(a[0]):int(a[1])]
    if isinstance(v, (str, _CsSB)) and name == "charAt" and a and len(a) == 1:
        return _CsCh(ord(_cs_str(v)[int(a[0])]))
    if isinstance(v, str) and name == "concat" and a and len(a) == 1:
        return v + _cs_str(a[0])
    if isinstance(v, str) and name == "replace" and a and len(a) == 2:
        return v.replace(_cs_str(a[0]), _cs_str(a[1]))
    return NotImplemented


def _cs_method(v, name, a, ev):
    if name[:1].islower() and not ev.fs and not ev.vb:
        r = _jv_method(v, name, a)
        if r is not NotImplemented:
            return r
        name = _JV_METHOD.get(name, name)
    if isinstance(v, _CsSB):
        if name in ("Append", "AppendLine") and a is not None:
            v.s += (_cs_str(a[0]) * (int(a[1]) if len(a) == 2 and isinstance(a[0], _CsCh) else 1) if a else "") + \
                ("\r\n" if name == "AppendLine" else "")
            return v
        if name == "Insert" and a:
            i = int(a[0])
            v.s = v.s[:i] + _cs_str(a[1]) + v.s[i:]
            return v
        if name == "ToString":
            return v.s
        if name == "Length":
            return len(v.s)
        if name == "Clear":
            v.s = ""
            return v
        if name == "Replace" and a:
            v.s = v.s.replace(_cs_str(a[0]), _cs_str(a[1]))
            return v
        raise _CsStop(name)
    if callable(v) and not isinstance(v, (str, list)):
        raise _CsStop(name)
    a = a or []
    if name in ("ToString", "ToArray", "ToList", "AsEnumerable", "Trim") and not a:
        if name == "ToString":
            return _cs_str(v)
        if name == "Trim":
            return _cs_str(v).strip()
        return list(_cs_chars(v)) if isinstance(v, str) else list(v)
    if name == "ToCharArray":
        return _cs_chars(v)
    if name == "Reverse":
        return _cs_chars(v)[::-1]
    if name in ("Length", "Count", "LongLength"):
        return len(v)
    if name in ("Select", "Map") and a and callable(a[0]):
        f = a[0]
        if len(f.params) == 2:
            return [f(x, _CsCh(i) if False else i) for i, x in enumerate(_cs_chars(v))]
        return [f(x) for x in _cs_chars(v)]
    if name == "Substring" and a:
        s = _cs_str(v)
        return s[int(a[0]):] if len(a) == 1 else s[int(a[0]):int(a[0]) + int(a[1])]
    if name == "Replace" and len(a) == 2:
        return _cs_str(v).replace(_cs_str(a[0]), _cs_str(a[1]))
    if name in ("ToUpper", "ToUpperInvariant"):
        return _cs_str(v).upper()
    if name in ("ToLower", "ToLowerInvariant"):
        return _cs_str(v).lower()
    if name == "Concat" and a:
        return (_cs_chars(v) if isinstance(v, str) else list(v)) + _cs_chars(a[0])
    if name in ("Skip", "Take") and a:
        s = _cs_chars(v)
        return s[int(a[0]):] if name == "Skip" else s[:int(a[0])]
    raise _CsStop(name)


def _cs_skip_stmt(t, i):
    """Index after the statement starting at i (C#: next `;` at depth 0)."""
    depth = 0
    while t[i][0] != "eof":
        if t[i][0] == "p" and t[i][1] in "([{":
            depth += 1
        elif t[i][0] == "p" and t[i][1] in ")]}":
            depth -= 1
            if depth < 0:
                return i
        elif t[i][0] == "p" and t[i][1] == ";" and depth == 0:
            return i + 1
        i += 1
    return i


def _cs_exec(ev, a, b, cands, depth=0, loops=None):
    """Run the statements in t[a:b): const-local assignments, appends, element writes, loops, returns."""
    t, env, vb = ev.t, ev.env, ev.vb
    i = a
    loops = loops if loops is not None else [0]

    def eval_at(j):
        ev.pos = j
        v = ev.expr()
        return v, ev.pos

    while i < b and t[i][0] != "eof":
        if time.time() > ev.deadline:
            raise _CsStop("time")
        k, v = t[i]
        nk, nv = t[i + 1] if i + 1 < len(t) else ("eof", None)
        prev = t[i - 1] if i > 0 else ("p", ";")
        try:
            # C# for (init; i < N; i++) body
            if k == "id" and v == "for" and nk == "p" and nv == "(" and not vb:
                h0 = i + 2
                h1 = _cs_skip_stmt(t, h0)
                h2 = _cs_skip_stmt(t, h1)
                j = h0 + (1 if t[h0][0] == "id" and t[h0 + 1][0] == "id" else 0)
                var = t[j][1]
                start, _ = eval_at(j + 2)
                if not (t[h1][1] == var and t[h1 + 1][1] in ("<", "<=")):
                    raise _CsStop("for")
                lim, _ = eval_at(h1 + 2)
                lim = int(lim) + (1 if t[h1 + 1][1] == "<=" else 0)
                close = h2
                depth_p = 0
                while t[close][0] != "eof":                          # the header's `)`
                    if t[close][1] == "(":
                        depth_p += 1
                    elif t[close][1] == ")":
                        if depth_p == 0:
                            break
                        depth_p -= 1
                    close += 1
                body_a = close + 1
                if t[body_a] == ("p", "{"):
                    body_b = _cs_match(t, body_a)
                    body_a, after = body_a + 1, body_b + 1
                else:
                    body_b = after = _cs_skip_stmt(t, body_a)
                for idx in range(int(start), lim):
                    loops[0] += 1
                    if loops[0] > 1 << 17:
                        raise _CsStop("loop")
                    env[var] = idx
                    _cs_exec(ev, body_a, body_b, cands, depth + 1, loops)
                i = after
                continue
            # VB For i = a To b [Step 1] ... Next
            if vb and k == "id" and v.lower() == "for" and nk == "id" and nv.lower() != "each":
                var = nv
                j = i + 2
                if t[j][0] == "id" and t[j][1].lower() == "as":
                    j += 2
                start, j = eval_at(j + 1)
                if not (t[j][0] == "id" and t[j][1].lower() == "to"):
                    raise _CsStop("For")
                lim, j = eval_at(j + 1)
                e = j
                nest = 0
                while t[e][0] != "eof":
                    if t[e][0] == "id" and t[e][1].lower() == "for":
                        nest += 1
                    if t[e][0] == "id" and t[e][1].lower() == "next":
                        if nest == 0:
                            break
                        nest -= 1
                    e += 1
                for idx in range(int(start), int(lim) + 1):
                    loops[0] += 1
                    if loops[0] > 1 << 17:
                        raise _CsStop("loop")
                    env[var] = idx
                    _cs_exec(ev, j, e, cands, depth + 1, loops)
                i = e + 1 + (1 if t[e + 1][0] == "id" and t[e + 1][1] == var else 0)
                continue
            # element write: x[i] = e / x[i] ^= e / VB x(i) = e / F# x.[i] <- e
            if k == "id" and v in env and isinstance(env[v], list) and (nk == "p" and nv in ("[", "(") or
                                                                       nv == "." and t[i + 2][1] == "["):
                j = i + (3 if nv == "." else 2)
                idx, j = eval_at(j)
                if t[j][1] not in ("]", ")"):
                    raise _CsStop("idx")
                op = t[j + 1][1]
                if op in ("=", "<-", "^=", "+=", "-=", "|=", "&="):
                    val, e = eval_at(j + 2)
                    cur = env[v][int(idx)]
                    if op in ("^=", "+=", "-=", "|=", "&="):
                        val = _cs_binop(op[0], cur, val, ev.fs)
                    if isinstance(cur, _CsCh):
                        val = _CsCh(int(val) & 0xFFFF)
                    env[v][int(idx)] = val
                    i = e
                    continue
            # assignment / compound append
            if k == "id" and nk == "p" and nv in ("=", "+=", "&=", "<-", ":=") and prev[1] not in (".", "[", "(", ",") \
                    and not (prev[0] == "id" and prev[1] in ("for", "foreach")):
                val, e = eval_at(i + 2)
                if nv in ("+=", "&="):
                    val = _cs_str(env.get(v, "")) + _cs_str(val) if not isinstance(env.get(v), int) or nv == "&=" \
                        else env[v] + int(val)
                env[v] = val
                if isinstance(v, str) and _CS_DESC_NAME.search(v):
                    cands.append((v, val))
                i = e
                continue
            # VB `Dim x As T = e` / `Dim sb As New StringBuilder` ; F# / TS `let x : T = e`
            if k == "id" and ((vb and nk == "id" and nv.lower() == "as") or (nk == "p" and nv == ":" and ev.fs)):
                j = i + 2
                if vb and t[j][0] == "id" and t[j][1].lower() == "new":
                    val, e = eval_at(j)
                    env[v] = val
                    i = e
                    continue
                while j < i + 12 and not (t[j][0] == "p" and t[j][1] in ("=", ";", ")", ",")):
                    j += 1
                if t[j] == ("p", "="):
                    val, e = eval_at(j + 1)
                    env[v] = val
                    if _CS_DESC_NAME.search(v):
                        cands.append((v, val))
                    i = e
                    continue
            # side-effect statement: sb.Append(..)..; Array.Reverse(x); list.Reverse();
            if k == "id" and (v in env or v in ("Array", "System")) and nk == "p" and nv == "." and \
                    prev[1] not in (".", "=", "(", ","):
                if v in env and isinstance(env[v], list) and t[i + 2] == ("id", "Reverse") and t[i + 3][1] == "(" \
                        and t[i + 4][1] == ")":
                    env[v].reverse()
                    i += 5
                    continue
                _, e = eval_at(i)
                i = e
                continue
            # dictionary entry ["descriptor"] = e / {"descriptor", e}, return e, => e
            if k == "p" and v == "[" and nk == "s" and _CS_DESC_NAME.search(nv) and t[i + 2][1] == "]" and t[i + 3][1] == "=":
                val, e = eval_at(i + 4)
                cands.append((nv, val))
                i = e
                continue
            if (k == "id" and v in ("return", "Return")) or (k == "p" and v == "=>"):
                val, e = eval_at(i + 1)
                cands.append(("", val))
                i = e
                continue
        except (_CsStop, ValueError, TypeError, IndexError, KeyError, ZeroDivisionError, OverflowError,
                UnicodeError, binascii.Error, RecursionError, AttributeError):
            if time.time() > ev.deadline:
                raise _CsStop("time")
        i += 1


def _cs_match(t, i):
    depth = 0
    while t[i][0] != "eof":
        if t[i][0] == "p" and t[i][1] in ("{", "(", "["):
            depth += 1
        elif t[i][0] == "p" and t[i][1] in ("}", ")", "]"):
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return i


def cs_fold(src, budget=0.5):
    """[(name, folded descriptor string)] of a C# / VB.NET / F# source whose descriptor is assembled at runtime."""
    try:
        src = src if isinstance(src, str) else bytes(src).decode("utf-8", "ignore")
        src = src[:1 << 18]
        if re.search(r"(?<!\\)(?:\\\\)*\\u+00(?:22|27|2[bB]|3[bBdD]|28|29)", re.sub(r'"(?:[^"\\\n]|\\.)*"', '""', src)) \
                and not re.search(r"(?m)^\s*(?:val|fun)\s+\w", src):
            src = _jv_unicode_pre(src)       # Java / BeanShell: a `\u0022` OUTSIDE any literal is a quote before lexing
        vb = bool(re.search(r"(?im)^\s*(?:(?:Public|Private|Friend|Shared)\s+)*(?:Dim|Const|Imports|Module|Sub|Function)\s+\w", src)
                  and re.search(r"(?i)\bAs\s+(?:New\s+)?\w|\bEnd\s+(?:Sub|Module|Function|Class)\b|&\s*Chr", src))
        fs = not vb and bool(re.search(r"(?m)^\s*let\s+(?:mutable\s+)?\w", src))
        toks = _cs_tokens(src, vb)
        env, cands = {}, []
        ev = _CsEval(toks, env, vb, fs, time.time() + budget)
        try:
            _cs_exec(ev, 0, len(toks) - 1, cands)
        except (_CsStop, RecursionError):
            pass
        out, seen = [], set()
        for name, val in [(n, v) for n, v in env.items() if _CS_DESC_NAME.search(n)] + cands:
            try:
                s = _cs_str(val)
            except _CsStop:
                continue
            if s and s not in seen:
                seen.add(s)
                out.append((name, s))
        return out
    except Exception:  # noqa: BLE001 - hostile / truncated source: nothing folds
        return []


def _cs_fold_codecs(src, budget=0.5):
    """find_codecs readings of runtime-assembled .NET descriptors (first plan wins)."""
    if not isinstance(src, str) or not (_CS_CUE.search(src[:1 << 18]) or _BSH_CUE.search(src[:1 << 18])) or \
            not _CS_DESC_NAME.search(src[:1 << 18]):
        return []
    end = time.time() + budget
    for name, s in cs_fold(src, budget * 0.6):
        if time.time() > end:
            break
        plain = peel_plan(s, budget=min(0.3, max(0.05, end - time.time())))
        if plain:
            ident = re.sub(r"^descriptor[_-]?", "", name, flags=re.I) or "descriptor"
            return [{"id": ident, "rep": "descriptor_folded", "transform": "identity", "key": "", "material": s,
                     "plain": plain}]
    return []


# Groovy / Kotlin descriptor folding (target groovy-literal-fold): a descriptor assembled at runtime from literals --
# GString `"${a}${b}"`, `'..' + '..'`, `[..].join()`, `.reverse()`, `.decodeBase64()` / `.decodeHex()`,
# `Base64.getDecoder().decode(..)`, `[..] as byte[]` / `as char[]`, `.collect { it as char }`, `(char) 0x76`,
# `String.format`, `.tr(..)`, slashy `/../` / dollar-slashy `$/../$`, `'''..'''` / `"""..."""` (`\` continuations),
# `.stripIndent()`, Kotlin `buildString { append(..) }`, `listOf(..).joinToString("")`, `String(byteArrayOf(..))`,
# `.toByteArray().map { (it.toInt() xor k).toChar() }`. A bounded scannerless const-evaluator over the literals.
_GV_CUE = re.compile(r"""\bdef\s+\w+\s*=|\b(?:val|var)\s+\w+\s*(?::\s*[\w.<>?]+\s*)?=|\.decodeBase64\s*\(|\.decodeHex\s*\(|"""
                     r"""\bas\s+(?:byte|char)\b|\bbuildString\b|\bjoinToString\b|\b(?:byte|char|int)ArrayOf\b|\blistOf\s*\(|"""
                     r"""\.collect\s*\{|\$/|\.stripIndent\s*\(|\.trimIndent\s*\(|\bpipeline\s*\{|\bfun\s+\w|\.tr\s*\(""")
_GV_STMT = re.compile(r"""(?m)(?:^|[;{])[ \t]*(?:(?:@\w+(?:\([^)\n]*\))?|def|final|static|private|public|protected|const|val|var|"""
                      r"""lateinit|String|CharSequence|Object|byte\[\]|char\[\]|int\[\]|ByteArray|CharArray|List(?:<[\w<>, ]*>)?)[ \t]+)*"""
                      r"""(?:(?P<name>[A-Za-z_]\w*)[ \t]*(?::[ \t]*[\w.<>?, \[\]]+[ \t]*)?(?P<op>\+?=)(?!=)|"""
                      r"""fun[ \t]+(?P<fn>[A-Za-z_]\w*)[ \t]*\([ \t]*\)[ \t]*(?::[ \t]*[\w.<>?]+[ \t]*)?=(?!=)|"""
                      r"""(?P<recv>[A-Za-z_]\w*)(?=[ \t]*(?:\.[ \t]*(?:append|insert|reverse|setLength)\b|<<)))|"""
                      r"""\breturn[ \t]+(?=\S)|\b(?P<key>descriptor\w*)[ \t]*:[ \t]*(?=[^\s:])""")
_GV_ESC = {"b": "\b", "t": "\t", "n": "\n", "f": "\f", "r": "\r", "s": " ", "\\": "\\", "'": "'", '"': '"', "$": "$", "/": "/"}
_GV_TYPES = ("byte[]", "char[]", "int[]", "Byte[]", "Character[]", "Integer[]", "String[]", "char", "Character", "byte",
             "Byte", "int", "Integer", "long", "Long", "short", "String", "List", "ArrayList", "Object", "CharSequence")


class _GvStop(Exception):
    pass


class _GvCh(int):
    """A Groovy/Kotlin char (an int that joins / concatenates as its character)."""


class _GvSB:
    def __init__(self, s=""):
        self.s = s


class _GvFn:
    def __init__(self, params, a, b):
        self.params, self.a, self.b = params, a, b


def _gv_str(v):
    if isinstance(v, str):
        return v
    if isinstance(v, _GvCh):
        return chr(v % 0x110000)
    if isinstance(v, _GvSB):
        return v.s
    if isinstance(v, bool) or v is None:
        raise _GvStop("str")
    if isinstance(v, int):
        return str(v)
    if isinstance(v, list):
        return "[" + ", ".join(_gv_str(x) for x in v) + "]"
    raise _GvStop("str")


def _gv_bytes(v):
    if isinstance(v, list) and all(isinstance(x, int) and not isinstance(x, (_GvCh, bool)) for x in v):
        return bytes(x & 0xFF for x in v)
    raise _GvStop("bytes")


def _gv_text(v, cs=None):
    """`new String(x[, cs])` / Kotlin `String(x)` / `.decodeToString()`."""
    if isinstance(v, list) and v and all(isinstance(x, _GvCh) for x in v):
        return "".join(chr(x) for x in v)
    if isinstance(v, (str, _GvSB)):
        return _gv_str(v)
    enc = (_gv_str(cs).strip().lower().replace("_", "-") if cs is not None else "utf-8")
    enc = {"utf8": "utf-8", "us-ascii": "ascii", "iso-8859-1": "latin-1", "iso8859-1": "latin-1"}.get(enc, enc)
    if enc not in ("utf-8", "ascii", "latin-1", "utf-16le", "utf-16be", "utf-16"):
        raise _GvStop("charset")
    try:
        return _gv_bytes(v).decode(enc)
    except UnicodeDecodeError:
        raise _GvStop("decode")


def _gv_tr_set(s):
    out, i = [], 0
    while i < len(s):
        if i + 2 < len(s) and s[i + 1] == "-":
            out.extend(chr(c) for c in range(ord(s[i]), ord(s[i + 2]) + 1))
            i += 3
        else:
            out.append(s[i])
            i += 1
    return out


def _gv_tr(s, a, b):
    a, b = _gv_tr_set(_gv_str(a)), _gv_tr_set(_gv_str(b))
    if not a or not b:
        raise _GvStop("tr")
    m = {}
    for i, c in enumerate(a):
        m[c] = b[i] if i < len(b) else b[-1]
    return "".join(m.get(c, c) for c in s)


def _gv_format(fmt, args):
    args, k = list(args), [0]

    def one(m):
        conv = m.group(4)
        if conv == "%":
            return "%"
        if conv == "n":
            return "\n"
        if m.group(1):
            i = int(m.group(1)[:-1]) - 1
        else:
            i, k[0] = k[0], k[0] + 1
        if i >= len(args):
            raise _GvStop("format")
        v, spec = args[i], "%" + (m.group(2) or "") + (m.group(3) or "")
        if conv in "sS":
            r = (spec + "s") % _gv_str(v)
            return r.upper() if conv == "S" else r
        if conv == "c":
            return (spec + "s") % (_gv_str(v) if isinstance(v, str) else chr(int(v) % 0x110000))
        if conv in "dxXo":
            if isinstance(v, str) or isinstance(v, list):
                raise _GvStop("format")
            return (spec + conv) % int(v)
        raise _GvStop("format")
    return re.sub(r"%(\d+\$)?([-#+ 0,(]*\d*)(\.\d+)?([a-zA-Z%])", one, _gv_str(fmt))


def _gv_dedent(s, kotlin=False):
    lines = s.split("\n")
    if kotlin:                                         # trimIndent: blank first / last line dropped
        if lines and not lines[0].strip():
            lines = lines[1:]
        if lines and not lines[-1].strip():
            lines = lines[:-1]
    ind = [len(x) - len(x.lstrip(" \t")) for x in lines if x.strip()]
    n = min(ind) if ind else 0
    return "\n".join(x[n:] if x.strip() else ("" if kotlin else x[n:]) for x in lines)


class _GvEval:
    def __init__(self, src, env, kotlin, deadline):
        self.s, self.env, self.kt, self.dl, self.recv, self.steps = src, env, kotlin, deadline, None, 0

    # -- lexical helpers ----------------------------------------------------------------------------------------------
    def ws(self, i, nl=True):
        s = self.s
        while i < len(s):
            c = s[i]
            if c in " \t\r" or (nl and c == "\n"):
                i += 1
            elif s.startswith("//", i) and not s.startswith("///", i):
                j = s.find("\n", i)
                i = len(s) if j < 0 else j
            elif s.startswith("/*", i):
                j = s.find("*/", i + 2)
                i = len(s) if j < 0 else j + 2
            elif c == "\\" and s.startswith("\n", i + 1) and not nl:
                i += 2
            else:
                break
        return i

    def tick(self):
        self.steps += 1
        if self.steps > 200000 or (self.steps & 255 == 0 and time.time() > self.dl):
            raise _GvStop("budget")

    def ident(self, i):
        m = re.compile(r"[A-Za-z_]\w*").match(self.s, i)
        if not m:
            raise _GvStop("ident")
        return m.group(0), m.end()

    def skip_braces(self, i):
        """index after the `}` matching the `{` at s[i] (string literals skipped)."""
        s, depth = self.s, 0
        while i < len(s):
            self.tick()
            c = s[i]
            if c in "\"'":
                q = s[i:i + 3] if s[i:i + 3] in ('"""', "'''") else c
                j = i + len(q)
                while j < len(s) and not s.startswith(q, j):
                    j += 2 if s[j] == "\\" and not (self.kt and len(q) == 3) else 1
                i = j + len(q)
                continue
            if c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    return i + 1
            i += 1
        raise _GvStop("brace")

    # -- string literals ----------------------------------------------------------------------------------------------
    def interp(self, body, esc):
        """GString / Kotlin template body -> text. esc: 'g' Groovy escapes, 'k' Kotlin, 'raw' none, '/' slashy, '$/'."""
        out, i, n = [], 0, len(body)
        while i < n:
            self.tick()
            c = body[i]
            if c == "\\" and esc in ("g", "k") and i + 1 < n:
                d = body[i + 1]
                if d == "\n":
                    i += 2
                elif d == "u" and re.match(r"u+[0-9a-fA-F]{4}", body[i + 1:i + 10]):
                    m = re.match(r"u+([0-9a-fA-F]{4})", body[i + 1:])
                    out.append(chr(int(m.group(1), 16)))
                    i += 1 + m.end()
                elif esc == "g" and d in "01234567":
                    m = re.match(r"[0-3]?[0-7]{1,2}", body[i + 1:])
                    out.append(chr(int(m.group(0), 8)))
                    i += 1 + m.end()
                elif d in _GV_ESC and not (esc == "k" and d in "sf/"):
                    out.append(_GV_ESC[d])
                    i += 2
                else:
                    raise _GvStop("escape")
            elif c == "\\" and esc == "/" and body.startswith("/", i + 1):
                out.append("/")
                i += 2
            elif c == "$" and esc == "$/" and i + 1 < n and body[i + 1] in "$/":
                out.append(body[i + 1])
                i += 2
            elif c == "$" and body.startswith("{", i + 1):
                depth, j = 0, i + 1
                while j < n:
                    depth += {"{": 1, "}": -1}.get(body[j], 0)
                    if depth == 0:
                        break
                    j += 1
                if j >= n:
                    raise _GvStop("gstring")
                sub = _GvEval(body[i + 2:j], self.env, self.kt, self.dl)
                sub.steps = self.steps
                k = sub.ws(0)
                v, k = sub.expr(k)
                if sub.ws(k) != len(sub.s):
                    raise _GvStop("gstring")
                self.steps = sub.steps
                out.append(_gv_str(v))
                i = j + 1
            elif c == "$" and re.match(r"[A-Za-z_]", body[i + 1:i + 2]):
                m = re.match(r"[A-Za-z_]\w*", body[i + 1:])
                if m.group(0) not in self.env:
                    raise _GvStop("unbound")
                out.append(_gv_str(self.env[m.group(0)]))
                i += 1 + m.end()
            else:
                out.append(c)
                i += 1
        return "".join(out)

    def string(self, i):
        """(value, end) of the string literal at s[i], or None."""
        s = self.s
        for q, esc, gs in (('"""', "raw" if self.kt else "g", True), ("'''", "g", False)):
            if s.startswith(q, i):
                j = i + 3
                while True:
                    k = s.find(q, j)
                    if k < 0:
                        raise _GvStop("string")
                    if esc == "raw" or (len(s[j:k]) - len(s[j:k].rstrip("\\"))) % 2 == 0:
                        break
                    j = k + 1
                while s.startswith(q[0], k + 3) and esc == "raw":     # Kotlin `""""a""""`: trailing quotes are content
                    k += 1
                body = s[i + 3:k]
                return (self.interp(body, esc) if gs else self.interp(body.replace("$", "\\$"), esc)), k + 3
        if s.startswith("$/", i):
            j = i + 2
            while True:
                k = s.find("/$", j)
                if k < 0:
                    raise _GvStop("string")
                if s[k - 1] != "$" or s[k - 2:k] == "$$":
                    break
                j = k + 1
            return self.interp(s[i + 2:k], "$/"), k + 2
        c = s[i:i + 1]
        if c in ("'", '"'):
            m = re.compile(c + r"((?:[^" + c + r"\\\n]|\\.|\\\n)*)" + c).match(s, i)
            if not m and c == '"':
                m = self._dq_nested(i)
            if not m:
                raise _GvStop("string")
            body, end = (m.group(1), m.end()) if not isinstance(m, tuple) else m
            if c == "'" and self.kt:
                t = self.interp(body, "k")
                if len(t) != 1:
                    raise _GvStop("char")
                return _GvCh(ord(t)), end
            return self.interp(body if c == '"' else body.replace("$", "\\$"), "k" if self.kt else "g"), end
        if c == "/" and not s.startswith(("//", "/*"), i):
            m = re.compile(r"/((?:[^/\\\n]|\\.)+)/").match(s, i)
            if not m:
                raise _GvStop("slashy")
            return self.interp(m.group(1), "/"), m.end()
        return None

    def _dq_nested(self, i):
        """A `"..${ "x" }.."` double-quoted string whose template holds quotes: (body, end) or None."""
        s, j, depth = self.s, i + 1, 0
        while j < len(s) and s[j] != "\n":
            if s[j] == "\\":
                j += 2
                continue
            if s.startswith("${", j):
                depth += 1
                j += 2
                continue
            if s[j] == "}" and depth:
                depth -= 1
            elif s[j] == '"' and not depth:
                return s[i + 1:j], j + 1
            elif s[j] == '"':
                k = s.find('"', j + 1)
                if k < 0:
                    return None
                j = k
            j += 1
        return None

    # -- expressions --------------------------------------------------------------------------------------------------
    _BIN = ((("|", "or"),), (("^", "xor"),), (("&", "and"),), (("<<", "shl"), (">>", "shr"), ("ushr", "ushr")),
            (("+",), ("-",)), (("*",), ("%",)))

    def expr(self, i, lvl=0):
        if lvl >= len(self._BIN):
            return self.unary(i)
        a, i = self.expr(i, lvl + 1)
        while True:
            self.tick()
            j = self.ws(i, nl=False)
            op = None
            for group in self._BIN[lvl]:
                for t in group:
                    if t.isalpha():
                        if re.compile(t + r"\b").match(self.s, j):
                            op = group[0]
                    elif self.s.startswith(t, j) and not self.s.startswith(t + "=", j) and \
                            not (t in "|&<>" and self.s.startswith(t * 2, j) and len(t) == 1) and \
                            not (t in ("+", "-") and self.s.startswith(t * 2, j)) and not (t == "*" and self.s.startswith("*.", j)):
                        op = group[0]
                    if op:
                        j += len(t)
                        break
                if op:
                    break
            if not op:
                return a, i
            b, i = self.expr(self.ws(j), lvl + 1)
            a = self.binop(op, a, b)

    def binop(self, op, a, b):
        if op == "<<" and isinstance(a, (_GvSB, str, list)):
            if isinstance(a, _GvSB):
                a.s += _gv_str(b)
                return a
            return (a + [b]) if isinstance(a, list) else _GvSB(a + _gv_str(b))
        if op == "+":
            if isinstance(a, (str, _GvSB)) or isinstance(b, (str, _GvSB)) and not isinstance(a, list):
                return _gv_str(a) + _gv_str(b)
            if isinstance(a, list):
                return a + (b if isinstance(b, list) else [b])
            if isinstance(a, _GvCh) and self.kt and not isinstance(b, _GvCh):
                return _GvCh(a + b)
        if op == "*" and isinstance(a, str) and isinstance(b, int) and 0 <= b < 4096:
            return a * b
        if op == "-" and isinstance(a, str) and isinstance(b, str):
            return a.replace(b, "", 1)
        if not (isinstance(a, int) and isinstance(b, int)) or isinstance(a, bool) or isinstance(b, bool):
            raise _GvStop("binop")
        a, b = int(a), int(b)
        r = {"|": lambda: a | b, "^": lambda: a ^ b, "&": lambda: a & b, "<<": lambda: a << (b & 63),
             ">>": lambda: a >> (b & 63), "ushr": lambda: (a & 0xFFFFFFFF) >> (b & 31), "+": lambda: a + b,
             "-": lambda: a - b, "*": lambda: a * b, "%": lambda: a % b if b else _gv_fail()}[op]()
        if abs(r) > 1 << 64:
            raise _GvStop("big")
        return r

    def unary(self, i):
        s = self.s
        self.tick()
        if s.startswith("-", i) and not s.startswith("--", i):
            v, i = self.unary(self.ws(i + 1))
            if not isinstance(v, int):
                raise _GvStop("neg")
            return -v, i
        m = re.compile(r"\(\s*(char|byte|int|short|long|String|Character|Integer)\s*\)\s*").match(s, i)
        if m:
            v, i = self.unary(m.end())
            return self.cast(v, m.group(1)), i
        v, i = self.primary(i)
        return self.postfix(v, i)

    def cast(self, v, t):
        if t in ("char", "Character"):
            if isinstance(v, str) and len(v) == 1:
                return _GvCh(ord(v))
            if isinstance(v, int):
                return _GvCh(int(v) & 0xFFFF)
        if t in ("byte", "Byte") and isinstance(v, int):
            return int(v) & 0xFF
        if t in ("int", "Integer", "short", "long", "Long") and isinstance(v, int):
            return int(v)
        if t in ("int", "Integer") and isinstance(v, str) and not self.kt:
            return int(v) if v.strip().lstrip("-").isdigit() else _gv_fail()
        if t in ("String", "CharSequence", "Object"):
            return _gv_str(v) if not isinstance(v, list) else v if t == "Object" else _gv_text(v)
        if t.endswith("[]") or t in ("List", "ArrayList"):
            items = list(v) if isinstance(v, str) else v
            if not isinstance(items, list):
                raise _GvStop("cast")
            if t.startswith(("char", "Character")):
                return [self.cast(x, "char") for x in items]
            if t.startswith(("byte", "Byte")):
                return [self.cast(x, "byte") for x in items]
            if t.startswith(("int", "Integer")):
                return [int(x) if isinstance(x, int) else _gv_fail() for x in items]
            return list(items)
        raise _GvStop("cast")

    def args(self, i, close=")"):
        """(positional, named, end) of an argument list starting after `(`."""
        pos, named = [], {}
        i = self.ws(i)
        if self.s.startswith(close, i):
            return pos, named, i + 1
        while True:
            m = re.compile(r"([A-Za-z_]\w*)\s*[:=](?![:=])\s*").match(self.s, i)
            if m and m.group(1) not in self.env and m.group(1) != "it":
                v, i = self.expr(self.ws(m.end()))
                named[m.group(1)] = v
            else:
                v, i = self.expr(i)
                pos.append(v)
            i = self.ws(i)
            if self.s.startswith(",", i):
                i = self.ws(i + 1)
                if self.s.startswith(close, i):
                    return pos, named, i + 1
                continue
            if self.s.startswith(close, i):
                return pos, named, i + 1
            raise _GvStop("args")

    def closure(self, i):
        """_GvFn of the `{ [a, b ->] body }` at s[i] and its end."""
        end = self.skip_braces(i)
        m = re.compile(r"\{\s*(?:([A-Za-z_]\w*(?:\s*:\s*\w+)?(?:\s*,\s*[A-Za-z_]\w*(?:\s*:\s*\w+)?)*)?\s*->)?").match(self.s, i)
        params = [p.split(":")[0].strip() for p in (m.group(1) or "").split(",") if p.strip()] if "->" in m.group(0) else ["it"]
        return _GvFn(params, m.end(), end - 1), end

    def call(self, fn, *vals):
        saved = dict(self.env)
        try:
            for p, v in zip(fn.params, vals):
                self.env[p] = v
            return self.block(fn.a, fn.b)
        finally:
            self.env.clear()
            self.env.update(saved)

    def block(self, a, b):
        """value of the last expression statement in s[a:b]."""
        v, i = None, self.ws(a)
        while i < b:
            self.tick()
            m = re.compile(r"(?:val|var|def)\s+([A-Za-z_]\w*)\s*(?::\s*[\w.<>?]+\s*)?=(?!=)\s*").match(self.s, i)
            if m:
                v, i = self.expr(self.ws(m.end()))
                self.env[m.group(1)] = v
            else:
                v, i = self.expr(i)
            k = self.ws(i, nl=False)
            if k < b and self.s[k] not in ";\n":
                raise _GvStop("stmt")
            i = k
            while i < b and self.s[i] in ";\n \t\r":
                i = self.ws(i + 1)
        if i > b:
            raise _GvStop("block")
        return v

    def primary(self, i):
        s = self.s
