        if s.startswith("new", i) and re.compile(r"new\s+").match(s, i):
            m = re.compile(r"new\s+((?:java\.lang\.)?String|(?:java\.lang\.)?StringBuilder|StringBuffer)\s*\(").match(s, i)
            if not m:
                raise _GvStop("new")
