        k = self.ws(j, nl=False)
        if name in ("StandardCharsets.UTF_8", "Charsets.UTF_8"):
            return "UTF-8", j
        if name in ("StandardCharsets.US_ASCII", "Charsets.US_ASCII"):
            return "US-ASCII", j
        if name in ("StandardCharsets.ISO_8859_1", "Charsets.ISO_8859_1"):
            return "ISO-8859-1", j
